window.__BOOK__['p05'].push([{"id":"b87-1","bab":"الجزء 9","sec":"بسم الله الرحمن الرحيم ذكر أخبار كثير ونسبه","page":"ج9 ص5","text":"هو فيما أخبرنا به محمد بن العباس اليزيدي عن محمد بن حبيب عن ابن الأعرابي أبو صخر كثير بن عبد الرحمن بن الأسود بن عامر بن عويمر بن مخلد بن سعيد بن سبيع بن جعثمة بن سعد بن مليح بن عمرو وهو خزاعة بن ربيعة وهو يحيى بن حارثة بن عمرو وهو مزيقيا بن عامر وهو ماء السماء بن حارثة الغطريف بن امرئ القيس البطريق بن ثعلبة البهلول ابن مازن بن الأزد وهو درء\nوقيل دراء ممدودا ابن الغوث بن نبت بن مالك ابن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان وأخبرنا أبو عبد الرحمن أحمد بن محمد بن إسحاق الحرمي قال حدثنا الزبير بن بكار قال حدثنا أبو صخر بن أبي الزعراء الخزاعي عن أمه ليلى\nبنت كثير قالت هو كثير بن عبد الرحمن بن الأسود بن عامر بن مخلد بن سبيع بن سعد بن مليح بن عمرو بن ربيعة بن حارثة بن عمرو بن عامر وأمه جمعة بنت الأشيم بن خالد بن عبيد ابن مبشر بن رياح بن سيالة بن عامر بن جعثمة بن كعب بن عمرو بن ربيعة بن حارثة بن عمرو بن عامر وكانت كنية الأشيم جده أبي أمه أبا جمعة ولذلك\nقيل له ابن أبي جمعة وكان له ابن يقال له ثواب من أشعر أهل زمانه مات سنة إحدى وأربعين ومائة ولا ولد له ومات كثير سنة خمس ومائة في ولاية يزيد بن عبد الملك وليس له اليوم ولد إلا من بنته ليلى ولليلى بنته ابن يكنى أبا سلمة شاعر وهو الذي يقول\n(وكان عزيزا أن تبيتي وبيننا ... حجاب فقد أمسيت مني على شهر)\n(ففي القرب تعذيب وفي النأي حسرة ... فيا ويح نفسي كيف أصنع بالدهر)\nي هذين البيتين غناء لمقاسة ولحنه من الثقيل الأول بالخنصر عن حبش","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":0,"spl":"بسم الله الرحمن الرحيم ذكر أخبار كثير ونسبه","tags":["الجواري والنساء"],"song":1,"loc":1597},
{"id":"b87-2","bab":"الجزء 9","sec":"طبقته ونحلته","page":"ج9 ص6","text":"ويكنى كثير أبا صخر وهو من فحول شعراء الإسلام وجعله ابن سلام\nفي الطبقة الأولى منهم وقرن به جريرا والفرزدق والأخطل والراعي وكان غاليا في التشيع يذهب مذهب الكيسانية ويقول بالرجعة والتناسخ وكان محمقا مشهورا بذلك وكان آل مروان يعلمون بمذهبه فلا يغيرهم ذلك لجلالته في أعينهم ولطف محله في أنفسهم وعندهم وكان من أتيه الناس وأذهبهم بنفسه على كل أحد\nأخبرني به أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني هارون بن عبد الله الزهري قال حدثني سليمان بن فليح قال سمعت محمد بن عبد العزيز يعني ابن عمر بن عبد الرحمن بن عوف يقول ما قصد القصيد ولا نعت الملوك مثل كثير أخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال كتب إلي إسحاق بن إبراهيم الموصلي حدثني إبراهيم بن سعد قال إني لأروي\nلكثير ثلاثين قصيدة لورقي بها مجنون لأفاق أخبرني الحرمي قال حدثني الزبير قال حدثني بعض أصحاب الحديث قال كنا نأتي إبراهيم بن سعد وهو خبيث النفس فنسأله عن شعر كثير فتطيب نفسه ويحدثنا\nأخبرني الحرمي قال حدثنا الزبير قال حدثنا عمر بن أبي بكر المؤملي عن عبد الله بن أبي عبيدة قال من لم يجمع من شعر كثير ثلاثين لامية فلم يجمع شعره\nقال الزبير قال المؤملي وكان ابن أبي عبيدة يملي شعر كثير بثلاثين دينارا قال وسئل عمي مصعب من أشعر الناس فقال كثير بن أبي جمعة وقال هو أشعر من جرير والفرزدق والراعي وعامتهم يعني الشعراء لم يدرك أحد في مديح الملوك ما أدرك كثير\nأخبرني أبو خليفة الفضل بن الحباب إجازة قال حدثنا محمد بن سلام الجمحي قال كان كثير شاعر أهل الحجاز وهو شاعر فحل ولكنه منقوص حظه بالعراق\nأخبرني أبو خليفة قال أخبرنا ابن سلام قال سمعت يونس النحوي يقول كثير أشعر أهل الإسلام قال ابن سلام وسمعت ابن أبي حفصة يعجبه مذهبه في المديح جدا ويقول كان يستقصي المديح وكان فيه مع جودة شعره خطل وعجب\nأخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني محمد بن إسماعيل الجعفري قال أخبرني إبراهيم بن إبراهيم بن حسين بن زيد قال سمعت المسور بن عبد الملك يقول ما ضر من يروي شعر كثير وجميل ألا تكون عنده مغنيتان مطربتان\nأخبرني حبيب بن نصر المهلبي وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال حدثني إسحاق بن إبراهيم عن المدائني عن الوقاصي قال رأيت كثيرا يطوف بالبيت فمن حدثك أنه يزيد على ثلاثة أشبار فكذبه وكان إذا دخل على عبد العزيز بن مروان يقول طأطئ رأسك لا يصبه السقف\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني إسحاق ابن إبراهيم عن المدائني وعن ابن حبيب عن أبيه عن جده عن جد أبيه عبد العزيز وأمه جمعة بنت كثير قال قال جرير لكثير أي رجل أنت لولا دمامتك فقال كثير\n(إن أك قصدا في الرجال فإنني ... إذا حل أمر ساحتي لطويل)","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":1,"spl":"طبقته ونحلته","tags":["الحب والغزل","المديح"],"loc":1598},
{"id":"b87-3","bab":"الجزء 9","sec":"كثير والحزين الديلي","page":"ج9 ص10","text":"أخبرني حبيب بن نصر وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر ابن شبة قال حدثني إسحاق بن إبراهيم عن المدائني عن الوقاصي قال وأخبرنا الحرمي بن أبي العلاء\nقال حدثنا الزبير بن بكار قال حدثني محمد بن يحيى عن بعض أصحابهم الديليين قال التقى كثير والحزين الديلي بالمدينة في دار ابن أزهر في سوق الغنم فضمهما المجلس فقال كثير للحزين ما أنت شاعر يا حزين إنما توصل الشيء إلى الشيء فقال له الحزين أتأذن لي أن أهجوك قال نعم وكان كثير قال قبل ذلك وهو ينتسب إلى بني الصلت بن النضر بن كنانة\n(أليس أبي بالنضر أوليس إخوتي ... بكل هجان من بني الصلت أزهرا)\n(فإن لم تكونوا من بني الصلت فاتركوا ... أراكا بأذيال الخمائل أخضرا)\nال فلما أذن كثير للحزين أن يهجوه قال الحزين\n(لقد علقت زب الذباب كثيرا ... أساود لا يطنينه وأراقم)\n(قصير القميص فاحش عند بيته ... يعض القراد باسته وهو قائم)\n(وما أنتم منا ولكنكم لنا ... عبيد العصا ما ابتل في البحر عائم)\n(وقد علم الأقوام أن بني استها ... خزاعة أذناب وأنا القوادم)\n(ووالله لولا الله ثم ضرابنا ... بأسيافنا دارت عليها المقاسم)\n(ولولا بنو بكر لذلت وأهلكت ... بطعن وأفنتها السيوف الصوارم)\nال فقام كثير فحمل عليه فلكزه وكان الحزين طويلا أيدا فقال له الحزين أنت عن هذا أعجز واحتمله فكان في يده مثل الكرة فضرب به الأرض فخلصه منه الأزهريون فبلغ ذلك أبا الطفيل عامر بن واثلة وهو\nبالكوفة فأقسم لئن ملأ عينيه من كثير ليضربنه بالسيف أو ليطعننه بالرمح وكان خندف الأسدي صديقا لأبي الطفيل فطلب إلى أبي الطفيل في كثير واستوهبه إياه فوهبه له والتقيا بمكة وجلسا جميعا مع عمر بن علي بن أبي طالب فقال أما والله لولا ما أعطيت خندفا من العهد لوفيت لك فذلك قول كثير في قصيدته التي يرثي فيها خندفا\n(ينال رجالا نفعه وهو منهم ... بعيد كعيوق الثريا المحلق)\nخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال قال كثير في أي شعر أعطى هؤلاء الأحوص عشرة آلاف دينار قالوا في قوله فيهم\n(وما كان مالي طارفا من تجارة ... وما كان ميراثا من المال متلدا)\n(ولكن عطايا من إمام مبارك ... ملا الأرض معروفا وجودا وسوددا)\nقال كثير إنه لضرع قبحه الله ألا قال كما قلت\n(دع عنك سلمى إذ فات مطلبها ... واذكر خليليك من بني الحكم)\n(ما أعطياني ولا سألتهما ... إلا وإني لحاجزي كرمي)\n(إني متى لا يكن نوالهما ... عندي بما قد فعلت أحتشم)\n(مبدي الرضا عنهما ومنصرف ... عن بعض ما لو فعلت لم ألم)\n(لا أنزر النائل الخليل إذا ... ما اعتل نزر الظؤور لم ترم)\nروضه من المنسرح غنى في هذا الشعر يونس ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق وغنى فيه الغريض ثاني ثقيل بالبنصر على مذهب إسحاق من رواية عمرو بن بانة وفيه لحن من الثقيل الأول ينسب إلى معبد وليس بصحيح له قال الزبير بن بكار في تفسير قوله لا أنزر النائل الخليل يقول لا ألح عليه بالمسألة يقال نزرته أنزره إذا ألححت عليه والظؤور المتعطفة على غير أولادها\nأخبرني الحرمي قال حدثني الزبير قال حدثنا المؤملي عن أبي عبيدة وأخبرنا أحمد بن عبد العزيز وحبيب بن نصر قالا حدثنا عبد الله بن محمد بن حكيم عن خالد بن سعيد بن عمرو بن سعيد عن أبيه\nقال دخل كثير على عبد الملك بن مروان فقال يا أمير المؤمنين إن أرضا لك يقال لها غرب ربما أتيتها وخرجت إليها بولدي وعيالي فأصبنا من رطبها وتمرها بشراء مرة وطعمة مرة فإن رأى أمير المؤمنين أن يعمرنيها فعل فقال له عبد الملك ذلك لك فندمه الناس وقالوا له أنت شاعر الخليفة ولك عنده منزلة فهلا سألت الأرض قطيعة فأتى الوليد فقال إن لي إلى أمير المؤمنين حاجة فأجلسني قريبا من البرذون فلما استوى عليه عبد الملك قال له إيه وعلم أن له إليه حاجة فقال كثير\n(جزتك الجوازي عن صديقك نضرة ... وأدناك ربي في الرفيق المقرب)\n(فإنك لا يعطى عليك ظلامة ... عدو ولا تنأى عن المتقرب)\n(وإنك ما تمنع فإنك مانع ... بحق وما أعطيت لم تتعقب)","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":2,"spl":"كثير والحزين الديلي","tags":["الهجاء"],"song":1,"loc":1599},
{"id":"b87-4","bab":"الجزء 9","sec":"كثير والحزين الديلي","page":"ج9 ص10","text":"فقال له أترغب غربا قال نعم يا أمير المؤمنين قال اكتبوها له ففعلوا أخبرني الحرمي قال حدثني الزبير قال حدثنا عمر بن أبي بكر المؤملي قال حدثني عبد الله بن أبي عبيدة قال كان الحزين الكناني قد ضرب علىكل رجل من قريش درهمين في كل\nشهر منهم ابن أبي عتيق فجاءه لأخذ درهميه على حمار له أعجف قال وكثير مع ابن أبي عتيق فدعا ابن أبي عتيق للحزين بدرهمين فقال الحزين لابن أبي عتيق من هذا معك\nقال هذا أبو صخر كثير بن ابي جمعة قال وكان قصيرا دميما فقال له الحزين أتأذن لي أن أهجوه ببيت من شعر قال لا لعمري لا آذن لك أن تهجو جليسي ولكني أشتري عرضه منك بدرهمين آخرين ودعا له بهما فأخذهما ثم\nقال لا بد من هجائه ببيت قال أو أشتري ذلك منك بدرهمين آخرين ودعا له بهما فأخذهما ثم قال ما أنا بتاركه حتى أهجوه قال أو أشتري ذلك منك بدرهمين فقال له كثير ايذن له ما عسى أن يقول في بيت فأذن له ابن أبي عتيق فقال\n(قصير القميص فاحش عند بيته ... يعض القراد باسته وهو قائم)\nال فوثب كثير إليه فلكزه فسقط هو والحمار وخلص ابن أبي عتيق بينهما وقال لكثير قبحك الله أتأذن له وتسفه عليه فقال كثير أو أنا ظننته أن يبلغ بي هذا كله في بيت واحد","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":3,"spl":"كثير والحزين الديلي","tags":["الهجاء","الرواية والكتابة"],"loc":1600},
{"id":"b87-5","bab":"الجزء 9","sec":"كثير يدعي أنه قرشي","page":"ج9 ص15","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة ولم يتجاوزه وأخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثنا عبد الرحمن ابن الخضر الخزاعي عن ولد جمعة بنت كثير أنه وجد في كتب أبيه التي فيها شعر كثير أن عبد الملك بن مروان قال له ويحك الحق بقومك من خزاعة فأخبر أنه من كنانة قريش وأنشد كثير قوله\n(أليس أبي بالصلت أم ليس إخوتي ... بكل هجان من بني النضر أزهرا)\n(فإن لم تكونوا من بني النضر فاتركوا ... أراكا بأذناب القوابل أخضرا)\n(أبيت التي قد سمتني ونكرتها ... ولو سمتها قبلي قبيصة أنكرا)\n(لبسنا ثياب العصب فاختلط السدى ... بنا وبهم والحضرمي المخصرا)\nقال له عبد الملك لابد أن تنشد هذا الشعر على مبنري الكوفة والبصرة وحمله وكتب إلى العراق في أمره قال عمر بن شبة في خبره خاصة فأجابته خزاعة الحجاز إلى ذلك وقال فيه الأحوص ويقال بل قاله سراقة البارقي\n(لعمري لقدجاء العراق كثير ... بأحدوثة من وحيه المتكذب)\n(أيزعم أني من كنانة أولي ... وما لي من أم هناك ولا أب)\n(فإن كنت حرا أو تخاف معرة ... فخذ ما أخذت من أميرك واذهب)\nقال كثير يجيبه وفي خبر الزبير قال هذا لأبي علقمة الخزاعي\n(أيا خبث أكرم كنانة إنهم ... مواليك إن أمر سما بك معلق)\nفي رواية الزبير أبا علقم\n(بنو النضر ترمي من ورائك بالحصى ... أولو حسب فيهم وفاء ومصدق)\n(يفيدونك المال الكثير ولم تجد ... لملكهم شبها لو انك تصدق)\n(إذا ركبوا ثارت عليك عجاجة ... وفي الأرض من وقع الأسنة أولق)\nأجابه الأحوص بقوله\n(دع القوم ما حلوا ببطن قراضم ... وحيث تفشى بيضه المتفلق)\n(فإنك لو قاربت أو قلت شبهة ... لذي الحق فيها والمخاصم معلق)\n(عذرناك أو قلنا صدقت وإنما ... يصدق بالأقوال من كان يصدق)\n(ستأبى بنو عمرو عليك وينتمي ... لهم حسب في جذم غسان معرق)\n(فإنك لا عمرا أباك حفظته ... ولا النضر إن ضيعت شيخك تلحق)\n(ولم تدرك القوم الذين طلبتهم ... فكنت كما كان السقاء المعلق)\n(بجذمة ساق ليس منه لحاؤها ... ولم يك عنها قلبه يتعلق)\n(فأصبحت كالمهريق فضلة مائه ... لبادي سراب بالملا يترقرق)\nال فخرج كثير فأتى الكوفة فرمي به إلى مسجد بارق فقالوا له أنت من أهل الحجاز قال نعم قالوا فأخبرنا عن رجل شاعر ولد زنا يدعى كثيرا قال سبحان الله أما تسمعون أيها المشايخ ما يقول الفتيان قالوا هو ما قاله لنفسه فانسل منهم وجاء إلى والي الكوفة حسان بن كيسان فطيره على البريد\nوقال عمر بن شبة في خبره إن سراقة البارقي هو المخاطب له بهذه الشتيمة وإنه عرفه وقال له إن قلت هذا على المنبر قتلتك قحطان وأنا أولهم فانصرف إلى منزله ولم يعد إلى عبد الملك وكان سراقة هذا شاعرا ظريفا فأخبرني عمي\nحدثني الكراني عن النضر بن عمر عن الهيثم بن عدي عن الأعمش عن إبراهيم قال كان سراقة البارقي من ظرفاء أهل العراق فأسره المختار يوم جبانة السبيع وكانت للمختار فيها وقعة منكرة فجاء به الذي أسره إلى\nالمختار فقال له إني أسرت هذا فقال له سراقة كذب ما هو الذي أسرني إنما أسرني غلام أسود على برذون أبلق عليه ثياب خضر ما أراه في عسكرك الآن وسلمني إليه فقال المختار أما إن الرجل قد عاين الملائكة خلوا سبيله فخلوه فهرب فأنشأ يقول\n(ألا أبلغ أبا إسحاق أني ... رأيت البلق دهما مصمتات)\n(أري عيني ما لم تبصراه ... كلانا عالم بالترهات)\n(كفرت بدينكم وجعلت نذرا ... علي قتالكم حتى الممات)","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":4,"spl":"كثير يدعي أنه قرشي","tags":["الهجاء"],"loc":1601},
{"id":"b87-6","bab":"الجزء 9","sec":"تشيع كثير وشعره في ابن الحنفية","page":"ج9 ص19","text":"أخبرنا الحرمي قال أخبرنا الزبير قال أخبرنا عمرو ومحمد بن الضحاك قالا كان كثير يتشيع تشيعا قبيحا يزعم أن محمد بن الحنفية لم يمت قال وكان ذلك رأي السيد وقد قال فيه يعني السيد شعرا كثيرا منه\n(ألا قل للوصي فدتك نفسي ... أطلت بذلك الجبل المقاما)\n(أضر بمعشر والوك منا ... وسموك الخليفة والإماما)\n(وعادوا فيك أهل الأرض طرا ... مقامك عنهم ستين عاما)\n(وما ذاق ابن خولة طعم موت ... ولا وارت له أرض عظاما)\n(لقد أوفى بمورق شعب رضوى ... تراجعه الملائكة الكلاما)\n(وإن له به لمقيل صدق ... وأندية تحدثه كراما)\n(هدانا الله إذ جرتم لأمر ... به ولديه نلتمس التماما)\n(تمام مودة المهدي حتى ... تروا راياتنا تترى نظاما)\nقال كثير في ذلك\n(ألا إن الأئمة من قريش ... ولاة الحق أربعة سواء)\n(علي والثلاثة من بنيه ... هم الأسباط ليس بهم خفاء)\n(فسبط سبط إيمان وبر ... وسبط غيبته كربلاء)\n(وسبط لا تراه العين حتى ... يقود الخيل يقدمها اللواء)\n(تغيب لا يرى عنهم زمانا ... برضوى عنده عسل وماء)\nخبرني الحسن بن علي قال حدثنا الحارث بن محمد عن المدائني عن أبي بكر الهذلي قال\nكان عبد الله بن الزبير قد أغري ببني هاشم يتبعهم بكل مكروه ويغري بهم ويخطب بهم على المنابر ويصرح ويعرض بذكرهم فربما عارضه ابن عباس وغيره منهم ثم بدا له فيهم فحبس ابن الحنفية في سجن عارم ثم جمعه وسائر من كان بحضرته من بني هاشم فجعلهم في محبس وملأه حطبا وأضرم فيه النار وقد كان بلغه أن أبا عبد الله الجدلي وسائر شيعة ابن الحنفية قد وافوا لنصرته ومحاربة ابن الزبير فكان ذلك سبب إيقاعه به وبلغ أبا عبد الله الخبر فوافى ساعة أضرمت النار عليهم فأطفأها واستنقذهم وأخرج ابن الحنفية عن جوار ابن الزبير منذ يومئذ فأنشدنا محمد بن العباس اليزيدي قال أنشدنا محمد بن حبيب لكثير يذكر ابن الحنفية وقد حبسه ابن الزبير في سجن يقال له سجن عارم\n(من ير هذا الشيخ بالخيف من منى ... من الناس يعلم أنه غير ظالم)\n(سمي النبي المصطفى وابن عمه ... وفكاك أغلال ونفاع غارم)\n(أبى فهو لا يشري هدى بضلالة ... ولا يتقي في الله لومة لائم)\n(ونحن بحمد الله نتلو كتابه ... حلولا بهذا الخيف خيف المحارم)\n(بحيث الحمام آمن الروع ساكن ... وحيث العدو كالصديق المسالم)\n(فما فرح الدنيا بباق لأهله ... ولا شدة البلوى بضربة لازم)\n(تخبر من لاقيت أنك عائذ ... بل العائذ المظلوم في سجن عارم)\nدثني أحمد بن محمد بن سعيد الهمداني قال حدثنا يحيى بن الحسن العلوي قال حدثنا الزبير بن بكار وأخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن إسماعيل الجعفري عن سعيد عن عقبة الجهني عن أبيه قال سمعت كثيرا ينشد علي بن عبد الله بن جعفر قوله في محمد بن الحنفية\n(أقر الله عيني إذ دعاني ... أمين الله يلطف في السؤال)\n(وأثنى في هواي علي خيرا ... وساءل عن بني وكيف حالي)\n(وكيف ذكرت حال أبي خبيب ... وزلة فعله عند السؤال)\n(هو المهدي خبرناه كعب ... أخو الأحبار في الحقب الخوالي)\nقال له علي بن عبد الله يا أبا صخر ما يثنى عليك في هواك خيرا إلا من كان على مثل مذهبك قال أجل بأبي أنت وأمي قال وكان كثير كيسانيا يرى الرجعة قال الزبير أبو خبيب عبد الله بن الزبير كناه بابنه\nخبيب وهو أكبر ولده وكان كثير سيئ الرأي فيه قال الزبير كناه بابنه خبيب وهو أكبر ولده وكان كثير سيئ الرأي فيه قال الزبير فأخبرني عمي قال لما قال كثير\n(هو المهدي خبرناه كعب ... أخو الأحبار في الحقب الخوالي)\nقيل له ألقيت كعبا قال لا قيل فلم قلت خبرناه كعب قال بالتوهم قال وكان كثير شيعيا غاليا يزعم أن الأرواح تتناسخ ويحتج بقول الله تعالى ( في أي صورة ما شاء ركبك\nويقول ألا ترى أنه حوله من صورة في صورة قال فحدثني عمر بن أبي بكر المؤملي عن عبد الله بن أبي عبيدة قال خندف الأسدي الذي أدخل كثيرا في الخشبية أخبرنا الحرمي\nقال حدثنا الزبير قال حدثني إبراهيم بن المنذر الحزامي عن محمد بن معن الغفاري قال كنا بالسيالة في مشيخة نتحدث إذا بكثير قد طلع علينا متكئا على عصا فقال كنا ببيداء بأشراف السيالة وبهذه الناحية فما بقي موضع ببيداء إلا وقد جئته فإذا هو على حاله ما تغير وما تغيرت الجبال ولا الموضع الذي كنا نطوف فيه وهذا يكون حتى نرجع إليه وكان يؤمن بالرجعة","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":5,"spl":"تشيع كثير وشعره في ابن الحنفية","tags":["المديح"],"loc":1602},
{"id":"b87-7","bab":"الجزء 9","sec":"تشيع كثير وشعره في ابن الحنفية","page":"ج9 ص19","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني يحيى بن محمد قال دخل عبد الله بن حسن على كثير يعوده في مرضه الذي مات فيه فقال له كثير أبشر فكأنك بي بعد أربعين ليلة قد طلعت عليك على فرس عتيق فقال له عبد الله بن حسن ما لك عليك لعنة الله فوالله لئن مت لا أشهدك ولا أعودك ولا أكلمك أبدا\nأخبرني الحرمي قال حدثا الزبير قال حدثني يحيى بن محمد بن عبد الملك بن عبد العزيز أحسبه عن ابن الماجشون قال وكان أبو هاشم عبد الله بن محمد بن علي قد وضع الأرصاد على كثير فلا يزال يؤتى بالخبر من خبره فيقول له إذا لقيه كنت في كذا وكنت في كذا إلى أن جرى بين كثير وبين رجل كلام فأتي به أبو هاشم فأقبل به على أدراجه فقال له أبو هاشم كنت الساعة مع فلان فقلت له كذا وكذا\nوقال لك كذا وكذا فقال له كثير أشهد أنك رسول الله أخبرنا محمد بن جعفر النحوي قال حدثنا محمد وأخبرنا الحرمي قال حدثنا الزبير قال حدثنا محمد بن إسماعيل عن موسى بن عبد الله فيما أحسب\nقال نظر كثير إلى بني حسن بن حسن وهم صغار فقال بأبي أنتم هؤلاء الأنبياء الصغار وكان يرى الرجعة وروى علي بن بشر بن سعيد الرازي عن محمد بن حميد عن أبي زهير عبد الرحمن بن مغراء الدوسي عن محمد ابن عمارة قال مر كثير بمعاوية بن عبد الله بن جعفر وهو في المكتب فأكب عليه\nيقبله وقال أنت من الأنبياء الصغار ورب الكعبة أخبرنا أحمد بن عبيد الله بن عمار قال حدثنا محمد بن إسماعيل قال حدثنا قعنب بن المحرز قال\nحدثني إبراهيم بن داجة قال كان كثير شيعيا وكان يأتي ولد حسن بن حسن إذا أخذ عطاءه فيهب لهم الدراهم ويقول وابأبي الأنبياء الصغار وكان يؤمن بالرجعة فيقول له محمد بن عبد الله بن عمرو بن عثمان وهو أخوهم لأمهم يا عم هب لي فيقول لا لست من الشجرة أخبرنا محمد بن العباس اليزيدي\nقال حدثنا أحمد بن يحيى ثعلب قال حدثني الزبير بن بكار قال حدثني عثمان بن عبد الرحمن عن إبراهيم بن يعقوب بن أبي عبيد الله قال قال عمر بن عبد العزيز إني لأعرف صلاح بني هاشم من فسادهم بحب كثير من أحبه منهم فهو فاسد ومن أبغضه فهو صالح لأنه كان خشبيا يقول بالرجعة أخبرنا الحرمي\nقال حدثنا الزبير قال حدثني عبد العزيز بن محمد الدراوردي عن أبي لهيعة عن رجاء بن حيوة قال سمعت عمر بن عبد العزيز يقول إن مما أعتبر به صلاح بني هاشم وفاسدهم حب كثير ثم\nذكر مثله أخبرنا الحرمي قال حدثنا الزبير قال حدثنا علي بن صالح عن ابن دأب قال كان كثير يدخل على عمة له برزة فتكرمه وتطرح له وسادة يجلس عليها فقال لها يوما لا والله ما تعرفينني ولا تكرمينني حق كرامتي قالت بلى والله إني لأعرفك قال فمن أنا قالت ابن فلان وابن فلانة وجعلت تمدح أباه وأمه فقال قد عرفت أنك لا تعرفينني قالت فمن أنت قال أنا يونس بن متى","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":6,"spl":"تشيع كثير وشعره في ابن الحنفية","tags":["المديح","اللهو والمزاح"],"loc":1603},
{"id":"b87-8","bab":"الجزء 9","sec":"كان كثير عاقا لأبيه","page":"ج9 ص25","text":"أخبرنا الحرمي قال حدثنا الزبير قال حدثني أبي قال كان كثير عاقا لأبيه وكان أبوه قد أصابته قرحة في إصبع من أصابع يده فقال له كثير أتدري لم أصابتك هذه القرحة في إصبعك قال لا أدري قال مما ترفعها إلى الله في يمين كاذبة أخبرنا الحرمي قال حدثنا الزبير قال حدثنا إبراهيم بن المنذر عن محمد ابن معن الغفاري عن أبيه وغيره قال حدثني رجل من مزينة قال\nإني لأعرف صلاح بني هاشم من وفسادهم بحب كثير من أحبه منهم فهو فاسد ومن أبغضه فهو صالح لأنه كان خشبيا يقول بالرجعة أخبرنا الحرمي قال\nحدثنا الزبير قال حدثني عبد العزيز بن محمد الدراوردي عن أبي لهيعة عن رجاء بن حيوة قال سمعت عمر بن عبد العزيز يقول إن مما أعتبر به صلاح بني هاشم وفاسدهم حب كثير ثم\nذكر مثله أخبرنا الحرمي قال حدثنا الزبير قال حدثنا علي بن صالح عن ابن دأب قال كان كثير يدخل على عمة له برزة فتكرمه وتطرح له وسادة يجلس عليها فقال لها يوما لا والله ما تعرفينني ولا تكرمينني حق كرامتي قالت بلى والله إني لأعرفك\nقال فمن أنا قالت ابن فلان وابن فلانة وجعلت تمدح أباه وأمه فقال قد عرفت أنك لا تعرفينني قالت فمن أنت قال أنا يونس بن متى كان كثير عاقا لأبيه أخبرنا الحرمي\nقال حدثنا الزبير قال حدثني أبي قال كان كثير عاقا لأبيه وكان أبوه قد أصابته قرحة في إصبع من أصابع يده فقال له كثير أتدري لم أصابتك هذه القرحة في إصبعك قال لا أدري قال مما ترفعها إلى الله في يمين كاذبة أخبرنا الحرمي قال حدثنا الزبير قال حدثنا إبراهيم بن المنذر عن محمد ابن معن الغفاري عن أبيه وغيره قال حدثني رجل من مزينة قال\nضفت كثيرا ليلة وبت عنده ثم تحدثنا ونمنا فلما طلع الفجر تضور ثم قمت فتوضأت وصليت وكثير راقد في لحافه فلما طلع قرن الشمس تضور ثم قال يا جارية اسجري لي ماء\nقال قلت تبا لك سائر اليوم أو هذه الساعة هذا وركبت راحلتي وتركته قال الزبير أسخني لي ماء أخبرنا الحرمي قال حدثنا الزبير قال حدثني محمد بن إسماعيل عن عبد العزيز بن عمران عن محمد بن عبد العزيز عن ابن شهاب عن طلحة بن عبيد الله\nقال ما رأيت قط أحمق من كثير دخلت عليه يوما في نفر من قريش وكنا كثيرا ما نتهزأ به وكان يتشيع تشيعا قبيحا فقلت له كيف تجدك يا أبا صخر وهو مريض فقال أجدني ذاهبا فقلت كلا فقال هل سمعتم الناس يقولون شيئا فقلت نعم يتحدثون أنك الدجال\nقال أما لئن قلت ذاك إني لأجد في عيني ضعفا منذ أيام أخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن إسماعيل عن عبد العزيز بن عمران أن ناسا من أهل المدينة كانوا يلعبون بكثير فيقولون وهو يسمع إن كثيرا لا يلتفت من تيهه فكان الرجل يأتيه من ورائه فيأخذ رداءه فلا يلتفت من الكبر ويمضي في قميص أخبرنا إبراهيم بن محمد بن أيوب قال حدثنا عبد الله بن مسلم بن قتيبة قال بلغني أن كثيرا دخل على عبد الملك بن مروان فسأله عن شيء\nفأخبره به فقال وحق علي بن أبي طالب إنه كما ذكرت قال كثير يا أمير المؤمنين لو سألتني بحقك لصدقتك قال لا أسألك إلا بحق أبي تراب فحلف له به فرضي أخبرنا الفضل بن الحباب أبو خليفة\nقال حدثنا محمد بن سلام قال أخبرني عثمان بن عبد الرحمن وأخبرنا محمد بن جعفر النحوي قال حدثنا محمد بن يزيد المبرد قال وأخبرنا أحمد بن عبد العزيز الجوهري وحبيب ابن نصر المهلبي قالا\nحدثنا عمر بن شبة وأخبرنا الحرمي قال حدثنا الزبير قال حدثنا المؤملي عن ابن أبي عبيدة قالوا جميعا لما أراد عبد الملك الخروج إلى مصعب لاذت به عاتكة بنت يزيد ابن معاوية وهي أم ابنه يزيد وقالت يا أمير المؤمنين لا تخرج السنة لحرب مصعب فإن آل الزبير ذكروا خروجك وابعث إليه الجيوش وبكت وبكى جواريها معها وجلس وقال قاتل الله ابن أبي جمعة فأين قوله\n\n(إذا ما أراد الغزو لم تثن همه ... حصان عليها عقد در يزينها)\n(نهته فلما لم تر النهي عاقه ... بكت فبكى مما شجاها قطينها)\nناه ابن سريج ثاني ثقيل بالخنصر في مجرى البنصر عن إسحاق والله لكأنه يراني ويراك يا عاتكة ثم خرج قال محمد بن جعفر النحوي في خبره ووافقه عليه عمر بن شبة فلما خرج عبد الملك نظر إلى كثير في ناحية عسكره يسير مطرقا فدعا به","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":7,"spl":"كان كثير عاقا لأبيه","tags":["الحب والغزل","المديح"],"song":1,"loc":1604},
{"id":"b87-9","bab":"الجزء 9","sec":"كان كثير عاقا لأبيه","page":"ج9 ص25","text":"وقال لأعلم ما أسكتك وألقى عليك بثك فإن أخبرتك عنه أتصدقني قال نعم قال قل وحق أبي تراب لتصدقني قال والله لأصدقنك قال لا أو تحلف به فحلف به فقال تقول رجلان من قريش يلقى أحدهما صاحبه فيحاربه القاتل والمقتول في النار فما معنى سيري مع أحدهما إلى الآخر ولا آمن سهما عائرا لعله أن يصيبني فيقتلني فأكون معهما\nقال والله يا أمير المؤمنين ما أخطأت قال فارجع من قريب وأمر له بجائزة أخبرنا وكيع قال حدثني أحمد بن أبي طاهر قال حدثنا أبو تمام الطائي حبيب بن أوس\nقال حدثني العطاف بن هارون عن يحيى بن حمزة قاضي دمشق قال حدثني حفص الأموي قال كنت أختلف إلى كثير أتروى شعره قال فوالله إني لعنده يوما إذ وقف\nعليه واقف فقال قتل آل المهلب بالعقر فقال ما أجل الخطب ضحى آل أبي سفيان بالدين يوم الطف وضحى بنو مروان بالكرم يوم العقر ثم انتضحت عيناه باكيا فبلغ ذلك يزيد بن عبد الملك فدعا به فلما دخل عليه\nقال عليك لعنة الله أترابية وعصبية وجعل يضحك منه أخبرنا الحرمي قال حدثنا الزبير قال حدثني محمد عن أبيه قال قال عبد الملك بن مروان لكثير من أشعر الناس اليوم يا أبا صخر\nقال من يروي أمير المؤمنين شعره فقال عبد الملك أما إنك لمنهم أخبرنا وكيع قال حدثنا عمر بن محمد بن عبد الملك الزيات قال حدثنا حماد بن إسحاق عن ابن أبي عوف عن عوانة قال قال كثير لعبد الملك كيف ترى شعري يا أمير المؤمنين قال أراه يسبق السحر ويغلب الشعر أخبرنا عمي عن الكراني عن النضر بن عمر قال\nكان عبد الملك بن مروان يخرج شعر كثير إلى مؤدب ولده مختوما يرويهم إياه ويرده أخبرنا الحرمي قال أخبرنا الزبير قال حدثنا عبد الله بن خالد الجهني إن كثيرا شب في حجر عم له صالح فلما بلغ الحلم أشفق عليه أن يسفه وكان غير جيد الرأي ولا حسن النظر في عواقب الأمور فاشترى له عمه قطيعا من الإبل وأنزله فرش ملل فكان به ثم ارتفع فنزل فرع المسور ابن إبراهيم بن عبد الرحمن بن عوف من جبل جهينة الأصغر وكان قبل المسور لبني مالك بن أفصى فضيقوا على كثير وأساؤوا جواره فانتقل عنهم وقال\n(أبت إبلي ماء الرداة وشفها ... بنو العم يحمون النضيح المبردا)\n(وما يمنعون الماء إلا ضنانة ... بأصلاب عسرى شوكها قد تخددا)\n(فعادت فلم تجهد على فضل مائه ... رياحا ولا سقيا ابن طلق بن أسعدا)\nال ويروى أنه أول شعر قاله","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":8,"spl":"كان كثير عاقا لأبيه","tags":[],"loc":1605},
{"id":"b87-10","bab":"الجزء 9","sec":"بدء قوله الشعر وعشقه عزة","page":"ج9 ص31","text":"أخبرنا الحرمي قال حدثنا الزبير قال حدثني عمي قال\nقال كثير ما قلت الشعر حتى قولته قيل له وكيف ذاك قال بينا أنا يوما نصف النهار أسير على بعير لي بالغميم أو بقاع حمدان إذا راكب قد دنا مني حتى صار إلى جنبي فتأملته فإذا هو من صفر وهو يجر نفسه في الأرض جرا فقال لي قل الشعر وألقاه علي\nقلت من أنت قال أنا قرينك من الجن فقلت الشعر ونسب كثير لكثرة تشبيبه بعزة الضمرية إليها وعرف بها فقيل كثير عزة وهي عزة بنت حميل بن وقاص\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني محمد بن الحسن قال أبو بصرة الغفاري المحدث واسمه حميل بن وقاص هو أبو عزة التي كان ينسب بها كثير وكان ابتداء عشقه إياها على أنه قد قيل إنه كان في ذلك كاذبا ولم يكن بعاشق وذلك يذكر بعد خبره معها فيما أخبرني به\nالحرمي قال حدثنا الزبير بن بكار قال حدثني عبد الله بن إبراهيم السعدي قال حدثني إبراهيم بن يعقوب بن جميع الخزاعي أنه كان أول عشق كثير عزة أن كثيرا مر بنسوة من بني ضمرة ومعه جلب غنم فأرسلن إليه عزة وهي صغيرة فقالت يقلن لك النسوة بعنا كبشا من هذه الغنم وأنسئنا بثمنه إلى أن ترجع فأعطاها كبشا وأعجبته فلما رجع جاءته امرأة منهن بدراهمه فقال وأين الصبية التي أخذت مني الكبش قالت وما تصنع بها هذه دراهمك قال لا آخذ دراهمي إلا ممن دفعت الكبش إليها وخرج وهو يقول\n(قضى كل ذي دين فوفى غريمه ... وعزة ممطول معنى غريمها)\nال فكان أول لقائه إياها أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الرحمن بن الخضر بن أبي بكر بن عبد العزيز بن عبد الرحمن أبي جندل عن أبيه عبد العزيز الخزاعي وأمه جمعة بنت كثير عن أمه جمعة عن أبيها كثير أن أول علاقته بعزة أنه خرج من منزله يسوق خلف غنم إلى\nالجار فلما كان بالخبت وقف على نسوة من بني ضمرة فسألهن عن الماء فقلن لعزة وهي جارية حين كعب ثدياها أرشديه إلى الماء فأرشدته وأعجبته فبينا هو يسقي غنمه إذ جاءته عزة بدراهم فقالت يقلن لك النسوة بعنا بهذه الدراهم كبشا من ضأنك فأمر الغلام فدفع إليها كبشا\nوقال ردي الدراهم وقولي لهن إذا رحت بكن اقتضيت حقي فلما راح مر بهن فقلن له هذا حقك فخذه فقال عزة غريمي ولست أقتضي حقي إلا منها فمزحن معه وقلن ويحك عزة جارية صغيرة وليس فيها وفاء لحقك فأحله على إحدانا فإنها أملأ به منها وأسرع له أداء فقال ما أنا بمحيل حقي عنها ومضى لوجهه ثم رجع إليهن حين فرغ من بيع جلبه فأنشدهن فيها\n(نظرت إليها نظرة وهي عاتق ... على حين أن شبت وبان نهودها)\n(وقد درعوها وهي ذات مؤصد ... مجوب ولما يلبس الدرع ريدها)\n(من الخفرات البيض ود جليسها ... إذا ما انقضت أحدوثة لو تعيدها)\nفي هذا البيت وأبيات أخر معه غناء يذكر بعد تمام هذا الخبر وما يضاف إليه من جنسه وأنشدهن أيضا\n(قضى كل ذي دين فوفى غريمه ... وعزة ممطول معنى غريمها)\nقلن له أبيت إلا عزة وأبرزنها إليه وهي كارهة ثم أحبته عزة بعد ذلك أشد من حبه إياها قال الزبير فسألت محمد بن أبي بكر بن عبد العزيز ابن عبد الرحمن الخزاعي المعروف بأبي جندل عن هذا الحديث فعرفه وحدثنيه عن أبيه عن جده عبد العزيز بن أبي جندل عن أمه جمعة بنت كثير عن أبيها\nوأخبرني عمي الحسن بن محمد الأصفهاني رحمه الله قال حدثني محمد بن سعد الكراني قال حدثنا النضر بن عمرو قال حدثني عمر بن عبد الله بن خالد المعيطي\nوأخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن نعيم قال حدثني إبراهيم بن إسحاق الطلحي وأخبرني الحرمي ابن أبي العلاء قال حدثنا الزبير\nقال حدثني يعقوب بن عبد الله الأسدي وغيره قال الزبير وحدثني محمد بن صالح الأسلمي قال دخلت عزة على عبد الملك بن مروان وقد عجزت فقال لها أنت عزة كثير فقالت أنا عزة بنت حميل قال أنت التي يقول لك كثير\n(لعزة نار ما تبوخ كأنها ... إذا ما رمقناها من البعد كوكب)\nما الذي أعجبه منك قالت كلا يا أمير المؤمنين فوالله لقد كنت في عهده أحسن من النار في الليلة القرة وفي حديث محمد بن صالح الأسلمي\nفقالت له أعجبه مني ما أعجب المسلمين منك حين صيروك خليفة قال وكانت له سن سوداء يخفيها فضحك حتى بدت فقالت له هذا الذي أردت أن أبديه فقال لها هل تروين قول كثير فيك\n(وقد زعمت أني تغيرت بعدها ... ومن ذا الذي يا عز لا يتغير)","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":9,"spl":"بدء قوله الشعر وعشقه عزة","tags":["الجواري والنساء"],"loc":1606},
{"id":"b87-11","bab":"الجزء 9","sec":"بدء قوله الشعر وعشقه عزة","page":"ج9 ص31","text":"(تغير جسمي والخليقة كالتي ... عهدت ولم يخبر بسرك مخبر)\nالت لا ولكني أروي قوله\n(كأني أنادي صخرة حين أعرضت ... من الصم لو تمشي بها العصم زلت)\n(صفوحا فما تلقاك إلا بخيلة ... فمن مل منها ذلك الوصل ملت)\nأمر بها فأدخلت على عاتكة بنت يزيد وفي غير هذه الرواية أنها أدخلت على أم البنين بنت عبد العزيز بن مروان فقالت لها أرأيت قول كثير\n(قضى كل ذي دين فوفى غريمه ... وعزة ممطول معنى غريمها)\nا هذا الذي ذكره قالت قبلة وعدته إياها قالت أنجزيها وعلي إثمها أخبرنا الحسن بن الطيب البجلي الشجاعي وأحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالوا حدثنا عمر بن شبة قال روى ابن جعدبة عن أشياخه وأخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا أبو بكر بن يزيد بن عياض بن جعدبة عن أبيه أن كثيرا كان له غلام تاجر فباع من عزة بعض سلعه ومطلته مدة وهو لا يعرفها فقال لها يوما أنت والله كما قال مولاي\n(قضى كل ذي دين فوفى غريمه ... وعزة ممطول معنى غريمها)\nانصرفت عنه خجلة فقالت له امرأة أتعرف عزة قال لا والله قالت فهذه والله عزة فقال لا جرم والله لا آخذ منها شيئا أبدا ولا أقتضيها ورجع إلى كثير فأخبره بذلك فأعتقه ووهب له المال الذي كان في يده أخبرنا الحرمي\nقال حدثنا الزبير بن بكار قال حدثني يعقوب بن حكيم السلمي عن قسيمة بنت عياض بن سعيد الأسلمية وكنيتها أم البنين قالت سارت علينا عزة في جماعة من قومها بين يدي يربوع وجهينة فسمعنا بها فاجتمعت جماعة من نساء الحاضر أنا فيهن فجئناها فرأينا امرأة حلوة حميراء نظيفة فتضاءلنا لها ومعها نسوة كلهن لها عليهن فضل من الجمال والخلق إلى أن تحدثت ساعة فإذا هي أبرع الناس وأحلاهم حديثا فما فارقناها إلا ولها علينا الفضل في أعيننا وما نرى في الدنيا امرأة تروقها جمالا وحسنا وحلاوة\nأخبرني عمي قال حدثني فضل اليزيدي عن إسحاق الموصلي عن أبي نصر شيخ له عن الهيثم بن عدي أن عبد الملك سأل كثيرا عن أعجب خبر له مع عزة فقال حججت سنة من السنين وحج زوج عزة بها ولم يعلم أحد منا\nبصاحبه فلما كنا ببعض الطريق أمرها زوجها بابتياع سمن تصلح به طعاما لأهل رفقته فجعلت تدور الخيام خيمة خيمة حتى دخلت إلي وهي لا تعلم أنها خيمتي وكنت أبري أسهما لي فلما رأيتها جعلت أبري وأنا أنظر إليها ولا أعلم حتى بريت عظامي مرات ولا أشعر به والدم يجري فلما تبينت ذلك دخلت إلي فأمسكت يدي وجعلت تمسح الدم عنها بثوبها وكان عندي نحي من سمن فحلفت لتأخذنه فأخذته وجاءت إلى زوجها بالسمن فلما رأى الدم سألها عن خبره فكاتمته حتى حلف لتصدقنه فصدقته فضربها وحلف لتشتمني في وجهي فوقفت علي وهو معها فقالت لي يابن الزانية وهي تبكي ثم انصرفا فذلك حين أقول\n(يكلفها الخنزير شتمي وما بها ... هواني ولكن للمليك استذلت)\nسبة ما في هذه القصيدة من الغناء\n(خليلي هذا رسم عزة فاعقلا ... قلوصيكما ثم أبكيا حيث حلت)\n(وما كنت أدري قبل عزة ما البكا ... ولا موجعات القلب حتى تولت)\n(فليت قلوصي عند عزة قيدت ... بحبل ضعيف بان منها فضلت)\n(وأصبح في القوم المقيمين رحلها ... وكان لها باغ سواي فبلت)\n(فقلت لها يا عز كل مصيبة ... إذا وطنت يوما لها النفس ذلت)\n(أسيئي بنا أو أحسني لا ملومة ... لدينا ولا مقلية إن تقلت)\n(هنيئا مريئا غير داء مخامر ... لعزة من أعراضنا ما استحلت)\n(تمنيتها حتى إذا ما رأيتها ... رأيت المنايا شرعا قد أظلت)\n(كأني أنادي صخرة حين أعرضت ... من الصم لو تمشي بها العصم زلت)\n(صفوحا فما تلقاك إلا بخيلة ... فمن مل منها ذلك الوصل ملت)\n(أصاب الردى من كان يهوى لك الردى ... وجن اللواتي قلن عزة جنت)\nعروضه من الطويل غنى معبد في الخمسة الأول ثقيلا أول بالوسطى وغنى إبراهيم في الثالث والرابع ثقيلا أول بالبنصر عن عمرو وغنى في هنيئا مريئا والذي بعده خفيف رمل بالوسطى وغنى إبراهيم في الخامس وما بعده ثاني ثقيل","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":10,"spl":"بدء قوله الشعر وعشقه عزة","tags":[],"song":1,"loc":1607},
{"id":"b87-13","bab":"الجزء 9","sec":"بدء قوله الشعر وعشقه عزة — هل كان كثير صادقا في عشقه","page":"ج9 ص31 – ج9 ص41","text":"وذكر الهشامي أن لابن سريج في هنيئا مريئا وما بعده ثاني ثقيل بالبنصر وذكر أحمد بن المكي أن لإبراهيم في كأني أنادي والذي بعده وفي أسيئي بنا أو أحسني هزجا بالسبابة في مجرى البنصر ولإسحاق فيه هزج آخر به ولعريب في كأني أنادي أيضا رمل ولإسحاق في وما كنت أدري ثقيل أول وله في أصاب الردى ثقيل أول آخر وقيل إن لإبراهيم في فقلت لها يا عز خفيف ثقيل ينسب إلى دحمان وإلى سياط\nأخبرني الحرمي وحبيب بن نصر قالا حدثنا الزبير قال حدثنا يعقوب بن حكيم عن إبراهيم بن أبي عمرو الجهني عن أبيه قال سارت علينا عزة في جماعة من قومها فنزلت حيالنا فجاءني كثير ذات يوم فقال لي أريد أن أكون عندك اليوم فأذهب إلى عزة فصرت به إلى منزلي فأقام عندي حتى كان العشاء ثم أرسلني إليها وأعطاني خاتمه\nوقال إذا سلمت فستخرج إليك جارية فادفع إليها خاتمي وأعلمها مكاني فجئت بيتها فسلمت فخرجت إلي الجارية فأعطيتها الخاتم فقالت أين الموعد\nقلت صخرات أبي عبيد الليلة فواعدتها هناك فرجعت إليه فأعلمته فلما أمسى قال لي انهض بنا فنهضنا فجلسنا هناك نتحدث حتى جاءت من الليل فجلست فتحدثا فأطالا فذهبت لأقوم فقال لي إلى أين تذهب فقلت أخليكما ساعة لعلكما تتحدثان ببعض ما تكتمان فقال لي اجلس فوالله ما كان بيننا شيء قط فجلست وهما يتحدثان وإن بينهما لثمامة عظيمة هي من ورائها جالسة حتى أسحرنا ثم قامت فانصرفت وقمت أنا وهو فظل عندي حتى أمسى ثم انطلق أخبرنا الحرمي\nقال حدثنا الزبير قال حدثنا إسحاق بن إبراهيم عن عبد الله بن سعيد بن أبان بن سعيد بن العاصي قال خرج كثير في الحاج بجمل له يبيعه فمر بسكينة بنت الحسين ومعها\nعزة وهو لا يعرفها فقالت سكينة هذا كثير فسوموه بالجمل فساموه فاستام مائتي درهم فقالت ضع عنا فأبى فدعت له بتمر وزبد فأكل ثم قالت له ضع عنا كذا وكذا لشيء يسير فأبى فقالوا قد أكلت يا كثير بأكثر مما نسألك فقالت ما أنا بواضع شيئا فقالت سكينة اكشفوا فكشفوا عنها وعن عزة فلما رآهما استحيا وانصرف وهو يقول هو لكم هو لكم\nمن ذكر أن كثيرا كان يكذب في عشقه أخبرنا أبو خليفة قال حدثنا ابن سلام قال كان كثير مدعيا ولم يكن عاشقا وكان جميل صادق الصبابة والعشق أخبرنا أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا\nحدثنا عمر بن شبة قال زعم إسحاق بن إبراهيم أنه سمع أبا عبيدة يقول كان جميل يصدق في حبه وكان كثير يكذب ومما وجدناه في أخباره ولم نسمعه من أحد أنه نظر إلى عزة ذات يوم وهي منتقبة تميس في مشيتها فلم يعرفها كثير فاتبعها\nوقال يا سيدتي قفي حتى أكلمك فإني لم أر مثلك قط فمن أنت ويحك قالت ويحك وهل تركت عزة فيك بقية لأحد قال بأبي أنت والله لو أن عزة أمة لي\nلوهبتها لك قالت فهل لك في المخاللة قال وكيف لي بذلك قالت أنى وكيف بما قلت في عزة قال أقلبه فأحوله إليك فسفرت عن وجهها ثم قالت أغدرا يا فاسق وإنك لهكذا فأبلس ولم ينطق وبهت فلما مضت أنشأ يقول\n(ألا ليتني قبل الذي قلت شيب لي ... من السم جدحات بماء الذرارح)\n(فمت ولم تعلم علي خيانة ... وكم طالب للربح ليس برابح)\n(أبوء بذنبي إنني قد ظلمتها ... وإني بباقي سرها غير بائح)","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":11,"spl":"بدء قوله الشعر وعشقه عزة — هل كان كثير صادقا في عشقه","tags":["الحب والغزل","الجواري والنساء","السفر والحج"],"loc":1608},
{"id":"b87-14","bab":"الجزء 9","sec":"عتاب المحبين","page":"ج9 ص42","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثني عمر بن شبة قال زعم ابن الكلبي عن أبي المقوم قال أخبرني سائب راوية كثير قال خرجت معه نريد مصر فمررنا بالماء الذي فيه عزة فإذا هي في خباء فسلمنا جميعا فقالت عزة وعليك السلام يا سائب ثم أقبلت على كثير فقالت ويحك ألا تتقي الله أرأيت قولك\n(بآية ما أتيتك أم عمرو ... فقمت لحاجتي والبيت خالي)\nخلوت معك في بيت أو غير بيت قط قال لم أقله ولكنني قلت\n(فأقسم لو أتيت البحر يوما ... لأشرب ما سقتني من بلال)\n(وأقسم إن حبك أم عمرو ... لداء عند منقطع السعال)\nقالت أما هذا فنعم فأتينا عبد العزيز ثم عدنا فقال كثير عليك السلام يا عزة قالت عليك السلام يا جمل فقال كثير\n(حيتك عزة بعد الهجر فانصرفت ... فحي ويحك من حياك يا جمل)\n(لو كنت حييتها ما زلت ذا مقة ... عندي وما مسك الإدلاج والعمل)\n(ليت التحية كانت لي فأشكرها ... مكان يا جمل حييت يا رجل)\nكر يونس أن في هذه الأبيات غناء لمعبد وذكر الهشامي أن فيها لبثينة خفيف رمل بالبنصر وذكر حبش أن فيها للغريض خفيف ثقيل أول بالوسطى ولإبراهيم ثاني ثقيل بالوسطى\nأخبرني عمي قال حدثني الحسن بن عليل العنزي قال حدثني علي بن محمد البرمكي قال حدثني إبراهيم بن المهدي قال قدم علي هشام بن محمد الكلبي فسألته عن العشاق يوما فحدثني\nقال تعشق كثير امرأة من خزاعة يقال لها أم الحويرث فنسب بها وكرهت أن يسمع بها ويفضحها كما سمع بعزة فقالت له إنك رجل فقير لا مال لك فابتغ مالا يعفي عليك ثم تعال فاخطبني كما يخطب الكرام قال\nفاحلفي لي ووثقي أنك لا تتزوجين حتى أقدم عليك فحلفت ووثقت له فمدح عبد الرحمن بن إبريق الأزدي فخرج إليه فلقيته ظباء سوانح ولقي غرابا يفحص التراب بوجهه فتطير من ذلك حتى قدم على حي من لهب فقال أيكم يزجر فقالوا كلنا فمن تريد قال أعلمكم بذاك قالوا ذاك الشيخ المنحني الصلب فأتاه فقص عليه القصة فكره ذلك له وقال له قد توفيت أو تزوجت رجلا من بني عمها فأنشأ يقول\n(تيممت لهبا أبتغي العلم عندهم ... وقد رد علم العائفين إلى لهب)\n(تيممت شيخا منهم ذا بجالة ... بصيرا بزجر الطير منحني الصلب)\n(فقلت له ماذا ترى في سوانح ... وصوت غراب يفحص الوجه بالترب)\n(فقال جرى الطير السنيح ببينها ... وقال غراب جد منهمر السكب)\n(فإلا تكن ماتت فقد حال دونها ... سواك خليل باطن من بني كعب)\nغناه مالك من رواية يونس ولم يجنسه قال فمدح الرجل الأزدي ثم أتاه فأصاب منه خيرا كثيرا ثم قدم عليها فوجدها قد تزوجت رجلا\nمن بني كعب فأخذه الهلاس فكشح جنباه بالنار فلما اندمل من علته وضع يده على ظهره فإذا هو برقمتين فقال ما هذا قالوا إنه أخذك الهلاس وزعم الأطباء أنه لا علاج لك إلا الكشح بالنار فكشحت بالنار فأنشأ يقول\n(عفا الله عن أم الحويرث ذنبها ... علام تعنيني وتكمي دوائيا)\n(فلو آذنوني قبل أن يرقموا بها ... لقلت لهم أم الحويرث دائيا)\nي هذين البيتين لمالك ثقيل أول بالوسطى ولابن سريج رمل بالبنصر كلاهما عن عمرو والهشامي وقيل إن فيهما لمعبد لحنا وقد أخبرني بهذا الخبر أحمد بن عبد العزيز وحبيب بن نصر المهلبي قالا\nحدثنا عمر بن شبة ولم يتجاوزاه بالرواية فذكر نحو هذا وقال فيه إنه قصد ابن الأزرق بن حفص بن المغيرة المخزومي الذي كان باليمن وإنه فعل ذلك بعد موت عزة وسائر الخبر متقارب\nوأخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن إسماعيل الجعفري عن محمد بن سليمان بن فليح أو فليح بن سليمان أنا شككت عن أبيه عن جده قال جاء كثير إلى عبد الله بن جعفر وقد نحل وتغير فقال له عبد الله\nمالي أراك متغيرا يا أبا صخر قال هذا ما عملت بي أم الحويرث ثم ألقى قميصه فإذا به قد صار مثل القش وإذا به آثار من كي ثم أنشده\n(عفا الله عن أم الحويرات ذنبها ... )\nلأبيات","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":12,"spl":"عتاب المحبين","tags":["المديح"],"song":3,"loc":1609,"partial":1},
{"id":"b87-15","bab":"الجزء 9","sec":"عزة تمتحن كثيرا","page":"ج9 ص46","text":"أخبرني عمي قال حدثني ابن أبي قال حدثني الحزامي عمن حدثه من أهل قديد أن عزة قالت لبثينة تصدي لكثير وأطمعيه في نفسك حتى أسمع ما يجيبك به فأقبلت إليه وعزة تمشي وراءها مختفية فعرضت عليه الوصل فقاربها ثم قال\n(رمتني على عمد بثينة بعد ما ... تولى شبابي وارججن شبابها)\nذكر أبياتا أخرى سقط من الكتاب ذكرها فكشفت عزة عن وجهها فبادرها الكلام ثم قال\n(ولكنما ترمين نفسا مريضة ... لعزة منها صفوها ولبابها)\nضحكت ثم قالت أولى لك بها قد نجوت وانصرفتا تتضاحكان\nأخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الرحمن بن عبد الله الزهري قال بكى بعض أهل كثير عليه حين نزل به الموت فقال له كثير لا تبك فكأنك بي بعد أربعين ليلة تسمع خشفة نعلي من تلك الشعبة راجعا إليكم\nأخبرني الفضل بن الحباب أبو خليفة قال حدثنا محمد بن سلام قال حدثني ابن جعدبة وأبو اليقظان عن جويرية بن أسماء قال مات كثير وعكرمة مولى ابن عباس في يوم واحد فاجتمعت قريش في جنازة كثير ولم يوجد لعكرمة من يحمله أخبرنا الحرمي\nقال حدثنا الزبير قال حدثني عمر بن مصعب قال حدثني الواقدي قال حدثني خالد بن القاسم البياضي قال مات عكرمة مولى ابن عباس وكثير بن عبد الرحمن الخزاعي صاحب عزة في يوم واحد في سنة خمس ومائة فرأيتهما جميعا صلي عليهما في يوم واحد بعد الظهر في موضع الجنائز فقال الناس مات اليوم أفقه الناس وأشعر الناس\nوقال ابن أبي سعد الوراق حدثني رجاء بن سهل أبو نصر الصاغاني قال حدثنا يحيى بن غيلان قال حدثني المفضل بن فضالة عن يزيد بن عروة قال مات عكرمة وكثير عزة في يوم واحد فأخرجت جنازتاهما فما علمت تخلفت امرأة بالمدينة ولا رجل عن جنازتيهما قال وقيل مات أشعر الناس وأعلم الناس قال وغلب النساء على جنازة كثير يبكينه ويذكرن عزة\nفي ندبتهن له قال فقال أبو جعفر محمد بن علي افرجوا لي عن جنازة كثير لأرفعها قال فجعلنا ندفع عنها النساء وجعل يضربهن محمد بن علي بكمه ويقول تنحين يا صواحبات يوسف فانتدبت له امرأة منهن فقالت يابن رسول الله لقد صدقت إنا لصواحبات يوسف وقد كنا له خيرا منكم له\nقال فقال أبو جعفر لبعض مواليه احتفظ بها حتى تجيئني بها إذا انصرفنا قال فلما انصرف أتي بتلك المرأة كأنها شرارة النار فقال لها محمد بن علي أنت القائلة إنكن ليوسف خير منا قالت نعم تؤمنني غضبك يابن رسول الله\nقال أنت آمنة من غضبي فأبيني قالت نحن يا بن رسول الله دعوناه إلى اللذات من المطعم والمشرب والتمتع والتنعم وأنتم معاشر الرجال ألقيتموه في الجب وبعتموه بأبخس الأثمان وحبستموه في السجن فأينا كان عليه أحنى وبه أرأف فقال محمد لله درك ولن تغالب امرأة إلا غلبت ثم\nقال لها ألك بعل قالت لي من الرجال من أنا بعله قال فقال أبو جعفر صدقت مثلك من تملك بعلها ولا يملكها قال فلما انصرفت قال رجل من القوم هذه زينب بنت معيقب نسبة ما في هذه الأخبار من الغناء\n(نظرت إليها نظرة وهي عاتق ... على حين أن شبت وبان نهودها)\n(نظرت إليها نظرة ما يسرني ... بها حمر أنعام البلاد وسودها)\n(وكنت إذا ما جئت سعدى بأرضها ... أرى الأرض تطوى لي ويدنو بعيدها)\n(من الخفرات البيض ود جليسها ... إذا ما انقضت أحدوثة لو تعيدها)\nعروضه من الطويل البيت الأول لكثير والثاني والثالث لنصيب من قصيدته التي أولها\n(لقد هجرت سعدى وطال صدودها ... )\nنى في البيت الثاني والثالث جحدر الراعي خفيف رمل بالبنصر وغنى فيهما الهذلي رملا بالوسطى وغنى في الثالث والرابع دعامة ثقيلا أول بالبنصر أخبرنا الحسين بن يحيى عن حماد عن أبيه قال قال عمر الوادي وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني مكين العذري قال سمعت عمر الوادي يقول بينا أنا أسير بين الروحاء والعرج إذ سمعت إنسانا يغني غناء لم أسمع قط مثله في بيتي كثير\n(وكنت إذا ما جئت سعدى بأرضها ... أرى الأرض تطوى لي ويدنو بعيدها)\n(من الخفرات البيض ود جليسها ... إذا ما انقضت أحدوثة لو تعيدها)","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":13,"spl":"عزة تمتحن كثيرا","tags":["الحب والغزل"],"song":1,"loc":1610,"partialRef":{"sid":"b71-3","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b87-16","bab":"الجزء 9","sec":"عزة تمتحن كثيرا","page":"ج9 ص46","text":"قال فكدت أسقط عن راحلتي طربا وقلت والله لألتمسن الوصول إلى هذا الصوت ولو بذهاب عضو من أعضائي فتيممت سمته فإذا راع في غنم فسألته إعادته علي قال نعم ولو حضرني قرى أقريكه ما أعدته ولكني أجعله قراك فربما ترنمت به وأنا غرثان فأشبع وعطشان فأروى ومستوحش فآنس وكسلان فأنشط قال فأعادهما علي حتى أخذتهما فما كان زادي حتى ولجت المدينة غيرهما","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":14,"spl":"عزة تمتحن كثيرا — أخبار عبيد الله بن عبد الله بن طاهر","tags":["السفر والحج","الرواية والكتابة"],"loc":1611},
{"id":"b87-17","bab":"الجزء 9","sec":"أخبار عبيد الله بن عبد الله بن طاهر","page":"ج9 ص50","text":"هو عبيد الله بن عبد الله بن طاهر بن الحسين ويكنى أبا أحمد وله محل من الأدب والتصرف في فنونه ورواية الشعر وقوله والعلم باللغة وأيام الناس وعلوم الأوائل من الفلاسفة في الموسيقى والهندسة وغير ذلك مما يجل عن الوصف ويكثر ذكره وله صنعة في الغناء حسنة متقنة عجيبة تدل على ما ذكرناه هاهنا من توصله إلى ما عجز عنه الأوائل من جمع النغم كلها في صوت واحد تتبعه هو وأتى به على فضله فيها وطلبه لها وكان المعتضد بالله رحمة الله عليه ربما كان أراد أن يصنع في بعض الأشعار غناء وبحضرته أكابر المغنين مثل القاسم بن زرزور وأحمد بن المكي ومن دونهما مثل أحمد بن أبي العلاء وطبقتهم فيعدل عنهم إليه فيصنع فيها أحسن صنعة ويترفع عن إظهار نفسه بذلك ويومئ إلى أنه من صنعة جاريته شاجي وكانت إحدى المحسنات المبرزات المقدمات وذلك بتخريجه وتأديبه وكان بها معجبا ولها مقدما","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":14,"spl":"عزة تمتحن كثيرا — أخبار عبيد الله بن عبد الله بن طاهر","tags":["الوصف والطبيعة"],"loc":1612},
{"id":"b87-18","bab":"الجزء 9","sec":"المعتضد يتفقده بالصلات","page":"ج9 ص51","text":"فأخبرني أحمد بن جعفر جحظة قال لما اختلت حال عبيد الله بن\nعبد الله بن طاهر كان المعتضد يتفقده بالصلات الفينة بعد الفينة واتفق يوما كان فيه مصطبحا أن غني بصوت الصنعة فيه لشاجي جارية عبيد الله فكتب إليه كتابا يقسم أن يأمرها بزيارته ففعل\nقال فحدثني من حضر من المغنيات ذلك المجلس بعد موت المعتضد قالت دخلت إلينا وما منا إلا من يرفل في الحلي والحلل وهي في أثواب ليست كثيابنا فاحتقرناها فلما غنت احتقرنا أنفسنا ولم تزل تلك حالنا حتى صارت في أعيننا كالجبل وصرنا كلا شيء\nقال ولما انصرفت أمر لها المعتضد بمال وكسوة ودخلت إلى مولاها فجعل يسألها عن أمرها وما رأت مما استظرفت وسمعت مما استغربت فقالت ما استحسنت هناك شيئا ولا استغربته من غناء ولا غيره إلا عودا من عود محفور فإني استظرفته\nقال جحظة فما قولك فيمن يدخل دار الخلافة فلا يمد عينه لشيء يستحسنه فيها إلا عودا قال محمد بن الحسن الكاتب وحدثني النوشجاني قال كان المعتضد إذا استحسن شعرا بعث به إلى شاجي جارية عبيد الله بن طاهر فتغني فيه\nقال وكانت صنعتها تسمى في عصره غناء الدار قال محمد بن الحسن وماتت شاجي في حياة عبيد الله بن عبد الله بن طاهر وكان عليلا فقال يرثيها وله فيه صنعة من خفيف الثقيل الأول بالوسطى\n(يمينا يقينا لو بليت بفقدها ... وبي نبض عرق للحياة أو النكس)\n(لأوشكت قتل النفس قبل فراقها ... ولكنها ماتت وقد ذهبت نفسي)\nومن نادر صنعة عبيد الله وجيد شعره قوله وله فيه لحنان ثقيل أول وهزج والثقيل الأول أجودهما\n(أنفق إذا أيسرت غير مقتر ... وأنفق على ما خليت حين تعسر)\n(فلا الجود يفني المال والمال مقبل ... ولا البخل يبقي المال والجد مدبر)\nأشعاره كثيرة جيدة كثيرة النادر والمختار وكتابه في النغم وعلل الأغاني المسمى كتاب الآداب الرفيعة كتاب مشهور جليل الفائدة دال على فضل مؤلفه\nأخبرني جحظة قال حدثني الحرمي بن أبي العلاء قال حدثني موسى بن هارون فيما أرى قال كنت عند عبيد الله بن عبد الله بن طاهر وقد جاءه الزبير بن بكار فأعلمه أن المتوكل أو المعتز وأراه المعتز بعث إلى أخيه محمد بن عبد الله بن طاهر يأمر بإحضاره وتقليده القضاء فقال له الزبير بن بكار قد بلغت هذه السن وأتولى القضاء أو بعد ما رويت أن من ولي القضاء فقد ذبح بغير سكين فقال له فتلحق بأمير المؤمنين بسر من رأى فقال له أفعل فأمر له بمال ينفقه وبظهر يحمله ويحمل ثقله ثم قال له إن رأيت يا أبا عبد الله أن تفيدنا شيئا قبل أن نفترق قال نعم انصرفت من عمرة المحرم\nفبينا أنا بأثاية العرج إذا أنا بجماعة مجتمعة فأقبلت إليهم وإذا رجل كان يقنص الظباء وقد وقع ظبي في حبالته فذبحه فانتفض في يده فضرب بقرنه صدره فنشب القرن فيه فمات وأقبلت فتاة كأنها المهاة فلما رأت زوجها ميتا شهقت ثم قالت\n(يا حسن لو بطل لكنه أجل ... على الأثاية ما أودى به البطل)\n(يا حسن جمع أحشائي وأقلقها ... وذاك يا حسن لولا غيره جلل)\n(أضحت فتاة بني نهد علانية ... وبعلها بين أيدي القوم محتمل)\nال ثم شهقت فماتت فما رأيت أعجب من الثلاثة الظبي مذبوح والرجل جريح ميت والفتاة ميتة حرى فأمر له عبيد الله بمال آخر ثم أقبل إلى أخيه محمد بن عبد الله بعد خروج الزبير فقال أما إن الذي أخذناه من الفائدة في خبر حسن وفي قولها\n(أضحت فتاة بني نهد علانية ... )\nريد ظاهرة أكثر عندي مما أعطيناه من الحباء والصلة وقد أخبرني الحسين بن علي عن الدمشقي عن الزبير بخبر حسن فقط ولم يذكر فيه من خبر عبيد الله شيئا ومن الأصوات التي تجمع النغم العشر صوت وهو يجمع النغم العشر كلها على غير توال\n(وإنك إذ أطمعتني منك بالرضا ... وأيأستني من بعد ذلك بالغضب)\n(كممكنة من ضرعها كف حالب ... ودافقة من بعد ذلك ما حلب)\nروضه من الطويل الشعر لإبراهيم بن علي بن هرمة والغناء في هذا اللحن الجامع للنغم لعبيد الله بن عبد الله بن طاهر - خفيف ثقيل - أول بالوسطى في مجراها وعليها ابتدأ الصوت\nوقال عمر بن محمد بن عبد الملك الزيات حدثني بعض أصحابنا عن أبي نواس أنه قال شاعران قالا بيتين وضعا التشبيه فيهما في غير موضعه فلو أخذ البيت الثاني من شعر أحدهما فجعل مع بيت الآخر وأخذ بيت ذاك فجعل مع هذا لصار متفقا معنى وتشبيها فقلت له أنى ذلك فقال قول جرير للفرزدق","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":15,"spl":"المعتضد يتفقده بالصلات","tags":["الحب والغزل"],"loc":1613,"partial":1},
{"id":"b87-19","bab":"الجزء 9","sec":"المعتضد يتفقده بالصلات","page":"ج9 ص51","text":"(فإنك إذ تهجو تميما وترتشي ... تبابين قيس أو سحوق العمائم)\n(كمهريق ماء بالفلاة وغره ... سراب أذاعته رياح السمائم)\nقول ابن هرمة\n(وإني وتركي ندى الأكرمين ... وقدحي بكفي زندا شحاحا)\n(كتاركة بيضها بالعراء ... وملبسة بيض أخرى جناحا)\nفلو قال جرير\n(فإنك إذ تهجو تميما وترتشي ... تبابين قيس أو سحوق العمائم)\n(كتاركة بيضها بالعراء ... وملبسة بيض أخرى جناحا)\nكان أشبه منه ببيته ولو قال ابن هرمة مع بيته\n(وإني وتركي ندى الأكرمين ... وقدحي بكفي زندا شحاحا)\n(كمهريق ماء بالفلاة وغره ... سراب أذاعته رياح السمائم)\nان أشبه به ثم قال ولكن ابن هرمة قد تلافى ذلك بعد فقال\n(وإنك إذا أطمعتني منك بالرضا ... وأيأستني من بعد ذلك بالغضب)\n(كممكنة من ضرعها كف حالب ... ودافقة من بعد ذلك ما حلب)\nقد أتى عبيد الله بهذا الكلام بعينه في الآداب الرفيعة وإنما أخذه من أبي نواس على ما روي عنه ووجدت في كتاب مؤلف في النغم غير مسمى الصانع أن من الأصوات التي تجمع النغم صوت ابن أبي مطر المكي في شعر نصيب وهو\n(ألا أيها الربع المقيم بعنبب ... سقتك السواقي من مراح ومعزب)\n(بذي هيدب أما الربى تحت ودقه ... فتروى وأما كل واد فيزعب)\nروضه من الطويل ويروى الربع الخلاء بعنبب أي الخالي وعنبب موضع ويروى سقتك الغوادي من مراد والمراد الموضع الذي يرتاد فيرعى فيه الكلأ والمراح الموضع الذي تروح إليه المواشي وتبيت فيه وفي الحديث أنه رخص في الصلاة في مراح الغنم ونهى عنها في أعطان الإبل والمعزب الموضع الذي يعزب فيه الرجل عن البيوت والمنازل وأصل العزوب البعد يقال عزب عنه رأيه وحلمه أي بعد والعزب مأخوذ من ذلك وهيدب السماء أطراف تراه في أذنابه كأنه معلق به قال أوس بن حجر\n(دان مسف فويق الأرض هيدبه ... يكاد يدفعه من قام بالراح)\nيزعب يطفح يقال زعبه السيل إذا ملأه الشعر لنصيب يقوله في عبد العزيز بن مروان أخبرنا الحرمي قال حدثنا الزبير قال حدثني جميع بن علي النميري عن عبد الله بن عبد العزيز بن محجن بن النصيب\nقال الزبير وكتب إلي بذلك عبد الله بن عبد العزيز يذكره عن عوضة بنت النصيب قالت وفد أبي على عبد العزيز بن مروان بمصر فوقف على الباب فاستأذن فلم يؤذن له فأرسل إليه حاجبه فقال استنشده فإن كان شعره رديئا فاردده وإن كان جيدا فأدخله فقال نصيب قد جلبنا شيئا للأمير فإن قبله نشرناه\nعليه وإلا طويناه ورجعنا به فقال عبد العزيز إن هذا لكلام رجل ذهن فأدخله فلما واجهه أنشده قصيدته التي يقول فيها\n(ألا هل أتى الصقر بن مروان أنني ... أرد لدى الأبواب عنه وأحجب)\n(وأني ثويت اليوم والأمس قبله ... على الباب حتى كادت الشمس تغرب)\n(وأني إذا رمت الدخول تردني ... مهابة قيس والرتاج المضبب)\nال وكان حاجب عبد العزيز يسمى قيسا قال وتشبيب هذه القصيدة\n(ألا أيها الربع المقيم بعنبب ... سقتك السواقي من مراح ومعزب)\nقال فلما دخل على عبد العزيز أعجب بشعره وأوجهه وقال للفرزدق كيف تسمع هذا الشعر قال حسن إلا من لغته قال هذا والله أشعر منك قال وقال نصيب فيها أيضا\n(وأهلي بأرض نازحون وما لهم ... بها كاسب غيري ولا متقلب)\n(فهل تلحقنيهم بعبل مواشك ... على الأين من نجب ابن مروان أصهب)\n(أبو بكرات إن أردت افتحاله ... وذو ثبتات بالرديفين متعب)\nقال له عبد العزيز ادخل على المهاري فخذ منها ما شئت فلو كنت سألت غيره لأعطيته فدخل فرده الجمال فقال عبد العزيز دعه فإنما يأخذ الذي نعت فأخذه قال الزبير وحدثني بعض أصحابنا عن محمد بن عبد العزيز قال\nنزل عبد العزيز بن عبد الوهاب على المهدي بعنبب من وادي السراة الذي عنى نصيب بقوله\n(ألا أيها الربع الخلاء بعنبب ... )\nالمهدي هو الذي يقول فيه الشاعر\n(اسلمي يا دار من هند ... بالسويقات إلى المهدي)\nصوت وهو يجمع من النغم ثمانيا\n(يا من لقلب مقصر ... ترك المنى لفواتها)\n(وتظلف النفس التي ... قد كان من حاجاتها)\n(وطلابك الحاجات من ... سلمى ومن جاراتها)\n(كتطرد العنس الذمول ... الفضل من مثناتها)\nوله يا من لقلب مقصر تأسف على شبابه ويدل على ذلك قوله\n(وتظلف النفس التي ... قد كان من حاجاتها)\nقال أظلف نفسك عن كذا أي امنعها منه لئلا يكون لها أثر فيه وهو مأخوذ من ظلف الأرض وهو المكان الذي لا أثر فيه قال عوف بن الأحوص","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":16,"spl":"المعتضد يتفقده بالصلات","tags":[],"song":1,"loc":1614,"partial":1},
{"id":"b87-20","bab":"الجزء 9","sec":"المعتضد يتفقده بالصلات","page":"ج9 ص51","text":"(ألم أظلف عن الشعراء عرضي ... كما ظلف الوسيقة بالكراع)\nالوسيقة الجماعة من الإبل يعني أنها تساق فلا يوجد لها أثر في الكراع وهو منقطع الجبل قال الشاعر\n(أمست كراع الغميم موحشة ... بعد الذي قد خلا من العجب)\nوقوله\n(كتطرد العنس الذمول ... الفضل من مثناتها)\nقول طلابك هذه الحاجات ضلال وتتابع كتطرد العنس وهي الناقة المذكرة الخلق الفضل من مثناتها والتطرد التتبع ومثله قول الشاعر\n(خبطت الصبا خبط البعير خطامه ... فلم أنتبه للشيب حتى علانيا)\nلشعر لمسافر بن أبي عمرو بن أمية بن عبد شمس والغناء لابن محرز ثاني ثقيل مطلق في مجرى البنصر عن إسحاق وهذا الصوت يجمع من النغم ثمانيا وكذلك\nذكر إسحاق ووصف أنه لم يجمع شيء من الغناء قديمه وحديثه إلى عصره من النغم ما جمعه هذا الصوت ووصف أنه لو تلطف متلطف لأن يجمع النغم الشعر في صوت واحد لأمكنه ذلك بعد أن يكون فهما بالصناعة طويل المعاناة لها وبعد أن يتعب نفسه في ذلك حتى يصح له فلم يقدر على ذلك سوى عبيد الله بن عبد الله إلى وقتنا هذا","topic":"ذكر أخبار كثير ونسبه","topicNo":87,"sp":17,"spl":"المعتضد يتفقده بالصلات","tags":["الوصف والطبيعة"],"loc":1615},
{"id":"b88-1","bab":"الجزء 9","sec":"ذكر مسافر ونسبه","page":"ج9 ص61","text":"مسافر بن أبي عمرو بن أمية ويكنى أبا أمية وقد تقدم نسبه وأنساب أهله وأمه آمنة بنت أبان بن كليب بن ربيعة بن عامر بن صعصعة وهي أم أبي معيط أبان بن عمرو بن أمية وأبو معيط ومسافر أخوان لأب وأم وهما أخوا عمومتهما أبي العاصي وأخويه من بني أمية الذين أمهم آمنة لأن أبا عمرو تزوجها بعد أبيه وكان سيدا جوادا وهو أحد أزواد الركب وإنما سموا بذلك لأنهم كانوا لا يدعون غريبا ولا مار طريق ولا محتاجا يجتاز بهم إلا أنزلوه وتكفلوا به حتى يظعن وهو أحد شعراء قريش وكان يناقض عمارة بن الوليد الذي أمر النجاشي السواحر فسحرته فمن ذلك قول عمارة\n(خلق البيض الحسان لنا ... وجياد الريط والأزر)\n(كابرا كنا أحق به ... حين صيغ الشمس والقمر)\nقال مسافر يرد عليه\n(أعمار بن الوليد وقد ... يذكر الشاعر من ذكره)\n(هل أخو كأس محققها ... وموق صحبه سكرة)\n(ومحييهم إذا شربوا ... ومقل فيهم هذره)\n(خلق البيض الحسان لنا ... وجياد الريط والحبره)\n(كابرا كنا أحق به ... كل حي تابع أثره)","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":0,"spl":"ذكر مسافر ونسبه","tags":["الحب والغزل","الجواري والنساء"],"loc":1616},
{"id":"b88-2","bab":"الجزء 9","sec":"مسافر وهند بنت عتبة","page":"ج9 ص62","text":"وله شعر ليس بالكثير والأبيات التي فيها الغناء يقولها في هند بنت عتبة بن ربيعة بن عبد شمس وكان يهواها فخطبها إلى أبيها بعد فراقها الفاكه بن المغيرة فلم ترض ثروته وماله فوفد على النعمان يستعينه على أمره ثم عاد فكان أول من لقيه أبو سفيان فأعلمه بتزويجه من هند فأخبرني أحمد بن عبيد الله بن عمار\nقال حدثني عمر بن محمد بن عبد الملك الزيات قال حدثني ابن أبي سلمة عن هشام قال ابن عمار وقد حدثناه ابن أبي سعد عن علي بن الصباح عن هشام\nقال ابن عمار وحدثنيه علي بن محمد بن سليمان النوفلي عن أبيه دخل حديث بعضهم في بعض أن مسافر بن أبي عمرو بن أمية كان من فتيان قريش جمالا وشعرا وسخاء قالوا فعشق هندا بنت عتبة بن ربيعة وعشقته فاتهم بها وحملت منه قال بعض الرواة فقال معروف بن خربوذ فلما بان حملها أو كاد قالت\nله اخرج فخرج حتى أتى الحيرة فأتى عمرو بن هند فكان ينادمه وأقبل أبو سفيان بن حرب إلى الحيرة في بعض ما كان يأتيها فلقي مسافرا فسأله عن حال قريش والناس فأخبره وقال له فيما يقول وتزوجت هندا بنت عتبة فدخله من ذلك ما اعتل معه حتى استسقى بطنه قال ابن خربوذ فقال مسافر في ذلك\n(ألا إن هندا أصبحت منك محرما ... وأصبحت من أدنى حموتها حما)\n(وأصبحت كالمقمور جفن سلاحه ... يقلب بالكفين قوسا وأسهما)\nدعا له عمرو بن هند الأطباء فقالوا لا دواء له إلا الكي فقال له ما ترى قال افعل فدعا له الذي يعالجه فأحمى مكاويه فلما صارت كالنار قال ادع أقواما يمسكونه فقال لهم مسافر لست أحتاج إلى ذلك فجعل يضع المكاوي عليه فلما رأى صبره ضرط الطبيب فقال مسافر\n(قد يضرط العير والمكواة في النار ... )\nجرت مثلا فلم يزده إلا ثقلا فخرج يريد مكة فلما انتهى إلى موضع يقال له هبالة مات فدفن بها ونعي إلى قريش فقال أبو طالب بن عبد المطلب يرثيه\n(ليت شعري مسافر بن أبي عمرو ... وليت يقولها المحزون)\n(رجع الركب سالمين جميعا ... وخليلي في مرمس مدفون)\n(بورك الميت الغريب كما بورك ... نضر الريحان والزيتون)\n(بيت صدق على هبالة قد حالت ... فياف من دونه وحزون)\n(مدره يدفع الخصوم بأيد ... وبوجه يزينه العرنين)\n\n(كم خليل رزئته وابن عم ... وحميم قضت عليه المنون)\n(فتعزيت بالتأسي وبالصبر ... وإني بصاحبي لضنين)\nنى في هذين البيتين يحيى المكي ثاني ثقيل بالوسطى من رواية ابنه والهشامي وأنشدنا الحرمي قال أنشدنا الزبير لأبي طالب بن عبد المطلب في مسافر بن أبي عمرو\n(ألا إن خير الناس غير مدافع ... بسرو سحيم غيبته المقابر)\n(تبكي أباها أم وهب وقد نأى ... وريسان أمسى دونه ويحابر)\n(على خير حاف من معد وناعل ... إذا الخير يرجى أو إذا الشر حاضر)\n(تنادوا ولا أبو أمية فيهم ... لقد بلغت كظ النفوس الحناجر)\nال وقال النوفلي إن البيتين\n(ألا إن هندا أصبحت منك محرما ... )\nوالذي بعده لهشام بن المغيرة وكانت عنده أسماء بنت مخرمة النهشلية فولدت له أبا جهل وأخاه الحارث ثم غضب عليها فجعلها مثل ظهر أمه وكان أول ظهار كان فجعلته قريش طلاقا فأرادت أسماء الانصراف إلى أهلها فقال لها هشام وأين الموعد قالت الموسم فقال لها ابناها أقيمي معنا فأقامت معهما فقال المغيرة بن عبد الله وهو أبو زوجها أما والله لأزوجنك غلاما ليس بدون هشام فزوجها أبا ربيعة ولده الآخر فولدت له عياشا وعبد الله فذلك قول هشام\n(تحدثنا أسماء أن سوف نلتقي ... أحاديث طسم إنما أنت حالم)\nقوله\n(ألا أصبحت أسماء حجرا محرما ... وأصبحت من أدنى حموتها حما)\nال النوفلي في خبره وحدثني أبي أنه إنما كان مسافر خرج إلى النعمان بن المنذر يتعرض لإصابة مال ينكح به هندا فأكرمه النعمان واستظرفه ونادمه وضرب عليه قبة من أدم حمراء وكان الملك إذا فعل ذلك\nبرجل عرف قدره منه ومكانه عنده وقدم أبو سفيان بن حرب في بعض تجاراته فسأله مسافر عن حال الناس بمكة فذكر له أنه تزوج هندا فاضطرب مسافر حتى مات وقال بعض الناس إنه استسقى بطنه فكوي فمات بهذا السبب قال النوفلي فهو أحد من قتله العشق","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":1,"spl":"مسافر وهند بنت عتبة","tags":["الحب والغزل"],"song":1,"loc":1617,"partial":1},
{"id":"b88-3","bab":"الجزء 9","sec":"هند والفاكه بن المغيرة","page":"ج9 ص66","text":"فأما خبر هند وطلاق الفاكه بن المغيرة إياها فأخبرني به أحمد بن عبيد الله بن عمار قال حدثني ابن أبي سعد قال حدثني أبو السكين زكريا بن يحيى ابن عمرو بن حصن بن حميد بن حارثة الطائي\nقال حدثني عمي زحر بن حصن عن جده حميد بن حارثة قال كانت هند بنت عتبة عند الفاكه بن المغيرة وكان الفاكه من فتيان قريش وكان له بيت للضيافة بارز من البيوت يغشاه الناس من غير إذن فخلا البيت ذات يوم فاضطجع هو وهند فيه ثم نهض لبعض حاجته وأقبل رجل ممن كان يغشى البيت فولجه فلما رآها رجع هاربا وأبصره الفاكه فأقبل إليها فضربها برجله\nوقال من هذا الذي خرج من عندك قالت ما رأيت أحدا ولا انتبهت حتى أنبهتني فقال لها ارجعي إلى أمك وتكلم الناس فيها وقال لها أبوها يا بنية إن الناس قد أكثروا فيك فأنبئيني نبأك فإن يكن الرجل عليك صادقا دسست عليه من يقتله فتنقطع عنك المقالة وإن يك كاذبا حاكمته إلى بعض كهان اليمن فقالت لا والله ما هو علي بصادق فقال له يا فاكه إنك قد رميت بنتي بأمر عظيم فحاكمني إلى بعض كهان اليمن فخرج الفاكه في جماعة من بني مخزوم وخرج عتبة في جماعة من عبد مناف ومعهم هند ونسوة فلما شارفوا البلاد وقالوا غدا نرد على الرجل تنكرت حال هند فقال لها عتبة إني أرى ما حل بك من تنكر الحال وما ذاك إلا لمكروه عندك قالت لا والله يا أبتاه ما ذاك لمكروه ولكني أعرف أنكم تأتون بشرا يخطئ ويصيب ولا آمنه أن يسمني ميسما يكون علي سبة\nفقال لها إني سوف أختبره لك فصفر بفرسه حتى أدلى ثم أدخل في إحليله حبة بر وأوكأ عليها بسير فلما أصبحوا قدموا على الرجل فأكرمهم ونحر لهم فلما قعدوا\nقال له عتبة جئناك في أمر وقد خبأت لك خبئا أختبرك به فانظر ما هو قال ثمرة في كمرة قال إني أريد أبين من هذا قال حبة بر في إحليل مهر\nقال صدقت انظر في أمر هؤلاء النسوة فجعل يدنو من إحداهن فيضرب بيده على كتفها ويقول انهضي حتى دنا من هند فقال لها انهضي غير رسحاء ولا زانية ولتلدن ملكا يقال له معاوية فنهض إلينا الفاكه فأخذ بيدها فنثرت يدها من يده وقالت إليك عني فوالله لأحرص أن يكون ذلك من غيرك فتزوجها أبو سفيان وقد قيل إن بيتي مسافر بن أبي عمرو أعني\n(ألا إن هندا أصبحت منك محرما ... )\nابن عجلان أخبرني محمد بن خلف وكيع قال حدثني عبد الله بن علي بن الحسن عن أبي نصر عن الأصمعي عن عبد الله بن أبي سلمة عن أيوب عن ابن سيرين قال\nخرج عبد الله بن العجلان في الجاهلية فقال\n(ألا إن هندا أصبحت منك محرما ... وأصبحت من أدنى حموتها حما)\n(فأصبحت كالمقمور جفن سلاحه ... يقلب بالكفين قوسا وأسهما)\nم مد بهما صوته فمات قال ابن سيرين فما سمعت أن أحدا مات عشقا غير هذا ومما يغنى فيه من شعر مسافر بن أبي عمرو وهو من جيد شعره قوله يفتخر\n(ألم نسق الحجيج وننحر ... المذلاقة الرفدا)\n(وزمزم من أرومتنا ... ونفقأ عين من حسدا)\n(وإن مناقب الخيرات ... لم نسبق بها عددا)\n(فإن نهلك فلم نملك ... وهل من خالد خلدا)\nناه ابن سريج رملا بالخنصر في مجرى البنصر عن إسحاق وفيه لسائب خاثر لحن من خفيف الثقيل الأول بالوسطى من رواية حماد وفيه للزف ثقيل بالوسطى","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":2,"spl":"هند والفاكه بن المغيرة","tags":[],"song":1,"loc":1618,"partialRef":{"sid":"b88-2","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b88-4","bab":"الجزء 9","sec":"فأما خبر عمارة بن الوليد والسبب الذي من أجله أمر النجاشي السواحر","page":"ج9 ص69","text":"فسحرته فإن الواقدي ذكره عن عبد الله بن جعفر بن أبي عون قال كان عمارة بن الوليد المخزومي بعد ما مشت قريش بعمارة إلى أبي طالب خرج هو وعمرو بن العاص بن وائل السهمي وكانا كلاهما تاجرين إلى النجاشي وكانت أرض الحبشة لقريش متجرا ووجها وكلاهما مشرك شاعر فاتك وهما في جاهليتهما وكان عمارة معجبا بالنساء صاحب محادثة فركبا في السفينة ليالي فأصابا من خمر معهما فلما انتشى عمارة\nقال لامرأة عمرو بن العاص قبليني فقال لها عمرو قبلي ابن عمك فقبلته وحذر عمرو على زوجته فرصدها ورصدته فجعل إذا شرب معه أقل عمرو من الشراب وأرق لنفسه بالماء مخافة أن يسكر فيغلبه عمارة على أهله وجعل عمارة يراودها على نفسها فامتنعت منه ثم إن عمرا جلس إلى ناحية السفينة يبول فدفعه عمارة في البحر فلما وقع فيه سبح حتى أخذ بالقلس فارتفع فظهر على السفينة فقال له عمارة أما والله لو علمت يا عمرو أنك تحسن السباحة ما فعلت فاضطغنها عمرو وعلم أنه أراد قتله فمضيا على وجههما\nذلك حتى قدما أرض الحبشة ونزلاها وكتب عمرو بن العاص إلى أبيه العاص أن اخلعني وتبرأ من جريرتي إلى بني المغيرة وجميع بني مخزوم وذلك أنه خشي على أبيه أن يتبع بجريرته وهو يرصد لعمارة ما يرصد فلما ورد الكتاب على العاص بن وائل مشى في رجال من قومه منهم نبيه ومنبه ابنا الحجاج إلى بني المغيرة وغيرهم من بني مخزوم فقال إن هذين الرجلين قد خرجا حيث علمتم وكلاهما فاتك صاحب شر وهما غير مأمونين على أنفسهما ولا ندري ما يكون وإني أبرأ إليكما من عمرو ومن جريرته وقد خلعته فقالت بنو المغيرة وبنو مخزوم أنت تخاف عمرا على عمارة وقد خلعنا نحن عمارة وتبرأنا إليك من جريرته فخل بين الرجلين فقال السهميون قد قبلنا فابعثوا مناديا بمكة أنا قد خلعناهما وتبرأ كل قوم من صاحبهم ومما جر عليهم فبعثوا مناديا ينادي بمكة بذلك فقال الأسود بن المطلب بطل والله دم عمارة بن الوليد آخر الدهر فلما اطمأنا بأرض الحبشة لم يلبث عمارة أن دب لامرأة النجاشي فأدخلته فاختلف إليها فجعل إذا رجع من مدخله يخبر عمرو بن العاص بما كان من أمره فجعل عمرو يقول ما أصدقك أنك قدرت على هذا الشأن إن المرأة أرفع من ذلك فلما أكثر على عمرو مما كان يخبره وقد كان صدقه ولكن أحب التثبت وكان عمارة يغيب عنه حتى يأتيه في السحر وكان في منزل واحد معه وجعل عمارة يدعوه إلى أن يشرب معه فيأبى عمرو ويقول إن هذا يشغلك عن مدخلك وكان عمرو يريد أن يأتيه بشيء لا يستطيع دفعه إن هو رفعه إلى النجاشي فال له في بعض ما يذكر له من أمرها إن كنت صادقا فقل لها\nتدهنك من دهن النجاشي الذي لا يدهن به غيره فإني أعرفه لو أتيتني به لصدقتك ففعل عمارة فجاء بقارورة من دهنه فلما شمه عرفه فقال له عمرو عند ذلك أنت صادق لقد أصبت شيئا ما أصاب أحد مثله قط من العرب ونلت من امرأة الملك شيئا ما سمعنا بمثل هذا وكانوا أهل جاهلية ثم سكت عنه حتى إذا اطمأن دخل على النجاشي فقال أيها الملك إن ابن عمي سفيه وقد خشيت أن يعرني عندك أمره وقد أردت أن أعلمك شأنه ولم أفعل حتى استثبت أنه قد دخل على بعض نسائك فأكثر وهذا من دهنك قد أعطيه دهني منه فلما شم النجاشي الدهن\nقال صدقت هذا دهني الذي لا يكون إلا عند نسائي ثم دعا بعمارة ودعا بالسواحر فجردوه من ثيابه فنفخن في إحليله ثم خلى سبيله فخرج هاربا فلم يزل بأرض الحبشة حتى كانت خلافة عمر بن الخطاب فخرج إليه عبد الله بن أبي ربيعة وكان اسمه قبل أن يسلم بحيرا فسماه رسول الله فرصده على ماء بأرض الحبشة وكان يرده مع الوحش فورد فلما وجد ريح الإنس هرب حتى إذا أجهده العطش ورد فشرب حتى تملأ وخرجوا في طلبه فقال عبد الله بن أبي ربيعة فسعيت إليه فالتزمته فجعل يقول لي يا بحير أرسلني يا بحير أرسلني إني أموت إن أمسكتموني\nقال عبد الله وضغطته فمات في يدي مكانه فواراه ثم انصرف وكان شعره قد غطى على كل شيء منه قال الواقدي عن ابن أبي الزناد وقال عمرو لعمارة يا فائد إن كنت تحب أن أصدقك بهذا أو أقبله منك فأتني بثوبين أصفرين فلما رأى النجاشي الثوبين قال له عمرو أتعرف الثوبين قال نعم\nوقال الواقدي عن ابن أبي الزناد عن أبيه قال النجاشي لعمارة إني أكره أن أقتل قرشيا ولو قتلت قرشيا لقتلتك فدعا بالسواحر","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":3,"spl":"فأما خبر عمارة بن الوليد والسبب الذي من أجله أمر النجاشي السواحر","tags":["الحب والغزل","الجواري والنساء"],"loc":1619},
{"id":"b88-5","bab":"الجزء 9","sec":"شعر عمرو بن العاص في عمارة","page":"ج9 ص72","text":"فقال عمرو بن العاص يذكر عمارة وما صنع به قال الواقدي أخبرني ابن أبي الزناد أنه سمع ذلك من ابن ابنه عمرو بن شعيب بن عبد الله بن عمرو يذكره لحده\n(تعلم عمار أن من شر شيمة ... لمثلك أن يدعى ابن عم له ابنما)\n(وإن كنت ذا بردين أحوى مرجلا ... فلست براع لابن عمك محرما)\n(إذا المرء لم يترك طعاما يحبه ... ولم ينه قلبا غاويا حيث يمما)\n(قضى وطرا منه يسيرا وأصبحت ... إذا ذكرت أمثالها تملأ الفما)\n(فليس الفتى ولو أتمت عروقه ... بذي كرم إلا بأن يتكرما)\n(صحبت من الأمر الرفيق طريقه ... ووليت غي الأمر من قد تلوما)\n(من الآن فانزع عن مطاعم جمة ... وعالج أمور المجد لا تتندما)\nال إسحاق وحدثني الأصمعي أن خولة بنت ثابت أخت حسان قالت في عمارة لما سحر\n(يا ليلتي لم أنم ولم أكد ... أقطعها بالبكاء والسهد)\n(أبكي على فتية رزئتهم ... كانوا جبالي فأوهنوا عضدي)\n(كانوا جمالي ونصرتي وبهم ... أمنع ضيمي وكل مضطهد)\n(فبعدهم أرقب النجوم وأذري ... الدمع والحزن والج كبدي)\nقال الأصمعي واجتاز ابن سريج بطويس ومعه فتية من قريش وهو\nيغنيهم في هذا الصوت فوقف حتى سمعه ثم أقبل عليهم فقال هذا والله سيد من غناه هذه الأصوات التي ذكرتها الجامعة للنغم العشر والثماني النغم منها هي المشهورة المعروفة عند الرواة وفي روايات الرواة وعند المغنين وكان عبيد الله بن عبد الله بن طاهر يراسل المعتضد بالله إذا استزار جواريه على ألسنتهن ومع ذوي الانس عنده من رسله مع أحمد بن الطيب وثابت بن قرة الطائي يذكر النغم وتفصيل مجاريها ومعانيها حتى فهم ذلك فصنع لحنا فجمع النغم الشعر في قول دريد بن الصمة\n(يا ليتني فيها جذع ... أخب فيها وأضع)","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":4,"spl":"شعر عمرو بن العاص في عمارة — الأرمال الثلاثة المختارة","tags":[],"loc":1620},
{"id":"b88-6","bab":"الجزء 9","sec":"المكتفي يراسله في الغناء","page":"ج9 ص73","text":"وصنع صنعة متقنة جيدة منها ما سمعناه من المحسنين والمحسنات ومنها ما لم نسمعه يكون مبلغها نحو خمسين صوتا وقد ذكرت من ذلك ما\nصلح في أغاني الخلفاء ثم صنع مثل ذلك للمكتفي بالله لرغبته في هذه الصناعة فوجدت رقعة بخطه كتب بها إلى المكتفي نسختها قال إسحاق ابن إبراهيم حين صاغ عند أبي العباس عبد الله بن طاهر بأمره لحنه في\n(يوم تبدي لنا قتيلة عن جيد ... تليع تزينه الأطواق)\n(وشتيت كالأقحوان جلاه الطل ... فيه عذوبة واتساق)\nني نظرت مع إبراهيم وتصفحت غناء العرب كله فلم نجد في جميع غناء العرب صوتا أطول إيقاعا من\n(عادك الهم ليلة الإيجاف ... من غزال مخضب الأطراف)\nلحنه خفيف ثقيل لابن محرز فإن إيقاعه ستة وخمسون دورا ثم لحن معبد\n(هريرة ودعها وإن لام لائم ... غداة غد أم أنت للبين واجم)\nهو أحد سبعته ولحنه خفيف ثقيل ودور إيقاعه ستة وخمسون دورا إلا أن صوت ابن محرز سداسي في العروض من الخفيف وصوت معبد ثماني من الطويل فصوت ابن محرز أعجب لأنه أقصر وما زلنا حتى تهيأ لنا شعر رباعي في سيدنا أمير المؤمنين أطال الله بقاءه دور إيقاعه ستة\nوخمسون دورا وهو يجمع من النغم العشر ثمانيا وهذا ظريف جدا بديع لم يكن مثله وأما الصوت الذي في تهنئة النوروز فلأنفسنا عملناه إذ لم يكن لنا من يدبر مثل هذا معه غيره وقد كتبنا شعره وشعر الآخر وإيقاع كل واحد منهما خفيف ثقيل والصنعة فيهما تستظرف\n(جمع الخلائف كلهم لجميع ما ... بلغوا وأعطوا في الإمام المكتفي)\n(وله الهدايا ألف نوروز وهذا ... الشعر منها لحنه لم يعرف)\nالآخر\n(دولة المكتفي الخليفة ... تفني مدى الدول)\n(يوم عيد ويوم عرس ... فما بعدها أمل)\nلصنعة في البيت الأول خاصة تدور على ستة وخمسين إيقاعا هكذا وجدت في الرقعة بخط عبيد الله وما سمعت أحدا يغني هذين الصوتين وقد عرضتهما على غير واحد من المتقدمين ومن مغنيات القصور فما عرفهما أحد منهن وذكرتهما في الكتاب لأن شريطته توجب ذكرهما","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":4,"spl":"شعر عمرو بن العاص في عمارة — الأرمال الثلاثة المختارة","tags":[],"loc":1621},
{"id":"b88-7","bab":"الجزء 9","sec":"الأرمال الثلاثة المختارة","page":"ج9 ص75","text":"أخبرني يحيى بن علي ومحمد بن خلف وكيع والحسين بن يحيى قالوا حدثنا حماد بن إسحاق قال حدثني أبي قال أبو أحمد رحمه الله وأخبرني أبي أيضا عن إسحاق وأخبرنا علي بن عبد العزيز قال حدثنا عبيد الله بن خرداذبه قال قال إسحاق أجمع العلماء بالغناء أن أحسن رمل غني رمل\n(فلم أر كالتجمير منظر ناظر ... )\nثم رمل\n(أفاطم مهلا بعض هذا التدلل ... )\nلو عاش ابن سريج حتى يسمع لحني الرمل\n(لعلك إن طالت حياتك أن ترى ... )\nاستحيا أن يصنع بعده شيئا وفي روايتي وكيع وعلي بن يحيى ولعلم أني نعم الشاهد له","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":4,"spl":"شعر عمرو بن العاص في عمارة — الأرمال الثلاثة المختارة","tags":["الرواية والكتابة"],"loc":1622,"partialRef":{"sid":"b52-78","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b88-8","bab":"الجزء 9","sec":"نسبة الأصوات وأخبارها","page":"ج9 ص76","text":"\n(فلم أر كالتجمير منظر ناظر ... ولا كليالي الحج أفلتن ذا هوى)\n(فكم من قتيل ما يباء به دم ... ومن غلق رهنا إذا لفه منى)\n(ومن مالئ عينيه من شيء غيره ... إذا راح نحو الجمرة البيض كالدمى)\n(يسحبن أذيال المروط باسؤق ... خدال وأعجاز مآكمها روا)\nروضه من الطويل الشعر لعمر بن أبي ربيعة والغناء لابن سريج رمل بالبنصر وقد كان علويه فيما بلغنا صنع فيه رملا وفي أفاطم مهلا خفيف رمل وفي لعلك إن طالت حياتك رملا آخر ولم يصنع شيئا وسقطت ألحانه فيها فما تكاد تعرف وهذه الأبيات يقولها عمر بن أبي ربيعة في بنت مروان بن الحكم","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":5,"spl":"نسبة الأصوات وأخبارها — عمر بن أبي ربيعة وأم عمرو بنت مروان","tags":["الجواري والنساء"],"song":1,"loc":1623},
{"id":"b88-9","bab":"الجزء 9","sec":"عمر بن أبي ربيعة وأم عمرو بنت مروان","page":"ج9 ص77","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا ابن كناسة عن أبي بكر بن عياش قال حجت أم عمرو بنت مروان فلما قضت نسكها أتت عمر بن أبي ربيعة وقد أخفت نفسها في نساء معها فحادثته ثم انصرفت وعادت إليه منصرفها\nمن عرفات وقد أثبتها فقالت له لا تذكرني في شعرك وبعثت إليه بألف دينار فقبلها واشترى بها ثيابا من ثياب اليمن وطيبا فأهداه إليها فردته فقال إذا والله أنهبه الناس فيكون مشهورا فقبلته وقال فيها\n(أيها الرائح المجد ابتكارا ... قد قضى من تهامة الأوطارا)\n(من يكن قلبه الغداة خليا ... ففؤادي بالخيف أمسى مطارا)\n(ليت ذا الدهر كان حتما علينا ... كل يومين حجة واعتمارا)\nال ابن كناسة قال ابن عياش فلما وجهت منصرفة قال فيها\n(فكم من قتيل ما يباء به دم ... ومن غلق رهنا إذا لفه منى)\nال ويروى ومن غلق رهن كأنه قال ومن رهن غلق لا يجعل من نعت الرهن كأنه جعل الإنسان غلقا وجعله رهنا كما يقال كم من عاشق مدنف ومن كلف صب قال الزبير وحدثني مسلم بن عبد الله بن مسلم بن جندب عن أبيه قال أنشده ابن أبي عتيق فقال إن في نفس الجمل ما ليس في نفس الجمال قال وقال عبد الله بن عمر وقد أنشده عمر بن أبي ربيعة شعره هذا يابن أخي أما اتقيت الله حيث يقول\n(ليت ذا الدهر كان حتما علينا ... كل يومين حجة واعتمارا)\nقال له عمر بن أبي ربيعة بأبي أنت وأمي إني وضعت ليتا حيث لا تغني","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":5,"spl":"نسبة الأصوات وأخبارها — عمر بن أبي ربيعة وأم عمرو بنت مروان","tags":["الجواري والنساء","الرواية والكتابة"],"loc":1624},
{"id":"b88-10","bab":"الجزء 9","sec":"عمر بن أبي ربيعة يتوب عن التشبيب بالنساء","page":"ج9 ص78","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه وأخبرني علي بن عبد العزيز عن عبيد الله بن عبد الله عن إسحاق وأخبرني ببعض هذا الخبر الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا مصعب بن عثمان\nأن عمر بن عبد العزيز لما ولي الخلافة لم تكن له همة إلا عمر بن أبي ربيعة والأحوص فكتب إلى عامله على المدينة قد عرفت عمر والأحوص بالخبث والشر فإذا أتاك كتابي هذا فاشددهما واحملهما إلي فلما أتاه الكتاب حملهما إليه فأقبل على عمر فقال له هيه\n(فلم أر كالتجمير منظر ناظر ... ولا كليالي الحج أفلتن ذا هوى)\n(وكم مالئ عينيه من شيء غيره ... إذا راح نحو الجمرة البيض كالدمى)\nإذا لم يفلت الناس منك في هذه الأيام فمتى يفلتون أما والله لو اهتممت بأمر حجك لم تنظر إلى شيء غيرك ثم أمر بنفيه فقال يا أمير المؤمنين أو خير من ذلك قال وما هو قال أعاهد الله ألا أعود إلى مثل هذا الشعر ولا أذكر النساء في شعر أبدا وأجدد توبة على يديك قال أو تفعل قال نعم فعاهد الله على توبة وخلاه ثم دعا بالأحوص فقال هيه\n(الله بيني وبين قيمها ... يهرب مني بها وأتبع)\nل الله بين قيمها وبينك ثم أمر بنفيه إلى بيش وقيل إلى دهلك وهو الصحيح فنفي إليها فم يزل بها فرحل إلى عمر عدة من الأنصار فكلموه في أمره وسألوه أن يقدمه وقالوا له قد عرفت نسبه وقدمه وموضعه وقد\nأخرج إلى بلاد الشرك فنطلب إليك أن ترده إلى حرم رسول الله ودار قومه فقال لهم عمر من الذي يقول\n(فما هو إلا أن أراها فجاءة ... فأبهت حتى ما أكاد أحير)\nفي رواية الزيبر أجيب مكان أحير قالوا الأحوص قال فمن الذي يقول\n(أدور ولولا أن أرى أم جعفر ... بأبياتكم ما درت حيث أدور)\n(وما كنت زوارا ولكن ذا الهوى ... إذا لم يزر لا بد أن سيزور)\nالوا الأحوص قال فمن الذي يقول\n(كأن لبنى صبير غادية ... أو دمية زينت بها البيع)\n(الله بيني وبين قيمها ... يهرب مني بها وأتبع)\nالوا الأحوص قال إن الفاسق عنها يومئذ لمشغول والله لا أرده ما كان لي سلطان فمكث هناك بعد ولاية عمر صدرا من ولاية يزيد بن عبد الملك ثم خلاه قال وكتب إلى عمر بن عبد العزيز من موضعه قال الزبير أنشدنيها عبد الملك بن عبد العزيز ابن بنت الماجشون قال أنشدنيها يوسف ابن الماجشون يعني هذه الأبيات\n(أيا راكبا إما عرضت فبلغن ... هديت أمير المؤمنين رسائلي)\n(وقل لأبي حفص إذا ما لقيته ... لقد كنت نفاعا قليل الغوائل)\n(أفي الله أن تدنوا ابن حزم وتقطعوا ... قوى حرمات بيننا ووصائل)\n(فكيف ترى للعيش طيبا ولذة ... وخالك أمسى موثقا في الحبائل)\n(وما طمع الحزمي في الجاه قبلها ... إلى أحد من آل مروان عادل)\n(وشى وأطاعوه بنا وأعانه ... على أمرنا من ليس عنا بغافل)\n(وكنت أرى أن القرابة لم تدع ... ولا الحرمات في العصور الأوائل)\n(إلى أحد من آل مروان ذي حجى ... بأمر كرهناه مقالا لقائل)\n(يسر بما أنهى العدو وإنه ... كنافلة لي من خيار النوافل)\n(فهل ينقصني القوم أن كنت مسلما ... بريئا بلائي في ليال قلائل)\n(ألا رب مسرور بنا سيغيظه ... لدى غب أمر عضه بالأنامل)\n(رجا الصلح مني آل حزم بن فرتنى ... على دينهم جهلا ولست بفاعل)\n(ألا قد يرجون الهوان فإنهم ... بنو حبق ناء عن الخير فائل)\n(على حين حل القول بي وتنظرت ... عقوبتهم مني رؤوس القبائل)\n(فمن يك أمسى سائلا بشماتة ... بما حل بي أو شامتا غير سائل)\n(فقد عجمت مني العواجم ماجدا ... صبورا على عضات تلك التلاتل)\n(إذا نال لم يفرح وليس لنكبة ... إذا حدثت بالخاضع المتضائل)\nقال الزبير وقال الأحوص أيضا\n(هل انت أمير المؤمنين فإنني ... بودك من ود العباد لقانع)\n(متمم أجر قد مضى وصنيعة ... لكم عندنا أو ما تعد الصنائع)\n(فكم من عدو سائل ذي كشاحة ... ومنتظر بالغيب ما أنت صانع)\nلم يغن عنه ذلك ولم يخل سبيله عمر حتى ولي يزيد بن عبد الملك فأقدمه وقد غنته حبابة بصوت في شعره\nأخبرنا إسماعيل بن يونس قال حدثنا عمر بن شبة قال قال هشام بن حسان كان السبب في رد يزيد بن عبد الملك الأحوص أن جميلة غنته يوما\n(كريم قريش حين ينسب والذي ... أقرت له بالملك كهلا وأمردا)","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":6,"spl":"عمر بن أبي ربيعة يتوب عن التشبيب بالنساء","tags":["الحب والغزل"],"loc":1625},
{"id":"b88-11","bab":"الجزء 9","sec":"عمر بن أبي ربيعة يتوب عن التشبيب بالنساء","page":"ج9 ص78","text":"فطرب يزيد وقال ويحك من كريم قريش هذا قالت أنت يا أمير المؤمنين ومن عسى أن يكون ذلك غيرك قال ومن قائل هذا الشعر في قالت الأحوص وهو منفي فكتب برده وحمله إليه وأنفذ إليه صلات سنية فلما قدم إليه أدناه وقربه وأكرمه وقال له يوما في مجلس حافل والله لو لم تمت الينا بحق ولا صهر ولا رحم إلا بقولك\n(وإني لأستحييكم أن يقودني ... إلى غيركم من سائر الناس مطمع)\nكفاك ذلك عندنا قال ولم يزل ينادمه وينافس به حتى مات وأخبار الأحوص في هذا السبب وغيره قد مضت مشروحة في أول ما مضى من ذكره وأخباره لأن الغرض هاهنا ذكر بقية خبره مع عمر بن أبي ربيعة في الشعرين اللذين أنكرهما عليهما عمر بن عبد العزيز وأشخصا من أجلهما","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":7,"spl":"عمر بن أبي ربيعة يتوب عن التشبيب بالنساء — سليمان بن عبد الملك ينفي عمر بن أبي ربيعة إلى ا","tags":["الموت"],"loc":1626},
{"id":"b88-12","bab":"الجزء 9","sec":"سليمان بن عبد الملك ينفي عمر بن أبي ربيعة إلى الطائف","page":"ج9 ص83","text":"أخبرنا محمد بن خلف وكيع قال حدثنا أحمد بن زهير قال قال مصعب ابن عبد الله قال حج سليمان بن عبد الملك وهو خليفة فأرسل إلى عمر بن أبي ربيعة فقال له ألست القائل\n(فكم من قتيل ما يباء به دم ... ومن غلق رهنا إذا لفه منى)\n(ومن مالئ عينيه من شيء غيره ... إذا راح نحو الجمرة البيض كالدمى)\n(يسحبن أذيال المروط بأسؤق ... خدال وأعجاز مآكمها روا)\n(أوانس يسلبن الحليم فؤاده ... فيا طول ما شوق ويا طول مجتلى)\nال نعم قال لا جرم والله لا تحضر الحج العام مع الناس فأخرجه إلى الطائف أخبرنا الحسين بن يحيى قال قال حماد قرأت على أبي حدثني ابن الكلبي عن أبي مسكين وعن صالح بن حسان قال قدم ابن أبي عتيق إلى مكة فسمع غناء ابن سريج\n(فلم أر كالتجمير منظر ناظر ... ولا كليالي الحج أفلتن ذا هوى)\nقال ما سمعت كاليوم قط وما كنت أحسب أن مثل هذا بمكة وأمر\nله بمال وحدره معه إلى المدينة وقال لأصغرن إلى معبد نفسه ولأهدين إلى المدينة شيئا لم ير أهلها مثله حسنا وظرفا وطيب مجلس ودماثة خلق ورقة منظر ومقة عند كل أحد فقدم به المدينة وجمع بينه وبين معبد فقال لابن سريج ما تقول فيه قال إن عاش كان مغني بلاده وقال إسحاق وحدثني المدائني عن جرير قال قال لي أبو السائب يوما ما معك من مرقصات ابن سريج فغنيته\n(فلم أر كالتجمير منظر ناظر ... )\nقال كما أنت حتى أتحرم لهذا بركعتين حدثني الحسين قال قال حماد قرأت على أبي وحدثني أبو عبد الله الزبيري قال كتب الوليد بن عبد الملك إلى عامل مكة أن أشخص إلي ابن سريج فورد الرسول إلى الوالي فمر في بعض طريقه على ابن سريج وهو جالس بين قرني بئر وهو يغني\n(فلم أر كالتجمير منظر ناظر ... )\nقال له الرسول تالله ما رأيت كاليوم قط ولا رأيت أحمق ممن يتركك ويبعث إلى غيرك فقال له ابن سريج أما والله ما هو بقدم ولا ساق ولكنه بقسم وأرزاق ثم مضى الرسول فأوصل الكتاب وبعث الوالي إلى ابن سريج فأحضره فلما رآه الرسول قال قد عجبت أن يكون المطلوب غيرك","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":7,"spl":"عمر بن أبي ربيعة يتوب عن التشبيب بالنساء — سليمان بن عبد الملك ينفي عمر بن أبي ربيعة إلى ا","tags":["السفر والحج","الرواية والكتابة"],"loc":1627,"partialRef":{"sid":"b3-16","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b88-13","bab":"الجزء 9","sec":"اعجاب عبد الله بن الزبير بغناء ابن سريج","page":"ج9 ص84","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني\nعمي قال رقي عبد الله بن الزبير أبا قبيس ليلا فسمع غناء فنزل هو وأصحابه يتعجبون وقال لقد سمعت صوتا إن كان من الإنس إنه لعجب وإن كان من الجن لقد أعطوا شيئا كثيرا فاتبعوا الصوت فإذا ابن سريج يتغنى في شعر عمر\n(فلم أر كالتجمير منظر ناظر ... )\nومن هذه الأرمال الثلاثة\n(أفاطم مهلا بعض هذا التدلل ... وإن كنت قد أزمعت صرمي فأجملي)\n(أغرك مني أن حبك قاتلي ... وأنك مهما تأمري القلب يفعل)\nالشعر لامرئ القيس والغناء في هذين البيتين من الرمل المختار لإسحاق بالبنصر وفي هذين البيتين مع أبيات أخر من هذه القصيدة ألحان شتى لجماعة نذكرها هاهنا ومن غنى فيها ثم نتبع ما يحتاج إلى ذكره منها وقد يجمع سائر ما يغنى فيه من القصيدة معه\n(قفا نبك من ذكرى حبيب ومنزل ... بسقط اللوى بين الدخول فحومل)\n(فتوضح فالمقراة لم يعف رسمها ... لما نسجتها من جنوب وشمأل)\n(أفاطم مهلا بعض هذا التدلل ... وإن كنت قد أزمعت صرمي فأجملي)\n(وإن كنت قد ساءتك مني خليقة ... فسلي ثيابي من ثيابك تنسل)\n(أغرك مني أن حبك قاتلي ... وأنك مهما تأمري القلب يفعل)\n(وما ذرفت عيناك إلا لتضربي ... بسهميك في أعشار قلب مقتل)\n(تسلت عمايات الرجال عن الصبا ... وليس فؤادي عن هواك بمنسل)\n(ألا أيها الليل الطويل ألا انجل ... بصبح وما الإصباح فيك بأمثل)\n(وبيضة خدر لا يرام خباؤها ... تمتعت من لهو بها غير معجل)\n(تجاوزت أحراسا إليها ومعشرا ... علي حراصا لو يسرون مقتلي)\n(ألا رب يوم صالح لك منهما ... ولا سيما يوم بدارة جلجل)\n(ويوم عقرت للعذارى مطيتي ... فواعجبي من رحلها المتحمل)\n(وقد أغتدي والطير في وكناتها ... بمنجرد قيد الأوابد هيكل)\n(مكر مفر مقبل مدبر معا ... كجلمود صخر حطه السيل من عل)\n(فقلت لها سيري وأرخي زمامه ... ولا تبعدينا من جناك المعلل)\nعروضه من الطويل وسقط اللوى منقطعه واللوى المستدق من الرمل حيث يستدق فيخرج منه إلى اللوى والدخول وحومل وتوضح والمقراة مواضع ما بين إمرة إلى أسود العين وقال أبو عبيدة في سقط\nاللوى وسقط الولد وسقط النار سقط وسقط وسقط ثلاث لغات وقال أبو زيد اللوى أرض تكون بين الحزن والرمل فصلا بينهما وقال الأصمعي قوله بين الدخول فحومل خطأ ولا يجوز إلا بواو وحومل لأنه لا يجوز أن يقال رأيت فلانا بين زيد فعمرو إنما يقال وعمرو ويقال رأيت زيدا فعمرا إذا رأى كل واحد منهما بعد صاحبه\nوقال غيره يجوز فحومل كما يقال مطرنا بين الكوفة فالبصرة كأنه قال من الكوفة إلى البصرة يريد أن المطر لم يتجاوز ما بين هاتين الناحيتين وليس هذا مثل بين زيد فعمرو ويعف رسمها يدرس ونسجتها ضربتها مقبلة ومدبرة فعفتها يعني أن الجنوب تعفي هذا الرسم إذا هبت وتجيء الشمأل فتكشفه\nوقال غير أبي عبيدة المقراة ليس اسم موضع إنما هو الحوض الذي يجمع فيه الماء والرسم الأثر الذي لا شخص له ويروى لما نسجته يعني الرسم ويقال عفا يعفو عفوا وعفاء قال الشاعر\n(على آثار من ذهب العفاء ... )\nعني محو الأثر وفاطمة التي خاطبها فقال أفاطم مهلا بنت العبيد بن ثعلبة بن عامر بن عوف بن كنانة بن عوف بن عذرة وهي التي يقول فيها\n(لا وأبيك ابنة العامري ... )\nأزمعت صرمي يقال أزمعت وأجمعت وعزمت وكله سواء يقول إن كنت عزمت على الهجر فأجملي ويقول الأسير أجملوا في قتلي قتلة أحسن من هذه أي على رفق وجميل والصرم القطيعة والصرم المصدر يقال صرمته أصرمه صرما مفتوح إذا قطعته ومنه سيف صارم أي قاطع\nومنه الصرام ومنه الصرائم وهي القطع من الرمل تنقطع من معظمه وقوله سلي ثيابي من ثيابك كناية أي اقطعي أمري من أمرك وقوله تنسل تبن عنها ويقال للسن إذا بانت فسقطت والنصل إذا سقط نسل ينسل وهو النسيل والنسال\nوقال قوم الثياب القلب وقوله وما ذرفت عيناك أي ما بكيت إلا لتضربي بسهميك في أعشار قلب مقتل قال الأصمعي يعني أنك ما بكيت إلا لتخرقي قلبا معشرا أي مكسرا شبهه بالبرمة إذا كانت قطعا ويقال برمة أعشار\nقال ولم أسمع للأعشار واحدا يقول لتضربي بسهميك أي بعينيك فتجعلي قلبي مخرقا فاسدا كما يخرق الجابر أعشار البرمة فالبرمة تنجبر إذا أخرقت وأصلحت والقلب لا ينجبر قال ومثله قوله\n(رمتك ابنة البكري عن فرع ضالة ... )","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":8,"spl":"اعجاب عبد الله بن الزبير بغناء ابن سريج","tags":[],"song":1,"loc":1628,"partialRef":{"sid":"b60-4","gi":0,"vi":1,"side":0},"partial":1},
{"id":"b88-14","bab":"الجزء 9","sec":"اعجاب عبد الله بن الزبير بغناء ابن سريج","page":"ج9 ص84","text":"ي نظرت إليك فأقرحت قلبك وقال غير الأصمعي وهو قول الكوفيين إنما هذا مثل أعشار الجزور وهي تنقسم على عشرة أنصباء فضربت فيها بسهميك المعلى وله سبعة أنصباء والرقيب وله ثلاثة أنصباء فأراد أنها ذهبت بقلبه كله مقتل أي مذلل يقال بعير مقتل أي مذلل وتسلت ذهبت يقال سلوت عنه وسليت إذا طابت نفسك بتركه قال رؤبة\n(لو أشرب السلوان ما سليت ... )\nالعمايات الجهالات عد الجهل عمى والصبا اللعب قال ابن السكيت صبا يصبو صبوا وصبوا وصباء وصبا انجل انكشف والأمر الجلي المنكشف وقوله أنا ابن جلا أي أنا ابن المكشوف الأمر المشهور غير المستور ومنه جلاء العروس وجلاء السيف وقوله فيك بأمثل يقول إذا جاءني الصباح وأنا فيك فليس ذلك بأمثل لأن الصبح قد يجيء والليل مظلم بعد يقول ليس الصبح بأمثل وهو فيك أي يريد أن يجيء منكشفا منجليا لا سواد فيه ولو أراد أن الصباح فيك أمثل من الليل لقال منك بأمثل ومثله قول حميد بن ثور في ذكر مجيء الصبح والليل باق\n(فلما تجلى الصبح عنها وأبصرت ... وفي غبش الليل الشخوص الأباعد)\nبش الليل بقيته هذا قول يعقوب بن السكيت وبيضة خدر شبه المرأة بالبيضة لصفائها ورقتها غير معجل أي لم يعجلني أحد عما أريده منها والخباء ما كان على عمودين أو ثلاثة والبيت ما كان على ستة أعمدة إلى تسعة والخيمة من الشعر وقوله يسرون مقتلي قال الأصمعي يسرونه وروي غيره يشرون بالشين المعجمة أي يظهرونه وقال الشاعر\n(فما برحوا حتى أتى الله نصره ... وحتى أشرت بالأكف الأصابع)\nي أظهرت وقال غيرهما لو يسرونه من الإسرار أي لو يستطيعون قتلي لأسروه من الناس وقتلوني قال أبو عبيدة دارة جلجل في الحمى وقال ابن الكلبي هي عند عين كندة ويروى سيما مخففة وسيما مشددة ويقال رب رجل ورب رجل وربت رجل ومن القراء من يقرأ ( ربما يود الذين كفروا\nمخففة وقرأ عليه رجل ربما فقال له أظنك يعجبك الرب ويروى\n(فيا عجبا من رحلها المتحمل ... )\nي يا عجبا لسفهي وشبابي يومئذ ويروى\n(وقد أغتدى والطير في وكراتها ... )\nالراء قال أبو عبيد ة والأكنات في الجبال كالتماريد في السهل والواحدة أكنة وهي الوقنات والواحدة أقنة وقد وقن يقن وقال الأصمعي إذا أوى الطير إلى وكره قيل وكر يكر ووكن يكن ويقال إنه جاءنا والطير وكن ما خرجن والمنجرد القصير الشعرة وذلك من العتق والأوابد الوحش وتأبدت توحشت وتأبد الموضع إذا توحش وقيد الأوابد يعني الفرس يقول هو قيد لها لأنها لا تفوته كأنها مقيدة والهيكل العظيم من الخيل ومن\nالشجر ومنه سمي بيت النصارى الهيكل وقال أبو عبيدة يقال قيد الأوابد وقيد الرهان وهو الذي كأن طريدته في قيد له إذا طلبها وكأن مسابقه في الرهان مقيد\nقال أبو عبيدة وأول من قيدها امرؤ القيس والمنجرد القصير الشعرة الصافي الأديم والهيكل الذكر والأنثى هيكلة والجمع هياكل وهو العظيم العبل الكثيف اللين وقوله مكر مفر يقول إذا شئت أن أكر عليه وجدته وكذلك إذا أردت أن أفر عليه أو أقبل أو أدبر والجلمود الصخرة ووصفها بأن السيل حطها من عل لأنها إذا كانت في أعلى الجبل كان أصلب لها من عل من فوق ويقال من عل ومن عل ومن علا ومن علو ومن عال ومن علو ومن معال وقوله سيري وأرخي زمامه أي هوني عليك الأمر ولا تبالي أعقر أم سلم وجناك كل شيء اجتنيته من قبلة وما أشبه ذلك هو الجنى وهو من الإنسان مثل الجنى من الشجر أي ما اجتني من ثمره والمعلل الملهي غنى في قفا نبك وأفاطم مهلا وأغرك وما ذرفت عيناك معبد لحنا من الثقيل الأول بالسبابة في مجرى الوسطى وغنى معبد أيضا في الأول والرابع من هذه الأبيات خفيف رمل بالوسطى وغنى سعيد بن جابر في الأربعة الأبيات رملا وغنت عريب في\n(أغرك مني أن حبك قاتلي ... )\nبعده شعر ليس منه وهو\n(فلا تحرجي من سفك مهجة عاشق ... بلى فاقتلي ثم اقتلي ثم فاقتلي)\n(فلا تدعي أن تفعلي ما أردته ... بنا ما أراك الله من ذاك فافعلي)\nلحنها فيها خفيف رمل وغنى ابن محرز في تسلت عمايات الرجال وبعده ألا أيها الليل الطويل ثاني ثقيل بالوسطى وغنى فيهما عبد الله بن العباس الربيعي ثاني ثقيل آخر بالسبابة في مجرى البنصر وغنت جميلة في تسلت عمايات الرجال وبعده ألا رب يوم لك لحنا من الثقيل الأول عن","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":9,"spl":"اعجاب عبد الله بن الزبير بغناء ابن سريج","tags":[],"loc":1629,"partialRef":{"sid":"b88-13","gi":1,"vi":1,"side":0},"partial":1},
{"id":"b88-15","bab":"الجزء 9","sec":"اعجاب عبد الله بن الزبير بغناء ابن سريج","page":"ج9 ص84","text":"الهشامي وغنت عزة الميلاء في تسلت عمايات الرجال وبعده ويوم عقرت للعذارى مطيتي ثقيلا أول آخر عن الهشامي وغنت حميدة جارية ابن تفاحة في وبيضة خدر وتجاوزت أحراسا لحنا من الثقيل الأول بالوسطى ولطويس في قفا نبك وبعده فتوضح فالمقراة ثقيل أول آخر وفي أفاطم مهلا وأغرك مني أن حبك قاتلي ليزيد بن الرحال هزج ولأبي عيسى بن الرشيد في وقد أغتدي ومكر مفر ثقيل أول ولفليح في قفا نبك وبعده أغرك مني رمل\nوقيل إن لمعبد في وبيضة خدر لحنا من الثقيل الأول وقيل هو لحن حميدة ولعريب في هذين البيتين خفيف ثقيل من رواية أبي العبيس وغنى سلام بن الغسال\nوقيل بل عبيدة أخوه في وإن كنت قد ساءتك مني وأغرك مني رملا بالوسطى وغنى في فقلت لها سيري وأرخي زمامه سعدويه بن نصر ثاني ثقيل وغنى في قفا نبك وبعده فتوضح فالمقراة إبراهيم الموصلي ثقيلا أول بإطلاق الوتر في مجرى الوسطى عن ابن المكي وزعم حبش أن لإسحاق فيهما ثقيلا وغنى في أغرك مني وما ذرفت ابن سريج خفيف رمل بالوسطى من رواية ابن المكي\nوقيل بل هو من منحوله وغنى بديح مولى ابن جعفر في وما ذرفت عيناك بيتا واحدا ثقيلا أول مطلقا في مجرى الوسطى عن ابن المكي فجميع ما جمع في هذه المواضع مما وجد في شعر قفا نبك من الأغاني صحيحها والمشكوك فيه منها اثنان وعشرون لحنا منها في الثقيل الأول تسعة أصوات وفي الثقيل الثاني ثلاثة أصوات وفي الرمل أربعة أصوات وفي خفيف الرمل صوتان وفي الهزج صوت وفي خفيف الثقيل ثلاثة أصوات","topic":"ذكر مسافر ونسبه","topicNo":88,"sp":10,"spl":"اعجاب عبد الله بن الزبير بغناء ابن سريج","tags":["الجواري والنساء"],"loc":1630},
{"id":"b89-1","bab":"الجزء 9","sec":"ذكر امرئ القيس ونسبه وأخباره","page":"ج9 ص93","text":"قال الأصمعي هو امرؤ القيس بن حجر بن الحارث بن عمرو بن حجر آكل المرار بن معاوية بن ثور وهو كندة وقال ابن الأعرابي هو امرؤ القيس بن حجر بن عمرو بن معاوية بن الحارث بن ثور وهو كندة\nوقال محمد بن حبيب هو امرؤ القيس بن حجر بن الحارث الملك ابن عمرو ابن حجر آكل المرار بن عمرو بن معاوية بن الحارث بن يعرب بن ثور بن مرتع بن معاوية بن كندة\nوقال بعض الرواة هو امرؤ القيس بن السمط بن امرئ القيس بن عمرو بن معاوية بن ثور وهو كندة وقالوا جميعا كندة هو كندة بن عفير بن عدي بن الحارث بن مرة بن أدد بن زيد بن يشجب بن عريب بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان بن عابر بن شالخ بن أرفحشذ بن سام بن نوح\nوقال ابن الأعرابي ثور هو كندة بن مرتع ابن عفير بن الحارث بن مرة بن عدي بن أدد بن زيد بن عمرو بن مسمع بن عريب بن عمرو بن زيد بن كهلان وأم امرئ القيس فاطمة بنت ربيعة بن الحارث بن زهير أخت كليب ومهلهل ابني ربيعة التغلبيين وقال من زعم أنه امرؤ القيس بن السمط أمه تملك بنت عمرو بن زبيد بن مذحج رهط عمرو بن معد يكرب قال من\nذكر هذا وأن أمه تملك قد ذكر ذلك امرؤ القيس في شعره فقال\n(ألا هل أتاها والحوادث جمة ... بأن امرأ القيس بن تملك بيقرا)\nيقر أي جاء العراق والحضر ويقال بيقر الرجل إذا هاجر وقال يعقوب بن السكيت أم حجر أبي امرئ القيس أم قطام بنت سلمة امرأة من عنزة","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":0,"spl":"ذكر امرئ القيس ونسبه وأخباره — الملك الضليل وذو القروح","tags":["الجواري والنساء"],"loc":1631},
{"id":"b89-2","bab":"الجزء 9","sec":"الملك الضليل وذو القروح","page":"ج9 ص94","text":"ويكنى امرؤ القيس على ما ذكره أبو عبيدة أبا الحارث وقال غيره يكنى أبا وهب وكان يقال له الملك الضليل وقيل له أيضا ذو القروح وإياه عنى الفرزدق بقوله\n(وهب القصائد لي النوابغ إذ مضوا ... وأبو يزيد وذو القروح وجرول)\nعني بأبي يزيد المخبل السعدي وجرول الحطيئة قال وولد ببلاد بني أسد وقال ابن حبيب كان ينزل المشقر من اليمامة ويقال بل كان ينزل في حصن بالبحرين وقال جميع من ذكرنا من الرواة إنما سمي كندة لأنه كند أباه أي عقه وسمي مرتع بذلك لأنه كان يجعل لمن أتاه من قومه مرتعا له ولماشيته وسمي حجر آكل المرار بذلك لأنه لما أتاه الخبر بأن الحارث بن جبلة كان نائما في حجر امرأته هند وهي\nتفليه جعل يأكل المرار وهو نبت شديد المرارة من الغيظ وهو لا يدري ويقال بل قالت هند للحارث وقد سألها ما ترين حجرا فاعلا قالت كأنك به قد أدركك في الخيل وهو كأنه بعير قد أكل المرار قال وسمي عمرو المقصور لأنه قد قصر على ملك أبيه أي أقعد فيه كرها","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":0,"spl":"ذكر امرئ القيس ونسبه وأخباره — الملك الضليل وذو القروح","tags":[],"loc":1632},
{"id":"b89-3","bab":"الجزء 9","sec":"الحارث بن عمرو وقباذ وابنه","page":"ج9 ص95","text":"أخبرني بخبره على ما قد سقته ونظمته أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة ولم يتجاوزه وروى بعضه عن علي بن الصباح عن هشام بن الكلبي وأخبرنا الحسن بن علي\nقال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن أبي سعد عن علي بن الصباح عن هشام بن الكلبي قال ابن أبي سعد وأخبرني دارم بن عقال بن حبيب الغساني أحد ولد السموءل بن عادياء عن أشياخه وأخبرنا إبراهيم بن أيوب عن ابن قتيبة\nوأخبرني محمد بن العباس اليزيدي قال حدثني عمي يوسف عن عمه إسماعيل وأضفت إلى ذلك رواية ابن الكلبي مما لم أسمعه من أحد ورواية الهيثم بن عدي ويعقوب بن السكيت والأثرم وغيرهم لما في ذلك من الاختلاف ونسبت رواية كل راو إذا خالف رواية غيره إليه قالوا كان عمرو بن حجر وهو المقصور ملكا بعد أبيه وكان أخوه معاوية وهو الجون على اليمامة وأمهما شعبة بنت أبي معاهر بن حسان بن عمرو بن تبع ولما مات ملك بعده ابنه الحارث وكان شديد الملك بعيد الصيت\nولما ملك قباذ بن فيروز خرج في أيام ملكه رجل يقال له مزدك فدعا الناس إلى الزندقة وإباحة الحرم وألا يمنع أحد منهم أخاه ما يريده من ذلك وكان المنذر بن ماء السماء يومئذ عاملا على الحيرة ونواحيها فدعاه قباذ إلى الدخول معه في ذلك فأبى فدعا الحارث بن عمرو فأجابه فشدد له ملكه وأطرد المنذر عن مملكته وغلب على ملكه وكانت أم أنو شروان بين يدي قباذ يوما فدخل عليه مزدك فلما رأى أم أنو شروان\nقال لقباذ ادفعها لي لأقضي حاجتي منها فقال دونكها فوثب إليه أنو شروان فلم يزل يسأله ويضرع إليه أن يهب له أمه حتى قبل رجله فتركها له فكانت تلك في نفسه فهلك قباذ على تلك الحال وملك أنو شروان فجلس في مجلس الملك وبلغ المنذر هلاك قباذ فأقبل إلى أنوشروان وقد علم خلافه على أبيه فيما كانوا دخلوا فيه فأذن أنوشروان للناس فدخل عليه مزدك ثم دخل عليه المنذر فقال أنوشروان إني كنت تمنيت أمنيتين أرجو أن يكون الله قد جمعهما لي فقال مزدك وما هما أيها الملك\nقال تمنيت أن أملك فأستعمل هذا الرجل الشريف يعني المنذر وأن أقتل هؤلاء الزنادقة فقال له مزدك أو تستطيع أن تقتل الناس كلهم قال إنك لها هنا يابن الزانية والله ما ذهب نتن ريح جوربك من أنفي منذ قبلت رجلك إلى يومي هذا وأمر به فقتل وصلب وأمر بقتل الزنادقة فقتل منهم ما بين جازر إلى النهروان إلى المدائن في ضحوة واحدة مائة ألف زنديق وصلبهم وسمي يومئذ أنوشروان وطلب أنوشروان الحارث بن عمرو فبلغه ذلك وهو بالأنبار وكان بها منزله\nوإنما سميت الأنبار لأنه كان يكون بها أهراء الطعام وهي الأنابير فخرج هاربا في هجائنه وماله فمر بالثوية وتبعه المنذر بالخيل من تغلب وبهراء وإياد فلحق بأرض كلب فنجا وانتهبوا ماله وهجائنه وأخذت بنو تغلب ثمانية وأربعين نفسا من بني آكل المرار فقدم بهم على المنذر فضرب رقابهم بحفر الأملاك في ديار بني مرينا العباديين بين دير هند والكوفة فذلك قول عمرو بن كلثوم\n(فآبوا بالنهاب وبالسبايا ... وأبنا بالملوك مصفدينا)\nفيهم يقول امرؤ القيس\n(ملوك من بني حجر بن عمرو ... يساقون العشية يقتلونا)\n(فلو في يوم معركة أصيبوا ... ولكن في ديار بني مرينا)\n(ولم تغسل جماجمهم بغسل ... ولكن في الدماء مرملينا)\n(تظل الطير عاكفة عليهم ... وتنتزع الحواجب والعيونا)\nقالوا ومضى الحارث فأقام بأرض كلب فكلب يزعمون أنهم قتلوه وعلماء كندة تزعم أنه خرج إلى الصيد فألظ بتيس من الظباء فأعجزه فآلى ألية ألا يأكل أولا إلا من كبده فطلبته الخيل ثلاثا فأتي بعد ثالثة وقد هلك جوعا فشوي له بطنه فتناول فلذة من كبده فأكلها حارة فمات وفي ذلك يقول الوليد بن عدي الكندي في أحد بني بجيلة\n(فشووا فكان شواؤهم خبطا له ... إن المنية لا تجل جليلا)\nزعم ابن قتيبة أن أهل اليمن يزعمون أن قباذ بن فيروز لم يملك الحارث بن عمرو وأن تبعا الأخير هو الذي ملكه قال ولما أقبل المنذر إلى الحيرة هرب الحارث وتبعته خيل فقتلت ابنه عمرا وقتلوا ابنه مالكا بهيت وصار الحارث إلىمسحلان فقتلته كلب وزعم غير ابن قتيبة أنه مكث فيهم حتى مات حتف أنفه","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":1,"spl":"الحارث بن عمرو وقباذ وابنه","tags":["الهجاء"],"loc":1633},
{"id":"b89-4","bab":"الجزء 9","sec":"الحارث بن عمرو وتمليكه أولاده على قبائل العرب","page":"ج9 ص98","text":"وقال الهيثم بن عدي حدثني حماد الراوية عن سعيد بن عمرو بن سعيد عن سعية بن عريض من يهود تيماء قال لما قتل الحارث بن أبي شمر\nالغساني عمرو بن حجر ملك بعده ابنه الحارث بن عمرو وأمه بنت عوف بن محلم بن ذهل بن شيبان ونزل الحيرة فلما تفاسدت القبائل من نزار أتاه اشرافهم فقالوا إنا في دينك ونحن نخاف أن نتفانى فيما يحدث بيننا فوجه معنا بنيك ينزلون فينا فيكفون بعضنا عن بعض ففرق ولده في قبائل العرب فملك ابنه حجرا على بني أسد وغطفان وملك ابنه شرحبيل قتيل يوم الكلاب على بكر بن وائل بأسرها وبني حنظلة بن مالك بن زيد مناة بن تميم والرباب وملك ابنه معد يكرب وهو غلفاء سمي بذلك لأنه كان يغلف رأسه على بني تغلب والنمر بن قاسط وسعد بن زيد مناة وطوائف من بني دارم بن مالك بن حنظلة والصنائع وهم بنو رقية قوم كانوا يكونون مع الملوك من شذاذ العرب وملك ابنه عبد الله على عبد القيس وملك ابنه سلمة على قيس","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":2,"spl":"الحارث بن عمرو وتمليكه أولاده على قبائل العرب","tags":["الجواري والنساء","الرواية والكتابة"],"loc":1634},
{"id":"b89-5","bab":"الجزء 9","sec":"مقتل حجر","page":"ج9 ص100","text":"وقال ابن الكلبي حدثني أبي أن حجرا كان في بني أسد وكانت له عليهم إتاوة في كل سنة مؤقتة فغبر ذلك دهرا ثم بعث إليهم جابيه الذي كان يجبيهم فمنعوه ذلك وحجر يومئذ بتهامة وضربوا رسله وضرجوهم ضرجا شديدا قبيحا فبلغ ذلك حجرا فسار إليهم بجند من ربيعة وجند من جند أخيه من قيس وكنانة فأتاهم وأخذ سراتهم فجعل يقتلهم بالعصا فسموا عبيد العصا وأباح الأموال وصيرهم إلى تهامة وآلى بالله ألا يساكنوهم في بلد أبدا وحبس منهم عمرو بن مسعود بن كندة بن فزارة الأسدي وكان سيدا وعبيد بن الأبرص الشاعر فسارت بنو أسد ثلاثا ثم إن عبيد بن الأبرص قام فقال أيها الملك اسمع مقالتي\n(يا عين فابكي ما بنى ... أسد فهم أهل الندامة)\n(أهل القباب الحمر والنعم ... المؤبل والندامة)\n(وذوي الجياد الجرد ... والأسل المثقفة المقامه)\n(حلا أبيت اللعن حلا ... إن فيما قلت آمه)\n(في كل واد بين يثرب ... فالقصور إلى اليمامة)\n(تطريب عان أو صياح ... محرق أو صوت هامه)\n(ومنعتهم نجدا فقد ... حلوا على وجل تهامه)\n(برمت بنو أسد كما ... برمت ببيضتها الحمامة)\n(جعلت لها عودين من ... نشم وآخر من ثمامه)\n(إما تركت تركت عفوا ... أو قتلت فلا ملامه)\n(أنت المليك عليهم ... وهم العبيد إلى القيامه)\n(ذلوا لسوطك مثل ما ... ذل الأشيقر ذو الخزامه)\nال فرق لهم حجر حين سمع قوله فبعث في أثرهم فأقبلوا حتى إذا كانوا على مسيرة يوم من تهامة تكهن كاهنهم وهو عوف بن ربيعة بن سوادة بن سعد بن مالك بن ثعلبة بن دودان بن أسد بن خزيمة فقال لبني أسد يا عبادي قالوا لبيك ربنا\nقال من الملك الأصهب الغلاب غير المغلب في الإبل كأنها الربرب لا يعلق رأسه الصخب هذا دمه ينثعب وهذا غدا أول من يسلب قالوا من هو يا ربنا\nقال لولا أن تجيش نفس جاشية لأخبرتكم أنه حجر ضاحية فركبوا كل صعب وذلول فما أشرق لهم النهار حتى أتوا على عسكر حجر فهجموا على قبته وكان حجابه من بني الحارث ابن سعد يقال لهم بنو خدان بن خنثر منهم معاوية بن الحارث وشبيب ورقية\nومالك وحبيب وكان حجر قد أعتق أباهم من القتل فلما نظروا إلى القوم يريدون قتله خيموا عليه ليمنعوه ويجيروه فأقبل عليهم علباء بن الحارث الكاهلي وكان حجر قد قتل أباه فطعنه من خللهم فأصاب نساه فقتله فلما قتلوه قالت بنو أسد يا معشر كنانة وقيس أنتم إخواننا وبنو عمنا والرجل بعيد النسب منا ومنكم وقد رأيتم ما كان يصنع بكم هو وقومه فانتهبوهم فشدوا على هجائنه فمزقوها ولفوه في ريطة بيضاء وطرحوه على ظهر الطريق فلما رأته قيس وكنانة انتهبوا أسلابه ووثب عمرو بن مسعود فضم عياله\nوقال أنا لهم جار قال ابن الكلبي وعدة قبائل من بني أسد يدعون قتل حجر ويقولون إن علباء كان الساعي في قتله وصاحب المشورة ولم يقتله هو\nقال ابن حبيب خدان في بني أسد وخدان في بني تميم وفي بني جديلة بالخاء مفتوحة وخدان مضمومة في الأزد وليس في العرب غير هؤلاء قال أبو عمرو الشيباني بل كان حجر لما خاف من بني أسد استجار عوير بن شجنة أحد بني عطارد بن كعب بن سعد بن زيد مناة بن تميم لبنته هند بنت حجر وعياله\nوقال لبني أسد لما كثروه أما إذا كان هذا شأنكم فإني مرتحل عنكم ومخليكم وشأنكم فواعدوه على ذلك ومال على خالد بن خدان أحد بني سعد بن ثعلبة فأدركه علباء بن الحارث أحد بني كاهل فقال يا خالد اقتل صاحبك لا يفلت فيعرك وإيانا بشر فامتنع خالد ومر علباء بقصدة رمح مكسورة فيها سنانها فطعن بها في خاصرة حجر وهو غافل فقتله ففي ذلك يقول الأسدي\n(وقصدة علباء بن قيس بن كاهل ... منية حجر في جوار ابن خدان)\nذكر الهيثم بن عدي أن حجرا لما استجار عوير بن شجنة لبنيه وقطينه تحول عنهم فأقام في قومه مدة وجمع لبني أسد جمعا عظيما من قومه وأقبل مدلا بمن معه من الجنود فتآمرت بنو أسد بينها وقالوا والله لئن قهركم هذا ليحكمن عليكم حكم الصبي فما خير عيش يكون بعد قهر وأنتم بحمد الله أشد العرب فموتوا كراما فساروا إلى حجر وقد ارتحل نحوهم فلقوه فاقتتلوا قتالا شديدا وكان صاحب أمرهم علباء بن الحارث فحمل على حجر فطعنه فقتله وانهزمت كندة وفيهم يومئذ امرؤ القيس فهرب على فرس له شقراء وأعجزهم وأسروا من أهل بيته رجالا وقتلوا وملؤوا أيديهم من الغنائم وأخذوا جواري حجر ونساءه وما كان معه من شيء فاقتسموه بينهم","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":3,"spl":"مقتل حجر","tags":["الهجاء"],"loc":1635},
{"id":"b89-6","bab":"الجزء 9","sec":"مقتل حجر","page":"ج9 ص100","text":"وقال يعقوب بن السكيت حدثني خالد الكلابي قال كان سبب قتل حجر أنه كان وفد إلى أبيه الحارث بن عمرو في مرضه الذي مات فيه وأقام عنده حتى هلك ثم أقبل راجعا إلى بني أسد وقد كان أغار عليهم في النساء وأساء ولايتهم وكان يقدم بعض ثقله أمامه ويهيأ نزله ثم يجيء وقد هيء له من ذلك ما يعجبه فينزل ويقدم مثل ذلك إلى ما بين يديه من المنازل فيضرب له في المنزلة الأخرى فلما دنا من بلاد بني أسد وقد بلغهم موت أبيه طمعوا فيه فلما أظلهم وضربت قبابه اجتمعت بنو أسد إلى نوفل بن ربيعة بن خدان فقال يا بني أسد من يتلقى هذا الرجل منكم فيقتطعه فإني قد أجمعت على الفتك به فقال له القوم ما لذلك أحد غيرك فخرج نوفل في خيله حتى أغار على الثقل فقتل من وجد فيه وساق الثقل وأصاب جاريتين قينتين لحجر ثم أقبل حتى أتى قومه فلما رأوا ما قد حدث وأتاهم\nبه عرفوا أن حجرا يقاتلهم وأنه لا بد من القتال فحشد الناس لذلك وبلغ حجرا أمرهم فأقبل نحوهم فلما غشيهم ناهضوه القتال وهم بين أبرقين من الرمل في بلادهم يدعيان اليوم أبرقي حجر فلم يلبثوا حجرا أن هزموا أصحابه وأسروه فحبسوه وتشاور القوم في قتله فقال لهم كاهن من كهنتهم بعد أن حبسوه ليروا فيه رأيهم أي قوم لا تعجلوا بقتل الرجل حتى أزجر لكم فانصرف عن القوم لينظر لهم في قتله فلما رأى ذلك علباء خشي أن يتواكلوا في قتله فدعا غلاما من بني كاهل وكان ابن أخته وكان حجر قتل أباه زوج أخت علباء فقال يا بني أعندك خير فتثأر بأبيك وتنال شرف الدهر وإن قومك لن يقتلوك فلم يزل بالغلام حتى حربه ودفع اليه حديدة وقد شحذها\nوقال ادخل عليه مع قومك ثم اطعنه في مقتله فعمد الغلام إلى الحديدة فخبأها ثم دخل على حجر في قبته التي حبس فيها فلما رأى الغلام غفلة وثب عليه فقتله فوثب القوم على الغلام فقالت بنو كاهل ثأرنا وفي أيدينا فقال الغلام إنما ثأرت بأبي فخلوا عنه وأقبل كاهنهم المزدجر فقال أي قوم قتلتموه ملك شهر وذل دهر أما والله لا تحظون عند الملوك بعده أبدا\nقال ابن السكيت ولما طعن الأسدي حجرا ولم يجهز عليه أوصى ودفع كتابه إلى رجل وقال له انطلق إلى ابني نافع وكان أكبر ولده فإن بكى وجزع فاله عنه واستقرهم واحدا واحدا حتى تأتي امرأ القيس وكان أصغرهم فأيهم لم يجزع فادفع إليه سلاحي وخيلي وقدوري ووصيتي وقد كان بين في وصيته من قتله وكيف كان خبره فانطلق الرجل بوصيته إلى نافع\nابنه فأخذ التراب فوضعه على رأسه ثم استقراهم واحدا واحدا فكلهم فعل ذلك حتى أتى امرأ القيس فوجده مع نديم له يشرب الخمر ويلاعبه بالنرد فقال له قتل حجر فلم يلتفت إلى قوله وأمسك نديمه فقال له امرؤ القيس اضرب فضرب حتى إذا فرغ قال ما كنت لأفسد عليك دستك ثم سأل الرسول عن أمر أبيه كله فأخبره فقال الخمر علي والنساء حرام حتى أقتل من بني أسد مائة وأجز نواصي مائة وفي ذلك يقول\n(أرقت ولم يأرق لما بي نافع ... وهاج لي الشوق الهموم الروادع)\nقال ابن الكلبي حدثني أبي عن ابن الكاهن الأسدي أن حجرا كان طرد امرأ القيس وآلى ألا يقيم معه أنفة من قوله الشعر وكانت الملوك تأنف من ذلك فكان يسير في أحياء العرب ومعه أخلاط من شذاذ العرب من طيئ وكلب وبكر بن وائل فإذا صادف غديرا أو روضة أو موضع صيد أقام فذبح لمن معه في كل يوم وخرج إلى الصيد فتصيد ثم عاد فأكل وأكلوا معه وشرب الخمر وسقاهم وغنته قيانه ولا يزال كذلك حتى ينفد ماء ذلك الغدير ثم ينتقل عنه إلى غيره فأتاه خبر أبيه ومقتله وهو بدمون من أرض اليمن أتاه به رجل من بني عجل يقال له عامر الأعور أخو الوصاف فلما أتاه بذلك قال\n(تطاول الليل على دمون ... دمون إنا معشر يمانون)\n(وإننا لأهلها محبون ... )\nم قال ضيعني صغيرا وحملني دمه كبيرا لا صحو اليوم ولا سكر غدا اليوم خمر وغدا أمر فذهبت مثلا ثم قال\n(خليلي لا في اليوم مصحى لشارب ... ولا في غد إذ ذاك ما كان يشرب)\nم شرب سبعا فلما صحا آلى ألا يأكل لحما ولا يشرب خمرا ولا يدهن بدهن ولا يصيب امرأة ولا يغسل رأسه من جنابة حتى يدرك بثأره فلما جنه الليل رأى برقا فقال\n(أرقت لبرق بليل أهل ... يضيء سناه بأعلى الجبل)\n(أتاني حديث فكذبته ... بأمر تزعزع منه القلل)\n(بقتل بني أسد ربهم ... ألا كل شيء سواه جلل)\n(فأين ربيعة عن ربها ... وأين تميم وأين الخول)","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":4,"spl":"مقتل حجر","tags":["الجواري والنساء"],"loc":1636,"partial":1},
{"id":"b89-7","bab":"الجزء 9","sec":"مقتل حجر","page":"ج9 ص100","text":"(ألا يحضرون لدى بابه ... كما يحضرون إذا ما أكل)\nروى الهيثم عن أصحابه أن امرأ القيس لما قتل أبوه كان غلاما قد ترعرع وكان في بني حنظلة مقيما لأن ظئره كانت امرأة منهم فلما بلغه ذلك قال\n(يا لهف هند إذ خطئن كاهلا ... القاتلين الملك الحلاحلا)\n(تالله لا يذهب شيخي باطلا ... ياخير شيخ حسبا ونائلا)\n(وخيرهم قد علموا فواضلا ... يحملننا والأسل النواهلا)\n(وحي صعب والوشيج الذابلا ... مستثفرات بالحصى جوافلا)\nيعني صعب بن علي بن بكر بن وائل معنى قوله مستثفرات بالحصى يريد أنها أثارت الحصى بحوافرها لشدة جريها حتى ارتفع إلى أثفارها فكأنها استثفرت به","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":5,"spl":"مقتل حجر — امرؤ القيس في ديار بكر وتغلب","tags":["الجواري والنساء","الرواية والكتابة"],"loc":1637},
{"id":"b89-8","bab":"الجزء 9","sec":"خبر هند بنت حجر مع عوير بن شجنة","page":"ج9 ص107","text":"وقال الهيثم بن عدي لما قتل حجر انحازت بنته وقطينه إلى عوير بن شجنة فقال له قومه كل أموالهم فإنهم مأكولون فأبى فلما كان الليل حمل هندا وقطينها وأخذ بخطام جملها وأشأم بهم في ليلة طخياء مدلهمة فلما أضاء البرق أبدى عن ساقيه وكانتا حمشتين فقالت هند ما رأيت كالليلة ساقي واف فسمعها فقال يا هند هما ساقا غادر شر فرمى بها النجاد حتى أطلعها نجران وقال لها إني لست أغني عنك شيئا وراء هذا الموضع وهؤلاء قومك وقد برئت خفارتي فمدحه امرؤ القيس بعدة قصائد منها قوله في قصيدة له\n(ألا إن قوما كنتم أمس دونهم ... هم منعوا جاراتكم آل غدران)\n(عوير ومن مثل العوير ورهطه ... أبر بميثاق وأوفى بجيران)\n(هم أبلغوا الحي المضيع أهله ... وساروا بهم بين الفرات ونجران)\nقوله\n(ألا قبح الله البراجم كلها ... وجدع يربوعا وعفر دارما)\n(فما فعلوا فعل العوير ورهطه ... لدى باب حجر إذ تجرد قائما)\nوقال ابن قتيبة في خبره إن القصة المذكورة عن عوير كانت مع أبي حنبل وجارية بن مر قال ويقال بل كانت مع عامر بن جوين الطائي وإن ابنته أشارت عليه بأخذ مال حجر وعياله فقام ودخل الوادي ثم صاح ألا إن عامر بن جوين غدر فأجابه الصدى مثل قوله فقال ما أقبح هذا من قول ثم صاح ألا إن عامر بن جوين وفى فأجابه الصدى بمثل قوله فقال ما أحسن هذا ثم دعا ابنته بجذعة من غنم فاحتلبها وشرب واستلقى على قفاه\nوقال والله لا أغدر ما أجزأتني جذعة ثم نهض وكانت ساقاه حمشتين فقالت ابنته والله ما رأيت كاليوم ساقي واف فقال وكيف بهما إذا كانتا ساقي غادر هما والله حينئذ أقبح","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":5,"spl":"مقتل حجر — امرؤ القيس في ديار بكر وتغلب","tags":["المديح"],"loc":1638},
{"id":"b89-9","bab":"الجزء 9","sec":"امرؤ القيس في ديار بكر وتغلب","page":"ج9 ص108","text":"وقال ابن الكلبي عن أبيه ويعقوب بن السكيت عن خالد الكلابي إن امرأ القيس ارتحل حتى نزل بكرا وتغلب فسألهم النصر على بني أسد فبعث العيون على بني أسد فنذروا بالعيون ولجؤوا إلى بني كنانة وكان الذي أنذرهم بهم علباء بن الحارث فلما كان الليل\nقال لهم علباء يا معشر بني أسد تعلمون والله إن عيون امرئ القيس قد أتتكم ورجعت إليه بخبركم فارحلوا بليل ولا تعلموا بني كنانة ففعلوا واقبل امرؤ القيس بمن معه من بكر وتغلب حتى انتهى إلى بني كنانة وهو يحسبهم بني أسد فوضع السلاح فيهم وقال يا لثارات الملك يا لثارات الهمام فخرجت إليه عجوز من بني كنانة فقالت أبيت اللعن لسنا لك بثأر نحن من كنانة فدونك\nثأرك فاطلبهم فإن القوم قد ساروا بالأمس فتبع بني أسد ففاتوه ليلتهم تلك فقال في ذلك\n(ألا يا لهف هند إثر قوم ... هم كانوا الشفاء فلم يصابوا)\n(وقاهم جدهم ببني أبيهم ... وبالأشقين ما كان العقاب)\n(وأفلتهن علباء جريضا ... ولو أدركنه صفر الوطاب)\nعني ببني أبيهم بني كنانة لأن أسدا وكنانة ابني خزيمة أخوان أخبرني أبو خليفة عن محمد بن سلام قال سمعت رجلا سأل يونس عن قوله صفر الوطاب فقال سألنا رؤبة عنه فقال لو أدركوه قتلوه وساقوا إبله فصفرت وطابه من اللبن\nوقال غيره صفر الوطاب أي إنه كان يقتل فيكون جسمه صفرا من دمه كما يكون الوطاب صفرا من اللبن وأدركهم ظهرا وقد تقطعت خيله وقطع أعناقهم العطش وبنو أسد جامون على الماء فنهد إليهم فقاتلهم حتى كثرت الجرحى والقتلى فيهم وحجز الليل بينهم وهربت بنو أسد فلما أصبحت بكر وتغلب أبوا أن يتبعوهم وقالوا له قد أصبت ثأرك\nقال والله ما فعلت ولا أصبت من بني كاهل ولا من غيرهم من بني أسد أحدا قالوا بلى ولكنك رجل مشؤوم وكرهوا قتالهم بني كنانة وانصرفوا عنه ومضى هاربا لوجهه حتى لحق بحمير","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":5,"spl":"مقتل حجر — امرؤ القيس في ديار بكر وتغلب","tags":["السفر والحج","الوصف والطبيعة"],"loc":1639},
{"id":"b89-10","bab":"الجزء 9","sec":"امرؤ القيس يستنجد بالقبائل واسيادها","page":"ج9 ص110","text":"وقال ابن السكيت حدثني خالد الكلابي أن امرأ القيس لما أقبل من الحرب على فرسه الشقراء لجأ إلى ابن عمته عمرو بن المنذر وأمه هند بنت عمرو بن حجر بن آكل المرار وذلك بعد قتل أبيه وأعمامه وتفرق ملك أهل بيته وكان عمرو يومئذ خليفة لأبيه المنذر ببقة وهي بين الأنبار وهيت فمدحه\nوذكر صهره ورحمه وأنه قد تعلق بحباله ولجأ إليه فأجاره ومكث عنده زمانا ثم بلغ المنذر مكانه عنده فطلبه وأنذره عمرو فهرب حتى أتى حمير\nوقال ابن الكلبي والهيثم بن عدي وعمر بن شبة وابن قتيبة فلما امتنعت بكر بن وائل وتغلب من اتباع بني أسد خرج من فوره ذلك إلى اليمن فاستنصر أزدشنوءة فأبوا أن ينصروه وقالوا إخواننا وجيراننا فنزل بقيل يدعى مرثد الخير بن ذي جدن الحميري وكانت بينهما قرابة فاستنصره واستمده على بني أسد فأمده بخمسمائة رجل من حمير ومات مرثد قبل رحيل امرئ القيس بهم وقام بالمملكة بعده رجل من حمير يقال له قرمل بن الحميم وكانت أمه سوداء فردد امرأ القيس وطول عليه حتى هم بالانصراف وقال\n(وإذ نحن ندعو مرثد الخير ربنا ... وإذ نحن لا ندعى عبيدا لقرمل)\nأنفذ له ذلك الجيش وتبعه شذاذ من العرب واستأجر من قبائل\nالعرب رجالا فسار بهم إلى بني أسد ومر بتبالة وبها صنم للعرب تعظمه يقال له ذو الخلصة فاستقسم عنده بقداحه وهي ثلاثة الآمر والناهي والمتربص فأجالها فخرج الناهي ثم أجالها فخرج الناهي ثم أجالها فخرج الناهي فجمعها وكسرها وضرب بها وجه الصنم\nوقال مصصت بظر أمك لو أبوك قتل ما عقتني ثم خرج فظفر ببني أسد ويقال إنه ما استقسم عند ذي الخلصة بعد ذلك بقدح حتى جاء أمر الله بالإسلام وهدمه جرير بن عبد الله البجلي قالوا وألح المنذر في طلب امرئ القيس ووجه الجيوش في طلبه من إياد وبهراء وتنوخ ولم تكن لهم طاقة وأمده أنوشروان بجيش من الأساورة فسرحهم في طلبه وتفرقت حمير ومن كان معه عنه فنجا عصبة من بني آكل\nالمرار حتى نزل بالحارث بن شهاب من بني يربوع بن حنظلة ومع امرئ القيس أدراع خمسة الفضفاضة والضافية والمحصنة والخربق وأم الذيول كن لبني آكل المرار يتوارثونها ملكا عن ملك فقلما لبثوا عند الحارث بن شهاب حتى بعث إليه المنذر مائة من أصحابه يوعده بالحرب إن لم يسلم إليه بني آكل المرار فأسلمهم ونجا امرؤ القيس ومعه يزيد بن معاوية بن الحارث وبنته هند بنت امرئ القيس والأدرع والسلاح ومال كان بقي معه فخرج على وجهه حتى وقع في أرض طيئ\nوقيل بل نزل قبلهم على سعد بن الضباب الإيادي سيد قومه فأجاره قال ابن الكلبي وكانت أم سعد بن الضباب تحت حجر أبي امرئ القيس فطلقها وكانت حاملا وهو لا يعرف فتزوجها الضباب فولدت سعدا على فراشه فلحق نسبه به فقال امرؤ القيس يذكر ذلك\n(يفاكهنا سعد وينعم بالنا ... ويغدو علينا بالجفان وبالجزر)\n(ونعرف فيه من أبيه شمائلا ... ومن خاله ومن يزيد ومن حجر)\n(سماحة ذا وبر ذا ووفاء ذا ... ونائل ذا إذا صحا وإذا سكر)\nم تحول عنه فوقع في أرض طيئ فنزل برجل من بني جديلة يقال له المعلى بن تيم ففي ذلك يقول\n(كأني إذ نزلت على المعلى ... نزلت على البواذخ من شمام)\n(فما ملك العراق على المعلى ... بمقتدر ولا ملك الشآم)\n(اقر حشى امرىء القيس بن حجر ... بنو تيم مصابيح الظلام)\nالوا فلبث عنده واتخذ إبلا هناك فغدا قوم من بني جديلة يقال لهم بنو زيد فطردوا الإبل وكانت لامرئ القيس رواحل مقيدة عند البيوت خوفا من أن يدهمه أمر ليسبق عليهن فخرج حينئذ فنزل ببني نبهان من طيئ فخرج نفر منهم فركبوا الرواحل ليطلبوا له الإبل فأخذتهن جديلة فرجعوا إليه بلا شيء فقال في ذلك\n(وأعجبني مشي الحزقة خالد ... كمشي أتان حلئت بالمناهل)\n(فدع عنك نهبا صيح في حجراته ... ولكن حديثا ما حديث الرواحل)\nفرقت عليه بنو نبهان فرقا من معزى يحلبها فأنشأ يقول\n(إذا ما لم تجد إبلا فمعزى ... كأن قرون جلتها العصي)\n(إذا ما قام حالبها أرنت ... كأن القوم صبحهم نعي)\n(فتملأ بيتنا أقطا وسمنا ... وحسبك من غنى شبع وري)\nكان عندهم ما شاء الله ثم خرج فنزل بعامر بن جوين واتخذ عنده إبلا وعامر يومئذ أحد الخلعاء الفتاك قد تبرأ قومه من جرائره فكان عنده ما شاء الله ثم هم أن يغلبه على أهله وماله ففطن امرؤ القيس بشعر كان عامر ينطق به وهو قوله\n(فكم بالصعيد من هجان مؤبله ... تسير صحاحا ذات قيد ومرسله)","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":6,"spl":"امرؤ القيس يستنجد بالقبائل واسيادها","tags":["الهجاء"],"loc":1640},
{"id":"b89-11","bab":"الجزء 9","sec":"امرؤ القيس يستنجد بالقبائل واسيادها","page":"ج9 ص110","text":"(أردت بها فتكا فلم أرتمض له ... ونهنهت نفسي بعدما كدت أفعله)\nكان عامر أيضا يقول يعرض بهند بنت امرئ القيس\n(ألا حي هندا وأطلالها ... وتظعان هند وتحلالها)\n(هممت بنفسي كل الهموم ... فأولى لنفسي أولى لها)\n(سأحمل نفسي على آلة ... فإما عليها وإما لها)\nكذا روى ابن أبي سعد عن دارم بن عقال ومن الناس من يروي هذه الأبيات للخنساء في قصيدتها\n(ألا ما لعيني ألا ما لها ... لقد أخضل الدمع سربالها)\nالوا فلما عرف امرؤ القيس ذلك منه وخافه على أهله وماله تغفله وانتقل إلى رجل من بني ثعل يقال له حارثة بن مر فاستجار به فوقعت\nالحرب بين عامر وبين الثعلي فكانت في ذلك أمور كثيرة","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":7,"spl":"امرؤ القيس يستنجد بالقبائل واسيادها — عمرو بن جابر يدل امرأ القيس على السموءل","tags":["الجواري والنساء","الرواية والكتابة"],"loc":1641},
{"id":"b89-12","bab":"الجزء 9","sec":"عمرو بن جابر يدل امرأ القيس على السموءل","page":"ج9 ص115","text":"قال دارم بن عقال في خبره فلما وقعت الحرب بين طيئ من أجله خرج من عندهم فنزل برجل من بني فزارة يقال له عمرو بن جابر بن مازن فطلب منه الجوار حتى يرى ذات عيبه فقال له الفزاري يابن حجر إني أراك في خلل من قومك وأنا أنفس بمثلك من أهل الشرف وقد كدت بالأمس تؤكل في دار طيئ وأهل البادية أهل بر لا أهل حصون تمنعهم وبينك وبين أهل اليمن ذؤبان من قيس أفلا أدلك على بلد فقد جئت قيصر وجئت النعمان فلم أر لضيف نازل ولا لمجتد مثله ولا مثل صاحبه\nقال من هو وأين منزله قال السموءل بتيماء وسوف أضرب لك مثله هو يمنع ضعفك حتى ترى ذات عيبك وهو في حصن حصين وحسب كبير فقال له امرؤ القيس وكيف لي به\nقال أوصلك إلى من يوصلك إليه فصحبه إلى رجل من بني فزارة يقال له الربيع بن ضبع الفزاري ممن يأتي السموءل فيحمله ويعطيه فلما صار إليه قال له الفزاري إن السموءل يعجبه الشعر فتعال نتناشد له أشعارا فقال امرؤ القيس قل حتى أقول فقال الربيع\n(قل للمنية أي حين نلتقي ... بفناء بيتك في الحضيض المزلق)\nوهي طويلة يقول فيها\n(ولقد أتيت بني المصاص مفاخرا ... وإلى السموءل زرته بالأبلق)\n(فأتيت أفضل من تحمل حاجة ... إن جئته في غارم أو مرهق)\n(عرفت له الأقوام كل فضيلة ... وحوى المكارم سابقا لم يسبق)\nال فقال امرؤ القيس\n(طرقتك هند بعد طول تجنب ... وهنا ولم تك قبل ذلك تطرق)\nهي قصيدة طويلة وأظنها منحولة لأنها لا تشاكل كلام امرئ القيس والتوليد فيها بين وما دونها في ديوانه أحد من الثقات وأحسبها مما صنعه دارم لأنه من ولد السموءل ومما صنعه من\nروى عنه من ذلك فلم تكتب هنا قال فوفد الفزاري بامرئ القيس إليه فلما كانوا ببعض الطريق إذا هم ببقرة وحشية مرمية فلما نظر إليها أصحابه قاموا فذكوها فبينما هم كذلك إذا هم بقوم قناصين من بني ثعل فقالوا لهم من أنتم فانتسبوا لهم وإذا هم من جيران السموءل فانصرفوا جميعا وقال امرؤ القيس\n(رب رام من بني ثعل ... مخرج كفيه من قتره)\n(عارض زوراء من نشم ... مع باناة على وتره)\nهكذا في رواية ابن دارم ويروى غير باناة وتحت باناة\n(إذ أتته الوحش واردة ... فتثنى النزع في يسره)\n(فرماها في فرائصها ... بإزاء الحوض أو عقره)\n(برهيش من كنانته ... كتلظي الجمر في شرره)\n(راشه من ريش ناهضة ... ثم أمهاه على حجره)\n(فهو لا تنمي رميته ... ما له لا عد من نفره)\nال ثم مضى القوم حتى قدموا على السموءل فأنشده الشعر وعرف لهم حقهم فأنزل المرأة في قبة أدم وأنزل القوم في مجلس له براح فكان عنده ما شاء الله ثم إنه طلب إليه أن يكتب له إلى الحارث بن أبي شمر الغساني بالشأم ليوصله إلى قيصر فاستنجد له رجلا واستودع عنده المرأة والأدراع والمال وأقام معها يزيد بن معاوية بن الحارث ابن عمه فمضى حتى انتهى إلى قيصر فقبله وأكرمه وكانت له عنده منزلة فاندس رجل من\nبني أسد يقال له الطماح وكان امرؤ القيس قد قتل أخا له من بني أسد حتى أتى إلى بلاد الروم فأقام مستخفيا ثم إن قيصر ضم إليه جيشا كثيفا وفيهم جماعة من أبناء الملوك فلما فصل قال لقيصر قوم من أصحابه إن العرب قوم غدر ولا تأمن أن يظفر بما يريد ثم يغزوك بمن بعثت معه","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":7,"spl":"امرؤ القيس يستنجد بالقبائل واسيادها — عمرو بن جابر يدل امرأ القيس على السموءل","tags":[],"loc":1642},
{"id":"b89-13","bab":"الجزء 9","sec":"قصة الحلة المسمومة وموت امرئ القيس","page":"ج9 ص118","text":"وقال ابن الكلبي بل قال له الطماح إن امرأ القيس غوي عاهر وإنه لما انصرف عنك بالجيش ذكر أنه كان يراسل ابنتك ويواصلها وهو قائل في ذلك أشعارا يشهرها بها في العرب فيفضحها ويفضحك فبعث إليه حينئذ بحلة وشي مسمومة منسوجة بالذهب\nوقال له إني أرسلت إليك بحلتي التي كنت ألبسها تكرمة لك فإذا وصلت إليك فالبسها باليمن والبركة واكتب إلي بخبرك من منزل منزل فلما وصلت إليه لبسها واشتد سروره بها فأسرع فيه السم وسقط جلده فلذلك سمي ذا القروح وقال في ذلك\n(لقد طمح الطماح من بعد أرضه ... ليلبسني مما يلبس أبؤسا)\n(فلو أنها نفس تموت سوية ... ولكنها نفس تساقط أنفسا)\nال فلما صار إلى بلدة من بلاد الروم تدعى أنقرة احتضر بها فقال\n(رب خطبة مسحنفره ... وطعنة مثعنجره)\n(وجفنة متحيرة ... حلت بأرض أنقره)\nرأى قبر امرأة من أبناء الملوك ماتت هناك فدفنت في سفح جبل يقال له عسيب فسأل عنها فأخبر بقصتها فقال\n(أجارتنا إن المزار قريب ... وإني مقيم ما أقام عسيب)\n(أجارتنا إنا غريبان هاهنا ... وكل غريب للغريب نسيب)\nم مات فدفن إلى جنب المرأة فقبره هناك أخبرني محمد بن القاسم عن مجالد بن سعيد عن عبد الملك بن عمير قال قدم علينا عمر بن هبيرة الكوفة فأرسل إلى عشرة أنا أحدهم من وجوه الكوفة فسمروا عنده ثم قال ليحدثني كل رجل منكم أحدوثة وابدأ أنت يا أبا عمر فقلت أصلح الله الأمير أحديث الحق أم حديث الباطل قال بل حديث الحق قلت إن امرأ القيس آلى بألية ألا يتزوج امرأة حتى يسألها عن ثمانية وأربعة وثنتين فجعل يخطب النساء فإذا سألهن\nعن هذا قلن أربعة عشر فبينما هو يسير في جوف الليل إذا هو برجل يحمل ابنة له صغيرة كأنها البدر ليلة تمامه فأعجبته فقال لها يا جارية ما ثمانية وأربعة واثنتان فقالت أما ثمانية فأطباء الكلبة وأما أربعة فأخلاف الناقة وأما اثنتان فثديا المرأة فخطبها إلى أبيها فزوجه إياها وشرطت هي عليه أن تسأله ليلة بنائها عن ثلاث خصال فجعل لها ذلك وأن يسوق إليها مائة من الإبل وعشرة أعبد وعشر وصائف وثلاثة أفراس ففعل ذلك ثم إنه بعث عبدا له إلى المرأة وأهدى إليها نحيا من سمن ونحيا من عسل وحلة من عصب فنزل العبد ببعض المياه فنشر الحلة ولبسها فتعلقت بعشرة فانشقت وفتح النحيين فطعم أهل الماء منهما فنقصا ثم قدم على حي المرأة وهم خلوف فسألها عن أبيها وأمها وأخيها ودفع إليها هديتها فقالت له أعلم مولاك أن أبي ذهب يقرب بعيدا ويبعد قريبا وأن أمي ذهبت تشق النفس نفسين وأن أخي يراعي الشمس وأن سماءكم انشقت وأن وعاءيكم نضبا فقدم الغلام على مولاه فأخبره فقال أما قولها إن أبي ذهب يقرب بعيدا ويبعد قريبا فإن أباها ذهب يحالف قوما على قومه وأما قولها ذهبت أمي تشق النفس نفسين فإن أمها ذهبت تقبل امرأة نفساء وأما قولها إن أخي يراعي الشمس فإن أخاها في سرح له يرعاه فهو ينتظر وجوب الشمس ليروح به وأما قولها إن سماءكم انشقت فإن البرد الذي بعثت به انشق وأما قولها إن وعاءيكم نضبا فإن النحيين اللذين بعثت بهما نقصا\nفاصدقني فقال يا مولاي إني نزلت بماء من مياه العرب فسألوني عن نسبي فأخبرتهم أني ابن عمك ونشرت الحلة فانشقت وفتحت النحيين فأطعمت منهما أهل الماء فقال أولى لك ثم ساق مائة من الإبل وخرج نحوها ومعه الغلام فنزلا منزلا فخرج الغلام يسقي الإبل فعجز فأعانه امرؤ القيس فرمى به الغلام في البئر وخرج حتى أتى المرأة بالإبل وأخبرهم أنه زوجها فقيل لها قد جاء زوجك فقالت والله ما أدري أزوجي هو أم لا ولكن انحروا له جزورا وأطعموه من كرشها وذنبها ففعلوا فقالت اسقوه لبنا حازرا وهو الحامض فسقوه فشرب فقالت افرشوا له عند الفرث والدم ففرشوا له فنام فلما أصبحت أرسلت إليه إني أريد أن أسألك فقال سلي عما شئت فقالت مم تختلج شفتاك\nقال لتقبيلي إياك قالت فمم يختلج كشحاك قال لالتزامي إياك قالت فمم يختلج فخذاك قال لتوركي إياك قالت عليكم العبد فشدوا أيديكم به ففعلوا","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":8,"spl":"قصة الحلة المسمومة وموت امرئ القيس","tags":["الجواري والنساء","اللهو والمزاح","الوصف والطبيعة"],"loc":1643},
{"id":"b89-15","bab":"الجزء 9","sec":"قصة الحلة المسمومة وموت امرئ القيس — مفاوضات امرئ القيس وقبائل أسد","page":"ج9 ص118 – ج9 ص122","text":"قال ومر قوم فاستخرجوا امرأ القيس من البئر فرجع إلى حيه فاستاق مائة من الإبل وأقبل إلى امرأته فقيل لها قد جاء زوجك فقالت والله ما أدري أهو زوجي أم لا ولكن انحروا له جزورا فأطعموه من كرشها وذنبها ففعلوا فلما أتوه بذلك قال وأين الكبد والسنام والملحاء فأبى أن يأكل فقالت اسقوه لبنا حازرا فأبى أن يشربه وقال فأين الصريف والرثيئة\nفقالت أفرشوا له عند الفرث والدم فأبى أن ينام وقال افرشوا لي فوق التلعة الحمراء واضربوا عليها خباء ثم أرسلت إليه هلم شريطتي عليك في المسائل الثلاث فأرسل إليها أن سلي عما شئت فقالت مم تختلج شفتاك\nقال لشربي المشعشعات قالت فمم يختلج كشحاك قال للبسي الحبرات قالت فمم تختلج فخذاك قال لركضي المطهمات فقالت هذا زوجي لعمري فعليكم به واقتلوا العبد فقتلوه ودخل امرؤ القيس بالجارية فقال ابن هبيرة حسبكم فلا خير في الحديث في سائر الليلة بعد حديثك يا أبا عمرو ولن تأتينا بأعجب منه فقمنا وانصرفنا وأمر لي بجائزة\nنسخت من كتاب جدي يحيى بن محمد بن ثوابة بخطه رحمه الله حدثني الحسن بن سعيد عن أبي عبيدة قال أخبرني سيبويه النحوي أن الخليل بن أحمد أخبره\nقال قدم على امرئ القيس بن حجر بعد مقتل أبيه رجال من قبائل بني أسد كهول وشبان فيهم المهاجر بن خداش ابن عم عبيد بن الأبرص وقبيصة بن نعيم وكان في بني أسد مقيما وكان ذا بصيرة بمواقع الأمور وردا وإصدارا يعرف ذلك له من كان محيطا بأكناف بلده من العرب فلما علم بمكانهم أمر بإنزالهم وتقدم بإكرامهم والإفضال عليهم واحتجب عنهم ثلاثا فسألوا من حضرهم من رجال كندة فقال هو في شغل بإخراج ما في خزائن حجر من السلاح والعدة فقالوا اللهم غفرا إنما قدمنا في أمر نتناسى به\nذكر ما سلف ونستدرك به ما فرط فليبلغ ذلك عنا فخرج عليهم في قباء وخف وعمامة سوداء وكانت العرب لا تعتم بالسواد إلا في الترات فلما نظروا إليه قاموا\nله وبدر إليه قبيصة إنك في المحل والقدر والمعرفة بتصرف الدهر وما تحدثه أيامه وتتنقل به أحواله بحيث لا تحتاج إلى تبصير واعظ ولا تذكرة مجرب ولك من سؤدد منصبك وشرف أعراقك وكرم أصلك في العرب محتمل يحتمل ما حمل عليه من إقالة العثرة ورجوع عن هفوة ولا تتجاوز الهمم إلى غاية إلا رجعت إليك فوجدت عندك من فضيلة الرأي وبصيرة الفهم وكرم الصفح في الذي كان من الخطب الجليل الذي عمت رزيته نزارا واليمن ولم تخصص كندة بذلك دوننا للشرف البارع كان لحجر التاج والعمة فوق الجبين الكريم وإخاء الحمد وطيب الشيم ولو كان يفدى هالك بالأنفس الباقية بعده لما بخلت كراعنا على مثله ببذل ذلك ولفديناه منه ولكن مضى به سبيل لا يرجع أولاه على أخراه ولا يلحق أقصاه أدناه فأحمد الحالات في ذلك أن تعرف الواجب عليك في إحدى خلال إما أن اخترت من بني أسد أشرافها بيتا وأعلاها في بناء المكرمات صوتا فقدناه إليك بنسعه تذهب مع شفرات حسامك قصدته فيقول رجل امتحن بهلك عزيز فلم تستل سخيمته إلا بتمكينه من الانتقام أو فداء بما يروح من بني أسد من نعمها فهي ألوف تجاوز الحسبة فكان ذلك فداء رجعت به القضب إلى أجفانها لم يردده تسليط الإحن على البرءاء وإما أن توادعنا حتى تضع الحوامل فنسدل الأزر ونعقد الخمر فوق الرايات قال فبكى ساعة ثم رفع رأسه فقال لقد علمت العرب أن لا كفء لحجر في دم وإني لن أعتاض به\nجملا أو ناقة فأكتسب بذلك سبة الأبد وفت العضد وأما النظرة فقد أوجبتها الأجنة في بطون أمهاتها ولن أكون لعطبها سببا وستعرفون طلائع كندة من بعد ذلك تحمل القلوب حنقا وفوق الأسنة علقا\n(إذا جالت الخيل في مأزق ... تصافح فيه المنايا النفوسا)\nتقيمون أم تنصرفون قالوا بل ننصرف بأسوأ الاختيار وأبلى الاجترار لمكروه وأذية وحرب وبلية ثم نهضوا عنه وقبيصة يقول متمثلا\n(لعلك أن تستوخم الموت إن غدت ... كتائبنا في مأزق الموت تمطر)\nقال امرؤ القيس لا والله لا أستوخمه فرويدا ينكشف لك دجاها عن فرسان كندة وكتائب حمير ولقد كان ذكر غير هذا أولى بي إذ كنت نازلا بربعي ولكنك قلت فأجبت فقال قبيصة ما نتوقع فوق قدر المعاتبة والإعتاب قال امرؤ القيس فهو ذاك","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":9,"spl":"قصة الحلة المسمومة وموت امرئ القيس — مفاوضات امرئ القيس وقبائل أسد","tags":["الحب والغزل","الجواري والنساء"],"loc":1644},
{"id":"b89-16","bab":"الجزء 9","sec":"أصوات معبد المعروفة بألقابها وهي خمسة","page":"ج9 ص124","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه وأخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة عن إسحاق وأخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه وأخبرني علي بن عبد العزيز عن ابن خرداذبة عن إسحاق أن معبدا كان يسمى صوته\n(هريرة ودعها وإن لام لائم ... )\nالدوامة لكثرة ما فيه من الترجيع ويسمي صوته\n(عاود القلب من تذكر جمل ... )\nلمنمنم ويسمي صوته\n(أمن آل ليلى بالملا متربع ... )\nعقصات القرون أي يحرك خصل الشعر ويسمي صوته\n(جعل الله جعفرا لك بعلا ... )\nلمتبختر ويسمي صوته\n(ضوء برق بدا لعينيك أم شبت ... بذي الأثل من سلامة نار)\nقطع الأثفار","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":10,"spl":"أصوات معبد المعروفة بألقابها وهي خمسة — نسبة هذه الأصوات وأخبارها","tags":["الرواية والكتابة"],"loc":1645,"partialRef":{"sid":"b88-6","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b89-17","bab":"الجزء 9","sec":"نسبة هذه الأصوات وأخبارها","page":"ج9 ص125","text":"(هريرة ودعها وإن لام لائم ... غداة غد أم أنت للبين واجم)\n(لقد كان في حول ثواء ثويته ... تقضى لبانات ويسأم سائم)\n(مبتلة هيفاء رود شبابها ... لها مقلتا ريم وأسود فاحم)\n(ووجه نقي اللون صاف يزينه ... مع الحلي لبات لها ومعاصم)\nلواجم الساكت المطرق من الحزن يقال وجم يجم وجوما وقوله لقد كان في حول ثواء ثويته قال الكوفيون أراد لقد كان في ثواء حول\nثويته فجعل ثواء بدلا من حول وأخبرنا أبو خليفة عن محمد بن سلام عن يونس قال كان أبو عمرو بن العلاء يعيب قول الأعشى\n(لقد كان في حول ثواء ثويته ... )\nدا ويقول ما أعرف له معنى ولا وجها يصح قال أبو خليفة وأما أبو عبيدة فإنه قال معناه لقد كان في ثواء حول ثويته واللبانات والمآرب والحوائج والأوطار واحد والمبتلة الحسنة الخلق والهيفاء اللطيفة الخصر والرئم الظبي والفاحم الشديد السواد\nوقال لبات لها وإنما لها لبة واحدة ولكن العرب تقول ذلك كثيرا يقال لها لبات حسان يراد اللبة وما حولها والمعاصم موضع الأسورة وواحدها معصم الشعر للأعشى والغناء لمعبد وله فيه لحنان أحدهما وهو الملقب بالدوامة خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق والآخر ثقيل عن الهشامي وابن خرداذبة","topic":"ذكر امرئ القيس ونسبه وأخباره","topicNo":89,"sp":10,"spl":"أصوات معبد المعروفة بألقابها وهي خمسة — نسبة هذه الأصوات وأخبارها","tags":["الوصف والطبيعة"],"loc":1646,"partialRef":{"sid":"b10-21","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b90-1","bab":"الجزء 9","sec":"أخبار الأعشى ونسبه","page":"ج9 ص127","text":"الأعشى هو ميمون بن قيس بن جندل بن شراحيل بن عوف بن سعد بن ضبيعة بن قيس بن ثعلبة الحصن بن عكابة بن صعب بن علي بن بكر بن وائل بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار ويكنى أبا بصير وكان يقال لأبيه قيس بن جندل قتيل الجوع سمي بذلك لأنه دخل غارا يستظل فيه من الحر فوقعت صخرة عظيمة من الجبل فسدت فم الغار فمات فيه جوعا فقال فيه جهنام واسمه عمرو وهو من قومه من بني قيس بن ثعلبة يهجوه وكانا يتهاجيان\n(أبوك قتيل الجوع قيس بن جندل ... وخالك عبد من خماعة راضع)\nهو أحد الأعلام من شعراء الجاهلية وفحولهم وتقدم على سائرهم وليس ذلك بمجمع عليه لا فيه ولا في غيره أخبرني أبو خليفة عن محمد بن سلام قال سألت يونس النحوي من أشعر الناس قال لا أومىء إلى رجل بعينه ولكني أقول امرؤ القيس إذا غضب والنابغة إذا رهب وزهير إذا رغب والأعشى إذا طرب أخبرني ابن عمار عن ابن مهرويه عن حذيفة بن محمد عن ابن سلام بمثله\nأخبرني عمي قال حدثنا ابن أبي سعد قال حدثنا علي بن الصباح عن ابن الكلبي عن أبيه وأبي مسكين أن حسانا سئل من أشعر الناس فقال أشاعر بعينه أم قبيلة قالوا بل قبيلة\nقال الزرق من بني قيس بن ثعلبة وهذا حديث يروى أيضا عن غير حسان أخبرني أحمد بن عبيد الله بن عمار عن ابن مهرويه قال حدثنا عبدة بن عصمة عن فراس بن خندف عن علي بن شفيع\nقال إني لواقف بسوق حجر إذ أنا برجل من هيئته وحاله عليه مقطعات خز وهو على نجيب مهري عليه رحل لم أر قط أحسن منه وهو يقول من يفاخرني من ينافرني ببني عامر بن صعصعة فرسانا وشعراء وعددا وفعالا\nقلت أنا قال بمن قلت ببني ثعلبة بن عكابة بن صعب بن علي بن بكر ابن وائل فقال أما بلغك أن رسول الله نهى عن المنافرة ثم ولى هاربا قلت من هذا قيل عبد العزيز بن زرارة بن جزء بن سفيان الكلابي","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":0,"spl":"أخبار الأعشى ونسبه — صناجة العرب","tags":["السفر والحج","الموت","الرواية والكتابة"],"loc":1647},
{"id":"b90-2","bab":"الجزء 9","sec":"صناجة العرب","page":"ج9 ص128","text":"أخبرني حبيب بن نصر المهلبي وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال\nقال أبو عبيدة من قدم الأعشى يحتج بكثرة طواله الجياد وتصرفه في المديح والهجاء وسائر فنون الشعر وليس ذلك لغيره ويقال هو أول من سأل بشعره وانتجع به أقاصي البلاد وكان يغنى في شعره فكانت العرب تسميه صناجة العرب\nأخبرني المهلبي والجوهري قالا حدثنا عمر بن شبة قال سمعت خلادا الأرقط يقول سمعت خلفا الأحمر يقول لا يعرف من أشعر الناس كما لا يعرف من أشجع الناس ولا من كذا ولا من كذا لأشياء ذكرها خلف ونسيتها أنا أبو زيد عمر بن شبة يقول هذا\nأخبرني محمد بن العباس اليزيدي قال حدثني عمي يوسف قال حدثني عمي إسماعيل بن أبي محمد قال أخبرني أبي قال سمعت أبا عمرو بن العلاء يقدم الأعشى وقال هشام بن الكلبي أخبرني أبو قبيصة المجاشعي أن مروان بن أبي حفصة سئل من أشعر الناس قال الذي يقول\n(كلا أبويكم كان فرع دعامة ... ولكنهم زادوا وأصبحت ناقصا)\nعني الأعشى أخبرني محمد بن العباس اليزيدي قال حدثني عمي قال قال سلمة بن نجاح أخبرني يحيى بن سليم الكاتب قال بعثني أبو جعفر أمير المؤمنين بالكوفة إلى حماد الراوية أسأله عن أشعر\nالشعراء قال فأتيت باب حماد فاستأذنت وقلت يا غلام فأجابني إنسان من أقصى بيت في الدار فقال من أنت فقلت يحيى بن سليم رسول أمير المؤمنين\nقال ادخل رحمك الله فدخلت أتسمت الصوت حتى وقفت على باب البيت فإذا حماد عريان على فرجه دستجة شاهسفرم فقلت إن أمير المؤمنين يسألك عن أشعر الناس فقال نعم ذلك الأعشى صناجها\nأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال سمعت أبا عبيدة يقول سمعت أبا عمرو بن العلاء يقول عليكم بشعر الأعشى فإني شبهته بالبازي يصيد ما بين العندليب إلى الكركي","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":0,"spl":"أخبار الأعشى ونسبه — صناجة العرب","tags":["الهجاء"],"loc":1648},
{"id":"b90-3","bab":"الجزء 9","sec":"مرتبته بين الشعراء","page":"ج9 ص130","text":"أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال سمعت أبا عبيدة يقول بلغني أن رجلا من أهل البصرة حج وروى هذا الحديث ابن الكلبي عن شعيب بن عبد الرحمن أبي معاوية النحوي عن رجل من أهل البصرة أنه حج قال فإني لأسير في ليلة إضحيانة إذ نظرت إلى رجل شاب راكب على ظليم قد زمه بخطامه وهو يذهب عليه ويجيء وهو يرتجز ويقول\n(هل يبلغنيهم إلى الصباح ... هقل كأن رأسه جماح)\nالجماح أطراف النبت الذي يسمى الحلي وهو سنبله إلا أنه ليس بخشن يشبه أذناب الثعالب قال والجماح أيضا سهيم يلعب به الصبيان يجعلون مكان زجه طينا قال فعلمت أنه ليس بإنسي فاستوحشت منه فتردد علي ذاهبا وراجعا حتى أنست به فقلت من أشعر الناس يا هذا قال الذي يقول\n(وما ذرفت عيناك إلا لتضربي ... بسهميك في أعشار قلب مقتل)\nلت ومن هو قال امرؤ القيس قلت فمن الثاني قال الذي يقول\n(تطرد القر بحر ساخن ... وعكيك القيظ إن جاء بقر)\nقلت ومن يقوله قال طرفة قلت ومن الثالث قال الذي يقول\n(وتبرد برد رداء العروس ... بالصيف رقرقت فيه العبيرا)\nلت ومن يقوله قال الأعشى ثم ذهب به أخبرني أحمد بن عبيد الله بن عمار قال حدثني أبو عدنان قال وقال لي يحيى بن الجون العبدي راوية بشار نحن حاكة الشعر في الجاهلية والإسلام ونحن أعلم الناس به أعشى بني قيس بن ثعلبة أستاذ الشعراء في الجاهلية وجرير بن الخطفي أستاذهم في الإسلام","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":1,"spl":"مرتبته بين الشعراء — حديث الشعبي عنه","tags":[],"loc":1649},
{"id":"b90-4","bab":"الجزء 9","sec":"حديث الشعبي عنه","page":"ج9 ص131","text":"أخبرني محمد بن العباس اليزيدي قال حدثنا الرياشي قال قال الشعبي الأعشى أغزل الناس في بيت وأخنث الناس في بيت\nوأشجع الناس في بيت فأما أغزل بيت فقوله\n(غراء فرعاء مصقول عوارضها ... تمشي الهوينى كما يمشي الوجي الوحل)\nأما أخنث بيت فقوله\n(قالت هريرة لما جئت زائرها ... ويلي عليك وويلي منك يا رجل)\nأما أشجع بيت فقوله\n(قالوا الطراد فقلنا تلك عادتنا ... أو تنزلون فإنا معشر نزل)\nخبرني الحسن بن علي قال حدثنا ابن مهرويه عن ابن أبي سعد قال ذكر الهيثم بن عدي أن حمادا الراوية سئل عن أشعر العرب قال الذي يقول\n(نازعتهم قضب الريحان متكئا ... وقهوة مزة راووقها خضل)\nخبرني أحمد بن عبيد الله بن عمار قال حدثنا أبو علي العنزي قال حدثني محمد بن معاوية الأسدي قال حدثني رجل من أبان بن تغلب عن سماك بن حرب قال قال لي يحيى بن متى راوية الأعشى وكان نصرانيا عباديا وكان معمرا قال كان الأعشى قدريا وكان لبيد مثبتا قال لبيد\n(من هداه سبل الخير اهتدى ... ناعم البال ومن شاء أضل)\nوقال الأعشى\n(إستأثر الله بالوفاء وبالعدل ... وولى الملامة الرجلا)\nلت فمن أين أخذ الأعشى مذهبه قال من قبل العباديين نصارى الحيرة كان يأتيهم يشتري منهم الخمر فلقنوه ذلك أخبرني محمد بن العباس اليزيدي\nقال حدثنا أبو شراعة في مجلس الرياشي قال حدثنا مشايخ بني قيس بن ثعلبة قالوا كانت هريرة التي يشبب بها الأعشى أمة سوداء لحسان بن عمرو بن مرثد\nوأخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة عن فراس بن الخندف قال كانت هريرة وخليدة أختين قينتين كانتا لبشر بن عمرو بن مرثد وكانتا تغنيانه النصب وقدم بهما اليمامة لما هرب من النعمان قال ابن دريد فأخبرني عمي عن ابن الكلبي بمثل ذلك","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":1,"spl":"مرتبته بين الشعراء — حديث الشعبي عنه","tags":["اللهو والمزاح","الوصف والطبيعة"],"loc":1650},
{"id":"b90-5","bab":"الجزء 9","sec":"الشعر واسطة للزواج","page":"ج9 ص133","text":"وأخبرني محمد بن العباس اليزيدي عن الرياشي مما أجازه له عن العتبي عن رجل من قيس عيلان قال كان الأعشى يوافي سوق عكاظ في كل سنة وكان المحلق الكلابي\nمئناثا مملقا فقالت له امرأته يا أبا كلاب ما يمنعك من التعرض لهذا الشاعر فما رأيت أحدا اقتطعه إلى نفسه إلا وأكسبه خيرا قال ويحك ما عندي إلا ناقتي وعليها الحمل قالت الله يخلفها عليك\nقال فهل له بد من الشراب والمسوح قالت إن عندي ذخيرة لي ولعلي أن أجمعها قال فتلقاه قبل أن يسبق إليه أحد وابنه يقوده فأخذ الخطام فقال الأعشى من هذا الذي غلبنا على خطامنا\nقال المحلق قال شريف كريم ثم سلمه إليه فأناخه فنحر له ناقته وكشط له عن سنامها وكبدها ثم سقاه وأحاطت بناته به يغمزنه ويمسحنه فقال ما هذه الجواري حولي\nقال بنات أخيك وهن ثمان شريدتهن قليلة قال وخرج من عنده ولم يقل فيه شيئا فلما وافى سوق عكاظ إذا هو بسرحة قد اجتمع الناس عليها وإذا الأعشى ينشدهم\n(لعمري لقد لاحت عيون كثيرة ... إلى ضوء نار باليفاع تحرق)\n(تشب لمقرورين يصطليانها ... وبات على النار الندى والمحلق)\n(رضيعي لبان ثدي أم تحالفا ... بأسحم داج عوض لا نتفرق)\nسلم عليه المحلق فقال له مرحبا يا سيدي بسيد قومه ونادى يا معاشر العرب هل فيكم مذكار يزوج ابنه إلى الشريف الكريم قال\nفما قام من مقعده وفيهن مخطوبة إلا وقد زوجها وفي أول القصيدة غناء وهو\n(أرقت وما هذا السهاد المؤرق ... وما بي من سقم وما بي معشق)\n(ولكن أراني لا أزال بحادث ... أغادى بما لم يمس عندي وأطرق)\nناه ابن محرز خفيف ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لحن ليونس من كتابه غير مجنس وفيه لابن سريج ثقيل بإطلاق الوتر في مجرى الوسطى عن إسحاق وعمرو\nأخبرني أبو العباس اليزيدي قال حدثني عمي عبيد الله عن ابن حبيب عن ابن الأعرابي عن المفضل قال اسم المحلق عبد العزى بن حنتم بن شداد بن ربيعة بن عبد الله بن عبيد وهو أبو بكر بن كلاب بن ربيعة بن عامر بن صعصعة وإنما سمي محلقا لأن حصانا له عضه في وجنته فحلق فيه حلقة قال وأنشد الأعشى قصيدته هذه كسرى ففسرت له فلما سمعها قال إن كان هذا سهر لغير سقم ولا عشق فما هو إلا لص","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":2,"spl":"الشعر واسطة للزواج","tags":[],"song":1,"loc":1651},
{"id":"b90-6","bab":"الجزء 9","sec":"المحلق الكلابي وسبب اتصاله بالأعشى","page":"ج9 ص135","text":"وذكر علي بن محمد النوفلي في خبر المحلق مع الأعشى غير هذه الحكايات وزعم أن أباه حدثه عن بعض الكلابيين من أهل البادية قال كان لأبي المحلق شرف فمات وقد أتلف ماله وبقي المحلق وثلاث أخوات له ولم يترك لهم إلا ناقة واحدة وحلتي برود حبرة كان يشهد فيهما\nالحقوق فأقبل الأعشى من بعض أسفاره يريد منزله باليمامة فنزل الماء الذي به المحلق فقراه أهل الماء فأحسنوا قراه فأقبلت عمة المحلق فقالت يابن أخي هذا الأعشى قد نزل بمائنا وقد قراه أهل الماء والعرب تزعم أنه لم يمدح قوما إلا رفعهم ولم يهج قوما إلا وضعهم فانظر ما أقول لك واحتل في زق من خمر من عند بعض التجار فأرسل إليه بهذه الناقة والزق وبردي أبيك فوالله لئن اعتلج الكبد والسنام والخمر في جوفه ونظر إلى عطفيه في البردين ليقولن فيك شعرا يرفعك به\nقال ما أملك غير هذه الناقة وأنا أتوقع رسلها فأقبل يدخل ويخرج ويهم ولا يفعل فكلما دخل على عمته حضته حتى دخل عليها فقال فقد ارتحل الرجل ومضى قالت الآن والله أحسن ما كان القرى تتبعه ذلك مع غلام أبيك مولى له أسود شيخ فحيثما لحقه أخبره عنك أنك كنت غائبا عن الماء عند نزوله إياه وأنك لما وردت الماء فعلمت أنه كان به كرهت أن يفوتك قراه فإن هذا أحسن لموقعه عنده فلم تزل تحضه حتى أتى بعض التجار فكلمه أن يقرضه ثمن زق خمر وأتاه بمن يضمن ذلك عنه فأعطاه فوجه بالناقة والخمر والبردين مع مولى أبيه فخرج يتبعه فكلما مر بماء\nقيل ارتحل أمس عنه حتى صار إلى منزل الأعشى بمنفوحة اليمامة فوجد عنده عدة من الفتيان قد غداهم بغير لحم وصب لهم فضيخا فهم يشربون منه إذ قرع الباب فقال انظروا\nمن هذا فخرجوا فإذا رسول المحلق يقول كذا وكذا فدخلوا عليه وقالوا هذا رسول المحلق الكلابي أتاك بكيت وكيت فقال ويحكم أعرابي والذي أرسل إلي لا قدر له والله لئن اعتلج الكبد والسنام والخمر في جوفي لأقولن فيه شعرا لم أقل قط مثله فواثبه الفتيان وقالوا غبت عنا فأطلت الغيبة ثم أتيناك فلم تطعمنا لحما وسقيتنا الفضيخ واللحم والخمر ببابك لا نرضى بدا منك فقال ائذنوا له فدخل فأدى الرسالة وقد أناخ الجزور بالباب ووضع الزق والبردين بين يديه\nقال أقره السلام وقل له وصلتك رحم سيأتيك ثناؤنا وقام الفتيان إلى الجزور فنحروها وشقوا خاصرتها عن كبدها وجلدها عن سنامها ثم جاؤوا بهما فأقبلوا يشوون وصبوا الخمر فشربوا وأكل معهم وشرب ولبس البردين ونظر إلى عطفيه فيهما فأنشأ يقول\n(أرقت وما هذا السهاد المؤرق ... )\nتى انتهى إلى قوله\n(أبا مسمع سار الذي قد فعلتم ... فأنجد أقوام به ثم أعرقوا)\n(به تعقد الأحمال في كل منزل ... وتعقد أطراف الحبال وتطلق)\nال فسار الشعر وشاع في العرب فما أتت على المحلق سنة حتى زوج أخواته الثلاث كل واحدة على مائة ناقة فأيسر وشرف وذكر الهيثم بن عدي عن حماد الراوية عن معقل عن أبي بكر الهلالي قال خرج الأعشى إلى اليمن يريد قيس بن معد يكرب فمر ببني\nكلاب فأصابه مطر في ليلة ظلماء فأوى إلى فتى من بني بكر بن كلاب فبصر به المحلق وهو عبد العزى بن حنتم بن شداد بن ربيعة بن عبد الله بن عبيد بن كلاب وهو يومئذ غلام له ذؤابة فأتى أمه فقال يا أمه رأيت رجلا أخلق به أن يكسبنا مجدا قالت وما تريد يا بني قال نضيفه الليلة فأعطته جلبابها فاشترى به عشيرا من جزور وخمرا فأتى الأعشى فأخذه إليه فطعم وشرب واصطلى ثم اصطبح فقال فيه\n(أرقت وما هذا السهاد المؤرق ... )\nالرواية الأولى أصح أخبرني أحمد بن عمار قال حدثنا يعقوب بن نعيم قال حدثنا قعنب بن المحرز عن الأصمعي قال حدثني رجل قال جاءت امرأة إلى الأعشى فقالت إن لي بنات قد كسدن علي فشبب بواحدة منهن لعلها أن تنفق فشبب بواحد منهن فما شعر الأعشى إلا بجزور قد بعث به إليه فقال ما هذا فقالوا زوجت فلانة فشبب بالأخرى فأتاه مثل ذلك فسأل عنها فقيل زوجت فما زال يشبب بواحدة فواحدة منهن حتى زوجن جميعا أخبرني محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثنا يحيى بن أبي سعيد الأموي عن محمد بن السائب الكلبي قال\nهجا الأعشى رجلا من كلب فقال\n(بنو الشهر الحرام فلست منهم ... ولست من الكرام بني عبيد)\n(ولا من رهط جبار بن قرط ... ولا من رهط حارثة بن زيد)","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":3,"spl":"المحلق الكلابي وسبب اتصاله بالأعشى","tags":["الحب والغزل","الهجاء"],"loc":1652,"partialRef":{"sid":"b90-5","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b90-7","bab":"الجزء 9","sec":"المحلق الكلابي وسبب اتصاله بالأعشى","page":"ج9 ص135","text":"قال وهؤلاء كلهم من كلب فقال الكلبي لا أبا لك أنا أشرف من هؤلاء قال فسبه الناس بعد بهجاء الأعشى إياه وكان متغيظا عليه فأغار على قوم قد بات فيهم الأعشى فأسر منهم نفرا وأسر الأعشى وهو لا يعرفه ثم جاء حتى نزل بشريح بن السموءل بن عادياء الغساني صاحب تيماء بحصنه الذي يقال له الأبلق فمر شريح بالأعشى فناداه الأعشى\n(شريح لا تتركني بعد ما علقت ... حبالك اليوم بعد القد أظفاري)\n(قد جلت ما بين بانقيا إلى عدن ... وطال في العجم تردادي وتسياري)\n(فكان أكرمهم عهدا وأوثقهم ... مجدا أبوك بعرف غير إنكار)\n(كالغيث ما استمطروه جاد وابله ... وفي الشدائد كالمستأسد الضاري)\n(كن كالسموءل إذ طاف الهمام به ... في جحفل كهزيع الليل جرار)\n(إذ سامه خطتي خسف فقال له ... قل ما تشاء فإني سامع حار)\n(فقال غدر وثكل أنت بينهما ... فاختر وما فيهما حظ لمختار)\n(فشك غير طويل ثم قال له ... أقتل أسيرك إني مانع جاري)\n(وسوف يعقبنيه إن ظفرت به ... رب كريم وبيض ذات أطهار)\n(لا سرهن لدينا ذاهب هدرا ... وحافظات إذا استودعن أسراري)\n(فاختار أدراعه كي لا يسب بها ... ولم يكن وعده فيها بختار)\nقال وكان امرؤ القيس بن حجر أودع السموءل بن عادياء أدراعا مائة فأتاه الحارث بن ظالم ويقال الحارث بن أبي شمر الغساني ليأخذها منه فتحصن منه السموءل فأخذ الحارث ابنا له غلاما وكان في الصيد فقال إما أن سلمت الأدراع إلي وإما أن قتلت ابنك فأبى السموءل أن يسلم إليه الأدراع فضرب الحارث وسط الغلام بالسيف فقطعه قطعتين فيقال إن جريرا حين قال للفرزدق\n(بسيف أبي رغوان سيف مجاشع ... ضربت ولم تضرب بسيف ابن ظالم)\nنما غنى هذه الضربة فقال السموءل في ذلك\n(وفيت بذمة الكندي إني ... إذا ما ذم أقوام وفيت)\n(وأوصى عاديا يوما بأن لا ... تهدم يا سموءل ما بنيت)\n(بني لي عاديا حصنا حصينا ... وماء كلما شئت استقيت)\nال فجاء شريح إلى الكلبي فقال له هب لي هذا الأسير المضرور فقال هو لك فأطلقه وقال أقم عندي حتى أكرمك وأحبوك فقال له الأعشى إن من تمام صنيعتك أن تعطيني ناقة نجيبة وتخليني الساعة قال\nفأعطاه ناقة فركبها ومضى من ساعته وبلغ الكلبي أن الذي وهب لشريح هو الأعشى فأرسل إلى شريح ابعث إلي الأسير الذي وهبت لك حتى أحبوه وأعطيه فقال قد مضى فأرسل الكلبي في أثره فلم يلحقه","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":4,"spl":"المحلق الكلابي وسبب اتصاله بالأعشى","tags":["الهجاء"],"loc":1653},
{"id":"b90-8","bab":"الجزء 9","sec":"الأعشى يمدح عامر بن الطفيل ويهجو علقمة بن علاثة","page":"ج9 ص141","text":"حدثنا ابن علاثة عن محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثنا يحيى بن سعيد بن يحيى الأموي عن محمد بن السائب قال أتى الأعشى الأسود العنسي وقد امتدحه فاستبطأ جائزته فقال الأسود ليس عندنا عين ولكن نعطيك عرضا فأعطاه خمسمائة مثقال دهنا وبخمسمائة حللا وعنبرا فلما مر ببلاد بني عامر خافهم على ما معه فأتى علقمة بن علاثة فقال له أجرني فقال قد أجرتك قال من الجن والإنس قال نعم قال ومن الموت قال لا فأتى عامر بن الطفيل\nفقال أجرني قال قد أجرتك قال من الجن والإنس قال نعم قال ومن الموت قال نعم قال وكيف تجيرني من الموت قال إن مت وأنت في جواري بعثت إلى أهلك الدية فقال الآن علمت أنك قد أجرتني من الموت فمدح عامرا وهجا علقمة فقال علقمة لو علمت الذي أراد كنت أعطيته إياه قال الكلبي ولم يهج علقمة بشي أشد عليه من قوله\n(تبيتون في المشتى ملاء بطونكم ... وجاراتكم غرثى يبتن خمائصا)\nرفع علقمة يديه وقال لعنه الله إن كان كاذبا أنحن نفعل هذا بجاراتنا وأخبار الأعشى وعلقمة وعامر تأتي مشروحة في خبر منافرتهما إن شاء الله تعالى أخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله قال حدثني محمد بن حبيب عن ابن الأعرابي عن المفضل وغيره من أصحابه أن الأعشى تزوج امرأة من عنزة ثم من هزان قال وعنزة هو ابن أسد بن ربيعة بن نزار فلم يرضها ولم يستحسن خلقها فطلقها وقال فيها\n(بيني حصان الفرج غير ذميمة ... وموموقة فينا كذاك ووامقه)\n(وذوقي فتى قوم فإني ذائق ... فتاة أناس مثل ما أنت ذائقه)\n(لقد كان في فتيان قومك منكح ... وشبان هزان الطوال الغرانقه)\n(فبيني فإن البين خير من العصا ... وإلا تري لي فوق رأسك بارقه)\n(وما ذاك عندي أن تكوني دنيئة ... ولا أن تكوني جئت عندي ببائقه)\n(ويا جارتا بيني فإنك طالقه ... كذاك أمور الناس غاد وطارقه)\nخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا الحسين بن إبراهيم بن الحر قال حدثنا المبارك بن سعيد عن سفيان الثوري قال طلاق الجاهلية طلاق كانت عند الأعشى امرأة فأتاها قومها فضربوه وقالوا طلقها فقال\n(أيا جارتا بيني فإنك طالقه ... كذاك أمور الناس غاد وطارقه)\nوذكر باقي الأبيات مثل ما تقدم أخبرنا أحمد قال حدثنا عمر قال حدثنا عبد الصمد بن عبد الوارث قال حدثنا عثمان البرقي في إسناد له قال أخذ قوم الأعشى فقالوا له طلق امرأتك فقال\n(أيا جارتا بيني فإنك طالقه ... كذاك أمور الناس غاد وطارقه)\nم ذكر نحو الخبر الذي قبله على ما قدمناه في هذه الأبيات غناء نسبته\n\n(فبيني فإن البين خير من العصا ... وإلا تري لي فوق رأسك بارقه)\n(وما ذاك عندي أن تكوني دنيئة ... ولا أن تكوني جئت عندي ببائقه)\n(ويا جارتا بيني فإنك طالقه ... كذاك أمور الناس غاد وطارقه)\nلشعر للأعشى والغناء للهذلي خفيف ثقيل مطلق في مجرى البنصر عن إسحاق وفيه لابن جامع ثاني ثقيل بالبنصر عن الهشامي قال الهشامي وفيه لفليح خفيف ثقيل بالوسطى لا يشك فيه من غنائه وذكر حبش أن الثقيل الثاني لابن سريج وذكر عبيد الله بن عبد الله بن طاهر أن الخفيف الثاني المنسوب إلى فليح لأبيه عبد الله بن طاهر وهذا الصوت يغنى في هذا الزمان على ما سمعناه\n(أيا جارتا دومي فإنك صادقه ... وموموقة فينا كذاك ووامقه)\n(ولم نفترق أن كنت فينا دنيئة ... ولا أن تكوني جئت عندي ببائقه)\nأحسبه غير في دور الطاهرية على هذا أخبرني علي بن سليمان الأخفش قال حدثني سوار بن أبي شراعة قال حدثني أبي عن مسعود بن بشر عن أبي عبيدة قال دخل الأخطل على عبد الملك بن مروان وقد شرب خمرا وتضمخ بلخالخ وخلوق وعنده الشعبي فلما رآه قال يا شعبي ناك الأخطل أمهات الشعراء جميعا فقال له الشعبي بأي شيء قال حين يقول\n(وتظل تنصفنا بها قروية ... إبريقها برقاعه ملثوم)\n(فإذا تعاورت الأكف زجاجها ... نفحت فشم رياحها المزكوم)\nقال الأخطل سمعت بمثل هذا يا شعبي قال إن أمنتك قلت لك قال أنت آمن فقلت له أشعر والله منك الذي يقول\n(وأدكن عاتق جحل ربحل ... صبحت براحه شربا كراما)\n(من اللائي حملن على المطايا ... كريح المسك تستل الزكاما)\nقال الأخطل ويحك ومن يقول هذا قلت الأعشى أعشى بني قيس ابن ثعلبة فقال قدوس قدوس ناك الأعشى أمهات الشعراء جميعا وحق الصليب أخبرني هاشم بن محمد الخزاعي","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":5,"spl":"الأعشى يمدح عامر بن الطفيل ويهجو علقمة بن علاثة","tags":["الهجاء"],"song":1,"loc":1654},
{"id":"b90-9","bab":"الجزء 9","sec":"الأعشى يمدح عامر بن الطفيل ويهجو علقمة بن علاثة","page":"ج9 ص141","text":"قال حدثنا أبو غسان دماذ عن أبي عبيدة والهيثم بن عدي وحدثني الصولي قال حدثني الغلابي عن العتبي عن أبيه وذكر هارون بن الزيات عن حماد عن أبيه عن عبد الله بن الوليد عن جعفر بن سعيد الضبي قالوا جميعا قدم الأخطل الكوفة فأتاه الشعبي يسمع من شعره قال فوجدته يتغدى فدعاني أتغدى فأتيته فوضع الشراب فدعاني إليه فأتيته فقال ما حاجتك قلت أحب أن أسمع من شعرك فأنشدني قوله\n(صرمت أمامة حبلنا ورعوم ... )\nتى انتهى إلى قوله\n(فإذا تعاورت الأكف ختامها ... نفحت فشم رياحها المزكوم)\nفقال يا شعبي ناك الأخطل أمهات الشعراء بهذا البيت قلت الأعشى أشعر منك يا أبا مالك قال وكيف قلت لأنه قال\n(من خمر عانة قد أتى لختامها ... حول تسل غمامة المزكوم)\nضرب بالكأس الأرض وقال هو والمسيح أشعر مني ناك والله الأعشى أمهات الشعراء إلا أنا حدثني وكيع قال حدثني محمد بن إسحاق المعولي عن إسحاق الموصلي عن الهيثم بن عدي عن حماد الراوية عن سماك بن حرب قال قال الأعشى أتيت سلامة ذا فائش فأطلت المقام ببابه حتى وصلت إليه فأنشدته\n(إن محلا وإن مرتحلا ... وإن في السفر من مضى مهلا)\n(استأثر الله بالوفاء وبالعدل ... وولى الملامة الرجلا)\n(الشعر قلدته سلامة ذا ... فائش والشيء حيث ما جعلا)\nقال صدقت الشيء حيث ما جعل وأمر لي بمائة من الإبل وكساني حللا وأعطاني كرشا مدبوغة مملوءة عنبرا وقال إياك أن تخدع عما فيها فأتيت الحيرة فبعتها بثلاثمائة ناقة حمراء\nأخبرني حبيب بن نصر المهلبي وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال قال هشام بن القاسم الغنوي وكان علامة بأمر الأعشى إنه وفد إلى النبي وقد مدحه بقصيدته التي أولها\n(ألم تغتمض عيناك ليلة أرمدا ... وعادك ما عاد السليم المسهدا)\n(وما ذاك من عشق النساء وإنما ... تناسيت قبل اليوم خلة مهددا)\nوفيها يقول لناقته\n(فآليت لا أرثي لها من كلالة ... ولا من حفا حتى تزور محمدا)\n(نبي يرى ما لا ترون وذكره ... أغار لعمري في البلاد وأنجدا)\n(متى ما تناخي عند باب ابن هاشم ... تراحي وتلقي من فواضله يدا)\nبلغ خبره قريشا فرصدوه على طريقه وقالوا هذا صناجة العرب ما مدح أحدا قط إلا رفع في قدره فلما ورد عليهم قالوا له أين أردت يا أبا بصير\nقال أردت صاحبكم هذا لأسلم قالوا إنه ينهاك عن خلال ويحرمها عليك وكلها بك رافق ولك موافق قال وما هن فقال أبو سفيان بن حرب الزنا قال لقد تركني الزنا وما تركته ثم ماذا\nقال القمار قال لعلي إن لقيته أن أصيب منه عوضا من القمار ثم ماذا قالوا الربا قال ما دنت ولا ادنت ثم ماذا قالوا الخمر قال أوه أرجع إلى صبابة قد بقيت لي في المهراس فأشربها فقال له أبو سفيان هل لك في خير مما هممت به\nقال وما هو قال نحن وهو الآن في هدنة فتأخذ مائة من الإبل وترجع إلى بلدك سنتك هذه وتنظر ما يصير إليه أمرنا فإن ظهرنا عليه كنت قد أخذت\nخلفا وإن ظهر علينا أتيته فقال ما أكره ذلك فقال أبو سفيان يا معشر قريش هذا الأعشى والله لئن أتى محمدا واتبعه ليضرمن عليكم نيران العرب بشعره فاجمعوا له مائة من الإبل ففعلوا فأخذها وانطلق إلى بلده فلما كان بقاع منفوحة رمى به بعيره فقتله","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":6,"spl":"الأعشى يمدح عامر بن الطفيل ويهجو علقمة بن علاثة","tags":["الحب والغزل"],"loc":1655,"partial":1},
{"id":"b90-10","bab":"الجزء 9","sec":"الفتيان يتنادمون على قبره بمنفوحة","page":"ج9 ص148","text":"أخبرني يحيى بن علي بن يحيى قال حدثنا محمد بن إدريس بن سليمان بن أبي حفصة قال قبر الأعشى بمنفوحة وأنا رأيته فإذا أراد الفتيان أن يشربوا خرجوا إلى قبره فشربوا عنده وصبوا عنده فضلات الأقداح أخبرني أبو الحسن الأسدي قال حدثنا علي بن سليمان النوفلي قال حدثنا أبي قال أتيت اليمامة واليا عليها فمررت بمنفوحة وهي منزل الأعشى التي يقول فيها\n(بشط منفوحة فالحاجر ... )\nقلت أهذه قرية الأعشى قالوا نعم فقلت أين منزله قالوا ذاك وأشاروا إليه قلت فأين قبره قالوا بفناء بيته فعدلت إليه بالجيش فانتهيت إلى قبره فإذا هو رطب فقلت ما لي أراه رطبا فقالوا إن الفتيان ينادمونه فيجعلون قبره مجلس رجل منهم فإذا صار إليه القدح صبوه عليه لقوله أرجع إلى اليمامة فأشبع من الأطيبين الزنا والخمر وأخبرنا الحسن بن علي قال حدثنا هارون بن محمد بن عبد الملك الزيات قال حدثنا الأطروش بن إسحاق بن إبراهيم عن أبيه أن ابن عائشة غنى يوما\n(هريرة ودعها وإن لام لائم ... )\nفأعجبته نفسه ورآه ينظر في أعطافه فقيل له لقد أصبحت اليوم تائها فقال وما يمنعني من ذلك وقد أخذت عن أبي عباد معبد أحد عشر صوتا منها\n(هريرة ودعها وإن لام لائم ... )\nأبو عباد مغني أهل المدينة وإمامهم قال وكان معبد يقول والله لقد صنعت صوتا لا يقدر أن يغنيه شبعان ممتلئ ولا يقدر متكئ على أن يغنيه حتى يجثو ولا قائم حتى يقعد قيل وما هو يا أبا عباد قال إسحاق فأخبرني بذاك محمد بن سلام الجمحي أنه بلغه أن معبدا قاله وأخبرني بهذا الخبر اسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثنا أبو غسان محمد بن يحيى قال قال معبد والله لأغنين صوتا لا يغنيه مهموم ولا شبعان ولا حامل حمل ثم غنى\n(ولقد قلت والضمير ... كثير البلابل)\n(ليت شعري تمنيا ... والمنى غير طائل)\n(هل رسول مبلغ ... فيؤدي رسائلي)\nحن معبد هذا خفيف ثقيل بالسبابة في مجرى الوسطى عن إسحاق ويونس وفيه ثقيل أول ينسب إليه أيضا ويقال إنه لأهل مكة ومنها الصوت المسمى بالمنمنم\n(هاج ذا القلب من تذكر جمل ... ما يهيج المتيم المحزونا)\n(إذ تراءت على البلاط فلما ... واجهتنا كالشمس تعشي العيونا)\n(ليلة السبت إذ نظرت إليها ... نظرة زادت الفؤاد جنونا)\nالشعر لإسماعيل بن يسار والغناء لمعبد ثقيل أول بالوسطى وفيه لدحمان ثاني ثقيل بالبنصر ذكر الهشامي أنه لا يشك فيه من غنائه وقد مضت أخبار إسماعيل بن يسار في المائة المختارة فاستغني عن إعادتها ها هنا\n(آمن آل ليلى بالملا متربع ... كما لاح وشم في الذراع مرجع)\n(سأتبع ليلى حيث سارت وخيمت ... وما الناس إلا آلف ومودع)\nالشعر لعمرو بن سعيد بن زيد وقيل إنه للمجنون وإن مع هذين البيتين أخر وهي\n(وقفت لليلى بعد عشرين حجة ... بمنزلة فانهلت العين تدمع)\n(فأمرض قلبي حبها وطلابها ... فيا آل ليلى دعوة كيف أصنع)\n(سأتبع ليلى حيث حلت وخيمت ... وما الناس إلا آلف ومودع)\n(كأن زماما في الفؤاد معلقا ... تقود به حيث استمرت وأتبع)\nالغناء لمعبد خفيف ثقيل أول بالسبابة في مجرى الوسطى وقد ذكر حماد بن إسحاق عن أبيه أن هذا الصوت منحول إلى معبد وأنه مما يشبه\nغناءه وذكر ابن الكلبي عن محمد بن يزيد أن معبدا أخذ لحن سائب خاثر في\n(أفاطم مهلا بعض هذا التدلل ... )\nغنى فيه\n(أمن آل ليلى بالملا متربع ... )","topic":"أخبار الأعشى ونسبه","topicNo":90,"sp":7,"spl":"الفتيان يتنادمون على قبره بمنفوحة","tags":[],"song":2,"loc":1656,"partialRef":{"sid":"b89-16","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b91-1","bab":"الجزء 9","sec":"نسب عمرو بن سعيد بن زيد وأخباره","page":"ج9 ص152","text":"هو عمرو بن سعيد بن زيد بن عمرو بن نفيل بن عبد العزى بن رياح بن عبد الله بن قرط بن رزاح بن عدي بن كعب بن لؤي بن غالب وسعيد بن زيد يكنى أبا الأعور وهو أحد العشرة الذين كانوا مع رسول الله على حراء فرجف بهم فقال اثبت حراء فليس عليك إلا نبي أو صديق أو شهيد\nأخبرني ابن أبي الأزهر قال حدثنا حماد بن إسحاق قال حدثني أبي قال حدثني الهيثم بن سفيان عن أبي مسكين قال جلس الوليد بن يزيد يوما للمغنين وكانوا متوافرين عنده وفيهم معبد وابن عائشة فقال لابن عائشة يا محمد قال لبيك يا أمير المؤمنين قال إني قد قلت شعرا فغن فيه قال وما هو فأنشده إياه وترنم به محمد ثم غناه فأحسن وهو\n\n(عللاني واسقياني ... من شراب أصبهاني)\n(من شراب الشيخ كسرى ... أو شراب القيروان)\n(إن في الكاس لمسكا ... أو بكفي من سقاني)\n(أو لقد غودر فيها ... حين صبت في الدنان)\n(كللاني توجاني ... وبشعري غنياني)\n(أطلقاني بوثاقي ... واشدداني بعناني)\n(إنما الكأس ربيع ... يتعاطى بالبنان)\n(وحميا الكأس دبت ... بين رجلي ولساني)\nلغناء لابن عائشة هزج بالبنصر من رواية حبش قال فأجاد ابن عائشة واستحسن غناءه من حضر فالتفت إلى معبد فقال كيف ترى يا أبا عباد فقال له معبد شنت غناءك بصلفك قال ابن عائشة يا أحول والله لولا أنك شيخنا وأنك في مجلس أمير المؤمنين لأعلمتك من الشائن لغنائه أنا بصلفي أم أنت بقبح وجهك وفطن الوليد بحركتهما فقال ما هذا فقال خير يا أمير المؤمنين لحن كان معبد طارحنيه فأنسيته فسألته عنه لأغني فيه أمير المؤمنين فقال وما هو قال\n(أمن آل ليلى بالملا متربع ... كما لاح وشم في الذراع مرجع)\nقال هات يا معبد فغناه إياه فاستحسنه الوليد وقال أنت والله سيد من غنى وهذا الخبر أيضا مما يدل على أن ما ذكره حماد من أن هذا الصوت منحول لمعبد لا حقيقة له أخبرني محمد بن إبراهيم قريض قال حدثني أحمد بن أبي العلاء المغني قال غنيت المعتضد صوتا في شعر له ثم أتبعته بشعر الوليد بن يزيد\n(كللاني توجاني ... وبشعري غنياني)\nفقال أحسن والله هكذا تقول الملوك المترفون وهكذا يطربون وبمثل هذا يشيرون وإليه يرتاحون أحسنت يا أحمد الاختيار لما شاكل الحال وأحسنت الغناء أعد فأعدته فأمر لي بعشرة آلاف درهم وشرب رطلا ثم استعاده فأعدته وفعل مثل ذلك حتى استعاده ست مرات وشرب ستة أرطال وأمر لي بعشرة آلاف درهم\nوقال مرة أخرى بستمائة دينار ثم سكر وما رئي قبل ذلك ولا بعده أعطى مغنيا هذه العطية وفي الخبر زيادة وقد ذكرته في موضع آخر يصلح له وقد\nذكر محمد بن الحسن الكاتب عن أحمد بن سهل النوشجاني أنه حضر أحمد بن أبي العلاء وقد غنى المعتضد هذا الصوت في هذا المجلس وأمر له بهذا المال بعينه ولم يشرح القصة كما شرحها أحمد","topic":"نسب عمرو بن سعيد بن زيد وأخباره","topicNo":91,"sp":0,"spl":"نسب عمرو بن سعيد بن زيد وأخباره — وهو المسمى مقطع الأثفار","tags":["الخمر"],"song":1,"loc":1657},
{"id":"b91-2","bab":"الجزء 9","sec":"ومنها صوت وهو المتبختر","page":"ج9 ص153","text":"(جعل الله جعفرا لك بعلا ... وشفاء من حادث الأوصاب)\n(إذ تقولين للوليدة قومي ... فانظري من ترين بالأبواب)\nلشعر للأحوص والغناء لمعبد - خفيف ثقيل - أول بالبنصر وذكر حماد عن أبيه في كتاب معبد أنه منحول إلى معبد وأنه لكردم","topic":"نسب عمرو بن سعيد بن زيد وأخباره","topicNo":91,"sp":0,"spl":"نسب عمرو بن سعيد بن زيد وأخباره — وهو المسمى مقطع الأثفار","tags":["الرواية والكتابة"],"song":1,"loc":1658},
{"id":"b91-3","bab":"الجزء 9","sec":"وهو المسمى مقطع الأثفار","page":"ج9 ص154","text":"(ضوء نار بدا لعينك أم شبت ... بذي الأثل من سلامة نار)\n(تلك بين الرياض والأثل والبانات ... منا ومن سلامة دار)\n(وكذاك الزمان يذهب بالناس ... وتبقى الرسوم والآثار)\nالشعر للأحوص والغناء لمعبد - خفيف ثقيل - بإطلاق الوتر في مجرى الوسطى عن إسحاق وذكر يونس أن فيه صوتين لمعبد وعمر الوادي رمل عن الهشامي وفيه لعبد الله بن العباس خفيف رمل بالوسطى","topic":"نسب عمرو بن سعيد بن زيد وأخباره","topicNo":91,"sp":0,"spl":"نسب عمرو بن سعيد بن زيد وأخباره — وهو المسمى مقطع الأثفار","tags":["اللهو والمزاح"],"loc":1659},
{"id":"b91-4","bab":"الجزء 9","sec":"الأحوص وموسى شهوات","page":"ج9 ص155","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثنا عمي قال مدح موسى شهوات أبا بكر بن عبد العزيز بن مروان بقصيدة أحسن فيها وأجاد وقال فيها\n(وكذاك الزمان يذهب بالناس ... وتبقى الديار والآثار)\nقام الأحوص ودخل منزله وقال قصيدة مدح فيها أبا بكر بن عبد العزيز أيضا وأتى فيها بهذا البيت بعينه وخرج فأنشدها فقال له موسى شهوات ما رأيت يا أحوص مثلك قلت قصيدة مدحت فيها الأمير فسرقت أجود بيت فيها وجعلته في قصيدتك فقال له الأحوص ليس الأمر كما ذكرت ولا البيت لي ولا لك هو للبيد سرقناه جميعا منه إنما ذكر لبيد قومه فقال\n(فعفا آخر الزمان عليهم ... فعلى آخر الزمان الدبار)\n(وكذاك الزمان يذهب بالناس ... وتبقى الرسوم والآثار)\nال فسكت موسى شهوات فلم يحر جوابا كأنما ألقمه حجرا ونسخت من كتاب أحمد بن سعيد الدمشقي خبر الأحوص مع سلامة التي ذكرها في هذا الشعر وهو موضوع لا أشك فيه لأن شعره المنسوب إلى الأحوص شعر ساقط سخيف لا يشبه نمط الأحوص والتوليد بين فيه يشهد على أنه محدث والقصة أيضا باطلة لا أصل لها ولكني ذكرته في موضعه على ما فيه من سوء العهدة\nقال حدثنا الزبير بن بكار قال حدثني أبو محمد الجزري قال كانت بالمدينة سلامة من أحسن الناس وجها وأتمهن عقلا وأحسنهن حديثا قد قرأت القرآن وروت الأشعار وقالت الشعر وكان عبد الرحمن بن حسان والأحوص بن محمد يختلفان إليها فيرويانها الشعر ويناشدانها إياه فعلقت الأحوص وصدت عن عبد الرحمن فقال لها عبد الرحمن يعرض لها بما ظنه من ذلك\n(أرى الإقبال منك على خليلي ... وما لي في حديثكم نصيب)\nأجابته\n(لأن الله علقه فؤادي ... فحاز الحب دونكم الحبيب)\nفقال الأحوص\n(خليلي لا تلمها في هواها ... ألذ العيش ما تهوى القلوب)\nال فأضرب عنها ابن حسان وخرج ممتدحا ليزيد بن معاوية فأكرمه وأعطاه فلما أراد الانصراف قال له يا أمير المؤمنين عندي نصيحة قال وما هي\nقال جارية خلفتها بالمدينة لامرأة من قريش من أجمل الناس وأكملهم وأعقلهم ولا تصلح أن تكون إلا لأمير المؤمنين وفي سماره فأرسل إليها يزيد فاشتريت له وحملت إليه فوقعت منه موقعا عظيما وفضلها على جميع من عنده وقدم عبد الرحمن المدينة فمر بالأحوص وهو قاعد على باب داره وهو مهموم فأراد أن يزيده إلى ما به فقال\n(يا مبتلى بالحب مفدوحا ... لاقى من الحب تباريحا)\n(ألجمه الحب فما ينثني ... إلا بكأس الشوق مصبوحا)\n(وصار ما يعجبه مغلقا ... عنه وما يكره مفتوحا)\n(قد حازها من أصبحت عنده ... ينال منها الشم والريحا)\n(خليفة الله فسل الهوى ... وعز قلبا منك مجروحا)\nأمسك الأحوص عن جوابه ثم إن شابين من بني أمية أرادا الوفادة إلى يزيد فأتاهما الأحوص فسألهما أن يحملا له كتابا ففعلا فكتب إليها معهما\n(سلام ذكرك ملصق بلساني ... وعلى هواك تعودني أحزاني)\n(ما لي رأيتك في المنام مطيعة ... وإذا انتبهت لججت في العصيان)\n(أبدا محبك ممسك بفؤاده ... يخشى اللجاجة منك في الهجران)\n(إن كنت عاتبة فإني معتب ... بعد الإساءة فاقبلي إحساني)\n(لا تقتلي رجلا يراك لما به ... مثل الشراب لغلة الظمآن)\n(ولقد أقول لقاطنين من آهلنا ... كانا على خلقي من الإخوان)\n(يا صاحبي على فؤادي جمرة ... وبرى الهوى جسمي كما تريان)\n(أمرقيان إلى سلامة أنتما ... ما قد لقيت بها وتحتسبان)\n(لا أستطيع الصبر عنها إنها ... من مهجتي نزلت بكل مكان)\nال ثم غلبه جزعه فخرج إلى يزيد ممتدحا له فلما قدم عليه قربه وأكرمه وبلغ لديه كل مبلغ فدست إليه سلامة خداما وأعطته مالا على أن يدخله إليها فأخبر الخادم يزيد بذلك فقال امض برسالتها ففعل ما أمره به وأدخل الأحوص وجلس يزيد بحيث يراهما فلما بصرت الجارية بالأحوص بكت إليه وبكى إليها وأمرت فألقي له كرسي فقعد عليه وجعل كل واحد منهما يشكو إلى صاحبه شدة الشوق فلم يزالا يتحدثان إلى السحر ويزيد يسمع كلامهما من غير أن تكون بينهما ريبة حتى إذا هم بالخروج قال\n(أمسى فؤادي في هم وبلبال ... من حب من لم أزل منه على بال)\nفقالت\n(صحا المحبون بعد النأي إذ يئسوا ... وقد يئست وما أصحوا على حال)\nقال\n(من كان يسلو بيأس عن أخي ثقة ... فعن سلامة ما أمسيت بالسالي)\nقالت\n(والله والله لا أنساك يا سكني ... حتى يفارق مني الروح أوصالي)\nقال","topic":"نسب عمرو بن سعيد بن زيد وأخباره","topicNo":91,"sp":1,"spl":"الأحوص وموسى شهوات","tags":["الحب والغزل"],"loc":1660},
{"id":"b91-5","bab":"الجزء 9","sec":"الأحوص وموسى شهوات","page":"ج9 ص155","text":"(والله ما خاب من أمسى وأنت له ... يا قرة العين في أهل وفي مال)\nثم ودعها وخرج فأخذه يزيد ودعا بها فقال أخبراني عما كان جرى بينكما في ليلتكما واصدقاني فأخبراه وأنشداه ما قالاه فلم يخرما حرفا ولا غيرا شيئا مما سمعه فقال له يزيد أتحبها يا أحوص قال إي والله يا أمير المؤمنين\n(حبا شديدا تليدا غير مطرف ... بين الجوانح مثل النار يضطرم)\nقال لها أتحبينه قالت نعم يا أمير المؤمنين\n(حبا شديدا جرى كالروح في جسدي ... فهل يفرق بين الروح والجسد)\nقال يزيد إنكما لتصفان حبا شديدا خذها يا أحوص فهي لك ووصله بصلة سنية وانصرف بها وبالجارية إلى الحجاز وهو من أقر الناس عينا مضى الحديث","topic":"نسب عمرو بن سعيد بن زيد وأخباره","topicNo":91,"sp":2,"spl":"الأحوص وموسى شهوات — مدن معبد","tags":["الجواري والنساء","السفر والحج"],"loc":1661},
{"id":"b91-6","bab":"الجزء 9","sec":"مدن معبد","page":"ج9 ص159","text":"أصوات معبد المسماة مدن معبد وتسمى أيضا حصون معبد أخبرني ابن أبي الأزهر والحسين بن يحيى عن حماد بن إسحاق عن أبيه قال حسين في خبره واللفظ له عن إسماعيل بن جامع عن يونس الكاتب قال قال معبد وقد سمع رجلا يقول إن قتيبة بن مسلم فتح سبعة حصون\nأو سبع مدن بخراسان فيها سبعة حصون صعبة المرتقى والمسالك لم يوصل إليها قط فقال والله لقد صنعت سبعة ألحان كل لحن منها أشد من فتح تلك الحصون فسئل عنها فقال\n(لعمري لئن شطت بعثمة دارها ... )\n(و : هريرة ودعها وإن لام لائم ... )\n(و : رأيت عرابة الأوسي يسمو ... )\n(و : كم بذاك الحجون من حي صدق ... )\n(و : لو تعلمين الغيب أيقنت أنني ... )\n(و : يا دار عبلة بالجواء تكلمي ... )\n(و : ودع هريرة إن الركب مرتحل ... )\nمن الناس من يروي مدن معبد\n(تقطع من ظلامة الوصل أجمع ... )\n(و : خمصانة قلق موشحها ... )\n(و : يوم تبدي لنا قتيلة ... )\nكان\n(كم بذاك الحجون من حي صدق ... )\n(و : لو تعلمين الغيب أيقنت أنني ... )\n(و : يا دار عبلة بالجواء تكلمي ... )\nسبة هذه الأصوات وأخبارها\n(لعمري لئن شطت بعثمة دارها ... لقد كدت من وشك الفراق أليح)\n(أروح بهم ثم أغدو بمثله ... ويحسب أني في الثياب صحيح)\nروضه من الطويل شطت بعدت ووشك الفراق دنوه وسرعته وأليح أشفق وأجزع الشعر لعبيد الله بن عبد الله بن عتبة الفقيه والغناء لمعبد - خفيف ثقيل - أول بالخنصر في مجرى البنصر من رواية يونس وإسحاق وعمرو وغيرهم وفيه رمل يقال إنه لابن سريج","topic":"نسب عمرو بن سعيد بن زيد وأخباره","topicNo":91,"sp":2,"spl":"الأحوص وموسى شهوات — مدن معبد","tags":["اللهو والمزاح"],"song":1,"loc":1662,"partialRef":{"sid":"b13-2","gi":2,"vi":4,"side":0},"partial":1},
{"id":"b92-1","bab":"الجزء 9","sec":"ذكر عبيد الله بن عبد الله ونسبه","page":"ج9 ص162","text":"هو عبيد الله بن عبد الله بن عتبة بن مسعود بن غافل بن حبيب بن شمخ بن فأر بن مخزوم بن صاهلة بن كاهل بن الحارث بن تميم بن سعد بن هذيل بن مدركة بن الياس بن مضر بن نزار وهو في حلفاء بني زهرة من قريش وعداده فيهم وعتبة بن مسعود وعبد الله بن مسعود البدري صاحب رسول الله أخوان ولعتبة صحبة بالنبي وليس من البدريين وكان ابنه عبد الله أبو عبيد الله بن عبد الله رجلا صالحا واستعمله عمر بن الخطاب فأحمده ولعبيد الله بن عبد الله أخوان عون وعبد الرحمن وكان عون من أهل الفقه والأدب وكان يقول بالإرجاء ثم رجع عنه وقال وكان شاعرا\n(فأول ما أفارق غير شك ... أفارق ما يقول المرجئونا)\n(وقالوا مؤمن من آل جور ... وليس المؤمنون بجائرينا)\n(وقالوا مؤمن دمه حلال ... وقد حرمت دماء المؤمنينا)\nوخرج مع ابن الأشعث فلما هزم هرب وطلبه الحجاج فأتى محمد بن مروان بن الحكم بنصيبين فأمنه وألزمه ابنيه مروان بن محمد وعبد الرحمن بن محمد فقال له كيف رأيت ابني أخيك قال أما عبد الرحمن فطفل وأما مروان فإني إن أتيته حجب وإن قعدت عنه عتب وإن عاتبته صخب وإن صاحبته غضب ثم تركه ولزم عمر بن عبد العزيز فلم يزل معه ذكر ذلك كله ومعانيه الأصمعي عن أبي نوفل الهذلي عن أبيه ولعون يقول جرير\n(يا أيها القارئ المرخي عمامته ... هذا زمانك إني قد مضى زمني)\n(أبلغ خليفتنا إن كنت لاقيه ... أني لدى الباب كالمصفود في قرن)\nخبره يأتي في أخبار جرير وأما عبد الرحمن فلم تكن له نباهة أخويه وفضلهما فسقط ذكره","topic":"ذكر عبيد الله بن عبد الله ونسبه","topicNo":92,"sp":0,"spl":"ذكر عبيد الله بن عبد الله ونسبه","tags":["اللهو والمزاح","السفر والحج","الوصف والطبيعة"],"loc":1663},
{"id":"b92-2","bab":"الجزء 9","sec":"بعض من صفاته","page":"ج9 ص163","text":"وأما عبيد الله فإنه أحد وجوه الفقهاء الذين روي عنهم الفقه والحديث\nوهو أحد السبعة من أهل المدينة وهم القاسم بن محمد بن أبي بكر الصديق وعروة بن الزبير وأبو بكر بن عبد الرحمن بن الحارث بن هشام وسعيد بن المسيب وعبيد الله بن عبد الله بن عتبة وخارجة ابن زيد بن ثابت وسليمان بن يسار وكان عبيد الله ضريرا وقد روى عن جماعة من وجوه الصحابة مثل ابن عباس وعبد الله ابن مسعود عمه وأبي هريرة وروى عنه الزهري وابن أبي الزناد وغيرهما من نظرائهما وكان عبد الله بن عباس يقدمه ويؤثره\nأخبرني محمد بن خلف وكيع قال حدثنا عبد الله بن أحمد بن حنبل قال حدثنا أبي قال حدثنا يونس بن محمد قال حدثنا حماد بن زيد عن معمر عن الزهري\nقال كان عبيد الله بن عبد الله يلطف لابن عباس فكان يعزه عزا أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار عن محمد بن الحسن عن مالك بن أنس عن ابن شهاب الزهري\nقال كنت أخدم عبيد الله بن عبد الله بن عتبة حتى إن كنت لأستقي الماء الملح وإن كان ليسأل جاريته فتقول غلامك الأعمش أخبرني وكيع قال حدثنا محمد بن عبد الملك بن زنجويه\nقال حدثنا عبد الرزاق عن معمر عن الزهري قال أدركت اربعة بحور عبيد الله بن عبد الله أحدهم أخبرني وكيع قال حدثنا محمد قال حدثنا حامد بن يحيى عن ابن عيينة عن الزهري\nقال سمعت من العلم شيئا كثيرا فلما لقيت عبيد الله بن عبد الله كأني كنت في شعب من الشعاب فوقعت في الوادي وقال مرة صرت كأني لم أسمع من العلم شيئا أخبرني وكيع قال حدثني بشر بن موسى قال حدثنا الحميدي عن ابن عيينة عن علي بن زيد بن جدعان قال كان عمر بن عبد العزيز يقول ليت لي مجلسا من عبيد الله بن عبد الله بن عتبة بدية أخبرني وكيع قال حدثنا أحمد بن عبد الرحمن بن وهب قال حدثني عمي عن يعقوب بن عبد الرحمن الزهري عن حمزة بن عبد الله قال\nقال عمر بن عبد العزيز لو كان عبيد الله بن عبد الله بن عتبة حيا ما صدرت إلا عن رأيه ولوددت أن لي بيوم من عبيد الله غرما قال ذلك في خلافته أخبرنا محمد بن جرير الطبري وعم أبي عبد العزيز بن أحمد ومحمد ابن العباس اليزيدي والطوسي ووكيع والحرمي بن أبي العلاء وطاهر بن عبد الله الهاشمي قالوا\nحدثنا الزبير بن بكار قال حدثنا إبراهيم بن طلحة بن عبد الله بن عبد الرحمن بن أبي بكر الصديق وابن أخيه يحيى بن محمد بن طلحة جميعا عن عثمان بن عمر بن موسى عن الزهري\nقال دخل عروة بن الزبير وعبيد الله بن عبد الله بن عتبة على عمر بن عبد العزيز وهو أمير المدينة فقال عروة لشيء حدث به من ذكر عائشة وعبد الله بن الزبير سمعت عائشة تقول ما أحببت أحدا حبي عبد الله بن الزبير لا أعني رسول الله ولا أبوي فقال عمر إنكم لتنتحلون عائشة لابن الزبير انتحال من لا يرى لكل مسلم معه فيها نصيبا فقال عروة بركة عائشة كانت أوسع من ألا يرى لكل مسلم فيها حق ولقد كان عبد الله منها بحيث وضعته الرحم والمودة التي لا يشرك كل واحد منهما فيه عند صاحبه أحد فقال عمر كذبت فقال عروة هذا عبيد الله بن عبد الله بن عتبة بن مسعود يعلم أني غير كاذب وإن من أكذب الكاذبين من كذب الصادقين فسكت عبيد الله ولم يدخل بينهما في شيء فأفف بهما عمر وقال اخرجا عني ثم لم يلبث أن بعث إلى عبيد الله بن عبد الله رسولا يدعوه لبعض ما كان يدعوه إليه فكتب إليه عبيد الله\n(لعمر ابن ليلى ابن عائشة التي ... لمروان أدته أب غير زمل)\n(لو أنهم عما وجدا ووالدا ... تأسوا فسنوا سنة المتعطل)\n(عذرت أبا حفص وإن كان واحدا ... من القوم يهدي هديهم ليس يأتلي)\n(ولكنهم فاتوا وجئت مصليا ... تقرب إثر السابق المتمهل)\n(وعمت فإن تسبق فضنء مبرز ... جواد وإن تسبق فنفسك فاعذل)\n(فمالك بالسلطان أن تحمل القذى ... جفون عيون بالقذى لم تكحل)\n(وما الحق أن تهوى فتسعف بالذي ... هويت إذا ما كان ليس بأعدل)\n(أبى الله والأحساب أن ترأم الخنا ... نفوس كرام بالخنا لم توكل)\nقال الزبير في خبره وحده الضنء والضنء الولد قال وأنشد الخليل بن أسد قال أنشدني دهثم\n(ابن عجوز ضنؤها غير أمر ... لو نحرت في بيتها عشر جزر)\n(لأصبحت من لحمهن تعتذر ... تغدو على الحي بعود من سمر)\n(حتى يفر أهلها كل مفر ... )","topic":"ذكر عبيد الله بن عبد الله ونسبه","topicNo":92,"sp":1,"spl":"بعض من صفاته","tags":["اللهو والمزاح","السفر والحج"],"loc":1664,"partial":1},
{"id":"b92-3","bab":"الجزء 9","sec":"بعض من صفاته","page":"ج9 ص163","text":"خبرني الحسن بن علي ووكيع قالا حدثنا أحمد بن زهير قال حدثنا الزبير وأخبرناه الحرمي بن أبي العلاء إجازة قال حدثنا الزبير عن ابن أبي أويس عن بكار بن حارثة عن عبد الرحمن بن أبي الزناد عن هشام بن عروة إن عبيد الله بن عبد الله جاء إلى عمر بن عبد العزيز فاستأذن عليه فرده الحاجب وقال له عنده عبد الله بن عمرو بن عثمان بن عفان وهو مختل\nبه فانصرف غضبان وكان في صلاحه ربما صنع الأبيات فقال لعمر\n(أبن لي فكن مثلي أو ابتغ صاحبا ... كمثلك إني تابع صاحبا مثلي)\n(عزيز إخائي لا ينال مودتي ... من الناس إلا مسلم كامل العقل)\n(وما يلبث الفتيان أن يتفرقوا ... إذا لم يؤلف روح شكل إلى شكل)\nال فأخبر عمر بأبياته فبعث إليه أبا بكر بن سليمان بن أبي خيثمة وعراك بن مالك يعذرانه عنده ويقولان إن عمر يقسم بالله ما علم بأبياتك ولا برد الحاجب إياك فعذره قال الزبير وقد أنشدني محمد بن الحسن قال أنشدني محرز بن جعفر لعبيد الله بن عبد الله هذه الأبيات وزاد فيها وهو أولها\n(وإني امرؤ من يصفني الود يلفني ... وإن نزحت دار به دائم الوصل)\n(عزيز إخائي لا ينال مودتي ... من الناس إلا مسلم كامل العقل)\n(ولولا اتقائي الله قلت قصيدة ... تسير بها الركبان أبردها يغلي)\n(بها تنقض الأحلاس في كل منزل ... وينفي الكرى عنه بها صاحب الرحل)\n(كفاني يسير إذ أراك بحاجتي ... كليل اللسان ما تمر وما تحلي)\n(تلاوذ بالأبواب مني مخافة الملامة ... والإخلاف شر من البخل)\nوذكر الأبيات الأول بعد هذه","topic":"ذكر عبيد الله بن عبد الله ونسبه","topicNo":92,"sp":2,"spl":"بعض من صفاته — شعره في عراك بن مالك وابن حزم","tags":["اللهو والمزاح","السفر والحج"],"loc":1665},
{"id":"b92-4","bab":"الجزء 9","sec":"شعره في عراك بن مالك وابن حزم","page":"ج9 ص168","text":"أخبرني وكيع قال حدثني علي بن حرب الموصلي قال حدثنا إسماعيل ابن ريان الطائي قال سمعت ابن إدريس يقول\nكان عراك بن مالك وأبو بكر بن حزم وعبيد الله بن عبد الله بن عتبة يتجالسون بالمدينة زمانا ثم إن ابن حزم ولي إمرتها وولي عراك القضاء وكانا يمران بعبيد الله فلا يسلمان عليه ولا يقفان وكان ضريرا فأخبر بذلك فأنشأ يقول\n(ألا أبلغا عني عراك بن مالك ... ولا تدعا أن تثنيا بأبي بكر)\n(فقد جعلت تبدو شواكل منكما ... كأنكما بي موقران من الصخر)\n(وطاوعتما بي داعكا ذا معاكة ... لعمري لقد أزرى وما مثله يزري)\n(ولولا اتقائي ثم بقياي فيكما ... للمتكما لوما أحر من الجمر)\n\n(فمسا تراب الأرض منها خلقتما ... ومنها المعاد والمصير إلى الحشر)\n(ولا تأنفا أن تسألا وتسلما ... فما خشي الإنسان شرا من الكبر)\n(فلو شئت أن ألفي عدوا وطاعنا ... لألفيته أو قال عندي في السر)\n(فإن أنا لم آمر ولم أنه عنكما ... ضحكت له حتى يلج ويستشري)\nروضه من الطويل غني في\n(فمسا تراب الأرض منها خلقتما ... )\nالذي بعده لحن من الثقيل الأول بالبنصر من رواية عمرو بن بانة\nوابن المكي ويونس وغيرهم وزعم ابن شهاب الزهري أن عبيد الله قال هذه الأبيات في عمر بن عبد العزيز وعمرو بن عثمان يعني أن الأبيات الأول ليست منها في شيء وإنما أدخلت فيها لاتفاق الروي والقافية\nأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا إبراهيم ابن المنذر الحزامي قال حدثنا إبراهيم بن محمد بن عبد العزيز عن أبيه عن ابن شهاب\nقال جئت عبيد الله بن عبد الله يوما في منزله فوجدته ينفخ وهو مغتاظ فقلت له مالك قال جئت أميركم آنفا يعني عمر بن عبد العزيز فسلمت عليه وعلى عبد الله بن عمرو بن عثمان فلم يردا علي فقلت\n(فمسا تراب الأرض منها خلقتما ... )\nذكر الأبيات الأربعة قال فقلت له رحمك الله أتقول الشعر في فضلك ونسكك قال إن المصدور إذا نفث برأ قال أبو زيد حدثنا إبراهيم بن المنذر وأنشدني هذه الأبيات عبد العزيز ابن أبي ثابت عن ابن أبي الزناد له وذكر مثل ذلك وأنها في عمر بن عبد العزيز وعبد الله بن عمرو وزاد فيها\n(وكيف يريدان ابن تسعين حجة ... على ما أتى وهو ابن عشرين أو عشر)","topic":"ذكر عبيد الله بن عبد الله ونسبه","topicNo":92,"sp":2,"spl":"بعض من صفاته — شعره في عراك بن مالك وابن حزم","tags":["اللهو والمزاح"],"song":1,"loc":1666,"partial":1},
{"id":"b92-5","bab":"الجزء 9","sec":"بعض من شعره الجيد","page":"ج9 ص171","text":"ولعبيد الله بن عبد الله شعر فحل جيد ليس بالكثير منه قوله\n(إذا كان لي سر فحدثته العدا ... وضاق به صدري فللناس أعذر)\n(وسرك ما استودعته وكتمته ... وليس بسر حين يفشو ويظهر)\nقوله لابن شهاب الزهري\n(إذا قلت أما بعد لم يثن منطقي ... فحاذر إذا ما قلت كيف أقول)\n(إذا شئت أن تلقى خليلا مصافيا ... لقيت وإخوان الثقات قليل)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني عبد الجبار ابن سعيد المساحقي عن ابن أبي الزناد عن أبيه قال أنشد عبيد الله بن عبد الله جامع بن مرخية الكلابي لنفسه\n(لعمر أبي المحصين أيام نلتقي ... لما لا نلاقيها من الدهر أكثر)\n(يعدون يوما واحدا إن أتيتها ... وينسون ما كانت على الدهر تهجر)\n(وإن أولع الواشون عمدا بوصلنا ... فنحن بتجديد المودة أبصر)\nال فأعجبت أبياته هذه جامعا فسر ذلك عبيد الله فكساه وحمله جامع بن مرخية هذا من شعراء الحجاز وهو الذي يقول\n(سألت سعيد بن المسيب مفتي المدينة ... هل في حب ظمياء من وزر)\n(فقال سعيد بن المسيب إنما ... تلام على ما تستطيع من الأمر)\nبلغ قوله سعيدا فقال كذب والله ما سألني ولا أفتيته بما قال أخبرني بذلك الحرمي بن أبي العلاء عن الزبير ومن جيد شعر عبيد الله وسهله\n(أعاذل عاجل ما أشتهي ... أحب من الآجل الرائث)\n(سأنفق مالي على لذتي ... وأوثر نفسي على الوارث)\n(أبادر إهلاك مستهلك ... لمالي أو عبث العابث)\nقوله يفتخر في أبيات\n(إذا هي حلت وسط عوذ ابن غالب ... فذلك ود نازح لا أطالعه)\n(شددت حيازيمي على قلب حازم ... كتوم لما ضمت عليه أضالعه)\n(أداجي رجالا لست مطلع بعضهم ... على سر بعض إن صدري واسعه)\n(بني لي عبد الله في ذروة العلا ... وعتبة مجدا لا تنال مصانعه)\nقوله فيه غناء\n(إن يك الدهر قد أضر بنا ... من غير ذحل فربما نفعا)\n(أبكي على ذلك الزمان ولا ... أحسب شيئا قد فات مرتجعا)\n(إذ نحن في ظل نعمة سلفت ... كانت لها كل نعمة تبعا)\nروضه من المنسرح غنت فيها عريب خفيف رمل عن الهشامي حدثنا محمد بن جرير الطبري والحرمي بن أبي العلاء ووكيع قالوا\nحدثنا الزبير بن بكار قال حدثني إسماعيل بن يعقوب عن ابن أبي الزناد عن أبيه قال قدمت المدينة امرأة من ناحية مكة من هذيل وكانت جميلة فخطبها الناس وكادت تذهب بعقول أكثرهم فقال فيها عبيد الله بن عبد الله ابن عتبة\n(أحبك حبا لو علمت ببعضه ... لجدت ولم يصعب عليك شديد)\n(وحبك يا أم الصبي مدلهي ... شهيدي أبو بكر وأي شهيد)\n(ويعلم وجدي القاسم بن محمد ... وعروة ما ألقى بكم وسعيد)\n(ويعلم ما أخفي سليمان علمه ... وخارجة يبدي لنا ويعيد)\n(متى تسألي عما أقول فتخبري ... فللحب عندي طارف وتليد)\nبلغت أبياته سعيد بن المسيب فقال والله لقد أمن أن تسألنا وعلم أنها لو استشهدت بنا لم نشهد له بالباطل عندها وقال الزبير أبو بكر الذي ذكر والنفر المسمون معه أبو بكر بن عبد الرحمن بن الحارث بن هشام والقاسم بن محمد بن أبي بكر وعروة بن الزبير وسعيد بن المسيب وسليمان بن يسار وخارجة بن زيد بن ثابت وهم الفقهاء الذين أخذ عنهم أهل المدينة","topic":"ذكر عبيد الله بن عبد الله ونسبه","topicNo":92,"sp":3,"spl":"بعض من شعره الجيد","tags":["الجواري والنساء"],"song":1,"loc":1667},
{"id":"b92-6","bab":"الجزء 9","sec":"شعره في عثمة","page":"ج9 ص173","text":"أخبرني وكيع قال حدثني عمر بن محمد بن عبد الملك الزيات عن أحمد بن سعيد الفهري عن إبراهيم بن المنذر بن عبد الملك بن الماجشون أن أبيات عبيد الله بن عبد الله بن عتبة التي أولها\n(لعمري لئن شطت بعثمة دارها ... لقد كدت من وشك الفراق أليح)\nقالها في زوجة له كانت تسمى عثمة فعتب عليها في بعض الأمر فطلقها وله فيها أشعار كثيرة منها هذه الأبيات ومنها قوله يذكر ندمه على طلاقها\n(كتمت الهوى حتى أضر بك الكتم ... ولامك أقوام ولومهم ظلم)\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال قال لي عمي لقيني علي بن صالح فأنشدني بيتا وسألني من قائله وهل فيه زيادة فقلت لا أدري وقد قدم ابن أخي أعنيك وقلما فاتني شيء إلا وجدته عنده قال الزبير فأنشدني عمي البيت وهو\n(غراب وظبي أعضب القرن ناديا ... بصرم وصردان العشي تصيح)\nقلت له قائله عبيد الله بن عبد الله بن عتبة وتمامها\n(لعمري لئن شطت بعثمة دارها ... لقد كدت من وشك الفراق أليح)\n(أروح بهم ثم أغدو بمثله ... ويحسب أني في الثياب صحيح)\nفكتبهما عمي عني وانصرف بهما إليه\n(ألا من لنفس لا تموت فينقضي ... عناها ولا تحيا حياة لها طعم)\n(أأترك إتيان الحبيب تأثما ... ألا إن هجران الحبيب هو الإثم)\n(فذق هجرها قد كنت تزعم أنه ... رشاد ألا يا ربما كذب الزعم)\nروضه من الطويل غنى يونس في هذه الأبيات الثلاثة لحنا ماخوريا\nوهو خفيف الثقيل الثاني من رواية إسحاق ويونس وابن المكي وغيرهم وغنت عريب في\n(أأترك إتيان الحبيب تأثما ... )\nحنا من الثقيل الأول وأضافت إليه بعده على الولاء بيتين ليسا من هذا الشعر وهما\n(وأقبل أقوال الوشاة تجرما ... ألا إن أقوال الوشاة هي الجرم)\n(وأشتاق لي إلفا على قرب داره ... لأن ملاقاة الحبيب هي الغنم)\nمما قاله عبيد الله أيضا في زوجته هذه وغني فيه\n(عفت أطلال عثمة بالغميم ... فأضحت وهي موحشة الرسوم)\n(وقد كنا نحل بها وفيها ... هضيم الكشح جائلة البريم)\nعروضه من الوافر عفت درست والأطلال ما شخص من آثار الديار والرسوم ما لم يكن له شخص منها ولا ارتفاع وإنما هو أثر والهضيم الكشح الخميص الحشى والبطن والبريم الخلخال وقيل بل هو اسم لكل ما يلبس من الحلي في اليدين والرجلين والجائل ما يجول في موضعه لا يستقر غنى في هذين البيتين قفا النجار ولحنه من القدر الأوسط من الثقيل الأول بالخنصر في مجرى البنصر ومما قاله في زوجته عثمة وفيها غناء\n\n(تغلغل حب عثمة في فؤادي ... فباديه مع الخافي يسير)\n(تغلغل حيث لم يبلغ شراب ... ولا حزن ولم يبلغ سرور)\n(صدعت القلب ثم ذررت فيه ... هواك فليم والتأم الفطور)\n(أكاد إذا ذكرت العهد منها ... أطير لو أن إنسانا يطير)\n(غني النفس أن أزداد حبا ... ولكني إلى صلة فقير)\n(وأنفذ جارحاك سواد قلبي ... فأنت علي ما عشنا أمير)\nمعبد في الأول والثاني من الأبيات هزج بالبنصر عن حبش وذكر أحمد بن عبيد الله أنه منحول من المكي وفي الثالث ثم الثاني لأبي عيسى ابن الرشيد رمل\nقال ابن أبي الزناد في الخبر الذي تقدم ذكره عن عبيد الله وما قاله من الشعر في عثمة وغيرها فقيل له أتقول في مثل هذا قال في اللدود راحة المفؤود\nأخبرني وكيع قال حدثنا أحمد بن عبد الرحمن قال حدثنا ابن وهب عن يعقوب يعني ابن عبد الرحمن عن أبيه قال كان رجل يأتي عبيد الله بن عبد الله ويجلس إليه فبلغ عبيد الله أنه يقع ببعض أصحاب رسول الله فجاءه الرجل فلم يلتفت إليه عبيد الله وكان الرجل شديد العقل فقال له يا أبا محمد إن لك لشأنا فإن رأيت لي عذرا فأقبل عذري فقال له أتتهم الله في علمه قال أعوذ بالله قال أتتهم رسول الله في حديثه قال أعوذ بالله قال يقول الله عز و جل\n(لقد رضي الله عن المؤمنين إذ يبايعونك تحت الشجرة ... )\nوأنت تقع في فلان وهو ممن بايع فهل بلغك أن الله سخط عليه بعد أن رضي عنه قال والله لا أعود أبدا قال والرجل عمر بن عبد العزيز أخبرني وكيع عن أحمد بن زهير عن يحيى بن معين قال مات عبيد الله بن عبد الله بن عتبة سنة اثنتين ومائة ويقال سنة تسع وتسعين أخبرني محمد بن جرير الطبري والحسن بن علي عن الحارث عن ابن سعد عن معن عن محمد بن هلال أن عبيد الله توفي بالمدينة سنة ثمان وتسعين ومنها\n(ودع هريرة إن الركب مرتحل ... وهل تطيق وداعا أيها الرجل)","topic":"ذكر عبيد الله بن عبد الله ونسبه","topicNo":92,"sp":4,"spl":"شعره في عثمة","tags":["الحب والغزل"],"song":4,"loc":1668,"partial":1},
{"id":"b92-7","bab":"الجزء 9","sec":"شعره في عثمة","page":"ج9 ص173","text":"(غراء فرعاء مصقول عوارضها ... تمشي الهوينى كما يمشي الوجي الوحل)\n(تسمع للحلي وسواسا إذا انصرفت ... كما استعان بريح عشرق زجل)\n(علقتها عرضا وعلقت رجلا ... غيري وعلق أخرى غيرها الرجل)\n(قالت هريرة لما جئت زائرها ... ويلي عليك وويلي منك يا رجل)\n(لم تمش ميلا ولم تركب على جمل ... ولم تر الشمس إلا دونها الكلل)\n(أقول للركب في درنى وقد ثملوا ... شيموا وكيف يشيم الشارب الثمل)\n(كناطح صخرة يوما ليفلقها ... فلم يضرها وأوهى قرنه الوعل)\n(أبلغ يزيد بني شيبان مألكة ... أبا ثبيت أما تنفك تأتكل)\n(إن تركبوا فركوب الخيل عادتنا ... أو تنزلون فإنا معشر نزل)\n(وقد غدوت إلى الحانوت يتبعني ... شاو نشول مشل شلشل شول)\n(في فتية كسيوف الهند قد علموا ... أن ليس يدفع عن ذي الحيلة الحيل)\n(نازعتهم قضب الريحان متكئا ... وقهوة مزة راووقها خضل)\nنى معبد في الأول والثاني في لحنه المذكور من مدن معبد لحنا من القدر الأوسط من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق وذكرت دنانير أن فيهما لابن سريج أيضا صنعة ولمعبد أيضا في الرابع والخامس والثالث ثقيل أول ذكره حبش\nوقيل بل هو لحن ابن سريج وذلك الصحيح ولابن محرز في الثقيل في إن تركبوا وفي كناطح صخرة ثاني ثقيل مطلق في مجرى الوسطى عن إسحاق ولحنين الحيري في أبلغ يزيد بني شيبان وإن تركبوا ثاني ثقيل آخر وذكر أحمد بن\nالمكي أن لابن محرز في ودع هريرة وتسمع للحلي ثاني ثقيل بالخنصر في مجرى البنصر وفي وقد غدوت وما بعده رمل لابن سريج ومخارق عن الهشامي ولابن سريج في تسمع للحلي وقبله ودع هريرة رمل بالسبابة في مجرى البنصر عن إسحاق وللغريض في قالت هريرة وعلقتها عرضا رمل وفي هذه الأبيات بعينها هزج ينسب إليه أيضا وإلى غيره وفي تسمع للحلي وقالت هريرة هزج لمحمد بن حسن بن مصعب وفي لم تمش ميلا وأقول للركب لابن سريج خفيف الثقيل الأول بالبنصر عن حبش وفي قالت هريرة وتسمع للحلي لحن لابن سريج وإن لحنين في البيتين الآخرين لحنا آخر وقد مضت أخبار هريرة مع الأعشى في\n(هريرة ودعها وإن لام لائم ... )\nأخبرني الحسين بن يحيى عن حماد عن أبيه عن الأصمعي قال قلت لأعرابية ما الغراء قالت التي بين حاجبيها بلج وفي جبهتها اتساع تتباعد قصتها معه عن حاجبيها فيكون بينهما نفنف\nوقال أبو عبيدة الفرعاء الكثيرة الشعر والعوارض الأسنان والهويني تصغير الهونى والهونى مؤنث الأهون والوجي الظالع وهو الذي قد حفي فليس يكاد يستقل على رجله والوحل الذي قد وقع في الوحل والعشرق نبت يبس فتحركه الريح شبه صوت حليها بصوته الزجل المصوت من العشرق وعلقتها أجببتها وعرضا على غير موعد الوعل التيس الجبلي والجمع أوعال مألكة رسالة والجمع مآلك ما تنفك ما تزال وتأتكل تتحرق وقال أبو عبيدة الشاوي الذي يشوي اللحم والنشول الذي ينشل اللحم من\nالقدر ومشل سواق سريع يسوق به وشلشل خفيف وشول طيب الريح","topic":"ذكر عبيد الله بن عبد الله ونسبه","topicNo":92,"sp":5,"spl":"شعره في عثمة","tags":[],"loc":1669,"partialRef":{"sid":"b88-6","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b92-9","bab":"الجزء 9","sec":"خلاف بني كعب وبني همام — يوم عين محلم","page":"ج9 ص179 – ج9 ص180","text":"الشعر للأعشى وقد تقدم نسبه وأخباره يقول هذه القصيدة ليزيد بن مسهر أبي ثابت الشيباني قال أبو عبيدة وكان من حديث هذه القصيدة أن رجلا من بني كعب بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبة يقال له ضبيع قتل رجلا من بني همام يقال له زاهر بن سيار بن أسعد بن همام بن مرة بن ذهل بن شيبان وكان ضبيع مطروقا ضعيف العقل فنهاهم يزيد بن مسهر أن يقتلوا ضبيعا بزاهر\nوقال اقتلوا به سيدا من بني سعد بن مالك بن ضبيعة فحض بني سيار بن أسعد على ذلك وأمرهم به وبلغ بني قيس ما قاله فقال الأعشى هذه الكلمة يأمره أن يدع بني سيار وبني كعب ولا يعين بني سيار فإنه إن أعانهم أعانت قبائل بني قيس بن كعب وحذرهم أن تلقى شيبان منهم مثل ما لقوا يوم العين عين محلم بهجر\nقال أبو عبيدة وكان من حديث ذلك اليوم كما زعم عمر بن هلال أحد بني سعد بن قيس بن ثعلبة أن يزيد بن مسهر كان خالع أصرم بن عوف ابن ثعلبة بن سعد بن قيس بن ثعلبة وكان عوف أبو بني الأصرم يقال له\nالأعجف والضيعة له وهي قرية باليمامة فلما خلع يزيد أصرم من ماله خالعه على أن يرهنه ابنيه أفلت وشهابا ابني أصرم وأمهما فطيمة بنت شرحبيل بن عوسجة بن ثعلبة بن سعد بن قيس وأن يزيد قمر أصرم فطلب أن يدفع إليه ابنيه رهينة فأبت أمهما وأبى يزيد إلا أخذهما فنادت قومها فحضر الناس للحرب فاشتملت فطيمة على ابنيها بثوبها وفك قومها عنها وعنهما فذلك قول الأعشى\n(نحن الفوارس يوم العين ضاحية ... جنبي فطيمة لا ميل ولا عزل)\nال فانهزمت بنو شيبان فحذر الأعشى أن يلقى مسهر مثل تلك الحال قال أبو عبيدة وذكر عامر ومسمع عن قتادة الفقيه أن رجلين من بني مروان تنازعا في هذا الحديث فجردا رسولا في ذلك إلى العراق حتى قدم إلى الكوفة فسأل فأخبر أن فطيمة من بني سعد بن قيس كانت عند رجل من بني شيبان وكانت له زوجة أخرى من بني شيبان فتعايرتا فعمدت الشيبانية فحلت ذوائب فطيمة فاهتاج الحيان فاقتتلوا فهزمت بنو شيبان يومئذ أخبرنا محمد بن خلف وكيع\nقال حدثنا أحمد بن محمد القصير قال حدثنا محمد بن صالح قال حدثني أبو اليقظان قال حدثني جويرية عن يشكر ابن وائل اليشكري وكان من علماء بكر بن وائل وولد أيام مسيلمة فجيء\nبه إليه فمسح على رأسه فعمي قال جويرية فحدثني يشكر هذا قال حدثني جرير بن عبد الله البجلي قال سافرت في الجاهلية فأقبلت على بعيري ليلة أريد أن أسقيه فجعلت أريده على أن يتقدم فوالله ما يتقدم فتقدمت فدنوت من الماء وعقلته ثم أتيت الماء فإذا قوم مشوهون عند الماء فقعدت فبينا أنا عندهم إذ أتاهم رجل أشد تشويها منهم فقالوا هذا شاعرهم فقالوا له يا فلان أنشد هذا فإنه ضيف فأنشد\n(ودع هريرة إن الركب مرتحل ... )\nفلا والله ما خرم منها بيتا واحدا حتى انتهى إلى هذا البيت\n(تسمع للحلي وسواسا إذا انصرفت ... كما استعان بريح عشرق زجل)\nأعجب به فقلت من يقول هذا القصيدة قال أنا قلت لولا ما تقول لأخبرتك أن أعشى بني ثعلبة أنشدنيها عام أول بنجران قال فإنك صادق أنا الذي ألقيتها على لسانه وأنا مسحل صاحبه ما ضاع شعر شاعر وضعه عند ميمون بن قيس\n(رأيت عرابة الأوسي يسمو ... إلى الخيرات منقطع القرين)\n(إذا ما راية رفعت لمجد ... تلقاها عرابة باليمين)\nروضه من الوافر الشعر للشماخ والغناء لمعبد خفيف الثقيل\nالأول بالوسطى وذكر إسحاق أنه من الأصوات القليلة الأشباه وذكر ابن المكي أن له فيه لحنا آخر من خفيف الثقيل وقد أخبرني أحمد بن عبد العزيز قال حدثني عمر بن شبة عن محمد بن يحيى أبي غسان قال غنى أبو نؤى\n(رأيت عرابة الأوسي يسمو ... إلى الخيرات منقطع القرين)\nنسبه الناس إلى معبد ولعله يعني اللحن الآخر الذي ذكره ابن المكي وقال هارون بن محمد بن عبد الملك الزيات أخبرني حماد عن ابن أبي جناح قال الناس ينسبون هذا الصوت إلى معبد","topic":"ذكر عبيد الله بن عبد الله ونسبه","topicNo":92,"sp":6,"spl":"خلاف بني كعب وبني همام — يوم عين محلم","tags":[],"song":1,"loc":1670,"partialRef":{"sid":"b68-15","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b93-1","bab":"الجزء 9","sec":"ذكر الشماخ ونسبه وخبره","page":"ج9 ص184","text":"هو فيما ذكر لنا أبو خليفة عن محمد بن سلام الشماخ بن ضرار ابن سنان بن أمية بن عمرو بن جحاش بن بجالة بن مازن بن ثعلبة بن سعد ابن ذبيان\nوذكر الكوفيون أنه الشماخ بن ضرار بن حرملة بن صيفي بن إياس ابن عبد بن عثمان بن جحاش بن بجالة بن مازن بن ثعلبة بن سعد بن ذبيان ابن بغيض بن ريث بن غطفان وأم الشماخ أنمارية من بنات الخرشب ويقال أنهن أنجب نساء العرب واسمها معاذة بنت بجير بن خالد بن إياس والشماخ مخضرم ممن أدرك الجاهلية والإسلام وقد قال للنبي\n(تعلم رسول الله أنا كأننا ... أفأنا بأنمار ثعالب ذي غسل)\nيعني أنمار بن بغيض وهم قومه وهو أحد من هجا عشيرته وهجا أضيافه ومن عليهم بالقرى والشماخ لقب واسمه معقل وقيل الهيثم والصحيح معقل قال جبل بن جوال له في قصة كانت بينهما\n(لعمري لعل الخير لو تعلمانه ... يمن علينا معقل ويزيد)\n(منيحة عنز أو عطاء فطيمة ... ألا إن نيل الثعبلي زهيد)\nللشماخ أخوان من أمه وأبيه شاعران أحدهما مزرد وهو مشهور واسمه يزيد وإنما سمي مزردا لقوله\n(فقلت تزردها عبيد فإنني ... لدرد الشيوخ في السنين مزرد)\nالآخر جزء بن ضرار وهو الذي يقول يرثي عمر بن الخطاب رضي الله عنه\n(عليك سلام من أمير وباركت ... يد الله في ذاك الأديم الممزق)\n(فمن يسع أو يركب جناحي نعامة ... ليدرك ما حاولت بالأمس يسبق)\nقد أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا شهاب بن عباد قال حدثنا محمد بن بشر قال حدثنا مسعر عن عبد الملك بن عمير عن الصقر بن عبد الله عن عروة عن عائشة قالت ناحت الجن على عمر قبل أن يقتل بثلاث فقالت\n(أبعد قتيل بالمدينة أظلمت ... له الأرض تهتز العضاه بأسؤق)\n(جزى الله خيرا من إمام وباركت ... يد الله في ذاك الأديم الممزق)\n(فمن يسع أو يركب جناحي نعامة ... ليدرك ما حاولت بالأمس يسبق)\n(قضيت أمورا ثم غادرت بعدها ... بوائق في أكمامها لم تفتق)\n(وما كنت أخشى أن تكون وفاته ... بكفي سبنتى أزرق العين مطرق)\nأخبرني أحمد قال حدثنا عمر بن شبة قال حدثنا سليمان بن داود الهاشمي قال أخبرنا إبراهيم بن سعد الزهري عن إبراهيم بن عبد الرحمن بن عبد الله بن أبي ربيعة عن أم كلثوم بنت أبي بكر الصديق أن عائشة حدثتها أن عمر أذن لأزواج النبي أن يحججن في آخر حجة حجها عمر قال فلما ارتحل عمر من المحصب أقبل رجل متلثم فقال وأنا أسمع هذا كان منزله فأناخ في منزل عمر ثم رفع عقيرته يتغنى\n(عليك سلام من أمير وباركت ... يد الله في ذاك الأديم الممزق)\n(فمن يجر أو يركب جناحي نعامة ... ليدرك ما قدمت بالأمس يسبق)\n(قضيت أمورا ثم غادرت بعدها ... بوائق في أكمامها لم تفتق)\nالت عائشة فقلت لبعض أهلي اعلموا لي علم هذا الرجل فذهبوا\nفلم يجدوا في مناخه أحدا قالت عائشة فوالله إني لأحسبه من الجن فلما قتل عمر نحل الناس هذه الأبيات للشماخ بن ضرار أو جماع بن ضرار هكذا في الخبر وهو جزء بن ضرار","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":0,"spl":"ذكر الشماخ ونسبه وخبره","tags":[],"loc":1671},
{"id":"b93-2","bab":"الجزء 9","sec":"طبقته بين الشعراء","page":"ج9 ص187","text":"وجعل محمد بن سلام في الطبقة الثالثة الشماخ وقرنه بالنابغة ولبيد وأبي ذؤيب الهذلي ووصفه فقال كان شديد متون الشعر أشد كلاما من لبيد وفيه كزازة ولبيد أسهل منه منطقا أخبرنا بذلك أبو خليفة عنه وقد\nقال الحطيئة في وصيته أبلغوا الشماخ أنه أشعر غطفان قد كتب ذلك في شعر الحطيئة وهو أوصف الناس للحمير أخبرني محمد بن الحسن بن دريد قال\nحدثني عمي عن ابن الكلبي قال أنشد الوليد بن عبد الملك شيئا من شعر الشماخ في صفة الحمير فقال ما أوصفه لها إني لأحسب أن أحد أبويه كان حمارا\nأخبرني إبراهيم بن عبد الله قال حدثنا عبد الله بن مسلم قال كان الشماخ يهجو قومه ويهجو ضيفه ويمن عليه بقراه وهو أوصف الناس للقوس والحمار وأرجز الناس على البديهة\nأخبرني محمد بن العباس اليزيدي قال حدثنا عبد الرحمن ابن أخي الأصمعي عن عمه قال قال مزرد لأمه كان كعب بن زهير لا يهابني وهو اليوم يهابني فقالت يا بني نعم إنه يرى جرو الهراش موثقا ببابك تعني أخاه الشماخ وقد\nذكر محمد ابن الحسن الأحول هذا الخبر عن ابن الأعرابي عن المفضل قال قالت معاذة بنت بجير بن خلف للشماخ ومزرد عرضتماني لشعراء العرب الحطيئة وكعب ابن زهير فقالا كلا لا تخافي قالت فما يؤمنني قالا إنك ربطت بباب بيتك جروي هراش لا يجترئ أحد عليهما يعنيان أنفسهما\nأخبرني أبو خليفة قال حدثنا محمد بن سلام قال أخبرني شعيب بن صخر قال كانت عند الشماخ امرأة من بني سليم أحد بني حرام بن سماك فنازعته وادعته طلاقا وحضر معها قومها فاختصموا إلى كثير بن الصلت وكان عثمان بن عفان أقعده للنظر بين الناس وهو رجل من كندة وعداده في بني جمح وقد ولدتهم بنو جمح ثم تحولوا إلى بني العباس فهم فيهم اليوم\nفرأى كثير عليهم يمينا فالتوى الشماخ باليمين يحرضهم عليها ثم حلف وقال\n(أتتني سليم قضها وقضيضها ... تمسح حولي بالبقيع سبالها)\n(يقولون لي يا احلف ولست بحالف ... أخاتلهم عنها لكيما أنالها)\n(ففرجت هم النفس عني بحلفة ... كما شقت الشقراء عنها جلالها)\nخبرني الحرمي قال حدثنا الزبير بن بكار قال قدم ناس من بهز المدينة يستعدون على الشماخ وزعموا أنه هجاهم ونفاهم فجحد ذلك الشماخ فأمر عثمان كثير بن الصلت أن يستحلفه على منبر النبي ما هجاهم فانطلق به كثير إلى المسجد ثم انتحاه دون بني بهز وبهز اسمه تيم بن سليم بن منصور فقال له ويلك يا شماخ إنك لتحلف على منبر رسول الله ومن حلف به آثما يتبوأ مقعده من النار\nقال فكيف أفعل فداؤك أبي وأمي قال إني سوف أحلفك ما هجوتهم فاقلب الكلام علي وعلى ناحيتي فقل والله ما هجوتكم فأردني وناحيتي بذلك وإني سأدفع عنك فلما وقف حلف كما\nقال له وأقبل على كثير فقال ما هجوتكم فقالت بهز ما عنى غيركم فأعد اليمين عليه فقال مالي أتأوله هل استحلفته إلا لكم وما اليمين إلا مرة واحدة انصرف يا شماخ فانصرف وهو يقول\n(أتتني سليم قضها وقضيضها ... تمسح حولي بالبقيع سبالها)\n(يقولون لي يا احلتذف ولست بحالف ... أخادعهم عنها لكيما أنالها)\n(فلو لا كثير نعم الله باله ... أزلت بأعلى حجتيك نعالها)\n(ففرجت هم الموت عني بحلفة ... كما شقت الشقراء عنها جلالها)\nنسخت هذا الخبر على التمام من كتاب يحيى بن حازم قال حدثني علي بن صالح صاحب المصلى قال قال القاسم بن معن كان الشماخ تزوج امرأة من بني سليم فأساء إليها وضربها وكسر يدها فعرضت امرأة من قومها يقال لها أسماء ذات يوم للطريق تسأل عن صاحبتها فاجتاز الشماخ وهي لا تعرفه فقالت له مافعل الخبيث شماخ فقال لها وما تريدين منه قالت إنه فعل بصاحبة لنا كيت وكيت فتجاهل عليها وقال لا أعلم له خبرا ومضى وتركها وهو يقول\n(تعارض أسماء الرفاق عشية ... تسائل عن ضعن النساء النواكح)\n(وماذا عليها إن قلوص تمرغت ... بعدلين أو ألقتهما بالصحاصح)\n(فإنك لو أنكحت دارت بك الرحا ... وألقيت رحلي سمحة غير طامح)\n(أأسماء إني قد أتاني مخبر ... بفيقة ينبي منطقا غير صالح)\n(بعجت إليه البطن ثم انتصحته ... وما كل من يفشى إليه بناصح)\n(وإني من قوم على أن ذممتهم ... إذا أولموا لم يولموا بالأنافح)\n(وإنك من قوم تحن نساؤهم ... إلى الجانب الأقصى حنين المنائح)\nم دخل المدينة في بعض حوائجه فتعلقت به بنو سليم يطلبونه بظلامة صاحبتهم فأنكر فقالوا احلف فجعل يطلب إليهم ويغلظ عليهم أمر","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":1,"spl":"طبقته بين الشعراء","tags":["الهجاء"],"loc":1672},
{"id":"b93-3","bab":"الجزء 9","sec":"طبقته بين الشعراء","page":"ج9 ص187","text":"اليمين وشدتها عليه ليرضوا بها منه حتى رضوا فحلف لهم وقال\n(ألا أصبحت عرسي من البيت جامحا ... بغير بلاء أي أمر بدا لها)\n(على خيرة كانت أم العرس جامح ... فكيف وقد سقنا إلى الحي ما لها)\n(سترجع غضبى رثة الحال عندنا ... كما قطعت منا بليل وصالها)\nذكر بعد هذه الأبيات قوله\n(أتتني سليم قضها وقضيضها ... )\nلى آخر الأبيات وقال ابن الكلبي كان الشماخ يهوى امرأة من قومه يقال لهاكلبة بنت جوال أخت جبل ابن جوال الشاعر ابن صفوان بن بلال بن أصرم بن إياس بن عبد تميم بن جحاش بن بجالة بن مازن بن ثعلبة وكان يتحدث إليها ويقول فيها الشعر فخطبها فأجابته وهمت أن تتزوجه ثم خرج إلى سفر له فتزوجها أخوه جزء بن ضرار فآلى الشماخ ألا يكلمه أبدا وهجاه بقصيدته التي يقول فيها\n(لنا صاحب قد خان من أجل نظرة ... سقيم الفؤاد حب كلبة شاغله)\nماتا متهاجرين","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":2,"spl":"طبقته بين الشعراء — أشعر ما قالت العرب","tags":["الهجاء","الجواري والنساء"],"loc":1673,"partialRef":{"sid":"b93-2","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b93-4","bab":"الجزء 9","sec":"أشعر ما قالت العرب","page":"ج9 ص191","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني عبد الله بن أبي سعد الوراق قال حدثني أحمد بن محمد بن بكر الزبيري قال حدثنا الحسن بن موسى بن رباح مولى الأنصار عن أبي غزية الأنصاري قال\nكنت على باب المهدي يوما فخرج حاجبه فقال أين ابن دأب فقال هأنذا فقال ادخل فدخل ثم خرج فجلس فقلت يابن دأب ما جرى بينك وبين أمير المؤمنين قال قال لي أنشدني أبياتا من أشعر ما قالت العرب فأردت أن أنشده قول صاحبك أبي صرمة الأنصاري التي يقول فيها\n(لنا صور يؤول الحق فيها ... وأخلاق يسود بها الفقير)\n(ونصح للعشيرة حيث كانت ... إذا ملئت من الغش الصدور)\n(وحلم لا يصوب الجهل فيه ... وإطعام إذا قحط الصبير)\n(بذات يد على ما كان فيها ... نجود به قليل أو كثير)\nتركتها وقلت إن من أشعر ما قالت العرب قول الشماخ\n(وأشعث قد قد السفار قميصه ... يجر شواء بالعصا غير منضج)\n(دعوت إلى ما نابني فأجابني ... كريم من الفتيان غير مزلج)\n(فتى يملأ الشيزى ويروي سنانه ... ويضرب في رأس الكمي المدجج)\n(فتى ليس بالراضي بأدنى معيشة ... ولا في بيوت الحي بالمتولج)\nقال أحسنت ثم رفع رأسه إلى عبد الله بن مالك فقال هذه صفتك يا أبا العباس فأكب عليه عبد الله فقبل رأسه وقال ذكرك الله بخير الذكر يا أمير المؤمنين\nقال أبو غزية فقلت له الأبيات التي تركت والله أشعر من التي ذكرت أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال عرابة الذي عناه الشماخ بمدحه هو أحد أصحاب النبي وهو عرابة ابن أوس بن قيظي بن عمرو بن زيد بن جشم بن حارثة بن الحارث بن الخزرج وإنما\nقال له الشماخ عرابة الأوسي وهو من الخزرج نسبة إلى أبيه أوس بن قيظي ولم يصنع إسحاق في هذا القول شيئا عرابة من الأوس لا من الخزرج وفي الأوس رجل يقال له الخزرج ليس هذا هو الجد الذي ينتهي إليه الخزرجيون الذي هو أخو الأوس هذا الخزرج بن النبيت بن مالك ابن الأوس وهكذا نسبه النسابون\nوأخبرني به الحرمي بن أبي العلاء عن عبد الله بن جعفر بن مصعب عن جده مصعب الزبيري عن ابن القداح وأتى النبي في غزاة أحد ليغزو معه فرده في غلمة استصغرهم منهم عبد الله بن عمر بن الخطاب\nوزيد بن ثابت وأسيد بن حضير والبراء بن عازب وعرابة بن أوس وأبو سعيد الخدري","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":2,"spl":"طبقته بين الشعراء — أشعر ما قالت العرب","tags":["المديح"],"loc":1674},
{"id":"b93-5","bab":"الجزء 9","sec":"قصة أبي عرابة وعمه مع النبي","page":"ج9 ص194","text":"أخبرني بذلك محمد بن جرير الطبري عن الحارث بن سعد عن الواقدي عن محمد بن حميد عن سلمة عن ابن إسحاق وأوس بن قيظي أبو عرابة من المنافقين الذين شهدوا أحدا مع النبي وهو الذي قال له إن بيوتنا عورة وأخوه مربع بن قيظي الأعمى الذي حثا في\nوجه رسول الله التراب لما خرج إلى أحد وقد مر في حائطه وقال له إن كنت نبيا فما أحل لك أن تدخل في حائطي فضربه سعد بن زيد الأشهلي بقوسه فشجه\nوقال دعني يا رسول الله أقتله فإنه منافق فقال دعوه فإنه أعمى القلب أعمى البصر فقال أخوه أوس بن قيظي أبو عرابة لا والله ولكنها عداوتكم يا بني عبد الأشهل فقال رسول الله لا والله ولكنه نفاقكم يا بني قيظي أخبرنا بذلك الحرمي عن عبد الله بن جعفر الزبيري عن جده مصعب عن ابن القداح أن عرابة كان سيدا من سادات قومه وجوادا من أجوادهم وكان أبوه أوس بن قيظي من وجوه المنافقين\nأخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن المدائني عن ابن جعدبة وأخبرني علي بن سليمان عن محمد بن يزيد وأخبرني إبراهيم ابن أيوب عن عبد الله بن مسلم أن الشماخ خرج يريد المدينة فلقيه عرابة بن أوس فسأله عما أقدمه المدينة فقال أردت أن أمتار لأهلي وكان معه بعيران فأوقرهما له برا وتمرا وكساه وبره وأكرمه فخرج عن المدينة وامتدحه بهذه القصيدة التي يقول فيها\n(رأيت عرابة الأوسي يسمو ... إلى الخيرات منقطع القرين)\nأخبرني محمد بن العباس اليزيدي قال حدثنا الرياشي قال حدثنا الأصمعي قال قال معاوية لعرابة بن أوس بأي شيء سدت قومك فقال أعفو عن جاهلهم وأعطي سائلهم وأسعى في حاجاتهم فمن فعل كما أفعل فهو مثلي ومن قصر عنه فأنا خير منه ومن زاد فهو خير مني\nقال الأصمعي وقد انقرض عقب عرابة فلم يبق منهم أحد أخبرني أحمد بن يحيى بن محد بن سعيد الهمداني قال قال يحيى بن الحسن بن جعفر بن عبيد الله بن الحسين بن علي بن الحسين بن علي بن أبي طالب رضي الله عنه قال ابن دأب وسمع قول الشماخ بن ضرار في عبد الله بن جعفر بن أبي طالب رضي الله عنه\n(إنك يآبن جعفر نعم الفتى ... ونعم مأوى طارق إذا أتى)\n(وجار ضيف طرق الحي سرى ... صادف زادا وحديثا ما اشتهى)\n(إن الحديث طرف من القرى ... )\nقال ابن دأب العجب للشماخ يقول مثل هذا لابن جعفر ويقول لعرابة\n(إذا ما راية رفعت لمجد ... تلقاها عرابة باليمين)\nبن جعفر كان أحق بهذا من عرابة أخبرني محمد بن خلف وكيع قال حدثني الكراني محمد بن سعد قال حدثني طائع قال أخبرني أبو عمرو الكيس قال قال لي أبو نواس ما أحسن الشماخ في قوله\n(إذا بلغتني وحملت رحلي ... عرابة فأشرقي بدم الوتين)\nلا كما قال الفرزدق\n(علام تلفتين وأنت تحتي ... وخير الناس كلهم أمامي)\n(متى تردي الرصافة تستريحي ... من التهجير والدبر الدوامي)\nلت أنا وقد أخذ معنى قول الفرزدق هذا داود بن سلم في مدحه قثم بن العباس فأحسن فقال\n(نجوت من حلي ومن رحلتي ... يا ناق إن أدنيتني من قثم)\n(إنك إن أدنيت منه غدا ... حالفنا اليسر ومات العدم)\n(في كفه بحر وفي وجهه ... بدر وفي العرنين منه شمم)\n(أصم عن قيل الخنا سمعه ... وما عن الخير به من صمم)\n(لم يدر ما لا وبلى قد درى ... فعافها واعتاض منها نعم)\nأخبرني الحسن بن علي قال حدثنا الخراز عن المدائني قال أنشد عبد الملك قول الشماخ في عرابة بن أوس\n(إذا بلغتني وحملت رحلي ... عرابة فاشرقي بدم الوتين)\nقال بئست المكافأة كافأها حملت رحله وبلغته فجعل مكافأتها نحرها","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":3,"spl":"قصة أبي عرابة وعمه مع النبي","tags":["المديح"],"loc":1675,"partial":1},
{"id":"b93-6","bab":"الجزء 9","sec":"المهلب والشعراء","page":"ج9 ص198","text":"قال الخراز ومثل هذا ماحدثناه المدائني عن ابن دأب أن رجلا لقي المهلب فنحر ناقته في وجهه فتطير من ذلك وقال له ما قصتك فقال\n(إني نذرت لئن لقيتك سالما ... أن تستمر بها شفار الجازر)\nفقال المهلب فأطعمونا من كبد هذه المظلومة ووصله قال المدائني ولقيته امرأة من الأزد وقد قدم من حرب كان نهض إليها فقالت أيها الأمير إني نذرت إن وافيتك سالما أن أقبل يدك وأصوم يوما وتهب لي جارية صغدية وثلثمائة درهم فضحك المهلب وقال قد وفينا لك بنذرك فلا تعاودي مثله فليس كل أحد يفي لك به وأخبرني الحسن قال حدثنا عبد الله بن أبي سعد قال حدثني بعض أصحابنا عن القحذمي أن أبادلامة لقي المهدي لما قدم بغداد فقال له\n(إني نذرت لئن رأيتك واردا ... أرض العراق وأنت ذو وفر)\n(لتصلين على النبي محمد ... ولتملأن دراهما حجري)\nفقال له أما النبي فصلى الله على النبي محمد وآله وسلم وأما الدراهم فلا سبيل إليها فقال له أنت أكرم من أن تعطيني أسهلهما عليك وتمنعني الأخرى فضحك وأمر له بما سأل وهذا مما ليس يجري في هذا الباب ولكن يذكر الشيء بمثله\nأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عبد الله بن أبي سعد قال حدثنا مسعود بن عيسى العبدي قال حدثني أحمد بن طالب الكناني كنانة تغلب\nوأخبرني به محمد بن أحمد بن الطلاس عن الخراز عن المدائني لم يتجاوزه به قال نصب عبد الملك بن مروان الموائد يطعم الناس فجلس رجل من أهل العراق على بعض تلك الموائد فنظر إليه خادم لعبد الملك فأنكره فقال له أعراقي أنت\nقال نعم قال أنت جاسوس قال لا قال بلى قال ويحك دعني أتهنأ بزاد أمير المؤمنين ولا تنغصني به ثم إن عبد الملك وقف على تلك المائدة فقال من القائل\n(إذا الأرطى توسد أبرديه ... خدود جوازئ بالرمل عين)\nما معناه ومن أجاب فيه أجزناه والخادم يسمع فقال العراقي\nللخادم أتحب أن أشرح لك قائله وفيم قاله قال نعم قال يقوله عدي ابن زيد في صفة البطيخ الرمسي فقال ذلك الخادم فضحك عبد الملك حتى سقط فقال له الخادم أخطأت أم أصبت فقال بل أخطأت فقال يا أمير المؤمنين هذا العراقي فعل الله به وفعل لقننيه فقال أي الرجال هو فأراه إياه فعاد إليه عبد الملك\nوقال أنت لقنته هذا قال نعم قال أفخطأ لقنته أم صوابا قال بل خطأ قال ولم قال لأني كنت متحرما بمائدتك فقال لي كيت وكيت فأردت أن أكفه عني وأضحكك\nقال فكيف الصواب قال يقوله الشماخ بن ضرار الغطفاني في صفة البقر الوحشية قد جزأت بالرطب عن الماء قال صدقت وأجازه ثم قال له حاجتك قال تنحي هذا عن بابك فإنه يشينه\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال كتب إلي إسحاق بن إبراهيم الموصلي أن أبا عبيدة حدثه عن غير واحد من أهل المدينة أن يزيد بن عبد الملك لما قدم عليه الأحوص وصله بمائة ألف درهم فأقبل إليه كثير يرجو أكثر من ذلك وكان قد عوده من كان قبل يزيد من الخلفاء أن يلقى عليهم بيوت الشعر ويسألهم عن المعاني فألقى على يزيد بيتا وقال يا أمير المؤمنين ما يعني الشماخ بقوله\n(فما أروى وإن كرمت علينا ... بأدنى من موقفة حرون)\n(تطيف على الرماة فتتقيهم ... بأوعال معطفة القرون)\nقال يزيد وما يضر يا ماص بظر أمه ألا يعلم أمير المؤمنين هذا وإن احتاج إلى علمه سأل عبدا مثلك عنه فندم كثير وسكته من حضر من أهل بيته وقالوا له إنه قد عوده من كان قبلك من الخلفاء أن يلقي عليه أشباه هذا وكانوا يشتهونه منه ويسألونه إياه فطفئ عنه غضبه وكانت جائزته ثلاثين ألفا وكان يطمع في أكثر من جائزة الأحوص وأخبرنا أبو خليفة بهذا الخبر عن محمد بن سلام فذكر أنه سأل يزيد عن قول الشماخ\n(وقد عرقت مغابنها وجادت ... بدرتها قرى حجن قتين)\nسكت عنه يزيد فقال يزيد وما على أمير المؤمنين لا أم لك ألا يعرف هذا هو القراد أشبه الدواب بك نسخت من كتاب يحيى بن حازم حدثنا علي بن صالح صاحب المصلى قال حدثنا ابن داب قال قال معاوية لعبد الله بن الزبير وهو عنده بالمدينة في أناس يابن الزبير ألا تعذرني في حسن بن علي ما رأيته مذ قدمت المدينة إلا مرة قال دع عنك حسنا فأنت والله وهو كما قال الشماخ\n(أجامل أقواما حياء وقد أرى ... صدورهم تغلي علي مراضها)","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":4,"spl":"المهلب والشعراء","tags":["الجواري والنساء"],"loc":1676},
{"id":"b93-7","bab":"الجزء 9","sec":"المهلب والشعراء","page":"ج9 ص198","text":"والله لو يشاء حسن أن يضربك بمائة ألف سيف ضربك والله لأهل العراق أرأم له من أم الحوار لحوارها فقال معاوية رحمه الله أردت أن تغريني به والله لأصلن رحمه ولأقبلن عليه وقال\n(ألا أيها المرء المحرش بيننا ... ألا اقتل أخاك لست قاتل أربد)\n(أبى قربه مني وحسن بلائه ... وعلمي بما يأتي به الدهر في غد)\nالشعر لعروة بن قيس فقال ابن الزبير أما والله إني وإياه ليد عليك بحلف الفضول فقال معاوية من أنت لا أعرض لك وحلف الفضول والله ما كنت فيها إلا كالرهينة تثخن معنا وتردى هزيلا كما قال أخو همدان\n(إذا ما بعير قام علق رحله ... وإن هو أبقى بالحياة مقطعا)","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":5,"spl":"المهلب والشعراء — صوت من مدن معبد","tags":[],"loc":1677},
{"id":"b93-8","bab":"الجزء 9","sec":"صوت من مدن معبد","page":"ج9 ص202","text":"وهو الذي أوله\n(كم بذاك الحجون من حي صدق ... )\n(أسعداني بعبرة أسراب ... من شؤون كثيرة التسكاب)\n(إن أهل الحصاب قد تركوني ... موزعا مولعا بأهل الحصاب)\n(كم بذاك الحجون من حي صدق ... وكهول أعفة وشباب)\n(سكنوا الجزع جزع بيت أبي موسى ... إلى النخل من صفي السباب)\n(فارقوني وقد علمت يقينا ... ما لمن ذاق ميتة من إياب)\n(فلي الويل بعدهم وعليهم ... صرت فردا وملني أصحابي)\nروضه من الخفيف الشؤون الشعب التي يتداخل بعضها في بعض من عظام الرأس واحدها شأن مهموزا والجزع منعطف الوادي وصفي السباب جمع صفاة وهي الحجارة ولقبت صفي السباب لأن قوما من قريش ومواليهم كانوا يخرجون إليها بالعشيات يتشاتمون ويذكرون المعايب والمثالب التي يرمون بهافسميت تلك الحجارة صفي السباب\nأخبرني أحمد بن عبد العزيز الجوهري عن علي بن محمد النوفلي عن أبيه قال يقال صفا السباب وصفي السباب بفتح الفاء وكسرها جميعا وهو شعب من شعاب مكة فيها صفا أي صخر مطروح وكانت قريش تخرج فتقف على ذلك الموضع فيفتخرون ثم يتشاتمون وذلك في الجاهلية فلا يفترقون إلا عن قتال ثم صار ذلك في صدر من الإسلام أيضا حتى نشأ سديف مولى عتبة بن أبي سديف وشبيب مولى بني أمية فكان هذا يخرج في موالي بني هاشم وهذا في موالي بني أمية فيفتخرون ثم يتشاتمون ثم يتجالدون بالسيوف وكان يقال لهم السديفية والشبيبية وكان أهل مكة مقتسمين بينهما في العصبية ثم درس ذلك فصارت العصبية بمكة بين الجزارين والحناطين فهي بينهم إلى اليوم وكذلك بالمدينة في القمار وغيره الشعر لكثير بن كثير بن المطلب بن أبي وداعة السهمي وقيل بل هو\nلكثير عزة وقد روي في ذلك خبر نذكره والغناء لمعبد ثقيل أول بالوسطى في مجراها عن إسحاق وذكر عمرو بن بانة أن فيه ثقيلا أول بالخنصر للغريض ولحنا آخر لابن عباد ولم يجنسه ولابن جامع في الخامس والسادس رمل بالوسطى ولابن سريج في الأربعة الأول ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق ولابن أبي دباكل الخزاعي فيها ثاني ثقيل بالوسطى عن الهشامي وأبي أيوب المدني وحبش فمن روى هذا الشعر لكثير عزة يرويه\n(إن أهل الخضاب قد تركوني ... )\nيزعم أن كثيرا قاله في خضاب خضبته عزة به","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":5,"spl":"المهلب والشعراء — صوت من مدن معبد","tags":["الهجاء"],"loc":1678,"partialRef":{"sid":"b13-2","gi":2,"vi":4,"side":0},"partial":1},
{"id":"b93-9","bab":"الجزء 9","sec":"ابن عائشة يذكر بحادثة لكثير وعزة فيغني بشعره","page":"ج9 ص204","text":"أخبرني بخبره أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة ولم يتجاوزه وأخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال حدثني الزبيري\nقال حدثني بهذا الخبر أيضا وفيه زيادة وخبره أحسن وأكثر تلخيصا وأدحل في معنى الكتاب قال الزبيري حدثني أبي قال خرجت إلى ناحية فيد متنزها فرأيت ابن عائشة يمشي بين رجلين من آل الزبير وإحدى يديه على يد هذا والأخرى على يد هذا وهو يمشي بينهما كأنه امرأة تجلى على زوجها فلما رأيتهم دنوت فسلمت وكنت أحدث القوم سنا فاشتهيت غناء ابن عائشة فلم أدر كيف أصنع وكان ابن عائشة إذا هيجته تحرك فقلت رحم الله كثيرا وعزة ما كان أوفاهما وأكرمهما\nوأصونهما لأنفسهما لقد ذكرت بهذه الأودية التي نحن فيها خبر عزة حين خضبت كثيرا فقال ابن عائشة وكيف كان حديث ذلك قلت حدثني من حضره بذلك ومن هاهنا تتفق رواية عمر بن شبة والزبيري\nقال خرج كثير يريد عزة وهي منتجعة بالصواري وهي الأودية بناحية فدك فلما كان منها قريبا وعلم أن القوم جلسوا عند أنديتهم للحديث بعث أعرابيا فقال له اذهب إلى ذلك الماء فإنك ترى امرأة جسيمة لحيمة تبالط الرجال الشعر\nقال إسحاق المبالطة أن تنشد أول الشعر وآخره فإذا رأيتها فناد من رأى الجمل الأحمر مرارا ففعل فقالت له ويحك قد أسمعت فانصرف فانصرف إليه فأخبره فلم يلبث أن أقلبت جارية معها طست وتور وقربة ماء حتى انتهت إليه ثم جاءت بعد ذلك عزة فرأته جالسا محتبيا قريبا من ذراع راحلته فقالت له ما على هذا فارقتك فركب راحلته وهي باركة وقامت إلى لحيته فأخذت التور فخضبته وهو على ظهر جمله حتى فرغت من خضابه ثم نزل فجعلا يتحدثان حتى علق الخضاب ثم قامت إليه فغسلت لحيته ودهنته ثم قام فركب وقال\n(إن أهل الخضاب قد تركوني ... موزعا مولعا بأهل الخضاب)\nذكر باقي الأبيات كلها وإلى هاهنا رواية عمر بن شبة فقال ابن عائشة فأنا والله أغنيه وأجيده فهل لكم في ذلك فقلنا وهل لنا عنه\nمدفع فاندفع يغني بالأبيات فخيل إلي أن الأودية تنطق معه حسنا فلما رجعنا إلى المدينة قصصت القصة فقيل لي إن ذلك أحسن صوت يغنيه ابن عائشة فقلت لا أدري إلا أني سمعت شيئا وافق محبتي","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":6,"spl":"ابن عائشة يذكر بحادثة لكثير وعزة فيغني بشعره","tags":["الجواري والنساء"],"loc":1679},
{"id":"b93-10","bab":"الجزء 9","sec":"معبد وابن سريج يبكيان أهل مكة بغنائهما","page":"ج9 ص206","text":"وقال عبد الله بن أبي سعد حدثني عبد الله بن الصباح عن هشام بن محمد عن أبيه قال زار معبد ابن سريج والغريض بمكة فخرجا به إلى التنعيم ثم صاروا إلى الثنية العليا ثم قالوا تعالوا حتى نبكي أهل مكة فاندفع ابن سريج فغنى صوته في شعر كثير بن كثير السهمي\n(أسعديني بعبرة أسراب ... من دموع كثيرة التسكاب)\nأخذ أهل مكة في البكاء وأنوا حتى سمع أنينهم ثم غنى معبد\n(يا راكبا نحو المدينة جسرة ... أجدا تلاعب حلقة وزماما)\n(اقرأ على أهل البقيع من امرئ ... كمد على أهل البقيع سلاما)\n(كم غيبوا فيه كريما ماجدا ... شهما ومقتبل الشباب غلاما)\n(ونفيسة في أهلها مرجوة ... جمعت صباحة صورة وتماما)\nنادوا من الدروب بالويل والحرب والسلب وبقي الغريض لا يقدر من البكاء والصراخ أن يغني الشعر لعمر بن أبي ربيعة والغناء لمعبد ثقيل أول بالوسطى وذكر عمرو بن بانة أنه ليحيى المكي وقد غلط وذكر حبش أن لعلويه فيه ثقيلا أول آخر ومن مدن معبد صوت وقد أضيف إليه غيره من القصيدة\n(سلي هل قلاني من عشير صحبته ... وهل ذم رحلي في الرفاق رفيق)\n(وهل يجتوي القوم الكرام صحابتي ... إذا اغبر مخشي الفجاج عميق)\n(ولو تعلمين الغيب أيقنت أنني ... لكم والهدايا المشعرات صديق)\n(تكاد بلاد الله يا أم معمر ... بما رحبت يوما علي تضيق)\n(أذود سوام الطرف عنك وهل لها ... إلى أحد إلا إليك طريق)\n(وحدثتني يا قلب أنك صابر ... على البين من لبنى فسوف تذوق)\n(فمت كمدا أو عش سقيما فإنما ... تكلفني ما لا أراك تطيق)\n(بلبنى أنادى عند أول غشية ... ولو كنت بين العائدات أفيق)\n(إذا ذكرت لبنى تجلتك زفرة ... ويثني لك الداعي بها فتفيق)\nروضه من الطويل الشعر لقيس بن ذريح والغناء لمعبد في اللحن المذكور ثقيل أول بالخنصر في مجرى البنصر عن إسحاق في الأول والثاني والثالث وذكر في موضع آخر وافقته دنانير أن لمعبد ثقيلا أول بالبنصر في مجرى الوسطى أوله\n(أتجمع قلبا بالعراق فريقه ... ومنه بأطلال الأراك فريق)\n(فكيف بها لا الدار جامعة النوى ... ولا أنت يوما عن هواك تفيق)\n(ولو تعلمين الغيب أيقنت أنني ... لكم والهدايا المشعرات صديق)\nلبيتان الأولان يرويان لجرير وغيره والثالث لقيس بن ذريح أضافه إليهما معبد وذكر عمرو ويونس أن لحن معبد الأول في خمسة أبيات أولى من الشعر وذكر عمرو بن بانة أن لبذل الكبيرة خفيف رمل بالوسطى في الرابع من الأبيات وبعده\n(دعون الهوى ثم ارتمين قلوبنا ... بأعين أعداء وهن صديق)\nبعده الخامس من الأبيات وهو أذود سوام الطرف وزعم حبش أن في لحن معبد الثاني الذي أوله أتجمع قلبا لابن سريج خفيف رمل بالبنصر وذكر أيضا أن للغريض في الأول والثاني والسابع ثاني ثقيل بالبنصر ولابن مسجح خفيف رمل بالبنصر وفي السادس وما بعده لحكم\nالوادي ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وذكر حبش أن للغريض فيها ثقيلا أول بالوسطى","topic":"ذكر الشماخ ونسبه وخبره","topicNo":93,"sp":7,"spl":"معبد وابن سريج يبكيان أهل مكة بغنائهما","tags":["الحب والغزل"],"song":2,"loc":1680},
{"id":"b94-1","bab":"الجزء 9","sec":"ذكر قيس بن ذريح ونسبه وأخباره","page":"ج9 ص210","text":"هو فيما ذكر الكلبي والقحذمي وغيرهما قيس بن ذريح بن سنة ابن حذافة بن طريف بن عتوارة بن عامر بن ليث بن بكر بن عبد مناة وهو علي ابن كنانة بن خزيمة بن مدركة بن الياس بن مضر بن نزار وذكر أبو شراعة القيسي أنه قيس بن ذريح بن الحباب بن سنة وسائر النسب متفق واحتج بقول قيس\n(فإن يك تهيامي بلبنى غواية ... فقد يا ذريح بن الحباب غويت)\nذكر القحذمي أن أمه بنت سنة بن الذاهل بن عامر الخزاعي وهذا هو الصحيح وأنه كان له خال يقال له عمرو بن سنة شاعر وهو الذي يقول\n(ضربوا الفيل بالمغمس حتى ... ظل يحبو كأنه محموم)\nفيه يقول قيس\n(أنبئت أن لخالي هجمة حبسا ... كأنهن بجنب المشعر النصل)\n(قد كنت فيما مضى قدما تجاورنا ... لا ناقة لك ترعاها ولا جمل)\n(ما ضر خالي عمرا لو تقسمها ... بعض الحياض وجم البئر محتفل)\nخبرني الحسن بن علي قال حدثني محمد بن موسى بن حماد قال حدثني أحمد بن القاسم بن يوسف قال حدثني جزء بن قطن قال حدثنا جساس بن محمد بن عمرو أحد بني الحارث بن كعب عن محمد بن أبي السري عن هشام بن الكلبي قال حدثني عدد من الكنانيين أن قيس بن ذريح كان رضيع الحسين بن علي بن أبي طالب رضي الله عنهما أرضعته أم قيس","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":0,"spl":"ذكر قيس بن ذريح ونسبه وأخباره","tags":["الحب والغزل","الجواري والنساء","الرواية والكتابة"],"loc":1681},
{"id":"b94-2","bab":"الجزء 9","sec":"قصته مع لبنى","page":"ج9 ص211","text":"أخبرني بخبر قيس ولبنى امرأته جماعة من مشايخنا في قصص متصلة ومنقطعة وأخبار منثورة ومنظومة فألفت ذلك أجمع ليتسق حديثه إلا ما جاء مفردا وعسر إخراجه عن جملة النظم فذكرته على حدة فممن أخبرنا بخبره أحمد بن عبد العزيز الجوهري\nقال حدثنا عمر بن شبة ولم يتجاوزه إلى غيره وإبراهيم بن محمد بن أيوب عن ابن قتيبة والحسن بن علي عن محمد بن موسى بن حماد البربري عن أحمد بن القاسم بن يوسف عن جزء بن قطن عن جساس بن محمد عن محمد بن أبي السري عن هشام بن الكلبي وعلى روايته أكثر المعول ونسخت أيضا من أخباره المنظومة أشياء ذكرها القحذمي عن رجاله وخالد بن كلثوم عن نفسه ومن\nروى عنه وخالد بن جمل ونتفا حكاها اليوسفي صاحب الرسائل عن أبيه عن أحمد بن حماد عن جميل عن ابن أبي جناح الكعبي وحكيت كل متفق فيه متصلا وكل مختلف في معانيه منسوبا إلى راوية قالوا جميعا\nكان منزل قومه في ظاهر المدينة وكان هو وأبوه من حاضرة المدينة وذكر خالد بن كلثوم أن منزله كان بسرف واحتج بقوله\n(الحمد لله قد أمست مجاورة ... أهل العقيق وأمسينا على سرف)\nقالوا فمر قيس لبعض حاجته بخيام بني كعب بن خزاعة فوقف على خيمة منها والحي خلوف والخيمة خيمة لبنى بنت الحباب الكعبية فاستسقى ماء فسقته وخرجت إليه به وكانت امرأة مديدة القامة شهلاء حلوة المنظر والكلام فلما رآها وقعت في نفسه وشرب الماء فقالت له أتنزل فتتبرد عندنا\nقال نعم فنزل بهم وجاء أبوها فنحر له وأكرمه فانصرف قيس وفي قلبه من لبنى حر لا يطفأ فجعل ينطق بالشعر فيها حتى شاع وروي ثم أتاها يوما آخر وقد اشتد وجده بها فسلم فظهرت له وردت سلامه وتحفت به فشكا إليها ما يجد بها وما يلقى من حبها وشكت إليه مثل ذلك فأطالت وعرف كل واحد منهما ما له عند صاحبه فانصرف إلى أبيه وأعلمه حاله وسأله أن يزوجه إياها فأبى عليه وقال يا بني عليك بإحدى بنات\nعمك فهن أحق بك وكان ذريح كثير المال موسرا فأحب ألا يخرج ابنه إلى غريبة فانصرف قيس وقد ساءه ما خاطبه أبوه به فأتى أمه فشكا ذلك إليها واستعان بها على أبيه فلم يجد عندها ما يحب فأتى الحسين بن علي بن أبي طالب وابن أبي عتيق فشكا إليهما ما به وما رد عليه أبوه فقال له الحسين أنا أكفيك فمشى معه إلى أبي لبنى فلما بصر به أعظمه ووثب إليه\nوقال له يابن رسول الله ما جاء بك ألا بعثت إلي فأتيتك قال إن الذي جئت فيه يوجب قصدك وقد جئتك خاطبا ابنتك لبنى لقيس بن ذريح فقال يابن رسول الله ما كنا لنعصي لك أمرا وما بنا على الفتى رغبة ولكن أحب الأمر إلينا أن يخطبها ذريح أبوه علينا وأن يكون ذلك عن أمره فإنا نخاف إن لم يسع أبوه في هذا أن يكون عارا وسبة علينا فأتى الحسين رضي الله عنه ذريحا وقومه وهم مجتمعون فقاموا إليه إعظاما له وقالوا له مثل قول الخزاعيين فقال لذريح أقسمت عليك إلا خطبت لبنى لابنك قيس\nقال السمع والطاعة لأمرك فخرج معه في وجوه من قومه حتى أتوا لبنى فخطبها ذريح على ابنه إلى أبيها فزوجه إياها وزفت إليه بعد ذلك فأقامت معه مدة لا ينكر أحد من صاحبه شيئا وكان أبر الناس بأمه فألهته لبنى وعكوفه عليها عن بعض ذلك فوجدت أمه في نفسها وقالت لقد شغلت هذه المرأة ابني عن بري ولم تر للكلام في ذلك موضعا حتى مرض مرضا شديدا فلما برأ من علته قالت أمه لأبيه لقد خشيت أن يموت قيس وما يترك خلفا وقد حرم الولد من هذه المرأة وأنت ذو مال فيصير مالك إلى الكلالة فزوجه بغيرها لعل الله أن يرزقه ولدا وألحت عليه في ذلك\nفأمهل قيسا حتى إذا اجتمع قومه دعاه فقال يا قيس إنك اعتللت هذه العلة فخفت عليك ولا ولد لك ولا لي سواك وهذه المرأة ليست بولود فتزوج إحدى بنات عمك لعل الله أن يهب لك ولدا تقر به عينك وأعيننا فقال قيس لست متزوجا غيرها أبدا فقال له أبوه فإن في مالي سعة فتسر بالإماء\nقال ولا أسوءها بشيء أبدا والله قال أبوه فإني أقسم عليك إلا طلقتها فأبى وقال الموت والله علي أسهل من ذلك ولكني أخيرك خصلة من ثلاث خصال\nقال وما هي قال تتزوج أنت فلعل الله أن يرزقك ولدا غيري قال فما في فضلة لذلك قال فدعني أرتحل عنك بأهلي واصنع ما كنت صانعا لو مت في علتي هذه","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":1,"spl":"قصته مع لبنى","tags":["الحب والغزل"],"loc":1682},
{"id":"b94-3","bab":"الجزء 9","sec":"قصته مع لبنى","page":"ج9 ص211","text":"قال ولا هذه قال فأدع لبنى عندك وأرتحل عنك فلعلي أسلوها فإني ما أحب بعد أن تكون نفسي طيبة أنها في خيالي قال لا أرض أو تطلقها وحلف لا يكنه سقف بيت أبدا حتى يطلق لبنى فكان يخرج فيقف في حر الشمس ويجيء قيس فيقف إلى جانبه فيظله بردائه ويصلى هو بحر الشمس حتى يفيء الفيء فينصرف عنه ويدخل إلى لبنى فيعانقها وتعانقه ويبكي وتبكي معه وتقول له يا قيس لا تطع أباك فتهلك وتهلكني فيقول ما كنت لأطيع أحدا فيك أبدا فيقال إنه مكث كذلك سنة وقال خالد بن كلثوم ذكر ابن عائشة أنه أقام على ذلك أربعين يوما ثم طلقها وهذا ليس بصحيح","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":2,"spl":"قصته مع لبنى","tags":[],"loc":1683},
{"id":"b94-4","bab":"الجزء 9","sec":"طلاقه لبنى ثم ندمه","page":"ج9 ص214","text":"أخبرني محمد بن خلف وكيع قال حدثني أحمد بن زهير قال حدثني\nيحيى بن معين قال حدثنا عبد الرزاق قال أخبرنا ابن جريج قال أخبرني عمر بن أبي سفيان عن ليث بن عمرو أنه سمع قيس بن ذريح يقول لزيد بن سليمان هجرني أبواي في لبنى عشر سنين أستأذن عليهما فيرداني حتى طلقتها\nقال ابن جريج وأخبرت أن عبد الله بن صفوان الطويل لقي ذريحا أبا قيس فقال له ما حملك على أن فرقت بينهما أما علمت أن عمر بن الخطاب قال ما أبالي أفرقت بينهما أو مشيت إليهما بالسيف\nوروى هذا الحديث إبراهيم بن يسار الرمادي عن سفيان بن عيينة عن عمرو بن دينار قال قال الحسين بن علي رضي الله عنهما لذريح بن سنة أبي قيس أحل لك أن فرقت بين قيس ولبنى أما إني سمعت عمر بن الخطاب يقول ما أبالي أفرقت بين الرجل وامرأته أو مشيت إليهما بالسيف قالوا فلما بانت لبنى بطلاقه إياها وفرغ من الكلام لم يلبث حتى استطير عقله وذهب به ولحقه مثل الجنون وتذكر لبنى وحالها معه فأسف وجعل يبكي وينشج أحر نشيج وبلغها الخبر فأرسلت إلى أبيها ليحتملها\nوقيل بل أقامت حتى انقضت عدتها وقيس يدخل عليها فأقبل أبوها بهودج على ناقة وبإبل تحمل أثاثها فلما رأى ذلك قيس أقبل على جاريتها فقال ويحك ما دهاني فيكم فقال لا تسألني وسل لبنى فذهب ليلم بخبائها فيسألها فمنعه قومها فأقبلت عليه امرأة من قومه فقالت له ما\nلك ويحك تسأل كأنك جاهل أو تتجاهل هذه لبنى ترتحل الليلة أو غدا فسقط مغشيا عليه لا يعقل ثم أفاق وهو يقول\n(وإني لمفن دمع عيني بالبكا ... حذار الذي قد كان أو هو كائن)\n(وقالوا غدا أو بعد ذاك بليلة ... فراق حبيب لم يبن وهو بائن)\n(وما كنت أخشى أن تكون منيتي ... بكفيك إلا أن ما حان حائن)\nي هذه الأبيات غناء ولها أخبار قد ذكرت في أخبار المجنون قال وقال قيس\n(يقولون لبنى فتنة كنت قبلها ... بخير فلا تندم عليها وطلق)\n(فطاوعت أعدائي وعاصيت ناصحي ... وأقررت عين الشامت المتخلق)\n(وددت وبيت الله أني عصيتهم ... وحملت في رضوانها كل موبق)\n(وكلفت خوض البحر والبحر زاخر ... أبيت على أثباج موج مغرق)\n(كأني أرى الناس المحبين بعدها ... عصارة ماء الحنظل المتفلق)\n(فتنكر عيني بعدها كل منظر ... ويكره سمعي بعدها كل منطق)\nال وسقط غراب قريبا منه فجعل ينعق مرارا فتطير منه وقال\n(لقد نادى الغراب ببين لبنى ... فطار القلب من حذر الغراب)\n(وقال غدا تباعد دار لبنى ... وتنأى بعد ود واقتراب)\n(فقلت تعست ويحك من غراب ... وكان الدهر سعيك في تباب)\nقال أيضا وقد منعه قومه من الإلمام بها\n(ألا يا غراب البين ويحك نبني ... بعلمك في لبنى وأنت خبير)\n(فإن أنت لم تخبر بما قد علمته ... فلا طرت إلا والجناح كسير)\n(ودرت بأعداء حبيبك فيهم ... كما قد تراني بالحبيب أدور)\nنى سليمان أخو حجبة رملا بالوسطى قالوا وقال أيضا وقد أدخلت هودجها ورحلت وهي تبكي ويتبعها\n(ألا يا غراب البين هل أنت مخبري ... بخير كما خبرت بالنأي والشر)\n(وقلت كذاك الدهر ما زال فاجعا ... صدقت وهل شيء بباق على الدهر)\nنى فيهما ابن جامع ثاني ثقيل بالبنصر عن الهشامي وذكر حبش أن لقفا النجار فيهما ثقيلا أول بالوسطى قالوا فلما ارتحل قومها مليا ثم علم أن أباها سيمنعه من المسير معها فوقف ينظر إليهم ويبكي حتى غابوا عن عينه فكر راجعا ونظر إلى أثر خف بعيرها فأكب عليه يقبله ورجع يقبل موضع مجلسها وأثر قدمها فليم على ذلك وعنفه قومه على تقبيل التراب فقال\n(وما أحببت أرضكم ولكن ... أقبل إثر من وطئ الترابا)\n(لقد لاقيت من كلفي بلبنى ... بلاء ما أسيغ به الشرابا)\n(إذا نادى المنادي باسم لبنى ... عييت فما أطيق له جوابا)\nقال وقد نظر إلى آثارها\n(ألا يا ربع لبنى ما تقول ... ابن لي اليوم ما فعل الحلول)\n(فلو أن الديار تجيب صبا ... لرد جوابي الربع المحيل)\n(ولو أني قدرت غداة قالت ... غدرت وماء مقلتها يسيل)\n(نحرت النفس حين سمعت منها ... مقالتها وذاك لها قليل)\n(شفيت غليل نفسي من فعالي ... ولم أغبر بلا عقل أجول)\nغنى فيه حسين بن محرز خفيف ثقيل من روايتي بذل وقريض وتمام هذه الأبيات\n(كأني واله بفراق لبنى ... تهيم بفقد واحدها ثكول)\n(ألا يا قلب ويحك كن جليدا ... فقد رحلت وفات بها الذميل)\n(فإنك لا تطيق رجوع لبنى ... إذا رحلت وإن كثر العويل)","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":3,"spl":"طلاقه لبنى ثم ندمه","tags":["الحب والغزل"],"song":3,"loc":1684},
{"id":"b94-5","bab":"الجزء 9","sec":"طلاقه لبنى ثم ندمه","page":"ج9 ص214","text":"(وكم قد عشت كم بالقرب منها ... ولكن الفراق هو السبيل)\n(فصبرا كل مؤتلفين يوما ... من الأيام عيشهما يزول)\nقال فلما جن عليه الليل وانفرد وأوى إلى مضجعه لم يأخذه القرار وجعل يتململ فيه تململ السليم ثم وثب حتى أتى موضع خبائها فجعل يتمرغ فيه ويبكي ويقول\n(بت والهم يا لبيني ضجيعي ... وجرت مذ نأيت عني دموعي)\n(وتنفست إذ ذكرتك حتى ... زالت اليوم عن فؤادي ضلوعي)\n(أتناساك كي يريغ فؤادي ... ثم يشتد عند ذاك ولوعي)\n(يا لبينى فدتك نفسي وأهلي ... هل لدهر مضى لنا من رجوع)\nنت في البيتين الأولين شارية خفيف رمل بالوسطى وغنى فيهما\nحسين بن محرز ثاني ثقيل هكذا ذكر الهشامي وقد قيل إنه لهاشم بن سليمان أخبرني محمد بن خلف وكيع قال قال الزبير بن بكار حدثني عبد الجبار ابن سعيد المساحقي عن محمد بن معن الغفاري عن أبيه عن عجوز لهم يقال لهما حمادة بنت أبي مسافر قالت جاورت آل ذريح بقطيع لي فيه الرائمة وذات البر والحائل والمتبع قالت فكان قيس بن ذريح إلى شرف في ذلك القطيع ينظر إلى ما يلقين فيتعجب فقلما لبث حتى عزم عليه أبوه بطلاق لبنى فكاد يموت ثم آلى أبوه لئن أقامت لا يساكن قيسا فظعنت فقال\n(أيا كبدا طارت صدوعا نوافذا ... ويا حسرتا ماذا تغلغل في القلب)\n(فأقسم ما عمش العيون شوارف ... روائم بو حائمات على سقب)\n(تشممنه لو يستطعن ارتشفنه ... إذا سفنه يزددن نكبا على نكب)\n(رئمن فما تنحاش منهن شارف ... وحالفن حبسا في المحول وفي الجدب)\n(بأوجد مني يوم ولت حمولها ... وقد طلعت أولى الركاب من النقب)\n(وكل ملمات الزمان وجدتها ... سوى فرقة الأحباب هينة الخطب)\nخبرني عمي قال حدثني الكراني قال سمعت ابن عائشة يقول قال إسحاق بن الفضل الهاشمي لم يقل الناس في هذا المعنى مثل قول قيس ابن ذريح\n(وكل مصيبات الزمان وجدتها ... سوى فرقة الأحباب هينة الخطب)\nال وقال ابن النطاح قال أبو دعامة","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":4,"spl":"طلاقه لبنى ثم ندمه","tags":["الجواري والنساء","الوصف والطبيعة"],"song":1,"loc":1685},
{"id":"b94-6","bab":"الجزء 9","sec":"اشتاقها فقصدها وقال شعرا","page":"ج9 ص220","text":"خرج قيس في فتية من قومه واعتل على أبيه بالصيد فأتى بلاد لبنى فجعل يتوقع أن يراها أو يرى من يرسل إليها فاشتغل الفتيان بالصيد فلما قضوا وطرهم منه رجعوا إليه وهو واقف فقالوا له قد عرفنا ما أردت بإخراجنا معك وأنك لم ترد الصيد وإنما أردت لقاء لبنى وقد تعذر عليك فانصرف الآن فقال\n(وما حائمات حمن يوما وليلة ... على الماء يغشين العصي حوان)\n(عوافي لا يصدرن عنه لوجهة ... ولا هن من برد الحياض دوان)\n(يرين حباب الماء والموت دونه ... فهن لأصوات السقاة روان)\n(بأجهد مني حر شوق ولوعة ... عليك ولكن العدو عداني)\n(خليلي إني ميت أو مكلم ... لبينى بسري فامضيا وذراني)\n(أنل حاجتي وحدي ويا رب حاجة ... قضيت على هول وخوف جنان)\n(فإن أحق الناس ألا تجاوزا ... وتطرحا من لو يشاء شفاني)\n(ومن قادني للموت حتى إذا صفت ... مشاربه السم الذعاف سقاني)\nقال فأقاموا معه حتى لقيها فقالت له يا هذا إنك متعرض لنفسك وفاضحي فقال لها\n(صدعت القلب ثم ذررت فيه ... هواك فليم فالتأم الفطور)\n(تغلغل حيث لم يبلغ شراب ... ولا حزن ولم يبلغ سرور)\nقال القحذمي حدثني أبو الوردان قال حدثني أبي قال أنشدت أبا السائب المخزومي قول قيس\n(صدعت القلب ثم ذررت فيه ... هواك فليم فالتأم الفطور)\nصاح بجارية له سندية تسمى زبدة فقال أي زبدة عجلي فقالت أنا أعجن فقال ويحك تعالي ودعي العجين فجاءت فقال لي أنشد بيتي قيس فأعدتهما فقال لها يا زبدة أحسن قيس وإلا فأنت حرة ارجعي الآن إلى عجينك أدركيه لا يبرد قالوا وجعل قيس يعاتب نفسه في طاعته أباه في طلاقه لبنى ويقول فألا رحلت بها عن بلده فلم أر ما يفعل ولم يرني فكان إذا فقدني أقلع عما يفعله وإذا فقدته لم أتحرج من فعله وما كان علي لو اعتزلته وأقمت في حيها أو في بعض بوادي العرب أو عصيته فلم أطعه هذه جنايتي على نفسي فلا لوم على أحد وهأنذا ميت مما فعلته فمن يرد روحي إلي وهل لي سبيل إلى لبنى بعد الطلاق وكلما قرع نفسه وأنبها بلون من التقريع والتأنيب بكى أحر بكاء وألصق خده بالأرض ووضعه على آثارها ثم قال\n(ويلي وعولي ومالي حين تفلتني ... من بعد ما أحرزت كفي بها الظفرا)\n(قد قال قلبي لطرفي وهو يعذله ... هذا جزاؤك مني فاكدم الحجرا)\n(قد كنت أنهاك عنها لو تطاوعني ... فاصبر فما لك فيها أجر من صبرا)\nناه الغريض خفيف ثقيل أول بالوسطى عن عمرو وفيه لإبراهيم ثقيل أول بالوسطى عن حبش وفي الثالث والأول خفيف رمل يقال إنه لابن الهربذ قالوا وقال أيضا\n(بانت لبينى فأنت اليوم متبول ... والرأي عندك بعد الحزم مخبول)\n(أستودع الله لبنى إذ تفارقني ... بالرغم مني وقول الشيخ مفعول)\n(وقد أراني بلبنى حق مقتنع ... والشمل مجتمع والحبل موصول)\nقال خالد بن كلثوم وقال\n(ألا ليت لبنى في خلاء تزورني ... فأشكو إليها لوعتي ثم ترجع)\n(صحا كل ذي لب وكل متيم ... وقلبي بلبنى ما حييت مروع)\n(فيا من لقلب ما يفيق من الهوى ... ويا من لعين بالصبابة تدمع)\nالوا وقال في ليلته تلك\n(قد قلت للقلب لا لبناك فاعترف ... واقض اللبانة ما قضيت وانصرف)\n(قد كنت أحلف جهدا لا أفارقها ... أف لكثرة ذاك القيل والحلف)\n(حتى تكنفني الواشون فافتلتت ... لا تأمنن أبدا من غش مكتنف)\n(هيهات هيهات قد أمست مجاورة ... أهل العقيق وأمسينا على سرف)\nال وسرف على ستة أميال من مكة والعقيق واد باليمامة\n(حي يمانون والبطحاء منزلنا ... هذا لعمرك شمل غير مؤتلف)\nالوا فلما أصبح خرج متوجها نحو الطريق الذي سلكته يتنسم روائحها فسنحت له ظبية فقصدها فهربت منه فقال","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":5,"spl":"اشتاقها فقصدها وقال شعرا","tags":["الحب والغزل","الجواري والنساء","السفر والحج"],"song":1,"loc":1686},
{"id":"b94-7","bab":"الجزء 9","sec":"من شعره في لبنى","page":"ج9 ص223","text":"(ألا يا شبه لبنى لا تراعي ... ولا تتيممي قلل القلاع)\nهي قصيدة طويلة يقول فيها\n(فوا كبدي وعاودني رداعي ... وكان فراق لبنى كالخداع)\n(تكنفني الوشاة فأزعجوني ... فيا لله للواشي المطاع)\n(فأصبحت الغداة ألوم نفسي ... على شيء وليس بمستطاع)\n(كمغبون يعض على يديه ... تبين غبنه بعد البياع)\n(بدار مضيعة تركتك لبنى ... كذاك الحين يهدى للمضاع)\n(وقد عشنا نلذ العيش حينا ... لو ان الدهر للإنسان داع)\n(ولكن الجميع إلى افتراق ... وأسباب الحتوف لها دواع)\nغناه الغريض من القدر الأوسط من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق وفيه لمعبد خفيف ثقيل أول بالوسطى عن عمرو والهشامي ولشارية في البيتين الأولين ثقيل أول آخر بالوسطى ولابن سريج رمل بالوسطى عن الهشامي في\n(بدار مضيعة تركتك لبنى ... )\nقبله\n(فواكبدي وعاودني رداعي ... )\nلسياط في البيتين الأولين خفيف رمل بالبنصر عن حبش حدثني عمي عن الكراني عن العتبي عن أبيه قال بعثت أم قيس بن ذريح بفتيات من قومه إليه يعبن إليه لبنى ويعبنه بجزعه وبكائه ويتعرضن لوصاله فأتينه فاجتمعن حواليه وجعلن يمازحنه ويعبن لبنى عنده ويعيرنه ما يفعله فلما أطلن أقبل عليهن وقال\n(يقر بعيني قربها ويزيدني ... بها كلفا من كان عندي يعيبها)\n(وكم قائل قد قال تب فعصيته ... وتلك لعمري توبة لا أتوبها)\n(فيا نفس صبرا لست والله فاعلمي ... بأول نفس غاب عنها حبيبها)\nناه دحمان ثقيلا أول بالوسطى وفيه هزج بالبنصر لسليم وذكر حبش أنه لإسحاق قال فانصرفن عنه إلى أمه فأيأسنها من سلوته وقال سائر الرواة الذي ذكرتهم اجتمع إليه النسوة فأطلن الجلوس عنده وحادثنة وهو ساه\nعنهن ثم نادى يا لبنى فقلن له ما لك ويحك فقال خدرت رجلي ويقال إن دعاء الإنسان باسم أحب الناس إليه يذهب عنه خدر الرجل فناديتها لذلك فقمن عنه وقال\n(إذا خدرت رجلي تذكرت من لها ... فناديت لبنى باسمها ودعوت)\n(دعوت التي لو أن نفسي تطيعني ... لفارقتها من حبها وقضيت)\n(برت نبلها للصيد لبنى وريشت ... وريشت أخرى مثلها وبريت)\n(فلما رمتني أقصدتني بسهمها ... وأخطأتها بالسهم حين رميت)\n(وفارقت لبنى ضلة فكأنني ... قرنت إلى العيوق ثم هويت)\n(فيا ليت أني مت قبل فراقها ... وهل ترجعن فوت القضية ليت)\n(فصرت وشيخي كالذي عثرت به ... غداة الوغى بين العداة كميت)\n(فقامت ولم تضرر هناك سوية ... وفارسها تحت السنابك ميت)\n(فإن يك تهيامي بلبنى غواية ... فقد يا ذريح بن الحباب غويت)\n(فلا أنت ما أملت في رأيته ... ولا أنا لبنى والحياة حويت)\n(فوطن لهلكي منك نفسا فإنني ... كأنك بي قد يا ذريح قضيت)\nقال خالد بن كلثوم مرض قيس فسأل أبوه فتيات الحي أن يعدنه ويحدثنه لعله أن يتسلى أو يعلق بعضهن ففعلن ذلك ودخل إليه طبيب\nليداويه والفتيات معه فلما اجتمعن عنده جعلن يحادثنه وأطلن السؤال عن سبب علته فقال\n(عيد قيس من حب لبنى ولبنى ... داء قيس والحب داء شديد)\n(وإذا عادني العوائد يوما ... قالت العين لا أرى من أريد)\n(ليت لبنى تعودني ثم أقضي ... إنها لا تعود فيمن يعود)\n(ويح قيس لقد تضمن منها ... داء خبل فالقلب منه عميد)\nغناه ابن سريج خفيف رمل عن الهشامي وفيه للحجبي ثقيل أول بالوسطى وفيه ليحيى المكي رمل قالوا فقال له الطبيب منذ كم هذه العلة ومنذ كم وجدت بهذه المرأة ما وجدت فقال\n(تعلق روحي روحها قبل خلقنا ... ومن بعد ما كنا نطافا وفي المهد)\n(فزاد كما زدنا فأصبح ناميا ... وليس إذا متنا بمنصرم العهد)\n(ولكنه باق على كل حادث ... وزائرنا في ظلمة القبر واللحد)\nناه الغريض ثقيلا أول بالوسطى من رواية حبش قالوا فقال له الطبيب إن مما يسليك عنها أن تتذكر ما فيها من المساوئ والمعيب وما تعافه النفس من أقذار بني آدم فإن النفس تنبو حينئذ وتسلو ويخف ما بها فقال\n(إذا عبتها شبهتها البدر طالعا ... وحسبك من عيب لها شبه البدر)\n(لقد فضلت لبنى على الناس مثل ما ... على ألف شهر فضلت ليلة القدر)\nوت\n(إذا ما مشت شبرا من الأرض أرجفت ... من البهر حتى ما تزيد على شبر)\n(لها كفل يرتج منها إذا مشت ... ومتن كغصن البان مضطمر الخصر)","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":6,"spl":"من شعره في لبنى","tags":["الحب والغزل"],"song":3,"loc":1687,"partial":1},
{"id":"b94-8","bab":"الجزء 9","sec":"من شعره في لبنى","page":"ج9 ص223","text":"نى في هذين البيتين ابن المكي خفيف رمل بالوسطى وفيهما رمل ينسب إلى ابن سريج وإلى ابن طنبورة عن الهشامي قالوا ودخل أبوه وهو يخاطب الطبيب بهذه المخاطبة فأنبه ولامه وقال له يا بني الله الله في نفسك فإنك ميت إن دمت على هذا فقال\n(وفي عروة العذري إن مت أسوة ... وعمرو بن عجلان الذي قتلت هند)\n(وبي مثل ما ماتا به غير أنني ... إلى أجل لم يأتني وقته بعد)\n\n(هل الحب إلا عبرة بعد زفرة ... وحر على الأحشاء ليس له برد)\n(وفيض دموع تستهل إذا بدا ... لنا علم من أرضكم لم يكن يبدو)\nنى في هذين البيتين زيد بن الخطاب مولى سليمان بن أبي جعفر وقيل إنه مولى سليمان بن علي ثقيلا أول بالوسطى عن الهشامي وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير وأخبرنا اليزيدي عن ثعلب عن الزبير قال حدثني إسماعيل بن أبي أويس قال جلست أنا وأبو السائب في النبالين فأنشدني قول قيس بن ذريح\n(عيد قيس من حب لبنى ولبنى ... داء قيس والحب داء شديد)\n(ليت لبنى تعودني ثم أقضي ... إنها لا تعود فيمن يعود)\nال فأنشدته أنا لقيس\n(تعلق روحي روحها قبل خلقنا ... ومن بعد ما كنا نطافا وفي المهد)\n(فزاد كما زدنا وأصبح ناميا ... وليس إذا متنا بمنتقض العهد)\n(ولكنه باق على كل حادث ... وزائرنا في ظلمة القبر واللحد)\nحلف لا يزال يقوم ويقعد حتى يرويها فدخل زقاق النبالين وجعلت أرددها عليه ويقوم ويقعد حتى رواها رجع الخبر إلى سياقته","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":7,"spl":"من شعره في لبنى","tags":["الحب والغزل"],"song":1,"loc":1688},
{"id":"b94-9","bab":"الجزء 9","sec":"زوجوه لينسى لبنى","page":"ج9 ص228","text":"وقال خالد بن جمل فلما طال على قيس ما به أشار قومه على أبيه بأن يزوجه امرأة جميلة فلعله أن يسلو بها عن لبنى فدعاه إلى ذلك فأباه وقال\n(لقد خفت ألا تقنع النفس بعدها ... بشيء من الدنيا وإن كان مقنعا)\n(وأزجر عنها النفس إذ حيل دونها ... وتأبى إليها النفس إلا تطلعا)\nأعلمهم أبوه بما رد عليه قالوا فمره بالمسير في أحياء العرب والنزول عليهم فلعل عينه أن تقع على امرأة تعجبه فأقسم عليه أبوه أن يفعل فسار حتى نزل بحي من فزارة فرأى جارية حسناء قد حسرت برقع خز عن وجهها وهي كالبدر ليلة تمه فقال لها ما اسمك يا جارية قالت لبنى فسقط على وجهه مغشيا عليه فنضحت على وجهه ماء وارتاعت لما عراه ثم قالت إن لم يكن هذا قيس بن ذريح إنه لمجنون فأفاق فنسبته فانتسب فقالت قد علمت أنك قيس ولكن نشدتك بالله وبحق لبنى إلا أصبت من طعامنا وقدمت إليه طعاما فأصاب منه بإصبعه وركب فأتى على أثره أخ لها كان غائبا فرأى مناخ ناقته فسألهم عنه فأخبروه فركب حتى رده إلى منزله وحلف عليه ليقيمن عنده شهرا فقال له لقد شققت علي ولكني سأتبع هواك والفزاري يزداد إعجابا بحديثه وعقله وروايته فعرض عليه الصهر فقال له يا هذا إن فيك لرغبة ولكني في شغل لا ينتفع بي معه فلم يزل يعاوده والحي يلومونه ويقولون له قد خشينا أن يصير علينا فعلك سبة فقال دعوني ففي مثل هذا الفتى يرغب الكرام فلم يزل به حتى أجابه وعقد الصهر بينه وبينه على أخته المسماة لبنى\nوقال له أنا أسوق عنك صداقها فقال أنا والله يا أخي أكثر قومي مالا فما حاجتك إلى تكلف هذا أنا سائر إلى قومي وسائق إليها المهر ففعل وأعلم أباه الذي كان منه فسره وساق المهر عنه ورجع إلى الفزاريين حتى أدخلت عليه زوجته فلم يروه هش إليها ولا دنا منها ولا خاطبها بحرف ولا نظر إليها وأقام على ذلك أياما كثيرة ثم أعلمهم أنه يريد الخروج إلى قومه أياما فأذنوا له في ذلك فمضى لوجهه إلى المدينة وكان له صديق من الأنصار بها فأتاه فأعلمه الأنصاري أن خبر تزويجه بلغ لبنى فغمها وقالت إنه لغدار ولقد كنت أمتنع من إجابة قومي إلى التزويج فأنا الآن أجيبهم وقد كان أبوها شكا قيسا إلى معاوية وأعلمه\nتعرضه لها بعد الطلاق فكتب إلى مروان بن الحكم يهدر دمه إن تعرض لها وأمر أباها أن يزوجها رجلا يعرف بخالد بن حلزة من بني عبد الله بن غطفان ويقال بل أمره بتزويجها رجلا من آل كثير بن الصلت الكندي حليف قريش فزوجها أبوها منه قال فجعل نساء الحي يقلن ليلة زفافها\n(لبينى زوجها أصبح ... لا حر بواديه)\n(له فضل على الناس ... بما باتت تناجيه)\n(وقيس ميت حي ... صريع في بواكيه)\n(فلا يبعده الله ... وبعدا لنواعيه)\nال فجزع قيس جزعا شديدا وجعل ينشج أحر نشيج ويبكي أحر بكاء ثم ركب من فوره حتى أتى محلة قومها فناداه النساء ما تصنع الآن ها هنا قد نقلت لبنى إلى زوجها وجعل الفتيان يعارضونه بهذه المقالة وما أشبهها وهو لا يجيبهم حتى أتى موضع خبائها فنزل عن راحلته وجعل يتمعك في موضعها ويمرغ خده على ترابها ويبكي أحر بكاء ثم قال\n(إلى الله أشكو فقد لبنى كما شكا ... إلى الله فقد الوالدين يتيم)\n(يتيم جفاه الأقربون فجسمه ... نحيل وعهد الوالدين قديم)\n(بكت دارهم من نأيهم فتهللت ... دموعي فأي الجازعين ألوم)\n(أمستعبرا يبكي من الشوق والهوى ... أم آخر يبكي شجوه ويهيم)\nابن جامع في البيتين الأولين ثقيل أول بالوسطى عن الهشامي ولعريب فيهما ثاني ثقيل وفي الثالث والرابع لمياسة خفيف رمل بالبنصر عن عمرو وحبش والهشامي وتمام هذه الأبيات وليست فيها صنعة قوله\n(تهيضني من حب لبنى علائق ... وأصناف حب هولهن عظيم)\n(ومن يتعلق حب لبنى فؤاده ... يمت أو يعش ما عاش وهو كليم)\n(فإني وإن أجمعت عنك تجلدا ... على العهد فيما بيننا لمقيم)\n(وإن زمانا شتت الشمل بيننا ... وبينكم فيه العدا لمشوم)\n(أفي الحق هذا أن قلبك فارغ ... صحيح وقلبي في هواك سقيم)\nقد قيل إن هذه الأبيات ليست لقيس وإنما خلطت بشعره ولكنها في هذه الرواية منسوبة إليه قال وقال أيضا في رحيل لبنى عن وطنها وانتقالها إلى زوجها بالمدينة وهو مقيم في حيها\n(بانت لبينى فهاج القلب من بانا ... وكان ما وعدت مطلا وليانا)\n(وأخلفتك منى قد كنت تأملها ... فأصبح القلب بعد البين حيرانا)","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":8,"spl":"زوجوه لينسى لبنى","tags":["الحب والغزل"],"song":2,"loc":1689},
{"id":"b94-10","bab":"الجزء 9","sec":"زوجوه لينسى لبنى","page":"ج9 ص228","text":"(الله يدري وما يدري به أحد ... ماذا أجمجم من ذكراك أحيانا)\n(يا أكمل الناس من قرن إلى قدم ... وأحسن الناس ذا ثوب وعريانا)\n(نعم الضجيع بعيد النوم تجلبه ... إليك ممتلئا نوما ويقظانا)\nللغريض في هذه الأبيات ثاني ثقيل مطلق في مجرى البنصر عن إسحاق وعمرو وذكر الهشامي أن فيه لابن محرز ثاني ثقيل آخر وقال أحمد ابن عبيد فيه لحنان ليحيى المكي وعلويه وتمام هذه القصيدة\n(لا بارك الله فيمن كان يحسبكم ... إلا على العهد حتى كان ما كانا)\n(حتى استفقت أخيرا بعد ما نكحت ... كأنما كان ذاك القلب حيرانا)\n(قد زارني طيفكم ليلا فأرقني ... فبت للشوق أذري الدمع تهتانا)\n(إن تصرمي الحبل أو تمسي مفارقة ... فالدهر يحدث للإنسان ألوانا)\n(وما أرى مثلكم في الناس من بشر ... فقد رأيت به حيا ونسوانا)","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":9,"spl":"زوجوه لينسى لبنى","tags":["الحب والغزل"],"loc":1690},
{"id":"b94-11","bab":"الجزء 9","sec":"أبو لبنى يشكوه إلى معاوية","page":"ج9 ص232","text":"وقال ابن قتيبة في خبره عن الهيثم بن عدي ورواه عمر بن شبة أيضا أن أبا لبنى شخص إلى معاوية فشكا إليه قيسا وتعرضه لابنته بعد طلاقه إياها فكتب معاوية إلى مروان أو سعيد بن العاص يهدر دمه إن ألم بها وأن يشتد في لك فكتب مروان أو سعيد في ذلك إلى صاحب الماء الذي ينزله أبو لبنى كتابا وكيدا ووجهت لبنى رسولا قاصدا إلى قيس تعلمه ما جرى\nوتحذره وبلغ أباه الخبر فعاتبه وتجهمه وقال له انتهى بك الأمر إلى أن يهدر السلطان دمك فقال\n(فإن يحجبوها أو يحل دون وصلها ... مقالة واش أو وعيد أمير)\n(فلن يمنعوا عيني من دائم البكا ... ولن يذهبوا ما قد أجن ضميري)\n(إلى الله أشكو ما ألاقي من الهوى ... ومن حرق تعتادني وزفير)\n(ومن حرق للحب في باطن الحشى ... وليل طويل الحزن غير قصير)\n(سأبكي على نفسي بعين غزيرة ... بكاء حزين في الوثاق أسير)\n(وكنا جميعا قبل أن يظهر الهوى ... بأنعم حالي غبطة وسرور)\n(فما برح الواشون حتى بدت لهم ... بطون الهوى مقلوبة لظهور)\n(لقد كنت حسب النفس لو دام وصلنا ... ولكنما الدنيا متاع غرور)\nكذا في هذا الخبر أن الشعر لقيس بن ذريح وذكر الزبير بن بكار أنه لجده عبد الله بن مصعب غنى يزيد حوراء في الأول والثاني والسادس والثالث من هذه الأبيات خفيف رمل بالوسطى وغنى إبراهيم في\nالأول والثاني لحنا من كتابه غير مجنس وذكر حبش أن فيهما لإسحاق خفيف ثقيل بالوسطى وفي الخامس وما بعده لعريب ثقيل أول ابتداؤه نشيد وقال ابن الكلبي في خبره قال قيس في إهدار معاوية دمه إن زارها\n(إن تك لبنى قد أتى دون قربها ... حجاب منيع ما إليه سبيل)\n(فإن نسيم الجو يجمع بيننا ... ونبصر قرن الشمس حين تزول)\n(وأرواحنا بالليل في الحي تلتقي ... ونعلم أنا بالنهار نقيل)\n(وتجمعنا الأرض القرار وفوقنا ... سماء نرى فيها النجوم تجول)\n(إلى أن يعود الدهر سلما وتنقضي ... ترات بغاها عندنا وذحول)\nمما وجد في كتاب لابن النطاح قال العتبي حدثنا أبي قال حج قيس ابن ذريج واتفق أن حجت لبنى في تلك السنة فرآها ومعها امرأة من قومها فدهش وبقي واقفا مكانه ومضت لسبيلها ثم أرسلت إليه بالمرأة تبلغه السلام وتسأله عن خبره فألفته جالسا وحده ينشد ويبكي\n(ويوم منى أعرضت عني فلم أقل ... بحاجة نفس عند لبنى مقالها)\n(وفي اليأس للنفس المريضة راحة ... إذا النفس رامت خطة لا تنالها)\nدخلت خباءه وجعلت تحدثه عن لبنى ويحدثها عن نفسه مليا ولم تعلمه أن لبنى أرسلتها إليه فسألها أن تبلغها عنه السلام فامتنعت عليه فأنشأ يقول\n(إذا طلعت شمس النهار فسلمي ... فآية تسليمي عليك طلوعها)\n(بعشر تحيات إذا الشمس أشرقت ... وعشر إذا اصفرت وحان رجوعها)\n(ولو أبلغتها جارة قولي اسلمي ... بكت جزعا ارفض منها دموعها)\n(وبان الذي تخفي من الوجد في الحشى ... إذا جاءها عني حديث يروعها)\nنى في البيتين الأولين علويه خفيف رمل بالوسطى قال وقضى الناس حجهم وانصرفوا فمرض قيس في طريقه مرضا شديدا أشفى منه على الموت فلم يأته رسولها عائدا لأن قومها رأوه وعلموا به فقال\n(ألبنى لقد جلت عليك مصيبتي ... غداة غد إذ حل ما أتوقع)\n(تمنينني نيلا وتلوبنني به ... فنفسي شوقا كل يوم تقطع)\n(وقلبك قط ما يلين لما يرى ... فواكبدي قد طال هذا التضرع)\n(ألومك في شأني وأنت مليمة ... لعمري وأجفى للمحب وأقطع)\n(أخبرت أني فيك ميت حسرتي ... فما فاض من عينيك للوجد مدمع)\n(ولكن لعمري قد بكيتك جاهدا ... وإن كان دائي كله منك أجمع)\n(صبيحة جاء العائدات يعدنني ... فظلت علي العائدات تفجع)\n(فقائلة جئنا إليه وقد قضى ... وقائلة لا بل تركناه ينزع)\nروى القحذمي هاهنا\n(فما غشيت عينيك من ذاك عبرة ... وعيني على ما بي بذكراك تدمع)\n(إذا أنت لم تبكي علي جنازة ... لديك فلا تبكي غدا حين أرفع)\nال فبلغتها الأبيات فجزعت جزعا شديدا وبكت بكاء كثيرا ثم خرجت إليه ليلا على موعد فاعتذرت وقالت إنما أبقي عليك وأخشى أن تقتل فأنا أتحاماك لذلك ولولا هذا لما افترقنا وودعته وانصرفت وقال خالد بن كلثوم فبلغه أن أهلها قالوا لها إنه عليل لما به وإنه سيموت في سفره هذا فقالت لهم لتدفعهم عن نفسها ما أراه إلا كاذبا فيما يدعي ومتعللا لا عليلا فبلغه ذلك فقال\n(تكاد بلاد الله يا أم معمر ... بما رحبت يوما علي تضيق)","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":10,"spl":"أبو لبنى يشكوه إلى معاوية","tags":["الحب والغزل"],"song":1,"loc":1691},
{"id":"b94-12","bab":"الجزء 9","sec":"أبو لبنى يشكوه إلى معاوية","page":"ج9 ص232","text":"(تكذبني بالود لبنى وليتها ... تكلف مني مثله فتذوق)\n(ولو تعلمين الغيب أيقنت أنني ... لكم والهدايا المشعرات صديق)\n(تتوق إليك النفس ثم أردها ... حياء ومثلي بالحياء حقيق)\n(أذود سوام النفس عنك وما له ... على أحد إلا عليك طريق)\n(فإني وإن حاولت صرمي وهجرتي ... عليك من احداث الردى لشفيق)\n(ولم أر أياما كأيامنا التي ... مررن علينا والزمان أنيق)\n(ووعدك إيانا ولو قلت عاجل ... بعيد كما قد تعلمين سحيق)\n(وحدثتني يا قلب أنك صابر ... على البين من لبنى فسوف تذوق)\n(فمت كمدا أو عش سقيما فإنما ... تكلفني ما لا أراك تطيق)\n(أطعت وشاة لم يكن لك فيهم ... خليل ولا جار عليك شفيق)\n(فإن تك لما تسل عنها فإنني ... بها مغرم صب الفؤاد مشوق)\n(بلبنى أنادى عند أول غشية ... ويثني بها الداعي لها فأفيق)\n(شهدت على نفسي بأنك غادة ... رداح وأن الوجه منك عتيق)\n(وأنك لا تجزينني بصحابة ... ولا أنا للهجران منك مطيق)\n(وأنك قسمت الفؤاد فنصفه ... رهين ونصف في الحبال وثيق)\n(صبوحي إذا ماذرت الشمس ذكركم ... ولي ذكركم عند المساء غبوق)\n(إذا أنا عزيت الهوى أو تركته ... أتت عبرات بالدموع تسوق)\n(كأن الهوى بين الحيازيم والحشى ... وبين التراقي واللهاة حريق)\n(فإن كنت لما تعلمي العلم فاسألي ... فبعض لبعض في الفعال فؤوق)\n(سلي هل قلاني من عشير صحبته ... وهل مل رحلي في الرفاق رفيق)\n(وهل يجتوي القوم الكرام صحابتي ... إذا اغبر مخشي الفجاج عميق)\n(وأكتم أسرار الهوى فأميتها ... إذا باح مزاح بهن بروق)\n(سعى الدهر والواشون بيني وبينها ... فقطع حبل الوصل وهو وثيق)\n(هل الصبر إلا أن أصد فلا أرى ... بأرضك إلا أن يكون طريق)","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":11,"spl":"أبو لبنى يشكوه إلى معاوية — قصته مع لبنى وزوجها","tags":["الحب والغزل","اللهو والمزاح","السفر والحج"],"loc":1692},
{"id":"b94-13","bab":"الجزء 9","sec":"قصته مع لبنى وزوجها","page":"ج9 ص237","text":"قال ثم أتى قومه فاقتطع قطعة من إبله وأعلم أباه أنه يريد المدينة ليبيعها ويمتار لأهله بثمنها فعرف أبوه أنه إنما يريد لبنى فعاتبه وزجره عن ذلك فلم يقبل منه وأخذ إبله وقدم بها المدينة فبينا هو يعرضها إذ ساومه زوج لبنى بناقة منها وهما لا يتعارفان فباعه إياها فقال له إذا كان غد فأتني في دار كثير بن الصلت فاقبض الثمن\nقال نعم ومضى زوج لبنى إليها فقال لها إني ابتعت ناقة من رجل من أهل البادية وهو يأتينا غدا لقبض ثمنها فأعدي له طعاما ففعلت فلما كان من الغد جاء قيس فصوت بالخادم قولي لسيدك صاحب الناقة بالباب فعرفت لبنى نغمته فلم تقل شيئا فقال زوجها للخادم قولي له ادخل فدخل فجلس فقالت لبنى للخادم قولي له يا فتى مالي أراك أشعث أغبر فقالت له ذلك فتنفس ثم\nقال لها هكذا تكون حال من فارق الأحبة واختار الموت على الحياة وبكى فقالت لها لبنى قولي له حدثنا حديثك فلما ابتدأ يحدث به كشفت الحجاب وقالت حسبك قد عرفنا حديثك وأسبلت الحجاب فبهت ساعة لا يتكلم ثم انفجر باكيا ونهض فخرج فناداه زوجها ويحك ما قصتك ارجع اقبض ثمن ناقتك وإن شئت زدناك فلم يكلمه وخرج\nفاغترز في رحله ومضى وقالت لبنى لزوجها ويحك هذا قيس بن ذريح فما حملك على ما فعلت به قال ما عرفته وجعل قيس يبكي في طريقه ويندب نفسه ويوبخها علىفعله ثم قال\n(أبتكي على لبنى وأنت تركتها ... وأنت عليها بالملا أنت أقدر)\n(فإن تكن الدنيا بلبنى تقلبت ... علي فللدنيا بطون وأظهر)\n(لقد كان فيها للأمانة موضع ... وللكف مرتاد وللعين منظر)\n(وللحائم العطشان ري بريقها ... وللمرح المختال خمر ومسكر)\n(كأني لها أرجوحة بين أحبل ... إذا ذكرة منها على القلب تخطر)\nلغريض في البيتين الأولين ثقيل أول بالوسطى عن عمرو والهشامي وفيهما لعريب رمل ولشارية خفيف رمل من رواية أبي العبيس أخبرني الحرمي بن أبي العلاء\nقال حدثنا الزبير بن بكار قال حدثني عبد الملك بن عبد العزيز قال تزوج رجل من أهل المدينة يقال له أبو درة امرأة كانت قبله عند رجل آخر من أهل المدينة يقال له أبو بطينة فلقيه زوجها الأول فضربه ضربة شلت يده منها فلقيه أبو السائب المخزومي فقال له يا ابا درة أضربك أبو بطينة في زوجته قال نعم قال أما إني أشهد أنها ليست كما قال قيس بن ذريح في زوجته لبنى\n(لقد كان فيها للأمانة موضع ... وللكف مرتاد وللعين منظر)\n(وللحائم العطشان ري بريقها ... وللمرح المختال خمر ومسكر)\nال وكانت زوجة أبي درة هذه سوداء كأنها خنفساء","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":11,"spl":"أبو لبنى يشكوه إلى معاوية — قصته مع لبنى وزوجها","tags":["الجواري والنساء","اللهو والمزاح","السفر والحج"],"song":1,"loc":1693},
{"id":"b94-14","bab":"الجزء 9","sec":"مرض قيس","page":"ج9 ص239","text":"قال وعاد إلى قومه بعد رؤيته إياها وقد أنكر نفسه وأسف ولحقه أمر عظيم فأنكروه وسألوه عن حاله فلم يخبرهم ومرض مرضا شديدا أشرف منه على الموت فدخل إليه أبوه ورجال قومه فكلموه وعاتبوه وناشدوه الله فقال ويحكم أتروني أمرضت نفسي أو وجدت لها سلوة بعد اليأس فاخترت الهم والبلاء أو لي في ذلك صنع هذا ما اختاره لي أبواي وقتلاني به فجعل أبوه يبكي ويدعو له بالفرج والسلوة فقال قيس\n(لقد عذبتني يا حب لبنى ... فقع إما بموت أو حياة)\n(فإن الموت أروح من حياة ... تدوم على التباعد والشتات)\n(وقال الأقربون تعز عنها ... فقلت لهم إذا حانت وفاتي)\nال ودست إليه لبنى بعد خروجه رسولا وقالت له استنشده فإن سألك عن نسبتك فانتسب له خزاعيا فإذا أنشدك فقل له لم تزوجت بعدها حتى أجابت إلى أن تتزوج بعدك واحفظ ما يقول لك حتى ترده علي فأتاه الرسول فسلم وانتسب خزاعيا وذكر أنه من أهل الشام واستنشده فأنشده قوله\n(فأقسم ما عمش العيون شوارف ... روائم بو حانيات على شقب)\nقد مضت هذه الأبيات فقال له الرجل فلم تزوجت بعدها فأخبره الخبر وحلف له أن عينه ما اكتحلت بالمرأة التي تزوجها وأنه لو رآها في نسوة ما عرفها وأنه ما مد يده إليها ولا كلمها ولا كشف لها عن ثوب فقال له الرجل فإني جار لها وإنها من الوجد بك على حال قد تمنى زوجها معها أن تكون بقربها لتصلح حالها بك فحملني إليها ماشئت أؤده إليها قال\nتعود إلي إذا أردت الرحيل فعاد إليه لما أراد الرحيل فقال تقول لها\n(ألا حي لبنى اليوم إن كنت غاديا ... وألمم بها من قبل أن لا تلاقيا)\n(وأهد لها منك النصيحة إنها ... قليل ولا تخش الوشاة الأدانيا)\n(وقل إنني والراقصات إلى منى ... بأجبل جمع ينتظرن المناديا)\n(أصونك عن بعض الأمور مضنة ... وأخشى عليك الكاشحين الأعاديا)\n(تساقط نفسي حين ألقاك أنفسا ... يردن فما يصدرن إلا صواديا)\n(فإن أحي أو أهلك فلست بزائل ... لكم حافظا ما بل ريق لسانيا)\n(أقول إذا نفسي من الوجد أصعدت ... بها زفرة تعتادني هي ما هيا)\n(وبين الحشى والنحر مني حرارة ... ولوعة وجد تترك القلب ساهيا)\n(ألا ليت لبنى لم تكن لي خلة ... ولم ترني لبنى ولم أدر ما هيا)\n(سلي الناس هل خبرت سرك منهم ... أخا ثقة أو ظاهر الغش باديا)\n(يقول لي الواشون لما تظاهروا ... عليك وأضحى الحبل للبين واهيا)\n(لعمري لقبل اليوم حملت ما ترى ... وأنذرت من لبنى الذي كنت لاقيا)\n(خليلي مالي قد بليت ولا أرى ... لبيني على الهجران إلا كما هيا)\n(ألا يا غراب البين مالك كلما ... ذكرت لبينى طرت لي عن شماليا)\n(أعندك علم الغيب أم لست مخبري ... عن الحي إلا بالذي قد بدا ليا)\n(جزعت عليها لو أرى لي مجزعا ... وأفنيت دمع العين لو كان فانيا)\n(حياتك لا تغلب عليها فإنه ... كفى بالذي تلقى لنفسك ناهيا)\n(تمر الليالي والشهور ولا أرى ... ولوعي بها يزداد إلا تماديا)\n(فما عن نوال من لبينى زيارتي ... ولا قلة الإلمام أن كنت قاليا)\n(ولكنها صدت وحملت من هوى ... لها ما يؤود الشامخات الرواسيا)\nوهذه القصيدة تخلط بقصيدة المجنون التي في وزنها وعلى قافيتها لتشابههما فقلما يتميزان غنى الحسين بن محرز في البيت الأول والبيت الخامس من هذه القصيدة ثقيلا أول بإطلاق الوتر في مجرى الوسطى من روايتي بذل والهشامي\nحدثني المدائني عن عوانة عن يحيى بن علي الكناني قال شهر أمر قيس بالمدينة وغنى في شعره الغريض ومعبد ومالك وذووهم فلم يبق شريف ولا وضيع إلا سمع بذلك فأطربه وحزن لقيس مما به وجاءها زوجها فأنبها على ذلك وعاتبها\nوقال قد فضحتني بذكرك فغضبت وقالت يا هذا إني والله ما تزوجتك رغبة فيك ولا فيما عندك ولا دلس أمري عليك ولقد علمت أني كنت زوجته قبلك وأنه أكره على طلاقي ووالله ما قبلت التزويج حتى أهدر دمه إن ألم بحينا فخشيت أن يحمله ما يجد على المخاطرة فيقتل فتزوجتك وأمرك الآن إليك ففارقني فلا حاجة بي إليك فأمسك عن جوابها وجعل يأتيها بجواري المدينة يغنينها بشعر قيس كيما يستصلحها بذلك فلا تزداد إلا تماديا وبعدا ولا تزال تبكي كلما سمعت شيئا من ذلك أحر بكاء وأشجاه رجع الحديث إلى سياقته","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":12,"spl":"مرض قيس","tags":["الحب والغزل"],"loc":1694},
{"id":"b94-15","bab":"الجزء 9","sec":"بريكة تجمعهما سرا","page":"ج9 ص241","text":"وقال الحرمازي وخالد بن جمل كانت امرأة من موالي بني زهرة يقال لها بريكة من أظرف النساء وأكرمهن وكان لها زوج من قريش له دار ضيافة فلما طالت علة قيس قال له أبوه إني لأعلم أن شفاءك في القرب من لبنى فارحل إلى المدينة فرحل إليها حتى أتى دار الضيافة التي لزوج بريكة\nفوثب غلمانه إلى رحل قيس ليحطوه فقال لا تفعلوا فلست نازلا أو ألقى بريكة فإني قصدتها في حاجة فإن وجدت لها عندها موضعا نزلت بكم وإلا رحلت فأتوها فأخبروها فخرجت إليه فسلمت عليه ورحبت به وقالت حاجتك مقضية كائنة ما كانت فانزل ودنا منها فقال أذكر حاجتي قالت إن شئت\nقال أنا قيس بن ذريح قالت حياك الله وقربك إن ذكرك لجديد عندنا في كل وقت قال وحاجتي أن أرى لبنى نظرة واحدة كيف شئت قالت ذلك لك علي فنزل بهم وأقام عندها وأخفت أمره ثم أهدى لها هدايا كثيرة\nوقال لاطفيها وزوجها بهذا حتى يأنس بك ففعلت وزارتها مرارا ثم قالت لزوجها أخبرني عنك أنت خير من زوجي قال لا قالت فلبنى خير مني قال لا قالت فما بالي أزورها ولا تزورني\nقال ذلك إليها فأتتها وسألتها الزيارة وأعلمتها أن قيسا عندها فتسارعت إلى ذلك وأتتها فلما رآها ورأته بكيا حتى كادا يتلفان ثم جعلت تسأله عن خبره وعلته فيخبرها ويسألها فتخبره ثم قالت أنشدني ما قلت في علتك فأنشدها قوله\n(أعالج من نفسي بقايا حشاشة ... على رمق والعائدات تعود)\n(فإن ذكرت لبنى هششت لذكرها ... كما هش للثدي الدرور وليد)\n(أجيب بلبنى من دعاني تجلدا ... وبي زفرات تنجلي وتعود)\n(تعيد إلى روحي الحياة وإنني ... بنفسي لو عاينتني لأجود)\nال وفي هذه القصيدة يقول\n(ألا ليت أياما مضين تعود ... فإن عدن يوما إنني لسعيد)\n(سقى دار لبنى حيث حلت وخيمت ... من الأرض منهل الغمام رعود)\nفي هذين البيتين لعريب خفيف ثقيل أول مطلق في مجرى الوسطى وقيل إنه لغيرها وتمام هذه القصيدة\n(على كل حال إن دنت أو تباعدت ... فإن تدن منا فالدنو مزيد)\n(فلا اليأس يسليني ولا القرب نافعي ... ولبنى منوع ما تكاد تجود)\n(كأني من لبنى سليم مسهد ... يظل على أيدي الرجال يميد)\n(رمتني لبينى في الفؤاد بسهمها ... وسهم لبينى للفؤاد صيود)\n(سلا كل ذي شجو علمت مكانه ... وقلبي للبنى ما حييت ودود)\n(وقائلة قد مات أو هو ميت ... وللنفس مني أن تفيض رصيد)\n(أعالج من نفسي بقايا حشاشة ... على رمق والعائدات تعود)\nقال الحرمازي في خبره خاصة وعاتبته على تزوجه فحلف أنه لم ينظر إليها ملء عينيه ولا دنا منها فصدقته وقال\n(ولقد أردت الصبر عنك فعاقني ... علق بقلبي من هواك قديم)\n(يبقى على حدث الزمان وريبه ... وعلى جفائك إنه لكريم)\n(فصرمته وصححت وهو بدائه ... شتان بين مصحح وسقيم)\n(واربته زمنا فعاد بحلمه ... إن المحب عن الحبيب حليم)\nعريب في هذه الأبيات خفيف ثقيل وللدارمي خفيف رمل من رواية الهشامي ومن الناس من ينسب خفيف الثقيل إليه وخفيف الرمل إليها قالوا فلم يزل يومه معها يحدثها ويشكو إليها أعف شكوى وأكرم حديث حتى\nأمسى فانصرفت ووعدته الرجوع إليه من غد فلم ترجع وشاع خبره فلم ترسل إليه رسولا فكتب هذه الأبيات في رقعة ودفعها إلى بريكة وسألها أن توصلها إليها ورحل متوجها إلى معاوية والأبيات\n(بنفسي من قلبي له الدهر ذاكر ... ومن هو عني معرض القلب صابر)\n(ومن حبه يزداد عندي جدة ... وحبي لديه مخلق العهد داثر)\nنت في هذين البيتين ضنين جارية خاقان بن حامد خفيف رمل قالوا","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":13,"spl":"بريكة تجمعهما سرا","tags":["الحب والغزل"],"song":3,"loc":1695},
{"id":"b94-16","bab":"الجزء 9","sec":"يزيد يرق لحاله","page":"ج9 ص244","text":"ثم ارتحل إلى معاوية فدخل إلى يزيد فشكا ما به إليه وامتدحه فرق له وقال سل ما شئت إن شئت أن أكتب إلى زوجها فأحتم عليه أن يطلقها فعلت\nقال لا أريد ذلك ولكن أحب أن أقيم بحيث تقيم من البلاد أتعرف أخبارها وأقنع بذلك من غير أن يهدر دمي قال لو سألت هذا من غير أن ترحل إلينا فيه لما وجب أن تمنعه فأقم حيث شئت وأخذ كتاب أبيه له بأن يقيم حيث شاء وأحب ولا يعترض عليه أحد وأزال ما كان كتب به في إهدار دمه فقدم إلى بلده وبلغ الفزاريين خبره وإلمامه بلبنى فكاتبوه في ذلك وعاتبوه فقال للرسول قل للفتى يعني أخا الجارية التي تزوجها يا أخي ما غررتك من نفسي ولقد أعلمتك أني مشغول عن كل أحد وقد جعلت أمر أختك إليك فأمض فيه من حكمك ما رأيت فتكرم الفتى عن أن يفرق بينهما فمكثت في حباله مدة ثم ماتت أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني سليمان بن عياش السعدي عن أبيه قال\nأقبلت ذات يوم من الغابة فلما كنت بالمذاذ إذا ربع حديث العهد بالساكن وإذا رجل مجتمع في جانب ذلك الربع يبكي ويحدث نفسه فسلمت فلم يرد علي سلاما فقلت في نفسي رجل ملتبس به فوليت عنه فصاح بي بعد ساعة وعليك السلام هلم هلم إلي يا صاحب السلام فأتيته فقال أما والله لقد فهمت سلامك ولكني رجل مشترك اللب يضل عني أحيانا ثم يعود إلي فقلت ومن أنت قال قيس بن ذريح الليثي قلت صاحب لبنى قال صاحب لبنى لعمري وقتيلها ثم أرسل عينيه كأنهما مزادتان فما أنسى حسن قوله\n(أبائنة لبنى ولم تقطع المدى ... بوصل ولا صرم فييأس طامع)\n(نهاري نهار الوالهين صبابة ... وليلى تنبو فيه عني المضاجع)\n(وقد كنت قبل اليوم خلوا وإنما ... تقسم بين الهالكين المصارع)\n(فلولا رجاء القلب أن تسعف النوى ... لما حبسته بينهن الأضالع)\n(له وجبات إثر لبنى كأنها ... شقائق برق في السماء لوامع)\n(أبى الله أن يلقى الرشاد متيم ... ألا كل أمر حم لا بد واقع)\n(هما برحابي معولين كلاهما ... فؤاد وعين جفنها الدهر دامع)\nخبرني الحسن بن علي قال حدثنا أحمد بن سعيد قال حدثنا الزبير قال وأخبرنا به وكيع عن أبي أيوب المديني قال الزبير قال حدثتني ظبية قالت\nسمعت عبد الله بن مسلم بن جندب ينشد زوجي قول قيس بن ذريح\n(إذا ذكرت لبنى تأوه واشتكى ... تأوه محموم عليه البلابل)\n(يبيت ويضحى تحت ظل منية ... به رمق تبكي عليه القبائل)\n(قتيل للبنى صدع الحب قلبه ... وفي الحب شغل للمحبين شاغل)\nصاح زوجي أوه واحرباه واسلباه ثم أقبل على ابن جندب فقال ويلك أتنشد هذا كذا قال فكيف أنشده قال لم لا تتأوه كما يتأوه وتشتكي كما يشتكي وقال القحذمي قال ابن أبي عتيق لقيس يوما أنشدني أحر ما قلت في لبنى فأنشده قوله\n(وإني لأهوى النوم في غير حينه ... لعل لقاء في المنام يكون)\n(تحدثني الأحلام أني أراكم ... فيا ليت أحلام المنام يقين)\n(شهدت بأني لم أحل عن مودة ... وأني بكم لو تعلمين ضنين)\n(وأن فؤادي لا يلين إلى هوى ... سواك وإن قالوا بلى سيلين)\nقال له ابن أبي عتيق لقل ما رضيت به منها يا قيس قال ذلك جهد المقل غنى في البيتين الأولين قفا النجار ثاني ثقيل بالوسطى عن حبش أخبرني أحمد بن جعفر جحظة قال أنشدني أحمد بن يحيى ثعلب\nلقيس بن ذريح وكان يستحسن هذه الأبيات من شعره\n(سقى طلل الدار التي أنتم بها ... حيا ثم وبل صيف وربيع)\n(مضى زمن والناس يستشفعون بي ... فهل لي إلى لبنى الغداة شفيع)\n(سأصرم لبنى حبلك اليوم مجملا ... وإن كان صرم الحبل منك يروع)\n(وسوف أسلي النفس عنك كما سلا ... عن البلد النائي البعيد نزيع)\n(وإن مسني للضر منك كآبة ... وإن نال جسمي للفراق خشوع)\n(يقولون صب بالنساء موكل ... وما ذاك من فعل الرجال بديع)\n(ندمت على ما كان مني ندامة ... كما ندم المغبون حين يبيع)\n(فقدتك من نفس شعاع ألم أكن ... نهيتك عن هذا وأنت جميع)\n(فقربت لي غير القريب وأشرفت ... هناك ثنايا ما لهن طلوع)\n(إلى الله أشكو نية شقت العصا ... هي اليوم شتى وهي أمس جميع)\n(فيا حجرات الدار حيث تحملوا ... بذي سلم لا جادكن ربيع)\n\n(فلو لم يهجني الظاعنون لهاجني ... حمائم ورق في الديار وقوع)\n(تداعين فاستبكين من كان ذا هوى ... نوائح لم تقطر لهن دموع)\nنى في هذين البيتين ابن سريج خفيف ثقيل أول عن الهشامي","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":14,"spl":"يزيد يرق لحاله","tags":["الحب والغزل"],"song":2,"loc":1696},
{"id":"b94-17","bab":"الجزء 9","sec":"يزيد يرق لحاله","page":"ج9 ص244","text":"(إذا أمرتني العاذلات بهجرها ... أبت كبد عما يقلن صديع)\n(وكيف أطيع العاذلات وذكرها ... يؤرقني والعاذلات هجوع)\nنى في هذين البيتين إبراهيم ثاني ثقيل بالبنصر عن عمرو","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":15,"spl":"يزيد يرق لحاله — فكاهات لأبي السائب المخزومي في شعره وفي سيرته","tags":[],"loc":1697},
{"id":"b94-18","bab":"الجزء 9","sec":"فكاهات لأبي السائب المخزومي في شعره وفي سيرته","page":"ج9 ص248","text":"أخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني عبد الملك بن عبد العزيز قال أنشدت أبا السائب المخزومي قول قيس بن ذريح\n\n(أحبك أصنافا من الحب لم أجد ... لها مثلا في سائر الناس يوصف)\n(فمنهن حب للحبيب ورحمة ... بمعرفتي منه بما يتكلف)\n(ومنهن ألا يعرض الدهر ذكرها ... على القلب إلا كادت النفس تتلف)\n(وحب بدا بالجسم واللون ظاهر ... وحب لدى نفسي من الروح ألطف)\nال أبو السائب لا جرم والله لأخلصن له الصفاء ولأغضبن لغضبه\nولأرضين لرضاه غنى في البيتين الأولين الحسين بن محرز خفيف ثقيل عن الهشامي وبذل أخبرني الحرمي قال حدثنا الزبير قال حدثنا عبد الملك بن عبد العزيز عن أبي السائب المخزومي أنه أخبره أنه كان مع عبد الرحمن بن عبد الله بن كثير في سقيفة دار كثير إذ مر بجنازة فقال لي يا أبا السائب جارك ابن كلدة ألا تقوم بنا فنصلي عليه\nقال قلت بلى والله فديتك فقمنا حتى إذا كنا عند دار أويس إذ ذكرت أن جده كان تزوج لبنى ونزل بها المدينة فرجعت فطرحت نفسي في السقيفة وقلت لا يراني الله أصلي عليه فرجع الكثيري فقال أكنت جنبا\nقلت لا والله قال فعلى غير وضوء قلت لا والله قال فما لك قلت ذكرت أن جده كان تزوج لبنى وفرق بينها وبين قيس بن ذريح لما ظعن بها من بلادها فما كنت لأصلي عليه\nأخبرني محمد بن العباس اليزيدي قال حدثنا أحمد بن يحيى قال حدثنا عبد الله بن شبيب قال حدثني هارون بن موسى الفروي قال أخبرنا الخليل ابن سعيد\nقال مررت بسوق الطير فإذا الناس قد اجتمعوا يركب بعضهم بعضا فاطلعت فإذا أبو السائب المخزومي قائم على غراب يباع وقد أخذ بطرف ردائه وهو يقول للغراب يقول لك قيس بن ذريح\n(ألا يا غراب البين قد طرت بالذي ... أحاذر من لبنى فهل أنت واقع)\nم لا تقع ويضربه بردائه والغراب يصيح قال فقال قائل له أصلحك الله يا أبا السائب ليس هذا ذاك الغراب فقال قد علمت ولكن آخذ البريء حتى يقع الجريء\nوقال الحرمازي في خبره لما بلغ لبنى قول قيس\n(ألا يا غراب البين قد طرت بالذي ... أحاذر من لبنى فهل أنت واقع)\nلت ألا ترى غرابا إلا قتلته فكانت كلما رأته أو رأته خادم لها أو جارة ابتيع ممن هو معه وذبحته وهذه القصيدة العينية أيضا من جيد شعر قيس والمختار منها قوله\n(أتبكي على لبنى وأنت تركتها ... وكنت كآت حتفه وهو طائع)\n(فيا قلب صبرا واعترافا لما ترى ... ويا حبها قع بالذي أنت واقع)\n(ويا قلب خبرني إذا شطت النوى ... بلبنى وبانت عنك ما أنت صانع)\n(أتصبر للبين المشت مع الجوى ... أم انت امرؤ ناسي الحياء فجازع)\n(كأنك بدع لم تر الناس قبلها ... ولم يطلعك الدهر فيمن يطالع)\n(ألا يا غراب البين قد طرت بالذي ... أحاذر من لبنى فهل أنت واقع)\n(فليس محب دائما لحبيبه ... ولا ثقة إلا له الدهر فاجع)\n(كأن بلاد الله ما لم تكن بها ... وإن كان فيها الناس قفر بلاقع)\n(فما أنت إذ بانت لبينى بهاجع ... إذا ما اطمأنت بالنيام المضاجع)\nوت\n(أقضي نهاري بالحديث وبالمنى ... ويجمعني والهم بالليل جامع)\n(نهاري نهار الناس حتى إذا دجا ... لي الليل هزتني إليك المضاجع)\n(لقد رسخت في القلب منك مودة ... كما رسخت في الراحتين الأصابع)\n(أحال علي الهم من كل جانب ... ودامت فلم تبرح علي الفواجع)\n(ألا إنما أبكي لما هو واقع ... فهل جزعي من وشك ذلك نافع)\n(وقد كنت أبكي والنوى مطمئنة ... بنا وبكم من علم ما البين صانع)\n(وأهجركم هجر البغيض وحبكم ... على كبدي منه كلوم صوادع)\n(وأعمد للأرض التي لا أريدها ... لترجعني يوما إليك الرواجع)\n(وأشفق من هجرانكم وتروعني ... مخافة وشك البين والشمل جامع)\n(فما كل ما منتك نفسك خاليا ... تلاقي ولا كل الهوى أنت تابع)\n(لعمري لمن أمسى ولبنى ضجيعه ... من الناس ما اختيرت عليه المضاجع)\n(فتلك لبينى قد تراخى مزارها ... وتلك نواها غربة ما تطاوع)\n(وليس لأمر حاول الله جمعه ... مشت ولا ما فرق الله جامع)\n(فلا تبكين في إثر لبنى ندامة ... وقد نزعتها من يديك النوازع)","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":15,"spl":"يزيد يرق لحاله — فكاهات لأبي السائب المخزومي في شعره وفي سيرته","tags":["الحب والغزل"],"song":1,"loc":1698},
{"id":"b94-19","bab":"الجزء 9","sec":"فكاهات لأبي السائب المخزومي في شعره وفي سيرته","page":"ج9 ص248","text":"نى الغريض في الثالث والرابع والأول والعشرين وهو لعمري لمن أمسى ولبنى ضجيعه ثقيلا أول بالسبابة في مجرى الوسطى عن إسحاق وغنى إبراهيم الموصلي في العاشر وهو أقضي نهاري بالحديث وبالمنى والحادي عشر والثاني عشر رملا بالوسطى عن عمرو وقد قيل إن ثلاثة أبيات من هذه وهي أقضي نهاري بالحديث وبالمنى والبيتان اللذان بعده لابن الدمينة الخثعمي وهو الصحيح وإنما أدخلها الناس في هذه الأبيات لتشابهها","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":16,"spl":"فكاهات لأبي السائب المخزومي في شعره وفي سيرته","tags":[],"loc":1699},
{"id":"b94-20","bab":"الجزء 9","sec":"نهاية قيس ولبنى","page":"ج9 ص251","text":"وقد اختلف في آخر أمر قيس ولبنى فذكر أكثر الرواة أنهما ماتا على افتراقهما فمنهم من قال إنه مات قبلها وبلغها ذلك فماتت أسفا عليه ومنهم من قال بل ماتت قبله ومات بعدها أسفا عليها وممن ذكر ذلك\nاليوسفي عن علي بن صالح صاحب المصلى قال قال لي أبو عمرو المدني ماتت لبنى فخرج قيس ومعه جماعة من أهله فوقف على قبرها فقال\n(ماتت لبينى فموتها موتي ... هل تنفعن حسرتي على الفوت)\n(وسوف أبكي بكاء مكتئب ... قضى حياة وجدا على ميت)\nم أكب على القبر يبكي حتى أغمي عليه فرفعه أهله إلى منزله وهو لا يعقل فلم يزل عليلا لا يفيق ولا يجيب مكلما ثلاثا حتى مات فدفن إلى جنبها\nوذكر القحذمي وابن عائشة وخالد بن جمل أن ابن أبي عتيق صار إلى الحسن والحسين ابني علي بن أبي طالب وعبد الله بن جعفر رضي الله عنهم وجماعة من قريش فقال لهم إن لي حاجة إلى رجل أخشى أن يردني فيها وإني أستعين بجاهكم وأموالكم فيها عليه قالوا ذلك لك مبتذل منا فاجتمعوا ليوم وعدهم فيه فمضى بهم إلى زوج لبنى فلما رآهم أعظم مصيرهم إليه وأكبره فقالوا لقد جئناك بأجمعنا في حاجة لابن أبي عتيق قال هي مقضية كائنة ما كانت قال ابن أبي عتيق قد قضيتها كائنة ما كانت من ملك أو مال أو أهل قال نعم قال تهب لهم ولي لبنى زوجتك\nوتطلقها قال فإني أشهدكم أنها طالق ثلاثا فآستحيا القوم واعتذروا وقالوا والله ما عرفنا حاجته ولو علمنا أنها هذه ما سألناك إياها وقال ابن عائشة فعوضه الحسن من ذلك مائة ألف درهم وحملها ابن أبي عتيق إليه فلم تزل عنده حتى انقضت عدتها فسأل القوم أباها فزوجها قيسا فلم تزل معه حتى ماتا قالوا فقال قيس يمدح ابن أبي عتيق\n(جزى الرحمن أفضل ما يجازي ... على الإحسان خيرا من صديق)\n(فقد جربت إخواني جميعا ... فما ألفيت كابن أبي عتيق)\n(سعى في جمع شملي بعد صدع ... ورأي حدت فيه عن الطريق)\n(وأطفأ لوعة كانت بقلبي ... أغصتني حرارتها بريقي)\nال فقال له ابن أبي عتيق يا حبيبي أمسك عن هذا المديح فما يسمعه أحد إلا ظنني قوادا مضى الحديث ومن مدن معبد وهو الذي أوله\n(يا دار عبلة بالجواء تكلمي ... )\nقد جمع معه سائر ما يغنى فيه من القصيدة منها\n(هل غادر الشعراء من متردم ... أم هل عرفت الدار بعد توهم)\n(يا دار عبلة بالجواء تكلمي ... وعمي صباحا دار عبلة واسلمي)\n(وتحل عبلة بالجواء وأهلنا ... بالحزن فالصمان فالمتثلم)\n(كيف القرار وقد تربع أهلها ... بعنيزتين وأهلنا بالغيلم)\n(حييت من طلل تقادم عهده ... أقوى وأقفر بعد أم الهيثم)\n(ولقد نزلت فلا تظني غيره ... مني بمنزلة المحب المكرم)\n(ولقد خشيت بأن أموت ولم تدر ... للحرب دائرة على ابني ضمضم)\n(الشاتمي عرضي ولم أشتمهما ... والناذرين إذا لم القهما دمي)\n(ولقد شفى نفسي وأبرأ سقمها ... قيل الفوارس ويك عنتر فاقدم)\n(ما زلت أرميهم بثغرة نحره ... ولبانه حتى تسربل بالدم)\n(هلا سألت الخيل يابنة مالك ... إن كنت جاهلة بما لم تعلمي)\n(يخبرك من شهد الوقيعة أنني ... أعشى الوغى وأعف عند المغنم)\n(يدعون عنتر والرماح كأنها ... أشطان بئر في لبان الأدهم)\n(فشككت بالرمح الطويل ثيابه ... ليس الكريم على القنا بمحرم)\n(فإذا شربت فإنني مستهلك ... مالي وعرضي وافر لم يكلم)\n(وإذا صحوت فما أقصر عن ندى ... وكما علمت شمائلي وتكرمي)\nلشعر لعنترة بن شداد العبسي وقد تقدمت أخباره ونسبه وغنى في البيت الأول على ما ذكره ابن المكي إسحاق خفيف ثقيل أول بالوسطى وما وجدت هذا في رواية غيره وغنى معبد في البيت الثاني والثالث خفيف ثقيل أول بإطلاق الوتر في مجرى الوسطى عن إسحاق وهو الصوت المعدود\nفي مدن معبد وغنى سلام الغسال في السابع والثامن والثالث والعاشر رملا بالسبابة في مجرى البنصر ووجدت في بعض الكتب أن له أيضا في السابع وحده ثاني ثقيل أيضا\nوذكر عمرو بن بانة أن هذا الثقيل الثاني بالوسطى لمعبد ووافقه يونس وذكر ابن المكي أن هذا الثقيل الثاني للهذلي وذكر غيره أنه لابن محرز","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":17,"spl":"نهاية قيس ولبنى","tags":["المديح"],"song":1,"loc":1700,"partial":1},
{"id":"b94-21","bab":"الجزء 9","sec":"نهاية قيس ولبنى","page":"ج9 ص251","text":"وذكر أحمد بن عبيد أن في السابع ثقيلا أول للهذلي ووافقه حبش وذكر حبش أن في الثاني لمعبد ثقيلا أول وأن لابن سريج فيه رملا آخر غير رمل ابن الغسال وأن لابن مسجح أيضا فيه خفيف ثقيل بالوسطى وفي كتاب أبي العبيس له في الثالث لحن وفي كتاب أبي أيوب المديني لابن جامع في هذه الأبيات لحن ولمعبد في الحادي عشر والثاني عشر والخامس عشر والسادس عشر خفيف ثقيلا أول مطلق في مجرى الوسطى عن إسحاق أيضا ولعلويه في السادس والرابع ثاني ثقيل وله أيضا في الرابع عشر والثالث عشر رمل وفي كتاب هارون بن الزيات لعبد آل في الخامس ثقيل أول وقد نسب الثقيل الثاني المختلف فيه لابن محرز وفي كتاب هارون لأحمد النصبي في الرابع والخامس لحن هل غادر الشعراء البيت يدفع اكثر الرواة أن يكون لعنترة وممن يدفعه الأصمعي وابن الأعرابي وأول القصيدة عندهما يا دار عبلة فذكر أبو عمرو الشيباني أنه لم يكن يرويه حتى سمع ابا حزام العكلي يرويه له قوله هل غادر الشعراء من متردم يقول هل تركوا شيئا ينظر فيه لم ينظروا فيه والمتردم المتعطف وهو مصدر يقول هل تركوا شيئا يتردم عليه أي يتعطف ويقال تردمت الناقة على ولدها إذا تعطفت عليه وثوب مردم وملدم إذا سدت خروقه بالرقاع والربع المنزل سمي ربعا لارتباعهم فيه والربيعة الصخرة حكى أبو نصر أنه يقول هل ترك الشعراء من خرق لم يرقعوه وفتق لم يرتقوه وهو أشبه بقوله من متردم وقال غيره يعني بقوله\nمن متردم البناء وهو الردم أي لم يتركوا بناء إلا بنوه قال الله عز و جل ( أجعل بينكم وبينهم ردما\nيعني بناء وردم فلان حائطه أي بناه والجواء بلد بعينه والجواء أيضا جمع جو وهو البطن الواسع من الأرض عمي صباحا وانعمي صباحا تحية تربع أهلها نزلوا في الربيع وعنيزتين أكمة سوداء بين البصرة ومكة والغيلم موضع والطلل ما كان له شخص من الدار مثل أثفية أو وتد أو نؤي وتقول العرب حيا الله طللك أي شخصك وابنا ضمضم حصين وهرم المريان وثغرة نحره موضع لبته واللبان مجرى لببه من صدره وهو الصدر نفسه ويروى بغرة وجهه وتسربل أي صار له سربال من الدم وقوله هلا سألت الخيل يريد فرسان الخيل كما قال الله تعالى ( واسأل القرية\nوالوقيعة الوقعة والوغى والوحى أصوات الناس وجلبتهم في الحرب وقال الشاعر\n(وليل كساج الحميري ادرعته ... كأن وغى حافاته لغط العجم)\nالأشطان الحبال واحدها شطن شبه اختلاف الرماح في صدر فرسه بالأشطان وشككت بالرمح نظمت وقال أبو عمرو يعني بثيابه قلبه والعرض موضع المدح والذم من الرجل يقال طيب العرض أي طيب ريح الجسم والكلوم الجراح والوافر التام وشمائلي أخلاقي واحدها شمال يقال فلان حلو الشمائل والنحائت والضرائب والغرائز","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":18,"spl":"نهاية قيس ولبنى","tags":["الحب والغزل"],"loc":1701},
{"id":"b94-22","bab":"الجزء 9","sec":"سبب قول عنترة معلقته","page":"ج9 ص256","text":"أخبرني علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري قال قال أبو عمرو الشيباني قال عنترة هذه القصيدة لأن رجلا من بني عبس سابه فذكر سواده وسواد\nأمه وإخوته وعيره ذلك فقال عنترة والله إن الناس ليترافدون بالطعمة فوالله ما حضرت مرفد الناس أنت ولا أبوك ولا جدك قط وإن الناس ليدعون في الفزع فما رأيتك في خيل قط ولا كنت في أول النساء وإن اللبس يعني الاختلاط ليكون بيننا فما حضرت أنت ولا أحد من أهل بيتك لخطة فيصل قط وكنت فقعا بقرقرة ولو كنت في مرتبتك ومغرسك الذي أنت فيه ثم ما جدتك لمجدتك أو طاولتك لطلتك ولو سألت أمك وأباك عن هذا لأخبراك بصحته وإني لأحتضر الوغى وأوفى المغنم وأعف عن المسألة وأجود بما ملكت وأفصل الخطة الصمعاء فقال له الآخر أنا أشعر منك فقال ستعلم وكان عنترة لا يقول من الشعر إلا البيت أو البيتين في الحرب فقال هذه القصيدة ويزعمون أنها أول قصيدة قالها وكانت العرب تسميها المذهبة نسبة الأصوات التي جعلت مكان بعض هذه الأصوات في مدن معبد وهن\n(تقطع من ظلامة الوصل أجمع ... أخيرا على أن لم يكن يتقطع)\n(وأصبحت قد ودعت ظلامة التي ... تضر وما كانت مع الضر تنفع)\nالشعر لكثير والغناء لمعبد خفيف ثقيل أول بالبنصر عن عمرو ويونس\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني سليمان بن عياش السعدي قال قال السائب راوية كثير وأخبرني إسماعيل بن يونس\nقال حدثنا عمر بن شبة قال زعم ابن الكلبي عن أبي المقوم قال حدثني سائب راوية كثير قال كنت مع كثير عند ظلامة فأقمنا أياما فلما أردنا الانصراف عقدت له في علاقة سوطه عقدا وقالت احفظها ثم انصرفنا فمررنا على ماء لبني ضمرة فقال إن في هذه الأخبية جارية ظريفة ذات جمال فهل لك أن تستبرزها فقلت ذاك إليك\nقال فملنا إليهم فخرجت إلينا جاريتها فأخرجتها إلينا فإذا هي عزة فجلس معها يحادثها وطرح سوطه بينه وبينها إلى أن غلبته عيناه وأقبلت عزة على تلك العقد تحلها واحدة واحدة فلما استيقظ انصرفنا فنظر إلى علاقة سوطه فقال أحلتها قلت نعم فلا وصلها الله والله إنك لمجنون قال فسكت عني طويلا ثم رفع السوط فضرب به واسطة رحله وأنشأ يقول\n(تقطع من ظلامة الوصل أجمع ... أخيرا على أن لم يكن يتقطع)\n(وأصبحت قد ودعت ظلامة التي ... تضر وما كانت مع الضر تنفع)\n(وقد سد من أبواب ظلامة التي ... لنا خلف للنفس منها ومقنع)\nم وصل عزة بعد ذلك وقطع ظلامة ومنها وهو الذي أوله خمصانة قلق موشحها\n\n(أقوى من ال ظليمة الحزم ... فالغمرتان فأوحش الخطم)\n(فجنوب أثبرة فملحدها ... فالسدرتان فما حوى دسم)\n(وبما أرى شخصا به حسنا ... في القوم إذ حيتكم نعم)\n(إذ ودها صاف ورؤيتها ... أمنية وكلامها غنم)\n(لفاء مملوء مخلخلها ... عجزاء ليس لعظمها حجم)\n(خمصانة قلق موشحها ... رؤد الشباب علا بها عظم)\n(وكأن غالية تباشرها ... تحت الثياب إذا صغا النجم)\n(أظليم إن مصابكم رجلا ... أهدى السلام تحية ظلم)\n(أقصيته وأراد سلمكم ... فليهنه إذ جاءك السلم)\nروضه من الكامل الشعر للحارث بن خالد المخزومي والغناء لمعبد ولحنه من القدر الأوسط من الثقيل الأول بالخنصر في مجرى البنصر قال ولحن معبد\n(خمصانة قلق موشحها ... )\nأول لحن مالك\n(أقوى من ال ظليمة الحزم ... )","topic":"ذكر قيس بن ذريح ونسبه وأخباره","topicNo":94,"sp":19,"spl":"سبب قول عنترة معلقته","tags":["الجواري والنساء"],"song":2,"loc":1702,"partial":1}]);
window.__BOOK__['p05'].push([{"id":"b95-1","bab":"الجزء 9","sec":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","page":"ج9 ص261","text":"الحارث بن خالد بن العاصي بن هشام بن المغيرة بن عبد الله بن عمر بن مخزوم وقد تقدم ذكره وأخباره في كتاب المائة المختارة في بعض الأغاني المختارة التي شعرها له وهو\n(إن امرأ تعتاده ذكر ... )\nخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال بلغني أن الحارث بن خالد بن العاصي بن هشام بن المغيرة ويقال بل خالد بن المهاجر بن خالد بن الوليد بن المغيرة كان تزوج حميدة بنت النعمان بن بشير بدمشق لما قدم على عبد الملك بن مروان فقالت فيه\n(نكحت المديني إذ جاءني ... فيا لك من نكحة غاوية)\n(كهول دمشق وشبانها ... أحب إلينا من الجالية)\n(صنان لهم كصنان التيوس ... أعيا على المسك والغالية)\nفقال الحارث يجيبها\n(أسنا ضوء نار ضمرة بالقفرة ... أبصرت أم سنا ضوء برق)\n(قاطنات الحجون أشهى إلى قلبي ... من ساكنات دور دمشق)\n(يتضوعن لو تضمخن بالمسك ... صنانا كأنه ريح مرق)\nناه مالك بن أبي السمح خفيف ثقيل أول بالسبابة في مجرى البنصر من رواية إسحاق وفيه لابن محرز لحن من رواية عمرو بن بانة ثقيل أول بالوسطى رجعت الرواية إلى خبر الحارث قال وطلقها الحارث فخلف عليها روح بن زنباع قال وكان الحارث خطب أمة لمالك بن عبد الله بن خالد بن أسيد وخطبها عبد الله بن مطيع\nفتزوجها عبد الله ثم طلقها أو مات عنها فتزوجها الحارث بن خالد بعد ذلك وقال فيها قبل أن يتزوج\n(أقوى من آل ظليمة الحزم ... فالغمرتان فأوحش الخطم)\nلأبيات التي فيها الغناء قال وأخبرني محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثنا محمد بن الحكم عن عوانة بهذا الخبر فذكر مثله ولم يذكر أن الحارث هو المتزوجها وفسر قولها\n(أحب إلينا من الجالية ... )\nقال الجالية أهل الحجاز كان أهل الشام يسمونهم بذلك لأنهم كانوا يجلون عن بلادهم إلى الشام وقال في الحديث فبلغ عبد الملك قولها فقال لولا أنها قدمت الكهول على الشبان لعاقبتها قال عوانة وكانت لحميدة أخت يقال لها عمرة وكانت تحت المختار ابن أبي عبيد الثقفي فأخذها مصعب بعد قتله المختار وأخذ امرأته الأخرى وهي بنت سمرة بن جندب فأمرهما بالبراءة من المختار أما بنت سمرة فبرئت منه وأبت ذلك عمرة فكتب به مصعب إلى أخيه عبد الله فكتب\nإليه إن أبت أن تبرأ منه فاقتلها فأبت فحفر لها حفيرة وأقيمت فيها فقتلت فقال عمر بن أبي ربيعة في ذلك\n(إن من أعجب العجائب عندي ... قتل بيضاء حرة عطبول)\n(قتلت حرة على غير جرم ... إن لله درها من قتيل)\n(كتب القتل والقتال علينا ... وعلى الغانيات جر الذيول)\nجع الحديث إلى رواية عمر بن شبة قال أبو زيد وحدثني ابن عائشة عن أبيه بهذا الخبر ونحوه وزاد فيه أن الحارث لما تزوجها قالت فيه\n(نكحت المديني إذ جاءني ... فيا لك من نكحة غاويه)\nذكر الأبيات المتقدمة وقال عمر بن شبة فيه وتزوجها روح بن زنباع فنظر إليها يوما تنظر إلى قومه جذام وقد اجتمعوا عنده فلامها فقالت وهل أرى إلا جذام فوالله ما أحب الحلال منهم فكيف بالحرام وقالت تهجوه\n(بكى الخز من روح وأنكر جلده ... وعجت عجيجا من جذام المطارف)\n(وقال العبا قد كنت حينا لباسكم ... وأكسية كردية وقطائف)\nقال روح\n(إن تبك منا تبك ممن يهينها ... وإن تهوكم تهو اللئام المقارفا)\nوقال روح\n(أثني علي بما علمت فإنني ... مثن عليك لبئس حشو المنطق)\nفقالت\n(أثني عليك بأن باعك ضيق ... وبأن اصلك في جذام ملصق)\nقال روح\n(أثني علي بما علمت فإنني ... مثن عليك بمثل ريح الجورب)\nقالت\n(فثناؤنا شر الثناء عليكم ... أسوا وأنتن من سلاح الثعلب)\nقالت\n(وهل أنا إلا مهرة عربية ... سليلة أفراس تجللها بغل)\n(فإن نتجت مهرا كريما فبالحرى ... وإن يك إقراف فما أنجب الفحل)\nقال روح\n(فما بال مهر رائع عرضت له ... أتان فبالت عند جحفلة البغل)\n(إذا هو ولى جانبا ربخت له ... كما ربخت قمراء في دمس سهل)\nقالت عمرة لأخيها أبان بن النعمان\n(أطال الله شأوك من غلام ... متى كانت مناكحنا جذام)\n(أترضى بالأكارع والذنابى ... وقد كنا يقر بنا السنام)\nقال ابن عم لروح\n(رضي الأشياخ بالفطيون فحلا ... وترغب للحماقة عن جذام)\n(يهودي له بضع العذارى ... فقبحا للكهول وللغلام)\n(تزف إليه قبل الزوج خود ... كأن شمسا تدلت من غمام)\n(فأبقى ذلكم عارا وخزيا ... بقاء الوحي في صم السلام)","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":0,"spl":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","tags":[],"song":1,"loc":1703,"partialRef":{"sid":"b30-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b95-2","bab":"الجزء 9","sec":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","page":"ج9 ص261","text":"(يهود جمعوا من كل أوب ... وليسوا بالغطاريف الكرام)\nوقالت\n(سميت روحا وأنت الغم قد علموا ... لا روح الله عن روح بن زنباع)\nقال روح\n(لا روح الله عمن ليس يمنعنا ... مال رغيب وبعل غير ممناع)\n(كشافع جونة ثجل مخاصرها ... دبابة شثنة الكفين جباع)\nقال والجباع القصيرة والجباع من السهام الذي لا نصل له والجباع الرصف وقالت\n(تكحل عينيك برد العشي ... كأنك مومسة زانيه)\n(وآية ذلك بعد الخفوق ... تغلف رأسك بالغاليه)\n(وأن بنيك لريب الزمان ... أمست رقابهم حاليه)\n(فلوكان أوس لهم حاضرا ... لقال لهم إن ذا ماليه)\nأوس رجل من جذام يقال إنه استودع روحا مالا فلم يرده عليه فقال لها روح\n(إن يكن الخلع من بالكم ... فليس الخلاعة من باليه)\n(وإن كان من قد مضى مثلكم ... فأف وتف على الماضيه)\n(وما إن برا الله فاستيقنيه ... من ذات بعل ومن جاريه)\n(شبيها بك اليوم فيمن بقي ... ولا كان في الأعصر الخاليه)\n(فبعدا لمحياك إذ ما حييت ... وبعدا لأعظمك الباليه)\nقال روح في بعض ما يتنازعان فيه اللهم إن بقيت بعدي فابتلها ببعل يلطم وجهها ويملأ حجرها قيئا فتزوجها بعده الفيض بن محمد بن الحكم بن أبي عقيل وكان شابا جميلا يصيب من الشراب فأحبته فكان ربما أصاب من الشراب مسكرا فيلطم وجهها ويقيء في حجرها فتقول يرحم الله أبا زرعة قد أجيبت دعوته في وقالت لفيض\n(سميت فيضا وما شيء تفيض به ... إلا سلاحك بين الباب والدار)\n(فتلك دعوة روح الخير أعرفها ... سقى الإله صداه الأوطف الساري)\nقالت لفيض أيضا\n(ألا يا فيض كنت أراك فيضا ... فلا فيضا أصبت ولا فراتا)\nقالت\n(وليس فيض بفياض العطاء لنا ... لكن فيضا لنا بالقيء فياض)\n(ليث الليوث علينا باسل شرس ... وفي الحروب هيوب الصدر جياض)\nولدت من الفيض ابنة فتزوجها الحجاج بن يوسف وقد كانت قبلها عند الحجاج أم أبان بنت النعمان بن بشير فقالت حميدة للحجاج\n(إذا تذكرت نكاح الحجاج ... من النهار أو من الليل الداج)\n(فاضت له العين بدمع ثجاج ... وأشعل القلب بوجد وهاج)\n(لو كان نعمان قتيل الأعلاج ... مستوي الشخص صحيح الأوداج)\n(لكنت منها بمكان النساج ... قد كنت أرجو بعض ما يرجو الراج)\n(أن تنكحيه ملكا أو ذا تاج ... )\nقدمت حميدة على ابنتها زائرة فقال لها الحجاج يا حميدة إني كنت\nأحتمل مزاحك مرة وأما اليوم فإني بالعراق وهم قوم سوء فإياك فقالت سأكف حتى أرحل أخبرني محمد بن خلف وكيع قال حدثنا سليمان بن أيوب قال\nحدثنا المدائني عن مسلمة بن محارب قال قالت حميدة بنت النعمان لزوجها روح بن زنباع وكان أسود ضخما كيف تسود وفيك ثلاث خصال أنت من جذام وأنت جبان وأنت غيور فقال أما جذام فأنا في أرومتها وبحسب الرجل أن يكون في أرومة قومه وأما الجبن فإنما لي نفس واحدة ولو كان لي نفسان لجدت بإحداهما وأما الغيرة فهو أمر لا أحب أن أشارك فيه وإن المرء لحقيق بالغيرة على المرأة مثلك الحمقاء الورهاء لا يأمن أن تأتي بولدمن غيره فتقذفه في حجره ثم ذكر باقي خبرها مثل ما تقدم وقال فيه فخلف بعده عليها الفيض بن محمد عم يوسف بن عمر فكان يشرب ويلطمها ويقيء في حجرها فقالت\n(سميت فيضا وما شيء تفيض به ... إلا سلاحك بين الباب والدار)\nال المدائني وتمثل فيض يوما بهذا البيت\n(إن كنت ساقية يوما على كرم ... صفو المدامة فاسقيها بني قطن)\nم تحرك فضرط فقالت واسق هذه أيضا بني قطن وهذا الصوت أعني\n(أقوى من آل ظليمة الحزم ... )\nهو الصوت الذي أشخص الواثق له أبا عثمان المازني بسبب بيت منه اختلف في إعرابه بحضرته وهو قوله\n(أظليم إن مصابكم رجلا ... أهدى السلام تحية ظلم)\nقال آخرون رجل حدثني بذلك علي بن سليمان الأخفش عن أبي العباس محمد بن يزيد عن أبي عثمان وأخبرني محمد بن يحيى الصولي قال حدثنا القاسم بن إسماعيل وعون بن محمد وعبد الواحد بن العباس بن عبد الواحد والطيب بن محمد الباهلي يزيد بعضهم على بعض قالوا حدثنا أبو عثمان المازني قال كان سبب طلب الواثق لي أن مخارقا غنى في مجلسه\n(أظليم إن مصابكم رجلا ... أهدى السلام تحية ظلم)\nغناه مخارق رجل فتابعه بعض القوم وخالفه آخرون فسأل الواثق\nعمن بقي من رؤساء النحويين فذكرت له فأمر بحملي فلما وصلت إليه قال ممن الرجل قلت من بني مازن قال أمن مازن تميم أم مازن قيس أم مازن ربيعة أم مازن اليمن","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":1,"spl":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","tags":["الجواري والنساء"],"loc":1704,"partialRef":{"sid":"b95-1","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b95-3","bab":"الجزء 9","sec":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","page":"ج9 ص261","text":"قلت من مازن ربيعة فقال لي با اسمك يريد ما اسمك وهي لغة كثيرة في قومنا فقلت على القياس مكر أي بكر فضحك فقال اجلس واطبئن يريد واطمئن فجلست فسألني عن البيت فقلت إن مصابكم رجلا فقال أين خبر إن\nقلت ظلم وهو الحرف الذي في آخر البيت وقال الأخفش في خبره وقلت له إن معنى مصابكم إصابتكم مثل ما تقول إن قتلكم رجلا حياكم ظلم ثم قلت يا أمير المؤمنين إن البيت كله معلق لا معنى له حتى يتم بقوله ظلم ألا ترى أنه لو\nقال أظليم إن مصابكم رجل أهدى السلام تحية لما احتيج إلى ظلم ولا كان له معنى إلا أن يجعل التحية بالسلام ظلما وذلك محال ويجب حينئذ أن يقول\n(أظليم إن مصابكم رجل ... أهدى السلام تحية ظلما)\nلا معنى لذلك ولا هو لو كان له وجه معنى قول الشاعر في شعره فقال صدقت ألك ولد قلت بنية لا غير قال فما قالت حين ودعتها قال قلت أنشدت شعر الأعشى\n(تقول ابنتي حين جد الرحيل ... أرانا سواء ومن قد يتم)\n(أبانا فلا رمت من عندنا ... فإنا بخير إذا لم ترم)\n(أرانا إذا أضمرتك البلاد ... نجفى وتقطع منا الرحم)\nال فما قلت لها قال قلت لها قول جرير\n(ثقي بالله ليس له شريك ... ومن عند الخليفة بالنجاح)\nقال ثق بالنجاح إن شاء الله تعالى إن ها هنا قوما يختلفون إلى أولادنا فامتحنهم فمن كان منهم عالما ينتفع به ألزمناهم إياه ومن كان بغير هذه الصورة قطعناه عنهم فأمر فجمعوا إلي فامتحنتهم فما وجدت فيهم طائلا\nوحذروا ناحيتي فقلت لا بأس على أحد فلما رجعت إليه قال كيف رأيتهم قلت يفضل بعضهم بعضا في علوم ويفضل الباقون في غيرها وكل يحتاج إليه فقال لي الواثق إني خاطبت منهم واحدا فكان في نهاية من الجهل في خطابه ونظره فقلت يا أمير المؤمنين أكثر من تقدم منهم بهذه الصفة ولقد أنشدت فيهم\n(إن المعلم لا يزال مضعفا ... ولو ابتنى فوق السماء بناء)\n(من علم الصبيان أضنوا عقله ... مما يلاقي غدوة ومساء)\nضى الحديث ومنها\n(يوم تبدي لنا قتيلة عن جيد ... أسيل تزينه الأطواق)\n(وشتيت كالأقحوان جلاه الطل ... فيه عذوبة واتساق)\nلشعر للأعشى والغناء لمعبد وذكر إسحاق أن لحنه خفيف ثقيل من أصوات قليلات الأشباه وذكر عمرو بن بانة أن لحنه من الثقيل الأول بالبنصر ولإسحاق لحن من الثقيل أيضا وهو مما عارض فيه معبدا فانتصف منه ومن أوائل أغانيه وصدورها أخبرنا إسماعيل بن يونس الشيعي\nقال حدثنا عمر بن شبة عن إسحاق قال ذكر الحسن بن عتبة اللهبي المعروف بفورك قال قال لي الوليد بن يزيد أريد الحج فما يمنعني منه إلا أن يلقاني أهل المدينة بقتيلات معبد وبقصره ونخله فأفتضح به طربا يعني ثلاثة أصوات لمعبد من شعر الأعشى في قتيلة هذه ونسبتها تأتي بعد ويعني بقصره ونخله لحنه\n(القصر فالنخل فالجماء بينهما ... )\nال أبو زيد قال إسحاق وحدثني عبد الملك بن هلال وبلغني أن فتية من قريش دخلوا إلى قينة ومعهم روح بن حاتم المهلبي فتماروا فيما يختارونه من الغناء فقالت لهم أغني لكم صوتا يزيل الاختلاف ويوقع بينكم الاجتماع فرضوا بها فغنت\n(يوم تبدي لنا قتيلة عن جيد ... أسيل تزينه الأطواق)\nرضوا به واتفقوا على أنه أحسن صوت يعرفونه وأقاموا عندها أسبوعا لا يسمعون غيره نسبة أصوات معبد في قتيلة منها\n(أثوى وقصر ليله ليزودا ... فمضى وأخلف من قتيلة موعدا)\n(يجحدن ديني بالنهار وأقتضي ... ديني إذا وقذ النعاس الرقدا)\n(وأرى الغواني لا يواصلن امرأ ... فقد الشباب وقد يصلن الأمردا)\nلشعر للأعشى والغناء لمعبد خفيف ثقيل أول بالوسطى\nأخبرني محمد بن العباس اليزيدي قال حدثنا أبو شراعة في مجلس الرياشي قال حدثت أن رجلا نظر إلى الأعشى يدور بين البيوت ليلا فقال له يا أبا بصير إلى أين في هذا الوقت فقال\n(يجحدن ديني بالنهار وأقتضى ... ديني إذا وقذ النعاس الرقدا)\nخبرني أحمد بن عبيد الله بن عمار قال حدثنا يعقوب بن إسرائيل قال حدثنا أحمد بن القاسم بن جعفر بن سليمان قال حدثني إسحاق الموصلي قال حدثني أبي قال غنيت بين يدي الرشيد وستارته منصوبة\n(وأرى الغواني لا يواصلن امرأ ... فقد الشباب وقد يصلن الأمردا)\nطرب واستعاده وأمر لي بمال فلما أردت أن أنصرف قال لي يا عاض كذا وكذا أتغني بهذا الصوت وجواري من وراء ستارة يسمعنه لولا حرمتك لضربت عنقك فتركته والله حتى أنسيته ومنها","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":2,"spl":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","tags":[],"song":2,"loc":1705,"partialRef":{"sid":"b1-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b95-4","bab":"الجزء 9","sec":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","page":"ج9 ص261","text":"(ألم خيال من قتيلة بعد ما ... وهى حبلها من حبالنا فتصرما)\n(فبت كأني شارب بعد هجعة ... سخامية حمراء تحسب عندما)\nلشعر للأعشى والغناء لمعبد خفيف ثقيل أول بالبنصر عن عمرو وفيه لابن محرز ثاني ثقيل بالوسطى عنه وعن ابن المكي","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":3,"spl":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","tags":[],"loc":1706},
{"id":"b95-5","bab":"الجزء 9","sec":"سبعة ابن سريج","page":"ج9 ص275","text":"فأما السبعة التي جعلت لابن سريج بإزاء سبعة معبد فإني قرأت خبرها في كتاب محمد بن الحسن قال حدثني الحسين بن أحمد الأكثمي عن أبيه قال ذكرنا عند إسحاق يوما أصوات معبد السبعة فقال والله ما سبعة ابن سريج بدونهن فقلنا له وأي سبعة فقال إن مغني المكيين لما سمعوا بسبعة معبد وشهرتها لحقتهم لذلك غيرة فاجتمعوا فاختاروا من غناء ابن سريج سبعة فجعلوها بإزاء سبعة معبد ثم خايروا أهل المدينة فانتصفوا منهم فسألوا إسحاق عن السبعة السريجية فقال منها\n(تشكى الكميت الجري لما جهدته ... )\nوقد مضت نسبته في الثلاثة الأصوات المختارة\n(و لقد حببت نعم إلينا بوجهها ... )\n(و قرب جيراننا جمالهم ... )\n(و أرقت وما هذا السهاد المؤرق ... )\nقد مضى في أخبار الأعشى المذكورة في مدن معبد\n(و بينا كذاك إذا عجاجة موكب ... )\n(و فلم أر كالتجمير منظر ناظر ... )\nقد مضى في الأرمال المختارة\n(و تضوع مسكا بطن نعمان إذ مشت ... )\nوقد ذكر في المائة مع غيره في شعر النميري\n(و إن جاء فليأت على بغلة ... )\nنسبة ما لم تمض نسبته من هذه الأصوات إذ كان بعضها قد مضى متقدما فمنها\n(لقد حببت نعم إلينا بوجهها ... مساكن ما بين الوتائر فالنقع)\n(ومن أجل ذات الخال أعملت ناقتي ... أكلفها سير الكلال مع الظلع)\nعروضه من الطويل والشعر لعمر بن أبي ربيعة والغناء لابن سريج ثاني ثقيل بالبنصر وذات الخال التي عناها هاهنا عمر امرأة من ولد أبي سفيان بن حرب كان عمر يكني عنها بذلك\nحدثني علي بن صالح بن الهيثم قال حدثني أبو هفان عن إسحاق بن إبراهيم الموصلي عن الزبيري والمسيبي ومحمد بن سلام والمدائني وأخبرنا به الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني عمي ولم يتجاوزه أن عمر بن أبي ربيعة وابن أبي عتيق كانا جالسين بفناء الكعبة إذا مرت بهما امرأة من آل أبي سفيان فدعا عمر بكتف فكتب إليها وكنى عن اسمها\n(ألما بذات الخال فاستطلعا لنا ... على العهد باق ودها أم تصرما)\n(وقولا لها إن النوى أجنبية ... بنا وبكم قد خفت أن تتيمما)\nناه ابن سريج خفيف ثقيل أول بالسبابة في مجرى البنصر عن إسحاق قال فقال له ابن أبي عتيق سبحان الله ما تريد إلى امرأة مسلمة محرمة أن تكتب إليها مثل هذا قال فكيف بما قد سيرته في الناس من قولي\n(لقد حببت نعم إلينا بوجهها ... مساكن ما بين الوتائر و النقع)\n(ومن أجل ذات الخال أعملت ناقتي ... أدلفها سير الكلال مع الظلع)\n(ومن أجل ذات الخال يوم لقيتها ... بمندفع الأخباب أخضلني دمعي)\n(ومن أجل ذات الخال آلف منزلا ... أحل به لا ذا صديق ولا زرع)\n(ومن أجل ذات الخال عدت كأنني ... مخامر سقم داخل أو أخو ربع)\n(ألما بذات الخال إن مقامها ... لدى الباب زاد القلب صدعا على صدع)\n(وأخرى لدى البيت العتيق نظرتها ... إليها تمشت في عظامي وفي سمعي)\nقال الحرمي في خبره أما ترى ما سار لي من الشعر ما علم الله أني اطلعت حراما قط ثم انصرفنا فلما كان من الغد التقينا فقال عمر أشعرت أن ذلك الإنسان قد رد الجواب قال وما كان من رده قال كتب\n(أمسى قريضك بالهوى نماما ... فاربع هديت وكن له كتاما)\n(واعلم بأن الخال حين وصفته ... قعد العدو به عليك وقاما)\n(لا تحسبن الكاشحين عدمتهم ... عما يسوءك غافلين نياما)\n(لا تمكنن من الدفينة كاشحا ... يتلو بها حفظا عليك إماما)\nنى فيه سليم خفيف رمل بالبنصر عن عمرو قال وفيه لفريدة وإبراهيم لحنان وفي بعض النسخ لإسحاق فيه ثقيل أول غير منسوب وذكر حبش أن خفيف الرمل لفريدة أخبرني محمد بن خلف وكيع قال أخبرنا أبو أيوب المديني عن محمد ابن سلام قال وأخبرني حماد بن إسحاق عن أبيه عن محمد بن سلام قال سألت عمر بن أبي خليفة العبدي وكان عابدا وكان يعجبه الغناء أي\nالقوم كان أحسن غناء قال ابن سريج إذا تمعبد يريد إذا غنى في مذهب معبد من الثقيل قلت مثل ماذا قال مثل صوته\n(لقد حببت نعم إلينا بوجهها ... مساكن ما بين الوتائر فالنقع)\nقال حماد بن إسحاق حدثني أبي قال حدثني أبو محمد العامري قال جلس معبد والأبجر وجماعة من المغنين فتذاكروا ابن سريج وما اشتهاه الناس من غنائه فقالوا ما هو إلا من غناء الزطف والمخنثين فنمي الحديث إلى ابن سريج فغنى\n(لقد حببت نعم إلينا بوجهها ... )","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":4,"spl":"سبعة ابن سريج","tags":["الحب والغزل"],"song":4,"loc":1707,"partialRef":{"sid":"b1-1","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b95-6","bab":"الجزء 9","sec":"سبعة ابن سريج","page":"ج9 ص275","text":"لما جاء معبد وأصحابه واجتمعوا غناهم إياه فلما سمعوه قاموا هاربين وجعل ابن سريج يصفق خلفهم ويقول إلى أين إنما هو ابن ليلته فكيف لو اختمر قال فقال معبد دعوه مع طرائقه الأول ولا تهيجوه على طرائقكم وإلا لم يدع لكم والله خبزا تأكلونه قال الزبير في خبره عن عمه وعلق نعما هذه فقال فيها شعرا كثيرا ونحن نذكر هاهنا ما فيه غناء من ذلك فمنه قوله\n(خطرت لذات الخال ذكرى بعد ما ... سلك المطي بنا على الأنصاب)\n(أنصاب عمرة والمطي كأنها ... قطع القطا صدرت عن الأجباب)\n(فانهل دمعي في الرداء صبابة ... فسترته بالبرد عن أصحابي)\n(فرأى سوابق دمعة مسكوبة ... بكر فقال بكى أبو الخطاب)\nروضه من الكامل بكر الذي ذكره هاهنا عمر هو ابن أبي عتيق وهو يسميه في شعره ببكر وبعتيق وإياه يعني بقوله\n(لا تلمني عتيق حسبي الذي بي ... إن بي يا عتيق ما قد كفاني)\nلغناء في خطرت لذات الخال للغريض ولحنه ثقيل أول بإطلاق الوتر في مجرى البنصر عن إسحاق وذكر عمرو بن بانة أن فيه ثقيلا أول بالبنصر لأبي سعيد مولى فائد\nوأخبرني الحرمي قال حدثني الزبير قال حدثني عمي أن عمر بن أبي ربيعة وافقها وهي تستلم الركن فقرب منها فلما رأته تأخرت وبعثت إليه جاريتها فقالت له تقول لك ابنة عمك إن هذا مقام لا بد منه كما ترى وأنا اعلم أنك ستقول في موقفنا هذا فلا تقولن هجرا فأرسل إليها لست أقول إلا خيرا ثم تعرض لها وهي ترمي الجمار فأعرضت عنه واستترت فقال\n(دين هذا القلب من نعم ... بسقام ليس كالسقم)\n(إن نعما أقصدت رجلا ... آمنا بالخيف إذ ترمي)\n(اسمعي منا تحاورنا ... واحكمي رضيت بالحكم)\n(بشتيت نبته رتل ... طيب الأنياب والطعم)\n(يأتكم منه بحجته ... فله العتبى ولا أحمي)\nعروضه من المديد الغناء لإسحاق خفيف رمل بالوسطى عن عمرو وفيه لمالك ثقيل أول من أصوات قليلات الأشباه عن إسحاق وفيه لابن سريج رمل بالبنصر عن حبش وفيه لابن مسجح ثقيل أول بالوسطى عن حبش أيضا وذكر الهشامي أن هذا الصوت مما يشك فيه أنه لمعبد أو غيره قال وقال فيها أيضا\n(أبيني اليوم أي نعم ... أوصل منك أم صرم)\n(فإن يك صرم عاتبة ... فقد نغنى وهو سلم)\n(تلومك في الهوى نعم ... وليس لها به علم)\n(صحيح لو رأى نعما ... لخالط جسمه سقم)\nروضه من الهزج غناه مالك ولحنه ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وفيه لمتيم خفيف رمل بالبنصر عن إسحاق وذكر أن فيه أيضا صنعة لابن سريج ومما يغنى فيه مما قاله فيها وهو من قصيدة طويلة\n\n(فقلت لجناد خذ السيف واشتمل ... عليه بحزم وانظر الشمس تغرب)\n(وأسرج لنا الدهماء واعجل بممطري ... ولا تعلمن خلقا من الناس مذهبي)\nروضه من الطويل غناه زرزور غلام المارقي خفيف ثقيل بالبنصر أخبرني الحرمي قال حدثنا الزبير قال حدثني عمي قال قيل لعمر بن أبي ربيعة ما أحب شيء أصبته إليك\nقال بينا أنا في منزلي ذات ليلة إذ طرقني رسول مصعب بن الزبير بكتابه يقول إنه قد وقعت عندنا أثواب مما يشبهك وقد بعثت بها إليك وبدنانير ومسك وطيب وبغلة\nقال فإذا بثياب من وشي وخز العراق لم أر مثلها قط وأربعمائة دينار ومسك وطيب كثير وبغلة فلما أصبحت لبست بعض تلك الثياب وتطيبت وأحرزت الدنانير وركبت البغلة وأنا نشيط لا هم لي قد أحرزت نفقة سنتي فما أفدت فائدة كانت أحب إلي منها وقلت في ذلك\n(ألا أرسلت نعم إلينا أن ائتنا ... فأحبب بها من مرسل متغضب)\n(فأرسلت أن لا أستطيع فأرسلت ... تؤكد أيمان الحبيب المؤنب)\n(فقلت لجناد خذ السيف واشتمل ... عليه بحزم وانظر الشمس تغرب)\n(وأسرج لي الدهماء واعجل بممطري ... ولا تعلمن خلقا من الناس مذهبي)\n(وموعدك البطحاء أو بطن يأجج ... أو الشعب بالممروخ من بطن مغرب)\n(فلما التقنيا سلمت وتبسمت ... وقالت مقال المعرض المتجنب)\n(أمن أجل واش كاشح بنميمة ... مشى بيننا صدقته لم تكذب)\n(قطعت وصال الحبل منا ومن يطع ... بذي وده قول المحرش يعتب)\n(فبات وسادي ثني كف مخضب ... معاود عذب لم يكدر بمشرب)\n(إذا ملت مالت كالكثيب رخيمة ... منعمة حسانة المتجلبب)\nخبرني الحرمي قال حدثنا الزبير قال حدثني عمي قال بلغ عمر بن أبي ربيعة أن نعما اغتسلت في غدير فنزل عليه ولم يزل يشرب منه حتى نضب قال الزبير قال عمي وقال فيها أيضا\n(طال ليلي وعادني اليوم سقم ... وأصابت مقاتل القلب نعم)","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":5,"spl":"سبعة ابن سريج","tags":["الحب والغزل"],"song":5,"loc":1708},
{"id":"b95-7","bab":"الجزء 9","sec":"سبعة ابن سريج","page":"ج9 ص275","text":"(وأصابت مقاتلي بسهام ... نافذات وما تبين كلم)\n(حرة الوجه والشمائل والجوهر ... تكليمها لمن نال غنم)\n(هكذا وصف ما بدا لي منها ... ليس لي بالذي تغيب علم)\n(غير أني أرى الثياب ملاء ... في يفاع يزين ذلك جسم)\n(وحديث بمثله تنزل العصم ... رخيم يشوب ذلك حلم)\nروضه من الخفيف غنى ابن سريج في الأربعة الأبيات لحنا ذكره إسحاق وأبو أيوب المديني في جامع غنائه ولم يجنسه وذكر حبش أنه خفيف رمل بالبنصر","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":6,"spl":"سبعة ابن سريج","tags":["الوصف والطبيعة"],"loc":1709},
{"id":"b95-8","bab":"الجزء 9","sec":"إسحاق وإبراهيم بن المهدي ورأيهما في معبد وابن سريج","page":"ج9 ص283","text":"أخبرني عمي قال حدثني الحسين بن يحيى أبو الحمار قال حدثني عمرو بن بانة قال كنت حاضرا مع إسحاق بن إبراهيم الموصلي عند إبراهيم بن المهدي\nفتفاوضنا حديث المغنين حتى انتهوا إلى أن حكى إسحاق قول عمر بن أبي خليفة إذا تمعبد ابن سريج كان أحسن الناس غناء فقال إبراهيم لإسحاق حاشاك يا أبا محمد أن تقول هذا فقد رفع الله علمك وقدر ابن سريج عن مثل هذا القول وأغنى ابن سريج بنفسه عن أن يقال له تمعبد وماكان معبد يضع نفسه هذا الموضع وكيف ذلك وهو إذا أحسن يقول أصبحت اليوم سريجيا وما قد أنصف أبو إسحاق إبراهيم بن المهدي معبدا في هذا القول لأن معبدا وإن كان يعظم ابن سريج ويوفيه حقه فليس بدونه ولا هو بمرذول عنده وقد مضى في صدر الكتاب خبر ابن سريج لما قدم المدينة مع الغريض ليستمنحا أهلها فسمعاه وهو يصيد الطير يغني لحنه\n(القصر فالنخل فالجماء بينهما ... )\nرجع ابن سريج ورد الغريض وقال لا خير لنا عند قوم هذا غناء غلام فيهم يصيد الطير فكيف بمن داخل الجونة وأظرف من ذلك من أخباره وأدل على تعظيم ابن سريج معبدا ما أخبرني به أحمد بن عبد العزيز الجوهري قال حدثني علي بن سليمان النوفلي قال حدثني أبي قال التقى ابن سريج ومعبد ليلة بعد افتراق طويل وبعد عهد فتساءلا عما صنعا من الأغاني بعد افتراقهما فتغنى هذا وتغنى هذا ثم تغنى ابن سريج لحنه في\n(أنا الهالك المسلوب مهجة نفسه ... إذا جاوزت مرا وعسفان عيرها)\nفغناه مرسلا لا صيحة فيه فقال له معبد أفلا حسنته بصيحة قال فأين أضعها قال في\n(غدت سافرا والشمس قد ذر قرنها ... )\nقال فصح أنت فيه حتى أسمع منك قال فصاح فيه معبد الصيحة التي يغنى بها فيه اليوم فاستعاده ابن سريج حتى أخذه فغنى صوته كما رسمه معبد فحسن به جدا وفي هذا دليل يبين فيه التحامل على معبد في الحكاية\n(غدت سافرا والشمس قد ذر قرنها ... فأغشى شعاع الشمس منها سفورها)\n(وقد علمت شمس النهار بأنها ... إذا ما بدت يوما سيذهب نورها)\n(أنا الهالك المسلوب مهجة نفسه ... إذا جاوزت مرا وعسفان عيرها)\n(أهاجتك سلمى إذ أجد بكورها ... وهجر يوما للرواح بعيرها)\nلشعر يقال إنه لطريف العنبري والغناء لابن سريج خفيف ثقيل أول بالوسطى في مجراها عن ابن المكي وذكر عمرو أنه لسياط ولإبراهيم في الثالث والأول والرابع خفيف رمل مطلق في مجرى الوسطى عن إسحاق وعمرو وفيه لبسباسة ثقيل أول بالبنصر عن حبش وفيه لابن جامع لحن عن حبش من رواية أبي أيوب المديني ومن سبعة ابن سريج\n(قرب جيراننا جمالهم ... ليلا فأضحوا معا قد ارتفعوا)\n(ما كنت أدري بوشك بينهم ... حتى رأيت الحداة قد طلعوا)\n(على مصكين من جمالهم ... وعنتريسين فيهما شجع)\n(يا نفس صبرا فإنه سفه ... بالحر أن يستفزه الجزع)\nلشعر لعمر بن أبي ربيعة والغناء لابن سريج ثقيل أول بالوسطى عن عمرو وذكر حبش أن فيه للغريض ثقيلا أول بالبنصر وذكر ابن أبي حسان أن هبة الله بن إبراهيم بن المهدي حدثه عن أبيه عن ابن جامع قال عيب على ابن سريج خفة غنائه فأخذ أبيات عمر بن أبي ربيعة\n(قرب جيراننا جمالهم ... )\nفغنى فيها في كل إيقاع لحنا فجميع ما فيها من الألحان له وأخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني منصور بن أبي مزاحم قال حدثني رزام أبو قيس مولى خالد بن عبد الله قال قال لي إسماعيل بن عبد الله يا أبا قيس أي رجل أنت لولا أنك تحب السماع قلت أصلحك الله أما والله لو سمعت فلانة تغنيك\n(قرب جيراننا جمالهم ... ليلا فأضحوا معا قد ارتفعوا)\nعذرتني فقال يا أبا قيس لا عاتبتك بعد هذا أبدا ومنها\n(بينا كذلك إذا عجاجة موكب ... رفعوا ذميل العيس في الصحراء)\n(قالت أبو الخطاب أعرف زيه ... ولباسه لا شك غير خفاء)\nلشعر لابن أبي ربيعة والغناء لابن سريج ثقيل أول بالبنصر وذكر الهشامي وأبو العبيس أنه لمعبد وليس الأمر كما ذكرا ومنها صوت وهو الذي أوله\n(إن جاء فليأت على بغلة ... )\n(سلمى عديه سرحتي مالك ... أو الربا دونهما منزلا)\n(إن جاء فليأت على بغله ... إني أخاف المهر أن يصهلا)\nلشعر لعمر بن أبي ربيعة والغناء لابن سريج من رواية يحيى بن المكي والهشامي ثقيل أول بالبنصر وذكر يونس أنه للغريض وذكر إسحاق في أغاني الغريض ولم يجنسه","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":7,"spl":"إسحاق وإبراهيم بن المهدي ورأيهما في معبد وابن سريج","tags":[],"song":3,"loc":1710,"partialRef":{"sid":"b3-12","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b95-9","bab":"الجزء 9","sec":"أغاني الخلفاء وأولادهم وأولاد أولادهم","page":"ج9 ص288","text":"قال مؤلف هذا الكتاب المنسوب إلى الخلفاء من الأغاني والملصق بهم منها لا أصل لجله ولا حقيقة لأكثره لا سيما ما حكاه ابن خرداذبة فإنه بدأ بعمر بن الخطاب رضي الله عنه فذكر أنه تغنى في هذا البيت\n(كأن راكبها غصن بمروحة ... )\nم والى بين جماعة من الخلفاء واحدا بعد واحد حتى كأن ذلك عنده ميراث من مواريث الخلافة أو ركن من أركان الإمامة لا بد منه ولا معدل عنه يخبط خبط العشواء ويجمع جمع حاطب الليل فأما عمر بن الخطاب فلو جاز هذا أن يروى عن كل أحد لبعد عنه وإنما روي أنه تمثل بهذا البيت وقد ركب ناقة فاستوطأها لا أنه غنى به ولا كان الغناء العربي أيضا عرف في زمانه إلا ما كانت العرب تستعمله من النصب والحداء وذلك جار مجرى الإنشاد إلا أنه يقع بتطريب وترجيع يسير ورفع للصوت والذي صح من ذلك عن رواة هذا الشأن فأنا ذاكر منه ما كان متقن الصنعة لاحقا بجيد الغناء قريبا من صنعة الأوائل وسالكا مذاهبهم لا ما كان ضعيفا سخيفا وجامع منه ما\nاتصل به خبر له يستحسن ويجري مجرى هذا الكتاب وما تضمنه فأول من دونت له صنعة منه عمر بن عبد العزيز فإنه ذكر عنه أنه صنع في أيام إمارته على الحجاز سبعة ألحان يذكر سعاد فيها كلها فبعضها عرفت الشاعر القائل له فذكرت خبره وبعضها لم أعرف قائله فأتيت به كما وقع إلي فإن مر بي بعد وقتي هذا أثبته في موضعه وشرحت من أخباره ما اتصل بي وإن لم يقع لي ووقع إلى بعض من كتب هذا الكتاب فمن أقل الحقوق عليه أن يتكلف إثباته ولا يستثقل تجشم هذا القليل فقد وصل إلى فوائد جمة تجشمناها له ولنظرائه في هذا الكتاب فحظي بها من غير نصب ولا كدح فإن جمال ذلك موفر عليه إذا نسب إليه وعيبه عنا ساقط مع اعتذارنا عنه إن شاء الله ومن الناس من ينكر أن تكون لعمر بن عبد العزيز هذه الصنعة ويقول إنها أصوات محكمة العمل لا يقدر على مثلها إلا من طالت دربته بالصنعة وحذق الغناء ومهر فيه وتمكن منه ولم يوجد عمر بن عبد العزيز في وقت من الأوقات ولا حال من الحالات اشتهر بالغناء ولا عرف به ولا بمعاشرة أهله ولا جالس من ينقل ذلك عنه ويؤديه وإنما هو شيء يحسن المغنون نسبته إليه وروي من غير وجه خلاف لذلك وإثبات لصنعته إياها وهو أصح القولين لأن الذين أنكروا ذلك لم يأتوا على إنكارهم بحجة أكثر من هذا الظن والدعوى ومخالفوهم قد أيدتهم أخبار رويت\nأخبرني محمد بن خلف وكيع والحسين بن يحيى عن حماد بن إسحاق قال حدثني أبي عن أبيه وعن إسماعيل بن جامع عن سياط عن يونس الكاتب عن شهدة أم عاتكة بنت شهدة عن كردم بن معبد عن أبيه\nأن عمر بن عبد العزيز طارحه لحنه في\n(ألما صاحبي نزر سعادا ... )\nنسخت هذا الخبر من كتاب محمد بن الحسين الكاتب قال حدثني أبو يعلى زرقان غلام أبي الهذيل وصاحب أحمد بن أبي داود قال حدثني محمد ابن يونس قال حدثني هاتف أراه قال أم ولد المعتصم قالت حدثتني علية ابنة المهدي قالت حدثتني عاتكة بنت شهدة عن أمها شهدة عن كردم قال طرح علي عمر بن عبد العزيز لحنه\n(علق القلب سعادا ... عادت القلب فعادا)\n(كلما عوتب فيها ... أو نهي عنها تمادى)\n(وهو مشغوف بسعدى ... قد عصى فيها وزادا)\nال كردم وكان عمر أحسن خلق الله صوتا وكان حسن القراءة للقرآن ونسخت من كتاب ابن الكرنبي بخطه حدثني أحمد بن الفتح الحجاجي في مجلس حماد بن إسحاق قال أخبرني أحمد بن الحسين قال رأيت عمر بن عبد العزيز في النوم وعليه عمامة ورأيت الشجة في وجهه تدل على أنها ضربة حافر فسمعته يقول قال عمر بن الخطاب لا تعلموا نساءكم الخلع قال حدثني محمد بن الحسين فأقبلت عليه في نومي\nفقلت له يا أمير المؤمنين صوت يزعم الناس أنك صنعته في شعر جرير\n(ألما صاحبي نزر سعادا ... لوشك فرقها وذرا البعادا)\n(لعمرك إن نفع سعاد عني ... لمصروف ونفعي عن سعادا)\n(إلى الفاروق ينتسب ابن ليلى ... ومروان الذي رفع العمادا)\nتبسم عمر ولم يرد علي شيئا نسبة هذين الصوتين\n(ألما صاحبي نزر سعادا ... لوشك فرقها وذرا البعاد)\n(لعمرك إن نفع سعاد عني ... لمصروف ونفعي عن سعادا)\n(إلى الفاروق ينتسب ابن ليلى ... ومروان الذي رفع العمادا)\nلشعر لجرير يمدح عمر بن عبد العزيز بن مروان والغناء لعمر بن عبد العزيز ثقيل أول مطلق في مجرى البنصر وفيه خفيف ثقيل ينسب إلى معبد\n(علق القلب سعادا ... عادت القلب فعادا)","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":8,"spl":"أغاني الخلفاء وأولادهم وأولاد أولادهم","tags":["المديح"],"song":2,"loc":1711,"partial":1},
{"id":"b95-10","bab":"الجزء 9","sec":"أغاني الخلفاء وأولادهم وأولاد أولادهم","page":"ج9 ص288","text":"(كلما عوتب فيها ... أو نهي عنها تمادى)\n(وهو مشغوف بسعدى ... قد عصى فيها وزادا)\nلغناء لعمر بن عبد العزيز خفيف ثقيل وفيه ثاني ثقيل ينسب إلى الهذلي","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":9,"spl":"أغاني الخلفاء وأولادهم وأولاد أولادهم — ذكر عمر بن عبد العزيز وشيء من أخباره","tags":[],"loc":1712},
{"id":"b95-11","bab":"الجزء 9","sec":"ذكر عمر بن عبد العزيز وشيء من أخباره","page":"ج9 ص292","text":"عمر بن عبد العزيز بن مروان بن الحكم بن أبي العاصي بن أمية بن عبد شمس بن عبد مناف ويكنى أبا حفص وأمه أم عاصم بنت عاصم بن عمر بن الخطاب رضي الله عنه وكان يقال له أشج قريش لأنه كان في جبهته أثر يقال إنه ضربة حافر فذكر يحيى بن سعيد الأموي عن أبيه أن عبد الملك بن مروان كان يؤثر عمر بن عبد العزيز ويرق عليه ويدنيه وإذا دخل عليه رفعه فوق ولده جميعا إلا الوليد فعاتبه بعض بنيه على ذلك فقال له أو ما تعلم لم فعلت ذلك\nقال لا قال إن هذا سيلي الخلافة يوما وهو أشج بني مروان الذي يملأ الأرض عدلا بعد أن تملأ جورا فمالي لا أحبه وأدنيه أخبرني محمد بن يزيد\nقال حدثنا الرياشي قال حدثنا سالم بن عجلان قال خرج عمر بن عبد العزيز يلعب فرمحته بغلة على جبينه فبلغ الخبر أمه أم عاصم فخرجت في خدمها واقبل عبد العزيز بن مروان إليها فقالت أما الكبير فيخدم وأما الصغير فيكرم وأما الوسط فيضيع لم لا تتخذ لابني حاضنا حتى أصابه ما ترى فجعل عبد العزيز بمسح الدم عن وجهه ثم نظر إليها وقال لها ويحك إن كان أشج بني مروان أو أشج بني أمية إنه لسعيد\nأخبرني الحسن بن علي قال حدثني محمد بن أحمد المقدمي قال حدثنا عبيد الله بن سعد الزهري قال حدثنا هارون بن معروف قال حدثنا ضمرة قال سمعت ثروان مولى عمر بن عبد العزيز\nقال دخل عمر بن عبد العزيز وهو غلام إصطبل أبيه فضربه فرس على وجهه فأتي به أبوه يحمل فجعل أبوه يمسح الدم عن وجهه ويقول لئن كنت أشج بني أمية إنك لسعيد\nحدثنا محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثنا مصعب الزبيري قال كانت بنت لعبيد الله بن عمر بن الخطاب تحت إبراهيم بن نعيم النحام فماتت فأخذ عاصم بن عمر بيده فأدخله منزله وأخرج إليه ابنتيه حفصة وأم عاصم فقال له اختر فاختار حفصة فزوجها إياه فقيل له تركت أم عاصم وهي أجملهما فقال رأيت جارية رائعة وبلغني أن آل مروان ذكروها فقلت علهم أن يصيبوا من دنياهم فتزوجها عبد العزيز بن مروان فولدت له أبا بكر وعمر وكانت عنده وقتل إبراهيم بن نعيم يوم الحرة وماتت أم عاصم عند عبد العزيز بن مروان فتزوج أختها حفصة بعدها\nفحملت إليه بمصر فمرت بأيلة وبها مخنث أو معتوه وقد كان أهدى لأم عاصم حين مرت به فأثابته فلما مرت به حفصة أهدى لها فلم تثبه فقال ليست حفصة من رجال أم عاصم فذهبت مثلا\nأخبرني أحمد بن عبيد الله بن عمار قال حدثنا أبو بكر الرمادي وسليمان ابن أبي شيخ قالا حدثنا أبو صالح كاتب الليث قال حدثني الليث قال لما ولي عمر بن عبد العزيز بدأ بلحمته وأهل بيته فأخذ ما كان في أيديهم وسمى أعمالهم المظالم ففزعت بنو أمية إلى فاطمة بنت مروان عمته فأرسلت إليه إنه قد عناني أمر لا بد من لقائك فيه فأتته ليلا فأنزلها عن دابتها فلما أخذت مجلسها\nقال يا عمة أنت أولى بالكلام لأن الحاجة لك فتكلمي قالت تكلم يا أمير المؤمنين فقال إن الله تبارك وتعالى بعث محمدا رحمة لم يبعثه عذابا إلى الناس كافة ثم اختار له ما عنده فقبضه إليه وترك لهم نهرا شربهم فيه سواء ثم قام أبو بكر فترك النهر على حاله ثم ولي عمر فعمل على عمل صاحبه فلما ولي عثمان اشتق من ذلك النهر نهرا ثم ولي معاوية فشق منه الأنهار ثم لم يزل ذلك النهر يشق منه يزيد ومروان وعبد الملك والوليد وسليمان حتى أفضى الأمر إلي وقد يبس النهر الأعظم ولن يروى أصحاب النهر حتى يعود اليهم النهر الأعظم إلى ما كان عليه فقالت له قد أردت كلامك ومذاكرتك فأما إذ كانت هذه مقالتك فلست بذاكرة لك شيئا أبدا ورجعت اليهم فأبلغتهم كلامه وقال سليمان بن أبي شيخ في خبره فلما رجعت إلى بني أمية قالت لهم ذوقوا مغبة أمركم في تزويجكم آل عمر بن الخطاب","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":9,"spl":"أغاني الخلفاء وأولادهم وأولاد أولادهم — ذكر عمر بن عبد العزيز وشيء من أخباره","tags":["الجواري والنساء"],"loc":1713},
{"id":"b95-12","bab":"الجزء 9","sec":"كثير والأحوص ونصيب عند عمر بن عبد العزيز","page":"ج9 ص295","text":"أخبرني محمد بن خلف وكيع قال أخبرني عبد الله بن دينار مولى بني نصر ابن معاوية قال حدثنا محمد بن عبد الرحمن التيمي قال حدثنا محمد بن عبد الرحمن بن سهيل عن حماد الراوية\nوأخبرني محمد بن حسين الكندي خطيب القادسية قال حدثنا الرياشي قال حدثنا شيبان بن مالك قال حدثنا عبد الله بن إسماعيل الجحدري عن حماد الراوية والروايتان متقاربتان وأكثر اللفظ للرياشي\nقال دخلت المدينة ألتمس العلم فكان أول من لقيت كثير عزة فقلت يا أبا صخر ما عندك من بضاعتي قال عندي ما عند الأحوص ونصيب قلت وما هو قال هما أحق بإخبارك فقلت له إنا لم نحث المطي نحوكم شهرا نطلب ما عندكم إلا ليبقى لكم\nذكر وقل من يفعل ذلك فأخبرني عما سألتك ليكون ما تخبرني به حديثا آخذه عنك فقال إنه لما كان من أمر عمر بن عبد العزيز ما كان قدمت أنا ونصيب والأحوص وكل واحد منا يدل بسابقته عند عبد العزيز وإخائه لعمر فكان أول من لقينا مسلمة بن عبد الملك وهو يومئذ فتى العرب وكل واحد منا ينظر في عطفيه لا يشك أنه شريك الخليفة في الخلافة فأحسن ضيافتنا وأكرم مثوانا ثم\nقال أما علمتم أن إمامكم لا يعطي الشعراء شيئا قلنا قد جئنا الآن فوجه لنا في هذا الأمر وجها فقال إن كان ذو دين من آل مروان قد ولي الخلافة فقد بقي من ذوي دنياهم من يقضي حوائجكم ويفعل بكم ما أنتم له أهل فأقمنا على بابه أربعة أشهر لا نصل إليه وجعل مسلمة يستأذن لنا فلا يؤذن فقلت لو أتيت المسجد يوم الجمعة فتحفظت من كلام عمر شيئا فأتيت المسجد فأنا أول من حفظ كلامه\nسمعته يقول في خطبة له لكل سفر زاد لا محالة فتزودوا من الدنيا إلى الآخرة التقوى وكونوا كمن عاين ما أعد الله له من ثوابه وعقابه فعمل طلبا لهذا وخوفا من هذا ولا يطولن عليكم الأمد فتقسوا قلوبكم وتنقادوا لعدوكم واعلموا أنه إنما يطمئن بالدنيا من وثق بالنجاة من عذاب الله في الآخرة فأما من لا يداوي جرحا إلا أصابه جرح من ناحية أخرى فكيف يطمئن بالدنيا أعوذ بالله أن آمركم بما أنهى نفسي عنه فتخسر صفقتي وتبدو عيلتي وتظهر مسكنتي يوم لا ينفع فيه إلا الحق والصدق فارتج المسجد بالبكاء وبكى عمر حتى بل ثوبه حتى ظننا أنه قاض نحبه فبلغت إلى صاحبي فقلت جددا لعمر من الشعر غير ما أعددناه فليس الرجل بدنيوي ثم إن مسلمة استأذن لنا يوم جمعة بعدما أذن للعامة فدخلنا فسلمنا عليه بالخلافة فرد علينا فقلت له يا أمير المؤمنين طال الثواء وقلت الفائدة وتحدثت بجفائك إيانا وفود العرب فقال يا كثير أما سمعت إلى قول الله عز و جل في كتابه ( إنما الصدقات للفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل فريضة من الله والله عليم حكيم\nأفمن هؤلاء أنت فقلت له وأنا ضاحك أنا ابن سبيل ومنقطع به قال أو لست ضيف أبي سعيد قلت بلى قال ما أحسب من كان ضيف أبي سعيد ابن سبيل ولا منقطعا به ثم استأذنه في الإنشاد فقال قل ولا تقل إلا حقا فإن الله سائلك فقلت\n(وليت فلم تشتم عليا ولم تخف ... بريا ولم تتبع مقالة مجرم)\n(وقلت فصدقت الذي قلت بالذي ... فعلت فأضحى راضيا كل مسلم)\n(ألا إنما يكفي الفتى بعد زيغه ... من الأود الباقي ثقاف المقوم)\n(لقد لبست لبس الهلوك ثيابها ... وأبدت لك الدنيا بكف ومعصم)\n(وتومض أحيانا بعين مريضة ... وتبسم عن مثل الجمان المنظم)\n(فأعرضت عنها مشمئزا كأنما ... سقتك مدوفا من سمام وعلقم)\n(وقد كنت من أجبالها في ممنع ... ومن بحرها في مزبد الموج مفعم)\n(وما زلت سباقا إلى كل غاية ... صعدت بها أعلى البناء المقدم)\n(فلما أتاك الملك عفوا ولم يكن ... لطالب دنيا بعده من تكلم)\n(تركت الذي يفني وإن كان مونقا ... وآثرت ما يبقى برأي مصمم)\n(فأضررت بالفاني وشمرت للذي ... أمامك في يوم من الهول مظلم)\n(ومالك أن كنت الخليفة مانع ... سوى الله من مال رغيب ولا دم)\n(سما لك هم في الفؤاد مؤرق ... صعدت به أعلى المعالي بسلم)\n(فما بين شرق الأرض والغرب كلها ... مناد ينادي من فصيح وأعجم)\n(يقول أمير المؤمنين ظلمتني ... بأخذ لدينار ولا أخذ درهم)\n(ولا بسط كف لامرئ ظالم له ... ولا السفك منه ظالما ملء محجم)\n(فلو يستطيع المسلمون تقسموا ... لك الشطر من أعمارهم غير ندم)\n(فعشت به ما حج لله راكب ... مغذ مطيف بالمقام وزمزم)","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":10,"spl":"كثير والأحوص ونصيب عند عمر بن عبد العزيز","tags":[],"loc":1714},
{"id":"b95-13","bab":"الجزء 9","sec":"كثير والأحوص ونصيب عند عمر بن عبد العزيز","page":"ج9 ص295","text":"(فأربح بها من صفقة لمبايع ... وأعظم بها أعظم بها ثم أعظم)\nقال لي يا كثير إن الله سائلك عن كل ما قلت ثم تقدم إليه الأحوص فاستأذنه فقال قل ولا تقل إلا حقا فإن الله سائلك فأنشده\n(وما الشعر إلا خطبة من مؤلف ... بمنطق حق أو بمنطق باطل)\n(فلا تقبلن إلا الذي وافق الرضا ... ولا ترجعنا كالنساء الأرامل)\n(رأيناك لم تعدل عن الحق يمنة ... ولا يسرة فعل الظلوم المجادل)\n(ولكن اخذت القصد جهدك كله ... وتقفو مثال الصالحين الأوائل)\n(فقلنا ولم نكذب بما قد بدا لنا ... ومن ذا يرد الحق من قول عاذل)\n(ومن ذا يرد السهم بعد مروقه ... على فوقه إن عار من نزع نابل)\n(ولولا الذي قد عودتنا خلائف ... غطاريف كانت كالليوث البواسل)\n(لما وخدت شهرا برحلي جسرة ... تفل متون البيد بين الرواحل)\n(ولكن رجونا منك مثل الذي به ... صرفنا قديما من ذويك الأفاضل)\n(فإن لم يكن للشعر عندك موضع ... وإن كان مثل الدر من قول قائل)\n(وكان مصيبا صادقا لا يعيبه ... سوى أنه يبنى بناء المنازل)\n(فإن لنا قربى ومحض مودة ... وميراث آباء مشوا بالمناصل)\n(فذادوا عدو السلم عن عقر دارهم ... وأرسوا عمود الدين بعد تمايل)\n(فقبلك ما أعطى الهنيدة جلة ... على الشعر كعبا من سديس وبازل)\n(رسول الإله المصطفى بنبوة ... عليه سلام بالضحى والأصائل)\n(فكل الذي عددت يكفيك بعضه ... ونيلك خير من بحور السوائل)\nفقال له عمر يا أحوص إن الله سائلك عن كل ما قلت ثم تقدم إليه نصيب فاستأذن في الإنشاد فأبى أن يأذن له وغضب غضبا شديدا وأمره باللحاق بدابق وأمر لي وللأحوص لكل واحد بمائة وخمسين درهما وقال الرياشي في خبره فقال لنا ما عندي ما أعطيكم فانتظروا حتى يخرج عطائي فأواسيكم منه فانتظرناه حتى خرج فأمر لي وللأحوص بثلاثمائة\nدرهم وأمر لنصيب بمائة وخمسين درهما فما رأيت أعظم بركة من الثلاث المائة التي أعطاني ابتعت بها وصيفة فعلمتها الغناء فبعتها بألف دينار","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":11,"spl":"كثير والأحوص ونصيب عند عمر بن عبد العزيز — عمر ودكين الراجز","tags":["السفر والحج"],"loc":1715},
{"id":"b95-14","bab":"الجزء 9","sec":"عمر ودكين الراجز","page":"ج9 ص299","text":"أخبرني عمي عبد العزيز بن أحمد قال حدثنا أحمد بن الحارث الخراز عن المدائني قال قال دكين الراجز امتدحت عمر بن عبد العزيز وهو والي المدينة فأمر لي بخمس عشرة ناقة كرائم فكرهت أن أرمي بهن الفجاج ولم تطب نفسي ببيعهن فقدمت علينا رفقة من مصر فسألتهم الصحبة فقالوا ذاك إليك ونحن نخرج الليلة فأتيته فودعته وعنده شيخان لا أعرفهما فقال لي يا دكين إن لي نفسا تواقة فإن صرت إلى أكثر مما أنا فيه فأتني ولك الإحسان\nقلت أشهد لي بذلك قال أشهد الله به قلت ومن خلقه قال هذين الشيخين فأقبلت على أحدهما فقلت من أنت أعرفك قال سالم بن عبد الله بن عمر فقلت له لقد استسمنت الشاهد وقلت للآخر من أنت\nقال أبو يحيى مولى الأمير فخرجت إلى بلدي بهن فرمى الله في أذنابهن بالبركة حتى اعتقدت منهن الإبل والعبيد فإني لبصحراء فلج إذا ناع ينعى سليمان\nقلت فمن القائم بعده قال عمر بن عبد العزيز فتوجهت نحوه فلقيني جرير منصرفا من عنده فقلت يا أبا حزرة من أين فقال من عند من يعطي الفقراء ويمنع الشعراء فانطلقت فإذا هو في عرصة دار وقد أحاط الناس به فلم أخلص اليه فناديت\n(يا عمر الخيرات والمكارم ... وعمر الدسائع العظائم)\n(إني امرؤ من قطن بن دارم ... طلبت ديني من أخي مكارم)\n(إذ تنتحي والليل غير نائم ... عند أبي يحيى وعند سالم)\nقام أبو يحيى فقال يا أمير المؤمنين لهذا البدوي عندي شهادة عليك فقال أعرفها ادن يا دكين أنا كما ذكرت لك إن نفسي لم تنل شيئا قط إلا تاقت لما هو فوقه وقد نلت غاية الدنيا فنفسي تتوق إلى الآخرة والله ما رزأت من أموال الناس شيئا ولا عندي إلا ألف درهم فخذ نصفها قال فوالله ما رأيت ألفا كان أعظم بركة منه قال ودكين الذي يقول\n(إذا المرء لم يدنس من اللؤم عرضه ... فكل رداء يرتديه جميل)\n(وإن هو لم يرفع عن اللؤم نفسه ... فليس إلى حسن الثناء سبيل)","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":11,"spl":"كثير والأحوص ونصيب عند عمر بن عبد العزيز — عمر ودكين الراجز","tags":["المديح"],"loc":1716},
{"id":"b95-15","bab":"الجزء 9","sec":"زهده وحبه آل البيت","page":"ج9 ص300","text":"أخبرني الحرمي عن الزبير عن هارون بن صالح عن أبيه قال كنا نعطي الغسال الدراهم الكثيرة حتى يغسل ثيابنا في أثر ثياب عمر بن عبد العزيز من كثرة الطيب فيها يعني المسك قال ثم رأيت ثيابه بعد ذلك وقد ولي الخلافة فرأيت غير ما كنت أعرف أخبرني محمد بن العباس اليزيدي قال حدثنا الرياشي قال حدثنا الأصمعي عن نافع بن أبي نعيم قال قدم عبد الله بن الحسن على عمر بن عبد العزيز فقال إنك لا تغنم أهلك شيئا خيرا من نفسك فارجع وأتبعه حوائجه\nقال الرياشي وحدثنا نصر بن علي قال حدثنا أبو أحمد محمد بن الزبير الأسدي عن سعيد بن أبان قال رأيت عمر بن عبد العزيز آخذا بسرة عبد الله بن حسن\nوقال اذكرها عندك تشفع لي يوم القيامة حدثني أبو عبيد الصيرفي قال حدثنا الفضل بن الحسن المصري قال حدثنا عبد الله بن عمر القواريري قال\nحدثنا يحيى بن سعيد عن سعيد بن أبان القرشي قال دخل عبد الله بن حسن على عمر بن عبد العزيز وهو حديث السن وله وفرة فرفع مجلسه وأقبل عليه وقضى حوائجه ثم أخذ عكنة من عكنه فغمزها حتى أوجعه\nوقال له اذكرها عندك للشفاعة فلما خرج لامه أهله وقالوا فعلت هذا بغلام حديث السن فقال إن الثقة حدثني حتى كأني أسمعه من في رسول الله\nقال إنما فاطمة بضعة مني يسرني ما يسرها وأنا أعلم أن فاطمة لو كانت حية لسرها ما فعلت بابنها قالوا فما معنى غمزك بطنه وقولك ما قلت قال إنه ليس أحد من بني هاشم إلا وله شفاعة فرجوت أن أكون في شفاعة هذا أخبرنا محمد بن العباس اليزيدي قال حدثنا عمر بن شبة قال حدثنا عيسى ابن عبد الله بن محمد بن عمر بن علي قال أخبرني يزيد بن عيسى بن مورق قال كنت بالشام زمن ولي عمر بن عبد العزيز وكان بخناصرة وكان\nيعطي الغرباء مائتي درهم قال فجئته فأجده متكئا على إزار وكساء من صوف فقال لي ممن أنت قلت من أهل الحجاز قال من أيهم قلت من أهل المدينة\nقال من أيهم قلت من قريش قال من أي قريش قلت من بني هاشم قال من أي بني هاشم قلت مولى علي قال من علي فسكت قال من فقلت ابن أبي طالب فجلس وطرح الكساء ثم وضع يده على صدره\nوقال وأنا والله مولى علي ثم قال أشهد على عدد ممن أدرك النبي يقول قال رسول الله من كنت مولاه فعلي مولاه أين مزاحم كم تعطي مثله قال مائتي درهم\nقال أعطه خمسين دينارا لولائه من علي ثم قال أفي فرض أنت قلت لا قال وافرض له ثم قال الحق بلادك فإنه سيأتيك إن شاء الله ما يأتي غيرك\nقال أبو زيد فحدثني عيسى بن عبد الله قال حدثني أبي عن أبيه قال قال أبي ولد لي غلام يوم قام عمر بن عبد العزيز فغدوت عليه فقلت له ولد لي في هذه الليلة غلام فقال لي ممن قلت من التغلبية قال فهب لي اسمه قلت نعم قال قد سميته اسمي ونحلته غلامي مورقا وكان نوبيا فأعتقه عمر بن العزيز بعد ذلك فولده اليوم موالينا أخبرني محمد بن العباس قال حدثنا عمر قال حدثنا عيسى بن عبد الله قال أخبرني موسى بن عبد الله بن حسن عن أبيه قال كان عمر بن عبد العزيز يراني إذا كانت لي حاجة أتردد إلى بابه فقال\nلي ألم أقل لك إذا كانت لك حاجة فارفع بها إلي فوالله إني لأستحيي من الله أن يراك على بابي أخبرني عمي قال حدثني الكراني قال حدثني العمري عن العتبي عن أبيه\nقال لما حضرت عمر بن عبد العزيز الوفاة جمع ولده حوله فلما رآهم استعبر ثم قال بأبي وأمي من خلفتهم بعدي فقراء فقال له مسلمة بن عبد الملك يا أمير المؤمنين فتعقب فعلك وأغنهم فما يمنعك أحد في حياتك ولا يرتجعه الوالي بعدك فنظر إليه نظر مغضب متعجب فقال يا مسلمة منعتهم إياه في حياتي وأشقى به بعد وفاتي إن ولدي بين رجلين إما مطيع لله فالله مصلح له شأنه ورازقه ما يكفيه أو عاص له فما كنت لأعينه على معصيته يا مسلمة إني حضرت أباك لما دفن فحملتني عيني عند قبره فرأيته قد أفضى إلى أمر من أمر الله راعني وهالني فعاهدت الله ألا أعمل بمثل عمله إن وليت وقد اجتهدت في ذلك طول حياتي وأرجو أن أفضي إلى عفو من الله وغفران\nقال مسلمة فلما دفن حضرت دفنه فلما فرغ من شأنه حتى حملتني عيني فرأيته فيما يرى النائم وهو في روضة خضراء نضرة فيحاء وأنهار مطردة وعليه ثياب بيض فأقبل علي فقال يا مسلمة لمثل هذا فليعمل العاملون هذا أو نحوه فإن الحكاية تزيد أو تنقص","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":12,"spl":"زهده وحبه آل البيت","tags":["اللهو والمزاح","السفر والحج"],"loc":1717},
{"id":"b95-16","bab":"الجزء 9","sec":"زهده وحبه آل البيت","page":"ج9 ص300","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم قال حدثنا عبد الله ابن أبي سعد قال حدثنا سليمان بن أبي شيخ عن يحيى بن سعيد الأموي قال لما مات عمر بن عبد العزيز وقف مسلمة عليه بعد أن أدرج في كفنه فقال رحمك الله يا أمير المؤمنين فقد أورثت صالحينا بك اقتداء وهدى\nوملأت قلوبنا بمواعظك وذكرك خشية وتقى وأثلت لنا بفضلك شرفا وفخرا وأبقيت لنا في الصالحين بعدك ذكرا","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":13,"spl":"زهده وحبه آل البيت — رده على كتاب الحسن البصري","tags":["الموت","الرواية والكتابة"],"loc":1718},
{"id":"b95-17","bab":"الجزء 9","sec":"كتابه إلى أساري قسطنطينية","page":"ج9 ص303","text":"أخبرني الحسن قال أخبرنا الغلابي عن ابن عائشة عن أبيه إن عمر بن عبد العزيز كتب إلى الأساري بقسطنطينية أما بعد فإنكم تعدون أنفسكم أسارى ولستم أسارى معاذ الله أنتم الحبساء في سبيل الله واعلموا أني لست أقسم شيئا بين رعيتي إلا خصصت أهلكم بأوفر ذلك وأطيبه وقد بعثت اليكم خمسة دنانير خمسة دنانير ولولا أني خشيت إن زدتكم أن يحبسه عنكم طاغية الروم لزدتكم وقد بعثت إليكم فلان بن فلان يفادي صغيركم وكبيركم ذكركم وأنثاكم حركم ومملوككم بما يسأل فأبشروا ثم أبشروا","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":13,"spl":"زهده وحبه آل البيت — رده على كتاب الحسن البصري","tags":["الحب والغزل","الرواية والكتابة"],"loc":1719},
{"id":"b95-18","bab":"الجزء 9","sec":"رده على كتاب الحسن البصري","page":"ج9 ص304","text":"أخبرني أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال حدثنا عبد الله بن مسلم قال زعم لنا سليمان بن أرقم قال كتب الحسن البصري إلى عمر بن عبد العزيز وكان يكاتبه فلما\nاستخلف كتب إليه من الحسن البصري إلى عمر بن عبد العزيز فقيل له إن الرجل قد ولي وتغير فقال لو علمت أن غير ذلك أحب إليه لاتبعت محبته ثم كتب من الحسن بن أبي الحسن إلى عمر بن عبد العزيز أما بعد فكأنك بالدنيا لم تكن وكأنك بالآخرة لم تزل\nقال فمضيت إليه بالكتاب فقدمت عليه به فإني عنده أتوقع الجواب إذ خرج يوما غير يوم جمعة حتى صعد المنبر واجتمع الناس فلما كثروا قام فحمد الله وأثنى عليه ثم\nقال أيها الناس إنكم في أسلاب الماضين وسيرثكم الباقون حتى تصيروا إلى خير الوارثين كل يوم تجهزون غاديا إلى الله ورائحا قد حضر أجله وطوي عمله وعاين الحساب وخلع الأسلاب وسكن التراب ثم تدعونه غير موسد ولا ممهد ثم وضع يديه على وجهه فبكى مليا ثم رفعهما فقال يا أيها الناس من وصل الينا منكم بحاجته لم نأله خيرا ومن عجز فوالله لوددت أنه وآل عمر في العجز سواء قال ثم نزل فأرسل إلي فدخلت إليه فكتب بسم الله الرحمن الرحيم أما بعد فإنك لست بأول من كتب عليه الموت وقد مات والسلام","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":13,"spl":"زهده وحبه آل البيت — رده على كتاب الحسن البصري","tags":["المديح","الموت","الرواية والكتابة"],"loc":1720},
{"id":"b95-20","bab":"الجزء 9","sec":"آخر خطبة له — شراؤه موضع قبره","page":"ج9 ص305 – ج9 ص306","text":"أخبرني ابن عمار قال حدثني سليمان بن أبي شيخ قال حدثنا أبو مطرف المغيرة بن مطرف عن شعيب بن صفوان عن أبيه أن عمر بن عبد العزيز خطب بخناصرة خطبة لم يخطب بعدها حمد الله وأثنى عليه ثم قال أيها الناس إنكم لم تخلقوا عبثا ولم تتركوا سدى وإن لكم معادا يتولى الله فيه الحكم فيكم والفصل بينكم فخاب وخسر من خرج من رحمة الله التي وسعت كل شيء وحرم الجنة التي عرضها السماوات والأرض\nواعلموا أن الأمان غدا لمن حذر الله وخافه وباع قليلا بكثير ونافدا بباق وخوفا بأمان ألا ترون أنكم في أسلاب الهالكين وسيخلفها من بعدكم الباقون وكذلك حتى تردوا إلى خير الوارثين ثم إنكم في كل يوم وليلة تشيعون غاديا إلى الله ورائحا قد قضى نحبه وانقضى أجله ثم تضعونه في صدع من الأرض في بطن لحد ثم تدعونه غير موسد ولا ممهد قد خلع الأسلاب وفارق الأحباب ووجه للحساب غنيا عما ترك فقيرا إلى ما قدم وايم الله إني لأقول لكم هذه المقالة ولا أعلم عند أحد منكم أكثر مما عندي وأستغفر الله لي ولكم وما يبلغنا أحد منكم حاجته يسعها ما عندنا إلا سددنا من حاجته ما قدرنا عليه ولا أحد يتسع له ما عندنا إلا وددت أنه بدئ بي وبلحمتي الذي يلونني حتى يستوي عيشنا وعيشكم وايم الله لو أردت غير هذا من عيش أو غضارة لكان اللسان به مني ناطقا ذلولا عالما بأسبابه ولكنه من الله عز و جل كتاب ناطق وسنة عادلة دل فيهما على طاعته ونهى فيهما عن معصيته ثم بكى فتلقى دموعه بطرف ردائه ثم نزل فلم ير على تلك الأعواد بعد حتى قبضه الله إليه رحمة الله عليه\nأخبرنا محمد بن العباس اليزيدي قال حدثنا عمر بن شبة قال حدثني أبو سلمة المديني عن إبراهيم بن ميسرة أن عمر بن عبد العزيز اشترى موضع قبره بعشرة دنانير\nأخبرني اليزيدي قال حدثنا عمر بن شبة قال حدثني أبو سلمة المديني قال أخبرني ابن مسلمة بن عبد الملك قال حدثني أبي مسلمة قال كنا عند عمر في اليوم الذي توفي فيه أنا وفاطمة بنت عبد الملك فقلنا له يا أمير المؤمنين إنا نرى أنا قد منعناك النوم فلو تأخرنا عنك شيئا عسى أن تنام قال ما أبالي لو فعلتما قال فتنحيت أنا وهي وبيننا وبينه ستر قال فما\nنشبنا أن سمعناه يقول حي الوجوه حي الوجوه فابتدرناه أنا وهي فجئناه وقد أغمض ميتا فإذا هاتف يهتف في البيت لا نراه ( تلك الدار الآخرة نجعلها للذين لا يريدون علوا في الأرض ولا فسادا والعاقبة للمتقين\nمن أصوات عمر في سعاد\n(ألا يا دين قلبك من سليمى ... كما قد دين قلبك من سعادا)\n(هما سبتا الفؤاد وأصبتاه ... ولم يدرك بذلك ما أراد)\n(قفا نعرف منازل من سليمى ... دوارس بين حومل أو عرادا)\n(ذكرت بها الشباب وآل ليلى ... فلم يرد الشباب بها مرادا)\n(فإن تشب الذؤابة أم زيد ... فقد لاقيت أياما شدادا)\nروضه من الوافر الشعر لأشهب بن رميلة فيما ذكر ابن الأعرابي وأبو عمرو الشيباني وحكى ابن الأعرابي أنه سمع بعض بني ضبة يذكر أنها لابن ابي رميلة الضبي والغناء لعمر بن عبد العزيز رمل بالوسطى عن الهشامي وحبش وغيرهما وفي نسخة عمرو بن بانة الثانية لخزرج رمل بالبنصر","topic":"ذكر الحارث بن خالد ونسبه وخبره في هذا الشعر","topicNo":95,"sp":14,"spl":"آخر خطبة له — شراؤه موضع قبره","tags":["المديح"],"song":1,"loc":1721},
{"id":"b96-1","bab":"الجزء 9","sec":"نسب الأشهب بن رميلة وأخباره","page":"ج9 ص308","text":"رملية أمه وهي أمة لخالد بن مالك بن ربعي بن سلمى بن جندل بن نهشل بن دارم بن عمرو بن تميم وهو الأشهب بن ثور بن أبي حارثة بن عبد الدار بن جندل بن نشهل بن دارم في النسب\nقال أبو عمرو وولدها يزعمون أنها كانت سبية من سبايا العرب فولدت لثور بن أبي حارثة أربعة نفر وهم رباب وحجناء والأشهب وسويد فكانوا من أشد إخوة في العرب لسانا ويدا وأمنعهم جانبا وكثرت أموالهم في الإسلام وكان أبوهم ثور ابتاع رميلة في الجاهلية وولدتهم في الجاهلية فعزوا عزا عظيما حتى كانوا إذا وردوا ماء من مياه الصمان حظروا على الناس ما يريدون منه وكانت لرميلة قطيفة حمراء فكانوا يأخذون الهدب من تلك القطيفة فيلقونه على الماء أي قد سبقنا إلى هذا فلا يرده أحد لعزهم فيأخذون من الماء ما يحتاجون إليه ويدعون ما يستغنون عنه فوردوا في بعض السنين ماء من مياه الصمان وورد معهم ناس من بني قطن بن نهشل وكانت بنو قطن بن نهشل وبنو زيد بن نهشل وبنو مناف بن درام حلفاء وكانت الأعجاز حلفاء عليهم وهم جندل وجرول وصخر بنو نهشل فأورد بعضهم بعيره فأشرعه حوضا قد حظروا عليه وبلغهم ذلك فغضبوا منه واجتمعوا وأحلافهم واجتمعت الأحلاف عليهم فاقتتلوا قتالا شديدا فضرب رباب بن رميلة رأس نسير بن صبيح المعروف بأبي بدال وأمه بنت أبي الحمام بن قراد بن مخزوم وقال رباب في ذلك\n(ضربته عشية الهلال ... أول يوم عد من شوال)\n(ضربا على رأس أبي بدال ... ثمت ما أبت ولا أبالي)\n(ألا يؤوب آخر الليالي ... )\nجمع كل واحد منهما لصاحبه فقالت بنو قطن يا بني جرول ويا بني صخر ويا بني مناف ضرب صاحبكم صاحبنا ضربة لا ندري أيموت منها أم يعيش فأنصفونا فأبى القوم أن يفعلوا فاقتتلوا يومهم ذلك إلى الليل وكان أبي بن أشيم أخو بني جرول وهو سيدهم خرج في حاجة له فلقيه بعض بني قطن فأسره وأتى به أ صحابه فقال نهشل بن حري يا بني قطن أطيعوني اليوم واعصوني أبدا قالوا نعم فقل فقال إن هذا لم يشهد شركم ولا حربكم ولا يحل لكم دمه وإن قومه أحر من يقاتلكم وشوكتهم فخذوا عليه العهد أن يصرفهم عنكم وخلوا سبيله قالوا افعل ما رأيت فأتاه نهشل بن حري فقال له يا أبا أسماء إن قومك قد حالوا بيننا وبين حقنا وقاتلوا دونه وقد أمكننا الله منك وأنت والله أوفى دما عندنا من بني رميلة فوالله لأقتلنك أو تعطيني ما أسألك\nقال سل قال تجعل أن تصرف بني جرول جميعا فإن لم يطيعوك انصرفت ببني أشيم فإن لم يطيعوك أتيتنا قال نعم فخلي سبيله تحت الليل فأتاهم وهم بحيث يرى بعضهم بعضا فقال يا بني جرول انصرفوا أتعترضون على قوم يريدون حقهم ألا تتقون الله والله لقد أسرني القوم ولو أرادوا قتلى لكان فيه وفاء بحقهم ولكنهم يكرهون حربكم فلا تبغوا\nعليهم فانصرف منهم أكثر من سبعين رجلا فلما رأى ذلك بنو صخر وبنو جرول قالوا والله إنا لنظلم قومنا إن قاتلناهم وانصرفوا وتخاذل القوم فلما رأى ذلك الأشهب بن رميلة\nقال ويلكم أفي ضربة من عصا لم تصنع شيئا تسفكون دماءكم والله ما به من بأس فأعطوا قومكم حقهم فقال حجناء ورباب والله لننصرفن فلنلحقن بغيركم ولا نعطي ما بأيدينا فجعل الأشهب ابن رميلة يقول ويلكم أتخربون دار قومكم في ضربة عصا لم تبلغ شيئا فلم يزل بهم حتى جاؤوا برباب فدفعوه إلى بني قطن وأخذوا منهم أبا بدال وهو المضروب فمات في تلك الليلة في أيديهم فكتموه وأرسلوا إلى عباد بن مسعود ومالك بن ربعي ومالك بن عوف والقعقاع بن معبد فعرضوا عليهم الدية فقالوا وما الدية وصاحبنا حي قالوا فإن صاحبكم ليس بحي فأمسكوا وقالوا ننظر ثم جاؤوا إلى رباب فقالوا أوصنا بما بدا لك\nقال دعوني أصلي قالوا صل فصلى ركعتين ثم قال أما والله إني إلى ربي لذو حاجة وما منعني أن أزيد في صلاتي إلا أن تروا أن ذلك فرق من الموت فليضربني منكم رجل شديد الساعد حديد السيف فدفعوه إلى أبي خزيمة بن نسير المكني بأبي بدال فضرب عنقه فدفنوه وذلك في الفتنة بعد مقتل عثمان بن عفان فقال الأشهب يرثي أخاه ويلوم نفسه في دفعه إليهم لتسكن الحرب\n(أعيني قلت عبرة من أخيكما ... بأن تسهرا ليل التمام وتجزعا)\n(وباكية تبكي الرباب وقائل ... جزى الله خيرا ما أعف وأمنعا)\n(وأضرب في الهيجا إذا حمس الوغى ... وأطعم إذ أمسى المراضيع جوعا)\n(إذا ما اعترضنا من أخينا أخاهم ... روينا ولم نشف الغليل فينقعا)","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":0,"spl":"نسب الأشهب بن رميلة وأخباره","tags":["الجواري والنساء","الوصف والطبيعة"],"loc":1722,"partial":1},
{"id":"b96-2","bab":"الجزء 9","sec":"نسب الأشهب بن رميلة وأخباره","page":"ج9 ص308","text":"(قرونا دما والضيف منتظر القرى ... ودعوة داع قد دعانا فأسمعا)\n(مردنا وكانت هفوة من حلومنا ... بثدي إلى أولاد ضمرة أقطعا)\n(وقد لامني قومي ونفسي تلومني ... بما فال رأيي في رباب وضيعا)\n(فلو كان قلبي من حديد أذابه ... ولو كان من صم الصفا لتصدعا)\nضى الحديث","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":1,"spl":"نسب الأشهب بن رميلة وأخباره","tags":[],"loc":1723},
{"id":"b96-3","bab":"الجزء 9","sec":"اصوات عمر في سعاد","page":"ج9 ص311","text":"ونسخت من كتاب محمد بن الحسن الكاتب حدثني محمد بن أحمد بن يحيى المكي عن أبيه قال لعمر بن عبد العزيز في سعاد سبعة ألحان منها\n(يا سعاد التي سبتني فؤادي ... ورقادي هبي لعيني رقادي)\nلحنه رمل مطلق ومنها\n(حظ عيني من سعاد ... أبدا طول السهاد)\nلحنه رمل بالسبابة في مجرى البنصر ومنها\n(سبحان ربي برا سعادا ... لا تعرف الوصل والودادا)\nلحنه خفيف رمل\nومنها\n(لعمري لئن كانت سعاد هي المنى ... وجنة خلد لا يمل خلودها)\nولحنه ثقيل أول ومنها\n(أسعاد جودي لا شقيت سعادا ... واجزي محبك رأفة وودادا)\nلحنه خفيف رمل ومنها\n(ألما صاحبي نزر سعادا ... )\nمنها\n(ألا يا دين قلبك من سليمى ... )\nقد ذكرت طريقتهما وقد روي عن عمر بن عبد العزيز حديث كثير وفقه وحمل عنه أهل العلم أخبرنا محمد بن جرير الطبري قال حدثنا عمران بن بكار الكلاعي\nقال حدثنا خالد بن علي قال حدثنا بقية بن الوليد عن مبشر بن إسماعيل عن بشر ابن عمر بن عبد العزيز عن أبيه عمر عن جده عبد العزيز عن معاوية بن أبي سفيان\nقال قال رسول الله من أحب أن تمثل له الرجال قياما فليتبوأ مقعده من النار أخبرني محمد بن عمران الصيرفي وعمي قالا حدثنا العنزي قال حدثني وزير بن محمد أبو هاشم الغساني قال حدثني محمد بن أيوب بن سعيد\nالسكري عن عمر بن عبد العزيز عن أمه عن أبيها عاصم بن عمر عن أبيه عمر ابن الخطاب قال قال رسول الله نعم الإدام الخل وممن حكي عنه أنه صنع في شعره غناء يزيد بن عبد الملك ولم يأت ذلك برواية عمن يحصل قوله كما حكي عن عمر بن عبد العزيز وإنما وجد في الكتب أنه صنع لحنا في شعره وذكره من لا يوثق به ولم نروه عن أحد فلم نأت بأخباره هاهنا مشروحة وأتيت بها في أخبار ه مع حبابة بحيث يصلح وأما اللحن الذي ذكر أنه صنعه فهو\n(أبلغ حبابة أسقى ربعها المطر ... ما للفؤاد سوى ذكراكم وطر)\n(إن سار صحبي لم أملل بذكركم ... أو عرسوا فهموم النفس والفكر)\nي هذين البيتين ثقيل أول يقال إنه ليزيد بن عبد الملك وذكر ابن المكي أنه لحبابة وحكي عن الهيثم بن عدي أن يزيد بن عبد الملك لما رأى حبابة تعلقها ولم يقدر على ابتياعها خوفا من أخيه سليمان أو من عمر بن عبد العزيز\nوقال فيها هذين البيتين وهو راحل عن الحجاز وغناه فيهما معبد فوصله بعد ذلك بما كان يغنيه وأخذته حبابة وغيرها عنه وذكر الهشامي أنه مما لا يشك فيه من غناء معبد وقد مضت أخبار يزيد بن عبد الملك وحبابة في صدر هذا الكتاب فاستغني عن إعادتها هنا\nوممن غنى منهم الوليد بن يزيد وله أصوات صنعها مشهورة وقد كان يضرب بالعود ويوقع بالطبل ويمشي بالدف على مذهب أهل الحجاز أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني عبد الله بن أبي سعد عن الفطراني عن محمد بن جبر قال حدثني من سمع خالد صامة يقول كنت يوما عند الوليد بن يزيد وأنا أغنيه\n(أراني الله يا سلمى حياتي ... )\nهو يشرب حتى سكر ثم قال لي هات العود فدفعته إليه فغناه أحسن غناء فنفست عليه إحسانه ودعوت بطبل فجعلت أوقع عليه وهو يضرب حتى دفع العود وأخذ الطبل فجعل يوقع به أحسن إيقاع ثم دعا بدف فأخذه ومشى به وجعل يغني أهزاج طويس حتى\nقلت قد عاش ثم جلس وقد انبهر فقلت يا سيدي كنت أرى أنك تأخذ عنا ونحن الآن نحتاج إلى الأخذ عنك فقال اسكت ويلك فوالله لئن سمع هذا منك أحد ما دمت حيا لأقتلنك فوالله ما حكيته عنه حتى قتل أخبرنا يحيى بن علي بن يحيى قال أخبرنا أبو أيوب المديني قال ذكر أبو الحسن المدائني أن يحيى مولى العبلات المعروف بقيل وهو الذي غنى\n(أزرى بنا أننا شالت نعامتنا ... )\nان مقيما بمكة فلما قدمها الوليد بن يزيد سأل عن أحسن الناس غناء\nوحكاية لابن سريج فقيل له فيل فدعاه وقال له امش لي بالدف ففعل ثم قال له الوليد هاته حتى أمشى به فإن أخطأت فقومني فمشى به أحسن من مشية فيل فقال له يحيى جعلت فداءك ايذن لي حتى أختلف إليك لأتعلم منك فمن مشهور صنعته في شعره\n(وصفراء في الكأس كالزعفران ... سباها التجيبي من عسقلان)\n(تريك القذاة وعرض الإ ناء ... ستر لها دون لمس البنان)","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":2,"spl":"اصوات عمر في سعاد","tags":[],"song":1,"loc":1724,"partialRef":{"sid":"b21-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b96-4","bab":"الجزء 9","sec":"اصوات عمر في سعاد","page":"ج9 ص311","text":"حنه فيه خفيف رمل وفيه لأبي كامل ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق ويونس ولعمر الوادي فيه ثقيل أول بالوسطى عن يونس والهشامي وقد مضت أخباره مشروحة في المائة الصوت المختارة وممن دونت صنعته من خلفاء بني العباس الواثق بالله ولم نعلمه حكي ذلك عن أحد منهم قبله إلا ما قدمنا سوء العهدة فيه عن ابن خرداذبة فإنه حكى أن للسفاح والمنصور وسائرهم غناء وأتى فيها بأشياء غثة لا يحسن لمحصل ذكرها\nوأخبرني يحيى بن محمد الصولي قال حدثني أحمد بن محمد بن إسحاق قال حدثنا حماد بن إسحاق عن أبيه قال دخلت يوما دار الواثق بغير إذن إلى موضع أمر أن أدخله إذا كان جالسا فسمعت صوت عود من بيت وترنما لم أسمع أحسن منه قط فأطلع خادم رأسه ثم رده وصاح بي فدخلت فإذا الواثق فقال أي شيء سمعت فقلت الطلاق لازم لي وكل مملوك لي حر لقد سمعت ما لم أسمع مثله قط حسنا فضحك فقال وما هو إنما هذه فضلة أدب وعلم مدحه الأوائل واشتهاه أصحاب رسول الله ورحمهم والتابعون بعدهم وكثر في حرم الله ومهاجر رسول الله أتحب أن تسمعه مني\nقلت إي والذي شرفني بخطابك وجميل رأيك فقال يا غلام هات العود وأعط إسحاق رطلا فدفع الرطل إلي وضرب وغنى في شعر لأبي العتاهية بلحن صنعه فيه\n(أضحت قبورهم من بعد عزهم ... تسفي عليها الصبا والحرجف السمل)\n(لا يدفعون هواما عن وجوههم ... كأنهم خشب بالقاع منجدل)\nشربت الرطل ثم قمت فدعوت له فأجلسني وقال أتشتهي أن تسمعه\nثانية فقلت إي والله فغنانيه ودعا لي برطل ففعلت كما فعلت ثانية ثم ثالثة وصاح ببعض خدمه وقال له احمل إلى إسحاق ثلثمائة ألف درهم ثم قال يا إسحاق قد سمعت ثلاثة أصوات وشربت ثلاثة أرطال وأخذت ثلثمائة ألف درهم فانصرف إلى أهلك ليسروا بسرورك فانصرفت بالدراهم أخبرني محمد قال سمعت أحمد بن محمد بن الفرات يقول سمعت عريب تقول","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":3,"spl":"اصوات عمر في سعاد — الواثق له صنعة جيدة في الغناء","tags":["المديح"],"loc":1725},
{"id":"b96-5","bab":"الجزء 9","sec":"الواثق له صنعة جيدة في الغناء","page":"ج9 ص316","text":"صنع الواثق مائة صوت ما فيها صوت ساقط ولقد صنع في هذا الشعر\n(هل تعلمين وراء الحب منزلة ... تدني إليك فإن الحب أقصاني)\n(هذا كتاب فتى طالت بليته ... يقول يا مشتكى بثى وأحزاني)\nحنا من الرمل تشبه فيه بصنعة الأوائل","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":3,"spl":"اصوات عمر في سعاد — الواثق له صنعة جيدة في الغناء","tags":["الحب والغزل","الرواية والكتابة"],"loc":1726},
{"id":"b96-6","bab":"الجزء 9","sec":"نسبة هذا الصوت","page":"ج9 ص317","text":"الشعر ليعقوب بن إسحاق الربعي المخزومي والغناء للواثق رمل بالوسطى من رواية الهشامي أخبرني محمد بن العباس اليزيدي والحرمي بن أبي العلاء وعلي بن سليمان الأخفش قالوا حدثنا أحمد بن يحيى ثعلب قال قال الزبير بن بكار كتب ابن أبي مسرة المكي إلى أهل المدينة ببيتين وهما\n(هذا كتاب فتى طالت بليته ... يقول يا مشتكى بثي وأحزاني)\n(هل تعلمين وراء الحب منزلة ... تدني إليك فإن الحب أقصاني)\nقال الزبير وكنت غائبا فلما قدمت قال لي أهل المدينة ذلك فقلت\nلهم أيكتب إليكم صاحبكم يعاتبكم فلا تجيبونه أنشدني يعقوب بن إسحاق الربعي المخزومي لنفسه\n(قال الوشاة لهند عن تصارمنا ... ولست أنسى هوى هند وتنساني)\n(يعقوب ليس بمتبول ولا كلف ... ويح الوشاة فإن الداء أضناني)\n(ما بي سوى الحب من هند وإن بخلت ... حبي لهند برى جسمي وأبلاني)\n(قد قلت حين بدا لي بخل سيدتي ... وقد تتابع بي بثي وأحزاني)\n(هل تعلمين وراء الحب منزلة ... تدني إليك فإن الحب أقصاني)\n(قالت نعم قلت ما ذاكم أسيدتي ... وطاعة الحب تنفي كل عصيان)\n(قالت فدعنا بلا صرم ولا صلة ... ولا صدود ولا في حال هجران)\n(حتى يشك وشاة قد رموك بنا ... وأعلنوا بك فينا أي إعلان)\nمن غناء الواثق بالله\n(خليلي عوجا من صدور الرواحل ... بجرعاء حزوى وابكيا في المنازل)\n(لعل انحدار الدمع يعقب راحة ... من الوجد أو يشفي نجي البلابل)\nالشعر لذي الرمة والغناء للواثق بالله رمل مطلق في مجرى الوسطى عن الهشامي ولإسحاق فيهما رمل بالسبابة في مجرى البنصر ولحن الواثق منهما الذي أوله البيت الثاني وهو اللحن المحثوث المسجح وله ردة في لعل ولحن إسحاق أوله البيت الأول ثم الثاني وهو أشدهما إمساكا وفيه صياح أخبرنا أبو أحمد يحيى بن علي بن يحيى\nقال حدثنا أبو أيوب المديني قال حدثنا محمد بن عبد الله بن مالك الخزاعي قال حدثني إسحاق بن إبراهيم الموصلي أنه دخل على إسحاق بن إبراهيم الطاهري وقد كان تكلم له في حاجة فقضيت فقال له أعطاك الله أيها الأمير ما لم تحط به أمنية ولم تبلغه رغبة\nقال فاشتهى هذا الكلام فاستعاده فأعدته قال ثم مكثنا ما شاء الله وأرسل الواثق إلى محمد بن إبراهيم يأمره بإشخاصي إليه في الصوت الذي أمرني أن أتغنى فيه وهو\n(لقد بخلت حتى لو أني سألتها ... )\nأمر لي بمائة ألف درهم فأقمت ما شاء الله ليس أحد من مغنيهم يقدر على أن يأخذ هذا الصوت مني فلما طال مقامي قلت يا أمير المؤمنين ليس أحد من هؤلاء المغنين يقدر على أن يأخذ هذا الغناء مني فقال لي ولم ويحك قلت لأني لا أصححه ولا تسخو نفسي لهم به فما فعلت يا\nأمير المؤمنين في الجارية التي أخذتها مني يعني شجا وهي التي كان أهداها إلى الواثق وعمل لها المصنف الذي في أيدي الناس لإسحاق قال وكيف فقلت لأنها تأخذه مني وأطيب به لها نفسا وهم يأخذونه منها\nقال فأمر بها فأخرجت وأخذته على المكان فأمر لي بمائة ألف درهم أخرى وأذن لي في الانصراف وكان إسحاق بن إبراهيم الطاهري حاضرا عنده فقلت له عند وداعي إياه أعطاك الله يا أمير المؤمنين ما لم تحط به أمنية ولم تبلغه رغبة فالتفت إلي إسحاق بن إبراهيم فقال لي ويحك يا إسحاق تعيد الدعاء فقلت إي والله أعيده قاص أنا أو مغن فانصرفت إلى بغداد وأقمت حتى قدم إسحاق فجئته مسلما فقال ويلك يا إسحاق أتدري ما\nقال أمير المؤمنين بعد خروجك من عنده قلت لا أيها الأمير قال قال لي ويحك كنا أغنى الناس عن أن نبعث إسحاق على لحننا فيفسده علينا هذه رواية أبي أيوب قال أبو أحمد يحيى بن علي بن يحيى وأخبرني أبي رحمه الله عن إسحاق أنه قال لما صنعت لحني في\n(خليلي عوجا من صدور الرواحل ... )\nنيته الواثق فاستحسنه وعجب من صحة قسمته ومكث صوته أياما ثم قال لي يا إسحاق قد صنعت لحنا في صوتك وفي إيقاعه وأمر فغنيت به فقلت يا أمير المؤمنين بغضت إلي لحني وسمجته عندي وقد كنت استأذنته مرات في الانحدار إلى بغداد بعد أن ألقيت اللحن الذي كان أمرني بصنعه في\n(لقد بخلت حتى لو اني سألتها ... )\nمنعني ودافعني بذلك فلما صنع لحنه الرمل في\n(خليلي عوجا من صدور الرواحل ... )","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":4,"spl":"نسبة هذا الصوت","tags":["الحب والغزل"],"song":1,"loc":1727,"partialRef":{"sid":"b52-107","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b96-7","bab":"الجزء 9","sec":"نسبة هذا الصوت","page":"ج9 ص317","text":"قلت له يا أمير المؤمنين قد والله اقتصصت وزدت فأذن لي بعد ذلك قال أبو الحسن علي بن يحيى قلت لإسحاق فأيهما أجود الآن لحنك فيه أو لحنه فقال لحني أجود قسمة وأكثر عملا ولحنه أظرف لأنه جعل ردته من نفس قسمته فليس يقدر على أدائه إلا متمكن من نفسه قال أبو الحسن فتأملت اللحنين بعد ذلك فوجدتهما كما ذكر إسحاق قال وقال لي إسحاق ما كان يحضر مجلس الواثق أعلم منه بالغناء فأما نسبة هذين الصوتين فإن أحدهما قد مضى ومضت نسبته والآخر\n(أيا منشر الموتى أقدني من التي ... بها نهلت نفسي سقاما وعلت)\n(لقد بخلت حتى لو أني سألتها ... قذى العين من ضاحي التراب لضنت)\nلشعر لأعرابي رواه إسحاق عنه ولم يذكر اسمه والناس يغلطون فينسبونه إلى كثير ويظنونه من قصيدته التي أولها\n(خليلي هذا رسم عزة فاعقلا ... قلوصيكما ثم ابكيا حيث حلت)\nهذا خطأ ممن قال ذلك والغناء للواثق ثاني ثقيل بالوسطى ولإسحاق في البيت الثاني وبعده بيت ألحقه به ليس من الشعر ثقيل أول بالسبابة في مجرى الوسطى والبيت الذي ألحقه إسحاق به من شعره\n(فإن بخلت فالبخل منها سجية ... وإن بذلت أعطت قليلا وأكدت)\nخبرني عمي رحمه الله قال حدثني أبو جعفر بن الدهقانة النديم قال كان الواثق إذا أراد أن يعرض صنعته على إسحاق نسبها إلى غيره وقال وقع إلينا صوت قديم من بعض العجائز ما سمعه أحد ويأمر من يغنيه إياه وكان إسحاق يأخذ نفسه في ذلك بقول الحق أشد أخذ فإن كان جيدا من\nصناعته قرظه ووصفه واستحسنه وإن كان مطرحا أو فاسدا أو متوسطا ذكر ما فيه فربما كان للواثق فيه هوى فيسأله عن تقويمه وإصلاح فساده وربما اطرحه بقول إسحاق فيه إلى أن صنع لحنا في قول الشاعر\n(لقد بخلت حتى لو أني سألتها ... قذى العين من ضاحي التراب لضنت)\nأعجب به واستحسنه وأمر المغنين فغنوا فيه وأمر بإشخاص إسحاق إليه من بغداد ليسمعه فكاده مخارق عنده وقال يا أمير المؤمنين إن إسحاق شيطان خبيث داهية وإن قولك له فيما تصنعه هذا صوت وقع إلينا لا يخفى عليه به أن الصوت لك ومن صنعتك ولا يوقع في فهمه أنه قديم فيقول لك وبحضرتك ما يقارب هواك فإذا خرج عن حضرتك\nقال لنا ضد ذلك فأحفظ الواثق قوله وغاظه وقال له أريد على هذا القول منك دليلا قال أنا أقيم عليه الدليل إذا حضر فلما قدم به وجلس في أول مجلس اندفع مخارق يغني لحن الواثق\n(لقد بخلت حتى لو اني سألتها ... )\nزاد فيه زوائد أفسدت قسمته فسادا شديدا وخفيت على الواثق لكثرة زوائد مخارق في غنائه فسأله الواثق عنه فقال هذا غناء فاسد غير مرضي عندي فغضب الواثق وأمر بإسحاق فسحب حتى أخرج من المجلس فلما كان من الغد قالت فريدة للواثق يا أمير المؤمنين إن إسحاق رجل يأخذ نفسه بقوله الحق في صناعته على كل حال ساءته أو سرته لا يخاف في ذلك ضررا ولا يرجو نفعا وما لك منه عوض وقد كاده مخارق عندك فزاد في صدر الصوت من زوائده التي تعرف وتركه في المصراع الثاني على حاله ونقص من البيت الثاني وقد تبينت ذلك وأنا أعرضه على إسحاق وأغنيه إياه على صحته واسمع ما يقول وما زالت تلطف للواثق حتى رضي عنه وأمر بإحضاره فغنته إياه فريدة كما صنعه الواثق فلما سمعه قال هذا صوت صحيح الصنعة والقسمة والتجزئة وما هكذا سمعته في المرة الأولى ثم\nأخبر الواثق عن مواضع فساده حينئذ وأبان ذلك له بما فهمه وغنته فريدة عدة أصوات من القديم والحديث كلها يقول فيها بما عنده من مدح لبعضها وطعن على بعض فاستحسن الواثق ذلك وأجازه يومئذ وحباه وجفا مخارقا مدة لما فعله به","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":5,"spl":"نسبة هذا الصوت","tags":["المديح"],"song":1,"loc":1728,"partialRef":{"sid":"b52-105","gi":8,"vi":1,"side":0},"partial":1},
{"id":"b96-8","bab":"الجزء 9","sec":"منزلة إسحاق عنده","page":"ج9 ص323","text":"أخبرني جحظة قال حدثني ابن المكي عن أبيه قال كان الواثق إذا صنع شيئا من الغناء أخبر إسحاق به وعرضه عليه حتى يصلح ما فيه ثم يظهره وقد\nأخبرني الحسن بن علي عن يزيد بن محمد المهلبي بهذا الخبر فذكر نحو ما ذكرته ها ههنا وفي ألفاظه اختلاف وقد تقدم ذكره وابتدأناه في أخبار إسحاق والأبيات الثانية التي غنى فيها الواثق وإسحاق أنشدنيها علي بن سليمان الأخفش وعلي بن هارون بن علي بن يحيى جميعا عن هارون بن علي بن يحيى عن أبيه عن إسحاق لأعرابي وأنشدناها محمد بن العباس اليزيدي قال أنشدني أحمد بن يحيى ثعلب لبعض الأعراب\n(ألا قاتل الله الحمامة غدوة ... على الغصن ماذا هيجت حين غنت)\n(فغنت بصوت أعجمي فهيجت ... هواي الذي كانت ضلوعي أكنت)\n(فلو قطرت عين امرئ من صبابة ... دما قطرت عيني دما وألمت)\n(فما سكتت حتى أويت لصوتها ... وقلت أرى هذي الحمامة جنت)\n(ولي زفرات لو يدمن قتلنني ... بشوق إلى نادي التي قد تولت)\n(إذا قلت هذي زفرة اليوم قد مضت ... فمن لي بأخرى في غد قد أظلت)\n(أيا منشر الموتى أعني على التي ... بها نهلت نفسي سقاما وعلت)\n(لقد بخلت حتى لو اني سألتها ... قذى العين من سافي التراب لضنت)\n(فقلت ارحلا يا صاحبي فليتني ... أرى كل نفس أعطيت ما تمنت)\n(حلفت لها بالله ما أم واحد ... إذا ذكرته آخر الليل أنت)\n(وما وجد أعرابية قذفت بها ... صروف النوى من حيث لم تك ظنت)\n(إذا ذكرت ماء العضاه وطيبه ... وبطن الحصى من بطن خبت أرنت)\n(بأعظم من وجدي بها غير أنني ... أجمجم أحشائي على ما أجنت)\nخبرني جحظة وابن أبي الأزهر ويحيى بن علي والحسين بن يحيى قالوا جميعا أخبرنا حماد بن إسحاق عن أبيه وقد جمعت روايتهم في هذا الخبر وزدت فيه ما نقصه كل واحد منهم حتى كملت ألفاظه قال ما وصلني أحد من الخلفاء بمثل ما وصلني به الواثق وما كان أحد منهم يكرمني إكرامه ولقد غنيته لحني\n(لعلك إن طالت حياتك أن ترى ... بلادا بها مبدى لليلى ومحضر)\nاستعاده مني ليلة لا يشرب على غيره ثم وصلني بثلثمائة ألف درهم ولقد قدمت عليه في بعض قدماتي فقال لي ويحك يا إسحاق أما اشتقت إلي فقلت بلى والله يا سيدي وقلت في ذلك أبياتا إن أمرتني أنشدتها قال هات فأنشدته\n(أشكو إلى الله بعدي عن خليفته ... وما أقاسيه من هم ومن كبر)\n(لا أستطيع رحيلا إن هممت به ... يوما إليه ولا أقوى على السفر)\n(أنوي الرحيل إليه ثم يمنعني ... ما أحدث الدهر والأيام في بصري)\nم استأذنته في إنشاد قصيدة مدحته بها فأذن لي فأنشدته قصيدتي التي أقول فيها\n(لما أمرت بإشخاصي إليك هوى ... قلبي حنينا إلى أهلي وأولادي)\n(ثم اعتزمت فلم أحفل ببينهم ... وطابت النفس عن فضل وحماد)\n(كم نعمة لأبيك الخير أفردني ... بها وخص بأخرى بعد إفرادي)\n(فلو شكرت أياديكم وأنعمكم ... لما أحاط بها وصفي وتعدادي)\n(لأشكرنك ما غار النجوم وما ... حدا على الصبح في إثر الدجى حاد)\nال علي بن يحيى خاصة في خبره فقال لي أحمد بن إبراهيم يا أبا الحسن أخبرني لو قال الخليفة لإسحاق أحضر لي فضلا وحمادا أليس كان يفتضح إسحاق يعني من دمامة خلقتهما وتخلف شاهدهما","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":6,"spl":"منزلة إسحاق عنده","tags":["الحب والغزل"],"loc":1729},
{"id":"b96-9","bab":"الجزء 9","sec":"الواثق وإسحاق في طريقهما إلى النجف","page":"ج9 ص325","text":"قال إسحاق ثم انحدرت مع الواثق إلى النجف فقلت يا أمير المؤمنين قد قلت في النجف قصيدة فقال هاتها فأنشدته قولي\n(يا راكب العيس لا تعجل بنا وقف ... نحي دارا لسعدي ثم ننصرف)\n(لم ينزل الناس في سهل ولا جبل ... أصفى هواء ولا أغذى من النجف)\n(حفت ببر وبحر في جوانبها ... فالبر في طرف والبحر في طرف)\n(ما إن يزال نسيم من يمانية ... يأتيك منها بريا روضة أنف)\nتى انتهيت إلى مديحه فقلت وقد انتهيت إلى قولي فيه\n(لا يحسب الجود يفني ماله أبدا ... ولا يرى بذل ما يحوي من السرف)\nقال لي أحسنت يا أبا محمد فكناني وأمر لي بألف درهم وانحدرنا إلى الصالحية التي يقول فيها أبو نواس\n(فالصالحية من أكناف كلواذا ... )\nذكرت الصبيان وبغداد فقلت\n(أتبكي على بغداد وهي قريبة ... فكيف إذا ما ازددت منها غدا بعدا)\n(لعمرك ما فارقت بغداد عن قلى ... لو انا وجدنا من فراق لها بدا)\n(إذا ذكرت بغداد نفسي تقطعت ... من الشوق أو كادت تموت بها وجدا)\n(كفى حزنا أن رحت لم تستطع لها ... وداعا ولم تحدث لساكنها عهدا)\nقالت لي يا موصلي لقد اشتقت إلى بغداد فقلت لا والله يا أمير المؤمنين ولكني اشتقت إلى الصبيان وقد حضرني بيتان فقال هاتهما فقلت\n(حننت إلى الأصيبية الصغار ... وشاقك منهم قرب المزار)\n(وكل مفارق يزداد شوقا ... إذا دنت الديار من الديار)\nقال لي يا إسحاق سر إلى بغداد فأقم شهرا مع صبيانك ثم عد إلينا وقد أمرت لك بمائة ألف درهم أخبرني جحظة عن ابن حمدون أن إسحاق كان يحضر مجالس الخلفاء إذا جلسوا للشرب في جملة المغنين وعوده معه إلى أيام الواثق فإنه كان إذا قدم عليه يحضر مع الجلساء بغير عود ويدنيه الواثق ولا يغني حتى\nيقول له غن فإذا قال له غن جاؤوه بعود فغنى به وإذا فرغ رفع العود من بين يديه إكراما من الواثق له أخبرني الحسين بن يحيى عن وسواسة بن الموصلي عن حماد بن إسحاق قال كتب حمدون بن إسماعيل إلى أبي إن أمير المؤمنين الواثق يأمرك أن تصنع لحنا في هذا الشعر\n(لقد بخلت حتى لو اني سألتها ... )\nوقد كان الواثق غنى فيه غناء أعجبه فغنى فيه أبي فلما سمعه الواثق قال أفسد علينا إسحاق ما كنا أعجبنا به من غنائنا قال حماد ثم لم أعلم أن أبي صنع بعده غناء حتى مات ومن مشهور أغاني الواثق\n(سقى العلم الفرد الذي في ظلاله ... غزالان مكحولان مؤتلفان)\n(أرغتهما ختلا فلم أستطعهما ... ورميا ففاتاني وقد رمياني)\nلحنه فيه من الثقيل الأول ولإسحاق فيه رمل أخبرني محمد بن خلف بن المرزبان قال حدثنا عبد الله بن أبي سعد قال أخبرني محمد بن منصور بن علية القرشي قال أخبرني جعفر بن عبيد الله بن جعفر الهاشمي عن إسحاق بن سليمان بن علي قال\nلقيت أعرابيا بالسمية فصيحا فاستخففته وتأملته فإذا هو مصفر شاحب ناحل الجسم فاستنشدته فأنشدني الشيء بعد الشيء على استكراه مني له فقلت له ما بالك فوالله إنك لفصيح فقال أما ترى الجبلين\nقلت بلى قال في ظلالهما والله ما يمنعني من إنشادك ويشغلني ويذهلني عن الناس قلت وما ذاك قال بنت عم لي قد تيمتني وذهبت بعقلي والله إنه لتأتي علي ساعات ما أدري أفي السماء أنا أم في الأرض ولا أزال ثابت العقل ما لم يخامر ذكرها قلبي فإذا خامره بطلت حواسي وعزب عني لبي\nقلت فما يمنعك منها أقلة ما في يدك قال والله ما يمنعني منها غير ذلك قلت وكم مهرها قال مائة ناقة قلت فأنا أدفعها إليك إذا لتدفعها إليهم قال والله لئن فعلت ذلك إنك لأعظم الناس علي منة فوعدته بذلك واستنشدته ما قال فيها فأنشدني أشياء كثيرة منها قوله\n(سقى العلم الفرد الذي في ظلاله ... غزالان مكحولان مؤتلفان)\nلبيتان فقلت له يا أعرابي والله لقد قتلتني بقولك ففاتاني وقد قتلاني وأنا برئ من العباس إن لم أقم بأمرك ثم دعوت بمركوب فركبته وحملت معي الأعرابي فصرنا إلى أبي الجارية في جماعة من أهلي وموالي حتى زوجته إياها وضمنت عنه الصداق واشتريت له مائة ناقة فسقتها عنه وأقمت عندهم ثلاثا ونحرت لهم ثلاثين جزورا ووهبت للأعرابي عشرة آلاف درهم وللجارية مثلها وقلت استعينا بهذا على اتصالكما وانصرفت فكان الأعرابي يطرقنا في كل سنة وامرأته معه فأهب له وأصله وينصرف","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":7,"spl":"الواثق وإسحاق في طريقهما إلى النجف","tags":[],"song":1,"loc":1730,"partialRef":{"sid":"b52-105","gi":8,"vi":1,"side":0},"partial":1},
{"id":"b96-10","bab":"الجزء 9","sec":"غناؤه في شعر حسان","page":"ج9 ص328","text":"ومن أغانيه أخبرني به ذكاء وجه الرزة عن أحمد بن أبي العلاء عن مخارق وأنه أخذه عنه\n\n(إن التي عاطيتها فرددتها ... قتلت قتلت فهاتها لم تقتل)\n(كلتاهما حلب العصير فعاطني ... بزجاجة أرخاهما للمفصل)\nروى كلتاهما جلب العصير وحلب العصير ويروى للمفصل وللمفصل والمفصل الواحد من المفاصل والمفصل هو اللسان ذكر ذلك علي بن سليمان الأخفش عن محمد بن الحسن الأحول عن ابن الأعرابي الشعر لحسان بن ثابت والغناء للواثق خفيف رمل بالبنصر وفيه لإبراهيم الموصلي رمل مطلق في مجرى الوسطى وهذه الأبيات من قصيدة حسان المشهورة التي يمدح بها بني جفنة وأولها\n(أسألت رسم الدار أم لم تسأل ... )\nهي من فاخر المديح منها قوله\n(أولاد جفنة عند قبر أبيهم ... قبر ابن مارية الكريم المفضل)\n(يسقون من ورد البريص عليهم ... بردى يصفق بالرحيق السلسل)\n(بيض الوجوه كريمة أنسابهم ... شم الأنوف من الطراز الأول)\n(يغشون حتى ما تهر كلابهم ... لا يسألون عن السواد المقبل)\nسخت من كتاب الشاهيني حدثني ابن عليل العنزي قال حدثني أحمد بن عبد الملك بن أبي السمال السعدي قال حدثني أبو ظبيان الحماني قال اجتمعت جماعة من الحي على شراب لهم فتغنى رجل منهم بشعر حسان\n(إن التي عاطيتني فرددتها ... قتلت قتلت فهاتها لم تقتل)\n(كلتاهما حلب العصير فعاطني ... بزجاجة أرخاهما للمفصل)\nقال رجل من القوم ما معنى قوله إن التي عاطيتني فجعلها واحدة ثم قال كلتاهما حلب العصير فجعلهما ثنتين فلم يعلم أحد منا الجواب فقال رجل من القوم امرأته طالق ثلاثا إن بات أو يسأل القاضي عبيد الله بن الحسن عن تفسير هذا الشعر\nقال أبو ظبيان فحدثني بعض أصحابنا السعديين قال فأتيناه نتخطى إليه الأحياء حتى أتيناه وهو في مسجده يصلي بين العشاءين فلما سمع حسنا أوجز في صلاته ثم أقبل علينا\nوقال ما حاجتكم فبدأ رجل منا كان أحسننا بقية فقال نحن أعز الله القاضي قوم نزعنا إليك من طرف البصرة في حاجة مهمة فيها بعض الشيء فإن أذنت لنا قلنا\nقال قولوا فذكر يمين الرجل والشعر فقال أما قوله إن التي ناولتني هي الخمرة وقوله قتلت يعني مزجت بالماء وقوله كلتاهما حلب العصير يعني به الخمر ومزاجها فالخمر عصير العنب والماء عصير السحاب قال الله عز و جل ( وأنزلنا من المعصرات ماء ثجاجا\nانصرفوا إذا شئتم أخبرني محمد بن يحيى قال حدثني أحمد بن يزيد المهلبي عن أبيه قال غنى مخارق يوما بحضرة الواثق\n(حتى إذا الليل خبا ضوءه ... وغابت الجوزاء والمرزم)\n(خرجت والوطء خفي كما ... ينساب من مكمنه الأرقم)\nاستملح الواثق الشعر واللحن فصنع في نحوه\n(قالت إذا الليل دجا فأتنا ... فجئتها حين دجا الليل)\n(خفي وطء الرجل من حارس ... ولو درى حل بي الويل)\nلحنه فيه من الرمل وصنع فيه الناس ألحانا بعده منها لعريب خفيف رمل ومنها ثقيل أول لا أعلم لمن هو وسمعت ذكاء ومحمد بن إبراهيم قريضا يغنيانه وذكرا أنهما أخذاه عن أحمد بن أبي العلاء ولا أدري لمن هو\nحدثني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق قال حدثني أبي قال سرت إلى سر من رأى بعد قدومي من الحج فدخلت إلى الواثق فقال بأي شيء أطرفتني من أحاديث الأعراب وأشعارهم فقلت يا أمير المؤمنين جلس إلي فتى من الأعراب في بعض المنازل فحادثني فرأيت منه أحلى ما رأيت من الفتيان منظرا وحديثا وأدبا فاستنشدته فأنشدني\n(سقى العلم الفرد الذي في ظلاله ... غزالان مكحولان مؤتلفان)\n(إذا أمنا التفا بجيدي تواصل ... وطرفاهما للريب مسترقان)\n(أرغتهما ختلا فلم أستطعهما ... ورميا ففاتاني وقد قتلاني)\nم تنفس تنفسا ظننت أنه قد قطع حيازيمه فقلت مالك بأبي أنت\nفقال إن لي وراء هذين الجبلين شجنا وقد حيل بيني وبين المرور به ونذروا دمي وأنا أتمتع بالنظر إلى الجبلين تعللا بهما إذا قدم الحاج ثم يحال بيني وبين ذلك فقلت له زدني مما قلت في ذلك فأنشدني\n(إذا ما وردت الماء في بعض أهله ... حضور فعرض بي كأنك مازح)\n(فإن سألت عني حضور فقل لها ... به غبر من دائه وهو صالح)","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":8,"spl":"غناؤه في شعر حسان","tags":[],"song":1,"loc":1731,"partial":1},
{"id":"b96-11","bab":"الجزء 9","sec":"غناؤه في شعر حسان","page":"ج9 ص328","text":"أمرني الواثق فكتبت له الشعرين فلما كان بعد أيام دعاني فقال قد صنع بعض عجائز دارنا في أحد الشعرين لحنا فاسمعه فإن ارتضيته أظهرناه وإن رأيت فيه موضع إصلاح أصلحته فغني لنا من وراء الستار فكان في نهاية الجودة وكذلك كان يفعل إذا صنع شيئا فقلت له أحسن والله صانعه يا أمير المؤمنين ما شاء فقال بحياتي فقلت وحياتك وحلفت له بما وثق به وأمر لي برطل فشربته ثم أخذ العود فغناه ثلاث مرات وسقاني ثلاثة أرطال وأمر لي بثلاثين ألف درهم فلما كان بعد أيام دعاني فقال قد صنع أيضا عندنا في الشعر الآخر وأمر فغني به فكانت حالي فيه مثل الحال في الأول فلما استحسنته وحلفت له على جودته ثلاث مرات سقاني ثلاثة أرطال وأمر لي بثلاثين ألف درهم ثم\nقال لي هل قضيت حق هديتك فقلت نعم يا أمير المؤمنين فأطال الله بقاءك وتمم نعمتك ولا أفقدنيها منك وبك ثم قال لكنك لم تقض حق جليسك الأعرابي ولا سألتني معونته على أمره وقد سبقت مسألتك وكتبت بخبره إلى صاحب الحجاز وأمرته بإحضاره وخطبت المرأة له وحمل صداقها إلى قومها عنه من مالي فقبلت يده وقلت السبق إلى المكارم لك وأنت أولى بها من عبدك ومن سائر الناس","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":9,"spl":"غناؤه في شعر حسان — طرب شيخ فرمى بنفسه في الفرات","tags":[],"loc":1732},
{"id":"b96-13","bab":"الجزء 9","sec":"نسبة ما في هذه الأخبار من الأغاني — شوت","page":"ج9 ص332 – ج9 ص332","text":"منها الصوتان اللذان في الأخبار المتقدمة\n(حتى إذا الليل خبا ضوءه ... وغابت الجوزاء والمرزم)\n(أقبلت والوطء خفي كما ... ينساب من مكمنة الأرقم)\nكر يحيى المكي أن اللحن لابن سريج رمل بالسبابة في مجرى البنصر وذكر الهشامي أنه منحول","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":9,"spl":"غناؤه في شعر حسان — طرب شيخ فرمى بنفسه في الفرات","tags":["الوصف والطبيعة"],"loc":1733},
{"id":"b96-14","bab":"الجزء 9","sec":"طرب شيخ فرمى بنفسه في الفرات","page":"ج9 ص333","text":"فأخبرني أحمد بن عبيد الله بن عمار وإسماعيل بن يونس وغيرهما قالوا حدثنا عمر بن شبة قال حدثني إسحاق بن إبراهيم عن ابن كناسة قال اصطحب شيخ مع شباب في سفينة في الفرات ومعهم مغنية فلما صاروا في بعض الطريق قالوا للشيخ معنا جارية لبعضنا وهي مغنية فأحببنا أن نسمع غناءها فهبناك فإن أذنت لنا فعلنا قال أنا أصعد إلى طلل السفينة فاصنعوا أنتم ما شئتم فصعد وأخذت الجارية عودها فغنت\n(حتى إذا الصبح بدا ضوءه ... وغابت الجوزاء والمرزم)\n(أقبلت والوطء خفي كما ... ينساب من مكمنه الأرقم)\nطرب الشيخ وصاح ثم رمى بنفسه بثيابه في الفرات وجعل يغوص في الفرات ويطفو ويقول أنا الأرقم أنا الأرقم فألقوا أنفسهم خلفه فبعد لأي ما استخرجوه وقالوا له يا شيخ ما حملك على ما صنعت فقال إليكم عني فإني والله أعرف من معاني الشعر ما لا تعرفون\nوقال إسماعيل في خبره فقلت له ما أصابك فقال دب شيء من قدمي إلى رأسي كدبيب النمل ونزل في رأسي مثله فلما وردا على قلبي لم أعقل ما عملت وأما ما في الخبر من الصنعة في قالت إذا الليل دجا فإن لحن الواثق\nهو المشهور وما وجدت في كتب الأغاني غيره بل سمعت محمد بن إبراهيم المعروف بقريض وذكاء وجه الرزة يغنيان فيه لحنا من الثقيل الأول المذموم فسألتهما عن صانعه فلم يعرفاه وذكرا جميعا أنهما أخذاه عن أحمد بن أبي العلاء","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":9,"spl":"غناؤه في شعر حسان — طرب شيخ فرمى بنفسه في الفرات","tags":["الجواري والنساء"],"loc":1734},
{"id":"b96-15","bab":"الجزء 9","sec":"الواثق أعلم الخلفاء بالغناء","page":"ج9 ص334","text":"وأخبرني الصولي عن أحمد بن محمد بن إسحاق عن حماد بن إسحاق قال كان الواثق أعلم الخلفاء بالغناء وبلغت صنعته مائة صوت وكان أحذق من غنى بضرب العود قال ثم ذكرها فعد منها\n(يفرح الناس بالسماع وأبكى ... أنا حزنا إذا سمعت السماعا)\n(ولها في الفؤاد صدع مقيم ... مثل صدع الزجاج أعيا الصناعا)\nلشعر للعباس بن الأحنف والغناء للواثق خفي ثقيل وفيه لأبي دلف خفيف رمل ومنها\n(ألا أيها النفس التي كادها الهوى ... أفآنت إذا رمت السلو غريمي)\n(أفيقي فقد أفنيت صبري أو اصبري ... لما قد لقيتيه علي ودومي)\nلشعر والغناء للواثق خفيف رمل ومنها\n(سقى العلم الفرد الذي في ظلاله ... غزالان مكحولان مؤتلفان)\n(أرغتهما ختلا فلم أستطعهما ... ورميا ففاتاني وقد قتلاني)\nلغناء للواثق ثقيل أول وفيه لإسحاق رمل وهو من غريب صنعته يقال إنه صنعه بالرقة ومنها\n(كل يوم قطيعة وعتاب ... ينقضي دهرنا ونحن غضاب)\n(ليت شعري أنا خصصت بهذا ... دون ذا الخلق أم كذا الأحباب)\n(فاصبر النفس لا تكونن جزوعا ... إنما الحب حسرة وعذاب)\nيه للواثق رمل ولزرزور ثقيل أول ولعريب هزج ومنها\n(ولم أر ليلى بعد موقف ساعة ... بخيف منى ترمي جمار المحصب)\n(ويبدي الحصى منها إذا قذفت به ... من البرد أطراف البنان المخضب)\n(فأصبحت من ليلى الغداة كناظر ... مع الصبح في أعقاب نجم مغرب)\n(ألا إنما غادرت يا أم مالك ... صدى أينما تذهب به الريح يذهب)\nالصنعة في هذا الشعر ثقيل أول وهو لحن الواثق فيما أرى ونسبه\nحبش وهو قليل التحصيل إلى ابن محرز في موضع وإلى سليم في موضع آخر وإلى معبد في موضع ثالث ومنها\n(أمست وشاتك قد دبت عقاربها ... وقد رموك بعين الغش وابتدروا)\n(تريك أعينهم ما في صدورهم ... إن الصدور يؤدي غيبها النظر)\nلشعر للمجنون والغناء للواثق ثاني ثقيل وفيه لمتيم ثقيل أول وقد نسب لحن كل واحد منهما إلى الآخر ومنها\n(عجبت لسعي الدهر بيني وبينها ... فلما انقضى ما بيننا سكن الدهر)\n(فيا هجر ليلى قد بلغت بي المدى ... وزدت على ما لم يكن بلغ الهجر)\nلغناء للواثق رمل وفيه لمعبد ثاني ثقيل بالوسطى ولابن سريج ثقيل أول بالبنصر ولعريب ثقيل أول آخر ومنها\n(كأن شخصي وشخصه حكيا ... نظام نسرينتين في غصن)\n(فليت ليلى وليله أبدا ... دام ودمنا به فلم نبن)\nلشعر أظنه لعلي بن هشام أو لمراد ولحن الواثق فيه ثقيل أول وفيه لعريب ثقيل أول آخر وفيه لأبي عيسى بن الرشيد ولمتيم لحنان لم يقع إلي جنسهما ومنها\n(اهابك إجلالا وما بك قدرة ... علي ولكن ملء عين حبيبها)\n(وما فارقتك النفس يا ليل أنها ... قلتك ولكن قل منك نصيبها)\nحن الواثق فيه ثقيل أول مطلق في مجرى الوسطى وفيه لغيره لحن ومنها\n(في فمي ماء وهل ينطق ... من في فيه ماء)\n(أنا مملوك لمملوك ... عليه الرقباء)\n(كنت حرا هاشميا ... فاسترقتني الإماء)\n(وسباني من له كان ... على الكره السباء)\n(أحمد الله على ما ... ساقه نحوي القضاء)\n(ما بعيني دموع ... أنفد الدمع البكاء)\nلغناء للواثق رمل ومنها\n(أي عون على الهموم ثلاث ... مترعات من بعدهن ثلاث)\n(بعدها أربع تتمة عشر ... لا بطاء لكنهن حثاث)\nيه رمل ينسب إلى الواثق وإلى متيم ومنها\n(أيا عبرة العينين قد ظمئ الحد ... فما لكما من أن تلما به بد)\n(ويا مقلة قد صار يبغضها الكرى ... كأن لم يكن من قبل بينهما ود)\n(لئن كان طول العهد أحدث سلوة ... فموعد بين العين والعبرة الوجد)\n(وما أنا إلا كالذين تخرموا ... على أن قلبي من قلوبهم فرد)\nلشعر والغناء للواثق رمل وفيه لأبي حشيشة هزج ذكر ذلك الهشامي\nالملقب بالمسك وأخبرني جحظة أنه للمسدود وأخبرني جحظة أن من صنعة أبي حشيشة في شعر الواثق خفيف رمل وهو\n(سألته حويجة فأعرضا ... وعلق القلب به ومرضا)\n(فاستل مني سيف عزم منتضى ... فكان ما كان وكابرنا القضا)\nقال وفي هذا الشعر أيضا بعينه للواثق رمل ولقلم الصالحية فيه هزج وقد غلط جحظة في هذا الشعر وهو لسعيد بن حميد مشهور وله فيه خبر قد ذكرناه في موضعه أخبرني عمي عن علي بن محمد بن نصر عن جده ابن حمدون عن أبيه حمدون بن إسماعيل قال كان الواثق يحب خادما له كان أهدي إليه من مصر فغاضبه يوما وهجره فسمع الخادم يحدث صاحبا له بحديث أغضبه عليه إلى أن قال له والله إنه ليجهد منذ أمس على أن أصالحه فما أفعل فقال الواثق في ذلك","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":10,"spl":"الواثق أعلم الخلفاء بالغناء","tags":["الحب والغزل"],"loc":1735},
{"id":"b96-16","bab":"الجزء 9","sec":"الواثق أعلم الخلفاء بالغناء","page":"ج9 ص334","text":"(يا ذا الذي بعذابي ظل مفتخرا ... هل أنت إلا مليك جار إذ قدرا)\n(لولا الهوى لتجازينا على قدر ... وإن أفق مرة منه فسوف ترى)\nال وغنى الواثق وعلويه فيه لحنين ذكر الهشامي أن لحن الواثق خفيف ثقيل وفي أغاني علويه لحنه في هذا الشعر خفيف رمل\nحدثني الصولي قال حدثني ابن أبي العيناء عن أبيه عن إبراهيم بن الحسن ابن سهل قال كنا وقوفا على رأس الواثق في أول مجالسه التي جلسها لما ولي الخلافة فقال من ينشدنا شعرا قصيرا مليحا فحرصت على أن أعمل شيئا فلم يجئني فأنشدته لعلي بن الجهم\n(لو تنصلت إلينا ... لوهبنا لك ذنبك)\n(ليتني أملك قلبي ... مثلما تملك قلبك)\n(أيها الواثق بالله ... لقد ناصحت ربك)\n(سيدي ما أبغض العيش ... إذا فارقت قربك)\n(أصبحت حجتك العليا ... وحزب الله حزبك)\nاستحسنها وقال لمن هذه فقلت لعبدك علي بن الجهم فقال خذ ألف دينار لك وله وصنع فيها لحنا كنا نغني به بعد ذلك أخبرني محمد بني يحيى بن أبي عباد قال حدثني أبي قال لما خرج المعتصم إلى عمورية استخلف الواثق بسر من رأى فكانت أموره كلها كأمور أبيه فوجه إلى الجلساء والمغنين أن يبكروا إليه يوما حدد لهم\nووجه إلى إسحاق فحضر الجميع فقال لهم الواثق إني عزمت على الصبوح ولست أجلس على سرير حتى أختلط بكم ونكون كالشيء الواحد فاجلسوا معي حلقة وليكن كل جليس إلى جانبه مغن فجلسوا كذلك فقال الواثق أنا أبدأ فأخذ عودا فغنى وشربوا وغنى من بعده حتى انتهى إلى إسحاق فأعطي العود فلم يأخذه فقال دعوه ثم غنوا دورا آخر فلما بلغ الغناء إلى إسحاق لم يغن وفعل هذا ثلاث مرات فوثب الواثق فجلس على سريره وأمر بالناس فأدخلوا فما\nقال لأحد منهم اجلس ثم قال علي بإسحاق فلما رآه قال يا خوزي يا كلب أتنزل لك وأغني وترتفع عني أترى لو أني قتلتك كان المعتصم يقيدني بك أبطحوه فبطح فضرب ثلاثين مقرعة ضربا خفيفا وحلف ألا يغني سائر يومه سواه فاعتذر وتكلمت الجماعة فيه فأخذ العود وما زال يغني حتى انقضى ذلك اليوم وعاد الواثق إلى مجلسه وجدت في بعض الكتب عن ابن المعتز قال كان الواثق يهوى خادما له فقال فيه\n(سأمنع قلبي من مودة غادر ... تعبدني خبثا بمكر مكاشر)\n(خطبت إليه الوصل خطبة راغب ... فلاحظني زهوا بطرف مهاجر)\nال أبو العباس عبد الله بن المعتز وللواثق في هذا الشعر لحن من الثقيل الأول أخبرني محمد بني يحيى قال حدثني الحسين بن يحيى أبو الحمار قال حدثني عبد أم غلام الواثق قال\nدعا بنا الواثق مع صلاة الغداة وهو يستاك فقال خذوا هذا الصوت ونحن عشرون غلاما كلنا يغني ويضرب ثم ألقى علينا\n(أشكو إلى الله ما ألقى من الكمد ... حسبي بربي فلا أشكو إلى أحد)\nفما زال يردده حتى أخذنا عنه نسبة هذا الصوت\n(أشكو إلى الله ما ألقى من الكمد ... حسبي بربي فلا أشكو إلى أحد)\n(أين الزمان الذي قد كنت ناعمة ... مهلة بدنوي منك يا سندي)\n(وأسأل الله يوما منك يفرحني ... فقد كحلت جفون العين بالسهد)\n(شوقا إليك وما تدرين ما لقيت ... نفسي عليك وما بالقلب من كمد)\nلغناء للواثق ثقيل أول بالبنصر وفيه لعريب أيضا ثقيل أول بالوسطى أخبرني أحمد بن جعفر جحظة قال حدثني محمد بن أحمد المكي قال حدثني أبي قال كان الواثق يعرض صنعته على إسحاق فيصلح الشيء بعد الشيء مما يخفى على الواثق فإذا صححه أخرجه إلينا وسمعناه حدثنا جحظة قال حدثني حماد بن إسحاق قال حدثني مخارق قال لما صنع الواثق لحنه في\n(حوراء ممكورة منعمة ... كأنما شف وجهها نزف)\nوصنع لحنه في سأذكر سربا طال ما كنت فيهم أمرني وعلويه وعريب أن نعارض صنعته فيهما ففعلنا واجتهدنا ثم غنيناه فضحك فقال أمنا معكم أن نجد من يبغض إلينا صنعتنا كما بغض إسحاق إلينا أيا منشر الموتى\nقال حماد هذا آخر لحن صنعه أبي يعني الذي عارض به لحن الواثق في أيا منشر الموتى أخبرني جحظة قال حدثني حماد بن إسحاق عن أبيه قال دخلت يوما إلى الواثق وهو مصطبح فقال لي غنني يا إسحاق بحياتي عليك صوتا غريبا لم أسمعه منك حتى أسر به بقية يومي فكأن الله أنساني الغناء كله إلا هذا الصوت\n(يا دار إن كان البلى قد محاك ... فإنه يعجبني أن أراك)\n(أبكي الذي قد كان لي مألفا ... فيك فأتي الدار من أجل ذاك)","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":11,"spl":"الواثق أعلم الخلفاء بالغناء","tags":["الحب والغزل"],"loc":1736},
{"id":"b96-17","bab":"الجزء 9","sec":"الواثق أعلم الخلفاء بالغناء","page":"ج9 ص334","text":"الغناء في هذا اللحن للأبجر رمل بالوسطى عن ابن المكي وهو الصواب وذكر عمرو بن بانة أنه لسليم قال فتبينت الكراهية في وجهه وندمت على ما فرط مني وتجلد فشرب رطلا كان في يده وعدلت عن الصوت إلى غيره فكان والله ذلك اليوم آخر جلوسي معه وممن حكي عنه أنه صنع في شعره وشعر غيره المنتصر فإني ذكرت ماروي عنه أنه غنى فيه على سوء العهدة في ذلك وضعف\nالصنعة لئلا يشذ عن الكتاب شيء قد روي وقد تداوله الناس فمما ذكر عنه أنه غنى فيه\n(سقيت كأسا كشفت ... عن ناظري الخمرا)\n(فنشطتني ولقد ... كنت حزينا خاثرا)\nلشعر للمنتصر وهو شعر ضعيف ركيك إلا أنه يغني فيه","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":12,"spl":"الواثق أعلم الخلفاء بالغناء — المنتصر متخلف في قول الشعر","tags":["الخمر","الرواية والكتابة"],"song":1,"loc":1737},
{"id":"b96-18","bab":"الجزء 9","sec":"المنتصر متخلف في قول الشعر","page":"ج9 ص343","text":"وحدثني الصولي عن أحمد بن يزيد المهلبي عن أبيه قال كان طبع المنتصر متخلفا في قول الشعر وكان متقدما في كل شيء غيره فكان إذا قال شعرا صنع فيه وأمر المغنين بإظهاره وكان حسن العلم بالغناء فلما ولي الخلافة قطع ذلك وأمر بستر ما تقدم منه من ذلك صنعته في شعره وهو من الثقيل الأول المذموم\n(سقيت كأسا كشفت ... عن ناظري الخمرا)\nال ومن شعره الذي غنى فيه ولحنه ثاني ثقيل\n(متى ترفع الأيام من قد وضعنه ... وينقاد لي دهر علي جموح)\n(أعلل نفسي بالرجاء وإنني ... لأغدو على ما ساءني وأروح)\nال وكان أبي يستجيد هذين البيتين ويستحسنهما ونذكر هاهنا شيئا من أخبار المنتصر في هذا المعنى دون غيره أسوة ما فعلنا في نظرائه\nأخبرني محمد بن يحيى الصولي قال حدثني محمد بن يحيى بن أبي عباد قال حدثني أبي قال أراد المنتصر أن يشرب في الزقاق فوافى الناس من كل وجه ليروه ويخدموه فوقف على شاطئ دجلة وأقبل على الناس فقال\n(لعمري لقد أصحرت خيلنا ... بأكناف دجلة للملعب)\nالشعر بأكناف دجلة للمصعب ولكنه غيره لأنه تطير من ذكر المصعب\n(فمن يك منا يبت آمنا ... ومن يك من غيرنا يهرب)\nال فعلم أنه يريد الخلوة بالندماء والمغنين فانصرفوا فلم يبق معه إلا من يصلح للأنس والخدمة حدثني الصولي قال حدثني أحمد بن يزيد المهلبي\nقال كان أبي أخص الناس بالمنتصر وكان يجالسه قبل مجالسته المتوكل فدخل المتوكل يوما على المنتصر على غفلة فسمع كلامه فاستحسنه فأخذه إليه وجعله في جلسائه وكان المنتصر يريد منه أن يلازمه كما كان فلم يقدر على ذلك لملازمته أباه فعتب عليه لتأخره عنه على ثقة بمودة وأنس به فلما أفضت إليه الخلافة استأذن عليه فحجبه وأمر بأن يعتقل في الدار فحبس أكثر يومه ثم أذن له فدخل وسلم وقبل الأرض بين يديه ثم قبل يده فأمره بالجلوس ثم التفت إلى بنان ابن عمرو وقال له غن وكان العود في يده\n(غدرت ولم أغدر وخنت ولم أخن ... ورمت بديلا بي ولم أتبدل)\nقال والشعر للمنتصر فغناه بنان وعلم أبي أنه أراده بذلك فقام فقال والله ما اخترت خدمة غيرك ولا صرت إليها إلا بعد إذنك فقال صدقت إنما قلت هذا مازحا أتراني أتجاوز بك حكم الله عز و جل إذ يقول\n(وليس عليكم جناح فيما أخطأتم به ولكن ما تعمدت قلوبكم وكان الله غفورا رحيما ... )\nثم استأذنه في الإنشاد فأذن له فأنشده\n(ألا يا قوم قد برح الخفاء ... وبان الصبر مني والعزاء)\n(تعجب صاحبي لضياع مثلي ... وليس لداء محروم دواء)\n(جفاني سيد قد كان برا ... ولم أذنب فما هذا الجفاء)\n(حللت بداره وعلمت أني ... بدار لا يخيب بها الرجاء)\n(فلما شاب رأسي في ذراه ... حجبت بعقب ما بعد اللقاء)\n(فإن تنأى ستور الإذن عنا ... فما نأت المحبة والثناء)\n(وإن يك كادني ظلما عدو ... فعند البحث ينكشف الغطاء)\n(ألم تر أن بالآفاق منا ... جماجم حشو أقبرها الوفاء)\n(وقد وصف الزمان لنا زياد ... وقال مقالة فيها شفاء)\n(ألا يا رب مغموم سيحظى ... بدولتنا ومسرور يساء)\n(أمنتصر الخلائف جدت فينا ... كما جادت على الأرض السماء)\n(وسعت الناس عدلا فاستقاموا ... بأحكام عليهن الضياء)\n(وليس يفوتنا ما عشت خير ... كفانا أن يطول لك البقاء)\nال فقال له المنتصر والله إنك لمن ذوي ثقتي وموضع اختياري ولك عندي الزلفى فطب نفسا قال ووصلني بثلاثة آلاف دينار","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":12,"spl":"الواثق أعلم الخلفاء بالغناء — المنتصر متخلف في قول الشعر","tags":[],"song":1,"loc":1738,"partial":1},
{"id":"b96-19","bab":"الجزء 9","sec":"من شعر حسين بن الضحاك في المنتصر","page":"ج9 ص346","text":"حدثني الصولي قال حدثني عون بن محمد الكندي قال لما ولي المنتصر الخلافة دخل عليه الحسين بن الضحاك فهنأه بالخلافة وأنشده\n(تجددت الدنيا بملك محمد ... فأهلا وسهلا بالزمان المجدد)\n(هي الدولة الغراء راحت وبكرت ... مشهرة بالرشد في كل مشهد)\n(لعمري لقد شدت عرا الدين بيعة ... أعز بها الرحمن كل موحد)\n(هنتك أمير المؤمنين خلافة ... جمعت بها أهواء أمة أحمد)\nقال فأظهر إكرامه والسرور به وقال له إن في بقائك بهاء للملك وقد ضعفت عن الحركة فكاتبني بحاجاتك ولا تحمل على نفسك بكثرة الحركة ووصله بثلاثة آلاف دينار ليقضي بها دينا بلغة أنه عليه قال وقال الحسين بن الضحاك فيه وقد ركب الظهور وراء الناس وهو آخر شعر قاله\n(ألا ليت شعري أبدر بدا ... نهارا أم الملك المنتصر)\n(إمام تضمن أثوابه ... على سرجه قمرا من بشر)\n(حمى الله دولة سلطانه ... بجند القضاء وجند القدر)\n(فلا زال ما بقيت مدة ... يروح بها الدهر أو يبتكر)\nال وغنى فيه بنان وعريب\nحدثني الصولي قال حدثني أحمد بن يزيد المهلبي قال أول قصيدة أنشدها أبي في المنتصر بعد أن ولي الخلافة\n(ليهنك ملك بالسعادة طائره ... موارده محمودة ومصادره)\n(فأنت الذي كنا نرجي فلم نخب ... كما يرتجى من واقع الغيث باكره)\n(بمنتصر بالله تمت أمورنا ... ومن ينتصر بالله فالله ناصره)\nأمر المنتصر عريب أن تغني نشيدا في أول الأبيات وتجعل البسيط في البيت الأخير فعملته وغنته به حدثني الصولي قال حدثني أحمد بن يزيد قال صلى المنتصر بالناس في الأضحى سنة سبع وأربعين ومائتين فأنشده أبي لما انصرف\n(ما استشرف الناس عيدا مثل عيدهم ... مع الإمام الذي بالله ينتصر)\n(غدا بجمع كجنح الليل يقدمه ... وجه أغر كما يجلو الدجى القمر)\n(يؤمهم صادع بالحق أحكمه ... حزم وعلم بما يأتي وما يذر)\n(لو خير الناس فاختاروا لأنفسهم ... أحظ منك لما نالوه ما قدروا)\nال فأمر له بألف دينار وتقدم إلى ابن المكي أن يغني في الأبيات حدثني الصولي قال حدثني الحسين بن يحيى قال حدثني بنان بن عمرو المغني قال غنيت يوما بين يدي المنتصر\n(هل تطمسون من السماء نجومتها ... بأكفكم أو تسترون هلالها)\nقال لي إياك وأن تغني بحضرتي هذا الصوت وأشباهه فما أحب أن أغنى إلا في أشعار آل أبي حفصة خاصة وممن هذه سبيله في صنعة الغناء المعتز بالله فإني لم أجد له منها شيئا إلا ما ذكره الصولي في أخباره فأتيت بما حكاه\nللعلة التي قدمتها من أني كرهت أن يخل الكتاب بشيء قد دونه الناس وتعارفوه فمما ذكر أنه غنى فيه\n(لعمري لقد أصحرت خيلنا ... بأكناف دجلة للمصعب)\n(فمن يك منا يبت آمنا ... ومن يك من غيرنا يهرب)\nلشعر لعدي بن الرقاع والغناء للمعتز خفيف رمل وهذه الأبيات من قصيدة لعدي يقولها في الوقعة التي كانت بين عبد الملك بن مروان والمصعب ابن الزبير بطسوج مسكن فقتل فيها مصعب بقرية من مسكن يقال لها دير الجاثليق وذكرته الشعراء في هذه الأبيات\n(لعمري لقد أصحرت خيلنا ... بأكناف دجلة للمصعب)\n(يهزون كل طويل القناة ... لدن ومعتدل الثعلب)\n(فداؤك أمي وأبناؤها ... وإن شئت زدت عليها أبي)\n(وما قلتها رهبة إنما ... يحل العقاب على المذنب)\n(إذا شئت نازلت مستقتلا ... أزاحم كالجمل الأجرب)\n(فمن يك منا يبت آمنا ... ومن يك من غيرنا يهرب)","topic":"نسب الأشهب بن رميلة وأخباره","topicNo":96,"sp":13,"spl":"من شعر حسين بن الضحاك في المنتصر","tags":[],"song":1,"loc":1739},
{"id":"b97-1","bab":"الجزء 9","sec":"أخبار عدي بن الرقاع ونسبه","page":"ج9 ص349","text":"هو عدي بن زيد بن مالك بن عدي بن الرقاع بن عصر بن عك بن شعل بن معاوية بن الحارث وهو عاملة بن عدي بن الحارث بن مرة بن أدد وأم معاوية بن الحارث عاملة بنت وديعة من قضاعة وبها سموا عاملة ونسبه الناس إلى الرقاع وهو جد جده لشهرته أخبرني بذلك أبو خليفة عن محمد بن سلام","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":0,"spl":"أخبار عدي بن الرقاع ونسبه","tags":["الجواري والنساء"],"loc":1740},
{"id":"b97-2","bab":"الجزء 9","sec":"طبقته بين الشعراء","page":"ج9 ص350","text":"وكان شاعرا مقدما عند بني أمية مداحا لهم خاصا بالوليد بن عبد الملك وله بنت شاعرة يقال لها سلمى ذكر ذلك ابن النطاح وجعله محمد بن سلام في الطبقة الثالثة من شعراء الإسلام وكان منزله بدمشق وهو من حاضرة الشعراء لا من باديتهم وقد تعرض لجرير وناقضه في مجلس الوليد بن عبد الملك ثم لم تتم بينهما مهاجاة إلا أن جريرا قد هجاه تعريضا في قصيدته\n(حي الهدملة من ذات المواعيس ... )\nولم يصرح لأن الوليد حلف إن هو هجاه أسرجه وألجمه وحمله على ظهره فلم يصرح بهجائه أخبرني أبو خليفة إجازة قال حدثنا محمد بن سلام قال أخبرني أبو الغراف\nقال دخل جرير على الوليد بن عبد الملك وهو خليفة وعنده عدي بن الرقاع العاملي فقال الوليد لجرير أتعرف هذا قال لا يا أمير المؤمنين فقال الوليد هذا عدي بن الرقاع فقال جرير فشر الثياب الرقاع قال ممن هو قال العاملي فقال جرير هي التي يقول فيها الله عز و جل ( عاملة ناصبة تصلى نارا حامية\nثم قال\n(يقصر باع العاملي عن الندى ... ولكن أير العماملي طويل)\nقال له عدي بن الرقاع\n(أأمك كانت أخبرتك بطوله ... أم أنت امرؤ لم تدر كيف تقول)\nقال لا بل أدري كيف أقول فوثب العاملي إلى رجل الوليد فقبلها وقال أجرني منه فقال الوليد لجرير لئن شتمته لأسرجنك ولألجمنك حتى يركبك فيعيرك الشعراء بذلك فكنى جرير عن اسمه فقال\n(إني إذا الشاعر المغرور حربني ... جار لقبر على مران مرموس)\n(قد كان أشوس آباء فورثنا ... شغبا على الناس في أبنائه الشوس)\n(أقصر فإن نزارا لن يفاضلها ... فرع لئيم وأصل غير مغروس)\n(وابن اللبون إذا ما لز في قرن ... لم يستطع صولة البزل القناعيس)\nخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال قال أبو عبيدة دخل جرير على الوليد بن عبد الملك وعنده عدي بن الرقاع العاملي فقال له الوليد أتعرف هذا قال لا فمن هو قال هذا ابن الرقاع قال فشر الثياب الرقاع فممن هو قال من عاملة قال أمن التي قال الله تعالى فيها ( عاملة ناصبة تصلى نارا حامية\nفقال الوليد والله ليركبنك لشاعرنا ومادحنا والراثي لأمواتنا تقول هذه المقالة يا غلام علي بإكاف ولجام فقام إليه عمر بن الوليد فسأله أن يعفيه فأعفاه فقال والله لئن هجوته لأفعلن ولأفعلن فلم يصرح بهجائه وعرض فقال قصيدته التي أوليها\n(حي الهدملة من ذات المواعيس ... )\nقال فيها يعرض به\n(قد جربت عركتي في كل معترك ... غلب الأسود فما بال الضغابيس)\nخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال حدثني سليمان بن عياش السعدي قال ذكر كثير وعدي بن الرقاع العاملي في مجلس بعض خلفاء بني أمية فامتروا فيهما أيهما أشعر وفي المجلس جرير فقال جرير لقد قال كثير بيتا هو أشهر وأعرف في الناس من عدي بن الرقاع نفسه ثم أنشد قول كثير\n(أأن زم أجمال وفارق جيرة ... وصاح غراب البين أنت حزين)\nال فحلف الخليفة لئن كان عدي بن الرقاع أعرف في الناس من بيت كثير ليسرجن جريرا وليلجمنه وليركبن عدي بن الرقاع على ظهره فكتب إلى واليه بالمدينة إذا فرغت من خطبتك فسل الناس من الذي يقول\n(أأن زم أجمال وفارق جيرة ... وصاح غراب البين أنت حزين)\nعن نسب ابن الرقاع فلما فرغ الوالي من خطبته قال إن أمير المؤمنين كتب إلي أن أسألكم من الذي يقول\n(أأن زم أجمال وفارق جيرة ... )\nال فابتدروا من كل وجه يقولون كثير كثير ثم قال وأمرني أن أسأل عن نسب ابن الرقاع فقالوا لا ندري حتى قام أعرابي من مؤخر المسجد فقال هو من عاملة أخبرني يحيى بن علي بن يحيى عن أبيه قال قال لي محمد بن المنجم ما أحد ذكر لي فأحببت أن أراه فإذا رأيته أمرت بصفعه إلا عدي بن الرقاع قلت ولم ذلك قال لقوله\n(وعلمت حتى ما أسائل عالما ... عن علم واحدة لكي أزدادها)\nفكنت أعرض عليه أصناف العلوم فكلما مر به شيء لا يحسنه أمرت بصفعه حدثني إبراهيم بن محمد بن أيوب قال حدثنا عبد الله بن مسلم قال\nكان عدي بن الرقاع ينزل بالشام وكانت له بنت تقول الشعر فأتاه ناس من الشعراء ليماتنوه وكان غائبا فسمعت بنته وهي صغيرة لم تبلغ دور وعيدهم فخرجت إليهم وأنشأت تقول\n(تجمعتم من كل أوب وبلدة ... على واحد لا زلتم قرن واحد)\nأفحمتهم","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":1,"spl":"طبقته بين الشعراء","tags":["الهجاء"],"loc":1741,"partialRef":{"sid":"b74-8","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b97-3","bab":"الجزء 9","sec":"عدي بن الرقاع شاعر المطية","page":"ج9 ص354","text":"وقال عبد الله بن مسلم وما ينفرد به ويقدم فيه وصف المطية فإنه كان من أوصف الشعراء لها حدثني أحمد بن عبيد الله بن عمار قال حدثنا محمد بن عباد بن موسى قال كنت عند أبي عمرو أعرض أو يعرض عليه رجل بحضرتي من شعر عدي ابن الرقاع وقرأت أو قرأ هذه الأبيات\n(لولا الحياء وأن رأسي قد عسا ... فيه المشيب لزرت أم القاسم)\n(وكأنها وسط النساء أعارها ... عينيه أحور من جآذر جاسم)\n(وسنان أقصده النعاس فرنقت ... في عينه سنة وليس بنائم)\nقال أبو عمرو أحسن والله فقال رجل كان يحضر مجلسه أعرابي كأنه مدني أما والله لو رأيته مشبوحا بين أربعة وقضبان الدفلى تأخذه لكنت أشد له استحسانا يعني إذا كان يغنى به على العود أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني عبد الله بن أبي سعد عن علي بن المغيرة قال\nكان أبو عبيدة يستحسن بيت عدي بن الرقاع\n(وسنان أقصده النعاس فرنقت ... في عينه سنة وليس بنائم)\nدا ويقول ما قال أحد في مثل هذا المعنى أحسن منه في هذا الشعر وفي هذا الشعر غناء نسبته\n(لولا الحياء وأن رأسي قد عسا ... فيه المشيب لزرت أم القاسم)\n(وكأنها وسط النساء أعارها ... عينيه أحور من جآذر جاسم)\n(وسنان أقصده النعاس فرنقت ... في عينه سنة وليس بنائم)\n(ألمم على طلل عفا متقادم ... بين الذؤيب وبين غيب الناعم)\nعروضه من الكامل الجآذر جمع جؤذر وهي أولاد البقر الوحشية وجاسم موضع ويروى في هذا الشعر عاسم مكان جاسم والوسنان النائم والوسن النوم الواحدة منه سنة والترنيق الدنو من الشيء يريد أن يفعله يقال رنقت العقاب لصيدها إذا دنت منه وترنيقها أيضا أن تقصر عن الخفقان بجناحيها ويقال طير مرنقة إذا جاءت تطير ثم أرادت الوقوع ومدت أجنحتها فلم تخفق وترجحت ويقال للقوم إذا قصروا في سيرهم وللسابح إذا قصر في الخفق بيديه ورجليه قد رنقوا ترنيقا الشعر لعدي بن الرقاع والغناء لابن مسجح خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وفيه ثقيل أول بالبنصر ينسب إليه أيضا\nوذكر الهشامي أنه من منحول يحيى بن المكي إليه أخبرني محمد بن يحيى الصولي قال حدثني محمد بن عبد الله المعروف بالحزنبل عن عمرو بن أبي عمرو قال\nكنت عند أبي ورجل يقرأ عليه شعر عدي بن الرقاع فلما قرأ عليه القصيدة التي يقول فيها\n(لولا الحياء وأن رأسي قد عسا ... فيه المشيب لزرت أم القاسم)\nال أبي أحسن والله عدي بن الرقاع قال وعنده شيخ مدني جالس فقال الشيخ والله لئن كان عدي أحسن لما أساء أبو عباد قال أبي ومن هو أبو عباد\nقال معبد والله لو سمعت لحنه في هذا الشعر لكان طربك أشد واستحسانك له أكثر فجعل أبي يضحك أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن جرير عن محمد بن سلام\nقال عزل الوليد بن عبد الملك عبيدة بن عبد الرحمن عن الأردن وضربه وحلقه وأقامه للناس وقال للمتوكلين به من أتاه متوجعا وأثنى عليه فأتوني به فأتى عدي بن الرقاع وكان عبيدة إليه محسنا فوقف عليه وأنشأ يقول\n(فما عزلوك مسبوقا ولكن ... إلى الخيرات سباقا جوادا)\n(وكنت أخي وما ولدتك أمي ... وصولا باذلا لي مسترادا)\n(وقد هيضت لنكبتك القدامى ... كذاك الله يفعل ما أراد)\nوثب المتوكلون به إليه فأدخلوه إلى الوليد وأخبروه بما جرى فتغيظ عليه الوليد وقال له أتمدح رجلا قد فعلت به ما فعلت فقال يا أمير المؤمنين إنه كان إلي محسنا ولي مؤثرا وبي برا ففي أي وقت كنت أكافئه بعد هذا اليوم فقال صدقت وكرمت فقد عفوت عنك وعنه لك فخذه وانصرف فانصرف به إلى منزله","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":2,"spl":"عدي بن الرقاع شاعر المطية","tags":[],"song":1,"loc":1742},
{"id":"b97-4","bab":"الجزء 9","sec":"رأي جرير فيه","page":"ج9 ص356","text":"أخبرني محمد بن القاسم الأنباري قال حدثني أحمد بن يحيى ثعلب قال قال نوح بن جرير لأبيه يا أبت من أنسب الشعراء قال له أتعني ما\nقلت قال إني لست أريد من شعرك إنما أريد من شعر غيرك قال ابن الرقاع في قوله\n(لولا الحياء وأن رأسي قد عسا ... فيه المشيب لزرت أم القاسم)\nلثلاثة الأبيات ثم قال لي ما كان يبالي أن لم يقل بعدها شيئا أخبرني الحسن بن علي عن هارون بن محمد بن عبد الملك عن أحمد بن الحارث الخراز عن المدائني قال قال جرير سمعت عدي بن الرقاع ينشد\n(تزجي أغن كأن إبرة روقه ... )\nرحمته من هذا التشبيه فقلت بأي شيء يشبهه ترى فلما قال\n(قلم أصاب من الدواة مدادها ... )\nحمت نفسي منه أخبرني اليزيدي قال حدثني عمي عبيد الله عن ابن حبيب عن أبي عبيدة قال مال روح بن زنباع الجذامي إلى يزيد بن معاوية لما فصل بين الخطبتين فقال يا أمير المؤمنين ألحقنا بإخوتنا من معد فإنا معديون والله ما نحن من قصب الشأم و من زعاف اليمن فقال يزيد إن أجمع قومك على ذلك جعلناك حيث شئت فبلغ ذلك عدي بن الرقاع فقال\n(إنا رضينا وإن غابت جماعتنا ... ما قال سيدنا روح بن زنباع)\n(يرعى ثمانين ألفا كان مثلهم ... مما يخالف أحيانا على الراعي)\nال فبلغ ناتل بن قيس الجذامي فجاء يركض فرسه حتى دخل\nالمقصورة في الجمعة الثانية فلما قام يزيد على المنبر وثب فقال أين الغادر الكاذب روح بن زنباع فأشاروا إلى مجلسه فأقبل عليه وعلى يزيد ثم قال يا أمير المؤمنين قد بلغني ما قال لك هذا وما نعرف شيئا منه ولا نقر به ولكنا قوم من قحطان يسعنا ما يسعهم ويعجز عنا ما يعجز عنهم فأمسك روح ورجع عن رأيه فقال عدي بن الرقاع في ذلك\n(أضلال ليل ساقط أكنافه ... في الناس أعذر أم ضلال نهار)\n(قحطان والدنا الذي ندعى له ... وأبو خزيمة خندف بن نزار)\n(أنبيع والدنا الذي ندعى له ... بأبي معاشر غائب متواري)\n(تلك التجارة لا زكاء لمثلها ... ذهب يباع بآنك وإبار)\nفقال له يزيد غيرت يابن الرقاع قال إن ناتلا والله علي أعزهما سخطا وأنصحهما لي ولعشيرتي قال أبو عبيدة الإبار جمع إبرة","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":3,"spl":"رأي جرير فيه","tags":[],"loc":1743,"partial":1},
{"id":"b97-5","bab":"الجزء 9","sec":"عدي بن الرقاع وابن سريج في حضرة الوليد","page":"ج9 ص358","text":"أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن جده إبراهيم أن الأحوص وابن سريج قدما المدينة فنزلا في بعض الخانات ليصلحا من شأنهما وقد قدم عدي بن الرقاع وكانت هذه حاله فنزل عليهما فلماكان في بعض الليل أفاضوا في الأحاديث فقال عدي بن الرقاع لابن سريج والله لخروجنا كان إلى أمير المؤمنين أجدى علينا من المقام معك يا مولى بن نوفل قال وكيف ذلك قال لأنك توشك أن تلهينا فتشغلنا عما قصدنا له فقال له ابن سريج أو قلة شكر أيضا فغضب عدي وقال إنك لتمن علينا أن نزلنا\nعليك وإني أعاهد الله ألا يظلني وإياك سقف إلا أن يكون بحضرة أمير المؤمنين وخرج من عندهما وقدم الوليد من باديته فأذن لهما فدخلا وبلغه خبر ابن الرقاع وماجرى بينه وبين ابن سريج فأمر بابن سريج فأخفي في بيت ودعا بعدي فأدخله فأنشده قصيدة امتدحه بها فلما فرغ أومأ إلى بعض الخدم فأمر ابن سريج فغنى في شعر عدي بن الرقاع يمدح الوليد\n(عرف الديار توهما فاعتادها ... من بعد ما شمل البلى أبلادها)\nطرب عدي وقال لا والله ما سمعت يا أمير المؤمنين بمثل هذا قط ولا ظننت أن يكون مثله طيبا وحسنا ولولا أنه في مجلس أمير المؤمنين لقلت طائف من الجن أيأذن لي أمير المؤمنين أن أقول\nقال قل قال مثل هذا عند أمير المؤمنين وهو يبعث إلى ابن سريج يتخطى به قبائل العرب فيقال ابن سريج المغني مولى بني نوفل بعث أمير المؤمنين إليه فضحك ثم\nقال للخادم أخرجه فخرج فلما رآه عدي أطرق خجلا ثم قال المعذرة إلى الله وإليك يا أخي فما ظننت أنك بهذه المنزلة وإنك لحقيق أن تحتمل على كل هفوة وخطيئة فأمر لهم الوليد بمال سوى بينهم فيه ونادمهم يومئذ إلى الليل نسبة هذا الصوت المذكور في هذا الخبر وسائر ما مضى في أخبار عدي قبله من الأشعار التي فيها غناء\n(عرف الديار توهما فاعتادها ... من بعد ما شمل البلى أبلادها)\n(إلا رواكد كلهن قد اصطلى ... حمراء أشعل أهلها إيقادها)\nروضه من الكامل الشعر لعدي بن الرقاع والغناء لابن محرز خفيف ثقيل أول بإطلاق الوتر في مجرى البنصر عن إسحاق\nأخبرني عيسى بن الحسين الوراق قال حدثني أحمد بن الهيثم بن فراس قال حدثني العمري عن الهيثم بن عدي قال أنشد عدي بن الرقاع الوليد بن عبد الملك قصيدته التي أولها\n(عرف الديار توهما فاعتادها ... )\nعنده كثير وقد كان يبلغه عن عدي أنه يطعن على شعره ويقول هذا شعر حجازي مقرور إذا أصابه قر الشأم جمد وهلك فأنشده إياها حتى أتى على قوله\n(وقصيدة قد بت أجمع بينها ... حتى أقوم ميلها وسنادها)\nقال له كثير لو كنت مطبوعا أو فصيحا أو عالما لم تأت فيها بميل ولا سناد فتحتاج إلى أن تقومها ثم أنشد\n(نظر المثقف في كعوب قناته ... حتى يقيم ثقافه منآدها)\nقال له كثير لا جرم أن الأيام إذا تطاولت عليها عادت عوجاء ولأن تكون مستقيمة لا تحتاج إلى ثقاف أجود لها ثم أنشد\n(وعلمت حتى ما أسائل واحدا ... عن علم واحدة لكي أزدادها)\nقال كثير كذبت ورب البيت الحرام فليمتحنك أمير المؤمنين بأن يسألك عن صغار الأمور دون كبارها حتى يتبين جهلك وما كنت قط أحمق منك الآن حيث تظن هذا بنفسك فضحك الوليد ومن حضر وقطع بعدي بن الرقاع حتى ما نطق","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":4,"spl":"عدي بن الرقاع وابن سريج في حضرة الوليد","tags":["المديح"],"song":1,"loc":1744,"partialRef":{"sid":"b3-34","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b97-6","bab":"الجزء 9","sec":"أخبار المعتز في الأغاني ومع المغنين وما جرى هذا المجرى","page":"ج9 ص361","text":"حدثني محمد بني يحيى الصولي قال حدثني علي بن محمد بن نصر قال حدثني جدي حمدون بن إسماعيل قال اصطبح المعتز في يوم ثلاثاء ونحن بين يديه ثم وثب فدخل واعترضته جارية كان يحبها ولم يكن ذلك اليوم من أيامها فقبلها وخرج فحدثني بما كان وأنشدني لنفسه في ذلك\n(إني قمرتك يا سؤلي ويا أملي ... أمرا مطاعا بلا مطل ولا علل)\n(حتى متى يا حبيب النفس تمطلني ... وقد قمرتك مرات فلم تف لي)\n(يوم الثلاثاء يوم سوف أشكره ... إذ زارني فيه من أهوى على عجل)\n(فلم أنل منه شيئا غير قبلته ... وكان ذلك عندي أعظم النفل)\nال وعمل فيه لحن خفيف وشربنا عليه سائر يومنا الغناء في هذه الأبيات لعريب رمل عن الهشامي ولأبي العبيس في الثالث والرابع هزج أخبرني محمد بن يحيى الصولي قال حدثني أحمد بن يزيد المهلبي قال حدثني أبي قال\nكان المعتز يشرب على بستان مملوء من النمام وبين النمام شقائق النعمان فدخل إليه يونس بن بغا وعليه قباء أخضر فقال المعتز\n(شبهت حمرة خده في ثوبه ... بشقائق النعمان في النمام)\nثم قال أجيزوا فابتدر بنان المغني وكان ربما عبث بالبيت بعد البيت فقال\n(والقد منه إذا بدا في قرطق ... كالغصن في لين وحسن قوام)\nقال له المعتز فغن فيه الآن فعمل فيه لحنا لحن بنان في هذين البيتين من خفيف الثقيل الثاني وهو الماخوري أخبرني محمد بن يحيى قال حدثني محمد بن يحيى بن أبي عباد\nقال حدثني عمر بن محمد بن عبد الملك قال شرب المعتز ويونس بن بغا بين يديه يسقيه والجلساء والمغنون بين يديه وقد أعد الخلع والجوائز إذ دخل بغا فقال يا أمير المؤمنين والدة عبدك يونس في الموت وهي تحب أن تراه فأذن له فخرج وفتر المعتز ونعس بعده وقام الجلساء وتفرق المغنون إلى أن صليت المغرب وعاد المعتز إلى مجلسه ودخل يونس وبين يديه الشموع فلما رآه المعتز دعا برطل فشربه وسقى يونس رطلا وغناه المغنون وعاد المجلس أحسن ما كان فقال المعتز\n(تغيب فلا أفرح ... فليتك ما تبرح)\n(وإن جئت عذبتني ... بأنك لا تسمح)\n(فأصحبت ما بين ذين ... لي كبد تجرح)\n(على ذاك يا سيدي ... دنوك لي أصلح)\nم قال غنوا فيه فجعلوا يفكرون فقال المعتز لسليمان بن القصار الطنبوري ويلك ألحان الطنبور أملح وأخف فغن فيه أنت فغنى فيه لحنا فدفع إليه دنانير الخريطة وهي مائة دينار مكية ومائتان مكتوب على كل دينار منها ضرب هذا الدينار بالجوسق بخريطة أمير المؤمنين المعتز بالله ثم دعا بالخلع والجوائز لسائر الناس فكان ذبلك المجلس من أحسن المجالس لحن سليمان بن القصار في هذه الأبيات رمل مطلق\nحدثني الصولي قال حدثني محمد بن عبد السميع الهاشمي قال حدثني أبي قال لما قتل بغا دخلنا فهنأنا المعتز بالظفر فاصطبح ومعه يونس بن بغا وما رأينا قط وجهين اجتمعا أحسن من وجهيهما فما مضت ثلاث ساعات حتى سكر ثم خرج علينا المعتز فقال\n(ما إن ترى منظرا إن شئته حسنا ... إلا صريعا يهادى بين سكرين)\n(سكر الشراب وسكر من هوى رشأ ... تخاله والذي يهواه عصنين)\nثم أمر فتغنى فيه بعض المغنين حدثني الصولي قال حدثني أحمد بن محمد بن إسحاق الخراساني قال حدثني الفضل بن العباس بن المأمون قال كنت مع المعتز في الصيد فانقطع عن الموكب وأنا ويونس بن بغا معه ونحن بقرب قنطرة وصيف وكان هناك دير فيه ديراني يعرفني وأعرفه نظيف ظريف مليح الأدب واللفظ فشكا المعتز العطش فقلت يا أمير المؤمنين في هذا الدير ديراني أعرفه خفيف الروح لا يخلو من ماء بارد أفترى أن نميل إليه\nقال نعم فجئناه فأخرج لنا ماء باردا وسألني عن المعتز ويونس فقلت فتيان من أبناء الجند فقال بل مفلتان من حور الجنة فقلت له هذا ليس في دينك فقال هو الآن في ديني فضحك المعتز فقال لي الديراني أتأكلون شيئا","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":5,"spl":"أخبار المعتز في الأغاني ومع المغنين وما جرى هذا المجرى","tags":[],"song":3,"loc":1745},
{"id":"b97-8","bab":"الجزء 9","sec":"أخبار المعتز في الأغاني ومع المغنين وما جرى هذا المجرى — ولي الخلافة وهو صغير","page":"ج9 ص361 – ج9 ص365","text":"قلت نعم فأخرج شطيرات وخبزا وإداما نظيفا فأكلنا أطيب أكل وجاءنا بأطراف أشنان فاستظرفه المعتز وقال لي قل له فيما بينك وبينه من تحب أن يكون معك من هذين لا يفارقك فقلت له فقال كلاهما وتمرا فضحك المعتز حتى مال على حائط الدير فقلت للديراني لا بد من أن تختار فقال الاختيار والله في هذا دمار وماخلق الله عقلا يميز بين هذين ولحقهما الموكب فارتاع الديراني فقال له المعتز بحياتي لا تنقطع عما كنا فيه فإني لمن ثم مولى ولمن هاهنا صديق فمزحنا ساعة ثم أمر له بخمسمائة ألف درهم فقال والله ما أقبلها إلا على شرط\nقال وما هو قال يجيب أمير المؤمنين دعوتي مع من أراد قال ذلك لك فأتعدنا ليوم جئناه فيه فلم يبق غاية وأقام للموكب كله ما احتاج إليه وجاءنا بأولاد النصارى يخدموننا ووصله المعتز يومئذ صلة سنية ولم يزل يعتاده ويقيم عنده\nحدثني الصولي قال حدثنا عبد الله بن المعتز قال بويع للمعتز بالخلافة وله سبع عشرة سنة كاملة وأشهر فلما انقضت البيعة قال\n(توحدك الرحمن بالعز والعلا ... فأنت على كل الأنام أمير)\nكذا ذكر الصولي في قافية الشعر ووجدته في أغاني بنان مرفوع القافية وله فيه صنعة ولعل المعتز قال البيت فأضاف بنان إليه آخر وجعل المخاطبة عن نفسه للمعتز فقال\n(توحدني الرحمن بالعز والعلا ... فأصبحت فوق العالمين أميرا)\n(تقاتل عنك الترك والخزر كلها ... كأنهم أسد لهن زئير)\nلغناء لبنان لحنان خفيف ثقيل وخفيف رمل ومما قاله المعتز وغنى فيه قوله ذكر الصولي أن عبد الله بن المعتز أنشده إياه لأبيه\n(ألا حي الحبيب فدته نفسي ... بكأس من مدامة خانقينا)\n(فإني قد بقيت مع الليالي ... أقاسي الهم في يده سنينا)\nلغناء فيه لعريب خفيف رمل ولبنان هزج\nوممن ذكر أن له صنعة من الخلفاء المعتمد قال محمد بن يحيى الصولي ذكر عبد الله بن المعتز عن القاسم بن زرزور أن المعتمد ألقى عليه لحنا صنعه في هذا الشعر وهو\n(ليس الشفيع الذي يأتيك مؤتزرا ... مثل الشفيع الذي يأتيك عريانا)\nلشعر للفرزدق والغناء للمعتمد ولحنه فيه خفيف ثقيل هذه حكاية الصولي وفي غناء عريب لها في هذا البيت خفيف ثقيل ولا أعلم لمن هو منهما على صحة إلا أن المشهور في أيدي الناس أنه لعريب ولم اسمع للمعتمد غناء إلا من هذه الجهة التي ذكرتها","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":6,"spl":"أخبار المعتز في الأغاني ومع المغنين وما جرى هذا المجرى — ولي الخلافة وهو صغير","tags":["الحب والغزل"],"song":2,"loc":1746},
{"id":"b97-9","bab":"الجزء 9","sec":"ذكر أخبار الفرزدق في هذا الشعر خاصة دون غيره","page":"ج9 ص367","text":"لأن أخباره كثيرة جدا فكرهت أن أثبتها هاهنا في غناء مشكوك فيه فذكرت نسبه وخبره في هذا الشعر خاصة وأخباره تأتي بعد هذا في موضع مفرد يتسع لطول أحاديثه الفرزدق لقب غلب عليه واسمه همام بن غالب بن صعصعة بن ناجية بن عقال بن محمد بن سفيان بن مجاشع بن دارم بن مالك بن حنظلة ابن مالك بن زيد مناة بن تميم وهو وجرير والأخطل أشعر طبقات الإسلاميين والمقدم في الطبقة الأولى منهم وأخباره تذكر مفردة في موضع آخر يتسع لها ونذكر هاهنا خبره في هذا المعنى فأخبرني خبره في ذلك جماعة فممن\nأخبرني به أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة وأخبرني به أبو خليفة إجازة عن محمد بن سلام وأخبرني به محمد بن العباس اليزيدي عن السكري عن محمد بن حبيب عن أبي عبيدة وابن الأعرابي\nقال عمر بن شبة خاصة في خبره حدثني محمد بن يحيى قال حدثني أبي أن عبد الله بن الزبير تزوج تماضر بنت منظور بن زبان وأمها مليكة بنت خارجة بن سنان بن أبي حارثة فخاصم الفرزدق امرأته النوار إلى ابن الزبير هكذا ذكر محمد بن يحيى ولم يذكر السبب في الخصومة وذكرها عمر بن شبة ولم يروها عن أحد وذكرها ابن حبيب عن أصحابه وذكرها\nأبو غسان دماذ عن أبي عبيدة أن رجلا من بني أمية خطب النوار بنت أعين المجاشعية فرضيته وجعلت أمرها إلى الفرزدق فقال لها أشهدي لي بذلك على نفسك شهودا ففعلت واجتمع الناس لذلك فتكلم الفرزدق ثم قال اشهدوا أني قد تزوجتها وأصدقتها كذا وكذا فأنا ابن عمها وأحق بها فبلغ ذلك النوار فأبته واستترت من الفرزدق وجزعت ولجأت إلى بني قيس بن عاصم المنقري فقال فيها\n(بني عاصم لا تلجئوها فإنكم ... ملاجيء للسوءات دسم العمائم)\n(بني عاصم لو كان حيا أبوكم ... للام بنيه اليوم قيس بن عاصم)\nقالوا والله لئن زدت على هذين البيتين لنقتلنك غيلة فنافرته إلى عبد الله بن الزبير وأرادت الخروج إليه فتحامى الناس كراءها ثم إن رجلا من بني عدي يقال له زهير بن ثعلبة وقوما يعرفون ببني أم النسير أكروها فقال الفرزدق\n(ولولا أن تقول بنو عدي ... أليست أم حنظلة النوار)\n(أتتكم يا بني ملكان عني ... قواف لا تقسمها التجار)\nعني بالنوار هاهنا بنت جل بن عدي بن عبد مناة وهي أم حنظلة بن مالك بن زيد مناة وهي إحدى جداته وقال فيها أيضا\n(سرى بالنوار عوهجي يسوقه ... عبيد قصير الشبر نائي الأقارب)\n(تؤم بلاد الأمن دائبة السرى ... إلى خير وال من لؤي بن غالب)\n(فدونك عرسي تبتغي نقض عقدتي ... وإبطال حقي باليمين الكواذب)\nوقال أيضا\n(ولولا أن أمي من عدي ... وأني كاره سخط الرباب)\n(إذا لأتى الدواهي من قريب ... جزاء غير منصرف العقاب)\n(وصلت على بني ملكان مني ... بجيش غير منتظر الإياب)\nقال لزهير أيضا\n(لبئس العبء يحمله زهير ... على أعجاز صرمته نوار)\n(لقد أهدت وليدتنا إليكم ... عوائر لا تقسمها التجار)\nوقال لبني أم النسير\n(لعمري لقد أردى النوار وساقها ... إلى الغور أحلام خفاف عقولها)\n(أطاعت بني أم النسير فأصبحت ... على قتب يعلو الفلاة دليلها)\n(وقد سخطت مني النوار الذي ارتضى ... به قبلها الأزواج خباب رحيلها)\n(وإن امرأ أمسى تحبب زوجتي ... كماش إلى أسد الشرى يستبيلها)\n(ومن دون أبوال الأسود بسالة ... وبسطة أيد يمنع الضيم طولها)\n(وإن أمير المؤمنين لعالم ... بتأويل ما أوصى العباد رسولها)\n(فدونكها يابن الزبير فإنها ... مولعة يوهي الحجارة قيلها)\nلما قدمت مكة نزلت على بنت منظور بن زبان واستشفعت بها إلى\nزوجها عبد الله وانضم الفرزدق إلى حمزة بن عبد الله بن الزبير وأمه بنت منظور هذه ومدحه فقال\n(أصبحت قد نزلت بحمزة حاجتي ... إن المنوه باسمه الموثوق)\nلأبيات وقال فيه أيضا\n(يا حمز هل لك في ذي حاجة غرضت ... أنضاؤه بمكان غير ممطور)\n(فأنت أحرى قريش أن تكون لها ... وأنت بين أبي بكر ومنظور)\n(بين الحواري والصديق في شعب ... نبتن في طيب الإسلام والخير)\nذه الأبيات كلها من رواية أبي زيد خاصة قالوا جميعا وقال في النوار\n(هلمي لابن عمك لا تكوني ... كمختار على الفرس الحمارا)\nقال فيها أيضا\n(تخاصمني النوار وغاب فيها ... كرأس الضب يلتمس الجرادا)\nال أبو زيد في خبره خاصة فجعل أمر الفرزدق يضعف وأمر النوار يقوى وقال الفرزدق\n(أما بنوه فلم تقبل شفاعتهم ... وشفعت بنت منظور بن زبانا)\n","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":7,"spl":"ذكر أخبار الفرزدق في هذا الشعر خاصة دون غيره","tags":["المديح"],"song":1,"loc":1747},
{"id":"b97-10","bab":"الجزء 9","sec":"ذكر أخبار الفرزدق في هذا الشعر خاصة دون غيره","page":"ج9 ص367","text":"(ليس الشفيع الذي يأتيك مؤتزرا ... مثل الشفيع الذي يأتيك عريانا)\nغنت في هذا البيت عريب خفيف ثقيل أول بالبنصر فبلغ ابن الزبير هذا فدعا النوار فقال إن شئت فرقت بينكما وقتلته فلا يهجونا أبدا وإن شئت سيرته إلى بلاد العدو فقالت ما أريد واحدة منهما\nقال فإنه ابن عمك وهو فيك راغب أفأزوجه إياك قالت نعم فزوجه إياها فكان الفرزدق يقول خرجنا متباغضين ورجعنا متحابين أخبرني أحمد قال حدثني عمر بن شبة\nقال قال عثمان بن سليمان شهدت الفرزدق يوم نازع النوار فتوجه القضاء عليه فأشفق من ذلك وتعرض لابن الزبير بكلام أغضبه وكان ابن الزبير حديدا فقال له ابن الزبير أيا ألأم الناس وهل أنت وقومك إلا جالية العرب وأمر به فأقيم وأقبل علينا فقال إن بني تميم كانوا وثبوا على البيت قبل الإسلام بمائة وخمسين سنة فاستلبوه وأجمعت العرب عليها لما انتهكت ما لم ينتهكه أحد قط فأجلتها من أرض تهامة فلما كان في طائفة من ذلك اليوم لقيني الفرزدق فقال هيه أيعيرنا ابن الزبير جلاءنا عن البيت اسمع ثم قال\n(فإن تغضب قريش ثم تغضب ... فإن الأرض ترعاها تميم)\n(هم عدد النجوم وكل حي ... سواهم لا تعد لهم نجوم)\n(فلولا بنت مر من نزار ... لما صح المنابت والأديم)\n(بها كثر العديد وطاب منكم ... وغيركم أحذ الريش هيم)\n(فمهلا عن تذلل من عززتم ... بخولته وعز به الحميم)\n(أعبد الله مهلا عن أذاتي ... فإني لا الضعيف ولا السؤوم)\n(ولكني صفاة لم تؤبس ... تزل الطير عنها والعصوم)\n(أنا ابن العاقر الخور الصفايا ... بصوأر حيث فتحت العكوم)\nذكر الزبير بن بكار عن عمه أن عبد الله بن الزبير لما حكم على الفرزدق قال إنما حكمت علي بهذا لأفارقها فتثب عليها وأمر به فأقيم وقال له ما قال في بني تميم قال ثم خرج عبد الله بن الزبير إلى المسجد فرأى الفرزدق في بعض طرق مكة وقد بلغته أبياته التي قالها فقبض ابن الزبير على عنقه فكاد يدقها ثم قال\n(لقد أصبحت عرس الفرزدق ناشزا ... ولو رضيت رمح استه لاستقرت)\nال الزبير وهذا الشعر لجعفر بن الزبير أخبرنا أبو خليفة قال أخبرنا ابن سلام قال أخبرنا إبراهيم بن حبيب الشهيد قال قال ابن الزبير للفرزدق ما حاجتك بها وقد كرهتك كن لها أكره وخل سبيلها فخرج وهو يقول ما أمرني بطلاقها إلا ليثب عليها فبلغ ذلك ابن الزبير فخرج وقد استهل هلال ذي الحجة ولبس ثياب الإحرام يريد البيت الحرام فألفى الفرزدق بباب المسجد عند الباعة فأخذ بعنقه فغمزها حتى جعل رأسه بين ركبتيه وقال\n(لقد أصبحت عرس الفرزدق ناشزا ... ولو رضيت رمح استه لاستقرت)\nال الزبير وهذا البيت لجعفر بن الزبير أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة عن محمد بن يحيى عن أبيه قال لما قال الفرزدق في ابن الزبير\n(أما بنوه فلم تقبل شفاعتهم ... وشفعت بنت منظور بن زبانا)\nال جعفر بن الزبير\n(ألا تلكم عرس الفرزدق جامحا ... ولو رضيت رمح استه لاستقرت)\nقال عبد الله بن الزبير أتجزرنا كلبا من كلاب بني تميم لئن عدت لم أكلمك أبدا قال وتماضر التي عناها الفرزدق أم خبيب وثابت ابني عبد الله بن الزبير وماتت عند عبد الله فتزوج أختها أم هاشم فولدت له هاشما وحمزة وعبادا قال وفي أم هاشم يقول الفرزدق يستعينها على ابن الزبير ويشكو طول مقامه\n(تروحت الركبان يا أم هاشم ... وهن مناخات لهن حنين)\n(وخيسن حتى ليس فيهن نافق ... لبيع ولا مركوبهن سمين)\nال وهذا يدل على أن النوار كانت استعانت بأم هاشم لا بتماضر فلما أذنت النوار لعبد الله في تزويجها بالفرزدق حكم لها عليه بمهر\nمثلها عشرة آلاف درهم فسأل هل بمكة أحد يعينه فدل على سلم بن زياد وكان ابن الزبير حبسه فقال فيه\n(دعي مغلقي الأبواب دون فعالهم ... ومري تمشي بي هبلت إلى سلم)\n(إلى من يرى المعروف سهلا سبيله ... ويفعل أفعال الكرام التي تنمي)\nم دخل على سلم فأنشده فقال له هي لك ومثلها نفقتك ثم أمر له بعشرين ألفا فقبضها فقالت له زوجته أم عثمان بنت عبد الله بن عثمان بن أبي العاصي الثقفية أتعطي عشرين ألفا وأنت محبوس فقال\n(ألا بكرت عرسي تلوم سفاهة ... على ما مضى مني وتأمر بالبخل)\n(فقلت لها والجود مني سجية ... وهل يمنع المعروف سؤاله مثلي)\n(ذريني فإني غير تارك شيمتي ... ولا مقصر عن السماحة والبذل)","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":8,"spl":"ذكر أخبار الفرزدق في هذا الشعر خاصة دون غيره","tags":["الجواري والنساء"],"loc":1748},
{"id":"b97-11","bab":"الجزء 9","sec":"ذكر أخبار الفرزدق في هذا الشعر خاصة دون غيره","page":"ج9 ص367","text":"(ولا طارد ضيفي إذا جاء طارقا ... فقد طرق الأضياف شيخي من قبلي)\n(أأبخل إن البخل ليس بمخلد ... ولا الجود يدنيني إلى الموت والقتل)\n(أبيع بني حرب بآل خويلد ... وما ذاك عند الله في البيع بالعدل)\n(وأشري ابن مروان الخليفة طائعا ... بنجل بني العوام قبح من نجل)\n(فإن تظهروا لي البخل آل خويلد ... فما دلكم دلي ولا شكلكم شكلي)\n(وإن تقهروني حيث غابت عشيرتي ... فمن عجب الأيام أن تقهروا مثلي)","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":9,"spl":"ذكر أخبار الفرزدق في هذا الشعر خاصة دون غيره","tags":["الموت"],"loc":1749},
{"id":"b97-12","bab":"الجزء 9","sec":"لم تحسن النوار عشرته فتزوج عليها","page":"ج9 ص375","text":"قال دماذ في خبره ثم اصطلحا ورضيت به وساق إليها مهرها ودخل بها وأحبلها قبل أن تخرج من مكة ثم خرج بها وهما عديلان في محمل فكانت لا تزال تشاره وتخالفه لأنها كانت صالحة حسنة الدين وكانت تكره كثيرا من أمره فتزوج عليها حدراء بنت زيق بن بسطام بن قيس بن مسعود بن قيس بن خالد بن عبد الله بن عمرو بن الحارث بن همام بن مرة بن ذهل بن شيبان فتزوجها على مائة من الإبل فقالت له النوار ويلك تزوجت أعرابية دقيقة الساقين بوالة على عقبيها على مائة بعير فقال الفرزدق يفضلها عليها ويعيرها أنها كانت تربيها أمة\n(لجارية بين السليل عروقها ... وبين أبي الصهباء من آل خالد)\n(أحق بإغلاء المهور من التي ... ربت وهي تنزو في حجور الولائد)\nمدحها أيضا فقال\n(عقيلة من بني شيبان ترفعها ... دعائم للعلا من آل همام)\n(من آل مرة بين المستضاء بهم ... من رهط صيد مصاليت وحكام)\n(بين الأحاوص من كلب مركبها ... وبين قيس بن مسعود وبسطام)\nقال أيضا يمدحها ويعرض بالنوار\n(لعمري لأعرابية في مظلة ... تظل بأعلى بيتها الريح تخفق)\n(كأم غزال أو كدرة غائص ... إذا ما أتت مثل الغمامة تشرق)\n(أحب إلينا من ضناك ضفنة ... إذا وضعت عنها المراوح تعرق)\nقال بعض باهلة يجيبه\n(أعوذ بالله من غول مغولة ... كأن حافرها في الحد ظنبوب)\n(تستروح الشاة من ميل إذا ذبحت ... حب اللحام كما يستروح الذيب)\nأغضب الفرزدق النوار بمدحه إياها فقالت والله لأخزينك يا فاسق وبعثت إلى جرير فجاءها فقالت ألا ترى ما قال لي الفاسق وشكت إليه فقال\n(فلا أنا معطى الحكم عن شف منصب ... ولا عن بنات الحنظليين راغب)\n(وهن كماء المزن يشفى به الصدى ... وكانت ملاحا غيرهن المشارب)\n(لقد كنت أهلا أن تسوق دياتكم ... إلى آل زيق أن يعيبك عائب)\n(وما عدلت ذات الصليب ظعينة ... عتيبة والردفان منها وحاجب)\n(ألا ربما لم نعط زيقا بحكمه ... وأدى إلينا الحكم والغل لازب)\n(حوينا أبا زريق وزيقا وعمه ... وجدة زيق قد حوتها المقانب)\nأجابه الفرزدق بقصيدة منها\n(ألست إذ القعساء أنسل ظهرها ... إلى آل بسطام بن قيس بخاطب)\n(فنل مثلها من مثلهم ثم لمهم ... بملكك من مال مراح وعازب)\n(فلو كنت من أكفاء حدراء لم تلم ... على دارمي بين ليلى وغالب)\n(وإني لأخشى إن خطبت إليهم ... عليك التي لاقى يسار الكواعب)\nسار كان عبدا لبني ددانة فأراد مولاته على نفسها فنهته مرة بعد مرة وألح فوعدته فجاء فقالت له إني أريد أن أبخرك فإن رائحتك متغيرة فوضعت تحته مجمرة وقد أعدت له حديدة حادة فأدخلت يدها فقبضت على ذكره وهو يرى أن ذلك لشيء فقطعته بالموسى فقالت صبرا على مجامر الكرام فذهبت مثلا عاد الشعر\n(ولو قبلوا مني عطية سقته ... إلى آل زيق من وصيف مقارب)\n(هم زوجوا قبلي ضرارا وأنكحوا ... لقيطا وهم أكفاؤنا في المناسب)\n(ولو تنكح الشمس النجوم بناتها ... إذا لنكحناهن قبل الكواكب)\nقال جرير\n(يا زيق أنكحت قينا باسته حمم ... يا زيق ويحك من أنكحت يا زيق)\n(غاب المثنى فلم يشهد نجيكما ... والحوفزان ولم يشهدك مفروق)\n(أين الألى أنزلوا النعمان مقتسرا ... أم أين أبناء شيبان الغرانيق)\n(يا رب قائلة بعد البناء بها ... لا الصهر راض ولا ابن القين معشوق)\nقال الفرزدق لجرير في هذا\n(إن كان أنفك قد أعياك محمله ... فاركب أتانك ثم اخطب إلى زيق)\nال ولامه الحجاج وقال أتزوجت ابنة نصراني على مائة ناقة قال وما هي في جود الأمير قال فاشترى الإبل وساقها فلما كان في بعض الطريق ومعه أوفى بن خنزير أحد بني التيم بن شيبان بن ثعلبة دليله رأى كبشا مذبوحا فقال يا أوفى هلكت والله حدراء\nقال مالك بذلك من علم فلما بلغ قال له بعض قومها هذا البيت فانزل وأما حدراء فهلكت وقد عرفنا الذي يصيبكم في دينكم من ميراثها وهو النصف فهو لك عندنا فقال لا والله لا أرزأ منه قطميرا وهذه صدقتها فاقبضوها فقال يا بني دارم والله ما صاهرنا أكرم منكم قال وفي هذه القصة يقول الفرزدق\n(عجبت لحادينا المقحم سيره ... بنا موجفات من كلال وظلعا)\n(ليدنينا ممن إلينا لقاؤه ... حبيب ومن دار أردنا لتجمعا)\n(ولو يعلم الغيب الذي من أمامنا ... لكر بنا حادي المطي فأسرعا)\n(يقولون زر حدراء والترب دونها ... وكيف بشيء وصله قد تقطعا)\n(وما مات عند ابن المراغة مثلها ... ولا تبعته ظاعنا حيث ودعا)","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":10,"spl":"لم تحسن النوار عشرته فتزوج عليها","tags":["المديح"],"loc":1750},
{"id":"b97-13","bab":"الجزء 9","sec":"لم تحسن النوار عشرته فتزوج عليها","page":"ج9 ص375","text":"(يقول ابن خنزير بكيت ولم تكن ... على امرأة عينا أخيك لتدمعا)\n(وأهون رزء لامرئ غير جازع ... رزية مرتج الروادف أفرعا)\nوقال ابن سلام فيما أخبرنا به أبو خليفة عنه قال حدثني حاجب بن زيد وأبو الغراف قالا تزوج الفرزدق حدراء بنت زيق بن بسطام بن قيس بن مسعود بن قيس ابن خالد بن ذي الجدين وهو عبد الله بن عمرو بن الحارث بن همام بن مرة بن ذهل بن شيبان على حكم أبيها فاحتكم مائة من الإبل فدخل علىالحجاج فعذله فقال أتزوجتها على حكمها وحكم أبيها مائة بعير وهي نصرانية وجئتنا متعرضا أن نسوقها عنك اخرج ما لك عندنا شيء فقال عنبسة بن سعيد بن العاصي وأراد نفعه أيها الأمير إنها من حواشي إبل الصدقة فأمر بها فوثب عليه جرير فقال\n(يا زيق قد كنت من شيبان في حسب ... يا زيق ويحك من أنكحت يا زيق)\n(أنكحت ويحك قينا باسته حمم ... يا زيق ويحك هل بارت بك السوق)\nم ذكر باقي القصيدة بمثل رواية دماذ قال ابن سلام وأراد الفرزدق أن تحمل فاعتلوا عليه وقالوا ماتت كراهة أن يهتك جرير أعراضهم فقال جرير\n(وأقسم ما ماتت ولكنه التوى ... بحدراء قوم لم يروك لها أهلا)\n(رأوا أن صهر القين عار عليهم ... وأن لبسطام على غالب فضلا)\n(إذا هي حلت مسحلان وحاربت ... بشيبان لاقى القوم من دونها شغلا)\nوحدراء هذه هي التي ذكرها الفرزدق في أشعاره ومن ذلك قوله\n(عزفت بأعشاش وما كدت تعزف ... وأنكرت من حدراء ما كنت تعرف)\n(ولج بك الهجران حتى كأنما ... ترى الموت في البيت الذي كنت تألف)\nروضه من الطويل عزفت عن الشيء انصرفت عنه عزف يعزف عزوفا الشعر للفرزدق والغناء لسلسل ثاني ثقيل بالوسطى وفيه لحن للغريض من الثقيل الأول بالبنصر من رواية حبش","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":11,"spl":"لم تحسن النوار عشرته فتزوج عليها","tags":["الجواري والنساء"],"song":1,"loc":1751},
{"id":"b97-14","bab":"الجزء 9","sec":"الفرزدق وابن أبي بكر بن حزم","page":"ج9 ص380","text":"أخبرني علي بن سليمان الأخفش ومحمد بن العباس اليزيدي قالا حدثنا أبو سعيد السكري قال حدثنا محمد بن حبيب وأبو غسان دماذ عن أبي عبيدة قال قال اليربوعي قال إبراهيم بن محمد بن سعد بن أبي وقاص الزهري قدم الفرزدق المدينة في إمارة أبان بن عثمان قال فإني والفرزدق وكثيرا لجلوس في\nالمسجد نتناشد الأشعار إذ طلع علينا غلام شخت آدم في ثوبين ممصرين أي مصبوغين بصفرة غير شديدة ثم قصد نحونا حتى جاء إلينا فلم يسلم فقال أيكم الفرزدق فقلت مخافة أن يكون من قريش أهكذا تقول لسيد العرب وشاعرها فقال لو كان كذلك لم أقل هذا له فقال له الفرزدق ومن أنت لا أم لك\nقال رجل من بني الأنصار ثم من بني النجار ثم أنا ابن أبي بكر بن حزم بلغني أنك تزعم أنك أشعر العرب وتزعم مضر ذلك لك وقد قال صاحبنا حسان شعرا فأردت أن أعرضه عليك وأؤجلك سنة فإن قلت مثله فأنت أشعر العرب وإلا فأنت كذاب منتحل ثم أنشده قول حسان\n(لنا الجفنات الغر يلمعن بالضحى ... وأسيافنا يقطرن من نجدة دما)\n(متى ما تزرنا من معد عصابة ... وغسان نمنع حوضنا أن يهدما)\nيل إن قوله وغسان هاهنا قسم أقسم به لأن غسان لم تكن تغزوهم مع معد\n(أبى فعلنا المعروف أن ننطق الخنا ... وقائلنا بالعرف إلا تكلما)\n(ولدنا بني العنقاء وابني محرق ... فأكرم بنا خالا وأكرم بنا ابنما)\nأنشده القصيدة إلى آخرها وقال له إني قد أجلتك بها حولا ثم انصرف وانصرف الفرزدق مغضبا يسحب رداءه ما يدري أي طريق يسلك حتى خرج من المسجد قال فأقبل كثير علي فقال قاتل الله الأنصاري ما أفصح لهجته وأوضح حجته وأجود شعره قال فلم نزل في حديث الفرزدق والأنصاري بقية يومنا حتى إذا كان الغد خرجت من منزلي إلى مجلسي الذي كنت فيه بالأمس وأتاني كثير فجلس معي فإنا لنتذاكر الفرزدق ونقول ليت شعري ما فعل إذ طلع علينا في حلة أفواف\nيمانية موشاة له غديرتان حتى جلس في مجلسه بالأمس ثم قال ما فعل الأنصاري قال فنلنا منه وشتمناه فقال قاتله الله ما رميت بمثله ولا سمعت بمثل شعره فارقتكما فأتيت منزلي فأقبلت أصعد وأصوب في كل فن من الشعر فلكأني مفحم أو لم أقل قط شعرا حتى نادى المنادي بالفجر فرحلت ناقتي ثم أخذت بزمامها فقدتها حتى أتيت ذبابا ثم ناديت بأعلى صوتي أخاكم أبا لبنى\nوقال سعدان أبا ليلى فجاش صدري كما يجيش المرجل ثم عقلت ناقتي وتوسدت ذراعها فما قمت حتى قلت مائة وثلاثة عشر بيتا فبينا هو ينشدنا إذ طلع علينا الأنصاري حتى انتهى إلينا فسلم ثم قال أما إني لم آتك لأعجلك عن الأجل الذي وقته لك ولكني أحببت ألا أراك إلا سألتك عما صنعت فقال اجلس ثم أنشده\n(عزفت بأعشاش وما كدت تعزف ... )\nلما فرغ الفرزدق من إنشاده قام الأنصاري كئيبا فلما توارى طلع أبوه وهو أبو بكر بن محمد بن عمرو بن حزم في مشيخة من الأنصار فسلموا علينا وقالوا يا أبا فراس قد عرفت حللنا ومكاننا من رسول الله ووصيته بنا وقد بلغنا أن سفيها من سفهائنا تعرض لك فنسألك بالله لما حفظت فينا وصية النبي ووهبتنا له ولم تفضحنا قال إبراهيم بن محمد فأقبلت أكلمه أنا وكثير فلما أكثرنا عليه قال اذهبوا فقد وهبتكم لهذا القرشي قال وقد كان جرير قال\n(ألا أيها القلب الطروب المكلف ... أفق ربما ينأى هواك ويسعف)\n(ظللت وقد خبرت أن لست جازعا ... لربع بسلمانين عينك تذرف)\nجعل الفرزدق هذه القصيدة نقيضة لها","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":12,"spl":"الفرزدق وابن أبي بكر بن حزم — نسبة ما في هذا الخبر من الأصوات","tags":["اللهو والمزاح"],"loc":1752,"partialRef":{"sid":"b97-13","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b97-15","bab":"الجزء 9","sec":"نسبة ما في هذا الخبر من الأصوات","page":"ج9 ص382","text":"صوت منها\n(لنا الجفنات الغر يلمعن بالضحى ... وأسيافنا يقطرن من نجدة دما)\n(ولدنا بني العنقاء وابني محرق ... فأكرم بنا خالا وأكرم بنا ابنما)\nروضه من الطويل الشعر لحسان بن ثابت والغناء لمعبد خفيف ثقيل أول بالبنصر عن عمرو بن بانة","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":12,"spl":"الفرزدق وابن أبي بكر بن حزم — نسبة ما في هذا الخبر من الأصوات","tags":[],"loc":1753},
{"id":"b97-16","bab":"الجزء 9","sec":"النابغة وحسان بسوق عكاظ","page":"ج9 ص383","text":"أخبرني عمي الحسن بن محمد قال حدثني محمد بن سعد الكراني عن أبي عبد الرحمن الثقفي وأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة وأخبرنا إبراهيم بن أيوب الصائغ عن ابن قتيبة أن نابغة بني ذبيان كان تضرب له قبة من أدم بسوق عكاظ يجتمع إليه فيها الشعراء فدخل إليه حسان بن ثابت وعنده الأعشى وقد أنشده شعره وأنشدته الخنساء قولها\n(قذى بعينك أم بالعين عوار ... )\nحتى انتهت إلى قولها\n(وإن صخرا لتأتم الهداة به ... كأنه علم في رأسه نار)\n(وإن صخرا لمولانا وسيدنا ... وإن صخرا إذا نشتو لنحار)\nقال لولا أن أبا بصير أنشدني قبلك لقلت إنك أشعر الناس أنت\nوالله أشعر من كل ذات مثانة قالت الله ومن كل ذي خصيتين فقال حسان أنا والله أشعر منك ومنها قال حيث تقول ماذا قال حيث أقول\n(لنا الجفنات الغر يلمعن بالضحى ... وأسيافنا يقطرن من نجدة دما)\n(ولدنا بني العنقاء وابني محرق ... فأكرم بنا خالا وأكرم بنا ابنما)\nقال إنك لشاعر لولا أنك قللت عدد جفانك وفخرت بمن ولدت ولم تفخر بمن ولدك وفي رواية أخرى فقال له إنك قلت الجفنات فقللت العدد ولو قلت الجفان لكان أكثر وقلت يلمعن في الضحى ولو قلت يبرقن بالدجى لكان أبلغ في المديح لأن الضيف بالليل أكثر طروقا وقلت يقطرن من نجدة دما فدللت على قلة القتل ولو قلت يجرين لكان أكثر لانصباب الدم وفخرت بمن ولت ولم تفخر بمن ولدك فقام حسان منكسرا منقطعا مما يغنى فيه من قصيدة الفرزدق الفائية قوله\n(ترى الناس ما سرنا يسيرون خلفنا ... وإن نحن أومأنا إلى الناس وقفوا)\nيه رمل بالوسطى يقال إنه لابن سريج وذكر الهشامي أنه من منحول يحي المكي أخبرنا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني أبو مسلمة موهوب بن رشيد الكلابي قال وقف الفرزدق على جميل والناس مجتمعون عليه وهو ينشد\n(ترى الناس ما سرنا يسيرون خلفنا ... وإن نحن أومأنا إلى الناس وقفوا)\nفأشرع إليه رأسه من وراء الناس وقال أنا أحق بهذا البيت منك قال أنشدك الله يا أبا فراس فمضى الفرزدق وانتحله","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":13,"spl":"النابغة وحسان بسوق عكاظ — الفرزدق وكثير والبيت المسروق","tags":[],"song":1,"loc":1754,"partial":1},
{"id":"b97-17","bab":"الجزء 9","sec":"الفرزدق وكثير والبيت المسروق","page":"ج9 ص385","text":"أخبرني الحرمي بن أبي العلاء قال حدثني الزبير قال حدثني أبي عن جدي أن الفرزدق لقي كثيرا فقال له ما أشعرك يا كثير في قولك\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى بكل سبيل)\nعرض له بسرقته إياه من جميل\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى على كل مرقب)\nفقال له كثير أنت يا فرزدق أشعر مني في قولك\n(ترى الناس ما سرنا يسيرون خلفنا ... وإن نحن أومأنا إلى الناس وقفوا)\nال وهذا البيت لجميل سرقه الفرزدق فقال الفرزدق لكثير هل كانت أمك ترد البصرة قال لا ولكن أبي كان نزيلا لأمك أخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن إسماعيل عن عبد العزيز بن عمران عن محمد بن عبد العزيز عن ابن شهاب عن طلحة بن عبد الله بن عوف قال لقي الفرزدق كثيرا بقارعة البلاط وأنا وهو نمشي فقال له الفرزدق يا أبا صخر أنت أنسب العرب حيث تقول\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى بكل سبيل)\nال وأنت يا أبا فراس أفخر العرب حيث تقول\n(ترى الناس ما سرنا يسيرون خلفنا ... وإن نحن أومأنا إلى الناس وقفوا)\nال عبد العزيز وهذان البيتان جميعا لجميل سرق أحدهما الفرزدق وسرق الآخر كثير فقال له الفرزدق يا أبا صخر هل كانت أمك\nترد البصرة قال لا ولكن أبي كان كثيرا يردها قال طلحة فوالذي نفسي بيده لقد تعجبت من كثير وجوابه وما رأيت أحدا قط أحمق منه لقد دخلت عليه يوما في نفر من قريش وكنا كثيرا نهزأ به وكان يتشيع تشيعا قبيحا فقلنا له كيف تجدك يا أبا صخر فقال بخير هل سمعتم الناس يقولون شيئا قلت نعم يتحدثون أنك الدجال قال والله إن قلت ذلك إني لأجد في عيني هذه ضعفا منذ أيام ولجرير قصيدة يناقض بها هذه القصيدة في أولها غناء نسيته\n(ألا أيها القلب الطروب المكلف ... أفق ربما ينأى هواك ويسعف)\n(ظللت وقد خبرت أن لست جازعا ... لربع بسلمانين عينك تذرف)\nلشعر لجرير والغناء لمحمد بن الأشعث الكوفي ثاني ثقيل بالبنصر عن عمرو بن بانة وقال حبش فيه ثقيل أول بالوسطى وليس ذلك بصحيح","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":13,"spl":"النابغة وحسان بسوق عكاظ — الفرزدق وكثير والبيت المسروق","tags":["الرواية والكتابة"],"loc":1755},
{"id":"b97-18","bab":"الجزء 9","sec":"رجع الحديث إلى سياقة حديث الفرزدق والنوار","page":"ج9 ص386","text":"قال دماذ وتزوج الفرزدق على النوار امرأة من اليرابيع وهم بطن من النمر بن قاسط حلفاء لبني الحارث بن عباد القيني وقد انتسبوا فيهم فقالت له النوار وما عسى أن تكون القينية فقال\n(أرتك نجوم الليل والشمس حية ... زحام بنات الحارث بن عبادا)\n(نساء أبوهن الأغر ولم تكن ... من الحت في أجبالها وهداد)\n(ولم يكن الجوف الغموض محلها ... ولا في الهجاريين رهط زياد)\n(أبوها الذي أدنى النعامة بعدما ... أبت وائل في الحرب غير تماد)\nعني بأبيها الذي أدنى النعامة الحارث بن عباد وأراد قوله\n(قربا مربط النعامة مني ... )\n(عدلت بها ميل النوار فأصبحت ... مقاربة لي بعد طول بعاد)\n(وليست وإن أنبأت أني أحبها ... إلى دارميات النجار جياد)\nقال أبو عبيدة حدثني أعين بن لبطة قال تزوج الفرزدق مضارة للنوار امرأة يقال لها رهيمة بنت غنيم بن درهم من اليرابيع قوم من النمر بن قاسط في بني الحارث بن عباد وأمها الحميضة من بني الحارث فنافرته الحميضة فاستعدت عليه فأنكرها الفرزدق وقال أنا منها بريء وطلق ابنتها وقال\n(إن الحميضة كانت لي ولابنتها ... مثل الهراسة بين النعل والقدم)\n(إذا أتت أهلها مني مطلقة ... فلن أرد عليها زفرة الندم)\nضى الحديث ولم أجد لأحد من الخلفاء الذين ذكرتهم والذين لم أذكرهم بعد الواثق صنعة يعتد بها إلا المعتضد فإنه صنع صنعة متقنة عجيبة أبرت على صنعة سائر الخلفاء سوى الواثق وفضل فيها أكثر أهل الزمان الذي نشأ فيه وإنما ذكرت صنعة من بينهما لأنها قد رويت فأما حقيقة الغناء الجيد فليس بينهما مثلهما\nوذكر عبيد الله بن عبد الله بن طاهر صنعة المعتضد فقرظها وقال لم أجد لحنا قديما قد جمع من النغم ما جمعه لحن ابن محرز في شعر مسافر بن أبي عمرو وهو\n(يا من لقلب مقصر ... ترك المنى لفواتها)\nإنه جمع من النغم العشر ثمانيا ولحن ابن محرز أيضا في شعر كثير\n(توهمت بالخيف رسما محيلا ... لعزة تعرف منه الطلولا)\nهو أيضا يجمع ثمانيا من النغم وقد تلطف بعض من له دربة وحذق بهذه الصناعة حتى جمع النغم العشر في هذا الصوت الأخير متوالية وجمعها في صوت آخر غير متوالية وهو في شعر ابن هرمة\n(فإنك إذ أطمعتني منك بالرضا ... وأيأستني من بعد ذلك بالغضب)\nأعجب من ذلك ما عمله أمير المؤمنين المعتضد بالله فإنه صنع في رجز دريد بن الصمة يا ليتني فيها جذع لحنا من الثقيل الأول يجمع النغم العشر فأتى به مستوفى الصنعة محكم البناء صحيح الأجزاء والقسمة مشبع المفاصل كثير الأدوار لاحقا بجيد صنعة الأوائل وإنما زاد فضله على من تقدمه لأنه عمله في ضرب من الرجز قصير جدا واستوفى فيه الصنعة كلها على ضيق الوزن فصار أعجب مما تقدمه إذ تلك عملت في أوزان تامة وأعاريض طوال يتمكن الصانع فيها من الصنعة ويقتدر على كثرة التصرف وليس هذا الوزن في تمكنه من ذلك فيه مثل تلك","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":14,"spl":"رجع الحديث إلى سياقة حديث الفرزدق والنوار — نسبة هذا اللحن","tags":["الهجاء"],"loc":1756,"partialRef":{"sid":"b46-20","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b97-19","bab":"الجزء 9","sec":"نسبة هذا اللحن","page":"ج9 ص388","text":"\n(يا ليتني فيها جذع ... أخب فيها وأضع)\n(أقود وطفاء الزمع ... كأنها شاة صدع)\nالشعر لدريد بن الصمة والغناء للمعتضد ولحنه ثقيل أول يجمع النغم العشر\nبسم الله الرحمن الرحيم","topic":"أخبار عدي بن الرقاع ونسبه","topicNo":97,"sp":14,"spl":"رجع الحديث إلى سياقة حديث الفرزدق والنوار — نسبة هذا اللحن","tags":[],"song":1,"loc":1757},
{"id":"b98-2","bab":"الجزء 10","sec":"أخبار المنخل ونسبه — اتهمه النعمان بامرأته المتجردة فقتله","page":"ج9 ص388 – ج10 ص5","text":"هو المنخل بن عمرو ويقال المنخل بن مسعود بن أفلت بن عمرو بن كعب بن سواءة بن غنم بن حبيب بن يشكر بن بكر بن وائل وذكر أبو محلم النسابة أنه المنخل بن مسعود بن أفلت بن قطن بن سوءة بن مالك بن ثعلبة بن حبيب بن غنم بن حبيب بن كعب بن يشكر وقال ابن الأعرابي هو المنخل بن الحارث بن قيس بن عمرو بن ثعلبة بن عدي بن جشم بن حبيب بن كعب بن يشكر\nشاعر مقل من شعراء الجاهلية وكان النعمان بن المنذر قد اتهمه بامرأته المتجردة وقيل بل وجده معها وقيل بل سعي به إليه في أمرها فقتله وقيل بل حبسه ثم غمض خبره فلم تعلم له حقيقة إلى اليوم فيقال إنه دفنه حيا ويقال إنه غرقه والعرب تضرب به المثل كما تضربه بالقارظ العنزي\nوأشباهه ممن هلك ولم يعلم له خبر وقال ذو الرمة\n(تقارب حتى تطمع التابع الصبا ... وليست بأدنى من إياب المنخل)\nقال النمر بن تولب\n(وقولي إذا ما أطلقوا عن بعيرهم ... تلاقونه حتى يؤوب المنخل)\nخبرني محمد بن خلف بن المرزبان قال أخبرني أحمد بن زهير قال أخبرني عبد الله بن كريم قال أخبرني أبو عمرو الشيباني قال كان سبب قتل المنخل أن المتجردة واسمها ملوية\nوقيل عند بنت المنذر بن الأسود الكلبية كانت عند ابن عمر لها يقال له حلم وهو الأسود بن المنذر بن حارثة الكلبي وكانت أجمل أهل زمانها فرآها المنذر بن المنذر الملك اللخمي فعشقها فجلس ذات يوم على شرابه ومعه حلم وامرأته المتجردة فقال المنذر لحلم إنه لقبيح بالرجل أن يقيم على المرأة زمانا طويلا حتى لا يبقى في رأسه ولا لحيته شعرة بيضاء إلا عرفتها فهل لك أن تطلق امرأتك المتجردة وأطلق امرأتي سلمى\nقال نعم فأخذ كل واحد منهما على صاحبه عهدا قال فطلق المنذر امرأته سلمى وطلق حلم امرأته المتجردة فتزوجها المنذر ولم يطلق لسلمى أن تتزوج حلما\nوحجبها وهي أم ابنه النعمان بن المنذر فقال النابغة الذبياني يذكر ذلك\n(قد خادعوا حلما عن حرة خرد ... حتى تبطنها الخداع ذو الحلم)\nال ثم مات المنذر بن المنذر فتزوجها بعده النعمان بن المنذر ابنه وكان قصيرا دميما أبرش وكان ممن يجالسه ويشرب معه النابغة الذبياني وكان جميلا عفيفا والمنخل اليشكري وكان جميلا وكان يتهم بالمتجردة فأما النابغة فإن النعمان أمره بوصفها فقال قصيدته التي أولها\n(من آل مية رائح أو مغتدي ... عجلان ذا زاد وغير مزود)\nوصفها فأفحش فقال\n(وإذا طعنت طعنت في مستهدف ... رابي المجسة بالعبير مقرمد)\n(وإذا نزعت نزعت عن مستحصف ... نزع الحزور بالرشاء المحصد)\nغار المنخل من ذلك وقال هذه صفة معاين فهم النعمان بقتل النابغة حتى هرب منه وخلا المنخل بمجالسته وكان يهوى المتجردة وتهواه وقد ولدت للنعمان غلامين جميلين يشبهان المنخل وكانت العرب تقول إنهما منه فخرج النعمان لبعض غزواته\nقال ابن الأعرابي بل خرج متصيدا فبعثت المتجردة إلى المنخل فأدخلته قبتها وجعلا يشربان فأخذت خلخالها وجعلته في رجله وأسدلت شعرها فشدت خلخالها إلى خلخاله الذي في رجله من شدة إعجابها به و دخل النعمان بعقب ذلك فرآها\nعلى تلك الحال فأخذه فدفعه إلى رجل من حرسه من تغلب يقال له عكب وأمره بقتله فعذبه حتى قتله فقال المنخل يحرض قومه عليه\n(ألا من مبلغ الحيين عني ... بأن القوم قد قتلوا أبيا)\n(فإن لم تثأروا لي من عكب ... فلا رويتم أبدا صديا)\nوقال أيضا\n(ظل وسط الندي قتلى بلا جرم ... وقومي ينتجون السخالا)\nقال في المتجردة\n(ديار للتي قتلتك غصبا ... بلا سيف يعد ولا نبال)\n(بطرف ميت في عين حي ... له خبل يزيد على الخبال)\nقال أيضا\n(ولقد دخلت على الفتاة ... الخدر في اليوم المطير)\n(الكاعب الخنساء ترفل ... في الدمقس وفي الحرير)\n(دافعتها فتدافعت ... مشي القطاة إلى الغدير)\n(ولثمتها فتنفست ... كتنفس الظبي البهير)\n(ورنت وقالت يا منخل ... هل بجسمك من فتور)\n(ما مس جسمي غير حبك ... فاهدئي عني وسيري)\n(يا هند هل من ناثل ... يا هند للعاني الأسير)\n(وأحبها وتحبني ... ويحب ناقتها بعيري)\n(ولقد من شربت من المدامة ... بالكبير وبالصغير)\n(فإذا سكرت فإنني ... رب الخورنق والسدير)\n(وإذا صحوت فإنني ... رب الشويهة والبعير)\n(يا رب يوم للمنخل ... قد لها فيه قصير)","topic":"أخبار المنخل ونسبه","topicNo":98,"sp":0,"spl":"أخبار المنخل ونسبه — اتهمه النعمان بامرأته المتجردة فقتله","tags":["الجواري والنساء"],"loc":1758},
{"id":"b98-3","bab":"الجزء 10","sec":"رواية أخرى عن علاقته بالمتجردة وشعره فيها","page":"ج10 ص9","text":"وأخبرني بخبر المنخل مع المتجردة أيضا علي بن سليمان الأخفش قال أخبرني أبو سعيد السكري عن محمد بن حبيب عن ابن الأعرابي قال كانت المتجردة امرأة النعمان فاجرة وكانت تتهم بالمنخل وقد ولدت للنعمان غلامين جميلين يشبهان المنخل فكان يقال إنهما منه وكان جميلا وسيما وكان النعمان أحمر أبرش قصيرا دميما وكان للنعمان يوم يركب فيه فيطيل المكث وكان المنخل من ندمائه لا يفارقه وكان يأتي المتجردة في ذلك اليوم الذي يركب فيه النعمان فيطيل عندها حتى إذا جاء النعمان آذنتها بمجيئه وليدة لها موكلة بذلك فتخرجه فركب النعمان ذات يوم وأتاها المنخل كما كان يأتيها فلاعبته وأخذت\nقيدا فجعلت إحدى حلقتيه في رجله والأخرى في رجلها وغفلت الوليدة عن ترقب النعمان لأن الوقت الذي يجيء فيه لم يكن قرب بعد وأقبل النعمان حينئذ ولم يطل في مكثه كما كان يفعل فدخل إلى المتجردة فوجدها مع المنخل قد قيدت رجلها ورجله بالقيد فأخذه النعمان فدفعه إلى عكب صاحب سجنه ليعذبه وعكب رجل من لخم فعذبه حتى قتله وقال المنخل قبل أن يموت هذه الأبيات وبعث بها إلى ابنيه\n(ألا من مبلغ الحرين عني ... بأن القوم قد قتلوا أبيا)\n(وإن لم تثأروا لي من عكب ... فلا أرويتما أبدا صديا)\n(يطوف بي عكب في معد ... ويطعن بالصملة في قفيا)\nال ابن حبيب وزعم ابن الجصاص أن عمرو بن هند هو قاتل المنخل والقول الأول أصح وهذه القصيدة التي منها الغناء يقولها في المتجردة وأولها قوله\n(إن كنت عاذلتي فسيري ... نحو العراق ولا تحوري)\n(لا تسألي عن جل ما ... لي واذكري كرمي وخيري)\n(وإذا الرياح تناوحت ... بجوانب البيت الكسير)\n(ألفيتني هش الندي ... بمر قدحي أو شجيري)\nلشجير القدح الذي لم يصلح حسنا ويقال بل هو القدح العارية\n(ونهى أبو أفعى فقلدني ... أبو أفعى جريري)\n(وجلالة خطارة ... هوجاء جائلة الضفور)\n(تعدو بأشعث قد وهى ... سر باله باقي المسير)\n(فضلا على ظهر الطريق ... إليك علقمة بن صير)\n(الواهب الكوم الصفايا ... والأوانس في الخدور)\n(يصفيك حين تجيئه ... بالعصب والحلي الكثير)\n(وفوارس كأوار حر ... النار أحلاس الذكور)\n(شدوا دوابر بيضهم ... في كل محكمة الفتير)\n(فاستلأموا وتلببوا ... إن التلبب للمغير)\n(وعلى الجياد المضمرات ... فوارس مثل الصقور)\n(يخرجن من خلل الغبار ... يجفن بالنعم الكثير)\n(فشفيت نفسي من أولئك ... والفوائح بالعبير)\n(يرفلن في المسك الذكي ... وصائك كدم النحير)\n(يعكفن مثل أساود التنوم ... لم تعكف لزور)\n(ولقد دخلت على الفتاة ... الخدر في اليوم المطير)\n(الكاعب الخنساء ترفل في الدمقس وفي الحرير ... )\n(فدفعتها فتدافعت ... مشي القطاة إلى الغدير)\n(ولثمتها فنتفست ... كتنفس الظبي البهير)\n(فدنت وقالت يا منخل ... ما بجسمك من حرور)\n(ما شف جسمي غير حبك ... فاهدئي عني وسيري)\n(ولقد شربت من المدامة ... بالصغير وبالكبير)\n(ولقد شربت الخمر بالخيل ... الإناث وبالذكور)\n(ولقد شربت الخمر بالعبد الصحيح وبالأسير ... )\n(فإذا سكرت فإنني ... رب الخورنق والسدير)\n(وإذا صحوت فإنني ... رب الشويهة والبعير)\n(يا رب يوم للمنخل قد لها فيه قصير ... )\n(يا هند هل من نائل ... يا هند للعاني الأسير)\nومن الناس من يزيد في هذه القصيدة\n(وأحبها وتحبني ... ويحب ناقتها بعيري)\nلم أجده في رواية صحيحة\n\n(لمن شيخان قد نشدا كلابا ... كتاب الله لو قبل الكتابا)\n(أناشده فيعرض في إباء ... فلا وأبي كلاب ما أصابا)\nالشعر لأمية بن الأسكر الليثي والغناء لعبد الله بن طاهر رمل بالوسطى صنعه ونسبه إلى لميس جاريته وذكر الهشامي أن اللحن لها وذكره عبيد الله بن عبد الله بن طاهر في جامع أغانيهم ووقع إلي فقال الغناء فيه للدار الكبيرة وكذلك كان يكني عن أبيه وعن إسحاق بن إبراهيم ابن مصعب وجواريهم ويكني عن نفسه وجاريته شاجي وما يصنع في دور إخوته بالدار الصغيرة","topic":"أخبار المنخل ونسبه","topicNo":98,"sp":1,"spl":"رواية أخرى عن علاقته بالمتجردة وشعره فيها","tags":[],"song":1,"loc":1759,"partial":1},
{"id":"b99-2","bab":"الجزء 10","sec":"أخبار أمية بن الأسكر ونسبه — شعره لابنه كلاب لما طالت غيبته","page":"ج10 ص14 – ج10 ص15","text":"هو أمية بن حرثان بن الأسكر بن عبد الله بن سرابيل الموت بن زهرة ابن زبينة بن جندع بن ليث بن بكر بن عبد مناة بن كنانة بن خزيمة بن مدركة ابن إلياس بن مضر بن نزار شاعر فارس مخضرم أدرك الجاهلية والإسلام وكان من سادات قومه وفرسانهم وله أيام مأثورة مذكورة وكان له أخ يقال له أبو لاعق الدم وكان من فرسان قومه وشعرائهم وابنه كلاب بن أمية أيضا أدرك النبي فأسلم مع أبيه ثم هاجر إلى النبي فقال أبوه فيه شعرا\nذكر أبو عمرو الشيباني أنه هذا الشعر وهو خطأ إنما خاطبه بهذا الشعر لما غزا مع أهل العراق لقتال الفرس وخبره في ذلك يذكر بعد هذا قال أبو عمرو في خبره فأمره بصلة أبيه وملازمته طاعته وكان عمر بن الخطاب استعمل كلابا على الأبلة فكان أبواه ينتابانه يأتيه أحدهما في كل سنة ثم أبطآ عليه وكبرا فضعفا عن لقائه فقال أبياتا وأنشدها عمر فرق له ورده إليهما فلم يلبث معهما إلا مدة حتى\nنهشته أفعى فمات وهذا أيضا وهم من أبي عمرو وقد عاش كلاب حتى ولي لزياد الأبله ثم استعفى فأعفاه وسأذكر خبره في ذلك وغيره ها هنا إن شاء الله تعالى\nفأما خبره مع عمر فإن الحسن بن علي أخبرني به قال حدثني الحارث بن محمد قال حدثني المدائني عن أبي بكر الهذلي عن الزبيري عن عروة بن الزبير قال هاجر كلاب بن أمية بن الأسكر إلى المدينة في خلافة عمر بن الخطاب فأقام بها مدة ثم لقي ذات يوم طلحة بن عبيد الله والزبير بن العوام فسألهما أي الأعمال أفضل في الإسلام فقالا الجهاد فسأل عمر فأغزاه في جيش وكان أبوه قد كبر وضعف فلما طالت غيبة كلاب عنه قال\n(لمن شيخان قد نشدا كلابا ... كتاب الله إن قبل الكتابا)\n(أناديه فيعرض في إباء ... فلا وأبي كلاب ما أصابا)\n(إذا سجعت حمامة بطن واد ... إلى بيضاتها دعوا كلابا)\n(أتاه مهاجران تكنفاه ... ففارق شيخه خطئا وخابا)\n(تركت أباك مرعشة يداه ... وأمك ما تسيغ لها شرابا)\n(تمسح مهره شفقا عليه ... وتجنبه أبا عرها الصعابا)\nقال تجنبه وتجنبه واحد من قول الله عز و جل ( واجنبني وبني أن نعبد الأصنام\nقال\n(فإنك قد تركت أباك شيخا ... يطارق أينقا شزبا طرابا)\n(فإنك والتماس الأجر بعدي ... كباغي الماء يتبع السرابا)","topic":"أخبار أمية بن الأسكر ونسبه","topicNo":99,"sp":0,"spl":"أخبار أمية بن الأسكر ونسبه — شعره لابنه كلاب لما طالت غيبته — شعره في استرحام عمر لاسترداد","tags":["السفر والحج","الخمر"],"loc":1760},
{"id":"b99-3","bab":"الجزء 10","sec":"شعره في استرحام عمر لاسترداد ابنه","page":"ج10 ص16","text":"فبلغت أبياته عمر فلم يردد كلابا وطال مقامه فأهتر أميه وخلط جزعا عليه ثم أتاه يوما وهو في مسجد رسول الله وحوله المهاجرون والأنصار فوقف عليه ثم أنشأ يقول\n(أعاذل قد عذلت بغير قدر ... ولا تدرين عاذل ما ألاقي)\n(فإما كنت عاذلتي فردي ... كلابا إذ توجه للعراق)\n(ولم أقض اللبانة من كلاب ... غداة غد وأذن بالفراق)\n(فتى الفتيان في عسر ويسر ... شديد الركن في يوم التلاقي)\n(فلا والله ما باليت وجدي ... ولا شفقي عليك ولا اشتياقي)\n(وإبقائي عليك إذا شتونا ... وضمك تحت بحري واعتناقي)\n(فلو فلق الفؤاد شديد وجد ... لهم سواد قلبي بانفلاق)\n(سأستعدي على الفاروق ربا ... له دفع الحجيج إلى بساق)\n(وأدعو الله مجتهدا عليه ... ببطن الأخشبين إلى دفاق)\n(إن الفاروق لم يردد كلابا ... إلى شيخين هامهما زواق)\nقال فبكى عمر بكاء شديدا وكتب برد كلاب إلى المدينة فلما قدم دخل إليه فقال ما بلغ من برك بأبيك قال كنت أوثره وأكفيه أمره وكنت أعتمد إذا أردت أن أحلب له لبنا أغزر ناقة في إبله وأسمنها فأريحها وأتركها حتى تستقر ثم أغسل أخلافها حتى تبرد ثم أحتلب له فأسقيه فبعث عمر إلى أمية من جاء به إليه فأدخله يتهادى وقد ضعف بصره وانحنى فقال له كيف أنت يا أبا كلاب\nقال كما تراني يا أمير المؤمنين قال فهل لك من حاجة قال نعم أشتهي أن أرى كلابا فأشمه شمة وأضمه ضمة قبل أن أموت فبكى عمر ثم قال ستبلغ من هذا ما تحب إن شاء الله تعالى ثم أمر كلابا أن يحتلب لأبيه ناقة كما كان يفعل ويبعث إليه بلبنها ففعل فناوله عمر الإناء\nوقال دونك هذا يا أبا كلاب فلما أخذه وأدناه إلى فمه قال لعمر والله يا أمير المؤمنين إني لأشم رائحة يدي كلاب من هذا الإناء فبكى عمر\nوقال هذا كلاب عندك حاضرا قد جئناك به فوثب إلى ابنه وضمه إليه وقبله وجعل عمر يبكي ومن حضره وقال لكلاب الزم أبويك فجاهد فيهما ما بقيا ثم شأنك بنفسك بعدهما وأمر له بعطائه وصرفه مع أبيه فلم يزل معه مقيما حتى مات أبوه","topic":"أخبار أمية بن الأسكر ونسبه","topicNo":99,"sp":0,"spl":"أخبار أمية بن الأسكر ونسبه — شعره لابنه كلاب لما طالت غيبته — شعره في استرحام عمر لاسترداد","tags":["السفر والحج"],"loc":1761},
{"id":"b99-4","bab":"الجزء 10","sec":"أصيبت ابله بالهيام فأخرجه قومه","page":"ج10 ص17","text":"ونسخت من كتاب أبي سعيد السكري أن أمية كانت له إبل هائمة أي أصابها الهيام وهو داء يصيب الإبل من العطش فأخرجته بنو بكر مخافة أن يصيب إبلهم فقال لهم يا بني بكر إنما هي ثلاث ليال ليلة بالبقعاء وليلة بالفرع وليلة بلقف في سامر من بني بكر فلم ينفعه ذلك وأخرجوه فأتى مزينة فأجاروه وأقام عندهم إلى أن صحت إبله وسكنت فقال يمدح مزينة\n(تكنفها الهيام وأخرجوها ... فما تأوي إلى إبل صحاح)\n(فكان إلى مزينة منتهاها ... على ما كان فيها من جناح)\n(وما يكن الجناح فإن فيها ... خلائق ينتمين إلى صلاح)\n(ويوما في بني ليث بن بكر ... تراعى تحت قعقعة الرماح)\n(فإما أصبحن شيخا كبيرا ... وراء الدار يثقلني سلاحي)\n(فقد آتي الصريخ إذا دعاني ... على ذي منعة عتد وقاح)\n(وشر أخي مؤامرة خذول ... على ما كان مؤتكل ولاح)","topic":"أخبار أمية بن الأسكر ونسبه","topicNo":99,"sp":1,"spl":"أصيبت ابله بالهيام فأخرجه قومه — عمر حتى خرف وسخر منه","tags":["المديح","الخمر"],"loc":1762},
{"id":"b99-5","bab":"الجزء 10","sec":"عمر حتى خرف وسخر منه","page":"ج10 ص18","text":"أخبرني عمي قال حدثنا محمد بن عبد الله الحزنبل عن عمرو بن أبي\nعمرو الشيباني عن أبيه وأخبرني به محمد بن خلف بن المرزبان قال حدثنا أبو توبة عن أبي عمرو قال عمر أمية بن الأسكر عمرا طويلا حتى خرف فكان ذات يوم جالسا في نادي قومه وهو يحدث نفسه إذ نظر إلى راعي ضأن لبعض قومه يتعجب منه فقام لينهض فسقط على وجهه فضحك الراعي منه واقبل ابناه إليه فلما رآهما أنشأ يقول\n(يا بني أمية إني عنكما غان ... وما الغنى غير أني مرعش فان)\n(يا بني أمية إلا تحفظا كبري ... فإنما أنتما والثكل سيان)\n(هل لكما في تراث تذهبان به ... إن التراث لهيان بن بيان)\nقال هيان بن بيان وهي ترى للقريب والبعيد\n(أصبحت هزءا لراعي الضأن يسخر بي ... ماذا يربيك مني راعي الضان)\n(أعجب لغيري إني تابع سلفي ... أعمام مجد وأجدادي وإخواني)\n(وانعق بضأنك في أرض تطيف بها ... بين الأساف وأنتجها بجلذان)\nلذان موضع بالطائف\n(ببلدة لا ينام الكالئان بها ... ولا يقر بها أصحاب ألوان)","topic":"أخبار أمية بن الأسكر ونسبه","topicNo":99,"sp":1,"spl":"أصيبت ابله بالهيام فأخرجه قومه — عمر حتى خرف وسخر منه","tags":["اللهو والمزاح","الخمر"],"loc":1763},
{"id":"b99-6","bab":"الجزء 10","sec":"إعجاب الإمام علي بشعره","page":"ج10 ص19","text":"وهذه الأبيات تمثل بها أمير المؤمنين علي بن أبي طالب صلوات الله عليه في خطبة له على المنبر بالكوفة حدثنا بها أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري\nقالا حدثنا عمر بن شبة قال حدثنا محمد بن أبي رجاء قال حدثنا إبراهيم بن سعد قال قال عبد الله بن عدي بن الخيار شهدت الحكمين ثم أتيت الكوفة وكانت لي إلى علي عليه السلام حاجة فدخلت عليه فلما رآني\nقال مرحبا بك يا ابن أم قتال أزائرا جئتنا أم لحاجة فقلت كل جاء بي جئت لحاجة وأحببت أن أجدد بك عهدا وسألته عن حديث فحدثني على ألا أحدث به واحدا فبينا أنا يوما بالمسجد في الكوفة إذا علي صلوات الله عليه متنكب قرنا له فجعل يقول الصلاة جامعة وجلس على المنبر فاجتمع الناس وجاء الأشعث بن قيس فجلس إلى جانب المنبر فلما اجتمع الناس ورضي منهم\nقال فحمد الله وأثنى عليه ثم قال أيها الناس إنكم تزعمون أن عندي من رسول الله ما ليس عند الناس ألا وإنه ليس عندي إلا ما في قرني هذا ثم نكت كنانته فأخرج منها صحيفة فيها المسلمون تتكافأ دماؤهم وهم يد على من سواهم من أحدث حدثا أو آوى محدثا فعليه لعنة الله والملائكة والناس أجمعين فقال له الأشعث بن قيس هذه والله عليك لا لك دعها تترحل فخفض علي صلوات الله عليه إليه بصره وقال ما يدريك ما علي مما لي عليك لعنة الله ولعنة اللاعنين حائك ابن حائك منافق ابن منافق كافر ابن كافر والله لقد\nأسرك الإسلام مرة والكفر مرة فما فداك من واحد منهما حسبك ولا مالك ثم رفع إلي بصره فقال يا عبيد الله\n(أصبحت قنا لراعي الضأن يلعب بي ... ماذا يريبك مني راعي الضان)\nقلت بأبي أنت وأمي قد كنت والله أحب أن أسمع هذا منك قال هو والله ذلك قال\n(فما قيل لي من بعدها من مقالة ... ولا علقت مني جديدا ولا درسا)\nخبرني الحسن بن علي قال حدثنا الحارث عن المدائني قال لما مات أمية بن الأسكر عاد ابنه كلاب إلى البصرة فكان يغزو مع المسلمين منها مغازيهم وشهد فتوحات كثيرة وبقي إلى أيام زياد فولاه الأبلة فسمع كلاب يوما عثمان بن أبي العاص يحدث أن داود نبي الله عليه السلام كان يجمع أهله في السحر فيقول ادعوا ربكم فإن في السحر ساعة لا يدعو فيها عبد مؤمن إلا غفر له إلا أن يكون عشار أو عريفا فلما سمع ذلك كلاب كتب إلى زياد فاستعفاه من عمله فأعفاه\nقال المدائني ولم يزل كلاب بالبصرة حتى مات والمربعة المعروفة بمربعة كلاب بالبصرة منسوبة إليه وقال أبو عمرو الشيباني كان بين بني غفار قومه وبني ليث حرب فظفرت بنو ليث بغفار فحالف رحضة بن خزيمة بن خلاف بن حارثة بن\nغفار وقومه جميعا بني أسلم بن أفصى بن خزاعة فقال أمية بن الأسكر في ذلك وكان سيد بني جندع بن ليث وفارسهم\n(لقد طبت نفسا عن مواليك يا رحضا ... وآثرت أذناب الشوائل والحمضا)\n(تعللنا بالنصر في كل شتوة ... وكل ربيع أنت رافضنا رفضا)\n(فلولا تأسينا وحد رماحنا ... لقد جلا قوم لحمنا تربا قضا)\nلقض والقضيض الحصا الصغار","topic":"أخبار أمية بن الأسكر ونسبه","topicNo":99,"sp":2,"spl":"إعجاب الإمام علي بشعره — تمثل عبد الله بن الزبير بشعره","tags":["المديح"],"loc":1764},
{"id":"b99-7","bab":"الجزء 10","sec":"تمثل عبد الله بن الزبير بشعره","page":"ج10 ص22","text":"أخبرني الحسن بن علي قال حدثني أحمد بن زهير قال حدثنا مصعب بن عبد الله عن أبيه قال افتعل عمرو بن الزبير كتابا عن معاوية إلى مروان بن الحكم بأن يدفع إليه مالا فدفعه إليه فلما عرف معاوية خبره كتب إلى مروان بأن يحبس عمرا حتى يؤدي المال فحبسه مروان وبلغ الخبر عبد الله بن الزبير فجاء إلى مروان وسأله عن الخبر فحدثه به فقال مالكم في ذمتي فأطلق عمرا وأدى عبد الله المال عنه وقال والله إني لأؤديه عنه وإني لأعلم أنه غير شاكر ثم تمثل قول أمية بن الأسكر الليثي\n(فلولا تأسينا وحد رماحنا ... لقد جر قوم لحمنا تربا قضا)\nوقال ابن الكلبي حدثنا بعض بني الحارث بن كعب قال","topic":"أخبار أمية بن الأسكر ونسبه","topicNo":99,"sp":2,"spl":"إعجاب الإمام علي بشعره — تمثل عبد الله بن الزبير بشعره","tags":["الخمر","الرواية والكتابة"],"loc":1765},
{"id":"b99-8","bab":"الجزء 10","sec":"سيدان يخطبان ابنة له جميلة","page":"ج10 ص23","text":"اجتمع يزيد بن عبد المدان وعامر بن الطفيل بموسم عكاظ فقدم أمية بن الأسكر ومعه بنت له من أجمل أهل زمانها فخطبها يزيد وعامر فقالت أم كلاب امرأة أمية من هذان الرجلان قال هذا ابن الديان وهذا عامر بن الطفيل قالت أعرف ابن الديان ولا أعرف عامرا قال هل سمعت بملاعب الأسنة قالت نعم والله قال فهذا ابن أخيه وأقبل يزيد فقال يا أمية أنا ابن الديان صاحب الكثيب ورئيس\nمذحج ومكلم العقاب ومن كان يصوب أصابعه فتنطف دما ويدلك راحتيه فتخرجان ذهبا قال أمية بخ بخ فقال عامر جدي الأحزم وعمي أبو الأصبع وعمي ملاعب الأسنة وجدي الرحال وأبي فارس قرزل\nقال أمية بخ بخ مرعى ولا كالسعدان فأرسلها مثلا فقال يزيد يا عامر هل تعلم شاعرا من قومي رحل بمدحه إلى رجل من قومك قال لا قال فهل تعلم أن شعراء قومك يرحلون بمدحهم إلى قومي قال نعم قال فهل لك نجم يمان أو برد يمان أو سيف يمان أو ركن يمان فقال لا قال فهل ملكناكم ولم تملكونا قال نعم فنهض يزيد وقام ثم قال\n(أمي يا بن الأسكر بن مدلج ... لا تجعلن هوازنا كمذحج)\n(إنك إن تلهج بأمر تلجج ... ما لنبع في مغرسه كالعوسج)\n(ولا الصريح المحض كالممزج ... )\nقال مرة بن دودان العقيلي وكان عدوا لعامر بن الطفيل\n(يا ليت شعري عنك يا يزيد ... ماذا الذي من عامر تريد)\n(لكل قوم فخرهم عتيد ... أمطلقون نحن أم عبيد)\n(لا بل عبيد زادنا الهبيد ... )\nفزوج أمية يزيد فقال يزيد في ذلك\n(يا للرجال لطارق الأحزان ... ولعامر بن طفيل الوسنان)\n(كانت إتاوة قومه لمحرق ... زمنا وصارت بعد للنعمان)\n(عد الفوارس من هوازن كلها ... كثفا علي وجئت بالديان)\n(فإذا لي الفضل المبين بوالد ... ضخم الدسيعة أزأني ويمان)\n(يا عام إنك فارس متهور ... غض الشباب أخوندي وقيان)\n(واعلم بأنك يا بن فارس قرزل ... دون الذي تسمو له وتداني)\n(ليست فوارس عامر بمقرة ... لك بالفضيلة في بني عيلان)\n(فإذا لقيت بني الخميس ومالكا ... وبني الضباب وحي آل قنان)\n(فاسأل من المرء المنوه باسمه ... والدافع الأعداء عن نجران)\n(يعطى المقادة في فوارس قومه ... كرما لعمرك والكريم يمان)\nقال عامر بن الطفيل مجيبا له\n(يا للرجال لطارق الأحزان ... ولما يجيء به بنو الديان)\n(فخروا علي بحبوة لمحرق ... وإتاوة سلفت من النعمان)\n(ما أنت وابن محرق وقبيله ... وإتاوة اللخمي في عيلان)\n(فاقصد بذرعك قصد أمرك قصده ... ودع القبائل من بني قحطان)\n(إذ كان سالفنا الإتاوة فيهم ... أولى ففخرك فخر كل يمان)\n(وافخر برهط بني الحماس ومالك ... وابن الضباب وزعبل وقيان)\n(وأنا المنخل وابن فارس قرزل ... وأبو نزار زانني ونماني)\n(وإذا تعاظمت الأمور موازنا ... كنت المنوه باسمه والثاني)\nلما رجع القوم إلى بني عامر وثبوا على مرة بن دودان وقالوا أنت شاعر بني عامر ولم تهج بني الديان فقال\n(تكلفني هوازن فخر قوم ... يقولون الأنام لنا عبيد)\n(أبوهم مذحج وأبو أبيهم ... إذا ما عدت الآباء هود)\n(وهل لي إن فخرت بغير فخر ... مقال والأنام له شهود)\n(فإنا لم نزل لهم قطينا ... تجيء إليهم منا الوفود)\n(فإنا نضرب الأحلام صفحا ... عن العلياء أو من ذا يكيد)\n(فقولوا يا بني عيلان كنا ... لكم قنا وما عنكم محيد)\nهذا الخبر مصنوع من مصنوعات ابن الكلبي والتوليد فيه بين وشعره شعر ركيك غث لا يشبه أشعار القوم وإنما ذكرته لئلا يخلو الكتاب من شيء قد روي","topic":"أخبار أمية بن الأسكر ونسبه","topicNo":99,"sp":3,"spl":"سيدان يخطبان ابنة له جميلة","tags":["المديح","الجواري والنساء"],"loc":1766,"partial":1},
{"id":"b99-9","bab":"الجزء 10","sec":"شعره في يوم المريسيع","page":"ج10 ص26","text":"وقال محمد بن حبيب فيما روى عنه أبو سعيد السكري ونسخته من كتابه قال أبو عمرو الشيباني أصيب قوم من بني جندع بن ليث بن بكر بن هوازن رهط أمية بن\nالأسكر يقال لهم بنو زبينة أصابهم أصحاب النبي يوم المريسيع في غزوته بني المصطلق وكانوا جيرانه يومئذ ومعهم ناس من بني لحيان من هذيل ومع بني جندع رجل من خزاعة يقال له طارق فاتهمه بنو ليث بهم وأنه دل عليهم وكانت خزاعة مسلمها ومشركها يميلون إلى النبي على قريش فقال أمية بن الأسكر لطارق الخزاعي\n(لعمرك إني والخزاعي طارقا ... كنعجة عاد حتفها تتحفر)\n(أثارت عليها شفرة بكراعها ... فظلت بها من آخر الليل تجزر)\n(شمت بقوم هم صديقك أهلكوا ... أصابهم يوم من الدهر أعسر)\n(كأنك لم تنبأ بيوم ذؤالة ... ويوم الرجيع إذ تنحر حبتر)\n(فهلا أباكم في هذيل وعمكم ... ثأرتم وهم أعدى قلوبا وأوتر)\n(ويوم الأراك يوم أردف سبيكم ... صميم سراة الديل عبد ويعمر)\n(وسعد بن ليث إذ تسل نساؤكم ... وكلب بن عوف نحروكم وعقروا)\n(عجبت لشيخ من ربيعة مهتر ... أمر له يوم من الدهر منكر)\nأجابه طارق الخزاعي فقال\n(لعمرك ما أدري وإني لقائل ... إلى أي من يظنني أتعذر)\n(أعنف أن كانت زبينة أهلكت ... ونال بني لحيان شر ونفروا)\nهذه الأبيات الابتداء والجواب تمثل بابتدائها ابن عباس في رسالة إلى معاوية وتمثل بجوابها معاوية في رسالة أجابه بها حدثني بذلك أحمد بن عيسى بن أبي موسى العجلي العطار بالكوفة\nقال حدثنا الحسين بن نصر بن مزاحم المنقري قال حدثنا زيد بن المعذل النمري قال حدثنا يحيى بن شعيب الخراز قال حدثنا أبو مخنف قال لما بلغ معاوية مصاب أمير المؤمنين علي عليه السلام دس رجلا من بني القين إلى البصرة يتجسس الأخبار ويكتب بها إليه فدل على القيني بالبصرة في بني سليم فأخذ وقتل وكتب ابن عباس من البصرة إلى معاوية أما بعد فإنك ودسك أخا بني القين إلى البصرة تلتمس من غفلات قريش مثل الذي ظفرت به من يمانيتك لكما قال الشاعر\nلعمرك إني والخزاعي طارقا ... كنعجة عاد حتفها تتحفر أثارت عليها شفرة بكراعها ... فظلت بها من آخر الليل تجزر شمت بقوم هم صديقك أهلكوا ... أصابهم يوم من الدهر أمعر\nأجابه معاوية أما بعد فإن الحسن قد كتب إلي بنحو مما كتبت به وأنبني بما لم أجن ظنا وسوء رأي وإنك لم تصب مثلنا ولكن مثلنا ومثلكم كما قال طارق الخزاعي\n(فوالله ما أدري وإني لصادق ... إلى أي من يظنني أتعذر)\n(أعنف أن كانت زبينة أهلكت ... ونال بني لحيان شر ونفروا)\n\n(أبني إني قد كبرت ورابني ... بصري وفي لمصلح مستمتع)\n(فلئن كبرت لقد دنوت من البلى ... اوحلت لكم مني خلائق أربع)\nروضه من الكامل والشعر لعبدة بن الطبيب والغناء لابن محرز ولحنه من القدر الأوسط من الثقيل الأول بالبنصر في مجراها عن إسحاق وفيه لمعبد خفيف ثقيل أول بالبنصر في مجراها عنه أيضا","topic":"أخبار أمية بن الأسكر ونسبه","topicNo":99,"sp":4,"spl":"شعره في يوم المريسيع","tags":[],"song":1,"loc":1767},
{"id":"b100-2","bab":"الجزء 10","sec":"نسب عبدة بن الطبيب وأخباره — أجاد الشعر ولم يكثر","page":"ج10 ص29 – ج10 ص30","text":"هو فيما ذكر ابن حبيب عن ابن الأعرابي وأبو نصر أحمد بن حاتم عن الأصمعي وأبي عمرو الشيباني وأبي فروة العكلي عبدة بن الطبيب والطبيب اسمه يزيد بن عمرو بن وعلة بن أنس بن عبد الله بن عبد تيم بن جشم بن عبد شمس ويقال عبشمس بن سعد بن زيد مناة بن تميم وقال ابن حبيب خاصة وقد أخبرني أبو عبيدة قال تميم كلها كانت في الجاهلية يقال لها عبد تيم وتيم صنم كان لهم يعبدونه\nوعبدة شاعر مجيد ليس بالمكثر وهو مخضرم أدرك الإسلام فأسلم وكان في جيش النعمان بن المقرن الذين حاربوا معه الفرس بالمدائن وقد ذكر ذلك في قصيدته التي أولها\n(هل حبل خولة بعد الهجر موصول ... أم أنت عنها بعيد الدار مشغول)\n(حلت خويلة في دار مجاورة ... أهل المدينة فيها الديك والفيل)\n(يقارعون رؤوس العجم ضاحية ... منهم فوارس لا عزل ولا ميل)\nخبرني محمد بن العباس اليزيدي قال حدثني عبد الرحمن ابن أخي الأصمعي عن عمه قال أرثى بيت قالته العرب قول عبدة بن الطبيب\n(فما كان قيس هلكه هلك واحد ... ولكنه بنيان قوم تهدما)\nوتمام هذه الأبيات أنشدناه علي بن سليمان الأخفش عن السكري والمبرد والأحول لعبدة يرثي قيسا\n(عليك سلام الله قيس بن عاصم ... ورحمته ما شاء أن يترحما)\n(تحية من أوليته منك نعمة ... إذا زار عن شحط بلادك سلما)\n(وما كان قيس هلكه هلك واحد ... ولكنه بنيان قوم تهدما)","topic":"نسب عبدة بن الطبيب وأخباره","topicNo":100,"sp":0,"spl":"نسب عبدة بن الطبيب وأخباره — أجاد الشعر ولم يكثر — كان يترفع عن الهجاء ويراه ضعة","tags":["اللهو والمزاح"],"loc":1768},
{"id":"b100-3","bab":"الجزء 10","sec":"كان يترفع عن الهجاء ويراه ضعة","page":"ج10 ص31","text":"أخبرني محمد بن الحسن بن دريد قال حدثنا أبو عثمان الأشنانداني عن التوزي عن أبي عبيدة عن يونس قال قال رجل لخالد بن صفوان كان عبدة بن الطبيب لا يحسن أن يهجو فقال لا تقل ذاك فوالله ما أبى من عي ولكنه كان يترفع عن الهجاء ويراه ضعة كما يرى تركه مروءة وشرفا قال\n(وأجرأ من رأيت بظهر غيب ... على عيب الرجال أولو العيوب)\nخبرني محمد بن القاسم الأنباري قال حدثنا أحمد بن يحيى ثعلب عن ابن الأعرابي أن عبد الملك بن مروان قال يوما لجلسائه أي المناديل أشرف فقال قائل منهم مناديل مصر كأنها غرقئ البيض وقال آخرون مناديل اليمن كأنها نور الربيع فقال عبد الملك مناديل أخي بني سعد عبدة بن الطبيب قال\n(لما نزلنا نصبنا ظل أخبية ... وفار للقوم باللحم المراجيل)\n(ورد وأشقر ما يؤنيه طابخه ... ما غير الغلي منه فهو مأكول)\n(ثمت قمنا إلى جرد مسومة ... أعرافهن لأيدينا مناديل)\nعني بالمراجيل المراجل فزاد فيها الياء ضرورة\n(إن الليالي أسرعت في نقضي ... أخذن بعضي وتركن بعضي)\n(حنين طولي وطوين عرضي ... أقعدنني من بعد طول نهض)\nروضه من الرجز الشعر للأغلب العجلي والغناء لعمرو بن بانة هزج بالبنصر","topic":"نسب عبدة بن الطبيب وأخباره","topicNo":100,"sp":0,"spl":"نسب عبدة بن الطبيب وأخباره — أجاد الشعر ولم يكثر — كان يترفع عن الهجاء ويراه ضعة","tags":["الهجاء"],"song":1,"loc":1769},
{"id":"b101-2","bab":"الجزء 10","sec":"أخبار الأغلب ونسبه — هو أول من رجز الأراجيز من العرب","page":"ج10 ص32 – ج10 ص33","text":"هو فيما ذكر ابن قتيبة الأغلب بن جشم بن سعد بن عجل بن لجيم بن صعب بن علي بن بكر بن وائل وهو أحد المعمرين عمر في الجاهلية عمرا طويلا وأدرك الإسلام فأسلم وحسن إسلامه وهاجر ثم كان فيمن توجه إلى الكوفة مع سعد ابن أبي وقاص فنزلها واستشهد في وقعة بنهاوند فقبره هناك في قبور الشهداء\nويقال إنه أول من رجز الأراجيز الطوال من العرب وإياه عنى الحجاج بقوله مفتخرا\n(إني أنا الأغلب أمسى قد نشد ... )\nقال ابن حبيب كانت العرب تقول الرجز في الحرب والحداء والمفاخرة وما جرى هذا المجرى فتأتي منه بأبيات يسيرة فكان الأغلب أول من قصد الرجز ثم سلك الناس بعده طريقته أخبرنا الفضل بن الحباب الجمحي أبو خليفة في كتابه إلينا قال أخبرنا محمد بن سلام قال حدثنا الأصمعي وأخبرنا أحمد بن محمد أبو الحسن الأسدي قال حدثنا الرياشي قال حدثنا معمر بن عبد الوارث عن أبي عمرو بن العلاء قال كانت للأغلب سرحة يصعد عليها ثم يرتجز\n(قد عرفتني سرحتي فأطت ... وقد شمطت بعدها واشمطت)\nاعترضه رجل من بني سعد ثم أحد بني الحارث بن عمرو بن كعب ابن سعد فقال له","topic":"أخبار الأغلب ونسبه","topicNo":101,"sp":0,"spl":"أخبار الأغلب ونسبه — هو أول من رجز الأراجيز من العرب — شعره في سجاح حين تزوجت مسيلمة الكذا","tags":["الحب والغزل","السفر والحج"],"loc":1770,"partial":1},
{"id":"b101-3","bab":"الجزء 10","sec":"أنشد من شعر الجاهلية فأنقص عمر عطاءه","page":"ج10 ص34","text":"(قبحت من سالفة ومن قفا ... عبد إذا ما رسب القوم طفا)\n(كما شرار الرعي أطراف السفى ... )\nأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني محمد بن عباد بن حبيب المهلبي قال حدثني نصر بن ناب عن داود بن أبي هند عن الشعبي قال كتب عمر بن الخطاب إلى المغيرة بن شعبة وهو على الكوفة أن اشتنشد من قبلك من شعراء قومك ما قالوا في الإسلام فأرسل إلى الأغلب العجلي فاستنشده فقال ( لقد سألت هينا موجودا ... أرجزا تريد أم قصيدا\nم أرسل إلى لبيد فقال له إن شئت مما عفا الله عنه يعني الجاهلية فعلت قال لا أنشدني ما قلت في الإسلام فانطلق لبيد فكتب سورة البقرة في صحيفة وقال أبدلني الله عز و جل بهذه في الإسلام مكان الشعر فكتب المغيرة بذلك إلى عمر فنقص عمر من عطاء الأغلب خمسمائة وجعلها في عطاء لبيد فكتب إلى عمر يا أمير المؤمنين أتنقص عطائي أن أطعتك فرد عليه خمسمائة وأقر عطاء لبيد على ألفين وخمسمائة أخبرني محمد بن عبد العزيز قال حدثنا عمر بن شبة قال\nحدثنا محمد بن حاتم قال حدثنا علي بن القاسم عن الشعبي قال دخل الأغلب على عمر فلما رآه قال هيه أنت القائل\n(أرجزا تريد أم قصيدا ... لقد سألت هينا موجوداا)\nقال يا أمير المؤمنين إنما أطعتك فكتب عمر إلى المغيرة أن أردد عليه الخمس المائة وأقر الخمس المائة للبيد","topic":"أخبار الأغلب ونسبه","topicNo":101,"sp":0,"spl":"أخبار الأغلب ونسبه — هو أول من رجز الأراجيز من العرب — شعره في سجاح حين تزوجت مسيلمة الكذا","tags":["الرواية والكتابة"],"loc":1771,"partial":1},
{"id":"b101-4","bab":"الجزء 10","sec":"شعره في سجاح حين تزوجت مسيلمة الكذاب","page":"ج10 ص36","text":"أخبرنا أبو خليفة عن محمد بن سلام قال قال الأغلب العجلي في سجاح لما تزوجت مسيلمة الكذاب\n(لقد لقيت سجاح من بعد العمى ... ملوحا في العين مجلود القرا)\n(مثل العتيق في شباب قد أتى ... من اللجيميين أصحاب القرى)\n(ليس بذي واهنة ولا نسا ... نشا بلحم وبخبز ما اشترى)\n(حتى شتا ينتح ذفراه الندى ... خاظى البضيع لحمه خظابظا)\n(كأنما جمع من لحم الخصى ... إذا تمطى بين برديه صأى)\n(كأن عرق أيره إذا ودى ... حبل عجوز ضفرت سبع قوى)\n(يمشي على قوائم خمس زكا ... يرفع وسطاهن من برد الندى)\n(قالت متى كنت أبا الخير متى ... قال حديثا لم يغيرني البلى)\n(ولم أفارق خلة لي عن قلى ... فانتسفت فيشته ذات الشوى)\n(كأن في أجلادها سبع كلى ... ما زال عنها بالحديث والمنى)\n(والخلق السفساف يردي في الردى ... قال ألا ترينه قالت أرى)\n(قال ألا أدخله قالت بلى ... فشام فيها مثل محراث الغضى)\n(يقول لما غاب فيها واستوى ... لمثلها كنت أحسيك الحسا)","topic":"أخبار الأغلب ونسبه","topicNo":101,"sp":0,"spl":"أخبار الأغلب ونسبه — هو أول من رجز الأراجيز من العرب — شعره في سجاح حين تزوجت مسيلمة الكذا","tags":["الرواية والكتابة"],"loc":1772},
{"id":"b101-5","bab":"الجزء 10","sec":"من أخبار سجاح","page":"ج10 ص37","text":"وكان من خبر سجاح وادعائها النبوة وتزويج مسيلمة الكذاب إياها ما أخبرنا به إبراهيم بن النسوي يحيى عن أبيه عن شعيب عن سيف\nأن سجاح التميمية ادعت النبوة بعد وفاة رسول الله واجتمعت عليها بنو تميم فكان فيما ادعت أنه أنزل عليها يأيها المؤمنون المتقون لنا نصف الأرض ولقريش نصفها ولكن قريشا قوم يبغون واجتمعت بنو تميم كلها إليها لتنصرها وكان فيهم الأحنف بن قيس وحارثة بن بدر ووجوه تميم كلها وكان مؤذنها شبيب بن ربعي الرياحي فعمدت في جيشها إلى مسيلمة الكذاب وهو باليمامة وقالت يا معشر تميم اقصدوا اليمامة فاضربوا فيها كل هامة وأضرموا فيها نارا ملهامة حتى تتركوها سوداء كالحمامة وقالت لبني تميم إن الله لم يجعل هذا الأمر في ربيعة وإنما جعله في مضر فاقصدوا هذا الجمع فإذا فضضتموه كررتم على قريش فسارت في قومها وهم الدهم الداهم وبلغ مسيلمة خبرها فضاق بها ذرعا وتحصن في حجر حصن اليمامة وجاءت في جيوشها فأحاطت به فأرسل إلى وجوه قومه\nوقال ما ترون قالوا نرى أن نسلم هذا الأمر إليها وتدعنا فإن لم نفعل فهو البوار وكان مسيلمة ذا دهاء فقال سأنظر في هذا الأمر ثم بعث إليها إن الله تبارك وتعالى أنزل عليك وحيا وأنزل علي فهلمي نجتمع فنتدارس ما أنزل الله علينا فمن عرف الحق تبعه واجتمعنا فأكلنا العرب أكلا بقومي وقومك\nفبعثت إليه أفعل فأمر بقبة أدم فضربت وأمر بالعود المندلي فسجر فيها وقال أكثروا من الطيب والمجمر فإن المرأة إذا شمت رائحة الطيب ذكرت الباه ففعلوا ذلك وجاءها رسوله يخبرها بأمر القبة المضروبة للاجتماع فأتته فقالت هات ما أنزل عليك فقال ألم تر كيف فعل ربك بالحبلى أخرج منها نطفة تسعى بين صفاق وحشا من بين\nذكر وأنثى وأموات وأحيا ثم إلى ربهم يكون المنتهى قالت وماذا قال ألم تر أن الله خلقنا أفواجا وجعل النساء لنا أزواجا فنولج فيهن الغراميل إيلاجا ونخرجها منهن إذا شئن إخراجا قالت فبأي شيء أمرك قال\n(ألا قومي إلى النيك ... فقد هيي لك المضجع)\n(فإن شئتي ففي البيت ... وإن شئتي ففي المخدع)\n(وإن شئتي سلقناك ... وإن شئتي على أربع)\n(وإن شئتي بثلثيه ... وإن شئتي به أجمع)\nال فقالت لا إلا به أجمع قال فقال كذا أوحى الله إلي فواقعها فلما قام عنها قالت إن مثلي لا يجري أمرها هكذا فيكون وصمة على قومي وعلي ولكني مسلمة النبوة إليك فاخطبني إلى أوليائي يزوجوك ثم أقود تميما معك\nفخرج وخرجت معه فاجتمع الحيان من حنيفة وتميم فقالت لهم سجاح إنه قرأ علي ما أنزل عليه فوجدته حقا فاتبعته ثم خطبها فزوجوه إياها وسألوه عن المهر فقال قد وضعت عنكم صلاة العصر فبنو تميم إلى الآن بالرمل لا يصلونها ويقولون هذا حق لنا ومهر كريمة منا لا نرده قال وقال شاعر من بني تميم يذكر أمر سجاح في كلمة له\n(أضحت نبيتنا أنثى نطيف بها ... وأصبحت أنبياء الله ذكرانا)\nال وسمع الزبرقان بن بدر الأحنف يومئذ وقد ذكر مسيلمة وما تلاه عليهم فقال الأحنف والله ما رأيت أحمق من هذا النبي قط فقال الزبرقان والله لأخبرن بذلك مسيلمة قال إذا والله أحلف أنك كذبت فيصدقني ويكذبك قال فأمسك الزبرقان وعلم أنه قد صدق قال وحدث الحسن البصري بهذا الحديث فقال أمن والله أبو بحر من نزول الوحي قال فأسلمت سجاح بعد ذلك وبعد قتل مسيلمة وحسن إسلامها\n(كم ليلة فيك بت أسهرها ... ولوعة من هواك أضمرها)\n(وحرقة والدموع تطفئها ... ثم يعود الجوى فيسعرها)\n(بيضاء رود الشباب قد غمست ... في خجل دائب يعصفرها)\n(الله جار لها فما امتلأت ... عيناي إلا من حيث أبصرها)\nالشعر للبحتري والغناء لعريب رمل مطلق من مجموع أغانيها وهو لحن مشهور في أيدي الناس والله أعلم","topic":"أخبار الأغلب ونسبه","topicNo":101,"sp":1,"spl":"من أخبار سجاح","tags":["الحب والغزل"],"song":1,"loc":1773},
{"id":"b102-2","bab":"الجزء 10","sec":"أخبار البحتري ونسبه — هجاؤه جيد على ندرته","page":"ج10 ص41 – ج10 ص42","text":"هو الوليد بن عبيد الله بن يحيى بن عبيد بن شملال بن جابر بن سلمة بن مسهر بن الحارث بن خيثم بن أبي حارثة بن جدي بن تدول بن بحتر بن عتود بن عثمة بن سلامان بن ثعل بن عمرو بن الغوث بن جلهمة وهو طيىء بن أدد بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان\nويكنى أبا عبادة شاعر فاضل فصيح حسن المذهب نقي الكلام مطبوع كان مشايخنا رحمة الله عليهم يختمون به الشعراء وله تصرف حسن فاضل نقي في ضروب الشعر سوى الهجاء فإن بضاعته فيه نزرة وجيده منه قليل وكان ابنه أبو الغوث يزعم أن السبب في قلة بضاعته في هذا الفن أنه لما حضره الموت دعا به\nوقال له اجمع كل شيء قلته في الهجاء ففعل فأمره بإحراقه ثم قال له يا بني هذا شيء قلته في وقت فشفيت به غيظي وكأفات به قبيحا فعل بي وقد انقضى أربي في ذلك وإن بقي روي وللناس أعقاب يورثونهم العداء والمودة\nوأخشى أن يعود عليك من هذا شيء في نفسك أو معاشك لا فائدة لك ولي فيه قال فعلمت أنه قد نصحني وأشفق علي فأحرقته أخبرني بذلك علي بن سليمان الأخفش عن أبي الغوث وهذا كما قال أبو الغوث لا فائدة لك ولا لي فيه لأن الذي وجدناه وبقي في أيدي الناس من هجائه أكثره ساقط مثل قوله في ابن شير زاد\n(نفقت نفوق الحمار الذكر ... وبان ضراطك عنا فمر)\nمثل قوله في علي بن الجهم\n(ولو أعطاك ربك ما تمنى ... لزادك منه في غلظ الأيور)\n(علام طفقت تهجوني مليا ... بما لفقت من كذب وزور)\nأشباه لهذه الأبيات ومثلها لا يشاكل طبعه ولا تليق بمذهبه وتنبيء بركاكتها وغثاثة ألفاظها عن قلة حظه في الهجاء وما يعرف له هجاء جيد إلا قصيدتان إحداهما قوله في ابن أبي قماش\n(مرت على عزمها ولم تقف ... مبدية للشنان والشنف)\nقول فيها لابن أبي قماش\n(قد كان في الواجب المحقق أن ... تعرف ما في ضميرها النطف)\n(بما تعاطيت في العيوب وما ... أوتيت من حكمة ومن لطف)\n(أما رأيت المريخ قد مازج الزهرة في الجد منه والشرف ... )\n(وأخبرتك النحوس أنكما ... في حالتي ثابت ومنصرف)\n(من أين أعلمت ذا وأنت على ... التقويم والزيج جد منعكف)\n(أما زجرت الطير العلا أو تعيفت ... المها او نظرت في الكتف)\n(رذلت في هذه الصناعة أو ... أكديت أو رمتها على الخرف)\n(لم تخط باب الدهليز منصرفا ... إلا وخلخالها مع الشنف)\nهي طويلة ولم يكن مذهبي ذكرها إلا للإخبار عن مذهبه في هذا الجنس وقصيدته في يعقوب بن الفرج النصراني فإنها وإن لم تكن في أسلوب هذه وطريقتها تجري مجرى التهكم باللفظ الطيب الخبيث المعاني وهي\n(تظن شجوني لم تعتلج ... وقد خلج البين من قد خلج)\nكان البحتري يتشبه بأبي تمام في شعره ويحذو مذهبه وينحو نحوه في البديع الذي كان أبو تمام يستعمله ويراه صاحبا وإماما ويقدمه على نفسه ويقول في الفرق بينه وبينه قول منصف إن جيد أبي تمام خير من جيده ووسطه ورديئه خير من وسط أبي تمام ورديئه وكذا حكم هو على نفسه","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":0,"spl":"أخبار البحتري ونسبه — هجاؤه جيد على ندرته","tags":["البحتري","الحب والغزل"],"loc":1774,"partial":1},
{"id":"b102-3","bab":"الجزء 10","sec":"من أشعر هو أو أبو تمام","page":"ج10 ص45","text":"أخبرني محمد بن يحيى الصولي قال حدثني الحسين بن علي الياقطاني قال قلت للبحتري أيما أشعر أنت أو أبو تمام فقال جيده خير من جيدي ورديئي خير من رديئه\nحدثني محمد بن يحيى قال حدثني أبو الغوث يحيى بن البحتري قال كان أبي يكنى أبا الحسن وأبا عبادة فأشير علي في أيام المتوكل بأن أقتصر على أبي عبادة فإنها أشهر فاقتصرت عليها\nحدثني محمد قال سمعت عبد الله بن الحسين بن سعد يقول للبحتري وقد اجتمعنا في دار عبد الله بالخلد وعنده المبرد في سنة ست وسبعين ومائتين وقد\nأنشد البحتري شعرا لنفسه قد كان أبو تمام قال في مثله أنت والله أشعر من أبي تمام في هذا الشعر قال كلا والله إن أبا تمام للرئيس والأستاذ والله ما أكلت الخبز إلا به فقال له المبرد لله درك يا أبا الحسن فإنك تأبى إلا شرفا من جميع جوانبك\nحدثني محمد قال حدثني الحسين بن إسحاق قال قلت للبحتري إن الناس يزعمون أنك أشعر من أبي تمام فقال والله ما ينفعني هذا القول ولا يضر أبا تمام والله ما أكلت الخبز إلا به ولوددت أن الأمر كان كما قالوا ولكني والله تابع له آخذ منه لائذ به نسيمي يركد عند هوائه وأرضي تنخفض عند سمائه حدثني محمد بن يحيى قال حدثني سوار بن أبي شراعة عن\nالبحتري قال وحدثني أبو عبد الله الألوسي عن علي بن يوسف عن البحتري قال كان أول أمري في الشعر ونباهتي أني صرت إلى أبي تمام وهو بحمص فعرضت عليه شعري وكان الشعراء يعرضون عليه أشعارهم فأقبل علي وترك سائر من حضر فلما تفرقوا\nقال لي أنت أشعر من أنشدني فكيف بالله حالك فشكوت خلة فكتب إلى أهل معرة النعمان وشهد لي بالحذق بالشعر وشفع لي إليهم وقال امتدحهم فصرت إليهم فأكرموني بكتابه ووظفوا لي أربعة آلاف درهم فكانت أول مال أصبته\nوقال علي بن يوسف في خبره فكانت نسخة كتابه يصل كتابي هذا على يد الوليد أبي عبادة الطائي هو على بذاذته شاعر فأكرموه حدثني جحظة قال سمعت البحتري يقول كنت أتعشق غلاما من أهل منبج يقال له شقران واتفق لي سفر فخرجت فيه فأطلت الغيبة ثم عدت وقد التحى فقلت فيه وكان أول شعر قلته\n(نبتت لحية شقران ... شقيق النفس بعدي)\n(حلقت كيف أتته ... قبل أن ينجز وعدي)","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":1,"spl":"من أشعر هو أو أبو تمام","tags":["البحتري","السفر والحج"],"loc":1775},
{"id":"b102-4","bab":"الجزء 10","sec":"كيف تم التعارف بينه وبين أبي تمام","page":"ج10 ص46","text":"وقد روي في غير هذه الحكاية أن اسم الغلام شندان حدثني علي بن سليمان قال حدثني أبو الغوث بن البحتري عن\nأبيه وحدثني عمي قال حدثني علي بن العباس النوبختي عن البحتري وقد جمعت الحكايتين وهما قريبتان قال أول ما رأيت أبا تمام أني دخلت على أبي سعيد محمد بن يوسف وقد مدحته بقصيدتي\n(أأفاق صب من هوى فافيقا ... أو خان عهدا أو أطاع شفيقا)\nسر بها أبو سعيد وقال أحسنت والله يا فتى وأجدت قال وكان في مجلسه رجل نبيل رفيع المجلس منه فوق كل من حضر عنده تكاد تمس ركبته ركبته فأقبل علي ثم\nقال يا فتى أما تستحي مني هذا شعر لي تنتحله وتنشده بحضرتي فقال له أبو سعيد أحقا تقول قال نعم وإنما علقه مني فسبقني به إليك وزاد فيه ثم اندفع فأنشد أكثر هذه القصيدة حتى شككني علم الله في نفسي وبقيت متحيرا فأقبل علي أبو سعيد فقال يا فتى قد كان في قرابتك منا وودك لنا ما يغنيك عن هذا فجعلت أحلف له بكل محرجة من الأيمان أن الشعر لي ما سبقني إليه أحد ولا سمعته منه ولا انتحلته فلم ينفع ذلك شيئا وأطرق أبو سعيد وقطع بي حتى تمنيت أني سخت في الأرض فقمت منكسر البال أجر رجلي فخرجت فما هو إلا أن بلغت باب الدار حتى خرج الغلمان فردوني فأقبل علي الرجل فقال الشعر لك يا بني والله ما قلته قط ولا سمعته إلا منك ولكنني ظننت أنك تهاونت بموضعي فأقدمت على الإنشاد بحضرتي من غير معرفة كانت بيننا تريد بذلك مضاهاتي ومكاثرتي حتى عرفني الأمير نسبك وموضعك ولوددت ألا تلد أبدا طائية إلا مثلك وجعل أبو سعيد يضحك ودعاني أبو تمام وضمني إليه وعانقني وأقبل\nيقرظني ولزمته بعد ذلك وأخذت عنه واقتديت به هذه رواية من ذكرت وقد حدثني علي بن سليمان الأخفش أيضا قال حدثني عبد الله بن الحسين بن سند القطربلي أن البحتري حدثه أنه دخل على أبي سعيد محمد بن يوسف الثغري وقد مدحه بقصيدة وقصده بها فألفى عنده أبا تمام وقد أنشده قصيدة له فيه فاستأذنه البحتري في الإنشاد وهو يومئذ حديث السن فقال له يا غلام أتنشدني بحضرة أبي تمام فقال تأذن ويستمع فقام فأنشده إياها وأبو تمام يسمع ويهتز من قرنه إلى قدمه استحسانا لها فلما فرغ منها\nقال أحسنت والله يا غلام فممن أنت قال من طيء فطرب أبو تمام وقال من طيء الحمد لله على ذلك لوددت أن كل طائية تلد مثلك وقبل بين عينيه وضمه إليه\nوقال لمحمد بن يوسف قد جعلت له جائزتي فأمر محمد بها فضمت إلى مثلها ودفعت إلى البحتري وأعطى أبا تمام مثلها وخص به وكان مداحا له طول أيامه ولابنه بعده ورثاهما بعد مقتليهما فأجاد ومراثيه فيهما أجود من مدائحه وروي أنه\nقيل له في ذلك فقال من تمام الوفاء أن تفضل المراثي المدائح لا كما قال الآخر وقد سئل عن ضعف مراثيه فقال كنا نعمل للرجاء نحن نعمل اليوم للوفاء وبينهما بعد حدثني حكم بن يحيى الكنتحي قال","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":2,"spl":"كيف تم التعارف بينه وبين أبي تمام","tags":["البحتري"],"loc":1776},
{"id":"b102-5","bab":"الجزء 10","sec":"بعض من صفاته","page":"ج10 ص49","text":"كان البحتري من أوسخ خلق الله ثوبا وآلة وأبخلهم على كل شيء وكان له أخ وغلام معه في داره فكان يقتلهما جوعا فإذا بلغ منهما الجوع أتياه يبكيان فيرمي إليهما بثمن أقواتهما مضيقا مقترا ويقول كلا أجاع الله أكبادكما وأعرى أجلادكما وأطال إجهادكما\nقال حكم بن يحيى وأنشدته يوما من شعر أبي سهل بن نوبخت فجعل يحرك رأسه فقلت له ما تقول فيه فقال هو يشبه مضغ الماء ليس له طعم ولا معنى\nوحدثني أبو مسلم محمد بن بحر الأصبهاني الكاتب قال دخلت على البحتري يوما فاحتبسني عنده ودعا بطعام له ودعاني إليه فامتنعت من أكله وعنده شيخ شامي لا أعرفه فدعاه إلى الطعام فتقدم وأكل معه أكلا عنيفا فغاظه ذلك والتفت إلي فقال لي أتعرف هذا الشيخ فقلت لا قال هذا شيخ من بني الهجيم الذين يقول فيهم الشاعر\n(وبنو الهجيم قبيلة ملعونة ... حص اللحى متشابهو الألوان)\n(لو يسمعون بأكلة أو شربة ... بعمان أصبح جمعهم بعمان)\nال فجعل الشيخ يشتمه ونحن نضحك وحدثني جحظة قال حدثني علي بن يحيى المنجم قال\nاجتازت جارية بالمتوكل معها كوز ماء وهي أحسن من القمر فقال لها ما اسمك قالت برهان قال ولمن هذا الماء قالت لستي قبيحة قال صبيه في حلقي فشربه عن آخره ثم قال للبحتري قل في هذا شيئا فقال البحتري\n(ما شربة من رحيق كأسها ذهب ... جاءت بها الحور من جنات رضوان)\n(يوما بأطيب من ماء بلا عطش ... شربته عبثا من كف برهان)\nخبرني علي بن سليمان الأخفش وأحمد بن جعفر جحظة قالا حدثنا أبو الغوث بن البحتري قال كتبت إلى أبي يوما أطلب منه نبيذا فبعث إلي بنصف قنينة دردي وكتب إلي دونكها يا بني فإنها تكشف القحط وتضبط الرهط قال الأخفش وتقيت الرهط","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":3,"spl":"بعض من صفاته — خبره مع أحمد بن علي الإسكافي","tags":["البحتري"],"loc":1777},
{"id":"b102-6","bab":"الجزء 10","sec":"خبره مع أحمد بن علي الإسكافي","page":"ج10 ص50","text":"حدثني أبو الفضل عباس بن أحمد بن ثوابة قال قدم البحتري النيل على أحمد بن علي الإسكافي مادحا له فلم يثبه ثوابا يرضاه بعد أن طالت مدته عنده فهجاه بقصيدته التي يقول فيها\n(ما كسبنا من أحمد بن علي ... ومن النيل غير حمى النيل)\nوهجاه بقصيدة أخرى أولها\n(قصة النيل فاسمعوها عجابه ... )\nجمع إلى هجائه إياه هجاء أبي ثوابة وبلغ ذلك أبي فبعث إليه بألف درهم وثياب ودابة بسرجها ولجامها فرده إليه وقال قد أسلفتكم إساءة لا يجوز معها قبول رفدكم فكتب إليه أبي أما الإساءة فمغفورة وأما المعذرة فمشكورة والحسنات يذهبن السيئات وما يأسو جراحك مثل يدك ولقد رددت إليك ما رددته علي وأضعفته فإن تلافيت ما فرط منك أثبنا وشكرنا وإن لم تفعل احتملنا وصبرنا فقبل ما بعث به وكتب إليه كلامك والله أحسن من شعري وقد أسلفتني ما أخجلني وحملتني ما اثقلني وسيأتيك ثنائي ثم غدا إليه بقصيدة أولها\n(ضلال لها ماذا أرادت إلى الصد ... )\nقال فيه بعد ذلك\n(برق أضاء العقيق من ضرمه ... )\nقال فيه أيضا\n(دان دعا داعي الصبا فأجابه ... )\nال ولم يزل أبي يصله بعد ذلك ويتابع بره لديه حتى افترقا","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":3,"spl":"بعض من صفاته — خبره مع أحمد بن علي الإسكافي","tags":["البحتري","الهجاء"],"loc":1778,"partial":1},
{"id":"b102-7","bab":"الجزء 10","sec":"شعره في نسيم غلامه","page":"ج10 ص51","text":"أخبرني جحظة قال كان نسيم غلام البحتري الذي يقول فيه\n(دعا عبرتي تجري على الجور والقصد ... ظن نسيما قارف الهم من بعدي)\n(خلا ناظري من طيفه بعد شخصه ... فيا عجبا للدهر فقد على فقد)\nلاما روميا ليس بحسن الوجه وكان قد جعله بابا من أبواب الحيل على الناس فكان يبيعه ويعتمد أن يصيره إلى ملك بعض أهل المروءات ومن ينفق عنده الأدب فإذا حصل في ملكه شبب به وتشوقه ومدح مولاه حتى يهبه له فلم يزل ذلك دأبه حتى مات نسيم فكفي الناس أمره\nأخبرني علي بن سليمان الأخفش قال كتب البحتري إلى أبي محمد بن علي القمي يستهديه نبيذا فبعث إليه نبيذا مع غلام له أمرد فجمشه البحتري فغضب الغلام غضبا شديدا دل البحتري على أنه سيخبر مولاه بما جرى فكتب إليه\n(أبا جعفر كان تجميشنا ... غلامك إحدى الهنات الدنيه)\n(بعثت إلينا بشمس المدام ... تضيء لنا مع شمس البريه)\n(فليت الهدية كان الرسول ... وليت الرسول إلينا الهديه)\nبعث إليه محمد بن علي الغلام هدية فانقطع البحتري عنه بعد ذلك مدة خجلا مما جرى فكتب إليه محمد بن علي\n(هجرت كأن البر أعقب حشمة ... ولم أر وصلا قبل ذا أعقب الهجرا)\nقال فيه قصيدته التي أولها\n(فتى مذحج عفوا فتى مذحج غفرا ... )\nهي طويلة وقال فيه أيضا\n(أمواهب هاتيك أم أنواء ... هطل وأخذ ذاك أم إعطاء)\n(إن دام ذا أو بعض ذا من فعل ذا ... ذهب السخاء فلا يعد سخاء)\n(ليس الذي حلت تميم وسطه الدهناء ... لكن صدرك الدهناء)\n(ملك أغر لآل طلحة مجده ... كفاه بحر سماحة وسماء)\n(وشريف أشراف إذا احتكت بهم ... جرب القبائل أحسنوا وأساءوا)\n(أمحمد بن علي اسمع عذرة ... فيها شفاء للمسيء وداء)\n(مالي إذا ذكر الكرام رأيتني ... مالي مع النفر الكرام وفاء)\n(يضفو علي العذل وهو مقارب ... ويضيق عني العذر وهو فضاء)\n(إني هجرتك إذ هجرتك حشمة ... لا العود يذهبها ولا الإبداء)\n(أخجلتني بندى يديك فسودت ... ما بيننا تلك اليد البيضاء)\n(وقطعتني بالبر حتى إنني ... متوهم أن لا يكون لقاء)\n(صلة غدت في الناس وهي قطيعة ... عجبا وبر راح وهو جفاء)\n(ليواصلنك ركب شعري سائرا ... تهدى به في مدحك الأعداء)\n(حتى يتم لك الثناء مخلدا ... أبدا كما دامت لك النعماء)\n(فتظل تحسدك الملوك الصيد بي ... وأظل يحسدني بك الشعراء)","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":4,"spl":"شعره في نسيم غلامه — مات في السكتة","tags":["البحتري","المديح"],"loc":1779,"partial":1},
{"id":"b102-8","bab":"الجزء 10","sec":"مات في السكتة","page":"ج10 ص53","text":"أخبرني علي بن سليمان الأخفش قال سألني القاسم بن عبيد الله عن\nخبر البحتري وقد كان أسكت ومات من تلك العلة فأخبرته بوفاته وأنه مات في تلك السكتة فقال ويحه رمي في أحسنه أخبرني محمد بن يحيى قال حدثني محمد بن علي الأنباري قال سمعت البحتري يقول أنشدني أبو تمام يوما لنفسه\n(وسابح هطل التعداء هتان ... على الجراء أمين غير خوان)\n(أظمى الفصوص ولم تظمأ قوائمه ... فخل عينيك في ظمآن ريان)\n(فلو تراه مشيحا والحصى زيم ... بين السنابك من مثنى وؤحدان)\n(أيقنت إن لم تثبت أن حافره ... من صخر تدمر أو من وجه عثمان)\nم قال لي ما هذا الشعر قلت لا أدري قال هذا هو المستطرد أو قال الاستطراد قلت وما معنى ذلك قال يريك أنه يريد وصف الفرس وهو يريد هجاء عثمان وقد فعل البحتري ذلك فقال في صفة الفرس\n(ما إن يعاف قذى ولو أوردته ... يوما خلائق حمدويه الأحول)\nكان حمدويه الأحول عدوا لمحمد بن علي القمي الممتدح بهذه القصيدة فهجاه في عرض مدحه محمدا والله أعلم","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":4,"spl":"شعره في نسيم غلامه — مات في السكتة","tags":["البحتري","الهجاء"],"loc":1780},
{"id":"b102-9","bab":"الجزء 10","sec":"رأي أبي تمام في شاعريته","page":"ج10 ص55","text":"حدثني علي بن سليمان الأخفش قال حدثني أبو الغوث بن البحتري قال حدثني أبي قال قال لي أبو تمام بلغني أن بني حميد أعطوك مالا جليلا فيما مدحتهم به فأنشدني شيئا منه فأنشدته بعض ما قلته فيهم فقال لي كم أعطوك فقلت كذا وكذا فقال ظلموك والله ما وفوك حقك فلم استكثرت ما دفعوه إليك والله لبيت منها خير مما أخذت ثم أطرق قليلا ثم\nقال لعمري لقد استكثرت ذلك واستكثر لك لما مات الناس وذهب الكرام وغاضت المكارم فكسدت سوق الأدب أنت والله يا بني أمير الشعراء غدا بعدي فقمت فقبلت رأسه ويديه ورجليه وقلت له والله لهذا القول أسر إلى قلبي وأقوى لنفسي مما وصل إلي من القوم حدثني محمد بن يحيى عن الحسن بن علي الكاتب قال قال لي البحتري أنشدت أبا تمام يوما شيئا من شعري فتمثل ببيت أوس بن حجر\n(إذا مقرم منا ذرا حد نابه ... تخمط فينا ناب آخر مقرم)\nم قال لي نعيت والله إلي نفسي فقلت أعيذك بالله من هذا القول فقال إن عمري لن يطول وقد نشأ في طيء مثلك أما علمت أن خالد\nابن صفوان رأى شبيب بن شيبة وهو من رهطه يتكلم فقال يا بني لقد نعى إلي نفسي إحسانك في كلامك لأنا أهل بيت ما نشأ فينا خطيب قط إلا مات من قبله فقلت له بل يبقيك الله ويجعلني فداءك قال ومات أبو تمام بعد سنة","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":5,"spl":"رأي أبي تمام في شاعريته — شعره في المتوكل","tags":["البحتري","المديح"],"loc":1781},
{"id":"b102-10","bab":"الجزء 10","sec":"شعره في المتوكل","page":"ج10 ص56","text":"حدثني أحمد بن جعفر جحظة قال حدثني أبو العنبس الصيمري قال كنت عند المتوكل والبحتري ينشده\n(عن أي ثغر تبتسم ... وبأي طرف تحتكم)\nتى بلغ إلى قوله\n(قل للخليفة جعفر المتوكل ... بن المعتصم)\n(المبتدي للمجتدي ... والمنعم بن المنتقم)\n(اسلم لدين محمد ... فإذا سلمت فقد سلم)\nال وكان البحتري من أبغض الناس إنشادا يتشادق ويتزاور في مشيه مرة جانبا ومرة القهقرى ويهز رأسه مرة ومنكبيه أخرى ويشير بكمه ويقف عند كل بيت ويقول أحسنت والله ثم يقبل على المستمعين فيقول ما لكم لا تقولون أحسنت هذا والله ما لا يحسن أحد\nأن يقول مثله فضجر المتوكل من ذلك وأقبل علي وقال أما تسمع يا صيمري ما يقول فقلت بلى يا سيدي فمرني فيه بما أحببت فقال بحياتي اهجه على هذا الروي الذي أنشدنيه فقلت تأمر ابن حمدون أن يكتب ما أقول فدعا بدواة وقرطاس وحضرني على البديهة أن قلت","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":5,"spl":"رأي أبي تمام في شاعريته — شعره في المتوكل","tags":["البحتري"],"loc":1782},
{"id":"b102-11","bab":"الجزء 10","sec":"المتوكل يأمر الصيمري أن يهجوه","page":"ج10 ص57","text":"(أدخلت رأسك في الرحم ... وعلمت أنك تنهزم)\n(يا بحتري حذار ويحك ... من قضاقضة ضغم)\n(فلقد أسلت بوادييك ... من الهجا سيل العرم)\n(فبأي عرض تعتصم ... وبهتكه جف القلم)\n(والله حلفة صادق ... وبقبر أحمد والحرم)\n(وبحق جعفر الإمام ... ابن الإمام المعتصم)\n(لأصيرنك شهرة ... بين المسيل إلى العلم)\n(حي الطلول بذي سلم ... حيث الأراكة والخيم)\n(يا بن الثقيلة والثقيل ... على قلوب ذوي النعم)\n(وعلى الصغير مع الكبير ... من الموالي والحشم)\n(في أي سلح ترتطم ... وبأي كف تلتقم)\n(يا بن المباحة للورى ... أمن العفاف أم التهم)\n(إذ رحل أختك للعجم ... وفراش أمك في الظلم)\n(وبباب دارك حانة ... في بيته يؤتى الحكم)\nال فغضب وخرج يعدو وجعلت أصيح به\n(أدخلت رأسك في الرحم ... وعلمت أنك تنهزم)\nالمتوكل يضحك ويصفق حتى غاب عن عينه هكذا حدثني جحظة عن أبي العنبس ووجدت هذه الحكاية بعينها بخط الشاهيني حكاية عن أبي العنبس فرأيتها قريبة اللفظ موافقة المعنى لما ذكره جحظة والذي يتعارفه الناس أن أبا العنبس قال هذه الأبيات ارتجالا وكان واقفا خلف البحتري فلما ابتدأ وأنشد قصيدته\n(عن اي ثغر تبتسم ... وبأي طرف تحتكم)\nصاح به أبو العنبس من خلفه\n(في أي سلح ترتطم ... وبأي كف تلتقم)\n(أدخلت رأسك في الرحم ... وعلمت أنك تنهزم)\nغضب البحتري وخرج فضحك المتوكل حتى أكثر وأمر لأبي العنبس بعشرة آلاف درهم والله أعلم وأخبرني بهذا الخبر محمد بن يحيى الصولي وحدثني عبد الله بن أحمد بن حمدون عن أبيه قال وحدثني يحيى بن علي عن أبيه أن البحتري أنشد المتوكل وأبو العنبس الصيمري حاضر قصيدته\n(عن أي ثغر تبتسم ... وبأي طرف تحتكم)\nلى آخرها وكان إذا أنشد يختال ويعجب بما يأتي به فإذا فرغ من القصيدة رد البيت الأول فلما رده بعد فراغه منها وقال\n(عن أي ثغر تبتسم ... وبأي طرف تحتكم)\nال أبو العنبس وقد غمزه المتوكل أن يولع به\n(في أي سلح ترتطم ... وبأي كف تلتقم)\n(أدخلت رأسك في الرحم ... وعلمت أنك تنهزم)\nقال نصف البيت الثاني فلما سمع البحتري قوله ولى مغضبا فجعل أبو العنبس يصيح به\n(وعلمت أنك تنهزم ... )\nضحك المتوكل من ذلك حتى غلب وأمر لأبي العنبس بالصلة التي أعدت للبحتري قال أحمد بن زياد فحدثني أبي قال جاءني البحتري فقال لي يا أبا خالد أنت عشيرتي وابن عمي وصديقي وقد رأيت ما جرى علي أفتأذن لي أن أخرج إلى منبج بغير إذن فقد ضاع العلم وهلك الأدب فقلت لا تفعل من هذا شيئا فإن الملوك تمزح بأعظم مما جرى ومضيت معه إلى الفتح فشكا إليه ذلك فقال له نحوا من قولي ووصله وخلع عليه فسكن إلى ذلك","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":6,"spl":"المتوكل يأمر الصيمري أن يهجوه — الصيمري يصر على هجائه بعد موت المتوكل","tags":["البحتري","الهجاء"],"loc":1783,"partial":1},
{"id":"b102-12","bab":"الجزء 10","sec":"الصيمري يصر على هجائه بعد موت المتوكل","page":"ج10 ص59","text":"حدثني جحظة عن علي بن يحيى المنجم قال لما قتل المتوكل قال أبو العنبس الصيمري\n(يا وحشة الدنيا على جعفر ... على الهمام الملك الأزهر)\n(على قتيل من بني هاشم ... بين سرير الملك والمنبر)\n(والله رب البيت والمشعر ... والله أن لو قتل البحتري)\n(لثار بالشام له ثائر ... في ألف نغل من بني عض خرى)\n(يقدمهم كل أخي ذلة ... على حمار دابر أعور)\nشاعت الأبيات حتى بلغت البحتري فضحك ثم قال هذا الأحمق يرى أني أجيبه على مثل هذا فلو عاش امرؤ القيس فقال من كان يجيبه","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":6,"spl":"المتوكل يأمر الصيمري أن يهجوه — الصيمري يصر على هجائه بعد موت المتوكل","tags":["البحتري"],"loc":1784},
{"id":"b102-13","bab":"الجزء 10","sec":"منزلتها في الغناء والشعر والخط","page":"ج10 ص61","text":"كانت عريب مغنية محسنة وشاعرة صالحة الشعر وكانت مليحة الخط والمذهب في الكلام ونهاية في الحسن والجمال والظرف وحسن الصورة وجودة الضرب وإتقان الصنعة والمعرفة بالنعم والأوتار والرواية للشعر والأدب لم يتعلق بها أحد من نظرائها ولا رئي في النساء بعد القيان الحجازيات القديمات مثل جميلة وعزة الميلاء وسلامة الزرقاء ومن جرى مجراهن على قلة عددهن نظير لها وكانت فيها من الفضائل التي وصفناها ما ليس لهن مما يكون لمثلها من جواري الخلفاء ومن نشأ في\nقصور الخلافة وغذي برقيق العيش الذي لا يدانيه عيش الحجاز والنش بين العامة والعرب الجفاة ومن غلظ طبعه وقد شهد لها بذلك من لا يحتاج مع شهادته إلى غيره\nأخبرني محمد بن خلف وكيع عن حماد بن إسحاق قال قال لي أبي ما رأيت امرأة أضرب من عريب ولاأحسن صنعة ولا أحسن وجها ولا أخف روحا ولا أحسن خطابا ولا أسرع جوابا ولا ألعب بالشطرنج والنرد ولا أجمع لخصلة حسنة لم أر مثلها في امرأة غيرها\nقال حماد فذكرت ذلك ليحيى بن أكثم في حياة أبي فقال صدق أبو محمد هي كذلك قلت أفسمعتها قال نعم هناك يعني في دار المأمون قلت أفكانت كما\nذكر أبو محمد في الحذق فقال يحيى هذه مسألة الجواب فيها على أبيك فهو أعلم مني بها فأخبرت بذلك أبي فضحك ثم قال ما استحييت من قاضي القضاة أن تسأله عن مثل هذا أخبرنا يحيى بن علي بن يحيى\nقال حدثني أبي قال قال لي إسحاق كانت عندي صناجة كنت بها معجبا واشتهاها أبو إسحاق المعتصم في خلافة المأمون فبينا أنا ذات يوم في منزلي إذ أتاني إنسان يدق الباب دقا شديدا فقلت أنظروا من هذا فقالوا رسول أمير المؤمنين فقلت ذهبت صناجتي تجده ذكرها له ذاكر فبعث إلي فيها فلما مضى بي الرسول انتهيت إلى الباب وأنا مثخن فدخلت فسلمت فرد علي السلام ونظر إلى تغير وجهي فقال لي اسكن فسكنت فقال\nلي غن صوتا وقال لي أتدري لمن هو فقلت أسمعه ثم أخبر أمير المؤمنين إن شاء الله ذلك فأمر جارية من وراء الستارة فغنته وضربت فإذا هي قد شبهته بالغناء القديم فقلت زدني معها عودا آخر فإنه أثبت لي فزادني عودا آخر فقلت هذا الصوت محدث لامرأة ضاربة قال من أين قلت ذاك قلت لما سمعت لينه عرفت أنه محدث من غناء النساء ولما رأيت جودة مقاطعه علمت أن صاحبته ضاربة وقد حفظت مقاطعه وأجزاءه ثم طلبت عودا آخر فلم أشك فقال صدقت الغناء لعريب","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":7,"spl":"منزلتها في الغناء والشعر والخط","tags":["البحتري"],"loc":1785},
{"id":"b102-14","bab":"الجزء 10","sec":"عدت أصواتها فكانت ألفا","page":"ج10 ص63","text":"قال ابن المعتز وقال يحيى بن علي أمرني المعتمد على الله أن أجمع غناءها الذي صنعته فأخذت منها دفاترها وصحفها التي كانت قد جمعت فيها غناءها فكتبته فكان ألف\nوأخبرني علي بن عبد العزيز عن ابن خرداذبه أنه سأل عريب عن صنعتها فقالت قد بلغت إلى هذا الوقت ألف صوت وحدثني محمد بن إبراهيم قريض أنه جمع غناءها من ديواني ابن المعتز وأبي العبيس بن حمدون وما أخذه عن بدعة جاريتها التي أعطاها إياها بنو هاشم فقابل بعضه ببعض فكان ألفا ومائة وخمسة وعشرين صوتا وذكر العتابي أن أحمد بن يحيى حدثه قال\nسمعت أبا عبد الله الهشامي يقول وقد ذكرت صنعة عريب صنعتها مثل قول أبي دلف في خالد بن يزيد حيث يقول\n(يا عين بكى خالدا ... ألفا ويدعى واحدا)\nيريد أن غناءها ألف صوت في معنى واحد فهي بمنزلة صوت واحد وحكى عنه أيضا هذه الحكاية ابن المعتز وهذا تحامل لا يحل ولعمري إن في صنعتها لأشياء مرذولة لينة وليس ذلك مما يضعها ولا عري كبير أحد من المغنين القدماء والمتأخرين من أن يكون في صنعته النادر والمتوسط سوى قوم معدودين مثل ابن محرز ومعبد في القدماء ومثل إسحاق وحده في المتأخرين وقد عيب بمثل هذا ابن سريج في محله فبلغه أن المغنين يقولون إنما يغني ابن سريج الأرمال والخفاف وغناؤه يصلح للأعراس والولائم فبلغه ذلك فتغنى بقوله\n(لقد حببت نعم إلينا بوجهها ... مساكن ما بين الوتائر فالنقع)\nم توفي بعدها وغناؤه يجري مجرى المعيب عليه وهذا إسحاق يقول في أبيه على عظيم محله في هذه الصناعة وما كان إسحاق يشيد به من\nذكره وتفضيله على ابن جامع وغيره ولأبي ستمائة صوت منها مائتان تشبه فيها بالقديم وأتى بها في نهاية من الجودة ومائتان غناء وسط مثل أغاني سائر الناس ومائتان فلسية وددت أنه لم يظهرها وينسبها لنفسه فأسترها عليه فإذا كان هذا قول إسحاق في أبيه فمن يعتذر بعده من أن يكون له جيد ورديء وما عري أحد في صناعة من الصناعة من حال ينقصه عن الغاية لأن الكمال شيء تفرد الله العظيم به والنقصان جبلة طبع بني آدم عليها وليس ذلك إذا وجد في بعض أغاني عريب مما يدعو إلى إسقاط سائرها ويلزمه اسم الضعف واللين وحسب المحتج لها شهادة إسحاق بتفضيلها وقلما شهد لأحد أو سلم خلق وإن تقدم وأجمع على فضله من شينه إياه وطعنه عليه لنفاسته في هذه الصناعة واستصغاره أهلها فقد تقدم في أخباره مع علوية ومخارق وعمرو بن بانة وسليم بن سلام وحسين بن محرز ومن قبلهم ومن فوقهم مثل ابن جامع وإبراهيم بن المهدي وتهجينه إياهم وموافقته لهم على خطئهم فيما غنوه وصنعوه مما يستغنى به عن الإعادة في هذا الموضع فإذا انضاف فعله هذا بهم وتفضيله إياها كان ذلك أدل دليل على التحامل ممن طعن عليها وإبطاله فيما ذكرها به ولقائل ذلك وهو أبو عبد الله الهشامي سبب كان يصطنعه عليها فدعاه إلى ما قال نذكره بعد هذا إن شاء الله تعالى ومما يدل على إبطاله أن المأمون أراد أن يمتحن إسحاق في المعرفة\nبالغناء القديم والحديث فامتحنه بصوت من غنائها من صنعتها فكاد يجوز عليه لولا أنه أطال الفكر والتلوم واستثبت مع علمه بالمذاهب في الصنعة وتقدمه في معرفة النغم وعللها والإيقاعات ومجاريها وأخبرنا بذلك يحيى بن علي بن يحيى قال حدثني أبي عن إسحاق فأما السبب الذي كان من أجله يعاديها الهشامي فأخبرني به يحيى بن محمد بن عبد الله بن طاهر قال ذكر لأبي أحمد عبيد الله بن عبد الله بن طاهر عمي أن الهشامي زعم أن أحسن صوت صنعته عريب\n(صاح قد لمت ظالما ... )\nأن غناءها بمنزلة قول أبي دلف في خالد\n(يا عين بكى خالدا ... ألفا ويدعى واحدا)\nفقال ليس الأمر كما ذكر ولعريب صنعة فاضلة متقدمة وإنما قال هذا فيها ظلما وحسدا وغمطها ما تستحقه من التفضيل بخبر لها معه طريف فسألناه عنه فقال أخرجت الهشامي معي إلى سر من رأى بعد وفاة أخي يعني أبا محمد بن عبد الله بن طاهر فأدخلته على المعتز وهو يشرب وعريب تغني فقال له يا بن هشام غن فقال تبت من الغناء مذ قتل سيدي المتوكل فقالت له عريب قد والله أحسنت حيث تبت فإن غناءك كان قليل المعنى لا متقن ولا صحيح ولا مطرب فأضحكت أهل المجلس جميعا منه فخجل فكان بعد ذلك يبسط لسانه فيها ويعيب","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":8,"spl":"عدت أصواتها فكانت ألفا","tags":["البحتري"],"song":1,"loc":1786,"partialRef":{"sid":"b65-21","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b102-15","bab":"الجزء 10","sec":"عدت أصواتها فكانت ألفا","page":"ج10 ص63","text":"صنعتها ويقول هي ألف صوت في العدد وصوت واحد في المعنى وليس الأمر كما قاله إن لها لصنعة تشبهت فيها بصنعة الأوائل وجودت وبرزت فيها منها\n(أئن سكنت نفسي وقل عويلها ... )\nمنها\n(تقول همي يوم ودعتها ... )\nمنها\n(إذا أردت انتصافا كان ناصركم ... )\nمنها\n(بأبي من هو دائي ... )\nمنها\n(أسلموها في دمشق كما ... )\nمنها\n(فلا تتعنتي ظلما وزورا ... )\nمنها\n(لقد لام ذا الشوق الخلي من الهوى ... )\nونسخت ما أذكره من أخبارها فأنسبه إلى ابن المعتز من كتاب دفعه إلي محمد بن إبراهيم الجراحي المعروف بقريض وأخبرني أن عبد الله بن المعتز دفعه إليه من جمعه وتأليفه فذكرت منها ما استحسنته من أحاديثها إذ كان فيها حشو كثير وأضفت إليه ما سمعته ووقع إلي غير مسموع مجموعا ومتفرقا ونسبت كل رواية إلى راويها","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":9,"spl":"عدت أصواتها فكانت ألفا — نسبها","tags":["البحتري","الحب والغزل","الرواية والكتابة"],"loc":1787,"partial":1},
{"id":"b102-16","bab":"الجزء 10","sec":"نسبها","page":"ج10 ص68","text":"قال ابن المعتز حدثني الهشامي أبو عبد الله وأخبرني علي بن عبد العزيز عن ابن خرداذبة قالا كانت عريب لعبد الله بن إسماعيل صاحب مراكب الرشيد وهو الذي رباها وأدبها وعلمها الغناء\nقال ابن المعتز وحدثني غير الهشامي عن إسماعيل بن الحسين خال المعتصم أنها بنت جعفر بن يحيى وأن البرامكة لما انتهبوا سرقت وهي صغيرة قال فحدثني عبد الواحد بن إبراهيم بن محمد بن الخصيب\nقال حدثني من أثق به عن أحمد بن عبد الله بن إسماعيل المراكبي أن أم عريب كانت تسمى فاطمة وكانت قيمة لأم عبد الله بن يحيى بن خالد وكانت صبية نظيفة فرآها جعفر بن يحيى فهويها وسأل أم عبد الله أن تزوجه إياها ففعلت وبلغ الخبر يحيى بن خالد فأنكره\nوقال له أتتزوج من لا تعرف لها أم ولا أب اشتر مكانها مائة جارية وأخرجها فأخرجها وأسكنها دارا في ناحية باب الأنبار سرا من أبيه ووكل بها من يحفظها وكان يتردد إليها فولدت عريب في سنة إحدى وثمانين ومائة فكانت سنوها إلى أن ماتت ستا وتسعين سنة\nقال وماتت أم عريب في حياة جعفر فدفعها إلى امرأة نصرانية وجعلها داية لها فلما حدثت الحادثة بالبرامكة باعتها من سنبس النخاس فباعها من المراكبي\nقال ابن المعتز وأخبرني يوسف بن يعقوب أنه سمع الفضل بن مروان يقول كنت إذا نظرت إلى قدمي عريب شبهتهما بقدمي جعفر بن يحيى قال وسمعت من يحكي أن بلاغتها في كتبها ذكرت لبعض الكتاب فقال فما يمنعها من ذلك وهي بنت جعفر بن يحيى\nوأخبرني جحظة قال دخلت إلى عريب مع شروين المغني وأبي العبيس بن حمدون وأنا يومئذ غلام علي قباء ومنطقة فأنكرتني وسألت عني فاخبرها شروين\nوقال هذا فتى من أهلك هذا ابن جعفر بن موسى ابن يحيى بن خالد وهو يغني بالطنبور فأدنتني وقربت مجلسي ودعت بطنبور وأمرتني بأن أغني فغنيت أصواتا فقالت قد أحسنت يا بني ولتكونن مغنيا ولكن إذا حضرت بين هذين الأسدين ضعت أنت وطنبورك بين عوديهما وأمرت لي بخمسين دينارا\nقال ابن المعتز وحدثني ميمون بن هارون قال حدثتني عريب قالت بعث الرشيد إلى أهلها تعني البرامكة رسولا يسألهم عن حالهم وأمره ألا يعلمهم أنه من قبله قالت فصار إلى عمي الفضل فسأله فأنشأ عمي يقول\n(سألونا عن حالنا كيف أنتم ... من هوى نجمه فكيف يكون)\n(نحن قوم أصابنا عنت الدهر ... فظلنا لريبه نستكين)\nذكرت عريب أن هذا الشعر للفضل بن يحيى ولها فيه لحنان ثاني ثقيل وخفيف ثقيل كلاهما بالوسطى وهذا غلط من عريب ولعله بلغها أن الفضل تمثل بشعر غير هذا فأنسيته وجعلت هذا مكانه فأما هذا الشعر فللحسين بن الضحاك لا يشك فيه يرثي به محمدا الأمين بعد قوله\n(نحن قوم أصابنا حادث الدهر ... فظلنا لريبه نستكين)\n(نتمنى من الأمين إيابا ... كل يوم وأين منا الأمين)\nهي قصيدة","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":9,"spl":"عدت أصواتها فكانت ألفا — نسبها","tags":["البحتري"],"song":1,"loc":1788},
{"id":"b102-17","bab":"الجزء 10","sec":"هربت إلى معشوقها ومكثت عنده زمانا","page":"ج10 ص70","text":"قال ابن المعتز وحدثني الهشامي أن مولاها خرج إلى البصرة وأدبها وخرجها وعلمها الخط والنحو والشعر والغناء فبرعت في ذلك كله وتزايدت حتى قالت الشعر وكان لمولاها صديق يقال له حاتم بن عدي من قواد خراسان وقيل إنه كان يكتب لعجيف على ديوان الفرض فكان مولاها يدعوه كثيرا ويخالطه ثم ركبه دين فاستتر عنده فمد عينه إلى عريب فكاتبها فأجابته وكانت المواصلة\nبينهما وعشقته عريب فلم تزل تحتال حتى اتخذت سلما من عقب وقيل من خيوط غلاظ وسترته حتى إذا همت بالهرب إليه بعد انتقاله عن منزل مولاها بمدة وقد أعد لها موضعا لفت ثيابها وجعلتها في فراشها بالليل ودثرتها بدثارها ثم تسورت من الحائط حتى هربت فمضت إليه فمكثت عنده زمانا\nقال وبلغني أنها لما صارت عنده بعث إلى مولاها يستعير منه عودا تغنيه به فأعاره عودها وهو لا يعلم أنها عنده ولا يتهمه بشيء من أمرها فقال عيسى بن عبد الله بن إسماعيل المراكبي وهو عيسى ابن زينب يهجو أباه ويعيره بها وكان كثيرا ما يهجوه\n(قاتل الله عريبا ... فعلت فعلا عجيبا)\n(ركبت والليل داج ... مركبا صعبا مهوبا)\n(فارتقت متصلا بالنجم ... أو منه قريبا)\n(صبرت حتى إذا ما ... أقصد النوم الرقيبا)\n(مثلت بين حشايا ... هالكيلا تستريبا)\n(خلفا منها إذا نودي ... لم يلف مجيبا)\n(ومضت يحملها الخوف ... قضيبا وكثيبا)\n(محة لو حركت خفت ... عليها أن تذوبا)\n(فتدلت لمحب ... فتلقاها حبيبا)\n(جذلا قد نال في الدنيا ... من الدنيا نصيبا)\n(أيها الظبي الذي تسحر ... عيناه القلوبا)\n(والذي يأكل بعضا ... بعضه حسنا وطيبا)\n(كنت نهبا لذئاب ... فلقد أطعمت ذيبا)\n(وكذا الشاة إذا لم ... يك راعيها لبيبا)\n(لا يبالي وبأ المرعى ... إذا كان خصيبا)\n(فلقد أصبح عبد الله ... كشخان حريبا)\n(قد لعمري لطم الوجه ... وقد شق الجيوبا)\n(وجرت منه دموع ... بلت الشعر الخضيبا)\nقال ابن المعتز حدثنا محمد بن موسى بن يونس أنها ملته بعد ذلك فهربت منه فكانت تغني عند أقوام عرفتهم ببغداد وهي متسترة متخفية فلما كان يوم من الأيام اجتاز ابن أخ للمراكبي ببستان كانت فيه مع قوم تغني فسمع غناءها فعرفه فبعث إلى عمه من وقته وأقام هو بمكانه فلم يبرح حتى جاء عمه فلببها وأخذها فضربها مائة مقرعة وهي تصيح يا هذا لم تقتلني أنا لست أصبر عليك أنا امرأة حرة إن كنت مملوكة فبعني لست أصبر على الضيقة فلما كان من غد ندم على فعله وصار إليها فقبل رأسها ورجلها ووهب لها عشرة آلاف درهم ثم بلغ محمدا الأمين خبرها فأخذها منه\nقال وكان خبرها سقط إلى محمد في حياة أبيه فطلبها منه فلم يجبه إلى ما سأل وقبل ذلك ما كان طلب منه خادما عنده فاضطغن لذلك عليه فلما ولي الخلافة جاء المراكبي ومحمد راكب ليقبل يده فأمر بمنعه ودفعه ففعل ذلك الشاكري فضربه المراكبي وقال له أتمنعني من يد سيدي أن أقبلها فجاء الشاكري لما نزل محمد فشكاه فدعا محمد بالمراكبي وأمر بضرب عنقه فسئل في أمره\nفأعفاه وحبسه وطالبه بخمسمائة ألف درهم مما اقتطعه من نفقات الكراع وبعث فأخذ عريب من منزله مع خدم كانوا له فلما قتل محمد هربت إلى المراكبي فكانت عنده قال وأنشدني بعض أصحابنا لحاتم بن عدي الذي كانت عنده لما هربت إليه ثم ملته فهربت منه وهي أبيات عدة هذان منها\n(ورشوا على وجهي من الماء واندبوا ... قتيل عريب لا قتيل حروب)\n(فليتك إن عجلتني فقتلتني ... تكونين)\nال ابن المعتز وأما رواية إسماعيل بن الحسين خال المعتصم فإنها تخالف هذا وذكر أنها إنما هربت من دار مولاها المراكبي إلى محمد بن حامد الخاقاني المعروف بالخشن أحد قواد خراسان قال وكان أشقر أصهب الشعر أزرق وفيه تقول عريب ولها فيه هزج ورمل من روايتي الهشامي وأبي العباس\n(بأبي كل أزرق ... أصهب اللون أشقر)\n(جن قلبي به وليس ... جنوني بمنكر)","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":10,"spl":"هربت إلى معشوقها ومكثت عنده زمانا","tags":["البحتري"],"loc":1789},
{"id":"b102-18","bab":"الجزء 10","sec":"تقول الشعر الفاحش","page":"ج10 ص73","text":"قال ابن المعتز وحدثني ابن المدبر قال خرجت مع المأمون إلى أرض الروم أطلب ما يطلبه الأحداث من الرزق فكنا نسير مع العسكر فلما خرجنا من الرقة رأينا جماعة من الحرم\nفي العماريات على الجمازات وكنا رفقة وكنا أترابا فقال لي أحدهم على بعض هذه الجمازات عريب فقلت من يراهنني أمر في جنبات هذه العماريات وأنشد أبيات عيسى ابن زينب\n(قاتل الله عريبا ... فعلت فعلا عجيبا)\nراهنني بعضهم وعدل الرهنان وسرت إلى جانبها فأنشدت الأبيات رافعا صوتي بها حتى أتممتها فإذا أنا بامرأة قد أخرجت رأسها فقالت يا فتى أنسيت أجود الشعر وأطيبه أنسيت قوله\n(وعريب رطبة الشفرين ... قد نيكت ضروبا)\nذهب فخذ ما بايعت فيه ثم ألقت السجف فعلمت أنها عريب وبادرت إلى أصحابي خوفا من مكروه يلحقني من الخدم","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":11,"spl":"تقول الشعر الفاحش — شعر في مظلومة رقيبة عريب","tags":["البحتري","الجواري والنساء"],"loc":1790},
{"id":"b102-19","bab":"الجزء 10","sec":"شعر في مظلومة رقيبة عريب","page":"ج10 ص74","text":"أخبرني إسماعيل بن يونس قال قال لنا عمر بن شبة كانت للمراكبي جارية يقال لها مظلومة جميلة الوجه بارعة الحسن فكان يبعث بها مع عريب إلى الحمام أو إلى من تزوره من أهله ومعارفه فكانت ربما دخلت معها إلى ابن حامد الذي كانت تميل إليه فقال فيها بعض الشعراء وقد رآها عنده\n(لقد ظلموك يا مظلوم لما ... أقاموك الرقيب على عريب)\n(ولو أولوك إنصافا وعدلا ... لما أخلوك أنت من الرقيب)\n(أتنهين المريب عن المعاصي ... فكيف وأنت من شأن المريب)\n(وكيف يجانب الجاني ذنوبا ... لديك وأنت داعية الذنوب)\n(فإن يسترقبوك على عريب ... فما رقبوك من غيب القلوب)\nفي هذا المعنى وإن لم يكن من جنس ما ذكرته ما أنشدنيه علي بن سليمان الأخفش في رقيبة مغنية استحسنت وأظنه للناشئ\n(فديتك لو أنهم أنصفوا ... لقد منعوا العين عن ناظريك)\n(ألم يقرءوا ويحهم ما يرون ... من وحي طرفك في مقلتيك)\n(وقد بعثوك رقيبا لنا ... فمن ذا يكون رقيبا عليك)\n(تصدين أعيننا عن سواك ... وهل تنظر العين إلا إليك)","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":11,"spl":"تقول الشعر الفاحش — شعر في مظلومة رقيبة عريب","tags":["البحتري","الجواري والنساء"],"loc":1791},
{"id":"b102-20","bab":"الجزء 10","sec":"محمد الأمين يبعث في إحضارها وإحضار مولاها","page":"ج10 ص75","text":"قال ابن المعتز وحدثني عبد الواحد بن إبراهيم عن حماد بن إسحاق عن أبيه وعن محمد بن إسحاق البغوي عن إسحاق بن إبراهيم أن خبر عريب لما نمي إلى محمد الأمين بعث في إحضارها وإحضار مولاها فأحضرا وغنت بحضرة إبراهيم بن المهدي تقول\n(لكل أناس جوهر متنافس ... وأنت طراز الآنسات الملائح)\nطرب محمد واستعاد الصوت مرارا وقال لإبراهيم يا عم كيف سمعت قال يا سيدي سمعت حسنا وإن تطاولت بها الأيام وسكن روعها ازداد غناؤها حسنا فقال للفضل بن الربيع خذها إليك وساوم بها ففعل فاشتط مولاها في السوم ثم أوجبها له بمائة ألف دينار وانتقض\nأمر محمد وشغل عنها وشغلت عنه فلم يأمر لمولاها بثمنها حتى قتل بعد أن افتضها فرجعت إلى مولاها ثم هربت منه إلى حاتم بن عدي وذكر باقي الخبر كما ذكره من تقدم\nوقال في خبره إنها هربت من مولاها إلى ابن حامد فلم تزل عنده حتى قدم المأمون بغداد فتظلم إليه المراكبي من محمد بن حامد فأمر بإحضاره فأحضر فسأله عنها فأنكر فقال له المأمون كذبت قد سقط إلي خبرها وأمر صاحب الشرطة أن يجرده في مجلس الشرطة ويضع عليه السياط حتى يردها فأخذه وبلغها الخبر فركبت حمار مكار وجاءت وقد جرد ليضرب وهي مكشوفة الوجه وهي تصيح أنا عريب إن كنت مملوكة فليبعني وإن كنت حرة فلا سبيل له علي فرفع خبرها إلى المأمون فأمر بتعديلها عند قتيبة بن زياد القاضي فعدلت عنده وتقدم إليه المراكبي مطالبا بها فسأله البينة على ملكه إياها فعاد متظلما إلى المأمون\nوقال قد طولبت بما لم يطالب به أحد في رقيق ولا يوجد مثله في يد من ابتاع عبدا أو أمة وتظلمت إليه زبيدة وقالت من أغلظ ما جرى علي بعد قتل محمد ابني هجوم المراكبي على داري وأخذه عريبا منها فقال المراكبي إنما أخذت ملكي لأنه لم ينقدني الثمن فأمر المأمون بدفعها إلى محمد بن عمر الواقدي وكان قد ولاه القضاء بالجانب الشرقي فأخذها من قتيبة بن زياد فأمر ببيعها ساذجة فاشتراها المأمون بخمسين ألف درهم فذهبت به كل مذهب ميلا إليها ومحبة لها قال ابن المعتز ولقد حدثني علي بن يحيى المنجم أن المأمون قبل\nفي بعض الأيام رجلها قال فلما مات المأمون بيعت في ميراثه ولم يبع له عبد ولا أمة غيرها فاشتراها المعتصم بمائة ألف درهم وأعتقها فهي مولاته\nوذكر حماد بن إسحاق عن أبيه أنها لما هربت من دار محمد حين قتل تدلت من قصر الخلد بحبل إلى الطريق وهربت إلى حاتم بن عدي وأخبرني جحظة عن ميمون بن هارون أن المأمون اشتراها بخمسة آلاف دينار ودعا بعبد الله بن إسماعيل فدفعها إليه\nوقال لولا أني حلفت ألا أشتري مملوكا بأكثر من هذا لزدتك ولكني سأوليك عملا تكسب فيه أضعافا لهذا الثمن مضاعفة ورمى إليه بخاتمين من ياقوت أحمر قيمتهما ألف دينار وخلع عليه خلعا سنية فقال يا سيدي إنما ينتفع الأحياء بمثل هذا وأما أنا فإني ميت لا محالة لأن هذه الجارية كانت حياتي وخرج عن حضرته فاختلط وتغير عقله ومات بعد أربعين يوما\nقال ابن المعتز فحدثني علي بن يحيى قال حدثني كاتب الفضل بن مروان قال حدثني إبراهيم بن رباح قال كنت أتولى نفقات المأمون فوصف له إسحاق بن إبراهيم الموصلي عريب فأمره أن يشتريها فاشتراها بمائة ألف درهم فأمرني المأمون بحملها وأن أحمل إلى إسحاق مائة ألف درهم أخرى ففعلت ذلك ولم أدر كيف أثبتها فحكيت في الديوان أن المائة الألف خرجت في ثمن جوهرة والمائة الألف الأخرى خرجت لصائغها ودلالها فجاء الفضل بن مروان إلى\nالمأمون وقد رأى ذلك فأنكره وسألني عنه فقلت نعم هو ما رأيت فسأل المأمون عن ذلك وقال أوجب وهب لدلال وصائغ مائة ألف درهم وغلظ القصة فأنكرها المأمون فدعاني ودنوت إليه وأخبرته أن المال الذي خرج في ثمن عريب وصلة إسحاق وقلت أيما أصوب يا أمير المؤمنين ما فعلت أو أثبت في الديوان أنها خرجت في صلة مغن وثمن مغنية فضحك المأمون وقال الذي فعلت أصوب ثم قال للفضل بن مروان يا نبطي لا تعترض على كاتبي هذا في شيء","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":12,"spl":"محمد الأمين يبعث في إحضارها وإحضار مولاها","tags":["البحتري"],"loc":1792},
{"id":"b102-21","bab":"الجزء 10","sec":"بعض من أخبارها","page":"ج10 ص78","text":"وقال ابن المكي حدثني أبي عن نحرير الخادم قال دخلت يوما قصر الحرم فلمحت عريب جالسة على كرسي ناشرة شعرها تغتسل فسألت عنها فقيل هذه عريب دعا بها سيدها اليوم فافتضها\nقال ابن المعتز فأخبرني ابن عبد الملك البصري أنها لما صارت في دار المأمون احتالت حتى وصلت إلى محمد بن حامد وكانت قد عشقته وكاتبته بصوت قالته ثم احتالت في الخروج إليه وكانت تلقاه في الوقت بعد الوقت حتى حبلت منه وولدت بنتا وبلغ ذلك المأمون فزوجه إياها وأخبرنا إبراهيم بن القاسم بن زرزور عن أبيه وحدثني به المظفر بن كيغلغ عن القاسم بن زرزور قال لما وقف المأمون على خبرها مع محمد بن حامد أمر بإلباسها جبة\nصوف وختم زيقها وحبسها في كنيف مظلم شهرا لا ترى الضوء يدخل إليها خبز وملح وماء من تحت الباب في كل يوم ثم ذكرها فرق لها وأمر بإخراجها فلما فتح الباب عنها وأخرجت لم تتكلم بكلمة حتى اندفعت تغني\n(حجبوه عن بصري فمثل شخصه ... في القلب فهو محجب لا يحجب)\nبلغ ذلك المأمون فعجب منها وقال لن تصلح هذه أبدا فزوجها إياه","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":13,"spl":"بعض من أخبارها — قصة بيت من الشعر","tags":["البحتري","الجواري والنساء","الرواية والكتابة"],"loc":1793},
{"id":"b102-22","bab":"الجزء 10","sec":"نسبة هذا الصوت","page":"ج10 ص79","text":"\n(لو كان يقدر أن يبثك ما به ... لرأيت أحسن عاتب يتعتب)\n(حجبوه عن بصري فمثل شخصه ... في القلب فهو محجب لا يحجب)\nلغناء لعريب ثقيل أول بالوسطى قال ابن المعتز وحدثني لؤلؤ صديق علي بن يحيى المنجم قال حدثني أحمد بن جعفر بن حامد قال لما توفي عمي محمد بن حامد صار جدي إلى منزله فنظر إلى تركته وجعل يقلب ما خلف ويخرج إليه منها الشيء بعد الشيء إلى أن أخرج إليه سفط مختوم ففض الخاتم وجعل يفتحه فإذا فيه رقاع عريب إليه فجعل يتصفحها ويبتسم فوقعت في يده رقعة فقرأها ووضعها من يده وقام لحاجة فقرأتها فإذا فيها قوله\n\n(وبلي عليك ومنكا ... أوقعت في الحق شكا)\n(زعمت أني خئون ... جورا علي وإفكا)\n(إن كان ما قلت حقا ... أو كنت أزمعت تركا)\n(فأبدل الله ما بي ... من ذلة الحب نسكا)\nعريب في هذه الأبيات رمل وهزج عن الهشامي والشعر لها","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":13,"spl":"بعض من أخبارها — قصة بيت من الشعر","tags":["البحتري","الحب والغزل"],"song":2,"loc":1794},
{"id":"b102-23","bab":"الجزء 10","sec":"قصة بيت من الشعر","page":"ج10 ص80","text":"قال ابن المعتز وحدثني عبد الوهاب بن عيسى الخراساني عن يعقوب الرخامي قال كنا مع العباس بن المأمون بالرقة وعلى شرطته هاشم رجل من أهل خراسان فخرج إلي وقال يا أبا يوسف ألقي إليك سرا لثقتي بك وهو عندك أمانة قلت هاته قال كنت واقفا على رأس الأمين وبي حر شديد فخرجت عريب فوقفت معي وهي تنظر في كتاب فما ملكت نفسي أن أومأت إليها بقبلة فقالت كحاشية البرد فوالله ما أدري ما أرادت فقلت قالت لك طعنة قال وكيف ذاك قلت أرادت قول الشاعر\n(رمى ضرع ناب فاستمر بطعنة ... كحاشية البرد اليماني المسهم)\nحكى هذه القصة أحمد بن أبي طاهر عن بشر بن زيد عن عبد الله\nابن أيوب بن أبي شمر أنهم كانوا عند المأمون ومعهم محمد بن حامد وعريب تغنيهم فغنت تقول\n(رمى ضرع ناب فاستمر بطعنة ... كحاشية البرد اليماني المسهم)\nفقال لها المأمون من أشار إليك بقبلة فقلت له طعنة فقالت له يا سيدي من يشير إلي بقبلة في مجلسك فقال بحياتي عليك قالت محمد بن حامد فسكت","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":13,"spl":"بعض من أخبارها — قصة بيت من الشعر","tags":["البحتري","اللهو والمزاح"],"loc":1795},
{"id":"b102-24","bab":"الجزء 10","sec":"أحبت أميرا وتزوجت خادما","page":"ج10 ص81","text":"قال ابن المعتز وحدثني محمد بن موسى قال اصطبح المأمون يوما ومعه ندماؤه وفيهم محمد بن حامد وجماعة من المغنين وعريب معه على مصلاه فأومأ محمد بن حامد إليها بقبلة فاندفعت تغني ابتداء\n(رمى ضرع ناب فاستمر بطعنة ... كحاشية البرد اليماني المسهم)\nريد بغنائها جواب محمد بن حامد بأن تقول له طعنة فقال لها المأمون أمسكي فأمسكت ثم أقبل على الندماء فقال من فيكم أومأ إلى عريب بقبلة والله لئن لم يصدقني لأضربن عنقه فقام محمد فقال أنا يا أمير المؤمنين أومأت إليها والعفو أقرب للتقوى فقال قد عفوت فقال كيف استدل أمير المؤمنين على ذلك\nقال ابتدأت صوتا وهي لا تغني ابتداء إلا لمعنى فعلمت أنها لم تبتدئ بهذا الصوت إلا لشيء أومئ به إليها ولم يكن من شرط هذا الموضع إلا إيماء بقبلة فعلمت أنها أجابت بطعنة\nقال ابن المعتز وحدثني علي بن الحسين أن عريب كانت تتعشق أبا عيسى بن الرشيد وروى غيره أنها كانت لا تضرب المثل إلا بحسن وجه أبي عيسى وحسن غنائه وكانت تزعم أنها ما عشقت أحدا من بني هاشم وأصفته المحبة من الخلفاء وأولادهم سواه قال ابن المعتز وحدثني بعض جوارينا أن عريب كانت تتعشق صالحا المنذري الخادم وتزوجته سرا فوجه به المتوكل إلى مكان بعيد في حاجة له فقالت فيه شعرا وصاغت لحنه في خفيف الثقيل وهو\n(أما الحبيب فقد مضى ... بالرغم مني لا الرضا)\n(أخطأت في تركي لمن ... لم ألق منه معوضا)\nال فغنته يوما بين يدي المتوكل فاستعاده وجعل جواريه يتغامزن ويضحكن فأصغت إليهن سرا من المتوكل فقالت يا سحاقات هذا خير من عملكن قال وحدثت عن بعض جواري المتوكل أنها دخلت يوما على عريب فقالت لها تعالي ويحك إلي فجاءت قال فقالت قبلي هذا الموضع مني فإنك تجدين ريح الجنة فأومأت إلى سالفتها ففعلت ثم قالت لها ما السبب في هذا قالت قبلني صالح المنذري في ذلك الموضع\nقال ابن المعتز وأخبرني أبو عبد الله الهشامي قال حدثني حمدون بن إسماعيل قال حدثني محمد بن يحيى الواثقي قال قال لي محمد بن حامد ليلة أحب أن تفرغ لي مضربك فإني أريد أن أجيئك فأقيم عندك ففعلت ووافاني فلما جلس جاءت عريب فدخلت وقد\nحدثني به جحظة قال حدثني أبو عبد الله بن حمدون أن عريب زارت محمد بن حامد وجلسا جميعا فجعل يعاتبها ويقول فعلت كذا وفعلت كذا فقالت لي يا محمد هذا عندك رأي ثم أقبلت عليه فقالت يا عاجز خذ بنا فيما نحن فيه وفيما جئنا إليه\nوقال جحظة في خبره اجعل سراويلي مخنقتي وألصق خلخالي بقرطي فإذا كان غد فاكتب إلي بعتابك في طومار حتى أكتب إليك بعذري في ثلاثة ودع هذا الفضول فقد قال الشاعر\n(دعي عد الذنوب إذا التقينا ... تعالي لا أعد ولا تعدي)\nتمام هذا قوله\n(فأقسم لو هممت بمد شعري ... إلى نار الجحيم لقلت مدي)\nالشعر للمؤمل والغناء لعريب خفيف رمل وفيه لعلوية رمل بالبنصر من رواية عمرو بن بانة","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":14,"spl":"أحبت أميرا وتزوجت خادما — عاشرت ثمانية من الخلفاء","tags":["البحتري"],"song":2,"loc":1796},
{"id":"b102-25","bab":"الجزء 10","sec":"عاشرت ثمانية من الخلفاء","page":"ج10 ص83","text":"أخبرني أبو يعقوب إسحاق بن الضحاك بن الخصيب قال حدثني أبو الحسن علي بن محمد بن الفرات قال كنت يوما عند أخي أبي العباس وعنده عريب جالسة على دست مفرد لها وجواريها يغنين بين يدينا وخلف ستارتنا فقلت لأخي وقد جرى\nذكر الخلفاء قالت لي عريب ناكني منهم ثمانية ما اشتهيت منهم أحدا إلا المعتز فإنه كان يشبه أبا عيسى بن الرشيد قال ابن الفرات فأصغيت إلى بعض بني أخي فقلت له فكيف ترى شهوتها الساعة فضحك ولمحته فقالت أي شيء قلتم فجحدتها فقالت لجواريها أمسكن ففعلن فقالت هن حرائر لئن لم تخبراني بما قلتما لينصرفن جميعا وهن حرائر إن حردت من شيء جرى ولو أنها تسفيل فصدقتها فقالت وأي شيء في هذا أما الشهوة فبحالها ولكن الآلة قد بطلت أو قالت قد كلت عودوا إلى ما كنتم فيه","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":14,"spl":"أحبت أميرا وتزوجت خادما — عاشرت ثمانية من الخلفاء","tags":["البحتري","الجواري والنساء"],"loc":1797},
{"id":"b102-27","bab":"الجزء 10","sec":"شرطان فاحشان — تحلم ثلاث مرات في النوم بحبيبها","page":"ج10 ص84 – ج10 ص86","text":"وحدثني الحسن بن علي بن مودة قال حدثني إبراهيم بن أبي العبيس قال حدثنا أبي قال دخلنا على عريب يوما مسلمين فقالت أقيموا اليوم عندي حتى\nأطعمكم لوزينجة صنعتها بدعة بيدها من لوز رطب وما حضر من الوظيفة وأغنيكم أنا وهي قال فقلت لها على شريطة قالت وما هي قلت شيء أريد أن أسألك عنه منذ سنين وأنا أهابك قالت ذاك لك وأنا أقدم الجواب قبل أن تسأل فقد علمت ما هو فعجبت لها وقلت فقولي فقالت تريد أن تسألني عن شرطي أي شرط هو فقلت إي والله ذاك الذي أردت قالت شرطي أير صلب ونكهة طيبة فإن انضاف إلى ذلك حسن يوصف وجمال يحمد فقد زاد قدره عندي وإلا فهذان ما لا بد لي منهما\nوحدثني الحسن بن علي عن محمد بن ذي السيفين إسحاق بن كنداجيق عن أبيه قال كانت عريب تولع بي وأنا حديث السن فقالت لي يوما يا إسحاق قد بلغني أن عندك دعوة فابعث إلي نصيبي منها\nقال فاستأنفت طعاما كثيرا وبعثت إليها منه شيئا كثيرا فأقبل رسولي من عندها مسرعا فقال لي لما بلغت إلى بابها وعرفت خبري أمرت بالطعام فأنهب وقد وجهت إليك برسول وهو معي فتحيرت وظننت أنها قد استقصرت فعلي فدخل الخادم ومعه شيء مشدود في منديل ورقعة فقرأتها فإذا فيها بسم الله الرحمن الرحيم يا عجمي يا غبي ظننت أني من الأتراك ووخش الجند فبعثت إلي بخبز ولحم وحلواء الله المستعان عليك يا فدتك نفسي قد وجهت إليك زلة من حضرتي فتعلم ذلك من الأخلاق ونحوه من الأفعال ولا تستعمل أخلاق العامة في رد الظرف فيزداد العيب والعتب عليك إن شاء الله فكشفت المنديل فإذا طبق ومكبة من ذهب منسوج على عمل الخلاف\nوفيه زبدية فيها لقمتان من رقاق وقد عصبت طرفيهما وفيها قطعتان من صدر دراج مشوي ونقل وطلع وملح وانصرف رسولها\nقال ابن المعتز حدثني الهشامي أبو عبد الله عن رجل ذكره عن علوية قال أمرني المأمون وسائر المغنين في ليلة من الليالي أن نصير إليه بكرة ليصطبح فغدونا ولقيني المراكبي مولى عريب وهي يومئذ عنده فقال لي يأيها الرجل الظالم المعتدي أما ترق ولا ترحم ولا تستحي عريب هائمة تحلم بك في النوم ثلاث مرات في كل ليلة\nقال علوية فقلت أم الخلافة زانية ومضيت معه فحين دخلت قلت استوثق من الباب فإني أعرف خلق الله بفضول البوابين والحجاب وإذا عريب جالسة على كرسي تطبخ وبين يديها ثلاث قدور من دجاج فلما رأتني قامت تعانقني وتقبلني ثم قالت أيما أحب إليك أن تأكل من هذه القدور أو تشتهي شيئا يطبخ لك فقلت بل قدر من هذه تكفينا فغرفت قدرا منها وجعلتها بيني وبينها فأكلنا ودعونا بالنبيذ فجلسنا نشرب حتى سكرنا ثم قالت يا أبا الحسن صنعت البارحة صوتا في شعر لأبي العتاهية فقلت وما هو فقالت هو\n(عذيري من الإنسان لا إن جفوته ... صفا لي ولا إن كنت طوع يديه)\nوقالت لي قد بقي فيه شيء فلم نزل نردده أنا وهي حتى استوى ثم جاء الحجاب فكسروا باب المراكبي واستخرجوني فدخلت على المأمون فلما رأيته أقبلت أمشي إليه برقص وتصفيق وأنا أغني الصوت فسمع وسمع من عنده ما لم يعرفوه واستظرفوه وسألني المأمون عن خبره فشرحته له فقال لي ادن وردده فرددته عليه سبع مرات فقال في آخر مرة يا علوية خذ الخلافة واعطني هذا الصاحب","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":15,"spl":"شرطان فاحشان — تحلم ثلاث مرات في النوم بحبيبها — سبب غضب الواثق والمعتصم عليها","tags":["البحتري"],"loc":1798},
{"id":"b102-28","bab":"الجزء 10","sec":"نسبة هذا الصوت","page":"ج10 ص86","text":"\n(عذيري من الإنسان لا إن جفوته ... صفا لي ولا إن كنت طوع يديه)\n(وإني لمشتاق إلى قرب صاحب ... يروق ويصفو إن كدرت عليه)\nلشعر من الطويل وهو لأبي العتاهية والغناء لعريب خفيف ثقيل أول بالوسطى ونسبه عمرو بن بانة في هذه الطريقة والأصبغ إلى علويه","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":15,"spl":"شرطان فاحشان — تحلم ثلاث مرات في النوم بحبيبها — سبب غضب الواثق والمعتصم عليها","tags":["البحتري"],"song":1,"loc":1799},
{"id":"b102-29","bab":"الجزء 10","sec":"سبب غضب الواثق والمعتصم عليها","page":"ج10 ص87","text":"قال ابن المعتز وحدثني القاسم ين زرزور قال حدثتني عريب قالت كنت في أيام محمد ابنة أربع عشرة سنة وأنا حينئذ أصوغ الغناء قال القاسم وكانت عريب تكايد الواثق فيما يصوغه من الألحان وتصوغ في ذلك الشعر بعينه لحنا فيكون أجود من لحنه فمن ذلك\n(لم آت عامدة ذنبا إليك بلى ... أقر بالذنب فاعف اليوم عن زللي)\nحنها فيه خفيف ثقيل ولحن الواثق رمل ولحنها أجود من لحنه ومنها\n(أشكو إلى الله ما ألقى من الكمد ... حسبي بربي ولا أشكو إلى أحد)\nحنها ولحن الواثق جميعا من الثقيل الأول ولحنها أجود من لحنه","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":15,"spl":"شرطان فاحشان — تحلم ثلاث مرات في النوم بحبيبها — سبب غضب الواثق والمعتصم عليها","tags":["البحتري"],"loc":1800},
{"id":"b102-30","bab":"الجزء 10","sec":"نسبة هذين الصوتين","page":"ج10 ص88","text":"\n(لم آت عامدة ذنبا إليك بلى ... أقر بالذنب فاعف اليوم عن زللي)\n(فالصفح من سيد أولى لمعتذر ... وقاك ربك يوم الخوف والوجل)\nلغناء للواثق رمل ولعريب خفيف ثقيل وذكر ذكاء وجه الرزة أن لطالب ابن يزداد فيه هزجا مطلقا\n(أشكو إلى الله ما ألقى من الكمد ... حسبي بربي ولا أشكو إلى أحد)\n(أين الزمان الذي قد كنت ناعمة ... في ظله بدنوي منك يا سندي)\n(وأسأل الله يوما منك يفرحني ... فقد كحلت جفون العين بالسهد)\n(شوقا إليك وما تدري بما لقيت ... نفسي عليك وما بالقلب من كمد)\nلغناء لعريب ثقيل أول بالوسطى وللواثق ثقيل أول بالبنصر قال ابن المعتز وكان سبب انحراف الواثق عنها وكيادها إياه وانحراف المعتصم عنها أنه وجد لها كتابا إلى العباس بن المأمون ببلد الروم اقتل أنت العلج ثم حتى أقتل أنا الأعور الليلي ها هنا تعني الواثق وكان يسهر بالليل وكان المعتصم استخلفه ببغداد قال وحدثني أبو العبيس بن حمدون قال\nغضبت عريب على بعض جواريها المذكورات وسماها لي فجئت إليها يوما وسألتها أن تعفو عنها فقالت في بعض ما تقوله مما تعتد به عليها من ذنوبها يا أبا العبيس إن كنت تشتهي أن ترى زناي وصفاقة وجهي وجراءتي على كل عظيمة أيام شبابي فانظر إليها واعرف أخبارها","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":16,"spl":"نسبة هذين الصوتين — أجادت ركوب الخيل","tags":["البحتري","الجواري والنساء"],"song":2,"loc":1801},
{"id":"b102-31","bab":"الجزء 10","sec":"أجادت ركوب الخيل","page":"ج10 ص89","text":"قال ابن المعتز وحدثني القاسم بن زرزور قال حدثني المعتمد قال حدثتني عريب أنها كانت في شبابها يقدم إليها برذون فتطفر عليه بلا ركاب قال\nوحدثني الأسدي قال حدثني صالح بن علي بن الرشيد المعروف بزعفرانة قال تمارى خالي أبو علي مع المأمون في صوت فقال المأمون أين عريب فجاءت وهي محمومة فسألها عن الصوت فقالت فيه بعلمها فقال لها غنيه فولت لتجيء بعود فقال لها غنيه بغير عود فاعتمدت على الحائط للحمى وغنت فأقبلت عقرب فرأيتها قد لسعت يدها مرتين أو ثلاثا فما نحت يدها ولا سكتت حتى فرغت من الصوت ثم سقطت وقد غشي عليها قال ابن المعتز وحدثني أبو العباس بن الفرات قال\nقالت لي تحفة جارية عريب كانت عريب تجد في رأسها بردا فكانت تغلف شعرها مكان العلة بستين مثقالا مسكا وعنبرا وتغسله من جمعة إلى جمعة فإذا غسلته أعادته وتتقسم الجواري غسالة رأسها بالقوارير وما تسرحه منه بالميزان\nحدثني أحمد بن جعفر جحظة عن علي بن يحيى المنجم قال دخلت يوما على عريب مسلما عليها فلما اطمأننت جالسا هطلت السماء بمطر عظيم فقالت أقم عندي اليوم حتى أغنيك أنا وجواري وابعث إلي من أحببت من إخوانك فأمرت بدوابي فردت وجلسنا نتحدث فسألتني عن خبرنا بالأمس في مجلس الخليفة ومن كان يغنينا وأي شيء استحسنا من الغناء فأخبرتها أن صوت الخليفة كان لحنا صنعه بنان من الماخوري فقالت وما هو فأخبرتها أنه\n(تجافي ثم تنطبق ... جفون حشوها الأرق)\n(وذي كلف بكى جزعا ... وسفر القوم منطلق)\n(به قلق يململه ... وكان وما به قلق)\n(جوانحه على خطر ... بنار الشوق تحترق)\nوجهت رسولا إلى بنان فحضر من وقته وقد بلته السماء فأمرت بخلع فاخرة فخلعت عليه وقدم له طعام فاخر فأكل وجلس يشرب معنا وسألته عن الصوت فغناها إياه فأخذت دواة ورقعة وكتبت فيها\n(أجاب الوابل الغدق ... وصاح النرجس الغرق)\n(وقد غنى بنان لنا ... جفون حشوها الأرق)\n(فهات الكأس مترعة ... كأن حبابها حدق)\nال علي بن يحيى فما شربنا بقية يومنا إلا على هذه الأبيات","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":16,"spl":"نسبة هذين الصوتين — أجادت ركوب الخيل","tags":["البحتري"],"song":1,"loc":1802},
{"id":"b102-33","bab":"الجزء 10","sec":"ترد على من دعاها برموز — هجرت المأمون أياما لأنها غضبت منه","page":"ج10 ص91 – ج10 ص92","text":"حدثني محمد بن خلف بن المرزبان عن عبد الله بن محمد المروزي قال قال لي الفضل بن العباس بن المأمون زارتني عريب يوما ومعها عدة من جواريها فوافتنا ونحن على شرابنا فتحادثنا ساعة وسألتها أن تقيم عندي فأبت وقالت دعاني جماعة من إخواني من أهل الأدب والظرف وهم مجتمعون في جزيرة المؤيد فيهم إبراهيم بن المدبر وسعيد بن حميد ويحيى بن عيسى بن منارة وقد عزمت على المسير إليهم فحلفت عليها فأقامت عندنا ودعت بداوة وقرطاس فكتبت بسم الله الرحمن الرحيم وكتبت بعد ذلك في سطر واحد ثلاثة أحرف متفرقة لم تزد عليها وهي أردت ولولا ولعلي ووجهت به إليهم فلما وصلت الرقعة عيوا بجوابها فأخذ إبراهيم بن المدبر الرقعة فكتب تحت أردت ليت وتحت لولا ماذا وتحت لعلي\nأرجو ووجهوا بالرقعة فصفقت ونعرت وشربت رطلا وقالت لنا أأترك هؤلاء وأقعد عندكم إذا تركني الله من يديه ولكني أخلف عندكم من جواري من يكفيكم وأقوم إليهم ففعلت ذلك وخلفت عندنا بعض جواريها وأخذت معها بعضهن وانصرفت أخبرنا محمد بن خلف عن سعيد بن عثمان بن أبي العلاء عن أبيه\nقال عتب المأمون على عريب فهجرها أياما ثم اعتلت فعادها فقال لها كيف وجدت طعم الهجر فقالت يا أمير المؤمنين لولا مرارة الهجر ما عرفت حلاوة الوصل ومن ذم بدء الغضب أحمد عاقبة الرضا قال فخرج المأمون إلى جلسائه فحدثهم بالقصة ثم قال أترى هذا لو كان من كلام النظام ألم يكن كبيرا\nحدثني محمد بن خلف عن أبي العيناء عن أحمد بن أبي دؤاد قال جرى بين عريب وبين المأمون كلام فكلمها المأمون بشيء غضبت منه فهجرته أياما قال أحمد بن أبي داود فدخلت على المأمون فقال لي\nيا أحمد اقض بيننا فقالت عريب لا حاجة لي في قضائه ودخوله فيما بيننا وأنشأت تقول\n(وتخلط الهجر بالوصال ولا ... يدخل في الصلح بيننا أحد)\nدثني محمد بن خلف قال حدثني محمد بن عبد الرحمن عن أحمد بن حمدون عن أبيه قال كنت حاضرا مجلس المأمون ببلاد الروم بعد صلاة العشاء الآخرة في ليلة ظلماء ذات رعود وبروق فقال لي المأمون اركب الساعة فرس النوبة وسر إلى عسكر أبي إسحاق يعني المعتصم فأد إليه رسالتي في كيت وكيت\nقال فركبت ولم تثبت معي شمعة وسمعت وقع حافر دابة فرهبت ذلك وجعلت أتوقاه حتى صك ركابي ركاب تلك الدابة وبرقت بارقة فأضاءت وجه الراكب فإذا عريب فقلت عريب قالت نعم حمدون\nقلت نعم ثم قلت من أين أقبلت في هذا الوقت قالت من عند محمد ابن حامد قلت وما صنعت عنده قالت عريب ياتكش عريب تجيء من عند محمد بن حامد في هذا الوقت خارجة من مضرب الخليفة وراجعة إليه تقول لها أي شيء عملت عنده صليت معه التراويح أوقرأت عليه أجزاء من القرآن أو دارسته شيئا من الفقه يا أحمق تعاتبنا وتحادثنا واصطلحنا ولعبنا وشربنا وغنينا وتنايكنا وانصرفنا فأخجلتني وغاظتني وافترقنا ومضيت فأديت الرسالة ثم عدت إلى المأمون وأخذنا في الحديث وتناشد الأشعار وهممت والله أن أحدثه حديثها ثم هبته فقلت أقدم قبل ذلك تعريضا بشيء من الشعر فأنشدته\n(ألا حي أطلالا لواسعة الحبل ... ألوف تسوي صالح القوم بالرذل)\n(فلو أن من أمسى بجانب تلعة ... إلى جبلي طي فساقطة الحبل)\n(جلوس إلى أن يقصر الظل عندها ... لراحوا وكل القوم منها على وصل)\nقال لي المأمون اخفض صوتك لا تسمعك عريب فتغضب وتظن أنا في حديثها فأمسكت عما أردت أن أخبره وخار الله لي في ذلك حدثني محمد بن أحمد الحكيمي قال أخبرني ميمون بن هارون قال قال لي ابن اليزيدي حدثني أبي قال خرجنا مع المأمون في خروجه إلى بلد الروم فرأيت عريب في هودج فلما رأتني قالت لي يا يزيدي أنشدني شعرا قلته حتى أصنع فيه لحنا فأنشدتها\n(ماذا بقلبي من دوام الخفق ... إذا رأيت لمعان البرق)\n(من قبل الأردن أو دمشق ... لأن من أهوى بذاك الأفق)\n(فإن فيه وهو أعز الخلق ... علي والزور خلاف الحق)\n(ذاك الذي يملك بني رقي ... ولست أبغي ما حييت عتقي)\nال فتنفست تنفسا ظننت أن ضلوعها قد تقصفت منه فقلت هذا والله تنفس أعشق فقالت اسكت يا عاجز أنا عاشق والله لقد نظرت نظرة مريبة في مجلس فادعاها من أهل المجلس عشرون رئيسا طريفا","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":17,"spl":"ترد على من دعاها برموز — هجرت المأمون أياما لأنها غضبت منه","tags":["البحتري"],"loc":1803},
{"id":"b102-34","bab":"الجزء 10","sec":"شعر لعباس بن الأحنف يصلح بينها وبين حبيبها","page":"ج10 ص94","text":"حدثني محمد بن خلف قال حدثني أحمد بن أبي طاهر قال حدثني أحمد بن حمدون قال\nوقع بين عريب وبين محمد بن حامد شر وكان يجد بها الوجد كله فكادا يخرجان من شرهما إلى القطيعة وكان في قلبها منه أكثر مما في قلبه منها فلقيته يوما فقالت له كيف قلبك يا محمد قال أشقى والله ما كان وأقرحه فقالت له استبدل تسل فقال لها لو كانت البلوى باختيار لفعلت فقالت لقد طال إذا تعبك فقال وما يكون أصبر مكرها أما سمعت قول العباس بن الأحنف\n(تعب يطول مع الرجاء بذي الهوى ... خير له من راحة في الياس)\n(لولا كرامتكم لما عاتبتكم ... ولكنتم عندي كبعض الناس)\nال فذرفت عيناها واعتذرت إليه وأعتبته واصطلحا وعادا إلى أفضل ما كانا عليه","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":18,"spl":"شعر لعباس بن الأحنف يصلح بينها وبين حبيبها — اختلاف في تقييم فنها","tags":["البحتري","الحب والغزل","اللهو والمزاح"],"loc":1804},
{"id":"b102-35","bab":"الجزء 10","sec":"اختلاف في تقييم فنها","page":"ج10 ص95","text":"حدثني أحمد بن جعفر جحظة قال قال لي أبو العباس بن حمدون وقد تجاذبنا غناء عريب ليس غناؤها مما يعتد بكثرته لأن سقطه كثير وصنعتها ساذجة فقلت له ومن يعرف في الناس كلهم من مغني الدولة العباسية سلمت صنعته كلها حتى تكون مثله ثم جعلت أعد ما أعرفه من جيد صنعتها ومتقدمها وهو يعترف بذلك حتى عددت نحوا من مائة صوت مثل لحنها في\n(يا عز هل لك في شيخ فتى أبدا ... )\nو\n(سيسليك عما فات دولة مفضل ... )\nو\n(صاح قد لمت ظالما ... )\nو\n(وضحك الزمان وأشرقت ... )\nنحو هذا ثم قال لي ما خلفت عريب بعدها امرأة مثلها في الغناء والرواية والصنعة فقلت له لا ولا كثيرا من الرجال أيضا ولعريب في صنعتها\n(يا عز هل لك في شيخ فتى أبدا ... )\nخبر أخبرني ببعضه أحمد بن عبيد الله بن عمار عن ميمون بن هارون وذكر ابن المعتز أن عبد الواحد بن إبراهيم بن الخصيب حدثه عمن يثق به عن أحمد بن عبد الله بن إسماعيل المراكبي قال قالت لي عريب حج بي أبوك وكان مضعوفا فكان عديلي وكنت في طريقي أطلب الأعراب فأستنشدهم الأشعار وأكتب عنهم النوادر وسائر ما أسمعه منهم فوقف شيخ من الأعراب علينا يسأل فاستنشدته فأنشدني\n(يا عز هل لك في شيخ فتى أبدا ... وقد يكون شباب غير فتيان)\nاستحسنته ولم أكن سمعته قبل ذلك قلت فأنشدني باقي الشعر فقال لي هو يتيم فاستحسنت قوله وبررته وحفظت البيت وغنيت فيه صوتا من الثقيل الأول ومولاي لا يعلم بذلك لضعفه فلما كان في ذلك اليوم عشيا\nقال لي ما كان أحسن ذلك البيت الذي أنشدك إياه الأعرابي وقال لك إنه يتيم أنشدينيه إن كنت حفظته فأنشدته إياه وأعلمته أني قد غنيت فيه ثم غنيته له فوهب لي ألف درهم بهذا السبب وفرح بالصوت فرحا شديدا قال ابن المعتز قال ابن الخصيب فحدثني هذا المحدث أنه قد حضر بعد ذلك بمجلس أبي عيسى بن المتوكل\nومن ها هنا تتصل رواية ابن عمار عن ميمون وقد جمعت الروايتين إلا أن ميمون بن هارون ذكر أنهم كانوا عند جعفر بن المأمون وعندهم أبو عيسى وكان عندهم علي ابن يحيى وبدعة جارية عريب تغنيهم فذكر علي بن يحيى أن الصنعة فيه لغير عريب وذكر أنها لا تدعي هذا وكابر فيه فقام جعفر بن المأمون فكتب رقعة إلى عريب ونحن لا نعلم يسألها عن أمر الصوت وأن تكتب إليه بالقصة ففعلت فكتبت إليه بخطها بسم الله الرحمن الرحيم\n(هنيا لأرباب البيوت بيوتهم ... وللعزب المسكين ما يتلمس)\nنا المسكينة وحيدة فريدة بغير مؤنس وأنتم فيما أنتم وقد أخذتم أنسي ومن كان يلهيني تعني جاريتيها بدعة وتحفة فأنتم في القصف والعزف وأنا في خلاف ذلك هناكم الله وأبقاكم وسألت مد الله في عمرك عما اعترض فيه فلان والقصة في هذا الصوت كذا وكذا وقصت قصتها مع الأعرابي كما حدثت به ولم تخرم حرفا منها فجاء الجواب إلى جعفر بن المأمون فقرأه وضحك ثم رمى به إلى أبي عيسى ورمى به أبو عيسى إلي\nوقال اقرأه وكان علي بن يحيى جالسا إلى جنبي فأراد أن يستلب الرقعة فمنعته وقمت ناحية فقرأتها فأنكر ذلك وقال ما هذا فورينا الأمر عنه لئلا تقع عربدة وكان عفا الله عنا وعنه مبغضا لها","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":18,"spl":"شعر لعباس بن الأحنف يصلح بينها وبين حبيبها — اختلاف في تقييم فنها","tags":["البحتري"],"loc":1805,"partialRef":{"sid":"b65-21","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b102-36","bab":"الجزء 10","sec":"تعرف خبر صوت لا يعرفه أحد على وجه الأرض","page":"ج10 ص97","text":"قال ابن المعتز وحدثني أبو الخطاب العباس بن أحمد بن الفرات قال حدثني أبي قال كنا يوما عند جعفر بن المأمون نشرب وعريب حاضرة إذ غنى بعض من كان هناك\n(يا بدر إنك قد كسيت مشابها ... من وجه ذاك المستنير اللائح)\n(وأراك تمصح بالمحاق وحسنها ... باق على الأيام ليس ببارح)\nضحكت عريب وصفقت وقالت ما على وجه الأرض أحد يعرف خبر هذا الصوت غيري فلم يقدم أحد منا على مسألتها عنه غيري فسألتها فقالت أنا أخبركم بقصته ولولا أن صاحب القصة قد مات لما أخبرتكم إن أبا محلم قدم بغداد فنزل بقرب دار صالح المسكين في خان هناك فاطلعت أم محمد ابنة صالح يوما فرأته يبول فأعجبها متاعه وأحبت مواصلته فجعلت لذلك علة بأن وجهت إليه تقترض منه مالا وتعلمه أنها في ضيقة وأنها ترده إليه بعد جمعة فبعث إليها عشرة آلاف درهم وحلف أنه لو ملك غيرها لبعث به فاستحسنت ذلك وواصلته وجعلت القرض سببا للوصلة فكانت تدخله إليها ليلا وكنت أنا أغني لهم فشربنا ليلة في القمر وجعل أبو محلم ينظر إليه ثم دعا بدواة ورقعة وكتب فيها قوله\n(يا بدر إنك قد كسيت مشابها ... من وجه أم محمد ابنة صالح)\nالبيت الآخر وقال لي غني فيه ففعلت واستحسناه وشربنا عليه فقالت لي أم محمد في آخر المجلس يا أختي قد تنبلت في هذا الشعر إلا أنه سيبقى علي فضيحة آخر الدهر فقال أبو محلم وأنا أغيره فجعل مكان أم محمد ابنة صالح\n(ذاك المستنير الائح ... )\nوغنيته كما غيره وأخذه الناس عني ولو كانت أم محمد حية لما أخبرتكم بالخبر","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":19,"spl":"تعرف خبر صوت لا يعرفه أحد على وجه الأرض — فأما نسبة هذا الصوت","tags":["البحتري"],"loc":1806,"partial":1},
{"id":"b102-37","bab":"الجزء 10","sec":"فأما نسبة هذا الصوت","page":"ج10 ص98","text":"فإن الشعر لأبي محلم النسابة والغناء لعريب ثقيل أول مطلق في مجرى\nالوسطى من رواية الهشامي وغيره وأبو محلم اسمه عوف بن محلم","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":19,"spl":"تعرف خبر صوت لا يعرفه أحد على وجه الأرض — فأما نسبة هذا الصوت","tags":["البحتري"],"loc":1807},
{"id":"b102-38","bab":"الجزء 10","sec":"كتبت إلى حبيبها تستزيره","page":"ج10 ص99","text":"أخبرني هاشم بن محمد الخزاعي عن ميمون بن هارون قال كتبت عريب إلى محمد بن حامد الذي كانت تهواه تستزيره فكتب إليها إني أخاف على نفسي فكتبت إليه\n(إذا كنت تحذر ما تحذر ... وتزعم أنك لا تجسر)\n(فمالي أقيم على صبوتي ... ويوم لقائك لا يقدر)\nصار إليها من وقته لعريب في هذين البيتين وبيتين آخرين بعدهما لم يذكرا في الخبر رمل ولشارية خفيف رمل جمعا من رواية ابن المعتز والبيتان الآخران\n(تبينت عذري وما تعذر ... وأبليت جسمي وما تشعر)\n(ألفت السرور وخليتني ... ودمعي من العين ما يفتر)\nوذكر ميمون في هذا الخبر أن محمد بن حامد كتب إليها يعاتبها في شيء كرهه فكتبت إليه تعتذر فلم يقبل فكتبت إليه بهذين البيتين الآخرين اللذين ذكرتهما بعد نسبة هذا الصوت\n(أحببت من شعر بشار لحبكم ... بيتا كلفت به من شعر بشار)\n(يا رحمة الله حلي في منازلنا ... وجاورينا فدتك النفس من جار)\n(إذا ابتهلت سألت الله رحمته ... كنيت عنك وما يعدوك إضماري)\nلشعر لأبي نواس منه البيت الأول والثاني لبشار ضمنه أبو نواس والغناء لعريب ثقيل أول بالبنصر ولعمرو بن بانة في الثاني والثالث رمل وهذا الشعر يقوله أبو نواس في رحمة ابن نجاح عم نجاح بن سلمة الكاتب\nأخبرني بخبره علي بن سليمان الأخفش عن محمد بن يزيد النحوي قال كان بشار يشبب بامرأة يقال لها رحمة وكان أبو نواس يتعشق غلاما اسمه رحمة بن نجاح عم نجاح بن سلمة الكاتب وكان متقدما في جماله وكان أبوه قد ألزمه وأخاه رجلا مدنيا وكان معهم كأحدهم وأكثر أبو نواس التشبيب برحمة في إقامته ببغداد وشخوصه عنها وكان بشار قد قال في رحمة المرأة التي يهواها\n(يا رحمة الله حلي في منازلنا ... حسبي برائحة الفردوس من فيك)\n(يا أطيب الناس ريقا غير مختبر ... إلا شهادة أطراف المساويك)\nقال أبو نواس وضمن بيت بشار\n(أحببت من شعر بشار لحبكم ... بيتا كلفت به من شعر بشار)\nلأبيات الثلاثة وقال فيه\n(يا من تأهب مزمعا لرواح ... متيمما بغداد غير ملاح)\n(في بطن جارية كفتك بسيرها ... رملا وكل سباحة السباح)\n(بنيت على قدر ولاءم بينها ... صنفان من قار ومن ألواح)\n(وكأنها والماء ينضح صدرها ... والخيزرانة في يد الملاح)\n(جون من الغربان يبتدر الدجى ... يهوي بصوت واصطفاق جناح)\n(سلم على شاطئ الصراة وأهلها ... واخصص هناك مدينة الوضاح)\n(واقصد هديت ولا تكن متحيرا ... في مقصد عن ظبي آل نجاح)\n(عن رحمة الرحمن واسأل من ترى ... سيماه سيما شارب للراح)\n(فإذا دفعت إلى أغن وألثغ ... ومنعم ومكحل ورداح)\n(وكشمسنا وكبدرنا حاشى التي ... سميتها منه بنور أقاحي)\n(فاقصد لوقت لقائه في خلوة ... لتبوح عني ثم كل مباح)\n(واخبر بما أحببت عن حالي التي ... ممساي فيها واحد وصباحي)\nال فافتدى أبو رحمة من أبي نواس ذكر ابنه بأن عقد بينه وبينه حرمة ودعاه إلى منزله فجاءه أبو نواس والمديني لا يعرفه فمازحه مزاحا أسرف عليه فيه فقام إليه رحمة فعرفه أنه أبو نواس فأشفق المديني من ذلك وخاف أن يهجوه ويشهر اسمه فسأل رحمة أن يكلمه في الصفح له والإغضاء عن الانتقام فأجابه أبو نواس وقال\n(اذهب سلمت من الهجاء ولذعه ... وأما ولثغة رحمة بن نجاح)\n(لولا فتور في كلامك يشتهى ... وترفقي لك بعد واستملاحي)\n(وتكسر في مقلتيك هو الذي ... عطف الفؤاد عليك بعد جماح)\n(لعلمت أنك لا تمازح شاعرا ... في ساعة ليست بحين مزاح)\n\n(أأبكاك بالعرف المنزل ... وما أنت والطلل المحول)\n(وما أنت ويك ورسم الديار ... وسنك قد قاربت تكمل)\nروضه من المتقارب والشعر للكميت بن زيد الأسدي والغناء لمعقل بن عيسى أخي أبي دلف العجلي ولحنه من الثقيل الأول بالبنصر وهذان البيتان من قصيدة مدح الكميت بهما عبد الرحمن بن عنبسة بن سعيد بن العاصي بن أمية\nأخبرني الحسن بن علي قال حدثني الحسن بن عليل العنزي عن علي بن هشام عن محمد بن عبد الأعلى بن كناسة قال كان بين بني أسد وبين طيء بالحص وهي قريبة من قادسية الكوفة حرب فاصطلحوا وبقي لطيء دماء رجلين فاحتمل ذلك رجل من بني أسد فمات قبل أن يؤديه فاحتمله الكميت بن زيد فأعانه فيه عبد الرحمن بن عنبسة فمدحه بقوله\n(أأبكاك بالعرف المنزل ... وما أنت والطلل المحول)\nأعانه الحكم بن الصلت الثقفي فمدحه بقصيدته التي أولها\n(رأيت الغواني وحشا نفورا ... )","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":20,"spl":"كتبت إلى حبيبها تستزيره","tags":["البحتري"],"song":3,"loc":1808,"partial":1},
{"id":"b102-39","bab":"الجزء 10","sec":"كتبت إلى حبيبها تستزيره","page":"ج10 ص99","text":"أعانه زياد بن المغفل الأسدي فمدحه بقصيدته التي أولها\n(هل للشباب الذي قد فات من طلب ... )\nم جلس الكميت وقد خرج العطاء فأقبل الرجل يعطي الكميت المائتين والثلاث المائة وأكثر وأقل قال وكانت دية الأعاربي حينئذ ألف بعير ودية الحضري عشرة آلاف درهم وكانت قيمة الجمل عشرة دراهم فأدى الكميت عشرين ألفا عن قيمة ألفي بعير","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":21,"spl":"كتبت إلى حبيبها تستزيره — كان شاعرا ومغنيا","tags":["البحتري","المديح"],"loc":1809,"partial":1},
{"id":"b102-40","bab":"الجزء 10","sec":"نسبة ما في أشعار الكميت هذه من الأغاني","page":"ج10 ص103","text":"صوت منها\n(هل للشباب الذي قد فات من طلب ... أم ليس غابره الماضي بمنقلب)\n(دع البكاء على ما فات من طلب ... فالدهر يأتي بألوان من العجب)\nناه إبراهيم الموصلي خفيف رمل بالسبابة في مجرى الوسطى من رواية إسحاق","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":21,"spl":"كتبت إلى حبيبها تستزيره — كان شاعرا ومغنيا","tags":["البحتري"],"loc":1810},
{"id":"b102-41","bab":"الجزء 10","sec":"كان شاعرا ومغنيا","page":"ج10 ص104","text":"كان معقل بن عيسى فارسا شاعرا جوادا مغنيا فهما بالنغم والوتر وذكره الجاحظ مع ذكر أخيه أبي دلف وتقريظه في المعرفة بالنغم وقال إنه من أحسن أهل زمانه وأجود طبقته صنعة إذ سلم ذلك له أخوه معقل وإنما أخمل ذكره ارتفاع شأن أخيه وهو القائل لأبي دلف في عتب عتبه عليه\n(أخي مالك ترميني فتقصدني ... وإن رميتك سهما لم يجز كبدي)\n(أخي مالك مجبولا على ترتي ... كأن أجسادنا لم تغذ من جسد)\nهو القائل لمخارق وقد كان زار أبا دلف إلى الجبل ثم رجع إلى العراق أخبرني بذلك علي بن سليمان الأخفش عن أبي سعيد السكري\n(لعمري لئن قرت بقربك أعين ... لقد سخنت بالبين منك عيون)\n(فسر أو أقم وقف عليك محبتي ... مكانك من قلبي عليك مصون)\n(فما أوحش الدنيا إذا كنت نازحا ... وما أحسن الدنيا بحيث تكون)\nروضه من الطويل والشعر لمعقل بن عيسى والغناء لمخارق ولحنه من الثقيل الأول بالوسطى وفيه لحن لمعقل بن عيسى خفيف رمل وفيه ثاني ثقيل يقال إنه لمخارق ويقال إنه لمعقل ومن شعر معقل قوله يمتدح المعتصم وفيه غناء للزبير بن دحمان من الثقيل الأول بالبنصر\n(الدار هاجك رسمها وطلولها ... أم بين سعدى يوم جد رحيلها)\n(كل شجاك فقل لعينك أعولي ... إن كان يغني في الديار عويلها)\n(ومحمد زين الخلائف والذي ... سن المكارم فاستبان سبيلها)\nوت\n(أليس إلى أجبال شمخ إلى اللوى ... لوى الرمل يوما للنفوس معاد)\n(بلاد بها كنا وكنا من أهلها ... إذ الناس ناس والبلاد بلاد)\nلشعر لرجل من عاد فيما ذكروا والغناء لابن محرز ولحنه من الثقيل الأول بالبنصر عن ابن المكي وقيل إنه من منحوله إليه أخبرني ابن عمار عن أبي سعد عن محمد بن الصباح قال حدثنا يحيى بن سلمة بن أبي الأشهب التيمي عن الهيثم بن عدي قال أخبرني حماد الراوية قال حدثني ابن أخت لنا من مراد قال وليت صدقات قوم من العرب فبينا أنا أقسمها في أهلها إذ قال لي رجل منهم ألا أريك عجبا قلت بلى فأدخلني في\nشعب من جبل فإذا أنا بسهم من سهام عاد من فتى قد نشب في ذروة الشعب وإذا على الجبل تجاهي مكتوب\n(ألا هل إلى أبيات شمخ إلى اللوى ... لوى الرمل يوما للنفوس معاد)\n(بلاد بها كنا وكنا من أهلها ... اذ الناس ناس والبلاد بلاد)\nم أخرجني إلى ساحل البحر وإذا أنا بحجر يعلوه الماء طورا ويظهر تارة وإذا عليه مكتوب يا بن آدم يا بن عبد ربه اتق الله ولا تعجل في أمرك فإنك لن تسبق رزقك ولن ترزق ما ليس لك ومن البصرة إلى الديل ستمائة فرسخ فمن لم يصدق بذلك فليمش الطريق على الساحل حتى يتحققه فإن لم يقدر على ذلك فلينطح برأسه هذا الحجر\n(يا بيت عاتكة الذي أتعزل ... حذر العدا وبه الفؤاد موكل)\n(إني لأمنحك الصدود وإنني ... قسما إليك مع الصدود لأميل)\nتعزله أتجنبه وأكون بمعزل عنه العدا جمع عدو ويقال عدا بالضم وعدا بالكسر وأمنحك أعطيك والمنيحة العطية وفي الحديث أن رجلا منح بعض ولده شيئا من ماله فقال له النبي أكل ولدك منحت مثل هذا قال لا قال فارجعه الشعر للأحوص بن محمد الأنصاري من قصيدة يمدح بها عمر بن عبد العزيز الغناء لمعبد ثاني ثقيل بالخنصر في مجرى البنصر عن إسحاق ويونس وغيرهما وفيه لابن سريج خفيف ثقيل الأول بالبنصر عن الهشامي وابن المكي وعلي بن يحيى","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":21,"spl":"كتبت إلى حبيبها تستزيره — كان شاعرا ومغنيا","tags":["البحتري"],"song":3,"loc":1811},
{"id":"b102-42","bab":"الجزء 10","sec":"الأحوص وبعض أخباره سرق أبيات سليمان بأعيانها وأدخلها في شعره وغير قوافيها فقط","page":"ج10 ص107","text":"أخبرني بخبر الأحوص في هذا الشعر الحرمي عن الزبير قال حدثني عمر بن أبي بكر المؤملي وأخبرنا به الحسين بن يحيى عن حماد عن أبيه عن مصعب الزبيري عن المؤملي عن عمر بن أبي بكر الموصلي عن عبد الله بن أبي عبيدة بن عمار بن ياسر\nقال خرجت أنا والأحوص بن محمد مع عبد الله بن الحسن بن الحسن إلى الحج فلما كنا بقديد قلنا لعبد الله بن الحسن لو أرسلت إلى سليمان بن أبي دباكل فأنشدنا شيئا من شعره فأرسل إليه فأتانا فاستنشدناه فأنشدنا قصيدته التي يقول فيها\n(يا بيت خنساء الذي أتجنب ... ذهب الشباب وحبها لا يذهب)\n(أصبحت أمنحك الصدود وإنني ... قسما إليك مع الصدود لأجنب)\n(ما لي أحن إلى جمالك قربت ... وأصد عنك وأنت مني أقرب)\n(لله درك هل لديك معول ... لمتيم أم هل لودك مطلب)\n(فلقد رأيتك قبل ذاك وإنني ... لموكل بهواك أو متقرب)\n(إذ نحن في الزمن الرخي وأنتم ... متجاورون كلامكم لا يرقب)\n(تبكي الحمامة شجوها فتهيجني ... ويروح عازب همي المتأوب)\n(وتهب جارية الرياح من أرضكم ... فأرى البلاد لها تطل وتخصب)\n(وأرى السمية باسمكم فيزيدني ... شوقا إليك رجاؤك المتنسب)\n(وأرى العدو يودكم فأوده ... إن كان ينسب منك أو لا ينسب)\n(وأخالف الواشين فيك تجملا ... وهم علي ذوو ضغائن دؤب)\n(ثم اتخذتهم علي وليجة ... حتى غضبت ومثل ذلك يغضب)\nال فلما كان من قابل حج أبو بكر بن عبد العزيز بن مروان فقدم المدينة فدخل عليه الأحوص واستصحبه فأصحبه فلما خرج الأحوص قال له بعض من عنده ماذا تريد بنفسك تقدم بالأحوص الشام وبها من ينافسك من بني أبيك وهو من الأفن والسفه على ما قد علمت فيعيبونك به فلما رجع أبو بكر من الحج دخل عليه الأحوص متنجزا لما وعده من الصحابة فدعا له بمائة دينار وأثواب\nوقال يا خال إني نظرت فيما سألتني من الصحابة فكرهت أن أهجم بك على أمير المؤمنين من غير إذنه فيجبهك فيشمت بك عدوي من أهل بيتي ولكن خذ هذه الثياب والدنانير وأنا مستأذن لك أمير المؤمنين فإذا أذن لك كتبت إليك فقدمت علي فقال له الأحوص لا ولكن قد سبعت عندك ولا حاجة لي بعطيتك ثم خرج من عنده فبلغ ذلك عمر بن عبد العزيز فأرسل إلى الأحوص وهو يومئذ أمير المدينة فلما دخل عليه أعطاه مائة دينار وكساه ثيابا فأخذ ذلك ثم قال له\nيا أخي هب لي عرض أبي بكر قال هو لك ثم خرج الأحوص فقال في عروض قصيدة سليمان بن أبي دباكل قصيدة مدح بها عمر بن عبد العزيز وقال حماد قال أبي سرق أبيات سليمان بأعيانها فأدخلها في شعره وغير قوافيها فقط فقال\n(يا بيت عاتكة الذي أتعزل ... حذر العدا وبه الفؤاد موكل)\n(أصبحت أمنحك الصدود وإنني ... قسما إليك مع الصدود لأميل)\n(فصددت عنك وما صددت لبغضة ... أخشى مقالة كاشح لا يعقل)\n(هل عيشنا بك في زمانك راجع ... فلقد تفاحش بعدك المتعلل)\n(إني إذا قلت استقام يحطه ... خلف كما نظر الخلاف الأقبل)\n(لو بالذي عالجت لين فؤاده ... فأبى يلان به للان الجندل)\n(وتجنبي بيت الحبيب أوده ... أرضي البغيض به حديث معضل)\n(ولئن صددت لأنت لولا رقبتي ... أهوى من اللائي أزور وأدخل)\n(إن الشباب وعيشنا اللذ الذي ... كنا به زمنا نسر ونجذل)\n(ذهبت بشاشته وأصبح ذكره ... حزنا يعل به الفؤاد وينهل)\n(إلا تذكر ما مضى وصبابة ... منيت لقلب متيم لا يذهل)\n(أودى الشباب وأخلقت لذاته ... وأنا الحزين على الشباب المعول)\n(يبكي لما قلب الزمان جديده ... خلقا وليس على الزمان معول)\n(والرأس شامله البياض كأنه ... بعد السواد به الثغام المحجل)\n(وسفيهة هبت علي بسحرة ... جهلا تلوم على الثواء وتعذل)\n(فأجبتها أن قلت لست مطاعة ... فذري تنصحك الذي لا يقبل)\n(إني كفاني أن أعالج رحلة ... عمر ونبوة من يضن ويبخل)\n(بنوال ذي فجر تكون سجاله ... عمما إذا نزل الزمان الممحل)\n(ماض على حدث الأمور كأنه ... ذو رونق عضب جلاه الصيقل)\n(تبدي الرجال إذا بدا إعظامه ... حذر البغاث هوى لهن الأجدل)\n(فيرون أن له عليهم سورة ... وفضيلة سبقت له لا تجهل)\n(متحمل ثقل الأمور حوى له ... سبق المكارم سابق متمهل)\n(وله إذا نسبت قريش منهم ... مجد الأرومة والفعال الأفضل)\n(وله بمكة إذ أمية أهلها ... إرث إذا عد القديم مؤثل)\n(أعيت قرابته وكان لزومه ... أمرا أبان رشاده من يعقل)\n(وسموت عن أخلاقهم فتركتهم ... لنداك إن الحازم المتحول)","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":22,"spl":"الأحوص وبعض أخباره سرق أبيات سليمان بأعيانها وأدخلها في شعره وغير قوافيها فقط","tags":["البحتري","الحب والغزل"],"loc":1812},
{"id":"b102-43","bab":"الجزء 10","sec":"الأحوص وبعض أخباره سرق أبيات سليمان بأعيانها وأدخلها في شعره وغير قوافيها فقط","page":"ج10 ص107","text":"(ولقد بدأت أريد ود معاشر ... وعدوا مواعد أخلفت إن حصلوا)\n(حتى إذا رجع اليقين مطامعي ... يأسا وأخلفني الذين أؤمل)\n(زايلت ما صنعوا إليك برحلة ... عجلى وعندك عنهم متحول)\n(ووعدتني في حاجة فصدقتني ... ووفيت إذ كذبوا الحديث وبدلوا)\n(وشكوت غرما فادحا فحملته ... عني وأنت لمثله متحمل)\n(فلأشكرن لك الذي أوليتني ... شكرا تحل به المطي وترحل)\n(مدحا تكون لكم غرائب شعرها ... مبذولة ولغيركم لا تبذل)\n(فإذا تنحلت القريض فإنه ... لكم يكون خيار ما أتنحل)\n(ولعمر من حج الحجيج لبيته ... تهوي به قلص المطي الذمل)\n(إن امرأ قد نال منك قرابة ... يبغي منافع غيرها لمضلل)\n(تعفو إذا جهلوا بحملك عنهم ... وتنيل إن طلبوا النوال فتجزل)\n(وتكون معقلهم إذا لم ينجهم ... من شر ما يخشون إلا المعقل)\n(حتى كأنك يتقى بك دونهم ... من أسد بيشة خادر متبسل)\n(وأراك تفعل ما تقول وبعضهم ... مذق الحديث يقول ما لا يفعل)\n(وأرى المدينة حين صرت أميرها ... أمن البريء بها ونام الأعزل)\nقال عمر ما أراك أعفيتني مما استعفيت منه قال لأنه مدح عمر وعرض بأخيه أبي بكر","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":23,"spl":"الأحوص وبعض أخباره سرق أبيات سليمان بأعيانها وأدخلها في شعره وغير قوافيها فقط — نسبة ما مض","tags":["البحتري","المديح","السفر والحج"],"loc":1813},
{"id":"b102-44","bab":"الجزء 10","sec":"نسبة ما مضى في هذه الأخبار من الأغاني","page":"ج10 ص111","text":"\n(مالي أحن إذا جمالك قربت ... وأصد عنك وأنت مني أقرب)\n(وأرى البلاد إذا حللت بغيرها ... وحشا وإن كانت تظل وتخصب)\n(يا بيت خنساء الذي أتجنب ... ذهب الشباب وحبها لا يذهب)\n(تبكي الحمامة شجوها فتهيجني ... ويروح عازب همي المتأوب)\nالشعر لسليمان بن أبي دباكل والغناء لمعبد خفيف ثقيل أول بالبنصر عن عمرو وقال ابن المكي فيه خفيف ثقيل آخر لابن محرز وأوله\n(تبكي الحمامة شجوها فتهيجني ... )\nن هي عاتكة التي يذكرها الأحوص في شعره أخبرني الحسين بن يحيى قال قال حماد قرأت على أبي وقال محمد بن كناسة حدثني أبو دكين بن زكريا بن محمد بن عمار بن ياسر قال رأيت عاتكة التي يقول فيها الأحوص\n(يا بيت عاتكة الذي أتعزل ... )\nهي عجوز كبيرة وقد جعلت بين عينيها هلالا من نيلج تتملح به أخبرني الحرمي عن الزبير عن محمد بن محمد العمري قال عاتكة التي يشبب بها الأحوص عاتكة بنت عبد الله بن يزيد بن معاوية\nأخبرني الحرمي عن الزبير عن إسحاق بن عبد الملك أن الأحوص كان لينا وأن عاتكة التي ينسب بها ليست عاتكة بنت عبد الله بن يزيد بن معاوية وإنما هو رجل كان ينزل قرى كانت بين الأشراف كنى عنه بعاتكة\nأخبرني الحرمي عن الزبيري عن يعقوب بن حكيم قال كان الأحوص لينا وكان يلزم نازلا بالأشراف فنهاه أخوه عن ذلك فتركه فرقا من أخيه وكان يمر قريبا من خيمة النازل بالأشراف ويقول\n(يا بيت عاتكة الذي أتعزل ... حذر العدا وبه الفؤاد موكل)\nكني عنه بعاتكة ولا يقدر أن يدخل عليه","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":23,"spl":"الأحوص وبعض أخباره سرق أبيات سليمان بأعيانها وأدخلها في شعره وغير قوافيها فقط — نسبة ما مض","tags":["البحتري"],"song":1,"loc":1814,"partialRef":{"sid":"b102-41","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b102-45","bab":"الجزء 10","sec":"الفرزدق وكثير يزوران الأحوص","page":"ج10 ص113","text":"أخبرني الحرمي عن الزبيري عن محمد بن إسماعيل بن جعفر بن إبراهيم قال حدثني عبد العزيز بن عمران قال قدم الفرزدق المدينة فقال لكثير هل لك بنا في الأحوص نأتيه ونتحدث عنده فقال له وما نصنع به إذا والله نجد عنده عبدا حالكا أسود حلوكا يؤثره علينا ويبيت مضاجعه ليلته حتى يصبح\nقال الفرزدق فقلت إن هذا من عداوة الشعراء بعضهم لبعض قال فانهض بنا إليه إذا لا أب لغيرك قال الفرزدق فأردفت كثيرا ورائي على بغلتي وقلت تلفف يا أبا صخر فمثلك لا يكون رديفا فخمر رأسه وألصق في وجهه فجعلت لا أجتاز بمجلس قوم إلا قالوا من هذا وراءك يا أبا فراس فأقول جارية وهبها لي الأمير فلما أكثرت عليه من ذلك واجتاز على بني زريق وكان يبغضهم فقلت لهم ما كنت أقول قبل ذلك كشف عن رأسه وأومض\nوقال كذب ولكني كرهت أن أكون له رديفا وكان حديثه لي معجبا فركبت وراءه ولم تكن لي دابة أركبها إلا دابته فقالوا لا تعجل يا أبا صخر ههنا دواب كثيرة تركب منها ما أردت فقال دوابكم والله أبغض إلي من ردفه فسكتوا عنه وجعل يتغشم عليهم حتى جاوز أبصارهم فقلت والله ما قالوا لك بأسا فما\nالذي أغضبك عليهم فقال والله ما أعلم نفرا أشد تعصبا للقرشيين من نفر اجتزت بهم قال فقلت له وما أنت لا أم لك ولقريش قال أنا والله أحدهم\nقلت إن كنت أحدهم فأنت والله دعيهم قال دعيهم خير من صحيح نسب العرب وإلا فأنا والله من أكرم بيوتهم أنا أحد بني الصلت بن النضر قلت إنما قريش ولد فهر بن مالك فقال كذبت فقال ما علمك يا بن الجعراء بقريش هم بنو النضر بن كنانة ألم تر إلى النبي انتسب إلى النضر بن كنانة ولم يكن ليجاوز أكرم نسبه\nقال فخرجنا حتى أتينا الأحوص فوجدناه في مشربة له فقلنا له أنرقى إليك أم تنزل إلينا قال لا أقدر على ذلك عندي أم جعفر ولم أرها منذ أيام ولي فيها شغل فقال كثير أم جعفر والله بعض عبيد الزرانيق فقلنا له فأنشدنا بعض ما أحدثت به فأنشدنا قوله\n(يا بيت عاتكة الذي أتعزل ... حذر العدا وبه الفؤاد موكل)\nتى أتى على آخرها فقلت لكثير قاتله الله ما أشعره لولا ما أفسد به نفسه قال ليس هذا إفسادا هذا خسف إلى التخوم فقلت صدقت وانصرفنا من عنده فقال أين تريد فقلت إن شئت فمنزلي وأحملك على البغلة وأهب لك المطرف وإن شئت فمنزلك ولا أرزؤك شيئا فقال بل منزلي وأبذل لك ما قدرت عليه وانصرفنا إلى منزله فجعل يحدثني وينشدني حتى جاءت الظهر فدعا لي بعشرين دينارا\nوقال استعن بهذه يا أبا فراس على مقدمك قلت هذا أشد من حملان بني زريق قال والله إنك ما تأنف من أخذ هذا من أحد غير الخليفة قال الفرزدق فجعلت أقول في\nنفسي تالله إنه لمن قريش وهممت ألا أقبل منه فدعتني نفسي وهي طمعة إلى أخذها منه فأخذتها معنى قول كثير للفرزدق يا بن الجعراء يعيره بدغة وهي أم عمرو بن تميم وبها يضرب المثل في الحماقة فيقال هي أحمق من دغة وكانت حاملا فدخلت الخلاء فولدت وهي لا تعلم ما الولد وخرجت وسلاها بين رجليها وقد استهل ولدها فقالت يا جارتا أيفتح الجعر فاه فقالت جارتها نعم يا حمقاء ويدعو أباه فبنو تميم يعيرون بذلك ويقال للمنسوب منهم يا بن الجعراء","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":24,"spl":"الفرزدق وكثير يزوران الأحوص — ملاحاة بينه وبين السري بن عبد الرحمن","tags":["البحتري"],"loc":1815},
{"id":"b102-46","bab":"الجزء 10","sec":"ملاحاة بينه وبين السري بن عبد الرحمن","page":"ج10 ص115","text":"أخبرني الحرمي عن الزبير قال حدثني سليمان بن داود المجمعي قال اجتاز السري بن عبد الرحمن بن عتبة بن عويم بن ساعدة الأنصاري بالأحوص وهو ينشد قوله\n(يا بيت عاتكة الذي أتعزل ... )\nقال السري\n(يا بيت عاتكة المنوه باسمه ... اقعد على من تحت سقفك واعجل)\nفواثبه الأحوص وقال في ذلك\n(فأنت وشتمي في أكاريس مالك ... وسبي به كالكلب إذ ينبح النجما)\n(تداعى إلى زيد وما أنت منهم ... تحق أبا إلا الولاء ولا أما)\n(وإنك لو عددت أحساب مالك ... وأيامها فيها ولم تنطق الرجما)\n(أعادتك عبدا أو تنقلت كاذبا ... تلمس في حي سوى مالك جذما)\n(وما أنا بالمحسوس في جذم مالك ... ولا بالمسمى ثم يلتزم الإسما)\n(ولكن أبي لو قد سألت وجدته ... توسط منها العز والحسب الضخما)\nفأجابه السري فقال\n(سألت جميع هذا الخلق طرا ... متى كان الأحيوص من رجالي)\nهي أبيات ليست بجيدة ولا مختارة فألغيت ذكرها","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":24,"spl":"الفرزدق وكثير يزوران الأحوص — ملاحاة بينه وبين السري بن عبد الرحمن","tags":["البحتري"],"loc":1816,"partialRef":{"sid":"b102-41","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b102-47","bab":"الجزء 10","sec":"شعره يسعف دليل المنصور","page":"ج10 ص116","text":"أخبرني محمد بن أحمد بن الطلاس أبو الطيب عن أحمد بن الحارث الخراز عن المدائني وأخبرني به الحرمي عن الزبير قال حدثني عمي وقد جمعت روايتيهما أن المنصور أمر الربيع لما حج أن يسايره برجل يعرف المدينة وأهلها وطرقها ودورها وحيطانها فكان رجل من أهلها قد انقطع إلى الربيع زمانا وهو رجل من الأنصار فقال له تهيأ فإني أظن جدك قد تحرك إن أمير المؤمنين قد أمرني أن أسايره برجل يعرف المدينة وأهلها وطرقها وحيطانها\nودورها فتحسس موافقته ولا تبتدئه بشيء حتى يسألك ولا تكتمه شيئا ولا تسأله حاجة فغدا عليه بالرجل وصلى المنصور فقال يا ربيع الرجل فقال ها هو ذا فسار معه يخبره عما سأل حتى ندر من أبيات المدينة فأقبل عليه المنصور فقال من أنت أولا فقال من لا تبلغه معرفتك هكذا\nذكر الخراز وليس في رواية الزبير فقال مالك من الأهل والولد فقال والله ما تزوجت ولا لي خادم قال فأين منزلك قال ليس لي منزل قال فإن أمير المؤمنين قد أمر لك بأربعة آلاف درهم فرمى بنفسه فقبل رجله فقال له اركب فركب فلما أراد الانصراف\nقال للربيع يا أبا الفضل قد أمر لي أمير المؤمنين بصلة قال إيه قال إن رأيت أن تنجزها لي قال هيهات قال فأصنع ماذا قال لا أدري والله وفي رواية الخراز أنه\nقال ما أمر لك بشيء ولو أمر به لدعاني فقال أعطه أو وقع إلي فقال الفتى هذا هم لم يكن في الحساب فلبثت أياما ثم قال المنصور للربيع ما فعل الرجل\nقال حاضر قال سايرنا به الغداة ففعل وقال له الربيع إنه خارج بعد غد فاحتل لنفسك فإنه والله إن فاتك فإنه آخر العهد به فسار معه فجعل لا يمكنه شيء حتى انتهى إلى مسيره ثم رجع وهو كالمعرض عنه فلما خاف فوته أقبل عليه فقال يا أمير المؤمنين هذا بيت عاتكة قال وما بيت عاتكة قال إن أمرأ الذي يقول فيه الأحوص\n(يا بيت عاتكة الذي أتعزل ... )\nال فمه قال إنه يقول فيها\n(أن أمرا قد نال منك وسيلة ... يرجو منافع غيرها لمضلل)\n(وأراك تفعل ما تقول وبعضهم ... مذق الحديث يقول ما لا يفعل)\nقال الزبير في خبره فقال له لقد رأيتك أذكرت بنفسك يا سليمان\nابن مخلد أعطه أربعة آلاف درهم فأعطاه إياها وقال الخراز في خبره فضحك المنصور وقال قاتلك الله ما أظرفك يا ربيع أعطه ألف درهم فقال يا أمير المؤمنين إنها كانت أربعة آلاف درهم فقال ألف يحصل خير من أربعة آلاف لا تحصل وقال الخراز في خبره حدثني المدائني قال أخذ قوم من الزنادقة وفيهم ابن لابن المقفع فمر بهم على أصحاب المدائن فلما رآهم ابن المقفع خشي أن يسلم عليهم فيؤخذ فتمثل\n(يا بيت عاتكة الذي أتعزل ... حذر العدا وبه الفؤاد موكل)\nلأبيات ففطنوا لما أراد فلم يسلموا عليه ومضى","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":25,"spl":"شعره يسعف دليل المنصور","tags":["البحتري"],"loc":1817,"partialRef":{"sid":"b102-41","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b102-48","bab":"الجزء 10","sec":"هو ومعبد المغني في حضرة يزيد بن عبد الملك","page":"ج10 ص118","text":"أخبرني أحمد بن عبد العزيز الجوهري عن ابن شبة قال بلغني أن يزيد بن عبد الملك كتب إلى عامله أن يجهز إليه الأحوص الشاعر ومعبدا المغني فأخبرنا محمد بن خلف وكيع\nقال حدثنا عبد الله بن شبيب قال حدثني إسماعيل بن أبي أويس قال حدثني أبي قال حدثنا سلمة بن صفوان الزرقي عن الأحوص الشاعر وذكر إسماعيل بن سعيد الدمشقي أن الزبير بن بكار حدثه عن ابن أبي أويس عن أبيه عن مسلمة بن صفوان عن الأحوص\nوأخبرني به الحرمي عن الزبير عن عمه عن جرير المديني المغني وأبو مسكين قالوا جميعا كتب يزيد بن عبد الملك في خلافته إلى أمير المدينة وهو عبد الواحد ابن عبد الله النصري أن يحمل إليه الأحوص الشاعر ومعبدا المغني مولى\nابن قطن قال فجهزنا وحملنا إليه فلما نزلنا عمان أبصرنا غديرا وقصورا فقعدنا على الغدير وتحدثنا وذكرنا المدينة فخرجت جارية من بعض تلك القصور ومعها جرة تريد أن تستقي فيها ماء قال الأحوص فتغنت بمدحي في عمر بن عبد العزيز\n(يا بيت عاتكة الذي أتعزل ... )\nتغنت بأحسن صوت ما سمعته قط ثم طربت فألقت الجرة فكسرتها فقال معبد غنائي والله وقلت شعري والله فوثبنا إليها وقلنا لها لمن أنت يا جارية قالت لآل سعيد بن العاص وفي خبر جرير المغني لآل الوليد بن عقبة ثم اشتراني رجل من آل الوحيد بخمسين ألف درهم وشغف بي فغلبته بنت عم له طرأت عليه فتزوجها على أمري فعاقبت منزلتها منزلتي ثم علا مكانها مكاني فلم تزدها الأيام إلا ارتفاعا ولم تزدني إلا اتضاعا فلم ترض منه إلا بأن أخدمها فوكلتني باستقاء الماء فأنا على ما تريان أخرج أستقي الماء فإذا رأيت هذه القصور والغدران ذكرت المدينة فطربت إليها فكسرت جرتي فيعذلني أهلي ويلومونني\nقال فقلت لها أنا الأحوص والشعر لي وهذا معبد والغناء له ونحن ماضيان إلى أمير المؤمنين وسنذكرك له أحسن ذكر وقال جرير في خبره ووافقه وكيع ورواية عمر بن شبة قالوا فأنشأت الجارية تقول\n(إن تروني الغداة أسعى بجر ... أستقي الماء نحو هذا الغدير)\n(فلقد كنت في رخاء من العيش ... وفي كل نعمة وسرور)\n(ثم قد تبصران ما فيه أمسيت ... وماذا إليه صار مصيري)\n(فإلى الله أشتكي ما ألاقي ... من هوان وما يجن ضميري)\n(أبلغا عني الإمام وما يعرف ... صدق الحديث غير الخبير)\n(أنني أضرب الخلائق بالعود ... وأحكاهم ببم وزير)\n(فلعل الإله ينقذ مما ... أنا فيه فإنني كالأسير)\n(ليتني مت يوم فارقت أهلي ... وبلادي فزرت أهل القبور)\n(فاسمعا ما أقول لفا كما ... الله نجاحا في أحسن التيسير)\nقال الأحوص من وقته\n(إن زين الغدير من كسر الجر ... وغنى غناء فحل مجيد)\n(قلت من أنت يا ظعين فقالت ... كنت فيما مضى لآل الوليد)\nفي رواية الدمشقي\n(قلت من أين يا خلوب فقالت ... كنت فيما مضى لآل سعيد)\n(ثم أصبحت بعد حي قريش ... في بني خالد لآل الوحيد)\n(فغنائي لمعبد ونشيدي ... لفتى الناس الأحوص الصنديد)\n(فتباكيت ثم قلت أنا الأحوص ... والشيخ معبد فأعيدي)\n(فأعادت لنا بصوت شجي ... يترك الشيخ في الصبا كالوليد)\nفي رواية أبي زيد\n(فأعادت فأحسنت ثم ولت ... تتهادى فقلت قول عميد)\n(يعجز المال عن شراك ولكن ... أنت في ذمة الهمام يزيد)\n(ولك اليوم ذمتي بوفاء ... وعلى ذاك من عظام العهود)\n(أن سيجري لك الحديث بصوت ... معبدي يرد حبل الوريد)\n(يفعل الله ما يشاء فظني ... كل خير بنا هناك وزيدي)\n(قالت القينة الكعاب إلى ... الله أموري وأرتجي تسديدي)\nناه معبد ثاني ثقيل بالبنصر من رواية حبش والهشامي وغيرهما وهي طريقة هذا الصوت وأهل العلم بالغناء لا يصححونه لمعبد قال الأحوص وضع فيه معبد لحنا فأجاده فلما قدمنا على يزيد قال يا معبد أسمعني أحدث غناء غنيت وأطراه فغناه معبد\n(إن زين الغدير من كسر الجر ... وغنى غناء فحل مجيد)\nقال يزيد إن لهذا لقصة فأخبراني بها فأخبراه فكتب لعامله بتلك الناحية إن لآل فلان جارية من حالها ذيت وذيت فاشترها بما بلغت فاشتراها بمائة ألف درهم وبعث بها هدية وبعث معها بألطاف كثيرة فلما قدمت على يزيد رأى فضلا بارعا فأعجب بها وأجازها وأخدمها وأقطعها وأفرد لها قصرا\nقال فوالله ما برحنا حتى جاءتنا منها جوائز وكسا وطرف وقال الزبير في خبره عن عمه قال أظن القصة كلها مصنوعة وليس يشبه الشعر شعر الأحوص ولا هو من طرازه وكذلك","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":26,"spl":"هو ومعبد المغني في حضرة يزيد بن عبد الملك","tags":["البحتري"],"song":1,"loc":1818,"partialRef":{"sid":"b102-41","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b102-50","bab":"الجزء 10","sec":"هو ومعبد المغني في حضرة يزيد بن عبد الملك — ينذر بزوال الدولة الأموية","page":"ج10 ص118 – ج10 ص122","text":"ذكر عمر بن شبة في خبره أخبرني الحرمي عن الزبير قال سمعت هشام بن عبد الله بن عكرمة يحدث عن عتبة بن عمر بن عبد الرحمن بن الحارث بن هشام قال\nكنت مع يزيد بن عمر بن هبيرة ليلة الفرات فلما انهزم الناس التفت إلي فقال يا أبا الحارث أمسينا والله وهم كما قال الأحوص\n(أبكي لما قلب الزمان جديده ... خلقا وليس على الزمان معول)\nخبرني الحرمي عن الزبير عن محمد بن محمد العمري أن عاتكة بنت عبد الله بن يزيد بن معاوية رئيت في النوم قبل ظهور دولة بني العباس على بني أمية كأنها عريانة ناشرة شعرها تقول\n(أين الشباب وعيشنا اللذ الذي ... كنا به زمنا نسر ونجذل)\n(ذهبت بشاشته وأصبح ذكره ... حزنا يعل به الفؤاد وينهل)\nتأول الناس ذلك بزوال دنيا بني أمية فكان كما قالوا أخبرني بهذا الخبر الحسن بن يحيى عن حماد عن أبيه عن الجمحي عن شيخ من قريش أنه رأى في النوم امرأة من ولد عثمان بن عفان على منايم على دار عثمان المقبلة على المسجد وهي حاسرة في يديها عود وهي تضرب به وتغني\n(أين الشباب وعيشنا اللذ الذي ... كنا به يوما نسر ونجذل)\n(ذهبت بشاشته وأصبح ذكره ... حزنا يعل به الفؤاد وينهل)\nال فما لبثنا إلا يسيرا حتى خرج الأمر عن أيديهم وقتل مروان\nقال إسحاق المنامة الدكان وجمعها منايم\n(يا هند إنك لو علمت ... بعاذلين تتابعا)\n(قالا فلم أسمع لما ... قالا وقلت بل اسمعا)\n(هند أحب إلي من ... مالي وروحي فارجعا)\n(ولقد عصيت عواذلي ... وأطعت قلبا موجعا)\nلشعر لعبد الله بن الحسن بن الحسن عليهم السلام والغناء لابن سريج ولحنه فيه لحنان أحدهما من القدر الأوسط من الثقيل الأول بالسبابة في مجرى الوسطى عن إسحاق والآخر رمل بالوسطى عن عمرو وفيه خفيف ثقيل ذكر أبو العبيس أنه لابن سريج وذكر الهشامي وابن المكي أنه للغريض وذكر حبش أن لإبراهيم فيه رملا آخر بالبنصر وقال أحمد بن عبيد الذي صح فيه ثقيل الأول وخفيفه ورمله وذكر إبراهيم أن فيه لحنا لابن عباد","topic":"أخبار البحتري ونسبه","topicNo":102,"sp":27,"spl":"هو ومعبد المغني في حضرة يزيد بن عبد الملك — ينذر بزوال الدولة الأموية","tags":["البحتري"],"song":1,"loc":1819}]);
window.__BOOK__['p05'].push([{"id":"b103-1","bab":"الجزء 10","sec":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره وخبر هذا","page":"ج10 ص123","text":"الشعر عبد الله بن الحسن بن الحسن بن علي بن أبي طالب عليهم السلام وقد مضى نسبه في أخبار عمه الحسين صلوات الله عليه في شعره الذي يقول فيه\n(لعمرك إنني لأحب دارا ... تحل بها سكينة والرباب)\nويكنى عبد الله بن الحسن أبا محمد وأم عبد الله بن الحسن بن الحسن فاطمة بنت الحسين بن علي بن أبي طالب عليهم السلام وأمها أم إسحاق بنت طلحة بن عبيد الله وأمها الجرباء بنت قسامة بن رومان عن طيء","topic":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره","topicNo":103,"sp":0,"spl":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره وخبر هذا — زواجه فاطمة بنت الحسي","tags":["الجواري والنساء"],"loc":1820},
{"id":"b103-2","bab":"الجزء 10","sec":"لماذا سميت جدته الجرباء","page":"ج10 ص124","text":"أخبرني أحمد بن سعيد قال حدثنا يحيى بن الحسن قال إنما سميت الجرباء لحسنها كانت لا تقف إلى جنبها امرأة وإن كانت جميلة إلا استقبح منظرها لجمالها وكان النساء يتحامين أن يقفن إلى جنبها فشبهت بالناقة الجرباء التي تتوقاها الإبل مخافة أن تعديها وكانت أم إسحاق من أجمل نساء قريش وأسوئهن خلقا ويقال إن نساء بني تيم كانت لهن حظوة عند أزواجهن على سوء أخلاقهن ويروى أن\nأم إسحاق كانت ربما حملت وولدت وهي لا تكلم زوجها أخبرني الحرمي بن أبي العلاء عن الزبير بن بكار عن عمه بذلك قال وقد كانت أم إسحاق عند الحسن بن علي بن أبي طالب صلوات الله عليه قبل أخيه الحسين عليه السلام فلما حضرته الوفاة دعا بالحسين صلوات الله عليه فقال له يا أخي إني أرضى هذه المرأة لك فلا تخرجن من بيوتكم فإذا انقضت عدتها فتزوجها فلما توفي الحسن عنها تزوجها الحسين عليه السلام وقد كانت ولدت من الحسن عليه السلام ابنه طلحة بن الحسن فهو أخو فاطمة لأمها وابن عمها وقد درج طلحة ولا عقب له ومن طرائف أخبار التيميات من نساء قريش في حظوتهن وسوء أخلاقهن ما أخبرنا به الحرمي بن أبي العلاء عن الزبير بن بكار عن محمد بن عبد الله\nقال كانت أم سلمة بنت محمد بن طلحة عند عبد الله بن الحسن وكانت تقسو عليه قسوة عظيمة وتغلظ له ويفرق منها ولا يخالفها فرأى يوما منها طيب نفس فأراد أن يشكو إليها قسوتها فقال لها يا بنت محمد قد أحرق والله قلبي فحددت له النظر وجمعت وجهها وقالت له أحرق قلبك ماذا فخافها فلم يقدر على أن يقول لها سوء خلقك فقال لها حب أبي بكر الصديق فأمسكت عنه وتزوج الحسن بن الحسن فاطمة بنت الحسين في حياة عمه وهو عليه السلام زوجه إياها","topic":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره","topicNo":103,"sp":0,"spl":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره وخبر هذا — زواجه فاطمة بنت الحسي","tags":["الجواري والنساء","الموت","الرواية والكتابة"],"loc":1821},
{"id":"b103-3","bab":"الجزء 10","sec":"زواجه فاطمة بنت الحسين","page":"ج10 ص125","text":"أخبرني الطوسي والحرمي عن الزبير عن عمه بذلك وحدثني أحمد\nابن محمد بن سعيد عن يحيى بن الحسن عن إسماعيل بن يعقوب قال حدثني جدي عبد الله بن موسى بن عبد الله بن الحسن قال خطب الحسن بن الحسن إلى عمه الحسين صلوات الله عليه وسأله أن يزوجه إحدى ابنتيه فقال له الحسين عليه السلام اختر يا بني أحبهما إليك فاستحيا الحسن ولم يحر جوابا فقال له الحسين عليه السلام فإني اخترت منهما لك ابنتي فاطمة فهي أكثر شبها بأمي فاطمة بنت رسول الله\nأخبرني الطوسي والحرمي عن الزبير عن عمه مصعب أن الحسن لما خيره عمه اختار فاطمة وكانوا يقولون إن امرأة سكينة مردودتها لمنقطعة القرين في الجمال\nأخبرني الطوسي والحرمي بن أبي العلاء عن الزبير بن بكار وأخبرني محمد بن العباس اليزيدي عن أحمد بن يحيى وأحمد بن زهير عن الزبير وأخبرني أحمد بن سعيد عن يحيى بن الحسن عن الزبير بن بكار واللفظ للحسن بن علي وخبره أتم قال قال الزبير حدثني عمي مصعب ولم يذكر أحدا","topic":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره","topicNo":103,"sp":0,"spl":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره وخبر هذا — زواجه فاطمة بنت الحسي","tags":["الجواري والنساء","اللهو والمزاح"],"loc":1822},
{"id":"b103-4","bab":"الجزء 10","sec":"ماذا قال حين حضرته الوفاة","page":"ج10 ص126","text":"وأخبرني محمد بن يحيى عن أيوب عن عمر بن أبي الموالي قال الزبير وحدثني عبد الملك بن عبد العزيز بن يوسف بن الماجشون وقد دخل حديث بعضهم في بعض حديث الآخرين أن الحسن بن الحسن لما حضرته الوفاة جزع وجعل يقول إني لأجد\nكربا ليس إلا هو كرب الموت وأعاد ذلك دفعات فقال له بعض أهله ما هذا الجزع تقدم على رسول الله وهو جدك وعلى علي والحسن والحسين صلوات الله عليهم وهم آباؤك فقال لعمري إن الأمر لكذلك ولكن كأني بعبد الله بن عمرو بن عثمان حين أموت وقد جاء في مضرجتين أو ممصرتين وهو يرجل جمته يقول أنا من بني عبد مناف جئت لأشهد ابن عمي وما به إلا أن يخطب فاطمة بنت الحسين فإذا جاء فلا يدخل علي فصاحت فاطمة أتسمع\nقال نعم قالت أعتقت كل مملوك لي وتصدقت بكل ملك لي إن أنا تزوجت بعدك أحدا أبدا قال فسكن الحسن وما تنفس ولا تحرك حتى قضى فلما ارتفع الصياح أقبل عبد الله على الصفة التي ذكرها الحسن فقال بعض القوم ندخله\nوقال بعضهم لا يدخل وقال قوم لا يضر دخوله فدخل وفاطمة تصك وجهها فأرسل إليها وصيفا كان معه فجاء يتخطى الناس حتى دنا منها فقال لها يقول لك مولاي أبقي على وجهك فإن لنا فيه أربا\nقال فأرسلت يدها في كمها واختمرت وعرف ذلك منها فما لطمت وجهها حتى دفن صلوات الله عليه فلما انقضت عدتها خطبها فقالت فكيف لي بنذري ويميني فقال نخلف عليك بكل عبد عبدين وبكل شيء شيئين ففعل وتزوجته وقد\nقيل في تزويجه إياها غير هذا أخبرني به أحمد بن محمد بن إسماعيل الهمداني عن يحيى بن الحسن العلوي عن أخيه أبي جعفر عن إسماعيل بن يعقوب عن محمد بن عبد الله البكري\nأن فاطمة لما خطبها عبد الله أبت أن تتزوجه فحلفت عليها أمها لتتزوجنه وقامت في الشمس وآلت لا تبرح حتى تتزوجه فكرهت فاطمة أن تحرج فتزوجته وكان عبد الله بن الحسن بن الحسن شيخ أهله وسيدا من ساداتهم ومقدما فيهم فصلا وعلما وكرما وحبسه أبو جعفر المنصور في الهاشمية بالكوفة لما خرج عليه ابناه محمد وإبراهيم فمات في الحبس وقيل إنه سقط عليه وقيل غير ذلك","topic":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره","topicNo":103,"sp":1,"spl":"ماذا قال حين حضرته الوفاة","tags":["الحب والغزل","الجواري والنساء"],"loc":1823},
{"id":"b103-5","bab":"الجزء 10","sec":"انتهى كل حسن إليه","page":"ج10 ص128","text":"أخبرني أحمد بن محمد بن سعيد عن يحيى بن الحسن عن علي بن أحمد الباهلي قال سمعت مصعبا الزبيري يقول انتهى كل حسن إلى عبد الله بن حسن وكان يقال من أحسن الناس فيقال عبد الله بن الحسن ويقال من أفضل الناس فيقال عبد الله بن الحسن\nحدثني محمد بن الحسن الخثعمي الأشناني والحسن بن علي السلولي قالا حدثنا عباد بن يعقوب قال حدثنا تلميذ بن سليمان قال رأيت عبد الله بن الحسن وسمعته يقول أنا أقرب الناس إلى رسول الله ولدتني بنت رسول الله مرتين حدثني أحمد بن محمد بن سعيد عن يحيى بن الحسن عن إسماعيل ابن يعقوب عن عبد الله بن موسى قال\nأول من اجتمعت له ولادة الحسن عليه السلام والحسين صلوات الله عليهما عبد الله بن الحسن عليه السلام حدثني محمد بن الحسن الأشناني عن عبد الله بن يعقوب عن بندقة ابن محمد بن حجازة الدهان\nقال رأيت عبد الله بن الحسن فقلت هذا والله سيد الناس كان مكسوا نورا من قرنه إلى قدمه قال علي بن الحسين وقد روي ذلك في أخبار أبي جعفر محمد بن علي عليه السلام وأمه أم عبد الله بنت الحسن بن علي عليه السلام\nحدثني أحمد بن محمد بن سعيد عن يحيى بن الحسن عن القاسم بن عبد الرزاق قال جاء منظور بن زيان الفزاري إلى حسن بن حسن وهو جده أبو أمه فقال له لعلك أحدثت بعدي أهلا\nقال نعم تزوجت بنت عمي الحسين ابن علي عليهما السلام قال بئسما صنعت أما علمت أن الأرحام إذا التقت أضوت كان ينبغي أن تتزوج في الغرب قال فإن الله جل وعز قد رزقني منها ولدا\nقال أرنيه فأخرج إليه عبد الله بن الحسن فسر به وقال أنجبت هذا والله ليث غاب ومعدو عليه قال فإن الله تعالى قد رزقني منها ولدا ثانيا قال فأرنيه فأخرج إليه حسن بن حسن بن حسن فسر به وقال أنجبت وهذا دون الأول قال فإن الله قد رزقني منها ولدا ثالثا قال فأرنيه فأراه إبراهيم بن الحسن حدثني أبو عبيد محمد بن أحمد الصيرفي قال حدثنا محمد بن علي\nابن خلف قال حدثنا عمر بن عبد الغفار قال حدثنا سعيد بن أبان القرشي قال كنت عند عمر بن عبد العزيز فدخل عبد الله بن الحسن عليه وهو يومئذ شاب في إزار ورداء فرحب به وأدناه وحياه وأجلسه إلى جنبه وضاحكه ثم غمز عكنة من بطنه وليس في البيت حينئذ إلا أموي فقيل له ما حملك على غمز بطن هذا الفتى\nقال إني لأرجو بها شفاعة محمد حدثني عمر بن عبد الله بن جميل العتكي عن عمر بن شبة عن إسماعيل بن جعفر الجعفري قال حدثني سعيد بن عقبة الجهني\nقال إني لعند عبد الله بن الحسن إذ أتاني آت فقال هذا رجل يدعوك فخرجت فإذا أنا بأبي عدي الشاعر الأموي فقال أعلم أبا محمد فخرج إليه عبد الله وهم خائفون فأمر له بأربعمائة دينار وهند بمائتي دينار فخرج بستمائة دينار وقد روى مالك ابن أنس عن عبد الله بن الحسن الحديث","topic":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره","topicNo":103,"sp":2,"spl":"انتهى كل حسن إليه","tags":["الجواري والنساء","الرواية والكتابة"],"loc":1824},
{"id":"b103-7","bab":"الجزء 10","sec":"كان يسدل شعره — شعر تمثل به","page":"ج10 ص130 – ج10 ص131","text":"حدثني أحمد بن محمد بن سعيد عن يحيى بن الحسن قال حدثنا علي بن أحمد الباهلي عن مصعب بن عبد الله قال سئل مالك\nعن السدل قال رأيت من يرضى بفعله عبد الله بن الحسن يفعله والسبب في حبس عبد الله بن الحسن وخروج ابنيه وقتلهما يطول ذكره وقد أتى عمر بن شبة منه بما لا يزيد عليه أحد إلا اليسير ولكن من أخباره ما يحسن ذكره ها هنا فنذكره أخبرني عمر بن عبد الله العتكي عن عمر بن شبة قال حدثني موسى ابن سعيد بن عبد الرحمن وأيوب بن عمر عن إسماعيل بن أبي عمرو قالوا\nلما بنى أبو العباس بناءه بالأنبار الذي يدعى الرصافة رصافة أبي العباس قال لعبد الله بن الحسن ادخل فانظر ودخل معه فلما رآه تمثل\n(ألم تر حوشبا أمسى يبني ... بناء نفعه لبني نفيله)\n(يؤمل أن يعمر عمر نوح ... وأمر الله يحدث كل ليلة)\nاحتمله أبو العباس ولم يبكته بها أخبرني عمي عن ابن شبة عن يعقوب بن القاسم عن عمرو بن شهاب وحدثني أحمد بن محمد بن سعيد عن يحيى بن الحسن عن الزبير عن محمد ابن الضحاك عن أبيه قالوا إن أبا العباس كتب إلى عبد الله بن الحسن في تغيب ابنيه\n(أريد حياته ويريد قتلي ... عذيرك من خليلك من مراد)\nقال عمر بن شبة وإنما كتب بها إلى محمد قال عمر بن شبة فبعثوا إلى عبد الرحمن بن مسعود مولى أبي حنين فأجابه\n(وكيف يريد ذاك وأنت منه ... بمنزلة النياط من الفؤاد)\n(وكيف يريد ذاك وأنت منه ... وزندك حين تقدح من زناد)\n(وكيف يريد ذاك وأنت منه ... وأنت لهاشم رأس وهاد)\nخبرني عمر بن عبد الله بن شبة عن عيسى بن عبد الله بن محمد بن عمر بن علي بن أبي طالب عليهم السلام عن الحسن بن زيد عن عبد الله بن الحسن\nقال بينا أنا في سمر أبي العباس وكان إذا تثاءب أو ألقى المروحة من يده قمنا فألقاها ليلة فقمنا فأمسكني فلم يبق غيري فأدخل يده تحت فراشه وأخرج إضبارة كتب\nوقال اقرأ يا أبا محمد فقرأت فإذا كتاب من محمد بن هشام بن عمرو التغلبي يدعوه إلى نفسه فلما قرأته قلت له يا أمير المؤمنين لك عهد الله وميثاقه ألا ترى منهما شيئا تكرهه ما كانا في الدنيا أخبرنا العتكي عن ابن شبة عن محمد بن إسماعيل عن عبد العزيز بن عمر عن عبد الله بن عبدة بن محمد بن عمار بن ياسر\nقال لما استخلف أبو جعفر ألح في طلب محمد والمسألة عنه وعمن يؤويه فدعا بني هاشم رجلا رجلا فسألهم عنه فكلهم يقول قد علم أمير المؤمنين أنك قد عرفته بطلب هذا الشأن قبل اليوم فهو يخافك على نفسه ولا يريد لك خلافا ولا يحب لك معصية إلا الحسن بن زيد فإنه أخبره خبره فقال والله ما آمن وثوبه عليك وأنه لا ينام فيه فر رأيك فيه قال ابن أبي عبيدة فأيقظ من لا ينام\nأخبرني عمر بن عبد الله بن شبة عن عيسى بن عبد الله بن محمد بن عمر بن علي بن أبي طالب عليه السلام عن محمد بن عمران عن عقبة بن سلم أن أبا جعفر دعاه فسأله عن اسمه ونسبه فقال أنا عقبة بن سلم بن نافع بن الأزدهاني\nقال إني أرى لك هيئة وموضعا وإني لأريدك لأمر أنا به معني قال أرجو أن أصدق ظن أمير المؤمنين قال فأخف شخصك وائتني في يوم كذا وكذا فأتيته فقال إن بني عمنا هؤلاء قد أبوا إلا كيدا بملكنا ولهم شيعة بخراسان بقرية كذا وكذا يكاتبونهم ويرسلون إليهم بصدقات وألطاف فاذهب حتى تأتيهم متنكرا بكتاب تكتبه عن أهل تلك القرية ثم تسير ناحيتهم فإن كانوا نزعوا عن رأيهم علمت ذلك وكنت على حذر منهم حتى تلقى عبد الله بن الحسن متخشعا وإن جبهك وهو فاعل فاصبر وعاوده أبدا حتى يأنس بك فإذا ظهر لك ما في قلبه فاعجل إلي ففعل ذلك وفعل به حتى أنس عبد الله بناحيته فقال له عقبة الجواب فقال له أما الكتاب فإني لا أكتب إلى أحد ولكن أنت كتابي إليهم فأقرئهم السلام وأخبرهم أن ابني خارج لوقت كذا وكذا فشخص عقبة حتى قدم على أبي جعفر فأخبره الخبر","topic":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره","topicNo":103,"sp":3,"spl":"كان يسدل شعره — شعر تمثل به","tags":["اللهو والمزاح"],"loc":1825},
{"id":"b103-8","bab":"الجزء 10","sec":"بماذا أجاب أبا جعفر عندما سأله عن ابنيه","page":"ج10 ص133","text":"أخبرني العتكي عن عمر بن محمد بن يحيى بن الحارث بن إسحاق قال سأل أبو جعفر عبد الله بن الحسن عن ابنيه لما حج فقال لا أعلم بهما حتى تغالظا فأمضه أبو جعفر فقال له يا أبا جعفر بأي أمهاتي\nتمضني أبخديجة بنت خويلد أم بفاطمة بنت رسول الله أم بفاطمة بنت الحسين عليهم السلام أم بأم إسحاق بنت طلحة قال لا ولا بواحدة منهن ولكن بالجرباء بنت قسامة فوثب المسيب بن زهير فقال يا أمير المؤمنين دعني أضرب عنق ابن الفاعلة فقام زياد بن عبيد الله فألقى عليه رداءه\nوقال يا أمير المؤمنين هبه لي فأنا المستخرج لك ابنيه فتخلصه منه قال ابن شبة وحدثني بكر بن عبد الله مولى أبي بكر عن علي بن رباح أخي إبراهيم بن رباح عن صاحب المصلى\nقال إني لواقف على رأس أبي جعفر وهو يتغدى بأوطاس وهو متوجه إلى مكة ومعه على مائدته عبد الله بن الحسن وأبو الكرام الجعفري وجماعة من بني العباس فأقبل على عبد الله بن الحسن فقال يا أبا محمد محمد وإبراهيم أراهما قد استوحشا من ناحيتي وإني لأحب أن يأنسا بي ويأتياني فأصلهما وأزوجهما وأخلطهما بنفسي\nقال وعبد الله يطرق طويلا ثم يرفع رأسه ويقول وحقك يا أمير المؤمنين مالي بهما ولا بموضعهما من البلاد علم ولقد خرجا عن يدي فيقول لا تفعل يا أبا محمد اكتب إليهما وإلى من يوصل كتابك إليهما\nقال وامتنع أبو جعفر عن عامة غدائه ذلك اليوم إقبالا على عبد الله وعبد الله يحلف أنه لا يعرف موضعهما وأبو جعفر يكرر عليه لا تفعل يا أبا محمد قال ابن شبة فحدثني محمد بن عباد عن السندي بن شاهك أن أبا جعفر قال لعقبة بن سلم إذا فرغنا من الطعام فلحظتك فامثل\nبين يدي عبد الله فإنه سيصرف بصره عنك فدر حتى تغمز ظهره بإبهام رجلك حتى يملأ عينيه منك ثم حسبك وإياك أن يراك ما دام يأكل ففعل ذلك عقبة فلما رآه عبد الله وثب حتى جثا بين يدي أبي جعفر\nوقال يا أمير المؤمنين أقلني أقالك الله قال لا أقالني الله إن أقلتك ثم أمر بحبسه قال ابن شبة فحدثني أيوب بن عمر عن محمد بن خلف المخزومي\nقال أخبرني العباس بن محمد بن علي بن عبد الله بن عباس قال لما حج أبو جعفر في سنة أربعين ومائة أتاه عبد الله وحسن ابنا حسن فإنهما وإياي لعنده وهو مشغول بكتاب ينظر فيه إذ تكلم المهدي فلحن فقال عبد اله يا أمير المؤمنين ألا تأمر بهذا من يعدل لسانه فإنه يفعل فعل الأمة فلم يفهم وغمزت عبد الله فلم ينتبه وعاد لأبي جعفر فأحفظ من ذلك وقال له أين ابنك قال لا أدري قال لتأتيني به قال لو كان تحت قدمي ما رفعتهما عنه قال يا ربيع فمر به إلى الحبس","topic":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره","topicNo":103,"sp":4,"spl":"بماذا أجاب أبا جعفر عندما سأله عن ابنيه","tags":["الحب والغزل"],"loc":1826},
{"id":"b103-9","bab":"الجزء 10","sec":"توفي في محبسه بالهاشمية","page":"ج10 ص135","text":"أخبرني أحمد بن محمد بن سعيد عن يحيى بن الحسن قال توفي عبد الله في محبسه بالهاشمية وهو ابن خمس وسبعين سنة في سنة خمس وأربعين ومائة وهند التي عناها عبد الله في شعره الذي فيه الغناؤ زوجته هند بنت أبي عبيدة بن عبد الله بن زمعة بن الأسود بن المطلب بن أسد بن عبد العزى بن قصي وأمها قرينة بنت يزيد بن عبد الله بن وهب بن زمعة بن الأسود بن الطلب وكان أبو عبيدة جوادا وممدحا وكانت هند قبل عبد الله بن الحسن\nتحت عبد الله بن عبد الملك بن مروان فمات عنها فأخبرني الحرمي عن الزبير عن سليمان بن عياش السعدي قال لما توفي أبو عبيدة وجدت ابنته هند وجدا شديدا فكلم عبد الله بن الحسن محمد بن بشير الخارجي أن يدخل على هند بنت أبي عبيدة فيعزيها ويؤسيها عن أبيها فدخل معه عليها فلما نظر إليها صاح بأبعد صوته\n(قومي اضربي عينيك يا هند لن ترى ... أبا مثله تسمو إليه المفاخر)\n(وكنت إذا أسبلت فوقك والدا ... تزيني كما زان اليدين الأساور)\nصكت وجهها وصاحت بحربها وجهدها فقال له عبد الله بن الحسن ألهذا دخلت فقال الخارجي وكيف أعزي عن أبي عبيدة وأنا أعزى به أخبرني العتكي عن شبة\nقال حدثني عبد الرحمن بن جعفر بن سليمان عن علي بن صالح قال زوج عبد الملك بن مروان ابنه عبد الله هند بنت أبي عبيدة وريطة بنت عبد الله بن عبد المدان لما كان يقال إنه كائن في أولادهما فمات عنهما عبد الله أو طلقهما فتزوج هندا عبد الله ابن الحسن وتزوج ريطة محمد بن علي فجاءت بأبي العباس السفاح\nأخبرني العتكي عن عمر بن شبة عن ابن داجة عن أبيه قال لما مات عبد الله بن عبد الملك رجعت هند بميراثها منه فقال عبد الله بن حسن لأمه فاطمة اخطبي علي هندا فقالت إذا تردك أتطمع في هند وقد ورثت ما ورثته وأنت ترب لا مال لك فتركها ومضى إلى أبي عبيدة\nأبي هند فخطبها إليه فقال في الرحب والسعة أما مني فقد زوجتك مكانك لا تبرح ودخل على هند فقال يا بنية هذا عبد الله بن حسن أتاك خاطبا قالت فما\nقلت له قال زوجته قالت أحسنت قد أجزت ما صنعت وأرسلت إلى عبد الله لا تبرح حتى تدخل على أهلك قال فتزينت له فبات بها معرسا من ليلته ولا تشعر أمه فأقام سبعا ثم أصبح يوم سابعه غاديا على أمه وعليه ردع الطيب وفي غير ثيابه التي تعرف فقالت له يا بني من أين لك هذا\nقال من عند التي زعمت أنها لا تريدني أخبرني حبيب بن نصر المهلبي وعمي عبد العزيز بن أحمد بن بكار قالا حدثنا الزبير قال حدثتني ظبية مولاة فاطمة قالت كان جدك عبد الله بن مصعب يستنشدني كثيرا أبيات عبد الله بن حسن ويعجب بها\n(إن عيني تعودت كحل هند ... جمعت كفها مع الرفق لينا)\n\n(يا عيد مالك من شوق وإيراق ... ومر طيف على الأهوال طراق)\n(يسري على الأين والحيات محتفيا ... نفسي فداؤك من سار على ساق)\nروضه من البسيط العيد ما اعتاد الإنسان من هم أو شوق أو مرض أو ذكر والأين والأيم ضرب من الحيات والأين الإعياء أيضا وروى أبو عمرو\n(يا عيد قلبك من شوق وإيراق ... )\nلشعر لتأبط شرا والغناء لابن محرز ثقيل أول بالوسطى من رواية يحيى المكي وحبش وذكر الهشامي أنه من منحول يحيى إلى ابن محرز","topic":"ذكر عبد الله بن الحسن بن الحسن عليهم السلام ونسبه وأخباره","topicNo":103,"sp":5,"spl":"توفي في محبسه بالهاشمية","tags":["المديح"],"song":1,"loc":1827,"partial":1},
{"id":"b104-2","bab":"الجزء 10","sec":"أخبار تأبط شرا ونسبه — لقبه وسببه","page":"ج10 ص137 – ج10 ص138","text":"هو ثابت بن جابر بن سفيان بن عميثل بن عدي بن كعب بن حزن وقيل حرب بن تميم بن سعد بن فهم بن عمرو بن قيس عيلان بن مضر بن نزار وأمه امرأة يقال لها أميمة يقال إنها من بني القين بطن من فهم ولدت خمسة نفر تأبط شرا وريش بلغب وريش نسر وكعب جدر ولا بواكي له وقيل إنها ولدت سادسا اسمه عمرو\nوتأبط شرا لقب لقب به ذكر الرواة أنه كان رأى كبشا في الصحراء فاحتمله تحت إبطه فجعل يبول عليه طول طريقه فلما قرب من الحي ثقل عليه الكبش فلم يقله فرمى به فإذا هو الغول فقال له قومه ما تأبطت يا ثابت قال الغول قالوا لقد تأبطت شرا فسمي بذلك وقيل بل قالت له أمه كل إخوتك يأتيني بشيء إذا راح غيرك فقال لها سآتيك الليلة بشيء ومضى فصاد أفاعي كثيرة من أكبر ما قدر عليه\nفلما راح أتى بهن في جراب متأبطا له فألقاه بين يديها ففتحته فتساعين في بيتها فوثبت وخرجت فقال لها نساء الحي ماذا أتاك به ثابت فقالت أتاني بأفاع في جراب قلن وكيف حملها قالت تأبطها قلن لقد تأبط شرا فلزمه تأبط شرا\nحدثني عمي قال حدثني علي بن الحسين بن عبد الأعلى عن أبي محلم بمثل هذه الحكاية وزاد فيها أن أمه قالت له في زمن الكمأة ألا ترى غلمان الحي يجتنون لأهليهم الكمأة فيروحون بها فقال أعطيني جرابك حتى أجتني لك فيه فأعطته فملأه لها أفاعي\nوذكر باقي الخبر مثل ما تقدم ومن ذكر أنه إنما جاءها بالغول يحتج بكثرة أشعاره في هذا المعنى فإنه يصف لقاءه إياها في شعره كثيرا فمن ذلك قوله\n(فأصبحت الغول لي جارة ... فيا جارتا لك ما أهولا)\n(فطالبتها بضعها فالتوت ... علي وحاولت أن أفعلا)\n(فمن كان يسأل عن جارتي ... فإن لها باللوى منزلا)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":0,"spl":"أخبار تأبط شرا ونسبه — لقبه وسببه — كان أحد العدائين المعدودين — شعره في غول تأبطها","tags":["الجواري والنساء","الوصف والطبيعة"],"loc":1828},
{"id":"b104-4","bab":"الجزء 10","sec":"كان أحد العدائين المعدودين — شعره في غول تأبطها","page":"ج10 ص139 – ج10 ص140","text":"أخبرني عمي عن الحزنبل عن عمرو بن أبي عمرو الشيباني قال نزلت على حي من فهم إخوة بني عدوان من قيس فسألتهم عن خبر تأبط شرا فقال لي بعضهم وما سؤالك عنه أتريد أن تكون لصا قلت لا ولكن أريد أن\nأعرف أخبار هؤلاء العدائين فأتحدث بها فقالوا نحدثك بخبره إن تأبط شرا كان أعدى ذي رجلين وذي ساقين وذي عينين وكان إذا جاع لم تقم له قائمة فكان ينظر إلى الظباء فينتقي على نظره أسمنها لم يجري خلفه فلا يفوته حتى يأخذه فيذبحه بسيفه ثم يشويه فيأكله وإنما سمي تأبط شرا لأنه فيما حكي لنا لقي الغول في ليلة ظلماء في موضع يقال له رحى بطان في بلاد هذيل فأخذت عليه الطريق فلم يزل بها حتى قتلها وبات عليها فلما أصبح حملها تحت إبطه وجاء بها إلى أصحابه فقالوا له لقد تأبطت شرا فقال في ذلك\n(تأبط شرا ثم راح أو اغتدى ... توائم غنما أو يشيف على ذحل)\nوائم يوافق ويشيف يقتدر وقال أيضا في ذلك\n(ألا من مبلغ فتيان فهم ... بما لاقيت عند رحى بطان)\n(وأني قد لقيت الغول تهوي ... بسهب كالصحيفة صحصحان)\n(فقلت لها : كلانا نضو أين ... أخو سفر فخلى لي مكاني)\n(فشدت شدة نحوي فاهوى ... لها كفي بمصقول يماني)\n(فأضربها بلا دهش فخرت ... صريعا لليدين وللجران)\n(فقالت عد فقلت لها رويدا ... مكانك إنني ثبت الجنان)\n(فلم أنفك متكئا عليها ... لأنظر مصبحا ماذا أتاني)\n(إذا عينان في رأس قبيح ... كرأس الهر مشقوق اللسان)\n(وساقا مخدج وشواة كلب ... وثوب من عباء أو شنان)\nخبرنا الحسين بن يحيى قال قرأت على حماد وحدثك أبوك عن حمزة ابن عتبة اللهبي قال قيل لتأبط شرا هذه الرجال غلبتها فكيف لا تنهشك الحيات في سراك فقال إني لأسري البردين يعني أول الليل لأنها تمور خارجة من حجرتها وآخر الليل تمور مقبلة إليها\nقال حمزة ولقي تأبط شرا ذات يوم رجلا من ثقيف يقال له أبو وهب كان جبانا أهوج وعليه حلة جيدة فقال أبو وهب لتأبط شرا بم تغلب الرجال يا ثابت وأنت كما أرى دميم ضئيل\nقال باسمي إنما أقول ساعة ما ألقى الرجل أنا تأبط شرا فينخلع قلبه حتى أنال منه ما أردت فقال له الثقفي أقط قال قط قال فهل لك أن تبيعني اسمك\nقال نعم فبم تبتاعه قال بهذه الحلة وبكنيتك قال له أفعل ففعل وقال له تأبط شرا لك اسمي ولي كنيتك وأخذ حلته وأعطاه طمرية ثم انصرف وقال في ذلك يخاطب زوجة الثقفي\n(ألا هل أتى الحسناء أن حليلها ... تأبط شرا واكتنيت أبا وهب)\n(فهبه تسمى اسمي وسميت باسمه ... فأين له صبري على معظم الخطب)\n(وأين له بأس كبأسي وسورتي ... وأين له في كل فادحة قلبي)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":0,"spl":"أخبار تأبط شرا ونسبه — لقبه وسببه — كان أحد العدائين المعدودين — شعره في غول تأبطها","tags":["السفر والحج","الوصف والطبيعة"],"loc":1829},
{"id":"b104-5","bab":"الجزء 10","sec":"أحب جارية وعجز عنها","page":"ج10 ص142","text":"قال حمزة وأحب تأبط شرا جارية من قومه فطلبها زمانا لا يقدر عليها ثم لقيته ذات ليلة فأجابته وأرادها فعجز عنها فلما رأت جزعه من ذلك تناومت عليه فآنسته وهدأ ثم جعل يقول\n(مالك من أير سلبت الخله ... عجزت عن جارية رفله)\n(تمشي إليك مشية خوزله ... كمشية الأرخ تريد العله)\nالأرخ الأنثى من البقر التي لم تنتج العلة تريد أن تعل بعد النهل أي أنها قد رويت فمشيتها ثقيلة والعل الشرب الثاني\n(لو أنها راعية في في ثله ... تحمل قلعين لها قبله)\n(لصرت كالهراوة العتله ... )\nبره مع بجيلة أخبرني الحسن بن علي عن عبد الله بن أبي سعد عن أحمد بن عمر عن أبي بركة الأشعجي قال أغار تأبط شرا وهو ثابت بن العميثل الفهمي ومعه ابن براق الفهمي على بجيلة فأطردا لهم نعما ونذرت بهما بجيلة فخرجت في آثارهما ومضيا هاربين في جبال السراة وركبا الحزن وعارضتهما بجيلة في السهل فسبقوهما إلى الوهط وهو ماء لعمرو بن العاص بالطائف فدخلوا لهما في قصبة العين وجاءا وقد بلغ العطش منهما إلى العين فلما وقفا عليها قال تأبط شرا لابن براق أقل من الشراب فإنها ليلة طرد قال وما يدريك قال\nوالذي أعدو بطيره إني لأسمع وجيب قلوب الرجال تحت قدمي وكان من أسمع العرب وأكيدهم فقال له ابن براق ذلك وجيب قلبك فقال له تأبط شرا والله ما وجب قط ولا كان وجابا وضرب بيده عليه وأصاخ نحو الأرض يستمع فقال والذي أعدو بطيره إني لأسمع وجيب قلوب الرجال فقال له براق فأنا أنزل قبلك فنزل فبرك وشرب وكان أكل القوم عند بجيلة شوكة فتركوه وهم في الظلمة ونزل ثابت فلما توسط الماء وثبوا عليه فأخذوه وأخرجوه من العين مكتوفا وابن براق قريب منهم لا يطمعون فيه لما يعلمون من عدوه فقال لهم ثابت إنه من أصلف الناس وأشدهم عجبا بعدوه وسأقول له أستأسر معي فسيدعوه عجبه بعدوه إلى أن يعدو من بين أيديكم وله ثلاثة أطلاق أولها كالريح الهابة والثاني كالفرس الجواد والثالث يكبو فيه ويعثر فإذا رأيتم منه ذلك فخذوه فإني أحب أن يصير في أيديكم كما صرت إذ خالفني ولم يقبل رأيي ونصحي له قالوا فافعل فصاح به تأبط شرا أنت أخي في الشدة والرخاء وقد وعدني القوم أن يمنوا عليك وعلي فاستأسر وواسني بنفسك في الشدة كما كنت أخي في الرخاء فضحك ابن براق وعلم انه قد كادهم\nوقال مهلا يا ثابت أيستأسر من عنده هذا العدو ثم عدا فعدا أول طلق مثل الريح الهابة كما وصف لهم والثاني كالفرس الجواد والثالث جعل يكبو ويعثر ويقع على وجهه فقال ثابت خذوه فعدوا بأجمعهم فلما أن نفسهم عنه شيئا عدا تأبط شرا في كتافه وعارضه ابن براق فقطع كتافه وأفلتا جميعا فقال تأبط شرا قصيدته القافية في ذلك\n(يا عيد مالك من شوق وإبراق ... ومر طيف على الأهوال طراق)\n(يسري على الأين والحيات محتفيا ... نفسي فداؤك من سار على ساق)\n(طيف ابنة الحر إذ كنا نواصلها ... ثم اجتنبت بها من بعد تفراق)\n(لتقرعن علي السن من ندم ... إذا تذكرت يوما بعض أخلاقي)\n(تالله آمن أنثى بعدما حلفت ... أسماء بالله من عهد وميثاق)\n(ممزوجة الود بينا واصلت صرمت ... الأول اللذ مضى والآخر الباقي)\n(فالأول اللذ مضى قال مودتها ... واللذ منها هذاء غير إحقاق)\n(تعطيك وعد أماني تغر به ... كالقطر مر على صخبان براق)\n(إني إذا حلة ضنت بنائلها ... وأمسكت بضعيف الحبل أحذاق)\n(نجوت منها نجائي من بجيلة إذ ... ألقيت للقوم يوم الروع أرواقي)\nذكرها ابن أبي سعيد في الخبر إلى آخرها وأما المفضل الضبي فذكر أن تأبط شرا وعمرو بن براق والشنفرى وغيره يجعل مكان الشنفرى السليك بن السلكة غزوا بجيلة فلم يظفروا منهم بغرة وثاروا إليهم فأسروا عمرا وكتفوه وأفلتهم الآخران عدوا فلم يقدروا عليهما فلما علما أن ابن براق قد أسر\nقال تأبط شرا لصاحبه امض فكن قريبا من عمرو فإني سأتراءى لهم وأطمعهم في نفسي حتى يتباعدوا عنه فإذا فعلوا ذلك فحل كتافه وانجوا ففعل ما أمره به وأقبل تأبط شرا","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":1,"spl":"أحب جارية وعجز عنها","tags":["الحب والغزل","الجواري والنساء","اللهو والمزاح"],"loc":1830,"partial":1},
{"id":"b104-6","bab":"الجزء 10","sec":"أحب جارية وعجز عنها","page":"ج10 ص142","text":"حتى تراءى لبجيلة فلما رأوه طمعوا فيه فطلبوه وجعل يطمعهم في نفسه ويعدو عدوا خفيفا يقرب فيه ويسألهم تخفيف الفدية وإعطاءه الأمان حتى يستأسر لهم وهم يجيبونه إلى ذلك ويطلبونه وهو يحضر إحضارا خفيفا ولا يتباعد حتى علا تلعة أشرف منها على صاحبيه فإذا هما قد نجوا ففطنت لهما بجيلة فألحقتهما طلبا ففاتاهم فقال يا معشر بجيلة أأعجبكم عدو ابن براق اليوم والله لأعدون لكم عدوا أنسيكم به عدوه ثم عدا عدوا شديدا ومضى وذلك قوله\n(يا عيد مالك من شوق وإبراق ... )\nأما الأصمعي فإنه ذكر فيما أخبرني به ابن أبي الأزهر عن حماد بن إسحاق عن أبيه عن عمه أن بجيلة أمهلتهم حتى وردوا الماء وشربوا وناموا ثم شدوا عليهم فأخذوا تأبط شرا فقال لهم إن ابن براق دلاني في هذا وإنه لا يقدر على العدو لعقر في رجليه فإن تبعتموه أخذتموه فكتفوا تأبط شرا ومضوا في أثر ابن براق فلما بعدوا عنه عدا في كتافه ففاتهم ورجعوا\nأخبرني الحرمي بن أبي العلاء قال حدثنا أبو سعيد السكري قال حدثنا ابن الأثرم وعن أبيه وحدثنا محمد بن حبيب عن أبي عمرو قالا كان تأبط شرا يعدو على رجليه وكان فاتكا شديدا فبات ليلة ذات ظلمة وبرق ورعد في قاع يقال له رحى بطان فلقيته الغول فما زال يقاتلها ليلته إلى أن أصبح وهي تطلبه قال والغول سبع من سباع الجن وجعل يراوغها وهي تطلبه وتلتمس غرة منه فلا تقدر عليه إلى أن أصبح\nفقال تأبط شرا\n(ألا من مبلغ فتيان فهم ... بما لاقيت عند رحى بطان)\n(بأني قد لقيت الغول تهوي ... بسهب كالصحيفة صحصحان)\n(فقلت لها كلانا نضوأين ... أخو سفر فخلي لي مكاني)\n(فشدت شدة نحوي فأهوى ... لها كفي بمصقول يماني)\n(فأضربها بلا دهش فخرت ... صريعا لليدين وللجران)\n(فقالت عد فقلت لها رويدا ... مكانك إنني ثبت الجنان)\n(فلم أنفك متكئا عليها ... لأنظر مصبحا ماذا أتاني)\n(إذا عينان في رأس قبيح ... كرأس الهر مشقوق اللسان)\n(وساقا مخدج وشواة كلب ... وثوب من عباء أو شنان)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":2,"spl":"أحب جارية وعجز عنها","tags":["السفر والحج","الخمر","الرواية والكتابة"],"loc":1831,"partialRef":{"sid":"b104-5","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b104-7","bab":"الجزء 10","sec":"غزا بجيلة فقتل رجلا واستاق غنما","page":"ج10 ص146","text":"قالوا وكان من حديثه انه خرج غازيا يريد بجيلة هو ورجل معه وهو يريد أن يغترهم فيصيب حاجته فأتى ناحية منهم فقتل رجلا ثم استاق غنما كثيرة فنذروا به فتبعه بعضهم على خيل وبعضهم رجالة وهم كثير فلما رآهم وكان من أبصر الناس عرف وجوههم فقال لصاحبه هؤلاء قوم قد عرفتهم ولن يفارقونا اليوم حتى يقاتلونا أو يظفروا بحاجتهم فجعل صاحبه ينظر فيقول ما أتبين أحدا حتى إذ دهموهما\nقال لصاحبه اشتد فإني سأمنعك ما دام في يدي سهم فاشتد الرجل ولقيهم تأبط شرا وجعل يرميهم حتى نفذت نبله ثم إنه اشتد فمر بصاحبه فلم يطق شدة فقتل صاحبه وهو ابن عم لزوجته فلما رجع تأبط شرا وليس صاحبه معه عرفوا أنه قد قتل فقالت له امرأته تركت صاحبك وجئت متباطئا فقال تأبط شرا في ذلك\n(ألا تلكما عرسى منيعة ضمنت ... من الله إثما مستسرا وعالنا)\n(تقول تركت صاحبا لك ضائعا ... وجئت إلينا فارقا متباطنا)\n(إذا ما تركت صاحبي لثلاثة ... أو اثنين مثلينا فلا أبت آمنا)\n(وما كنت أباء على الخل إذ دعا ... ولا المرء يدعوني ممرا مداهنا)\n(وكري إذا أكرهت رهطا وأهله ... وأرضا يكون العوص فيها عجاهنا)\n(ولما سمعت العوص تدعو تنفرت ... عصافير رأسي من غواة فراتنا)\n(ولم أنتظر أن يدهموني كأنهم ... ورائي نحل في الخلية واكنا)\n(ولا أن تصيب النافذات مقاتلي ... ولم أك بالشد الذليق مداينا)\n(فأرسلت مثنيا عن الشد واهنا ... وقلت تزحزح لا تكونن حائنا)\n(وحثحثت مشعوف النجاء كأنه ... هجف رأى قصرا سمالا وداجنا)\n(من الحص هزروف يطير عفاؤه ... إذا استدرج الفيفا ومد المغابنا)\n(أزج زلوج هذر في زفازف ... هزف يبذ الناجيات الصوافنا)\n(فزحزت عنهم أو تجئني منيتي ... بغبراء أو عرفاء تفري الدفائنا)\n(كأني أراها الموت لا در درها ... إذا أمكنت أنيابها والبراثنا)\n(وقالت لأخرى خلفها وبناتها ... حتوف تنقي مخ من كان واهنا)\n(أخاليج وراد على ذي محافل ... إذا نزعوا مدوا الدلا والشواطنا)\nقال غيره بل خرج تأبط شرا هو وصاحبان له حتى أغاروا على العوص من بجيلة فأخذوا نعما لهم واتبعتهم العوص فأدركوهم وقد كانوا استأجروا لهم رجالا كثيرة فلما رأى تأبط شرا ألا طاقة لهم بهم شمر وتركهما فقتل صاحباه وأخذت النعم وأفلت حتى أتى بني القين من فهم فبات عند امرأة منهم يتحدث إليها فلما أراد أن يأتي قومه دهنته ورجلته فجاء إليهم وهم يبكون فقالت له امرأته لعنك الله تركت صاحبيك\nوجئت مدهنا وإنه إنما قال هذه القصيدة في هذا الشأن وقال تأبط شرا يرثيهما وكان اسم أحدهما عمرا\n(أبعد قتيل العوص آسى على فتى ... وصاحبه أو يأمل الزاد طارق)\n(أأطرد فهما آخر الليل أبتغي ... علالة يوم أن تعوق العوائق)\n(لعمر فتى نلتم كأن رداءه ... على سرحة من سرح دومة سامق)\n(لأطرد نهبا أو نرود بفتية ... بأيمانهم سمر القنا والعقائق)\n(مساعرة شعث كأن عيونهم ... حريق الغضا تلفى عليها الشقائق)\n(فعدوا شهور الحرم ثم تعرفوا ... قتيل أناس أو فتاة تعانق)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":3,"spl":"غزا بجيلة فقتل رجلا واستاق غنما","tags":["الجواري والنساء"],"loc":1832},
{"id":"b104-8","bab":"الجزء 10","sec":"محاولة قتله هو وأصحابه بالسم","page":"ج10 ص149","text":"قال الأثرم قال أبو عمرو في هذه الرواية وخرج تأبط شرا يريد أن يغزو هذيلا في رهط فنزل على الأحل بن قنصل رجل من بجيلة وكان بينهما حلف فأنزلهم ورحب بهم ثم إنه ابتغى لهم الذراريح ليسقيهم فيستريح منهم ففطن له تأبط شرا فقام إلى أصحابه فقال إني أحب ألا يعلم أنا قد فطنا له ولكن سابوه حتى نحلف ألا نأكل من طعامه ثم أغتره فأقتله لأنه إن علم حذرني وقد كان مالأ ابن قنصل رجل منهم يقال له لكيز\nقتلت فهم أخاه فاعتل عليه وعلى أصحابه فسبوه وحلفوا ألا يذوقوا من طعامه ولا من شرابه ثم خرج في وجهه وأخذ في بطن واد فيه النمور وهي لا يكاد يسلم منها أحد والعرب تسمي النمر ذا اللونين وبعضهم يسميه البسنتى فنزل في بطنه وقال لأصحابه انطلقوا جميعا فتصيدوا فهذا الوادي كثير الأروى فخرجوا وصادوا وتركوه في بطن الوادي فجاءوا فوجدوه قد قتل نمرا وحده وغزا هديلا فغنم وأصاب فقال تأبط شرا في ذلك\n(أقسمت لا أنسى وإن طال عيشنا ... صنيع لكيز والأحل بن قنصل)\n(نزلنا به يوما فساء صباحنا ... فإنك عمري قد ترى أي منزل)\n(بكى إذ رآنا نازلين ببابه ... وكيف بكاء ذي القليل المعيل)\n(فلا وأبيك ما نزلنا بعامر ... ولا عامر ولا الرئيس ابن قوقل)\nامر بن مالك أبو براء ملاعب الأسنة وعامر بن الطفيل وابن قوقل مالك بن ثعلبة أحد بني عوف بن الخزرج\n(ولا بالشليل رب مروان قاعدا ... بأحسن عيش والنفاثي نوفل)\nب مروان جرير بن عبد الله البجلي ونوفل بن معاوية بن عروة بن صخر بن يعمر أحد بني الديل بن بكر\n(ولا ابن وهيب كاسب الحمد والعلا ... ولا ابن ضبيع وسط آل المخبل)\n(ولا ابن حليس قاعدا في لقاحه ... ولا ابن جري وسط آل المغفل)\n(ولا ابن رياح بالزليفات داره ... رياح بن سعد لا رياح بن معقل)\n(أولئك أعطى للولائد خلفة ... وأدعى إلى شحم السديف المرعبل)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":4,"spl":"محاولة قتله هو وأصحابه بالسم — نجاته من موت محتم","tags":["الخمر"],"loc":1833},
{"id":"b104-9","bab":"الجزء 10","sec":"نجاته من موت محتم","page":"ج10 ص151","text":"وقال أيضا في هذه الرواية كان تأبط شرا يشتار عسلا في غار من بلاد هذيل يأتيه كل عام وأن هذيلا ذكرته فرصدوه لإبان ذلك حتى إذا جاء هو وأصحابه تدلى فدخل الغار وقد أغاروا عليهم فأنفروهم فسبقوهم ووقفوا على الغار فحركوا الحبل فأطلع تأبط شرا رأسه فقالوا اصعد فقال ألا أراكم قالوا بلى قد رأيتنا فقال فعلام أصعد أعلى الطلاقة أم الفداء قالوا لا شرط لك\nقال فأراكم قاتلي وآكلي جناي لا والله لا أفعل قال وكان قبل ذلك نقب في الغار نقبا أعده للهرب فجعل يسيل العسل من الغار ويهريقه ثم عمد إلى الزق فشده على صدره ثم لصق بالعسل فلم يبرح ينزلق عليه حتى خرج سليما وفاتهم وبين موضعه الذي وقع فيه وبين القوم مسيرة ثلاث فقال تأبط شرا في ذلك\n(أقول للحيان وقد صفرت لهم ... وطابي ويومي ضيق الحجر معور)\n(هما خطتا إما إسار ومنة ... وإما دم والقتل بالحر أجدر)\n(وأخرى أصادي النفس عنها وإنها ... لمورد حزم إن ظفرت ومصدر)\n(فرشت لها صدري فزل عن الصفا ... به جؤجؤ صلب ومتن مخصر)\n(فخالط سهل الأرض لم يكدح الصفا ... به كدحة والموت خزيان ينظر)\n(فأبت إلى فهم وما كنت آئبا ... وكم مثلها فارقتها وهي تصفر)\n(إذا المرء لم يحتل وقد جد جده ... أضاع وقاسى أمره وهو مدبر)\n(ولكن أخو الحزم الذي ليس نازلا ... به الأمر إلا وهو للحزم مبصر)\n(فذاك قريع الدهر ما كان حولا ... إذا سد منه منخر جاش منخر)\n(فإنك لو قايست باللصب حيلتي ... بلقمان لم يقصر بي الدهر مقصر)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":4,"spl":"محاولة قتله هو وأصحابه بالسم — نجاته من موت محتم","tags":["الحب والغزل","السفر والحج"],"loc":1834},
{"id":"b104-10","bab":"الجزء 10","sec":"قتل هو وأصحابه نفرا من العوص","page":"ج10 ص152","text":"وقال أيضا في حديث تأبط شرا إنه خرج في عدة عن فهم فيهم عامر ابن الأخنس والشنفرى والمسيب وعمرو بن براق ومرة بن خليف حتى بيتوا العوص وهم حي من بجيلة فقتلوا منهم نفرا وأخذوا لهم إبلا فساقوها حتى كانوا من بلادهم على يوم وليلة فاعترضت لهم خثعم وفيهم ابن حاجز وهو رئيس القوم وهم يومئذ نحو من أربعين رجلا فلما نظرت إليهم صعاليك فهم قالوا لعامر بن الأخنس ماذا ترى\nقال لا أرى لكم إلا صدق الضراب فإن ظفرتم فذاك وإن قتلتم كنتم قد أخذتم ثأركم قال تأبط شرا بأبي أنت وأمي فنعم رئيس القوم أنت إذا جد الجد وإذا كان قد أجمع رأيكم على هذا فإني أرى لكم أن تحملوا على القوم حملة واحدة فإنكم قليل والقوم كثير ومتى افترقتم كثركم القوم فحملوا عليهم فقتلوا منهم في حملتهم فحملوا ثانية فانهزمت خثعم وتفرقت وأقبل ابن حاجز فأسند في الجبل فأعجز فقال تأبط شرا في ذلك\n(جزى الله فتيانا على العوص أمطرت ... سماؤهم تحت العجاجة بالدم)\n(وقد لاح ضوء الفجر عرضا كأنه ... بلمحته إقراب أبلق أدهم)\n(فإن شفاء الداء إدراك ذحلة ... صباحا على آثار حوم عرمرم)\n(وضاربتهم بالسفح إذ عارضتهم ... قبائل من أبناء قسر وخثعم)\n(ضرابا عدا منه ابن حاجز هاربا ... ذرا الصخر في جوف الوجين المديم)\nقال الشنفرى في ذلك\n(دعيني وقولي بعد ما شئت إنني ... سيغدى بنعشي مرة فأغيب)\n(خرجنا فلم نعهد وقلت وصاتنا ... ثمانية ما بعدها متعتب)\n(سراحين فتيان كأن وجوههم ... مصابيح أو لون من الماء مذهب)\n(نمر برهو الماء صفحا وقد طوت ... ثمائلنا والزاد ظن مغيب)\n(ثلاثا على الأقدام حتى سما بنا ... على العوص شعشاع من القوم محرب)\n(فثاروا إلينا في السواد فهجهجوا ... وصوت فينا بالصباح المثوب)\n(فشن عليهم هذة السيف ثابت ... وصمم فيهم بالحسام المسيب)\n(وظلت بفتيان معي أتقيهم ... بهن قليلا ساعة ثم جنبوا)\n(وقد خر منهم راجلان وفارس ... كمي صرعناه وحوم مسلب)\n(يشق إليه كل ربع وقلعة ... ثمانية والقوم رجل ومقنب)\n(فلما رآنا قومنا قيل أفلحوا ... فقلنا : اسألوا عن قائل لا يكذب)\nقال تأبط شرا في ذلك\n(أرى قدمي وقعهما خفيف ... كتحليل الظليم حدا رئاله)\n(أرى بهما عذابا كل يوم ... بخثعم أو بجيلة أو ثماله)\nفرق تأبط شرا أصحابه ولم يزالوا يقاتلونهم حتى انهزمت خثعم وساق تأبط شرا وأصحابه الإبل حتى قدم بها عليا مكة وقال غيره إنما سمي تأبط شرا ببيت قاله وهو\n(تأبط شرا ثم راح أو اغتدى ... يوائم غنما أو يشيف على ذحل)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":5,"spl":"قتل هو وأصحابه نفرا من العوص — شعره عندما هرب من مراد إلى قومه","tags":["السفر والحج"],"loc":1835},
{"id":"b104-11","bab":"الجزء 10","sec":"شعره عندما هرب من مراد إلى قومه","page":"ج10 ص154","text":"قال وخرج تأبط شرا يوما يريد الغارة فلقى سرحا لمراد فأطرده ونذرت به مراد فخرجوا في طلبه فسبقهم إلى قومه وقال في ذلك\n(إذا لاقيت يوم الصدق فاربع ... عليه ولا يهمك يوم سو)\n(على أني بسرح بني مراد ... شجوتهم سباقا أي شجو)\n(وآخر مثله لا عيب فيه ... بصرت به ليوم غير زو)\n(خفضت بساحة تجري علينا ... أباريق الكرامة يوم لهو)\nأغار تأبط شرا وحده على خثعم فبينا هو يطوف إذ مر بغلام يتصيد الأرانب معه قوسه ونبله فلما رآه تأبط شرا أهوى ليأخذه فرماه الغلام فأصاب يده اليسرى وضربه تأبط شرا فقتله وقال في ذلك\n(وكادت وبيت الله أطناب ثابت ... تقوض عن ليلى وتبكي النوائح)\n(تمنى فتى منا يلاقي ولم يكد ... غلام نمته المحصنات الصرائح)\n(غلام نمى فوق الخماسي قدره ... ودون الذي قد ترتجيه النواكح)\n(فإن تك نالته خطاطيف كفه ... بأبيض قصال نمى وهو فادح)\n(فقد شد في إحدى يديه كنانه ... يداوى لها في أسود القلب قادح)\nذه الأبيات أن تكون لقوم المقتول أشبه منها بتأبط شرا","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":5,"spl":"قتل هو وأصحابه نفرا من العوص — شعره عندما هرب من مراد إلى قومه","tags":["الحب والغزل"],"loc":1836},
{"id":"b104-12","bab":"الجزء 10","sec":"خبره مع امرأة من هذيل","page":"ج10 ص155","text":"قال وخطب تأبط شرا امرأة من هذيل من بني سهم فقال لها قائل لا تنكحيه فإنه لأول غدا يفقد فقال تأبط شرا\n(وقالوا لها لا تنكحيه فإنه ... لأول نصل أن يلاقى مجمعا)\n(فلم تر من رأي فتيلا وحاذرت ... تأيمها من لابس الليل أروعا)\n(قليل غرار النوم أكبر همه ... دم الثأر أو يلقى كميا مقنعا)\n(قليل ادخار الزاد إلا تعلة ... وقد نشز الشرسوف والتصق المعى)\n(تناضله كل يشجع نفسه ... وما طبه في طرقه أن يشجعا)\n(يبيت بمغنى الوحش حتى ألفنه ... ويصبح لا يحمي لها الدهر مرتعا)\n(رأين فتى لا صيد وحش يهمه ... فلو صافحت إنسا لصافحنه معا)\n(ولكن أرباب المخاض يشقهم ... إذا افتقدوه أو رأوه مشيعا)\n(وإني ولا علم لأعلم أنني ... سألقى سنان الموت يرشق أضلعا)\n(على غرة أو جهرة من مكاثر ... أطال نزال الموت حتى تسعسعا)\nسعسع فني وذهب يقال قد تسعسع الشهر ومنه حديث عمر رضي الله عنه حين ذكر شهر رمضان فقال ( إن هذا الشهر قد تسعسع وكنت أظن الموت في الحي أو أرى ... ألذ وأكرى أو أموت مقنعا ولست أبيت الدهر إلا على فتى ... أسلبه أو أذغر السرب أجمعا ومن يضرب الأبطال لا بد أنه ... سيلقى بهم من مصرع الموت مصرعا\nال وخرج تأبط شرا ومعه صاحبان له عمرو بن كلاب أخو المسيب\nوسعد بن الأشرس وهم يريدون الغارة على بجيلة فنذروا بهم وهم في جبل ليس لهم طريق عليهم فأحاطوا بهم وأخذوا عليهم الطريق فقاتلوهم فقتل صاحبا تأبط شرا ونجا ولم يكد حتى أتى قومه فقالت له امرأته وهي أخت عمرو بن كلاب إحدى نساء كعب بن علي بن إبراهيم بن رياح هربت عن أخي وتركته وغررته أما والله لو كنت كريما لما أسلمته فقال تأبط شرا في ذلك\n(ألا تلكما عرسي منيعة ضمنت ... من الله خزيا مستسرا وعاهنا)\nذكر باقي الأبيات وإنما دعا امرأته إلى أن عيرته أنه لما رجع بعد مقتل صاحبيه انطلق إلى امرأة كان يتحدث عندها وهي من بني القين بن فهم فبات عندها فلما أصبح غدا إلى امرأته وهو مدهن مترجل فلما رأته في تلك الحال علمت أين بات فغارت عليه فعيرته","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":6,"spl":"خبره مع امرأة من هذيل — غارته على خثعم","tags":[],"loc":1837},
{"id":"b104-13","bab":"الجزء 10","sec":"غارته على خثعم","page":"ج10 ص157","text":"وذكروا أن تأبط شرا أغار على خثعم فقال كاهن لهم أروني أثره حتى آخذه لكم فلا يبرح حتى تأخذوه فكفئوا على أثره جفنة ثم أرسلوا إلى الكاهن فلما رأى أثره قال هذا ما لا يجوز في صاحبه الأخذ فقال تأبط شرا\n(ألا أبلغ بني فهم بن عمرو ... على طول التنائي والمقاله)\n(مقال الكاهن الجامي لما ... رأى أثري وقد أنهبت ماله)\n(رأى قدمي وقعهما حثيث ... كتحليل الظليم دعا رئاله)\n(أرى بهما عذابا كل عام ... لخثعم أو بجيلة أو ثماله)\n(وشر كان صب على هذيل ... إذا علقت حبالهم حباله)\n(ويوم الأزد منهم شر يوم ... إذا بعدوا فقد صدقت قاله)\nفزعموا أن ناسا من الأزد بئوا لتأبط شرا ربيئة وقالوا هذا مضيق ليس له سبيل إليكم من غيره فأقيموا فيه حتى يأتيكم فلما دنا من القوم توجس ثم انصرف ثم عاد فنهضوا في أثره حين رأوه لا يجوز ومر قريبا فطمعوا فيه وفيهم رجل يقال له حاجز ليث من ليوثهم سريع فأغروه به فلم يلحقه فقال تأبط شرا في ذلك\n(تتعتعت حضني حاجز وصحابه ... وقد نبذوا خلقانهم وتشنعوا)\n(أظن وإن صادفت وعثا وأن جرى ... بي السهل أو متن من الأرض مهيع)\n(أجاري ظلال الطير لو فات واحد ... ولو صدقوا قالوا له هو أسرع)\n(فلو كان من فتيان قيس وخندف ... أطاف به القناص من حيث أفزعوا)\n(وجاب بلادا نصف يوم وليلة ... لآب إليهم وهو أشوس أروع)\n(فلو كان منكم واحد لكفيته ... وما ارتجعوا لو كان في القوم مطمع)\nأجابه حاجز\n(فإن تك جاريت الظلال فربما ... سبقت ويوم القرن عريان أسنع)\n(وخليت إخوان الصفاء كأنهم ... ذبائح عنز أو فحيل مصرع)\n(تبكيهم شجو الحمامة بعدما ... أرحت ولم ترفع لهم منك إصبع)\n(فهذي ثلاث قد حويت نجاتها ... وإن تنج أخرى فهي عندك أربع)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":6,"spl":"خبره مع امرأة من هذيل — غارته على خثعم","tags":["الحب والغزل"],"loc":1838},
{"id":"b104-14","bab":"الجزء 10","sec":"خير أيامه","page":"ج10 ص159","text":"أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال ذكر علي بن محمد المدائني عن ابن دأب قال سئل تأبط شرا أي يوم مر بك خير قال خرجت حتى كنت في بلاد بجيلة أضاءت لي النار رجلا جالسا إلى امرأة فعمدت إلى سيفي فدفنته قريبا ثم أقبلت حتى استأنست فنبحني الكلب فقال ما هذا فقلت بائس فقال ادنه فدنوت فإذا رجل جلحاب آدم وإذا أضوى الناس إلى جانبه فشكوت إليه الجوع والحاجة فقال اكشف تلك القصعة فأتيت قصعة إلى جنب إبله فإذا فيها تمر ولبن فأكلت منه حتى شبعت ثم خررت متناوما فو الله ما شئت أن أضطجع حتى أضطجع هو ورفع رجله على رجله ثم اندفع يغني وهو يقول\n(خير الليالي إن سألت بليلة ... ليل بخيمة بين بيش وعثر)\n(لضجيع آنسة كأن حديثها ... شهد يشاب بمزجة من عنبر)\n(وضجيع لاهية ألاعب مثلها ... بيضاء واضحة كظيظ المئزر)\n(ولأنت مثلهما وخير منهما ... بعد الرقاد وقبل أن لم تسحري)\nال ثم انحرف فنام ومالت فنامت فقلت ما رأيت كالليلة في الغرة فإذا عشر عشراوات بين أثلاث فيها عبد واحد وأمه فوثبت فانتضيت سيفي وانتحيت للعبد فقتلته وهو نائم ثم انحرفت إلى الرجل فوضعت سيفي على كبده حتى أخرجته من صلبه ثم ضربت فخذ المرأة فجلست فلما رأته مقتولا جزعت فقلت لا تخافي أنا خير لك منه\nقال وقمت إلى جل متاعها فرحلته على بعض الإبل أنا والأمة فما حللت عقده حتى نزلت بصعدة بني عوف بن فهر وأعرست بالمرأة هناك وحين اضطجعت فتحت عقيرتي وغنيت\n(بحليلة البجلي بت من ليلها ... بين الإزار وكشحها ثم الصق)\n(بأنسية طويت على مطويها ... طي الحمالة أو كطي المنطق)\n(فإذا تقوم فصعدة في رملة ... لبدت بريق ديمة لم تغدق)\n(وإذا تجيء تجيء شحب خلفها ... كالأيم أصعد في كثيب يرتقي)\n(كذب الكواهن والسواحر والهنا ... أن لا وفاء لعاجز لا يتقي)\nال فهذا خير يوم لقيته وشر يوم لقيت أني خرجت حتى إذا كنت في بلاد ثمالة أطوف حتى إذا كنت من الفقير عشيا إذا بسبع خلفات فيهن عبد فأقبلت نحوه وكأني لا أريده وحذرني فجعل يلوذ بناقة فيها حمراء فقلت في نفسي والله إنه ليثق بها فأفوق له ووضع رجله في أرجلها وجعل يدور معها فإذا هو على عجزها وأرميه حين أشرف فوضعت سهمي في قلبه فخر وندت الناقة شيئا وأتبعتها فرجعت فسقتهن شيئا ثم\nقلت والله لو ركبت الناقة وطردتهن وأخذت بعثنون الحمراء فوثبت فساعة استويت عليها كرت نحو الحي تريع وتبعتها الخلفات وجلعت أسكنها وذهبت فلما خشيت أن تطرحني في أيدي القوم رميت بنفسي عنها فانكسرت رجلي وانطلقت والذود معها فخرجت أعرج حتى انخنست في طرف كثيب وجازني الطلب فمكثت مكاني حتى أظلمت وشبت لي ثلاثة أنوار فإذا نار عظيمة ظننت أن لها أهلا كثيرا ونار دونها ونويرة صغيره فهويت للصغرى وأنا أجمر فلما نبحني الكلب نادى رجل فقال من هذا فقلت بائس فقال ادنه فدنوت وجلست وجعل يسائلني إلى أن قال والله إني لأجد منك ريح دم فقلت لا والله ما بي دم فوثب إلي فنفضني ثم نظر في جعبتي فإذا\nالسهم فقلت رميت العشية أرنبا فقال كذبت هذا ريح دم إنسان ثم وثب إلي ولا أدفع الشر عن نفسي فأوثقني كتافا ثم علق جعبتي وقوسي وطرحني في كسر البيت ونام فلما أسحرت حركت رجلي فإذا هي صالحة وانفتل الرباط فحللته ثم وثبت إلى قوسي وجعبتي فأخذتهما ثم هممت بقتله فقلت أنا ضمن الرجل وأنا أخشى أن أطلب فأدرك ولم أقتل أحدا أحب إلي فوليت ومضيت فو الله إني لفي الصحراء أحدث نفسي إذا أنا به على ناقة يتبعني فلما رأيته قد دنا مني جلست على قوسي وجعبتي وأمنته وأقبل فأناخ راحلته ثم علقها ثم أقبل إلي وعهده بي عهده فقلت له ويلك ما تريد مني فأقبل يشتمني حتى إذا أمكنني وثبت عليه فما ألبثته أن ضربت به الأرض وبركت عليه أربطه فجعل يصيح يا لثمالة لم أر كاليوم فجنبته إلى ناقته وركبتها فما نزعت حتى أحللته في الحي وقلت\n(أغرك مني يا بن فعلة علتي ... عشية أن رابت علي روائبي)\n(و موقد نيران ثلاث فشرها ... وألأمها إذ قدتها غير عازب)\n(سلبت سلاحي بائسا وشتمتني ... فيا خير مسلوب ويا شر سالب)\n(فإن أك لم أخضبك فيها فإنها ... نيوب أساويد وشول عقارب)\n(ويا ركبة الحمراء شرة ركبة ... وكادت تكون شر ركبة راكب)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":7,"spl":"خير أيامه","tags":["الجواري والنساء","اللهو والمزاح"],"loc":1839},
{"id":"b104-15","bab":"الجزء 10","sec":"غارته على الأزد","page":"ج10 ص163","text":"قال وخرج تأبط غازيا يريد الغارة على الأزد في بعض ما كان يغير عليهم وحده فنذرت به الأزد فأهملوا له إبلا وأمروا ثلاثة من ذوي بأسهم حاجزين أبي وسواد بن عمرو بن مالك وعوف بن عبد الله أن يتبعوه حتى ينام فيأخذوه أخذا فكمنوا له مكمنا وأقبل تأبط شرا فبصر بالإبل فطردها بعض يومه ثم تركها ونهض في شعب لينظر هل يطلبه أحد فكمن القوم حين رأوه ولم يرهم فلما لم ير أحدا في أثره عاود الإبل فشلها يومه وليلته والغد حتى أمسى ثم عقلها وصنع طعاما فأكله والقوم ينظرون إليه في ظله ثم هيأ مضطجعا على النار ثم أخمدها وزحف على بطنه ومعه قوسه حتى دخل بين الإبل وخشي أن يكون رآه أحد وهو لا يعلم ويأبى إلا الحذر والأخذ بالحزم فمكث ساعة وقد هيأ سهما على كبد قوسه فلما أحسوا نومه أقبلوا ثلاثتهم يؤمون المهاد الذي رأوه هيأه فإذا هو يرمي أحدهم فيقتله وجال الآخران ورمى آخر فقتله وأفلت حاجز هاربا وأخذ سلب الرجلين وأطلق عقل الإبل وشلها حتى جاء بها قومه وقال تأبط في ذلك\n(ترجى نساء الأزد طلعة ثابت ... أسيرا ولم يدرين كيف حويلي)\n(فإن الألي أوصيتم بين هارب ... طريد ومسفوح الدماء قتيل)\n(وخدت بهم حتى إذا طال وخدهم ... وراب عليهم مضجعي ومقيلي)\n(مهدت لهم حتى إذا طاب روعهم ... إلى المهد خاتلت الضيا بختيل)\n(فلما أحسوا النوم جاءوا كأنهم ... سباع أصابت هجمة بسليل)\n(فقلدت سوار بن عمرو بن مالك ... بأسمر جسر القذتين طميل)\n(فخر كأن الفيل ألقى جرانه ... عليه بريان القواء أسيل)\n(وظل رعاع المتن من وقع حاجز ... يخر ولو نهنهت غير قليل)\n(لأبت كما آبا ولو كنت قارنا ... لجئت وما مالكت طول ذميلي)\n(فسرك ندماناك لما تتابعا ... وأنك لم ترجع بعوص قتيل)\n(ستأتي إلى فهم غنيمة خلسة ... وفي الأزد نوح ويلة بعويل)\nفقال حاجز بن أبي الأزدي يجيبه\n(سألت فلم تكلمني الرسوم ... )\nهي في أشعار الأزد فأجابه تأبط شرا\n(لقد قال الخلي وقال خلسا ... بظهر الليل شد به العكوم)\n(لطيف من سعاد عناك منها ... مراعاة النجوم ومن يهيم)\n(وتلك لئن عنيت بها رداح ... من النسوان منطقها رخيم)\n(نياق القرط غراء الثنايا ... وريداء الشباب ونعم خيم)\n(ولكن فات صاحب بطن رهو ... وصاحبه فأنت به زعيم)\n(أؤاخذ خطة فيها سواء ... أبيت وليل واترها نؤوم)\n(ثأرت بها وما اقترفت يداه ... فظل لها بنا يوم غشوم)\n(نحز رقابهم حتى نزعنا ... وأنف الموت منخره رميم)\n(وإن تقع النسور علي يوما ... فلحم المعنفي لحم كريم)\n(وذي رحم أحال الدهر عنه ... فليس له لذي رحم حريم)\n(أصاب الدهر آمن مروتيه ... فألقاه المصاحب والحميم)\n(مددت له يمينا من جناحي ... لها وفر وكافية رحوم)\n(أواسيه على الأيام إني ... إذا قعدت به اللؤما ألوم)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":8,"spl":"غارته على الأزد","tags":["الوصف والطبيعة","الموت"],"loc":1840,"partial":1},
{"id":"b104-16","bab":"الجزء 10","sec":"رثاؤه لأخيه عمرو","page":"ج10 ص165","text":"ذكروا انه لما انصرف الناس عن المستغل وهي سوق كانت العرب\nتجتمع بها قال عمرو بن جابر بن أخو سفيان تأبط شرا لمن حضر من قومه لا واللات والعزى لا أرجع حتى أغير على بني عتير من هذيل ومعه رجلان من قومه هو ثالثهما فأطردوا إبلا لبني عتير فأتبعهم أرباب الإبل فقال عمرو أنا كار على القوم ومنهنهم عنكما فامضيا بالإبل فكر عليهم فنهنهم طويلا فجرح في القوم رئيسا ورماه رجل من بني عتير بسهم فقتله فقالت بنو عتير هذا عمرو بن جابر ما تصنعون أن تلحقوا بأصحابه أبعدها الله من إبل فإنا نخشى أن نلحقهم فيقتل القوم منا فيكونوا قد أخذوا الثأر فرجعوا ولم يجاوزوه وكانوا يظنون أن معه أناسا كثيرا فقال تأبط لما بلغه قتل أخيه\n(وحرمت النساء وإن أحلت ... بشور أو بمزج أو لصاب)\n(حياتي أو أزور بني عتير ... وكاهلها بجمع ذي ضباب)\n(إذا وقعت لكعب أو خثيم ... وسيار يسوغ لها شرابي)\n(أظني ميتا كمدا ولما ... أطالع طلعة أهل الكراب)\n(ودمت مسيرا أهدي رعيلا ... أؤم سواد طود ذي نقاب)\nأجابه أنس بن حذيفة الهذلي\n(لعلك أن تجيء بك المنايا ... تساق لفتية منا غضاب)\n(فتنزل في مكرهم صريعا ... وتنزل طرقة الضبع السغاب)\n(تأبط سوأة وحملت شرا ... لعلك أن تكون من المصاب)\nم أن السمع بن جابر أخا تابط شرا خرج في صعاليك من قومه يريد الغارة على بني عتير ليثأر بأخيه عمرو بن جابر حتى إذا كان ببلاد هذيل لقي راعيا لهم فسأله عنهم فأخبره بأهل بيت من عتير كثير مالهم فبيتهم فلم يفلت منهم مخبر واستاقوا أموالهم فقال في ذلك السمع بن جابر\n(بأعلى ذي جماجم أهل دار ... إذا ظعنت عشيرتهم أقاموا)\n(طرقتهم بفتيان كرام ... مساعير إذا حمي المقام)\n(متى ما أدع من فهم تجبني ... وعدوان الحماة لهم نظام)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":9,"spl":"رثاؤه لأخيه عمرو","tags":["الخمر"],"loc":1841},
{"id":"b104-17","bab":"الجزء 10","sec":"أصابته في غارته غلى الأزد","page":"ج10 ص167","text":"ذكروا أن تأبط شرا خرج ومعه مرة بن خليف يريدان الغارة على الأزد وقد جعلا الهداية بينهما فلما كانت هداية مرة نعس فجار عن الطريق ومضيا حتى وقعا بين جبال ليس فيها جبل متقارب وإذا فيها مياه يصيح الطير عليها وإذا البيض والفراخ بظهور الأكم فقال تأبط شرا هلكنا واللات يا مرة ما وطيء هذا المكان إنس قبلنا ولو وطئته إنس ما باضت الطير بالأرض فاختر أية هاتين القنتين شئت وهما أطول شيء يريان من الجبال فأصعد إحداهما وتصعد أنت الأخرى فإن رأيت الحياة فألح بالثوب وإن رأيت الموت فألح بالسيف فإني فاعل مثل ذلك فأقاما يومين ثم إن تأبط شرا ألاح بالثوب وانحدرا حتى التقيا في سفح الجبل فقال مرة ما رأيت يا ثابت قال دخانا أو جرادا قال مرة\nإنك إن جزعت منه هلكنا فقال تأبط شرا أما أنا فإني سأخرم بك من حيث تهتدي الريح فمكثا بذلك يومين وليلتين ثم تبعا الصوت فقال تأبط شرا النعم والناس أما والله لئن عرفنا لنقتلن ولئن أغرنا لندركن فأت الحي من طرف وأنا من الآخر ثم كن ضيفا ثلاثا فإن لم يرجع إليك قلبك فلا رجع ثم أغر على ما قبلك إذا تدلت الشمس فكانت قدر قامة وموعدك الطريق ففعلا حتى إذا كان اليوم الثالث أغار كل واحد منهما على ما يليه فاستاقا النعم والغنم وطردا يوما وليلة طردا عنيفا حتى أمسيا الليلة الثانية دخلا شعبا فنحرا قلوصا فبينا هما يشويان إذ سمعا حسا على باب الشعب فقال تأبط الطلب يا مرة إن ثبت فلم يدخل فهم مجيزون وإن دخل فهو الطلب فلم يلبث أن سمع الحس يدخل فقال مرة هلكنا ووضع تأبط شرا يده على عضد مرة فإذا هي ترعد فقال ما أرعدت عضدك إلا من قبل أمك الوابشية من هذيل خذ بظهري فإن نجوت نجوت وإن قتلت وقيتك فلما دنا القوم أخذ مرة بظهر تأبط وحمل تأبط فقتل رجلا ورموه بسهم فأعلقوه فيه وأفلتا جميعا بأنفسهما فلما أمنا وكان من آخر الليل\nقال مرة ما رأيت كاليوم عنيمة أخذت على حين أشرافنا على أهلنا وعض مرة عضده وكان الحي الذين أغاروا عليهم بجيلة وأتى تأبط امرأته فلما رأت جراحته ولولت فقال تأبط في ذلك\n(وبالشعب إذ سدت بجيلة فجه ... ومن خلفه هضب صغار وجامل)\n(شددت لنفس المرء مرة حزمه ... وقد نصبت دون النجاء الحبائل)\n(وقلت له كن خلف ظهري فإنني ... سأفديك وانظر بعد ما أنت فاعل)\n(فعاذ بحد السيف صاحب أمرهم ... وخلوا عن الشيء الذي لم يحاولوا)\n(وأخطأهم قتلى ورفعت صاحبي ... على الليل لم تؤخذ عليه المخاتل)\n(واخطأ غنم الحي مرة بعدما ... حوته إليه كفه والأنامل)\n(يعض على أطرافه كيف زوله ... ودون الملا سهل من الأرض ماثل)\n(فقلت له هذي بتلك وقد يرى ... لها ثمنا من نفسه ما يزاول)\n(تولول سعدى أن أتيت مجرحا ... إليها وقد منت علي المقاتل)\n(وكائن أتاها هاربا قبل هذه ... ومن غانم فأين منك الولاول)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":10,"spl":"أصابته في غارته غلى الأزد","tags":["الحب والغزل","الوصف والطبيعة"],"loc":1842},
{"id":"b104-18","bab":"الجزء 10","sec":"أراد هو وأصحابه الأخذ بثأر صاحبيهم","page":"ج10 ص169","text":"فلما انقضت الأشهر الحرم وخرج تأبط والمسيب بن كلاب في ستة نفر يريدون الغارة على بجيلة والأخذ بثأر صاحبيهم عمرو بن كلاب وسعد بن الأشرس فخرج تأبط والمسيب بن كلاب وعامر بن الأخنس وعمرو بن براق ومرة ابن خليف والشنفرى بن مالك والسمع وكعب بن حدار ابنا جابر أخوا تأبط فمضوا حتى أغاروا على العوص فقتلوا منهم ثلاثة نفر فارسين وراجلا وأطردوا لهم إبلا وأخذوا منهم امرأتين فمضوا بما غنموا حتى إذا كانوا على يوم وليلة من قومهم عرضت لهم خثعم في نحو من أربعين رجلا فيهم أبي بن جابر الخثعمي وهو رئيس القوم فقال تأبط يا قوم لا تسلموا لهم ما في أيديكم حتى تبلوا عذرا وقال عامر بن الأخنس عليكم بصدق الضراب وقد أدركتم بثأركم وقال\nالمسيب اصدقوا القوم الحملة وإياكم والفشل وقال عمرو بن براق ابذلوا مهجكم ساعة فإن النصر عند الصبر وقال الشنفرى\n(نحن الصعاليك الحماة البزل ... إذا لقينا لا نرى نهلل)\nقال مرة بن خليف\n(يا ثابت الخير ويا بن الأخنس ... ويا بن براق الكريم الأشوس)\n(والشنفرى عند حيود الأنفس ... أنا ابن حامي السرب في المغمس)\n(نحن مساعير الحروب الضرس ... )\nقال كعب حدار أخو تأبط\n(يا قوم أما إذ لقيتم فاصبروا ... ولا تخيموا جزعا فتدبروا)\nقال السمع أخو تأبط\n(يا قوم كونوا عندها أحرارا ... لا تسلموا العون ولا البكارا)\n(ولا القناعيس ولا العشارا ... لخثعم وقد دعوا غرارا)\n(ساقوهم الموت معا أحرارا ... وافتخروا الدهر بها افتخارا)\nفلما سمع تأبط مقالتهم قال بأبي أنتم وأمي نعم الحماة إذا جد الجد أما إذا أجمع رأيكم على قتال القوم فاحملوا ولا تتفرقوا فإن القوم أكثر منكم فحملوا عليهم فقتلوا منهم ثم كروا الثانية فقتلوا ثم كروا الثالثة فقتلوا فانهزمت خثعم وتفرقت في رؤوس الجبال ومضى تأبط وأصحابه بما غنموا وأسلاب من قتلوا فقال تأبط في ذلك\n(جزى الله على فتيانا على العوص أشرقت ... سيوفهم تحت العجاجة بالدم)\nلأبيات وقال الشنفرى في ذلك\n(دعيني وقولي بعد ما شئت إنني ... سيفدى بنفسي مرة فأغيب)\nلأبيات وقال الشنفرى أيضا\n(ألا هل أتى عنا سعاد ودونها ... مهامه بيد تعتلي بالصعالك)\n(بأنا صبحنا القوم في حر دارهم ... حمام المنايا بالسيوف البواتك)\n(قتلنا بعمرو منهم خير فارس ... يزيد وسعدا وابن عوف بمالك)\n(ظللنا نفري بالسيوف رؤوسهم ... ونرشقهم بالنبل بين الدكادك)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":11,"spl":"أراد هو وأصحابه الأخذ بثأر صاحبيهم","tags":[],"loc":1843,"partial":1},
{"id":"b104-19","bab":"الجزء 10","sec":"كان ضعيفا أمام النساء","page":"ج10 ص171","text":"قال وخرج تأبط في سرية من قومه فيهم عمرو بن براق ومرة بن خليف والمسيب بن كلاب وعامر بن الأخنس وهو رأس القوم وكعب\nحدار وريش كعب والسمع وشريس بنو جابر إخوة تأبط شرا وسعد ومالك ابنا الأقرع حتى مروا ببني نفاثة بن الديل وهم يريدون الغارة عليهم فباتوا في جبل مطل عليهم فلما كان في وجه السحر أخذ عامر بن الأخنس قوسه فوجد وترها مسترخيا فجعل يوترها ويقول له تأبط بعض حطيط وترك يا عامر وسمعه شيخ من بني نفاثة فقال لبنات له أنصتن فهذه والله غارة لبني ليث وكان الذي بينهم يومئذ متفاقما في قتل حميصة بن قيس أخي بلعاء وكانوا أصابوه خطأ وكانت بنو نفاثة في غزوة والحي خلوف وليس عندهم غير أشياخ وغلمان لا طباخ بهم فقالت امرأة منهم اجهروا الكلام والبسوا السلاح فإن لنا عدة فو اللات ما هم إلا تأبط وأصحابه فبرزن مع نوفل وأصحابه فلما بصر بهم\nقال انصرفوا فإن القوم قد نذروا بكم فأبوا عليه إلا الغارة فسل تأبط سيفه وقال لئن أغرتم عليهم لأتكئن على سيفي حتى أنفذه من ظهري فانصرفوا ولا يحسبون إلا أن النساء رجال حتى مروا بإبل البلعاء بن قيس بقرب المنازل فأطردوها فلحقهم غلام من بني جندع بن ليث فقال يا عامر بن الأخنس أتهاب نساء بني نفاثة وتغير على رجال بني ليث هذه والله إبل لبلعاء بن قيس فقال له عامر أو كان رجالهم خلوفا\nقال نعم قال أقرئ بلعاء مني السلام وأخبره بردي إبله وأعلمه أني قد حبست منها بكرا لأصحابي فإنا قد أرملنا فقال الغلام لئن حبست منها هلبة لأعلمنه ولا أطرد منها بعيرا أبدا فحمل عليه تأبط فقتله ومضوا بالإبل إلى قومهم فقال في ذلك تأبط\n(ألا عجب الفتيان من أم مالك ... تقول أراك اليوم أشعث أغبرا)\n(تبوعا لآثار السرية بعد ما ... رأيتك براق المفارق أيسرا)\n(فقلت له يومان يوم إقامة ... أهز به غصنا من البان أخضرا)\n(ويوم أهز السيف في جيد أغيد ... له نسوة لم تلق مثلي أنكرا)\n(يخفن عليه وهو ينزع نفسه ... لقد كنت أباء الظلامة قسورا)\n(وقد صحت في آثار حوم كأنها ... عذارى عقيل أو بكارة حميرا)\n(أبعد النفاثيين آمل طرقة ... وآسى على شيء إذا هو أدبرا)\n(أكفكف عنهم صحبتي وإخالهم ... من الذل يعرا بالتلاعة أعفرا)\n(فلو نالت الكفان أصحاب نوفل ... بمهمهة من بطن ظرء فعرعرا)\n(ولما أبى الليثي إلا تهكما ... بعرضي وكان العرض عرضي أوفرا)\n(فقلت له حق الثناء فإنني ... سأذهب حتى لم أجد متأخرا)\n(ولما رأيت الجهل زاد لجاجة ... يقول فلا يألوك أن تتشورا)\n(دنوت له حتى كأن قميصه ... تشرب من نضح الأخادع عصفرا)\n(فمن مبلغ ليث بن بكر بأننا ... تركنا أخاهم يوم قرن معفرا)\nقال غزا تأبط بني نفاثة بن الديل بن بكر بن عبد مناة بن كنانة وهم خلوف ليس في دارهم رجل وكان الخبر قد أتى تأبط فأشرف فوق جبل ينظر إلى الحي وهم أسفل منه فرأته امرأة فطرح نفسه فعلمت المرأة أنه تأبط وكانت عاقلة فأمرت النساء فلبسن لبسة الرجال ثم خرجن كأنهن يطلبن الضالة وكان أصحابه يتفلتون ويقولون اغز وإنما كان في سرية من بين الستة إلى السبعة فأبى أن يدعهم وخرج يريد هذيلا وانصرف عن النفاثيين فبينا هو يتردد في تلك الجبال إذ لقي حليفا له من هذيل فقال له العجب لك يا تأبط قال وما هو قال إن رجال بني نفاثة كانوا خلوفا فمكرت بك امرأة وأنهم قد رجعوا ففي ذلك يقول\n(ألا عجب الفتيان من أم مالك ... تقول لقد أصبحت أشعث أغبرا)\nذكر باقي الأبيات المتقدمة وقال غيره لا بل قال هذه القصيدة في عامر بن الأخنس الفهمي وكان من حديث عامر بن الأخنس انه غزا في نفر بضعة وعشرين رجلا فيهم عامر بن الأخنس وكان سيدا فيهم وكان إذا خرج في غزو رأسهم وكان يقال له سيد الصعاليك فخرج بهم حتى باتوا على بني نفاثة بن عدي بن الديل ممسين ينتظرون أن ينام الحي حتى إذا كان في سواد الليل مر بهم راع من الحي قد أغدر فمعه غديرته يسوقها فبصر بهم وبمكانهم فخلى الغديرة وتبع الضراء ضراء الوادي حتى جاء الحي فأخبرهم بمكان القوم وحيث رآهم فقاموا فاختاروا فتيان الحي فسلحوهم وأقبلوا نحوهم حتى إذا دنوا منهم قال رجل من النفاثيين والله ما قوسي بموترة فقالوا فأوتر\nقوسك فوضع قوسه فأوترها فقال تأبط لأصحابه اسكتوا واستمع فقال أتيتم والله قالوا وما ذلك قال أنا والله أسمع حطيط وترقوس قالوا والله ما نسمع شيئا","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":12,"spl":"كان ضعيفا أمام النساء","tags":["المديح"],"loc":1844},
{"id":"b104-20","bab":"الجزء 10","sec":"كان ضعيفا أمام النساء","page":"ج10 ص171","text":"قال بلى والله إني لأسمعه يا قوم النجاء قالوا لا والله ما سمعت شيئا فوثب فانطلق وتركهم ووثب معه نفر وبيتهم بنو نفاثة فلم يفلت منهم إنسان وخرج هو وأصحابه الذين انطلقوا معه وقتل تلك الليلة عامر بن الأخنس قال ابن عمير وسألت أهل الحجاز عن عامر بن الأخنس فزعموا أنه مات على فراشه فلما رجع تأبط قالت له امرأته تركت أصحابك فقال حينئذ\n(ألا عجب الفتيان من أم مالك ... تقول لقد أصبحت أشعث أغبرا)","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":13,"spl":"كان ضعيفا أمام النساء","tags":["السفر والحج","الوصف والطبيعة"],"loc":1845},
{"id":"b104-21","bab":"الجزء 10","sec":"مصرعه على يد غلام","page":"ج10 ص175","text":"فلما رجع تأبط وبلغه ما لقي أصحابه قال والله ما يمس رأسي غسل ولادهن حتى أثأر بهم فخرج في نفر من قومه حتى عرض لهم بيت من هذيل بين صوى جبل فقال اغنموا هذا البيت أولا قالوا لا والله ما لنا فيه أرب ولئن كانت فيه غنيمة ما نستطيع أن نسوقها فقال إني أتفاءل أن أنزل ووقف وأتت به ضبع من يساره فكرهها وعاف على غير الذي رأى فقال أبشري أشبعك من القوم غدا فقال له أصحابه ويحك انطلق فو الله ما نرى أن نقيم عليها قال لا والله لا أريم حتى أصبح وأتت\nبه ضبع عن يساره فقال أشبعك من القوم غدا فقال أحد القوم والله إني أرى هاتين غدا بك فقال لا والله لا أريم حتى أصبح فبات حتى إذا كان في وجه الصبح وقد رأى أهل البيت وعدهم على النار وأبصر سواد غلام من القوم دون المحتلم وغدوا على القوم فقتلوا شيخا وعجوزا وحازوا جاريتين وإبلا ثم\nقال تأبط إني قد رأيت معهم غلاما فأين الغلام الذي كان معهم فأبصر أثره فاتبعه فقال له أصحابه ويلك دعه فإنك لا تريد منه شيئا فاتبعه واستتر الغلام بقتادة إلى جنب صخرة وأقبل تأبط يقصه وفوق الغلام سهما حين رأى انه لا ينجيه شيء وأمهله حتى إذا دنا منه قفز قفزة فوثب على الصخرة وأرسل السهم فلم يسمع تأبط إلى الحبضة فرفع رأسه فانتظم السهم قلبه وأقبل نحوه وهو يقول لا بأس فقال الغلام لا بأس والله لقد وضعته حيث تكره وغشيه تأبط بالسيف وجعل الغلام يلوذ بالقتادة ويضر بها تأبط بحشاشته فيأخذ ما أصابت الضربة منها حتى خلص إليه فقتله ثم نزل إلى أصحابه يجر رجله فلما رأوه وثبوا ولم يدروا ما أصابه فقالوا مالك فلم ينطق ومات في أيديهم فانطلقوا وتركوه فجعل لا يأكل منه سبع ولا طائر إلا مات فاحتملته هذيل فألقته في غار يقال له غار رخمان فقالت ريطة أخته وهي يومئذ متزوجة في بني الديل\n(نعم الفتى غادرتم برخمان ... ثابت بن جابر بن سفيان)\nوقال مرة بن خليف يرثيه\n(إن العزيمة والعزاء قد ثويا ... أكفان ميت غدا في غار رخمان)\n(إلا يكن كرسف كفنت جيده ... ولا يكن كفن من ثوب كتان)\n(فإن حرا من الأنساب ألبسه ... ريش الندى والندى من خير أكفان)\n(وليلة رأس أفعاها إلى حجر ... ويوم أور من الجوزاء رنان)\n(أمضيت أول رهط عند آخره ... في إثر عادية أو إثر فتيان)\nقالت أم تأبط ترثيه\n(وابناه وابن الليل ... )\nال أبو عمرو الشيباني لا بل كان من شأن تأبط وهو ثابت بن جابر بن سفيان وكان جزيئا شاعرا فاتكا انه خرج من أهله بغارة من قومه يريدون بني صاهلة بن كاهل بن الحارث بن سعيد بن هذيل وذلك في عقب شهر حرام مما كان يحرم أهل الجاهلية حتى هبط صدر أدم وخفض عن جماعة بني صاهلة فاستقبل التلاعة فوجد بها دارا من بني نفاثة بن عدي ليس فيها إلا النساء غير رجل واحد فبصر الرجل بتأبط وخشيه وذلك في الضحى فقام الرجل إلى النساء فأمرهن فجعلن رؤوسهن جمما وجعلن دروعهن أردية وأخذن من بيوتهن عمدا كهيئة السيوف فجعلن لها حمائل ثم تأبطنها ثم نهض ونهضن معه يغريهن كما يغري القوم وأمرهن أن لا يبرزن\nخدا وجعل هو يبرز للقوم ليروه وطفق يغري ويصيح على القوم حتى أفزع تأبط شرا وأصحابه وهو على ذلك يغري في بقية ليلة أوليلتين من الشهر الحرام فنهضوا في شعب يقال له شعب وشل وتأبط ينهض في الشعب مع أصحابه ثم يقف في آخرهم ثم يقول يا قوم لكأنما يطردكم النساء فيصيح عليه أصحابه فيقولون انج أدركك القوم وتأبى نفسه فلم يزل به أصحابه حتى مضى معهم فقال تأبط في ذلك\n(أبعد النفاثيين أزجر طائرا ... وآسى على شيء إذا هو أدبرا)\n(أنهنه رجلي عنهم وإخالهم ... من الذل يعرا بالتلاعة أعفرا)\n(ولو نالت الكفان أصحاب نوفل ... بمهمهة من بين ظرء وعرعرا)\nال ثم طلعوا الصدر حين أصبحوا فوجدوا أهل بيت شاذ من بني قريم ذنب نمار فظل يراقبهم حتى أمسوا وذلك البيت لساعدة بن سفيان أحد بني حارثة بن قريم فحصرهم تأبط وأصحابه حتى أمسوا","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":14,"spl":"مصرعه على يد غلام","tags":["الحب والغزل","الوصف والطبيعة"],"loc":1846,"partial":1},
{"id":"b104-23","bab":"الجزء 10","sec":"مصرعه على يد غلام — أمه ترثيه","page":"ج10 ص175 – ج10 ص179","text":"قال وقد كانت قالت وليدة لساعدة إني قد رأيت اليوم القوم أو النفر بهذا الجبل فبات الشيخ حذرا قائما بسيفه بساحة أهله وانتظر تأبط وأصحابه أن يغفل الشيخ وذلك آخر ليلة من الشهر الحرام فلما خشوا أن يفضحهم الصبح ولم يقدروا على غرة مشوا إليه وغروه ببقية الشهر الحرام وأعطوه من مواثيقهم ما أقنعه وشكوا إليه الجوع فلما اطمأن إليهم وثبوا عليه فقتلوه وابنا له صغيرا حين مشى قال ومضى تأبط شرا إلى ابن له ذي ذؤابة كان أبوه قد أمره فارتبأ\nمن وراء ماله يقال له سفيان بن ساعدة فأقبل إليه تأبط شرا مستترا بمجنة فلما خشي الغلام أن يناله تأبط بسيفه مع الغلام سيف وهو مفوق سهما رمى مجن تأبط بحجر فظن تأبط انه قد أرسل سهمه فرمى مجنة عن يده ومشى إليه فأرسل الغلام سهمه فلم يخط لبته حتى خرج منه السهم ووقع في البطحاء حذو القوم وأبوه ممسك فقال أبو الغلام حين وقع السهم أخاطئه سفيان فحرد القوم فذلك حين قتلوا الشيخ وابنه الصغير ومات تأبط\nفقالت أمه وكانت امرأة من بني القين بن جسر بن قضاعة ترثيه\n(قتيل ما قتيل بني قريم ... إذا ضنت جمادى بالقطار)\n(فتى فهم جميعا غادروه ... مقيما بالحريضة من نمار)\nقالت أمه ترثيه أيضا\n(ويل ام طرف غادروا برخمان ... بثابت بن جابر بن سفيان)\n(يجدل القرن ويروي الندمان ... ذو مأقط يحمي وراء الإخوان)\nقالت ترثيه أيضا\nوابناه ابن الليل ليس بزميل شروب للقيل رقود بالليل وواد ذي هول أجزت بالليل تضرب بالذيل برجل كالثول قال وكان تأبط شرا يقول قبل ذلك\n(ولقد علمت لتعدونم ... علي شتم كالحساكل)\n(ياكلن أوصالا ولحما ... كالشكاعي غير جاذل)\n(يا طير كلن فإنني ... سم لكن وذو دغاول)\nقال قبل موته\n(لعلي ميت كمدا ولما ... أطالع أهل ضيم فالكراب)\n(وإن لم آت جمع بني خثيم ... وكاهلها برجل كالضباب)\n(إذا وقعت بكعب أو قريم ... وسيار فياسوغ الشراب)\nأجابه شاعر من بني قريم\n(تأبط سوأة وحملت شرا ... لعلك أن تكون من المصاب)\n(لعلك أن تجيء بك المنايا ... تساق لفتية منا غضاب)\n(فتصبح في مكرهم صريعا ... وتصبح طرفة الضبع السغاب)\n(فزلتم تهربون ولو كرهتم ... تسوقون الحرائم بالنقاب)\n(وزال بأرضكم منا غلام ... طليعة فتية غلب الرقاب)\nنذكر ها هنا بعد أخبار تأبط شرا أخبار صاحبيه عمرو بن براق والشنفرى ونبدأ بما يغنى فيه من شعريهما ونتبعه بالأخبار فأما عمرو بن براق فمما يغنى فيه من شعره قوله\n(متى تجمع القلب الذكي وصارما ... وأنفا حميا تجتنبك المظالم)\n(وكنت إذا قوم غزوني غزوتهم ... فهل أنا في ذا يا لهمدان ظالم)\n(كذبتم وبيت الله لا تأخذونها ... مراغمة ما دام للسيف قائم)\n(ولا صلح حتى تعثر الخيل بالقنا ... وتضرب بالبيض الرقاق الجماجم)\nروضه من الطويل الشعر لابن براق وقيل ابن براقة والغناء لمحمد ابن إسحاق بن عمرو بن بزيع ثقيل أول مطلق في مجرى الوسطى عن الهشامي","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":15,"spl":"مصرعه على يد غلام — أمه ترثيه","tags":[],"song":1,"loc":1847},
{"id":"b104-25","bab":"الجزء 10","sec":"عمرو بن براق — سلب منه ماله ثم استرده","page":"ج10 ص181 – ج10 ص182","text":"أخبرني علي بن سليمان الأخفش قال حدثنا السكري عن ابن حبيب قال واخبرنا الهمداني ثعلب عن ابن الأعرابي عن المفضل قالا\nفقال في ذلك أغار رجل من همدان يقال له حريم على إبل لعمرو بن براق وخيل فذهب بها فأتى عمرو امرأة كان يتحدث إليها ويزورها فأخبرها أن حريما أغار على إبله وخيله فذهب بها وأنه يريد الغارة عليه فقالت له المرأة ويحك لا تعرض لتلفات حريم فإني أخافه عليك قال فخالفها وأغار عليه فاستاق كل شيء كان له فأتاه حريم بعد ذلك يطلب إليه أن يرد عليه ما أخذه منه فقال لا أفعل وأبى عليه فانصرف فقال عمرو في ذلك\n(تقول سليمى لا تعرض لتلفة ... وليلك عن ليل الصعاليك نائم)\n(وكيف ينام الليل من جل ماله ... حسام كلون الملح أبيض صارم)\n(صموت إذا عض الكريهة لم يدع ... لها طمعا طوع اليمين ملازم)\n(نقدت به ألفا وسامحت دونه ... على النقد إذ لا تستطاع الدراهم)\n(ألم تعلمي أن الصعاليك نومهم ... قليل إذا نام الدثور المسالم)\n(إذا الليل أدجى واكفهرت نجومه ... وصاح من الإفراط هام جواثم)\n(ومال بأصحاب الكرى غالباته ... فإني على أمر الغواية حازم)\n(كذبتم وبيت الله لا تأخذونها ... مراغمة ما دام للسيف قائم)\n(تحالف أقوام علي ليسمنوا ... وجروا علي الحرب إذا أنا سالم)\n(أفالآن أدعى للهوادة بعدما ... أجيل على الحي المذاكي الصلادم)\n(كأن حريما إذ رجا أن يضمها ... ويذهب مالي يا بنة القوم حالم)\n(متى تجمع القلب الذكي وصارما ... وأنفا حميا تجتنبك المظالم)\n(ومن يطلب المال الممنع بالقنا ... يعش ذا غنى أو تخترمه المخارم)\n(وكنت إذا قوم غزوني غزوتهم ... فهل أنا في ذا يالهمدان ظالم)\n(فلا صلح حتى تعثر الخيل بالقنا ... وتضرب بالبيض الرقاق الجماجم)\nأما الشنفرى فإنه رجل من الأزد ثم من الأواس بن الحجر بن الهنو بن الأزد ومما يغنى فيه من شعره قوله\n\n(ألا أم عمرو أزمعت فاستقلت ... وما ودعت جيرانها إذ تولت)\n(فواندما بانت أمامة بعدما ... طمعت فهبها نعمة قد تولت)\n(وقد أعجبتني لا سقوطا خمارها ... إذا ما مشت ولا بذات تلفت)\nنى في هذه الأبيات إبراهيم ثاني ثقيل بالبنصر عن عمرو بن بانة","topic":"أخبار تأبط شرا ونسبه","topicNo":104,"sp":16,"spl":"عمرو بن براق — سلب منه ماله ثم استرده","tags":["الجواري والنساء"],"song":1,"loc":1848},
{"id":"b105-1","bab":"الجزء 10","sec":"أخبار الشنفرى ونسبه أخبار في غير قومه","page":"ج10 ص185","text":"وأخبرني بخبره الحرمي بن أبي العلاء قال حدثنا أبو يحيى المؤدب وأحمد ابن أبي المنهال المهلبي عن مؤرج عن أبي هشام محمد بن هشام النميري أن الشنفرى كان من الأواس بن الحجر بن الهنو بن الأزد بن الغوث أسرته بنو شبابة بن فهم بن عمرو بن قيس بن عيلان فلم يزل فيهم حتى أسرت بنو سلامان بن مفرج بن عوف بن ميدعان بن مالك بن الأزد رجلا من فهم أحد بني شبابة ففدته بنو شبابة بالشنفرى\nقال فكان الشنفرى في بني سلامان بن مفرج لا تحسبه إلا أحدهم حتى نازعته بنت الرجل الذي كان في حجره وكان السلامي اتخذه ولدا وأحسن إليه وأعطاه فقال لها الشنفرى اغسلي رأسي يا أخية وهو لا يشك في أنها أخته فأنكرت أن يكون أخاها ولطمته فذهب مغاضبا حتى أتى الذي اشتراه من فهم فقال له الشنفرى اصدقني ممن أنا\nقال أنت من الأواس بن الحجر فقال أما إني لن أدعكم حتى أقتل منكم مائة بما استعبدتموني ثم إنه ما زال يقتلهم حتى قتل تسعة وتسعين رجلا وقال الشنفرى للجارية السلامية التي لطمته وقالت لست بأخي\n(ألا ليت شعري والتلهف ضلة ... بما ضربت كف الفتاة هجينها)\n(ولو علمت قعسوس أنساب والدي ... ووالدها ظلت تقاصر دونها)\n(أنا ابن خيار الحجر بيتا ومنصبا ... وأمي ابنة الأحرار لو تعرفينها)\nال ثم لزم الشنفرى دار فهم فكان يغير على الأزد على رجليه فيمن تبعه من فهم وكان يغير وحده أكثر من ذلك وقال الشنفرى لبني سلامان\n(وإني لأهوى أن ألف عجاجتي ... على ذي كساء من سلامان أو برد)\n(وأصبح بالعضداء أبغي سراتهم ... وأسلك خلا بين أرباع والسرد)\nكان يقتل بني سلامان بن مفرج حتى قعد له رهط من الغامديين من بني الرمداء فأعجزهم فأشلوا عليه كلبا لهم يقال له حبيش ولم يضعوا له شيئا ومر وهو هارب بقرية يقال لها دحيس برجلين من بني سلامان بن مفرج فأرادهما ثم خشي الطلب فقال\n(قتيلي فجار أنتما إن قتلتما ... بجوف دحيس أو تبالة يا اسمعا)\nريد يا هذان اسمعا وقال فيما كان يطالب به بني سلامان\n(فإلا تزرني حتفتي أو تلاقني ... أمش بدهر أو عذاف فنورا)\n(أمشي بأطراف الحماط وتارة ... تنفض رجلي بسبطا فعصنصرا)\n(وأبغي بني صعب بن مر بلادهم ... وسوف ألاقيهم إن الله يسرا)\n(ويوما بذات الرأس أو بطن منجل ... هنالك تلقى القاصي المتغورا)","topic":"أخبار الشنفرى ونسبه","topicNo":105,"sp":0,"spl":"أخبار الشنفرى ونسبه أخبار في غير قومه — سملوا عينه ثم قتلوه","tags":["الجواري والنساء","السفر والحج"],"loc":1849},
{"id":"b105-2","bab":"الجزء 10","sec":"سملوا عينه ثم قتلوه","page":"ج10 ص187","text":"قال ثم قعد له بعد ذلك أسيد بن جابر السلاماني وخازم الفهمي بالناصف من أبيدة ومع أسيد ابن أخيه فمر عليهم الشنفرى فأبصر السواد بالليل فرماه وكان لا يرى سوادا إلا رماه كائنا ما كان فشك ذراع ابن أخي أسيد إلى عضده فلم يتكلم فقال الشنفرى إن كنت شيئا فقد أصبتك وإن لم تكن شيئا فقد أمنتك وكان خازم باطحا يعني منبطحا بالطريق يرصده فنادى أسيد يا خازم أصلت يعني اسلل سيفك فقال الشنفرى لكل أصلت فأصلت الشنفرى فقطع إصبعين من أصابع خازم الخنصر والبنصر وضبطه خازم حتى لحقه أسيد وابن أخيه نجدة فأخذ أسيد سلاح الشنفرى وقد صرع الشنفرى خازما وابن أخي أسيد فضبطاه وهما تحته وأخذ أسيد برجل ابن أخيه فقال أسيد رجل من هذه فقل الشنفرى رجلي فقال ابن أخي أسيد بل هي رجلي يا عم فأسروا الشنفرى وأدوه إلى أهلهم وقالوا له أنشدنا فقال إنما النشيد على المسرة فذهبت مثلا ثم ضربوا يده فتعرضت أي اضطربت فقال الشنفرى في ذلك\n(لا تبعدي إما ذهبت شامه ... فرب واد نفرت حمامه)\n(ورب قرن فصلت عظامه ... )\nثم قال له السلامي أأطرفك ثم رماه في عينه فقال الشنفرى له كأن كنا نفعل أي كذلك كنا نفعل وكان الشنفرى إذا رمى رجلا منهم قال له أأطرفك ثم يرمي عينه ثم قالوا له حين أرادوا قتله أين نقبرك فقال\n(لا تقبروني إن قبري محرم ... عليكم ولكن أبشري أم عامر)\n(إذا احتملت رأسي وفي الرأس أكثري ... وغودر عند الملتقى ثم سائري)\n(هنالك لا أرجو حياة تسرني ... سمير الليالي مبسلا بالجرائر)","topic":"أخبار الشنفرى ونسبه","topicNo":105,"sp":0,"spl":"أخبار الشنفرى ونسبه أخبار في غير قومه — سملوا عينه ثم قتلوه","tags":["الوصف والطبيعة"],"loc":1850,"partial":1},
{"id":"b105-3","bab":"الجزء 10","sec":"تأبط شرا يرثيه","page":"ج10 ص188","text":"وقال تأبط شرا يرثي الشنفرى\n(على الشنفرى ساري الغمام ورائح ... غزير الكلى وصيب الماء باكر)\n(عليك جزاء مثل يومك بالجبا ... وقد أرعفت منك السيوف البواتر)\n(ويومك يوم العيكتين وعطفة ... عطفت وقد مس القلوب الحناجر)\n(تجول ببز الموت فيهم كأنهم ... بشوكتك الحدى ضئين نوافر)\n(فإنك لو لاقيتني بعدما ترى ... وهل يلقين من غيبته المقابر)\n(لألفيتني في غارة أنتمي بها ... إليك وإما راجعا أنا ثائر)\n(وإن تك مأسورا وظلت مخيما ... وأبليت حتى ما يكيدك واتر)\n(وحتى رماك الشيب في الرأس عانسا ... وخيرك مبسوط وزادك حاضر)\n(وأجمل موت المرء إذ كان ميتا ... ولا بد يوما موته وهو صابر)\n(فلا يبعدن الشنفري وسلاحه الحديد ... وشد خطوه متواتر)\n(إذا راع روع الموت راع وإن حمى ... معه حر كريم مصابر)","topic":"أخبار الشنفرى ونسبه","topicNo":105,"sp":1,"spl":"تأبط شرا يرثيه — خبر آخر عن سبب اسره ومقتله","tags":["الموت"],"loc":1851},
{"id":"b105-4","bab":"الجزء 10","sec":"خبر آخر عن سبب اسره ومقتله","page":"ج10 ص189","text":"قال وقال غيره لا بل كان من أمر الشنفرى وسبب أسره ومقتله أن الأزد قتلت الحارث بن السائب الفهمي فأبوا أن يبوءوا بقتله فباء بقتله رجل منهم يقال له حزام بن جابر قبل ذلك فمات أخو الشنفرى فأنشأت أمه تبكيه فقال الشنفرى وكان أول ما قاله من الشعر\n(ليس لوالدة هوءها ... ولا قولها لابنها دعدع)\n(تطيف وتحدث أحواله ... وغيرك أملك بالمصرع)\nال فلما ترعرع الشنفرى جعل يغير على الأزد مع فهم فيقتل من أدرك منهم ثم قدم منى وبها حزام بن جابر فقيل له هذا قاتل أبيك فشد عليه فقتله ثم سبق الناس على رجليه فقال\n(قتلت حزاما مهديا بملبد ... ببطن منى وسط الحجيج المصوت)\nال ثم إن رجلا من الأزد أتى أسيد بن جابر وهو أخو حزام المقتول فقال تركت الشنفرى بسوق حباشة فقال أسيد بن جابر والله لئن كنت صادقا لا نرجع حتى نأكل من جنى أليف أبيدة فقعد له على الطريق هو وابنا حزام فأحسوه في جوف الليل وقد نزع نعلا ولبس نعلا ليخفي وطأه فلما سمع الغلامان وطأه قالا هذه الضبع فقال أسيد ليست الضبع ولكنه الشنفرى ليضع كل واحد منكما نعله على مقتله حتى إذا رأى سوادهم نكص مليا لينظر هل يتبعه أحد ثم رجع حتى دنا منهم فقال الغلامان أبصرنا فقال عمهما لا والله ما أبصركما ولكنه أطرد لكيما تتبعاه فليضع كل وحدا منكما نعله على مقتله فرماهم الشنفرى فخسق في النعل ولم\nيتحرك المرمي ثم رمى فانتظم ساقي أسيد فلما رأى ذلك أقبل حتى كان بينهم فوثبوا عليه فأخذوه فشدوه وثاقا ثم إنهم انطلقوا به إلى قومهم فطرحوه وسطهم فتماروا بينهم في قتله فبعضهم يقول أخوكم وابنكم فلما رأى ذلك أحد بني حزام ضربه ضربة فقطع يده من الكوع وكانت بها شامة سوداء فقال الشنفرى حين قطعت يده\n(لا تبعدي إما هلكت شامه ... فرب خرق قطعت قتامه)\n(ورب قرن فصلت عظامه ... )\nقال تأبط شرا يرثيه\n(لا يبعدن الشنفرى وسلاحه الحديد ... وشد خطوه متواتر)\n(إذا راع روع الموت راع وإن حمى ... حمى معه حر كريم مصابر)\nقال وذرع خطو الشنفرى ليلة قتل فوجد أول نزوة نزاها إحدى وعشرين خطوة ثم الثانية سبع عشرة خطوة قال وقال ظالم العامر في الشنفرى وغاراته على الأزد وعجزهم عنه ويحمد أسيد بن جابر في قتله الشنفرى\n(فما لكم لم تدركوا رجل شنفرى ... وأنتم خفاف مثل أجنحة الغرب)\n(تعاديتم حتى إذا ما لحقتم ... تباطأ عنكم طالب وأبو سقب)\n(لعمرك للساعي أسيد بن جابر ... أحق بها منكم بني عقب الكلب)\nقال ولما قتل الشنفرى وطرح رأسه مر به رجل منهم فضرب جمجمة الشنفرى بقدمه فعقرت قدمه فمات منها فتمت به المائة","topic":"أخبار الشنفرى ونسبه","topicNo":105,"sp":1,"spl":"تأبط شرا يرثيه — خبر آخر عن سبب اسره ومقتله","tags":["السفر والحج"],"loc":1852,"partialRef":{"sid":"b105-2","gi":0,"vi":1,"side":0},"partial":1},
{"id":"b105-5","bab":"الجزء 10","sec":"شعره لما قتل حزاما قاتل أبيه","page":"ج10 ص192","text":"وكان مما قاله الشنفرى فيهم من الشعر وفي لطمه المرأة التي أنكرته الذي ذكرته واستغني عن إعادته مما تقدم ذكره من شعر الشنفرى وقال الشنفرى في قتله حزاما قاتل أبيه\n(أرى أم عمرو أجمعت فاستقلت ... وما ودعت جيرانها إذ تولت)\n(فقد سبقتنا أم عمرو بأمرها ... وقد كان أعناق المطي أظلت)\n(فواندما على أميمة بعدما ... طمعت فهبها نعمة العيش ولت)\n(أميمة لا يخزي نثاها حليلها ... إذا ذكر النسوان عفت وجلت)\n(يحل بمنجاة من اللوم بيتها ... إذا ما بيوت بالملامة حلت)\n(فقد أعجبتني لا سقوط قناعها ... إذا ما مشت ولا بذات تلفت)\n(كأن لها في الأرض نسيا تقصه ... إذا ما مشت وإن تحدثك تبلت)\nلنسي الذي يسقط من الإنسان وهو لا يدري أين هو يصفها بالحياء وأنها لا تلتفت يمينا ولا شمالا ولا تبرج ويروى\n(تقصه على أمها وإن تكلمك ... )\n(فدقت وجلت واسبكرت وأكملت ... فلو جن إنسان من الحسن جنت)\n(تبيت بعيد النوم تهدي غبوبها ... لجاراتها إذا الهدية قلت)\nالغبوب ما غب عندها من الطعام أي بات ويروى غبوقها\n(فبتنا كأن البيت حجر حولنا ... بريحانة راحت عشاء وطلت)\n(بريحانة من بطن حلية أمرعت ... لها أرج من حولها غير مسنت)\n(غدوت من الوادي الذي بين مشعل ... وبين الجبا هيهات أنسأت سربتي)\n(أمشي على الأرض التي لن تضيرني ... لأكسب مالا أو ألاقي حمتي)\n(إذا ما أتتني حتفتي لم أبالها ... ولم تذر خالاتي الدموع وعمتي)\n(وهنيء بي قوم وما إن هنأتهم ... وأصبحت في قوم وليسوا بمنبتي)\n(وأم عيال قد شهدت تقوتهم ... إذا أطعمتهم أوتحت وأقلت)\n(تخاف علينا الجوع إن هي أكثرت ... ونحن جياع أي ألي تألت)\n(عفاهية لا يقصر الستر دونها ... ولا ترتجى للبيت إن لم تبيت)\n(لها وفضة فيها ثلاثون سلجما ... إذا ما رأت أولى العدي اقشعرت)\n(وتأتي العدي بارزا نصف ساقها ... كعدو حمار العانة المتفلت)\n(إذا فزعت طارت بأبيض صارم ... وراحت بما في جفرها ثم سلت)\n(حسام كلون الملح صاف حديده ... جراز من أقطار الحديد المنعت)\n(تراها كأذناب المطي صوادرا ... وقد نهلت من الدماء وعلت)\n(سنجزي سلامان بن مفرج قرضهم ... بما قدمت أيديهم وأزلت)\n(شفينا بعبد الله بعض غليلنا ... وعوف لدى لمعدى أوان استهلت)\n(قتلنا حزاما مهديا بملبد ... محلهما بين الحجيج المصوت)\n(فإن تقبلوا تقبل بمن نيل منهم ... وإن تدبروا فأم من نيل فتت)\n(ألا لا تزرني إن تشكيت خلتي ... كفاني بأعلى ذي الحميرة عدوتي)\n(وإني لحلو إن أريدت حلاوتي ... ومر إذا النفس الصدوف استمرت)\n(أبي لما آبى وشيك مفيئتي ... إلى كل نفس تنتحي بمودتي)\nقال الشنفرى أيضا\n(ومرقبة عنقاء يقصر دونها ... أخو الضروة الرجل الخفي المخفف)\n(نميت إلى أعلى ذراها وقد دنا ... من الليل ملتف الحديقة أسدف)\n(فبت على حد الذراعين أحدبا ... كما يتطوى الأرقم المتعطف)\n(قليل جهازي غير نعلين أسحقت ... صدورهما مخصورة لا تخصف)\n(وملحفة درس وجرد ملاءة ... إذا أنهجت من جانب لا تكفف)\n(وأبيض من ماء الحديد مهند ... مجد لأطراف السواعد مقطف)\n(وصفراء من نبع أبي ظهيرة ... ترن كإرنان الشجي وتهتف)\n(إذا طال فيها النزع تأتي بعجسها ... وترمي بذرويها بهن فتقذف)\n(كأن حفيف النبل من فوق عجسها ... عوازب نحل أخطأ الغار مطنف)\n(نأت أم قيس المربعين كليهما ... وتحذر أن ينأى بها المتصيف)\n(وإنك لو تدرين أن رب مشرب ... مخوف كداء البطن أو هو أخوف)\n(وردت بمأثور ونبل وضالة ... تخيرتها مما أريش وأرصف)\n(أركبها في كل أحمر عاتر ... وأقذف منهن الذي هو مقرف)\n(وتابعت فيه البري حتى تركته ... يزف إذا أنفذته ويزفزف)\n(بكفي منها للبغيض عراضة ... إذا بعت خلا ما له متخوف)\n(وواد بعيد العمق ضنك جماعه ... بواطنه للجن والأسد مألف)\n(تعسفت منه بعد ما سقط الندى ... غماليل يخشى غيلها المتعسف)\n(وإني إذا خام الجبان عن الردى ... فلي حيث يخشى أن يجاوز مخسف)\n(وإن امرأ أجار سعد بن مالك ... علي وأثواب الأقيصر يعنف)\nوقال الشنفرى أيضا\n(ومستبسل ضافي القميص ضغته ... بأزرق لا نكس ولا متعوج)\n(عليه نساري على خوط نبعة ... وفوق كعرقوب القطاة محدرج)\n(وقاربت من كفي ثم فرجتها ... بنزع إذا ما استكره النزع مخلج)\n(فصاحت بكفي صيحة ثم رجعت ... أنين الأميم ذي الجراح المشجج)\nقد روى فناحت بكفي نوحة","topic":"أخبار الشنفرى ونسبه","topicNo":105,"sp":2,"spl":"شعره لما قتل حزاما قاتل أبيه","tags":["السفر والحج"],"loc":1853,"partial":1},
{"id":"b105-6","bab":"الجزء 10","sec":"رواية ثالثة في مقتله","page":"ج10 ص196","text":"وقال غيره لا بل كان من أمر الشنفرى انه سبت بنو سلامان بن مفرج\nابن مالك بن هوازن بن كعب بن عبد الله بن مالك بن نصر بن الأزد الشنفرى وهو أحد بني ربيعة بن الحجر بن عمران بن عمرو بن حارثة بن ثعلبة بن امرئ القيس بن مازن بن الأزد وهو غلام فجعله الذي سباه في بهمة يرعاها مع ابنه له فلما خلا بها الشنفرى أهوى ليقبلها فصكت وجهه ثم سعت إلى أبيها فأخبرته فخرج إليه ليقتله فوجده وهو يقول\n(ألا هل أتى فتيان قومي جماعة ... بما لطمت كف الفتاة هجينها)\n(ولو علمت تلك الفتاة مناسبي ... ونسبتها ظلت تقاصر دونها)\n(أليس أبي خير الأواس وغيرها ... وأمي ابنة الخيرين لو تعلمينها)\n(إذا ما أروم الود بيني وبينها ... يؤم بياض الوجه مني يمينها)\nال فلما سمع قوله سأله ممن هو فقال أنا الشنفرى أخو بني الحارث بن ربيعة وكان من أقبح الناس وجها فقال له لولا أني أخاف أن يقتلني بنو سلامان لأنكحتك ابنتي فقال علي إن قتلوك أن أقتل بك مائة رجل منهم فأنكحه ابنته وخلى سبيله فسار بها إلى قومه فشدت بنو سلامان خلافه على الرجل فقتلوه فلما بلغه ذلك سكت ولم يظهر جزعا عليه وطفق يصنع النبل ويجعل أفواقها من القرون والعظام ثم إن امرأته بنت السلاماني قالت له ذات يوم لقد خست بميثاق أبي عليك فقال\n(كأن قد فلا يغررك مني تمكثي ... سلكت طريقا بين يربغ فالسرد)\n(وإني زعيم أن تثور عجاجتي ... على ذي كساء من سلامان أو برد)\n(هم عرفوني ناشئا ذا مخيلة ... أمشي خلال الدار كالفرس الورد)\n(كأني إذا لم يمس في الحي مالك ... بتيهاء لا أهدي السبيل ولا أهدي)\nال ثم غزاهم فجعل يقتلهم ويعرفون نبله بأفواقها في قتلاهم حتى قتل منهم تسعة وتسعين رجلا ثم غزاهم غزوة فنذروا به فخرج هاربا وخرجوا في إثره فمر بامرأة منهم يلتمس الماء فعرفته فأطعمته أقطا ليزيد عطشا ثم استسقى فسقته رائبا ثم غيبت عنه الماء ثم خرج من عندها وجاءها القوم فأخبرتهم خبره ووصفت صفته وصفة نبله فعرفوه فرصدوه على ركي لهم وهو ركي ليس لهم ماء غيره فلما جن عليه الليل أقبل إلى الماء فلما دنا منه\nقال إني أراكم وليس يرى أحدا إنما يريد بذلك أن يخرج رصدا إن كان ثم فأصاخ القوم وسكتوا ورأى سوادا وقد كانوا أجمعوا قبل إن قتل منهم قتيل أن يمسكه الذي إلى جنبه لئلا تكون حركة\nقال فرمى لما أبصر السواد فأصاب رجلا فقتله فلم يتحرك أحد فلما رأى ذلك أمن في نفسه وأقبل إلى الركي فوضع سلاحه ثم انحدر فيه فلم يرعه إلا بهم على رأسه قد أخذوا سلاحه فنزا ليخرج فضرب بعضهم شماله فسقطت فأخذها فرمى بها كبد الرجل فخر عنده في القليب فوطئ على رقبته فدقها وقال في قطع شماله\n(لا تبعدي إما ذهبت شامه ... فرب واد نفرت حمامه)\n(ورب قرن فصلت عظامه ... ورب حي فرقت سوامه)\nال ثم خرج إليهم فقتلوه وصلبوه فلبث عاما أو عامين مصلوبا وعليه من نذره رجل قال فجاء رجل منهم كان غائبا فمر به وقد سقط فركض رأسه برجله فدخل فيها عظم من رأسه فعلت عليه فمات منها فكان ذلك الرجل هو تمام المائة\n(ألا طرقت في الدجى زينب ... وأحبب بزينب إذ تطرق)\n(عجبت لزينب أنى سرت ... وزينب من ظلها تفرق)\nروضه من المتقارب الشعر لابن رهيمة والغناء لخليل المعلم رمل بالبنصر عن الهشامي وأبي أيوب المدني","topic":"أخبار الشنفرى ونسبه","topicNo":105,"sp":3,"spl":"رواية ثالثة في مقتله","tags":[],"song":1,"loc":1854},
{"id":"b106-2","bab":"الجزء 10","sec":"أخبار الخليل ونسبه — عمل في تأديب الصبيان وتعليم الجواري الغناء","page":"ج10 ص199 – ج10 ص200","text":"هو الخليل بن عمرو مكي مولى بني عامر بن لؤي مقل لا تعرف له صنعة غير هذا الصوت أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن أبي سعد قال حدثني القطراني المغني عن محمد بن حسين قال\nكان خليل المعلم يلقب خليلان وكان يؤدب الصبيان ويلقنهم القرآن والخط ويعلم الجواري الغناء في موضع واحد فحدثني من حضره قال كنت يوما عنده وهو يردد على صبي يقرأ بين يديه ( ومن الناس من يشتري لهو الحديث ليضل عن سبيل الله بغير علم\nثم يلتفت إلى صبية بين يديه فيردد عليها\n(اعتاد هذا القلب بلباله ... أن قربت للبين أجماله)\nضحكت ضحكا مفرطا لما فعله فالتفت الي فقال ويلك مالك فقلت أتنكر ضحكي مما تفعل والله ما سبقك إلى هذا أحد ثم قلت أنظر أي\nشيء أخذت على الصبي من القرآن وأي شيء هوذا على الصبية والله إني لأظنك ممن يشتري لهو الحديث ليضل عن سبيل الله فقال أرجو ألا أكون كذلك إن شاء الله\nأخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد المبرد قال حدثني عبد الصمد بن المعذل قال كان خليلان المعلم أحسن الناس غناء وأفتاهم وأفصحهم فدخل يوما على عقبة بن سلم الأزدي الهنائي فاحتبسه عنده فأكل معه ثم شرب وحانت منة التفاتة فرأى عودا معلقا فعلم أنه عرض له به فدعا به وأخذه فغناهم\n(يا بنة الأزدي قلبي كئيب ... مستهام عندها ما ينيب)\nحانت منه التفاتة فرأى وجه عقبة بن سلم متغيرا وقد ظن أنه عرض به ففطن لما أراد فغنى\n(ألا هزئت بنا قرشية ... يهتز موكبها)\nسري عن عقبة وشرب فلما فرغ وضع العود من حجره وحلف بالطلاق ثلاثا أنه لا يغني بعد يومه ذلك إلا لمن يجوز حكمه عليه","topic":"أخبار الخليل ونسبه","topicNo":106,"sp":0,"spl":"أخبار الخليل ونسبه — عمل في تأديب الصبيان وتعليم الجواري الغناء — نسبة هذين الصوتين","tags":["الجواري والنساء"],"loc":1855},
{"id":"b106-3","bab":"الجزء 10","sec":"نسبة هذين الصوتين","page":"ج10 ص201","text":"(يا بنة الأزدي قلبي كئيب ... مستهام عندها ما ينيب)\n(ولقد لاموا فقلت دعوني ... إن من تنهون عنه حبيب)\n(إنما أبلى عظامي وجسمي ... حبها والحب شيء عجيب)\n(أيها العائب عندي هواها ... أنت تفدي من أراك تعيب)\nعروضه من المديد والشعر لعبد الرحمن بن أبي بكر الصديق رضي الله عنه والغناء لمعبد ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لمالك خفيف ثقيل أول بالخنصر في مجرى البنصر عنه وفيه خفيف رمل بالسبابة في مجرى الوسطى لم ينسبه إسحاق إلى أحد ووجدته في روايات لا أثق بها منسوبا إلى حنين وقد\nذكر يونس أن فيه لحنين ولمالك كلاهما ولعل هذا أحدهما وذكر حبش أن خفيف الرمل لابن سريج وذكر الهشامي وعلي بن يحيى أن لحن مالك الآخر ثاني ثقيل وذكر الهشامي أن فيه لطويس هزجا مطلقا في مجرى البنصر وذكر عمرو بن بانة أن لمالك فيه ثقيلا أول وخفيفه ولمعبد خفيف ثقيل آخر\n(ألا هزئت بنا قرشية ... يهتز موكبها)\n(رأت بي شيبة في الرأس ... مني ما أغيبها)\n(فقالت لي ابن قيس ذا ... وبعض الشيب يعجبها)\n(لها بعل خبيث النفس ... يحصرها ويحجبها)\n(يراني هكذا أمشي ... فيوعدها ويضربها)\nروضه من الوافر الشعر لابن قيس الرقيات والغناء لمعبد خفيف\nثقيل بالخنصر في مجرى الوسطى وفيه ليونس ثقيل أول عن إسحاق بن إبراهيم والهشامي\n(هل ما علمت وما استودعت مكتوم ... أم حبلها إذ نأتك اليوم مصروم)\n(أم هل كئيب بكى لم يقض عبرته ... إثر الأحبة يوم البين مشكوم)\n(يحملن أترجة نضخ العبير بها ... كأن تطيابها في الأنف مشموم)\n(كأن فأرة مسك في مفارقها ... للباسط المتعاطى وهو مزكوم)\n(كأن إبريقهم ظبي على شرف ... مفدم بسبا الكتان ملثوم)\n(قد أشهد الشرب فيهم مزهر صدح ... والقوم تصرعهم صهباء خرطوم)\nلشعر لعلقمة بن عبدة والغناء لابن سريج وله فيه لحنان أحدهما في الأول والثاني خفيف ثقيل أول بالخنصر في مجرى البنصر عن إسحاق\nوالآخر رمل بالخنصر في مجرى البنصر في الخامس والسادس من الأبيات وذكر عمرو بن بانة أن في الأربعة الأبيات الأول المتوالية لمالك خفيف ثقيل بالوسطى وفيها ثقيل أول نسبه الهشامي إلى الغريض وذكر حبش أن لحن الغريض ثاني ثقيل بالبنصر وذكر حبش أن في الخامس والسادس خفيف رمل بالبنصر لابن سريج","topic":"أخبار الخليل ونسبه","topicNo":106,"sp":0,"spl":"أخبار الخليل ونسبه — عمل في تأديب الصبيان وتعليم الجواري الغناء — نسبة هذين الصوتين","tags":["الحب والغزل"],"song":2,"loc":1856},
{"id":"b107-2","bab":"الجزء 10","sec":"أخبار علقمة ونسبه — سبب تلقيبه بالفحل","page":"ج10 ص205 – ج10 ص205","text":"هو علقمة بن عبدة بن النعمان بن ناشرة بن قيس بن عبيد بن ربيعة ابن مالك بن زيد مناة بن تميم بن مر بن أد بن طابخة بن إلياس بن مضر بن نزار وكان زيد مناة بن تميم وفد هو وبكر بن وائل وكانا لدة عصر واحد على بعض الملوك وكان زيد مناة حسودا شرها طعانا وكان بكر بن وائل خبيثا منكرا داهيا فخاف زيد مناة أن يحظى من الملك بفائدة ويقل معها حظه فقال له يا بكر لا تلق الملك بثياب سفرك ولكن تأهب للقائه وادخل عليه في أحسن زينة ففعل بكر ذلك وسبقه زيد مناة إلى الملك فسأله عن بكر فقال ذلك مشغول بمغازلة النساء والتصدي لهن وقد حدث نفسه بالتعرض لبنت الملك فغاظه ذلك وأمسك عنه ونمى الخبر إلى بكر بن وائل فدخل إلى الملك فأخبره بما دار بينه وبين زيد مناة وصدقه عنه واعتذر إليه مما قاله فيه عذرا قبله فلما كان من غد اجتمعا عند الملك فقال الملك لزيد مناة ما تحب أن أفعل بك فقال لا تفعل ببكر شيئا إلا فعلت بي مثليه وكان بكر أعور العين اليمنى قد أصابها ماء فذهب بها فكان لا يعلم من رآه أنه أعور فأقبل الملك على بكر بن وائل فقال له ما تحب أن أفعل بك يا بكر قال تفقأ عيني اليمنى وتضعف لزيد مناة فأمر بعينه\nالعوراء ففقئت وأمر بعيني زيد مناة ففقئتا فخرج بكر وهو أعور بحاله وخرج زيد مناة وهو أعمى\nواخبرني بذلك محمد بن الحسن بن دريد عن أبي حاتم عن أبي عبيدة ويقال لعلقمة بن عبدة علقمة الفحل سمي بذلك لأنه خلف على امرأة امرئ القيس لما حكمت له على امرئ القيس بأنه أشعر منه في صفة فرسه فطلقها فخالفه عليها وما زالت العرب تسميه بذلك وقال الفرزدق\n(والفحل علمقة الذي كانت له ... حلل الملوك كلامه يتنحل)","topic":"أخبار علقمة ونسبه","topicNo":107,"sp":0,"spl":"أخبار علقمة ونسبه — سبب تلقيبه بالفحل — هو امرؤ القيس يتحاكمان إلى زوجته","tags":["الجواري والنساء","السفر والحج"],"loc":1857},
{"id":"b107-3","bab":"الجزء 10","sec":"علقمة يحكم قريشا في شعره","page":"ج10 ص206","text":"أخبرني عمي قال حدثني النضر بن عمرو قال حدثني أبو السوار عن أبي عبيد الله مولى إسحاق بن عيسى عن حماد الراوية قال كانت العرب تعرض أشعارها على قريش فما قبلوه منها كان مقبولا وما ردوه منها كان مردودا فقدم عليهم علقمة بن عبدة فأنشدهم قصيدته التي يقول فيها\n(هل ما علمت وما استودعت مكتوم ... أم حبلها أن نأتك اليوم مصروم)\nفقالوا هذه سمط الدهر ثم عاد إليهم العام المقبل فأنشدهم\n(طحابك قلب في الحسان طروب ... بعيد الشباب عصر حان مشيب)\nقالوا هاتان سمطا الدهر أخبرني الحسن بن علي قال حدثني هارون بن محمد بن عبد الملك عن حماد بن إسحاق قال سمعت أبي يقول سرق ذو الرمة قوله\n(يطفو إذا ما تلقته الجراثيم ... )\nن قول العجاج\n(إذا تلقته العقاقيل طفا ... )\nسرقه العجاج من علقمة بن عبدة في قوله\n(يطفو إذا ما تلقته العقاقيل ... )","topic":"أخبار علقمة ونسبه","topicNo":107,"sp":0,"spl":"أخبار علقمة ونسبه — سبب تلقيبه بالفحل — هو امرؤ القيس يتحاكمان إلى زوجته","tags":["الرواية والكتابة"],"loc":1858,"partial":1},
{"id":"b107-4","bab":"الجزء 10","sec":"هو امرؤ القيس يتحاكمان إلى زوجته","page":"ج10 ص208","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن لقيط وأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني أبو عبيدة قال\nكانت تحت امرئ القيس امرأة من طيء تزوجها حين جاور فيهم فنزل به علقمة الفحل بن عبدة التميمي فقال كل واحد منهما لصاحبه أنا أشعر منك فتحاكما إليها فأنشد امرؤ القيس قوله\n(خليلي مرا بي على أم جندب ... )\nتى مر بقوله\n(فللسوط ألهوب وللساق درة ... وللزجر منه وقع أخرج مهذب)\nيروى أهوج منعب فأنشدها علقمة قوله\n(ذهبت من الهجران في غير مذهب ... )\nتى انتهى الى قوله\n(فأدركه حتى ثنى من عنانه ... يمر كغيث رائح متحلب)\nقالت له علقمة أشعر منك قال وكيف قالت لأنك زجرت فرسك وحركته بساقك وضربته بسوطك وأنه جاء هذا الصيد ثم أدركه ثانيا من عنانه فغضب امرؤ القيس وقال ليس كما قلت ولكنك هويته فطلقها فتزوجها علقمة بعد ذلك وبهذا لقب علقمة الفحل","topic":"أخبار علقمة ونسبه","topicNo":107,"sp":0,"spl":"أخبار علقمة ونسبه — سبب تلقيبه بالفحل — هو امرؤ القيس يتحاكمان إلى زوجته","tags":["الجواري والنساء","الرواية والكتابة"],"loc":1859,"partialRef":{"sid":"b78-4","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b107-5","bab":"الجزء 10","sec":"ربيعة بن حذار يصنف الشعراء","page":"ج10 ص209","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن لقيط قال تحاكم علقمة بن عبدة التميمي والزبرقان بن بدر السعدي والمخبل وعمرو بن الأهتم إلى ربيعة بن حذار الأسدي فقال أما أنت يا زبرقان فإن شعرك كلحم لا أنضج فيؤكل ولا ترك نيئا فينتفع به وأما أنت يا عمرو فإن شعرك كبرد حبرة يتلألأ في البصر فكلما أعدته فيه نقص وأما أنت يا مخبل فإنك قصرت عن الجاهلية ولم تدرك الإسلام وأما أنت يا علقمة فإن شعرك كمزادة قد أحكم خرزها فليس يقطر منها شيء أخبرني محمد بن الحسن بن دريد قال حدثني عمي عن العباس بن هشام عن أبيه قال\nمر رجل من مزينة على باب رجل من الأنصار وكان يتهم بامرأته فلما حاذى بابه تنفس ثم تمثل\n(هل ما علمت وما استودعت مكتوم ... أم حبلها إذ نأتك اليوم مصروم)\nال فتعلق به الرجل فرفعه إلى عمر رضوان الله عليه فاستعداه عليه فقال له المتمثل وما علي في أن أنشدت بيت شعر فقال له عمر رضي الله عنه مالك لم تنشده قبل أن تبلغ بابه ولكنك عرضت به مع ما تعلم من القالة فيه ثم أمر به فضرب عشرين سوطا\n(فو الله لا أنسى قتيلا رزيته ... بجانب قوسى ما حييت على الأرض)\n(بلى إنها تعفو الكلوم وإنما ... نوكل بالأدنى وإن جل ما يمضي)\n(ولم أدر من ألقى عليه رداءه ... ولكنه قد بز عن ماجد محض)\nلشعر لأبي خراش الهذلي والغناء لابن محرز خفيف ثقيل أول بالوسطى من رواية عمرو بن بانة وذكر يحيى بن المكي أنه لابن مسجح وذكر الهشامي أنه ليحيى المكي لحنه ابن مسجح وفي أخبار معبد إن له فيه لحنا","topic":"أخبار علقمة ونسبه","topicNo":107,"sp":1,"spl":"ربيعة بن حذار يصنف الشعراء","tags":["اللهو والمزاح","الرواية والكتابة"],"song":1,"loc":1860},
{"id":"b108-2","bab":"الجزء 10","sec":"ذكر أبي خراش الهذلي وأخباره نسبه وموته — شعره في نجاته من خصومه","page":"ج10 ص211 – ج10 ص213","text":"أبو خراش اسمه خويلد بن مرة أحد بني قرد واسم قرد عمرو بن معاوية بن سعد بن هذيل بن مدركة بن إلياس بن مضر بن نزار شاعر فحل من شعراء هذيل المذكورين الفصحاء مخضرم أدرك الجاهلية والإسلام فأسلم وعاش بعد النبي مدة ومات في خلافة عمر بن الخطاب رضي الله عنه نهشته أفعى فمات وكان ممن يعدو فيسبق الخيل في غارات قومه وحروبهم\nأخبرني حبيب بن نصر المهلبي وعمي والحسن بن علي قالوا حدثنا عبد الله بن أبي سعد قال حدثنا أحمد بن عمير بن إسماعيل بن عبد العزيز بن عمر بن عبد الرحمن بن عوف\nقال حدثني أبو بركة الأشجعي من أنفسهم قال خرج أبو خراش الهذلي من أرض هذيل يريد مكة فقال لزوجته أم خراش ويحك إني أريد مكة لبعض الحاجة وإنك من أفك النساء وإن بني الديل يطلبونني بترات فإياك وأن تذكريني لأحد من أهل مكة حتى نصدر منها قالت معاذ الله أن أذكرك لأهل مكة وأنا أعرف السبب\nقال فخرج بأم خراش وكمن لحاجته وخرجت إلى السوق لتشتري عطرا أو بعض ما تشتريه النساء من حوائجهن فجلست إلى عطار فمر بها فتيان من بني الديل فقال أحدهما لصاحبه أم خراش ورب الكعبة وإنها لمن أفك النساء وإن كان أبو خراش معها فستدلنا عليه\nقال فوقفا عليها فسلما وأحفيا المسألة والسلام فقالت من أنتما بأبي أنتما فقالا رجلان من أهلك من هذيل قالت بأبي أنتما فإن أبا خراش معي ولا تذكراه لأحد ونحن رائحون العشية فخرج الرجلان فجمعا جماعة من فتيانهم وأخذوا مولى لهم يقال له مخلد وكان من أجود الرجال عدوا فمكنوا في عقبة على طريقه فلما رآهم قد لاقوه في عين الشمس\nقال لها قتلتني ورب الكعبة لمن ذكرتني فقالت والله ما ذكرتك لأحد إلا لفتيين من هذيل فقال لها والله ما هما من هذيل ولكنهما من بني الديل وقد جلسا لي وجمعا علي جماعة من قومهم فاذهبي أنت فإذا جزت عليهم فإنهم لن يعرضوا لك لئلا أستوحش فأفوتهم فاركضي بعيرك وضعي عليه العصا والنجاء النجاء\nقال فانطلقت وهي على قعود عقيلي يسابق الريح فلما دنا منهم وقد ثلثموا ووضعوا تمرا على طريقه على كساء فوقف قليلا كأنه يصلح شيئا وجازت بهم أم خراش فلم يعرضوا لها لئلا ينفر منهم ووضعت العصا على قعودها وتواثبوا إليه ووثب يعدو\nقال فزاحمه على المحجة التي يسلك فيها على العقبة ظبي فسبقه أبو خراش وتصايح القوم يا مخلد أخذا أخذا قال ففات الأخذ فقالوا ضربا ضربا فسبق الضرب فصاحوا رميا\nرميا فسبق الرمي وسبقت أم خراش إلى الحي فنادت ألا إن أبا خراش قد قتل فقام أهل الحي إليها وقام أبوه وقال ويحك ما كانت قصته فقالت إن بني الديل عرضوا له الساعة في العقبة\nقال فما رأيت أو ما سمعت قالت سمعتهم يقولون يا مخلد أخذا أخذا قال ثم سمعت ماذا قالت ثم سمعتهم يقولون ضربا ضربا قال ثم سمعت ماذا قالت سمعتهم يقولون رميا رميا\nقال فإن كنت سمعت رميا رميا فقد أفلت وهو منا قريب ثم صاح يا أبا خراش فقال أبو خراش يا لبيك وإذا هو قد وافاهم على أثرها وقال أبو خراش في ذلك\n(رفوني وقالوا يا خويلد لم ترع ... فقلت وأنكرت الوجوه هم هم)\nفوني بالفاء سكنوني وقالوا لا بأس عليك\n(فغاررت شيئا والدريس كأنما ... يزعزعه وعك من الموم مردم)\nاررت تلبثت والدريس الخلق من الثياب ومثله الجرد والسحق والحشيف ومردم لازم\n(تذكرت ما أين المفر وإنني ... بحبل الذي ينجي من الموت معصم)\n(فوالله ما ربداء أو علج عانة ... أقب وما إن تيس رمل مصمم)\n(بأسرع مني إذ عرفت عديهم ... كأني لأولاهم من القرب توأم)\n(وأجود مني حين وافيت ساعيا ... وأخطأني خلف الثنية اسهم)\n(أوائل بالشد الذليق وحثني ... لدى المتن مشبوح الذراعين خلجم)\n(تذكر ذحلا عندنا وهو فاتك ... من القوم يعروه اجتراء ومأثم)\n(تقول ابنتي لما رأتني عشية ... سلمت وما إن كدت بالأمس تسلم)\n(فقلت وقد جاوزت صارى عشية ... أجاوزت أولى القوم أم أنا أحلم)\n(فلولا دراك الشد آضت حليلتي ... تخير في خطابها وهي أيم)\n(فستخط أو ترضى مكاني خليفة ... وكاد خراش عند ذلك ييتم)","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":0,"spl":"ذكر أبي خراش الهذلي وأخباره نسبه وموته — شعره في نجاته من خصومه","tags":["الجواري والنساء"],"loc":1861},
{"id":"b108-3","bab":"الجزء 10","sec":"عدا بين فرسين فسبقهما","page":"ج10 ص214","text":"أخبرني هاشم بن محمد الخزاعي ومحمد بن الحسين الكندي خطيب المسجد الجامع بالقادسية قالا حدثنا الرياشي قال حدثنا الأصمعي قال حدثني رجل من هذيل قال دخل أبو خراش الهذلي مكة وللوليد بن المغيرة المخزومي فرسان يريد أن يرسلهما في الحلبة فقال للوليد ما تجعل لي إن سبقتهما قال إن فعلت فهما لك فأرسلا وعدا بينهما فسبقهما فأخذهما\nقال الأصمعي إذا فاتك الهذلي أن يكون شاعرا أو ساعيا أو راميا فلا خير فيه وأخبرني بما أذكره من مجموع أخبار أبي خراش علي بن سليمان الأخفش عن أبي سعيد السكري\nوأخبرني بما أذكره من مجموع أشعارهم وأخبارهم فذكره أبو سعيد عن محمد بن حبيب عن ابن الأعرابي عن أبي حاتم عن أبي عبيدة وعن ابن حبيب عن أبي عمرو واخبرني ببعضه محمد بن العباس اليزيدي\nقال حدثنا الرياشي عن الأصمعي وقد ذكرت ما رواه في أشعار هذيل وأخبارها كل واحد منهم عن أصحابه في مواضعه قال السكري فيما رواه عن ابن حبيب عن أبي عمرو\nقال نزل أبو خراش الهذلي دبية السلمي وكان صاحب العزى التي في غطفان وكان يسدنها وهي التي هدمها خالد بن الوليد لما بعثه رسول الله إليها فهدمها وكسرها وقتل دبية السلمي قال فلما نزل عليه أبو خراش أحسن ضيافته ورأى في رجله نعلين قد أخلقتا فأعطاه نعلين من حذاء السبت فقال أبو خراش يمدحه\n(حذاني بعد ما خذمت نعالي ... دبية إنه نعم الخليل)\n(مقابلتين من صلوي مشب ... من الثيران وصلهما جميل)\n(بمثلهما يروح المرء لهوا ... ويقضي الهم ذو الأرب الرجيل)\n(فنعم معرس الأضياف تذحي ... رحالهم شآمية بليل)\n(يقاتل جوعهم بمكللات ... من الفرني يرعبها الجميل)\nال أبو عمرو الجميل الإهالة ولا يقال لها جميل حتى تذاب إهالة كانت أو شحما وقال أبو عمرو ولما بعث رسول الله خالد بن الوليد فهدم عزى غطفان وكانت ببطن نخلة نصبها ظالم بن أسعد بن عامر بن مرة وقتل دبية فقال أبو خراش الهذلي يرثيه\n(ما لدبية منذ اليوم لم أره ... وسط الشروب ولم يلمم ولم يطف)\n(لو كان حيا لغاداهم بمترعة ... فيها الرواويق من شيزى بني الهطف)\nنو الهطف قوم من بني أسد يعملون الجفان\n(كابي الرماد عظيم القدر جفنته ... حين الشتاء كحوض المنهل اللقف)\nلمنهل الذي إبله عطاش واللقف الذي يضرب الماء أسفله فيتساقط وهو ملآن\n(أمسى سقام خلاء لا أنيس به ... إلا السباع ومر الريح بالغرف)","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":1,"spl":"عدا بين فرسين فسبقهما — يرثي زهير بن العجوة","tags":["المديح"],"loc":1862},
{"id":"b108-4","bab":"الجزء 10","sec":"يرثي زهير بن العجوة","page":"ج10 ص217","text":"وقال الأصمعي وأبو عمرو في روايتهما جميعا أخذ أصحاب رسول الله في يوم حنين أسارى وكان فيهم زهير بن العجوة أخو بني عمرو بن الحارث فمر به جميل بن معمر بن حبيب بن وهب نب حذافة بن جمح وهو مربوط في الأسرى وكانت بينهما إحنة في الجاهلية فضرب عنقه فقال أبو خراش يرثيه\n(فجع أصحابي جميل بن معمر ... بذي فجر تأوي إليه الأرامل)\n(طويل نجاد السيف ليس بحيدر ... إذا قام واستنت عليه الحمائل)\n(إلى بيته يأوي الغريب إذا شتا ... ومهتلك بالي الدريسين عائل)\n(تروح مقرورا وراحت عشية ... لها حدب تحتثه فيوائل)\n(تكاد يداه تسلمان رداءه ... من القر لما استقبلته الشمائل)\n(فما بال أهل الدار لم يتصدعوا ... وقد خف منها اللوذعي الحلاحل)\n(فأقسم لو لاقيته غير موثق ... لآبك بالجزع الضباع النواهل)\n(لظل جميل أسوأ القوم تلة ... ولكن ظهر القرن للمرء شاغل)\n(فليس كعهد الدار يا أم مالك ... ولكن أحاطت بالرقاب السلاسل)\n(وعاد الفتى كالكهل ليس بقائل ... سوى الحق شيئا فاستراح العواذل)\n(ولم أنس أياما لا ولياليا ... بحلية إذ نلقى بها ما نحاول)\nقال أيضا يرثيه\n(أفي كل ممسى ليلة أنا قائل ... من الدهر لا يبعد قتيل جميل)\n(فما كنت أخشى أن تصيب دماءنا ... قريش ولما يقتلوا بقتيل)\n(فأبرح ما أمرتم وعمرتم ... مدى الدهر حتى تقتلوا بغليل)","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":1,"spl":"عدا بين فرسين فسبقهما — يرثي زهير بن العجوة","tags":[],"loc":1863},
{"id":"b108-5","bab":"الجزء 10","sec":"شعره في إنقاذ أسرى","page":"ج10 ص218","text":"وقال أبو عمرو في خبره خاصة أقبل أبو خراش وأخوه عروة وصهيب القردي في بضعة عشر رجلا من بني قرد يطلبون الصيد فبينا هم بالمجمعة من نخلة لم يرعهم إلا قوم قريب من عدتهم فظنهم القرديون قوما من بني ذؤيبة أحد بني سعد بن بكر بن هوازن أو من بني حبيب أحد بني نصر فعدا الهذليون إليهم يطلبونهم وطمعوا فيهم حتى خالطوهم وأسروهم جميعا وإذا هم قوم من بني ليث بن بكر فيهم ابنا شعوب أسرهما صهيب القردي فهم بقتلهما وعرفهم أبو خراش فاستنقذهم جميعا من أصحابه وأطلقهم فقال أبو خراش في ذلك يمن على ابني شعوب أحد بني شجع بن عامر بن ليث فعله بهما\n(عدونا عدوة لا شك فيها ... وخلناهم ذؤيبة أو حبيبا)\n(فنغري الثائرين بهم وقلنا ... شفاء النفس أن بعثوا الحروبا)\n(منعنا من عدي بني حنيف ... صحاب مضرس وابني شعوبا)\n(فأثنوا يا بني شجع علينا ... وحق ابني شعوب أن يثيبا)\n(وسائل سبرة الشجعي عنا ... غداة نخالهم نجوا جنيبا)\n(بأن السابق القردي ألقى ... عليه الثوب إذ ولى دبيبا)\n(ولولا ذاك أرهقه صهيب ... حسام الحد مطرورا خشيبا)","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":2,"spl":"شعره في إنقاذ أسرى — يفتدي أخاه عروة بن مرة","tags":[],"loc":1864},
{"id":"b108-6","bab":"الجزء 10","sec":"شعره في زهده","page":"ج10 ص219","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي قال حدثنا الأصمعي قال أقفر أبو خراش الهذلي من الزاد أياما ثم مر بامرأة من هذيل جزلة شريفة فأمرت له بشاة فذبحت وشويت فلما وجد بطنه ريح الطعام قرقر فضرب بيده على بطنه\nوقال إنك لتقرقر لرائحة الطعام والله لاطعمت منه شيئا ثم قال يا ربة البيت هل عندك شيء من صبر أو مر قالت تصنع به ماذا قال أريده فأتته منه بشيء فاقتمحه ثم أهوى إلى بعيره فركبه فناشدته المرأة فأبى فقالت له يا هذا هل رأيت بأسا أو أنكرت شيئا قال لا والله ثم مضى وأنشأ يقول\n(وإني لاثوي الجوع حتى يملني ... فأحيا ولم تدنس ثيابي ولا جرمي)\n(وأصطبح الماء القراح فأكتفي ... إذا الزاد أضحى للمزلج ذا طعم)\n(أرد شجاع البطن قد تعلمينه ... وأوثر غيري من عيالك بالطعم)\n(مخافة أن أحيا برغم وذلة ... فللموت خير من حياة على رغم)","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":2,"spl":"شعره في إنقاذ أسرى — يفتدي أخاه عروة بن مرة","tags":["الجواري والنساء","الرواية والكتابة"],"loc":1865},
{"id":"b108-7","bab":"الجزء 10","sec":"يفتدي أخاه عروة بن مرة","page":"ج10 ص220","text":"وأخبرني عمي بن هارون بن محمد الزيات عن أحمد بن الحارث عن المدائني بنحو مما رواه الأصمعي وقال أبو عمرو أسرت فهم عروة بن مرة أخا أبي خراش\nوقال غيره بل بنو كنانة أسرته فلما دخلت الأشهر الحرم مضى أبو خراش إليهم ومعه ابنه خراش فنزل بسيد من ساداتهم ولم يعرفه نفسه ولكنه استضافه فأنزله وأحسن قراه فلما تحرم به انتسب له وأخبره خبر أخيه وسأله معاونته حتى يشتريه منهم فوعده بذلك وغدا على القوم مع ذلك الرجل فسألهم في الأسير أن يهبوه له فما فعلوا فقال لهم فبيعوينه فقالوا أما هذا فنعم فلم يزل يساومهم حتى رضوا بما بذله لهم فدفع أبو خراش إليهم ابنه خراشا رهينة وأطلق أخاه عروة ومضيا حتى أخذ أبو خراش فكاك أخيه وعاد به إلى القوم حتى أعطاهم إياه وأخذ ابنه فبينما أبو خراش ذات يوم في بيته إذ جاءه عبد له فقال إن أخاك عروة جاءني وأخذ شاة من غنمك فذبحها ولطمني لما منعته منها فقال له دعه فلما كان بعد أيام عاد فقال له قد أخذ أخرى فذبحها فقال دعه فلما أمسى\nقال له إن أخاك اجتمع مع شرب من قومه فلما انتشى جاء إلينا وأخذ ناقة من إبلك لينحرها لهم فعاجله فوثب أبو خراش إليه فوجده قد أخذ الناقة لينحرها فطردها أبو خراش فوثب أخوه عروة إليه فلطم وجهه وأخذ الناقة فعقرها وانصرف أبو خراش فلما كان من غد لامه قومه وقالوا له بئست لعمر الله المكافأة كانت منك لأخيك رهن ابنه فيك وفداك بماله ففعلت به ما فعلت فجاء عروة يعتذر إليه فقال أبو خراش\n(لعلك نافعي يا عرو يوما ... إذا جاورت من تحت القبور)\n(أخذت خفارتي ولطمت عيني ... وكيف تثيب بالمن الكبير)\n(ويوم قد صبرت عليك نفسي ... لدى الأشهاد مرتدي الحرور)\n(إذا ما كان كس القوم روقا ... وجالت مقلتا الرجل البصير)\n(بما يممته وتركت بكرى ... وما أطعمت من لحم الجزور)\nال معنى قوله بكري أي بكر ولدي أي أولهم","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":2,"spl":"شعره في إنقاذ أسرى — يفتدي أخاه عروة بن مرة","tags":[],"loc":1866},
{"id":"b108-9","bab":"الجزء 10","sec":"كان بنو مرة عشرة — خبر أخيه زهير","page":"ج10 ص221 – ج10 ص222","text":"وقال الأصمعي وأبو عبيدة وأبو عمرو وابن الأعرابي كان بنو مرة عشرة أبو خراش وأبو جندب وعروة والأبح والأسود وأبو الأسود وعمرو وزهير وجناد وسفيان وكانوا جميعا شعراء دهاة سراعا لا يدركون عدوا فأما الأسود بن مرة فإنه كان على ماء من داءة وهو غلام شاب فوردت عليه إبل رئاب بن ناضرة بن المؤمل من بني لحيان ورئاب شيخ كبير فرمى الأسود ضرع ناقة من الإبل فعقرها فغضب رئاب فضربه بالسيف فقتله وكان أشدهم أبو جندب فعرف خبر أخيه فغضب غضبا شديدا وأسف فاجتمعت رجال هذيل إليه يكلمونه وقالوا خذ عقل أخيك واستبق ابن عمك فلم يزالوا به حتى قال نعم اجمعوا العقل فجاؤوه به في مرة واحدة فلما أراحوه عليه صمت فطال صمته فقالوا\nله أرحنا اقبضه منا فقال إني أريد أن أعتمر فاحبسوه حتى أرجع فإن هلكت فلأم ما أنتم هذه لغة هذيل يقولون إم بالكسر ولا يستعملون الضم وإن عشت فسوف ترون أمري وولى ذاهبا نحو الحرم فدعا عليه رجال من هذيل وقالوا اللهم لا ترده فخرج فقدم مكة فواعد كل خليع وفاتك في الحرم أن يأتوه يوم كذا وكذا فيصيب بهم قومه فخرج صادرا حتى أخذته الذبحة في جانب الحرم فمات قبل أن يرجع فكان ذلك خبره\nقالوا واما زهير بن مرة فخرج معتمرا قد جعل على جسده من لحاء الحرم حتى ورد ذات الأقير من نعمان فبينا هو يسقي إبلا له إذ ورد عليه قوم من ثمالة فقتلوه فله يقول أبو خراش وقد انبعث يغزو ثمالة ويغير عليهم حتى قتل منهم بأخيه أهل دارين أي حلتين من ثمالة\n(خذوا ذلكم بالصلح إني رأيتكم ... قتلتم زهيرا وهو مهد ومهمل)\nهد أي أهدى هديا للكعبة ومهمل قد أهمل إبله في مراعيها\n(قتلتم فتى لا يفجر الله عامدا ... ولا يجتويه جاره عام يمحل)\nلهم يقول أبو خراش\n(إني امرؤ أسال كيما أعلما ... من شر رهط يشهدون الموسما)\n(وجدتهم ثمالة بن أسلما ... )\nوكان أبو خراش إذا لقيهم في حروبه أوقع بهم ويقول\n(إليك أم ذبان ... ما ذاك من حلب الضان)\n(لكن مصاع الفتيان ... بكل لين حران)","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":3,"spl":"كان بنو مرة عشرة — خبر أخيه زهير","tags":["السفر والحج","الموت"],"loc":1867,"partial":1},
{"id":"b108-10","bab":"الجزء 10","sec":"خبر أخيه عروة","page":"ج10 ص223","text":"قال وأما عروة بن مرة وخراش بن أبي خراش فأخذهما بطنان من ثمالة يقال لهما بنو رزام وبنو بلال وكانوا متجاورين فخرج عروة بن مرة وابن أبي خراش أخيه مغيرين عليهم طمعا في أن يظفروا من أموالهم بشيء فظفر بهما الثماليون فأما بنو رزام فنهوا عن قتلهما وأبت بنو بلال إلا قتلهما حتى كاد يكون بينهم شر فألقى رجل من القوم ثوبه على خراش حين شغل القوم بقتل عروة ثم\nقال له انج وانحرف القوم بعد قتلهم عروة إلى الرجل وكانوا أسلموه إليه فقالوا أين خراش فقال أفلت مني فذهب فسعى القوم في أثره فأعجزهم فقال أبو خراش في ذلك يرثي أخاه عروة ويذكر خلاص ابنه\n(حمدت إلهي بعد عروة إذ نجا ... خراش وبعض الشر أهون من بعض)\n(فوالله لا أنسى قتيلا رزيته ... بجانب قوسى ما حييت على الأرض)\n(بلى إنها تعفو الكلوم وإنما ... نوكل بالأدنى وإن جل ما يمضي)\n(ولم أدر من ألقى عليه رداءه ... سوى أنه قد سل عن ماجد محض)\n(ولم يك مثلوج الفؤاد مهبلا ... أضاع الشباب في الربيلة والخفض)\n(ولكنه قد نازعته مجاوع ... على أنه ذو مرة صادق النهض)\nال ثم إن أبا خراش وأخاه عروة استنفرا حيا من هذيل يقال لهم بنو زليفة بن صبيح ليغزوا ثمالة بهم طالبين بثأر أخيهما فلما دنوا من ثمالة أصاب عروة ورد حمى وكانت به حمى الربع فجعل عروة يقول\n(أصبحت مورودا فقربوني ... إلى سواد الحي يدفنوني)\n(إن زهيرا وسطهم يدعوني ... رب المخاض واللقاح الجون)\nلبثوا إلى أن سكنت الحمى ثم بيتوا ثمالة فوجدوهم خلوفا ليس فيهم رجال فقتلوا من وجدوا من الرجال وساقوا النساء والذراري والأموال وجاء الصائح إلى ثمالة عشاء فلحقوهم وانهزم أبو خراش واصحابه وانقطعت بنوزليفة فنظر الأكنع الثمالي وكان مقطوع الأصبع إلى عروة فقال يا قوم ذلك والله عروة وأنا والله رام بنفسي عليه حتى يموت أحدنا وخرج يمعج نحو عروة فصلح عروة بأبي خراش أخيه أي\nأبا خراش هذا والله الأكنع وهو قاتلي فقال أبو خراش أمضه وقعد له على طريقه ومر به الأكنع مصمما على عروة وهو لا يعلم بموضع أبي خراش فوثب عليه أبو خراش فضربه على حبل عاتقه حتى بلغت الضربة سحره وانهزمت ثمالة ونجا أبو خراش وعروة وقال أبو خراش يرثي أخاه ومن قتلته ثمالة وكنانة من أهله وكان الأصمعي يفضلها\n(فقدت بني لبنى فلما فقدتهم ... صبرت فلم أقطع عليهم أباجلي)\nلأبجل عرق في الرجل\n(رماح من الخطي زرق نصالها ... حداد أعاليها شداد الأسافل)\n(فلهفي على عمرو بن مرة لهفة ... ولهفي على ميت بقوسى المعاقل)\n(حسان الوجوه طيب حجزاتهم ... كريم نثاهم غير لف معازل)\n(قتلت قتيلا لا يحالف غدرة ... ولا سبة لا زلت أسفل سافل)\n(وقد أمنوني واطمأنت نفوسهم ... ولم يعلموا كل الذي هو داخلي)\n(فمن كان يرجو الصلح مني فإنه ... كأحمر عاد أو كليب بن وائل)\n(أصيبت هذيل بابن لبنى وجدعت ... أنوفهم باللوذعي الحلاحل)\n(رأيت بني العلات لما تضافروا ... يحوزون سهمي دونهم بالشمائل)","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":4,"spl":"خبر أخيه عروة","tags":[],"loc":1868},
{"id":"b108-11","bab":"الجزء 10","sec":"أخبار سائر اخوته","page":"ج10 ص226","text":"قالوا وأما أبو الأسود فقتلته فهم بياتا تحت الليل وأما الأبح فكان شاعرا فأمسى بدار بعرعر من ضيم فذكر لسارية بن زنيم العبدي أحد بني عبد بن عدي ابن الديل فخرج بقوم من عشيرته يريده ومن معه فوجدوهم قد ظعنوا وكان بين بني عبد بن عدي بن الديل وبينهم حرب فقال الأبح في ذلك\n(لعمرك ساري بن أبي زنيم ... لأنت بعرعر الثأر المنيم)\n(تركت بني معاوية بن صخر ... وأنت بمربع وهم بضيم)\n(تساقيهم على رصف وظر ... كدابغة وقد حلم الأديم)\nصف وظر ماءان ومربع وضيم موضعان\n(فلم نتركهم قصدا ولكن ... فرقت من المصالت كالنجوم)\n(رأيتهم فوارس غير عزل ... إذا شرق المقاتل بالكلوم)\nأجابه سارية قال\n(لعلك يا أبح حسبت أني ... قتلت الأسود الحسن الكريما)\n(أخذتم عقله وتركتموه ... يسوق الظمي وسط بني تميما)\nيرهم بأخذ دية الأسود بن مرة أخيهم وأنهم لم يدركوا بثأره وبنو تميم من هذيل قالوا وأما جنادة وسفيان فماتا وقتل عمرو ولم يسم قاتله قالوا وأمهم جميعا لبنى إلا سفيان بن مرة فإن أمه أم عمرو القردية وكان أيسر القوم وأكثرهم مالا وقال أبو عمرو وغزا أبو خراش فهما فأصاب منهم عجوزا وأتى بها منزل قومه فدفعها إلى شيخ منهم وقال احتفظ بها حتى آتيك وانطلق لحاجته فأدخلته بيتا صغيرا وأغلقت عليه وانطلقت فجاء أبو خراش وقد ذهبت فقال\n(سدت عليه دولجا ثم يممت ... بني فالج بالليث أهل الخزائم)\nالدولج بيت صغير يكون للبهم والليث ماء لهم والخزائم البقر واحدتها خزومة\n(وقالت له دنخ مكانك إنني ... سألقاك إن وافيت أهل المواسم)\nقال دنخ الرجل ودمخ إذا أكب على وجهه ويديه وقال أبو عمرو دخلت أميمة امرأة عروة بن مرة على أبي خراش وهو يلاعب ابنه فقالت له يا أبا خراش تناسيت عروة وتركت الطلب بثأره ولهوت مع ابنك أما والله لو كنت المقتول ما غفل عنك ولطلب قاتلك حتى يقتله فبكى أبو خراش وأنشأ يقول\n(لعمري لقد راعت أميمة طلعتي ... وإن ثوائي عندها لقليل)\n(وقالت : أراه بعد عروة لاهيا ... وذلك رزء لو علمت جليل)\n(فلا تحسبي أني تناسيت فقده ... ولكن صبري يا أميم جميل)\n(ألم تعلمي أن قد تفرق قبلنا ... نديما صفاء مالك وعقيل)\n(أبى الصبر أنى لا يزال يهيجني ... مبيت لنا فيما خلا ومقيل)\n(وأني إذا ما الصبح آنست ضوءه ... يعاودني قطع علي ثقيل)\nال أبو عمرو فأما أبو جندب أخو أبي خراش فإنه كان جاور بني نفاثة ابن عدي بن الديل حينا من الدهر ثم إنهم هموا بأن يغدروا به وكانت له إبل كثيرة فيها أخوه جنادة فراح عليه أخوه جنادة ذات ليلة وإذا به كلوم فقال له أبو جندب حتى أتى جيرانه من بني نفاثة فقال لهم يا قوم ما هذا الجوار لقد كنت أرجو من جواركم خيرا من هذا أيتجاور أهل الأعراض بمثل هذا فقالوا أو لم يكن بنو لحيان يقتلوننا فو الله ما قرت دماؤنا وما زالت تغلي والله إنك للثأر المنيم فقال أما إنه لم يصب أخي إلا خير ولكنما هذه معاتبة لكم وفطن للذي يريد القوم من الغدر به وكان بأسفل دفاق فأصبحوا ظاعنين وتواعدوا ماء ظر فنفذ الرجال إلى الماء وأخروا\nالنساء لأن يتبعنهم إذا نزلوا واتخذوا لحياض للإبل فأمر أبو جندب أخاه جنادة وقال له اسرح مع نعم القوم ثم توقف وتأخر حتى تمر عليك النعم كلها وأنت في آخرها سارح بإبلك واتركها متفرقة في المرعى فإذا غابوا عنك فاجمع إبلك واطردها نحو أرضنا وموعدك نجد ألوذثنية في طريق بلاده\nوقال لامرأته أم زنباع وهي من بني كلب بن عوف اظعني وتمكثي حتى تخرج آخر ظعينة من النساء ثم توجهي فموعدك ثنية يدعان من جانب النخلة وأخذ أبو جندب دلوه وورده مع الرجال فاتخذ القوم الحياض واتخذ أبو جندب حوضا فملأه ماء ثم قعد عنده فمرت به إبل ثم إبل فكلما وردت إبل سأل عن إبله فيقولون قد بلغت تركناها بالضجن ثم قدمت النساء كلما قدمت ظعينة سألها عن أهله فيقولون بلغتك تركناها تظعن حتى إذا ورد آخر النعم أتخر الظعن\nقال والله لقد حبس أهلي حابس أبصر يا فلان حتى أستأنس أهلي وإبلي وطرح دلوه على الحوض ثم ولى حتى أدرك القوم بحيث وعدهم فقال أبو جندب في ذلك\n(أقول لأم زنباع أقيمي ... صدور العيس شطر بني تميم)\n(وغربت الدعاء وأين مني ... أناس بين مر وذي يدوم)\nربت الدعاء دعوت من بعيد\n(وحي بالمناقب قد حموها ... لدى قران حتى بطن ضيم)\n(وأحياء لدى سعد بن بكر ... بأملاح فظاهرة الأديم)","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":5,"spl":"أخبار سائر اخوته","tags":["الجواري والنساء"],"loc":1869},
{"id":"b108-12","bab":"الجزء 10","sec":"أخبار سائر اخوته","page":"ج10 ص226","text":"(أولئك معشري وهم أرومي ... وبعض القوم ليس بذي أروم)\n(هنالك لو دعوت أتاك منهم ... رجال مثل أرمية الحميم)\nلأرمية السحاب الشديد الوقع واحدها رمي والحميم مطر القيظ\n(أقل الله خيرهم ألما ... يدعهم بعض شرهم القديم)\n(ألما يسلم الجيران منهم ... وقد سال الفجاج من الغميم)\n(غداة كأن جناد بن لبنى ... به نضخ العبير من الكلوم)\n(دعى حولي نفاثة ثم قالوا ... لعلك لست بالثأر المنيم)\nالمنيم الذي إذا أدرك استراح أهله وناموا\n(نعوا من قتلت لحيان منهم ... ومن يغتر بالحرب القروم)\nالوا جميعا وكان أبو جندب ذا شر وبأس وكان قومه يسمونه المشؤوم فاشتكى شكوى شديدة وكان له جار من خزاعة يقال له حاطم فوقعت به بنو لحيان فقتلوه قبل أن يستبل أبو جندب من مرضه واستاقوا أمواله وقتلوا امرأته وقد كان أبو جندب كلم قومه فجمعوا لجاره غنما فلما أفاق أبو جندب من مرضه خرج من أهله حتى قدم مكة ثم جاء يمشي\nحتى استلم الركن وقد شق ثوبه عن استه فعرف الناس أنه يريد شرا فجعل يصيح ويقول\n(إني امرؤ أبكي على جاريه ... أبكي على الكعبي والكعبيه)\n(ولو هلكت بكيا عليه ... كانا مكان الثوب من حقويه)\nلما فرغ من طوافه وقضى حاجته من مكة خرج في الخلعاء من بكر وخزاعة فاستجاشهم على بني لحيان فقتل منهم قتلى وسبى من نسائهم وذراريهم سبايا وقال في ذلك\n(لقد أمسى بنو لحيان مني ... بحمد الله في خزي مبين)\n(تركتهم على الركبات صعرا ... يشيبون الذوائب بالأنين)","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":6,"spl":"أخبار سائر اخوته","tags":["اللهو والمزاح","السفر والحج"],"loc":1870},
{"id":"b108-13","bab":"الجزء 10","sec":"يشكو إلى عمر شوقه إلى ابنه","page":"ج10 ص231","text":"أخبرني هاشم بن محمد الخزاعي قال حدثني عبد الرحمن ابن أخي الأصمعي قال حدثني عمي قال هاجر خراش بن أبي خراش الهذلي في أيام عمر بن الخطاب رضي الله عنه وغزا مع المسلمين فأوغل في أرض العدو فقدم أبو خراش المدينة فجلس بين يدي عمر وشكا إليه شوقه إلى ابنه وأنه رجل قد انقرض أهله وقتل إخوته ولم يبق له ناصر ولا معين غير ابنه خراش وقد غزا وتركه وأنشأ يقول\n(ألا من مبلغ عني خراشا ... وقد يأتيك بالنبأ البعيد)\n(وقد يأتيك بالأخبار من لا ... تجهز بالحذاء ولا تزيد)\nزيد وتزود واحد من الزاد\n(يناديه ليغبقه كليب ... ولا يأتي لقد سفه الوليد)\n(فرد إناءه لا شيء فيه ... كأن دموع عينيه الفريد)\n(وأصبح دون عابقه وأمسى ... جبال من حرار الشام سود)\n(ألا فاعلم خراش بأن خير المهاجر ... بعد هجرته زهيد)\n(رأيتك وابتغاء البردوني ... كمحصور اللبان ولا يصيد)\nال فكتب عمر رضي الله عنه بأن يقبل خراش إلى أبيه وألا يغزو من كان له أب شيخ إلا بعد أن يأذن له أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا الأصمعي وأخبرني حبيب بن نصر قال حدثنا عبد الله بن أبي سعد قال حدثنا علي بن الصباح عن ابن الكلبي عن أبيه وأخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ قال أبو عبيدة وأخبرني أيضا هاشم قال حدثنا عبد الرحمن ابن أخي الأصمعي\nعن عمه وذكره أبو سعيد السكري في رواية الأخفش عنه عن أصحابه قالوا جميعا أسلم أبو خراش فحسن إسلامه ثم أتاه نفر من أهل اليمن قدموا حجاجا فنزلوا بأبي خراش والماء منهم غير بعيد فقال يا بني عمي ما أمسى عندنا ماء ولكن هذه شاة وبرمة وقربة فردوا الماء وكلوا شاتكم ثم دعوا برمتنا وقربتنا على الماء حتى نأخذها قالوا والله ما نحن بسائرين في لبلتنا هذه وما نحن ببارحين حيث أمسينا فلما رأى ذلك أبو خراش أخذ قربته وسعى نحو الماء تحت الليل حتى استقى ثم أقبل صادرا فنهشته حية قبل أن يصل إليهم فأقبل مسرعا حتى أعطاهم الماء\nوقال اطبخوا شاتكم وكلوا ولم يعلمهم بما أصابه فباتوا على شاتهم يأكلون حتى أصبحوا وأصبح أبو خراش في الموت فلم يبرحوا حتى دفنوه وقال وهو يعالج الموت\n(لعمرك والمنايا غالبات ... على الإنسان تطلع كل نجد)\n(لقد أهلكت حية بطن أنف ... على الأصحاب ساقا ذات فقد)\nوقال أيضا\n(لقد أهلكت حية بطن أنف ... على الأصحاب ساقا ذات فضل)\n(فما تركت عدوا بين بصرى ... إلى صنعاء يطلبه بذحل)\nقال فبلغ عمر بن الخطاب رضي الله عنه خبره فغضب غضبا شديدا وقال لولا أن تكون سبة لأمرت ألا يضاف يمان أبدا ولكتبت بذلك إلى الآفاق إن الرجل ليضيف أحدهم فيبذل مجهوده فيسخطه ولا يقبله منه ويطالبه بما لا يقدر عليه كأنه يطالبه بدين أو يتعنته ليفضحه فهو يكلفه التكاليف حتى أهلك ذلك من فعلهم رجلا مسلما وقتله ثم كتب إلى عامله باليمن بأن يأخذ النفر الذين نزلوا بأبي خراش فيغرمهم ديته ويؤدبهم بعد ذلك بعقوبة تمسهم جزاء لأعمالهم\n(تهيم بها لا الدهر فان ولا المنى ... سواها ولا ينسيك نأي ولا شغل)\n(كبيضة أدحي بميث خميلة ... يحففها جون بجؤجؤه صعل)\nلشعر لعبد الرحمن بن مسافع بن دارة والغناء لابن محرز ثقيل أول بالوسطى عن ابن المكي","topic":"ذكر أبي خراش الهذلي وأخباره","topicNo":108,"sp":7,"spl":"يشكو إلى عمر شوقه إلى ابنه","tags":["اللهو والمزاح"],"song":1,"loc":1871},
{"id":"b109-2","bab":"الجزء 10","sec":"أخبار ابن دارة ونسبه — هجا بني أسد وحرض عكلا عليهم","page":"ج10 ص234 – ج10 ص235","text":"هو عبد الرحمن بن مسافع بن دارة وقيل بل هو عبد الرحمن بن ربعي بن مسافع بن دارة وأخوه مسافع بن دارة وكلاهما شاعر وفي شعريهماجميعا غناء يذكرها هنا وأخوهما سالم بن مسافع بن دارة شاعر أيضا وفي بعض شعره غناء يذكر بعد أخبار هذين فأما سالم فمخضرم قد أدرك الجاهلية والإسلام وأما هذان فمن شعراء الإسلام ودارة لقب غلب على جدهم ومسافع أبوهم وهو ابن شريح بن يربوع الملقب بدارة بن كعب بن عدي بن جشم بن عوف بن بهثة بن عبد الله بن غطفان بن سعد بن قيس عيلان بن مضر وهذا الشعر يقوله عبد الرحمن في حبس السمهري العكلي اللص وقتله وكان نديما له وأخا\nأخبرني بخبره هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال لما أخذ السمهري العكلي وحبس وقتل وكانت بنو أسد أخذته وبعثت به إلى السلطان وكان نديما لعبد الرحمن بن مسافع بن دارة فقتل بعد طول حبس فقال عبد الرحمن بن مسافع يهجو بني أسد ويحرض عليهم عكلا\n\n(إن يمس بالعينين سقم فقد أتى ... لعينيك من طول البكاء على جمل)\n(تهيم بها لا الدهر فان ولا المنى ... سواها ولا تسلى بنأي ولا شغل)\n(كبيضة أدحي بميث خميلة ... يحففها جون بجؤجؤه الصعل)\n(وما الشمس تبدو يوم غيم فأشرقت ... على الشامة العنقاء فالنير فالذبل)\n(بدا حاجب منها وضنت بحاجب ... بأحسن منها يوم زالت على الحمل)\n(يقولون إزل حب جمل وقربها ... وقد كذبوا ما في المودة من إزل)\n(إذا شحطت عني وجدت حرارة ... على كبدي كادت بها كمدا تغلي)\n(ولم أر محزونين أجمل لوعة ... على نائبات الدهر مني ومن جمل)\n(كلانا يذود النفس وهي حزينة ... ويضمر وجدا كالنوافذ بالنبل)\n(وإني لمبلي اليأس من حب غيرها ... فأما على جمل فإني لا أبلي)\n(وإن شفاء النفس لو تسعف المنى ... ذوات الثنايا الغر والحدق النجل)\n(أولئك إن يمنعن فالمنع شيمة ... لهن وإن يعطين يحمدن بالبذل)\n(سأمسك بالوصل الذي كان بيننا ... وهل ترك الواشون والنأي من وصل)\n(ألا سقياني قهوة فارسية ... من الأول المختوم ليست من الفضل)\n(تنسي ذوي الأحلام واللب حلمهم ... إذا أزبدت في دنها زبد الفحل)\n(ويا راكبا إما عرضت فبلغن ... على نأيهم مني القبائل من عكل)\n(بأن الذي أمست تجمجم فقعس ... إسار بلا أسر وقتل بلا قتل)\n(وكيف تنام الليل عكل ولم تنل ... رضى قود بالسمهري ولا عقل)\n(فلا صلح حتى تنحط الخيل في القنا ... وتوقد نار الحرب بالحطب الجزل)\n(وجرد تعادى بالكماة كأنها ... تلاحظ من غيظ بأعينها القبل)\n(عليها رجال جالدوا يوم منعج ... ذوي التاج ضرابو الملوك على الوهل)\n(بضرب يزيل الهام عن مستقره ... وطعن كأفواه المفرجة الهدل)\n(علام تمشي فقعس بدمائكم ... وما هي بالفرغ المنيف ولا الأصل)\n(وكنا حسبنا فقعسا قبل هذه ... أذل على وقع الهوان من النعل)\n(فقد نظرت نحو السماء وسلمت ... على الناس واعتاضت بخصب من المحل)\n(رمى الله في أكبادكم أن نجت بها ... شعاب القنان من ضعيف ومن وغل)\n(وإن أنتم تثأروا بأخيكم ... فكونوا نساء للخلوق وللكحل)\n(وبيعوا الردينيات بالحلي واقعدوا ... على الذل وابتاعوا المغازل بالنبل)\n(ألا حبذا من عنده القلب في كبل ... ومن حبه داء وخبل من الخبل)\n(ومن هو لا ينسى ومن كل قوله ... لدينا كطعم الراح أو كجنى النحل)\n(ومن إن نأى لم يحدث النأي بغضه ... ومن إن دنا في الدار أرصد بالبذل)\nوأما خبر السمهري ومقتله فإن علي بن سليمان الأخفش أخبرني به قال حدثنا أبو سعيد السكري قال حدثنا محمد بن حبيب عن أبي عمرو الشيباني قال","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":0,"spl":"أخبار ابن دارة ونسبه — هجا بني أسد وحرض عكلا عليهم","tags":["اللهو والمزاح"],"song":1,"loc":1872},
{"id":"b109-3","bab":"الجزء 10","sec":"خبر مصرع السمهري","page":"ج10 ص238","text":"لقي السمهري بن بشر بن أقيش بن مالك بن الحارث بن أقيش العكلي ويكنى أبا الديل هو وبهدل ومروان بن قرفة الطائيان عون بن جعدة بن هبيرة ابن أبي وهب بن عمرو بن عائذ بن عمران بن مخزوم بن يقظة بن مرة بن كعب بن لؤي بن غالب ومعه خاله أحد بني حارثة بن لأم من طيء بالثعلبية وهو يريد الحج من الكوفة أو يريد المدينة وزعم آخرون أنهم لقوه بين نخل والمدينة فقالوا له العراضة أي مر لنا بشيء فقال يا غلام جفن لهم فقالوا لا والله ما الطعام نريد فقال عرضهم فقالوا ولا ذلك نريد فارتاب بهم فأخذ السيف فشد عليهم وهو صائم وكان بهدل لا\nيسقط له سهم فرمى عونا فأقصده فلما قتلوه ندموا فهربوا ولم يأخذوا إبله فتفرقت إبله ونجا خاله الطائي إما عرفوه فكفوا عن قتله وإما هرب ولم يعرف القتلة فوجد بعض إبله في يدي شافع بن واتر الأسدي وبلغ عبد الملك بن مروان الخبر فكتب إلى الحجاج بن يوسف وهو عامله على العراق وإلى هشام بن إسماعيل وهو عامله على المدينة والى عامل اليمامة أن يطلبوا قتله عون ويبالغوا في ذلك وأن يأخذوا السعادة به أشد أخذ ويجعلوا لمن دل عليهم جعله وانشام السمهري في بلاد غطفان ما شاء الله ثم مر بنخل فقالت عجوز من بني فزارة أظن والله هذا العكلي الذي قتل عونا فوثبوا عليه فأخذوه ومر أيوب بن سلمة المخزومي بهم فقالت له بنو فزارة هذا العكلي قاتل عون ابن عمك فأخذه منهم فأتى به هشام ابن إسماعيل المخزومي عامل عبد الملك على المدينة فجحد وأبى أن يقر فرفعه إلى السجن فحبسه وزعم آخرون أن بني عذرة أخذوه فلما عرفت إبل عون في يدي شافع ابن واتر اتهموه بقتله فأخذوه وقالوا أنت قرفتنا قتلت عونا وحبسوه بصل ماء لبني أسد وجحد وقد كان عرف من قتله إما أن يكون كان معهم فورى عنهم وبرأ نفسه وإما أن يكون أودعوها إياه أو باعوها منه فقال شافع\n(فإن سركم أن تعلموا أين ثأركم ... فسلمى معان وابن قرفة ظالم)\n(وفي السجن عكلي شريك لبهدل ... فولوا ذباب السيف من هو حازم)\n(فوالله ما كنا جناة ولا بنا ... تأوب عونا حتفه وهو صائم)\nعرفوا من قتله فألحوا على بهدل في الطلب وضيقوا على السمهري في القيود والسجن وجحد فلما كان ذلك من إلحاحهم على السمهري أيقنت نفسه أنه غير ناج فجعل يلتمس الخروج من السجن فلما كان يوم الجمعة والإمام يخطب وقد شغل الناس بالصلاة فك إحدى حلفتي قيده ورمى بنفسه من فوق السجن والناس في صلاتهم فقصد نحو الحرة فولج غارا من الحرة وانصرف الإمام من الصلاة فخاف أهل المدينة عامتهم أتباعه وغلقوا أبوابهم\nوقال لهم الأمير اتبعوه فقالوا وكيف نتبعه وحدنا فقال لهم أنتم ألفا رجل فكيف تكونون وحدكم فقالوا أرسل معنا الأبليين وهم حرس وأعوان من أهل الأبلة فأعجزهم الطلب فلما أمسى كسر الحلقة الأخرى ثم همس ليلته طلقا فأصبح وقد قطع أرضا بعيدة فبينا هو يمضي إذ نعب غراب عن شماله فتطير فإذا الغراب على شجرة بان ينشنش ريشه ويلقيه فاعتاف شيئا في نفسه فمضى وفيها ما فيها فإذا هو قد لقي راعيا في وجهه ذلك فسأله من أنت\nقال رجل من لهب من أزد شنوءة أنتجع أهلي فقال له هل عندك شيء من زجر قومك فقال إني لآنس من ذلك شيئا أي لأبصر فقص عليه حاله غير أنه ورى\nالذنب على غيره والعيافة وخبره عن الغراب والشجرة فقال اللهبي هذا الذي فعل ما فعل ورأى الغراب على البانة يطرح ريشه سيصلب فقال السمهري بفيك الحجر فقال اللهبي بل بفيك الحجر استخبرتني فأخبرتك ثم تغضب ثم مضى حتى اغترز في بلاد قضاعة وترك بلاد غطفان","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":1,"spl":"خبر مصرع السمهري","tags":["السفر والحج"],"loc":1873},
{"id":"b109-4","bab":"الجزء 10","sec":"خبر مصرع السمهري","page":"ج10 ص238","text":"وذكر بعض الرواة أنه توقف يومه وليلته فيما يعمله وهل يعود من حيث جاء ثم سار حتى أتى أرض عذرة بن سعد يستجير القوم فجاء إلى القوم متنكرا ويستحلب الرعيان اللبن فيحلبون له ولقيه عبد الله الأحدب السعدي أحد بني مخزوم من بني عبد شمس وكان أشد منه وألص فجنى جناية فطلب فترك بلاد تميم ولحق ببلاد قضاعة وهو على نجيبة لا تساير فبينا السمهري يماشي راعيا لبني عذرة ويحدثه عن خيار إبلهم ويسأله السمهري عن ذلك وإنما يسأله عن أنجاههن ليركبها فيهرب بها لئلا يفارق الأحدب أشار له إلى ناقة فقال السمهري هذه خير من التي تفضلها هذه لا تجارى فتحين الغفلة فلما غفل وثب عليها ثم صاح بها فخرجت تطير به وذلك في آخر الليل فلما أصبحوا فقدوها وفقدوه فطلبوه في الأثر وخرجا حتى إذا كان حجر عن يسارهما وهو واد في جبل أو شبه الثقب فيه استقبلتهما سعة هي أوسع من الطريق فظنا أن الطريق فيها فسارا مليا فيها ولا نجم يأتمان به فلما عرفا أنهما حائدان والتفت عليهما الجبال أمامهما وجد الطلب إثر بعيريهما ورأوه وقد سلك الثقب في غير طريق عرفوا أنه سيرجع فقعدوا له بفم الثقب ثم كرا راجعين وجاءت الناقة وعلى رأسها مثل الكوكب من لغامها فلما أبصر القوم هم أن يعقر ناقتهم فقال له الأحدب ما هذا جزاؤها فنزل ونزل الأحدب فقاتلهما القوم حتى كادوا\nيغشون السمهري فهتف بالأحدب فطرد عنه القوم حتى توقلا في الجبل وفي ذلك يقول السمهري يعتذر من ضلاله","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":2,"spl":"خبر مصرع السمهري","tags":["الوصف والطبيعة"],"loc":1874},
{"id":"b109-5","bab":"الجزء 10","sec":"متفرقات من شعر السمهري","page":"ج10 ص242","text":"(وما كنت محيارا ولا فزع السرى ... ولكن حذا حجر بغير دليل)\nوقال الأحدب في ذلك\n(لما دعاني السمهري أجبته ... بأبيض من ماء الحديد صقيل)\n(وما كنت ما اشتدت على السيف قبضتي ... لأسلم من حب الحياة زميلي)\nقال السمهري أيضا\n(نجوت ونفسي عند ليلى رهينة ... وقد غمني داج من الليل دامس)\n(وغامست عن نفسي بأخلق مقصل ... ولا خير في نفس امرئ لاتغامس)\n(ولو أن ليلى أبصرتني غدوة ... ومطواي والصف الذين أمارس)\n(إذا لبكت ليلى علي وأعولت ... وما نالت الثوب الذي أنا لابس)\nرجع إلى صحراء منعج وهي إلى جنب أضاخ والحلة قريب منها وفيها منازل عكل فكان يتردد ولا يقرب الحلة وقد كان أكثر الجعل فيه فمر بابني فائد بن حبيب من بني أسد ثم من بني فقعس فقال أجيرا متنكرا فحلبا له فشرب ومضى لا يعرفانه وذهبا ثم لبث السمهري ساعة وكر راجعا فتحدث إلى أخت ابني فائد فوجداه منبطحا على بطنه يحدثها\nفنظر أحدهما إلى ساقه مكدحة وإذا كدوح طرية فأخبر أخاه بذلك فنظر فرأى ما أخبره أخوه فارتابا به فقال أحدهما هذا والله السمهري الذي جعل فيه ما جعل فاتفقا على مضابرته فوثبا عليه فقعد أحدهما على ظهره وأخذ الآخر برجليه فوثب السمهري فألقى الذي على ظهره\nوقال أتلعبان وقد ضبط رأس الذي كان على ظهره تحت إبطه وعالجه الآخر فجعل رأسه تحت إبطه أيضا وجعلا يعالجانه فناديا أختهما أن تعينهما فقالت ألي الشرك في جعلكما قالا نعم فجاءت بجرير فجعلته في عنقه بأنشوطة ثم جذبته وهو مشغول بالرجلين يمنعهما فلما استحكمت العقدة وراحت من علابيه خلى عنهما وشد أحدهما فجاء بصرار فألقاه في رجله وهو يداور الآخر والأخرى تخنقه فخر لوجهه فربطاه ثم انطلقا به إلى عثمان بن حيان المري وهو في إمارته على المدينة فأخذا ما جعل لأخذه فكتب فيه إلى الخليفة فكتب أن ادفعه إلى ابن أخي عون عدي فدفع إليه فقال السمهري أتقتلني وأنت لا تدري أقاتل عمك أنا أم لا ادن أخبرك فأراد الدنو منه فنودي إياك والكلب وإنما أراد أن يقطع أنفه فقتله بعمه ولما حبسه ابن حيان في السجن تذكر زجر اللهبي وصدقة فقال\n(ألا أيها البيت الذي أنا هاجره ... فلا البيت منسي ولا أنا زائره)\n(ألا طرقت ليلى وساقي رهينة ... بأشهب مشدود علي مسامره)\n(فإن أنج يا ليلى فرب فتى نجا ... وإن تكن الأخرى فشيء أحاذره)\n(وما أصدق الطير التي برحت لنا ... وما أعيف اللهبي لا عز ناصره)\n(رأيت غرابا ساقطا فوق بانة ... ينشنش أعلى ريشه ويطايره)\n(فقال غراب باغتراب من النوى ... وبان ببين من حبيب تحاذره)\n(فكان اغتراب بالغراب ونية ... وبالبان بين بين لك طائره)\nقال السمهري في الحبس يحرض أخاه مالكا على ابني فائد\n(فمن مبلغ عني خليلي مالكا ... رسالة مشدود الوثاق غريب)\n(ومن مبلغ حزما وتيما ومالكا ... وأرباب حامي الحفر رهط شبيب)\n(ليبكوا التي قالت بصحراء منعج ... لي الشرك يا بني فائد بن حبيب)\n(أتضرب في لحمي بسهم ولم يكن ... لها في سهام المسلمين نصيب)\nقال السمهري يرقق بني أسد\n(تمنت سليمى أن أقيل بأرضها ... وأنى لسلمى ويبها ما تمنت)\n(ألا ليت شعري هل أزورن ساجرا ... وقد رويت ماء الغوادي وعلت)\n(بني أسد هل فيكم من هوادة ... فتغفر إن كانت بي النعل زلت)\nبنو تميم تزعم أن البيت لمرة بن محكان السعدي\nوقال السمهري في الحبس يذم قومه\n(لقد جمع الحداد بين عصابة ... تسائل في الأقياد ماذا ذنوبها)\n(بمنزلة أما اللئيم فشامت ... بها وكرام القوم باد شحوبها)\n(إذا حرسي قعقع الباب أرعدت ... فرائص أقوام وطارت قلوبها)\n(ألا ليتني من غير عكل قبيلتي ... ولم أدر ما شبان عكل وشيبها)\n(قبيلة من لا يقرع الباب وفدها ... لخير ولا يهدي الصواب خطيبها)\n(نرى الباب لا نسطيع شيئا وراءه ... كأنا قني أسلمتها كعوبها)\n(وإن تك عكل سرها ما أصابني ... فقد كنت مصبوبا على ما يريبها)\nقال السمهري أيضا في الحبس\n(ألا حي ليلى إذ ألم لمامها ... وكان مع القوم الأعادي كلامها)\n(تعلل بليلى إنما أنت هامة ... من الغد يدنو كل يوم حمامها)\n(وبادر بليلى أوجه الركب إنهم ... متى يرجعوا يحرم عليك كلامها)\n(وكيف ترجيها وقد حيل دونها ... وأقسم أقوام مخوف قسامها)\n(لأجتنبنها أو ليبتدرنني ... ببيض عليها الأثر فعم كلامها)\n(لقد طرقت ليلى ورجلي رهينة ... فما راعني في السجن إلا لمامها)","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":3,"spl":"متفرقات من شعر السمهري","tags":["الحب والغزل"],"loc":1875},
{"id":"b109-6","bab":"الجزء 10","sec":"متفرقات من شعر السمهري","page":"ج10 ص242","text":"(فلما انتبهت للخيال الذي سرى ... إذا الأرض قفر قد علاها قتامها)\n(فإلا تكن ليلى طوتك فإنه ... شبيه بليلى حسنها وقوامها)\n(ألا ليتنا نحيا جميعا بغبطة ... وتبلى عظامي حين تبلى عظامها)\nقال أيضا\n(ألا طرقت ليلى وساقي رهينة ... بأسمر مشدود علي ثقيل)\n(فما البين يا سلمى بأن تشحط النوى ... ولكن بينا ما يريد عقيل)\n(فإن أنج منها أنج من ذي عظيمة ... وإن تكن الأخرى فتلك سبيل)\nقال أيضا وهو طريد\n(فلا تيأسا من رحمة الله وانظرا ... بوادي جبونا أن تهب شمال)\n(ولا تيأسا أن ترزقا أريحية ... كعين المها أعناقهن طوال)\n(من الحارثيين الذين دماؤهم ... حرام وأما مالهم فحلال)\nقال أيضا\n(ألم تر أني وابن أبيض قد جفت ... بنا الأرض إلا أن نؤم الفيافيا)\n(طريدين من حيين شتى أشدنا ... مخافتنا حتى نخلنا التصافيا)\n(وما لمته في أمر حزم ونجدة ... ولا لامني في مرتي واحتياليا)\n(وقلت له إذ حل يسقي ويستقي ... وقد كان ضوء الصبح لليل حاديا)\n(لعمري لقد لاقت ركابك مشربا ... لئن هي لم تضبح عليهن عاليا)\nأخذت طيء ببهدل ومروان أخيه أشد الأخذ وحبسوا فقالوا إن حبسنا لم نقدر عليهما ونحن محبوسون ولكن خلوا عنا حتى نتجسس عنهما فنأتيكم بهما وكانا تأبدا مع الوحش يرميان الصيد فهو رزقهما ولما طال ذلك على مروان هبط إلى راع فتحدث إليه فسقاه وبسطه حتى اطمأن إليه ولم يشعره أنه يعرفه فجعل يأتيه بين الأيام فلا ينكره فانطلق الراعي فأخبره باختلافه إليه فجاء معه الطلب وأكمنهم حتى إذا جاء مروان إلى الراعي كما كان يفعل سقاه وحدثه فلم يشعر حتى أطافوا به فأخذوه وأتوا به عثمان بن حيان أيضا عامل الوليد بن عبد الملك على المدينة فأعطى الذي دل عليه جعله وقتله","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":4,"spl":"متفرقات من شعر السمهري — نهاية بهدل","tags":["السفر والحج","الوصف والطبيعة"],"loc":1876},
{"id":"b109-7","bab":"الجزء 10","sec":"نهاية بهدل","page":"ج10 ص247","text":"وأما بهدل فكان يأوي إلى هضبة سلمى فبلغ ذلك سيدا من سلمى من طيء فقال قد أخيفت طيء وشردت من السهل من أجل هذا الفاسق الهارب فجاء حتى حل بأهله أسفل تلك الهضبة ومعه أهلات من قومه فقال لهم إنكم بعيني الخبيث فإذا كان النهار فليخرج الرجال من البيوت وليخلوا النساء فإنه إذا رأى ذلك انحدر إلى القباب وطلب الحاجة والعل فكانوا يخلون الرجال نهارا فإذا أظلموا ثابوا إلى رحالهم أياما فظن بهدل أنهم يفعلون ذلك لشغل يأتيهم فانحدر إلى قبة السيد وقد أمر النساء إن\nانحدر إليكن رجل فإنه ابن عمكن فأطعمنه وادهن رأسه وفي قبة السيد ابنتان له فسألهما من أنتما فأخبرتاه وأطعمتاه ثم انصرف فلما راح أبوهما أخبرتاه فقال أحسنتما إلى ابن عمكما فجعل ينحدر اليهما حتى اطمأن وغسلتا رأسه وفلتاه ودهنتاه فقال الشيخ لابنتيه أفلياه ولا تدهناه إذا أتاكما هذه المرة واعقدا خصل لمته إذا نعس رويدا بخمل القطيفة ثم إذا شددنا عليه فاقلبا القطيفة على وجهه وخذا أنتما بشعره من ورائه فمدا به إليكما ففعلتا واجتمع له أصحابه فكروا إلى رحالهم قبل الوقت الذي كانوا يأتونها وشدوا عليه فربطوه فدفعوه إلى عثمان بن حيان فقتله فقالت بنت بهدل ترثيه\n(فيا ضيعة الفتيان إذ يعتلونه ... ببطن الشرى مثل الفنيق المسدم)\n(دعا دعوة لما أتى أرض مالك ... ومن لا يجب عند الحفيظة يسلم)\n(أما كان في قيس من ابن حفيظة ... من القوم طلاب الترات غشمشم)\n(فيقتل جبرا بامرئ لم يكن به ... بواء ولكن لا تكايل بالدم)\nكان دعا يا لمالك لينتزعوه فلم يجبه أحد","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":4,"spl":"متفرقات من شعر السمهري — نهاية بهدل","tags":["الجواري والنساء"],"loc":1877},
{"id":"b109-8","bab":"الجزء 10","sec":"تساجل هو والكميت بن معروف","page":"ج10 ص248","text":"قال ولما قال عبد الرحمن بن دارة ابن عم سالم بن دارة هذه القصيدة\nيحض عكلا على بني فقعس اعترض الكميت بن معروف الففعسي فعيره بقتل سالم حين قتله زميل الفزاري فقال قوله\n(فلا تكثروا فيه الضجاج فإنه ... محا السيف ما قال ابن دارة أجمعا)\nفقال عبد الرحمن بن دارة\n(فيا راكبا إما عرضت فبلغن ... مغلغلة عني القبائل من عكل)\n(جلت حمما عنها القصاف وما جلت ... قشير وفي الشدات والحرب ما يجلي)\n(فإن يك باع الفقعسي دماءهم ... بوك بوكس فقد كانت دماؤكم تغلي)\n(وكيف تنام الليل عكل ولم يكن ... لها قود بالسمهري ولا عقل)\n(رمى الله في أكبادهم إن نجت بها ... حروف القنان من ذليل ومن وغل)\n(وكنا حسبنا فقعسا قبل هذه ... أذل على طول الهوان من النعل)\n(فإن انتم لم تثأروا بأخيكم ... فكونوا بغايا للخلوق وللكحل)\n(وبيعوا الردينيات بالحلي واقعدوا ... على الوتر وابتاعوا المغازل بالنبل)\n(فإن الذي كانت تجمجم فقعس ... قتيل بلا قتلى وتبل بلا تبل)\n(فلا سلم حتى تنحط الخيل بالقنا ... وتوقد نار الحرب بالحطب الجزل)\nلما بلغ قوله مالكا أخا السمهري بخراسان انحط من خراسان حتى قدم بلاد عكل فاستجاش نفرا من قومه فعلقوا في أرض بني أسد يطلبون الغرة فوجدوا بثادق رجلا معه امرأة من فقعس فقتلوه وحزوا رأسه\nوذهبوا بالرأس وتركوا جسده كما قتلوها أيضا وذكر لي أن الرجل ابن سعدة والمرأة التي كانت معه هي سعدة أمه فقال عبد الرحمن في ذلك\n(ما لقتيل فقعس لا رأس له ... هلا سألت فقعسا من جدله)\n(لا يتبعن فقعسي جمله ... فردا إذا ما الفقعسي أعمله)\n(لا يلقين قاتلا فيقتله ... بسيفه قد سمه وصقله)\nوقال عبد الرحمن أيضا\n(لما تمالى القوم في رأد الضحى ... نظرا وقد لمع السراب فجالا)\n(نظر ابن سعدة نظرة ويلا لها ... كانت لصحبك والمطي خبالا)\n(لمحا رأى من فوق طود يافع ... بعض العداة وجنة وظلالا)\n(عيرتني طلب الحمول وقد أرى ... لم آتهن مكففا بطالا)\n(فانظر لنفسك يا بن سعدة هل ترى ... ضبعا تجر بثادق أوصالا)\n(أوصال سعدة والكميت وإنما ... كان الكميت على الكميت عيالا)\nقال عبد الرحمن في ذلك\n(أصبحتم ثكلى لئاما وأصبحت ... شياطين عكل قد عراهن فقعس)\n(قضى مالك ما قد قضى ثم قلصت ... به في سواد الليل وجناء عرمس)\n(فأضحت بأعلى ثادق وكأنها ... محالة غرب تستمر وتمرس)","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":5,"spl":"تساجل هو والكميت بن معروف — مقتله","tags":["الجواري والنساء"],"loc":1878},
{"id":"b109-9","bab":"الجزء 10","sec":"مقتله","page":"ج10 ص251","text":"وحدثني علي بن سليمان الأخفش أن بني أسد ظفرت بعبد الرحمن بن دارة بالجزيرة بعدما أكثر من سبهم وهجائهم وتآمروا في قتله فقال بعضهم لا تقتلوه ولتأخذوا عليه أن يمدحنا ونحسن إليه فيمحو بمدحه ما سلف من هجائه فعزموا على ذلك ثم إن رجلا منهم كان قد عضه بهجائه اغتفله فضربه بسيفه فقتله وقال في ذلك\n(قتل ابن دارة بالجزيرة سبنا ... وزعمت أن سبابنا لا يقتل)\nال علي بن سليمان وقد روي أن البيت المتقدم\n(فلا تكثروا فيه الضجاج فإنه ... محا السيف ما قال ابن دارة أجمعا)\nهذا الشاعر الذي قتل ابن دارة وهو من بني أسد وهكذا ذكر السكري\n(كلانا يرى الجوزاء يا جمل إذ بدت ... ونجم الثريا والمزار بعيد)\n(فكيف بكم يا جمل أهلا ودونكم ... بحور يقمصن السفين وبيد)\n(إذا قلت قد حان القفول يصدنا ... سليمان عن أهوائنا وسعيد)\nالشعر لمسعود بن خرشة المازني والغناء لبحر خفيف ثقيل بالوسطى عن الهشامي","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":5,"spl":"تساجل هو والكميت بن معروف — مقتله","tags":[],"song":1,"loc":1879},
{"id":"b109-10","bab":"الجزء 10","sec":"أخبار مسعود بن خرشة","page":"ج10 ص253","text":"حنينه إلى جارية عشقها مسعود بن خرشة أحد بني حرقوص بن مازن بن مالك بن عمرو بن تميم شاعر إسلامي بدوي من لصوص بني تميم قال أبو عمرو وكان مسعود بن خرشة يهوى امرأة من قومه من بني مازن يقال لها جمل بنت شراحيل أخت تمام بن شراحيل المازني الشاعر فانتجع قومها ونأوا عن بلادهم فقال مسعود\n(كلانا يرى الجوازء يا جمل إذ بدت ... ونجم الثريا والمزار بعيد)\n(فيكف بكم يا جمل أهلا ودونكم ... بحور يقمصن السفين وبيد)\n(إذا قلت قد حان القفول يصدنا ... سليمان عن أهوائنا وسعيد)\nال أبو عمرو ثم خطبها رجل من قومها وبلغ ذلك مسعودا فقال\n(أيا جمل لا تشقي بأقعس حنكل ... قليل الندى يسعى بكير ومحلب)\n(له أعنز حو ثمان كأنما ... يراهن غر الخيل أو هن أنجب)\nوقال أبو عمرو وسرق مسعود بن خرشة إبلا من مالك بن سفيان بن عمرو الفقعسي هو ورفقاء له وكان معه رجلان من قومه فأتوا بها اليمامة ليبيعوها فاعترض عليهم أمير كان بها من بني أسد ثم عزل وولي مكانه رجل من بني عقيل فقال مسعود في ذلك\n(يقول المرجفون أجاء عهد ... )","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":6,"spl":"أخبار مسعود بن خرشة — كفى عهدا بتنفيذ القلاص","tags":["الجواري والنساء"],"loc":1880,"partial":1},
{"id":"b109-11","bab":"الجزء 10","sec":"كفى عهدا بتنفيذ القلاص","page":"ج10 ص254","text":"أتى عهد الإمارة من عقيل\n... أغر الوجه ركب في النواصي\nحصون بني عقيل كل عضب\n... إذا فزعوا وسابغة دلاص\nوما الجارات عند المحل فيهم\n... ولو كثر الروازح بالخماص\nال وقال مسعود وقد طلبه والي اليمامة فلجأ إلى موضع فيه ماء وقصب\n(ألا ليت شعري هل أبيتن ليلة ... بوعثاء فيها للظباء مكانس)\n(وهل أنجون من ذي لبيد بن جابر ... كأن بنات الماء فيه المجالس)\n(وهل أسمعن صوت القطا تندب القطا ... إلى الماء منه رابع وخوامس)","topic":"أخبار ابن دارة ونسبه","topicNo":109,"sp":6,"spl":"أخبار مسعود بن خرشة — كفى عهدا بتنفيذ القلاص","tags":[],"loc":1881},
{"id":"b110-2","bab":"الجزء 10","sec":"أخبار بحر ونسبه — الرشيد يشرب على أصواته","page":"ج10 ص254 – ج10 ص255","text":"هو بحر بن العلاء مولى بني أمية حجازي أدرك دولة بني هاشم وعمر إلى أيام الرشيد وقد هرم وكان له أخ يقال له عباس وأخوه بحر أصغر منه مات في أيام المعتصم وكان يلقب حامض الرأس وله صنعة وأقدمه الرشيد عليه ثم كرهه فصرفه\nحدثني جحظة قال حدثني ميمون بن هارون قال حدثني أحمد بن أبي خالد الأحول عن علي بن صالح صاحب المصلى أن الرشيد سمع من علوية ومخارق وهما يومئذ من صغار المغنين في الطبقة الثالثة أصواتا استحسنها ولم يكن سمعها فقال لهما ممن أخذتما هذه الأصوات فقالا من بحر فاستعادها وشرب عليها ثم غناه مخارق بعد أيام صوتا لبحر فأمر بإحضاره وأمره أن يغني ذلك الصوت فغناه\nفسمع الرشيد صوتا حائلا مرتعشا فلم يعجبه واستثقله لولائه لبني أمية فوصله وصرفه ولم يصل إليه بعد ذلك\n(إلا يا لقومي للنوائب والدهر ... وللمرء يردي نفسه وهو لا يدري)\n(وللأرض كم من صالح قد تودات ... عليه فوارته بلماعة قفر)\nروضه من الطويل قال الأصمعي يقال للرجل أو للقوم إذا دعوتهم يال كذا بفتح اللام وإذا دعوت للشيء قلت بالكسرة تقول يا للرجال ويا للقوم وتقول يا للغنيمة ويا للحادثة أي اعجلوا للغنيمة وللحادثة فكأنه قال يا قوم اعجلوا للغنيمة وروى الأصمعي وغيره مكان قد تودأت قد تلمأت عليه وتلاءمت أي وارته ويروى تأكمت أي صارت أكمة الشعر لهدبة بن خشرم والغناء لمعبد ثقيل أول بإطلاق الوتر في مجرى البنصر عن إسحاق","topic":"أخبار بحر ونسبه","topicNo":110,"sp":0,"spl":"أخبار بحر ونسبه — الرشيد يشرب على أصواته","tags":[],"song":1,"loc":1882},
{"id":"b111-3","bab":"الجزء 10","sec":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله — طبقته في الشعر — الحرب بين قومه بني عامر وقوم زيادة بن زياد","page":"ج10 ص256 – ج10 ص257 – ج10 ص258","text":"هو هدبة بن خشرم بن كرز بن أبي حية بن الكاهن وهو سلمة بن أسحم بن عامر بن ثعلبه بن عبد الله بن ذبيان بن الحارث بن سعد بن هذيم وسعد بن هذيم شاعر من أسلم بن الحاف بن قضاعة ويقال بل هو سعد بن أسلم وهذيم عبد لأبيه رباه فقيل سعد بن هذيم يعني سعدا هذا\nوهدبة شاعر فصيح متقدم من بادية الحجاز وكان شاعرا راوية كان يروي للحطيئة والحطيئة يروي لكعب بن زهير وكعب بن زهير يروي لأبيه زهير وكان جميل راوية هدبة وكثير راوية جميل فلذلك قيل إن آخر فحل اجتمعت له الرواية إلى الشعر كثير وكان لهدبة ثلاثة إخوة كلهم شاعر حوط وسيحان والواسع أمهم حية بنت أبي بكر بن أبي حية من رهطهم الأدنين وكانت شاعرة أيضا\nوهذا الشعر يقوله هدبة في قتله زيادة بن زيد بن مالك بن عامر بن قرة ابن حنش بن عمرو بن عبد الله بن ثعلبة بن ذبيان بن الحارث بن سعد بن هذيم\nأخبرني بالخبر في ذلك جماعة من شيوخنا فجمعت بعض روايتهم إلى بعض واقتصرت على ما لا بد منه من الأشعار وأتيت بخبرهما على شرح وألحقت ما نقص من رواية بعضهم عن رواية صاحبه في موضع النقصان فممن\nحدثني به محمد بن العباس اليزيدي قال حدثنا عيسى بن إسماعيل العتكي تينة قال حدثنا خلف بن المثنى الحداني عن أبي عمرو المديني وأخبرني الحسن بن يحيى ومحمد بن مزيد بن أبي الأزهر البوشنجي عن حماد بن إسحاق الموصلي عن أبيه\nوأخبرني إبراهيم بن أيوب الصائغ عن ابن قتيبة وأخبرني أحمد بن عبيد الله بن عمار عن علي بن محمد بن سليمان النوفلي عن أبيه عن عمه وقد نسبت إلى كل واحد منهم ما انفرد به من الرواية وجمعت ما اتفقوا عليه قال عيسى بن إسماعيل في خبره خاصة كان أول ما هاج الحرب بين بني عامر بن عبد الله بن ذبيان وبين بني رقاش وهم بنو قرة بن حفش بن عمرو بن عبد الله بن ثعلبة بن ذبيان وهم\nرهط زيادة بن زيد وبنو عامر رهط هدبة أن حوط بن خشرم أخا هدبة راهن زيادة بن زيد على جملين من إبلهما وكان مطلقهما من الغاية على يوم وليلة وذلك في القيظ فتزودوا الماء في الروايا والقرب وكانت أخت حوط سلمى بنت خشرم تحت زيادة بن زيد فمالت مع أخيها على زوجها فوهنت أوعية زيادة ففني ماؤه قبل ماء صاحبه فقال زيادة\n(قد جعلت نفسي في أديم ... محرم الدباغ ذي هزوم)\n(ثم رمت بي عرض الديموم ... في بارح من وهج السموم)\n(عند اطلاع وعرة النجوم ... )\nال اليزيدي في خبره المحرم الذي لم يدبغ والهزوم الشقوق قال وقال زيادة أيضا\n(قد علمت سلمة بالعميس ... ليلة مرمار ومرمريس)\n(أن أبا المسور ذو شريس ... يشفي صداع الأبلج الدلعيس)\nلعميس موضع والمرمار والمرمريس الشدة والاختلاط وأبا المسور يعني زيادة نفسه وكانت كنيته أبا المسور","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":0,"spl":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله — طبقته في الشعر — الحرب بين ق","tags":[],"loc":1883,"partial":1},
{"id":"b111-4","bab":"الجزء 10","sec":"تبادل التشبيب بأختيهما","page":"ج10 ص260","text":"قال فكان ذلك أول ما أثبت الضغائن بينهما ثم إن هدبة بن خشرم وزيادة بن زيد اصطحبا وهما مقبلان من الشام في ركب من قومهما فكانا يتعاقبان السوق بالإبل وكان مع هدبة أخته فاطمة فنزل زيادة فارتجز فقال\n(عوجي علينا واربعي يا فاطما ... ما دون أن يرى البعير قائما)\nي ما بين مناخ البعير إلى قيامه\n(ألا ترين الدمع مني ساجما ... حذار دار منك لن تلائما)\n(فعرجت مطردا عراهما ... فعما يبذ القطف الرواسما)\nطرد متتابع السير وعراهم شديد وفعم ضخم والرسيم سير فوق العنق والرواسم الإبل التي تسير هذا السير الذي ذكرناه\n(كأن في المثناة منه عائما ... إنك والله لأن تباغما)\nلمثناة الزمام وعائم سائح تباغم تكلم\n(خودا كأن البوص والمآكما ... منها نقا مخالط صرائما)\nلبوص العجز والمأكمتان ما عن يمين العجز وشماله والنقا ما عظم من الرمل والصرائم دونه\n(خير من استقبالك السمائما ... ومن مناد يبتغي معاكما)\nويروى ومن نداء أي رجل تناديه تبتغي أن يعينك على عكمك حتى تشده فغضب هدبة حين سمع زيادة يرتجز بأخته فنزل فرجز بأخت زيادة وكانت تدعى فيما روى اليزيدي أم حازم وقال الآخرون وأم القاسم فقال هدبة\n(لقد أراني والغلام الحازما ... نزجي المطي ضمرا سواهما)\n(متى تظن القلص الرواسما ... والجلة الناجية العياهما)\nلعياهم الشداد\n(يبلغن أم حازم وحازما ... إذا هبطن مستحيرا قاتما)\n(ورجع الحادي لهما الهماهما ... ألا ترين الحزن مني دائما)\n(حذار دار منك لن تلائما ... والله لا يشفي الفؤاد الهائما)\n(تمساحك اللبات والمآكما ... ولا اللمام دون أن تلازما)\n(ولا اللثام دون أن تفاقما ... ولا الفقام دون أن تفاغما)\n(وتعلو القوائم القوائما ... )\nال فشتمه زيادة وشتمه هدبة وتسابا طويلا فصاح بهما القوم اركبا لاحملكما الله فإنا قوم حجاج وخشوا أن يقع بينهما شر فوعظوهما حتى أمسك كل واحد منهما على ما في نفسه وهدبة أشدهما حنقا لأنه رأى أن زيادة قد ضامه إذ رجز بأخته وهي تسمع قوله ورجز هو بأخته وهي غائبة لا تسمع قوله فمضيا ولم يتحاورا بكلمة حتى قضيا حجهما ورجعا إلى عشيرتيهما","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":1,"spl":"تبادل التشبيب بأختيهما — خبر عمه زفر وسبب غضب قومه","tags":["الرواية والكتابة"],"loc":1884,"partial":1},
{"id":"b111-5","bab":"الجزء 10","sec":"خبر عمه زفر وسبب غضب قومه","page":"ج10 ص262","text":"قال اليزيدي خاصة في خبره ثم التقى نفر من بني عامر من رهط هدبة فيهم أبو جبر وهو رئيسهم الذي لا يعصونه وخشرم أبو هدبة وزفر عم هدبة وهو الذي بعث الشر وحجاج بن سلامة وهو أبو ناشب ونفر من بني رقاش رهط زيادة وفيهم زيادة بن زيد وإخواته عبد الرحمن ونفاع وأدرع بواد من أودية حرتهم فكان بينهم كلام فغضب ابن الغسانية وهو أدرع وكان زفر عم هدبة يعزى إلى رجل من بني رقاش فقام له أدرع فرجز به فقال\n(أدوا إلينا زفرا ... نعرف منه النظرا)\n(وعينه والأثرا ... )\nال فغضب رهط هدبة وادعوا حدا على بني رقاش فتداعوا إلى السلطان ثم اصطلحوا على أن يدفع إليهم أدرع فيخلو به نفر منهم فما رأوه عليه أمضوه فلما خلوا به ضربوه الحد ضربا مبرحا فراح بنو رقاش وقد\nأضمروا الحرب وغضبوا فقال عبد الرحمن بن زيد\n(ألا أبلغ أبا جبر رسولا ... فما بيني وبينكم عتاب)\n(ألم تعلم بأن القوم راحوا ... عشية فارقوك وهم غضاب)\nأجابه الحجاج بن سلامة فقال\n(إن كان ما لاقى ابن كنعاء مرغما ... رقاش فزاد الله رغما سبالها)\n(منعنا أخانا إذ ضربنا أخاكم ... وتلك من الأعداء لا مثل مالها)","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":1,"spl":"تبادل التشبيب بأختيهما — خبر عمه زفر وسبب غضب قومه","tags":["السفر والحج"],"loc":1885,"partial":1},
{"id":"b111-6","bab":"الجزء 10","sec":"هدبة وزيادة يتهاديان الأشعار","page":"ج10 ص263","text":"قال اليزيدي في خبره وجعل هدبة وزيادة يتهاديان الأشعار ويتفاخران ويطلب كل واحد منهما العلو على صاحبه في شعره وذكر أشعارا كثيرة فذكرت بعضها وأتيت بمختار ما فيه فمن ذلك قول زيادة في قصيدة أولها\n(أراك خليلا قد عزمت التجنبا ... وقطعت حاجات الفؤاد فأصحبا)\nخترت منها قوله\n(وأنك للناس الخليل إذا دنت ... به الدار والباكي إذا ما تغيبا)\n(وقد أعذرت صرف الليالي بأهلها ... وشحط النوى بيني وبينك مطلبا)\n(فلا هي تألو ما نأت وتباعدت ... ولا هو يألو ما دنا وتقربا)\n(اطعت بها قول الوشاة فلا أرى الوشاة ... انتهوا عنه ولا الدهر أعتبا)\n(فهلا صرمت والحبال متينة ... أميمة إن واش وشى وتكذبا)\n(إذا خفت شك الأمر فارم بعزمة ... غيابته يركب بك الدهر مركبا)\n(وإن وجهة يدت سدت عليك فروجها ... فإنك لاق لا محالة مذهبا)\n(يلام رجال قبل تجريب غيبهم ... وكيف يلام المرء حتى يجربا)\n(وإني لمعراض قليل تعرضي ... لوجه امرئ يوما إذا ما تجنبا)\n(قليل عثاري حين أذعر ساكن ... جناني إذا ما الحرب هرت لتكلبا)\n(بحسبك ما يأتيك فاجمع لنازل ... قراه ونوبه إذا ما تنوبا)\n(ولا تنتجع شرا إذا حيل دونه ... بستر وهب أسبابه ما تهيبا)\n(أنا ابن رقاش وابن ثعلبة الذي ... بنى هاديا يعلو الهوادي أغلبا)\n(بنى العز بنيانا لقومي فما صعوا ... بأسيافهم عنه فأصبح مصعبا)\n(فما إن ترى في الناس أما كأمنا ... ولا كأبينا حين ننسبه أبا)\n(أتم وأنمى بالبنين إلى العلا ... وأكرم منا في المناصب منصبا)\n(ملكنا ولم نملك وقدنا ولم نقد ... كأن لنا حقا على الناس ترتبا)\nال اليزيدي ترتب ثابت لازم\n(بآية أنا لا نرى متتوجا ... من الناس يعلونا إذا ما تعصبا)\n(ولا ملكا إلا اتقانا بملكه ... ولا سوقة إلا على الخرج أتعبا)\n(ملكنا ملوكا واستبحنا حماهم ... وكنا لهم في الجاهلية موكبا)\n(ندامى وأردافا فلم تر سوقة ... توازننا فاسأل إيادا وتغلبا)\nأجابه هدبة وهذا مختار ما فيها فقال\n(تذكر شجوا من أميمة منصبا ... تليدا ومنتابا من الشوق مجلبا)\n(تذكر حبا كان في ميعة الصبا ... ووجدا بها بعد المشيب معتبا)\n(إذا كاد ينساها الفؤاد ذكرتها ... فيا لك ما عنى الفؤاد وعذبا)\n(غدا في هواها مستكينا كأنه ... خليع قداح لم يجد متنشبا)\n(وقد طال ما كان علقت ليلى مغمرا ... وليدا إلى أن صار رأسك أشيبا)\nلمغمر الغمر أي غير حدث\n(رأيتك في ليلى كذي الداء لم يجد ... طبيبا يداوي ما به فتطببا)\n(فلما اشتفى مما به كر طبه ... على نفسه من طول ما كان جربا)","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":2,"spl":"هدبة وزيادة يتهاديان الأشعار — قتل زيادة وتنحى ثم استسلم","tags":["الحب والغزل"],"loc":1886},
{"id":"b111-7","bab":"الجزء 10","sec":"قتل زيادة وتنحى ثم استسلم","page":"ج10 ص265","text":"فلم يزل هدبة يطلب غرة زيادة حتى أصابها فبيته فقتله وتنحى مخافة السلطان وعلى المدينة يومئذ سعيد بن العاص فأرسل إلى عم هدبة وأهله فحبسهم بالمدينة فلما بلغ هدبة ذلك أقبل حتى أمكن من نفسه وتخلص عمه وأهله فلم يزل محبوسا حتى شخص عبد الرحمن بن زيد أخو زيادة إلى معاوية فأورد كتابه إلى سعيد بأن يقيد منه إذا قامت البينة\nفأقامها فمشت عذرة إلى عبد الرحمن فسألوه قبول الدية فامتنع وقال\n(أنختم علينا كلكل الحرب مرة ... فنحن منيخوها عليكم بكلكل)\n(فلا يدعني قومي لزيد بن مالك ... لئن لم أعجل ضربة أو أعجل)\n(أبعد الذي بالنعف نعف كويكب ... رهينة رمس ذي تراب وجندل)\n(كريم أصابته ديات كثيرة ... فلم يدر حتى حين من كل مدخل)\n(أذكر بالبقيا على من أصابني ... وبقياي أني جاهد غير مؤتلي)\nناه ابن سريج رملا بالسبابة في مجرى البنصر عن إسحاق وقيل إنه لمالك بن أبي السمح وله فيه لحن آخر","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":2,"spl":"هدبة وزيادة يتهاديان الأشعار — قتل زيادة وتنحى ثم استسلم","tags":[],"song":1,"loc":1887},
{"id":"b111-8","bab":"الجزء 10","sec":"رجع الخبر إلى سياقته سعيد بن العاص يحكم معاوية في أمر هدبة","page":"ج10 ص266","text":"وأما علي بن محمد النوفلي فذكر عن أبيه أن سعيد بن العاص كره الحكم بينهما فحملهما إلى معاوية فنظر في القصة ثم ردها إلى سعيد وأما غيره فذكر أن سعيدا هو الذي حكم بينهما من غير أن يحملهما إلى معاوية قال علي بن محمد عن أبيه فلما صاروا بين يدي معاوية قال عبد الرحمن أخو زيادة له يا أمير المؤمنين أشكو إليك مظلمتي وما دفعت إليه وجرى علي وعلى أهلي وقرباي\nوقتل أخي زيادة وترويع نسوتي فقال له معاوية يا هدبة قل فقال إن هذا رجل سجاعة فإن شئت أن أقص عليك قصتنا كلاما أو شعرا فعلت قال لا بل شعرا فقال هدبة هذه القصيدة ارتجالا\n(ألا يا لقومي للنوائب والدهر ... وللمرء يردي نفسه وهو لا يدري)\n(وللأرض كم من صالح قد تأكمت ... عليه فوارته بلماعة قفر)\n(فلا تتقي ذا هيبة لجلاله ... ولا ذا ضياع هن يتركن للفقر)\nتى قال\n(رمينا فرامينا فصادف رمينا ... منايا رجال في كتاب وفي قدر)\n(وأنت أمير المؤمنين فما لنا ... وراءك من معدى ولا عنك من قصر)\n(فإن تك في أموالنا لم نضق بها ... ذراعا وإن صبر فنصبر للصبر)\nقال له معاوية أراك قد أقررت بقتل صاحبهم ثم قال لعبد الرحمن هل لزيادة ولد قال نعم المسور وهو غلام صغير لم يبلغ وأنا عمه وولي دم أبيه فقال إنك لا تؤمن على أخذ الدية أو قتل الرجل بغير حق والمسور أحق بدم أبيه فرده إلى المدينة فحبس ثلاث سنين حتى بلغ المسور جميل بن معمر يزوره في السجن ويهديه أخبرني الحرمي بن العلاء قال حدثنا الزبير بن بكار قال نسخت من كتاب عامر بن صالح قال\nدخل جميل بن معمر العذري على هدبة بن خشرم السجن وهو محبوس بدم زيادة بن زيد وأهدى له بردين من ثياب كساه إياها سعيد بن العاص وجاءه بنفقة فلما دخل إليه عرض ذلك عليه وسأله أن يقبله منه فقال له هدبة أأنت يا بن معمر الذي تقول\n(بني عامر أنى انتجعتم وكنتم ... إذا عدد الأقوام كالخصية الفرد)\nأما والله لئن خلص الله لي ساقي لأمدن لك مضمارك خذ برديك ونفقتك فخرج جميل فلما بلغ باب السجن خارجا قال اللهم أغن عني أجدع بني عامر قال وكانت بنو عامر قد قلت فحالفت لإياد قال أحمد بن الحارث الخراز عن المدائني فقالت أم هدبة فيه لما شخص إلى المدينة فحبس بها\n(أيا إخوتي أهل المدينة أكرموا ... أسيركم إن الأسير كريم)\n(فرب كريم قد قراه وضافه ... ورب أمور كلهن عظيم)\n(عصى جلها يوما عليه فراضه ... من القوم عياف أشم حليم)\nأرسل هدبة العشيرة إلى عبد الرحمن في أول سنة فكلموه فاستمع منهم ثم قال\n(أبعد الذي بالنعف نعف كويكب ... رهينة رمس ذي تراب وجندل)\n(أذكر بالبقيا على من أصابني ... وبقياي أني جاهد غير مؤتلي)\nفرجعوا إلى هدبة بالأبيات فقال لم يؤئسني بعد فلما كانت السنة\nالثالثة بلغ المسور فأرسل هدبة إلى عبد الرحمن من كلمه فأنصت حتى فرغوا ثم قام عنه مغضبا وأنشأ يقول\n(سأكذب أقواما يقولون إنني ... سآخذ مالا من دم أنا ثائره)\n(فباست امرئ واست التي زحرت به ... يسوق سواما من أخ هو واتره)\nنهض فرجعوا إلى هدبة فأخبروه الخبر فقال الآن أيست منه وذهب عبد الرحمن بالمسور وقد بلغ إلى والي المدينة وهو سعيد بن العاص وقيل مروان بن الحكم فأخرج هدبة","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":3,"spl":"رجع الخبر إلى سياقته سعيد بن العاص يحكم معاوية في أمر هدبة","tags":[],"loc":1888},
{"id":"b111-9","bab":"الجزء 10","sec":"لقاؤه الأخير بزوجته","page":"ج10 ص269","text":"قالوا فلما كان في الليلة التي قتل في صباحها أرسل إلى امرأته وكان يحبها إيتيني الليلة أستمتع بك وأودعك فأتته في اللباس والطيب فصارت إلى رجل قد طال حبسه وأنتنت في الحديد رائحته فحادثها وبكى وبكت ثم راودها عن نفسها وطاوعته فلما علاها سمعت قعقعة الحديد فاضطربت تحته فتنحى عنها وأنشأ يقول\n(وأدنيتني حتى إذا ما جعلتني ... لدى الخصر أو أدنى استقلك راجف)\n(فإن شئت والله انتهيت وإنني ... لئلا تريني آخر الدهر خائف)\n(رأت ساعدي غول وتحت ثيابه ... جآجئ يدمى حدها والحراقف)\nم قال الشعر حتى أتى عليه وهو طويل جدا وفيه يقول\n(فلم تر عيني مثل سرب رأيته ... خرجن علينا من زقاق ابن واقف)\n(تضمخن في الجادي حتى كأنما الأنوف ... إذا استعرضتهن رواعف)\n(خرجن بأعناق الظباء وأعين الجآذر وارتجت لهن السوالف ... )\n(فلو أن شيئا صاد شيئا بطرفه ... لصدن ظباء فوقهن المطارف)\nنى فيه الغريض رملا بالبنصر من رواية حبش وفيه لحن خفيف ثقيل وذكر إسحاق أن فيه لحنا ليونس ولم يذكر طريقته في مجرده أخبرنا الحرمي قال حدثنا الزبير عن عمه قال مر أبو الحارث جمين يوما بسوق المدينة فخرج عليه رجل من زقاق ابن واقف بيده ثلاث سمكات قد شق أجوافها وقد خرج شحمها فبكى أبو الحارث ثم قال تعس الذي يقول\n(فلم تر عيني مثل سرب رأيته ... خرجن علينا من زقاق ابن واقف)\nانتكس ولا انجبر والله لهذه السمكات الثلاث أحسن من السرب الذي وصف وأحسب أن هذا الخبر مصنوع لأنه ليس بالمدينة زقاق يعرف بزقاق ابن واقف ولا بها سمك ولكن رويت ما روي","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":4,"spl":"لقاؤه الأخير بزوجته — يذكر شرط زوجته في الزواج بعد موته","tags":[],"loc":1889,"partial":1},
{"id":"b111-10","bab":"الجزء 10","sec":"شعره في حبى امرأة مالك","page":"ج10 ص270","text":"وقال حماد بن إسحاق عن أبيه أن ابن كناسة قال مر بهدبة على حبى فقالت في سبيل الله شبابك وجلدك وشعرك وكرمك فقال هدبة\n(تعجب حبى من أسير مكبل ... صليب العصا باق على الرسفان)\n(فلا تعجبي مني حليلة مالك ... كذلك يأتي الدهر بالحدثان)\nقال النوفلي عن أبيه فلما مضي به من السجن للقتل التفت فرأى امرأته وكانت من أجمل النساء فقال\n(أقلي علي اللوم يا أم بوزعا ... ولا تجزعي مما أصاب فأوجعا)\n(ولا تنكحي إن فرق الدهر بيننا ... أغم القفا والوجه ليس بأنزعا)\n(كليلا سوى ما كان من حد ضرسه ... أكيبد مبطان العشيات أروعا)\n(ضروبا بلحييه على عظم زوره ... إذا الناس هشوا للفعال تقنعا)\n(وحلي بذي أكرومة وحمية ... وصبر إذا ما الدهر عض فأسرعا)","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":4,"spl":"لقاؤه الأخير بزوجته — يذكر شرط زوجته في الزواج بعد موته","tags":[],"loc":1890},
{"id":"b111-11","bab":"الجزء 10","sec":"يذكر شرط زوجته في الزواج بعد موته","page":"ج10 ص271","text":"وقال حماد عن أبيه عن مصعب بن عبد الله قال لما أخرج هدبة من السجن ليقتل جعل الناس يتعرضون له ويخبرون صبره ويستنشدونه فأدركه عبد الرحمن بن حسان فقال له يا هدبة\nأتأمرني أن أتزوج هذه بعدك يعني زوجته وهي تمشي خلفه فقال نعم إن كنت من شرطها قال وما شرطها قال قد قلت في ذلك\n(فلا تنكحي إن فرق الدهر بيننا ... أغم القفا والوجه ليس بأنزعا)\n(وكوني حبيسا أو لأروع ماجد ... إذا ضن أعشاش الرجال تبرعا)\nمالت زوجته إلى جزار وأخذت شفرته فجدعت بها أنفها وجاءته تدمى مجدوعة فقالت أتخاف أن يكون بعد هذا نكاح قال فرسف في قيوده وقال الآن طاب الموت\nوقال النوفلي عن أبيه إنها فعلت ذلك بحضرة مروان وقالت له إن لهدبة عندي وديعة فأمهله حتى آتيه بها قال أسرعي فإن الناس قد كثروا وكان جلس لهم بارزا عن داره فمضت إلى السوق فانتهت إلى قصاب وقالت أعطني شفرتك وخذ هذين الدرهمين وأنا أردها عليك ففعل فقربت من حائط وأرسلت ملحفتها على وجهها ثم جدعت أنفها من أصله وقطعت شفتيها ثم ردت الشفرة وأقبلت حتى دخلت بين الناس وقالت يا هدبة أتراني متزوجة بعد ما ترى قال لا الآن طابت نفسي بعد بالموت ثم خرج يرسف في قيوده فإذا هو بأبويه يتوقعان الثكل فهما بسوء حال فأقبل عليهما وقال\n(أبلياني اليوم صبرا منكما ... إن حزنا إن بدا بادئ شر)\n(لا أراني اليوم إلا ميتا ... إن بعد الموت دار المستقر)\n(اصبرا اليوم فإني صابر ... كل حي لقضاء وقدر)","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":4,"spl":"لقاؤه الأخير بزوجته — يذكر شرط زوجته في الزواج بعد موته","tags":["الموت"],"loc":1891},
{"id":"b111-12","bab":"الجزء 10","sec":"زوجته تنكث بعهدها","page":"ج10 ص272","text":"قال النوفلي فحدثني أبي قال حد حدثني رجل من عذرة عن أبيه قال إني لببلادنا يوما في بعض المياه فإذا أنا بامرأة تمشي أمامي وهي مدبرة ولها خلق عجيب من عجز وهيئة وتمام جسم وكمال قامة فإذا صبيان قد اكتنفاها يمشيان قد ترعرعا فتقدمتها والتفت إليها فإذا هي أقبح منظر وإذا هي مجدوعة الأنف مقطوعة الشفتين فسألت عنها فقيل لي هذه امرأة هدبة تزوجت بعده رجلا فأولدها هذين الصبيين\nقال ابن قتيبة في حديثه فسأل سعيد بن العاص أخا زيادة أن يقبل الدية عنه قال أعطيك ما لم يعطه أحد من العرب أعطيك مائة ناقة حمراء ليس فيها جداء ولا ذات داء فقال له والله لو نقبت لي قبتك هذه ثم ملأتها لي ذهبا ما رضيت بها من دم هذا الأجدع فلم يزل سعيد يسأله ويعرض عليه فيأبى ثم قال له والله لو أردت قبول الدية لمنعني قوله\n(لنجدعن بأيدينا أنوفكم ... ويذهب القتل فيما بيننا هدرا)\nدفعه حينئذ لقتله بأخيه","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":5,"spl":"زوجته تنكث بعهدها — هو أول من أقيد منه في الإسلام","tags":["الجواري والنساء"],"loc":1892},
{"id":"b111-13","bab":"الجزء 10","sec":"تعريضه بحبى في طريقه إلى الموت","page":"ج10 ص273","text":"قال حماد وقرأت على أبي عن مصعب بن عبد الله الزبيري قال ومر هدبة بحبى فقالت له كنت أعدك في الفتيان وقد زهدت فيك اليوم لأني لا أنكر أن يصبر الرجال على الموت لكن كيف تصبر عن\nهذه فقال أما والله إن حبي لها لشديد وإن شئت لأصفن لك ذلك ووقف الناس معه فقال\n(وجدت بها ما لم تجد أم واحد ... ولا وجد حبى بابن أم كلاب)\n(رأته طويل الساعدين شمردلا ... كما تشتهي من قوة وشباب)\nانقمعت داخلة إلى بيتها فأغلقت الباب دونه قالوا فدفع إلى أخي زيادة ليقتله قال فاستأذن في أن يصلي ركعتين فأذن له فصلاهما وخفف ثم التفت إلى من حضر فقال لولا أن يظن بي الجزع لأطلتهما فقد كنت محتاجا إلى إطالتهما ثم قال لأهله إنه بلغني أن القتيل يعقل ساعة بعد سقوط رأسه فإن عقلت فإني قابض رجلي وباسطها ثلاثا ففعل ذلك حين قتل وقال قبل أن يقتل\n(إن تقتلوني في الحديد فإنني ... قتلت أخاكم مطلقا لم يقيد)\nقال عبد الرحمن أخو زيادة والله لا قتلته إلا مطلقا من وثاقه فأطلق له فقام إليه وهز السيف ثم قال\n(قد علمت نفسي وأنت تعلمه ... لأقتلن اليوم من لا أرحمه)\nثم قتله فقال حماد في روايته ويقال إن الذي تولى قتله ابنه المسور دفع إليه عمه السيف وقال له قم فاقتل قاتل أبيك فقام فضربه ضربتين قتله فيهما","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":5,"spl":"زوجته تنكث بعهدها — هو أول من أقيد منه في الإسلام","tags":["الحكمة والمواعظ","الموت"],"loc":1893},
{"id":"b111-14","bab":"الجزء 10","sec":"هو أول من أقيد منه في الإسلام","page":"ج10 ص275","text":"أخبرني الحسين بن يحيى قال قال حماد فرأت على أبي قال بلغني أن هدبة أول من أقيد منه في الإسلام قال أحمد بن الحارث الخراز قال المدائني مرت كاهنة بأم هدبة وهو وأخوته نيام بين يديها فقالت يا هذه إن الذي معي يخبرني عن بنيك هؤلاء بأمر قالت وما هو قالت أما هدبة وحوط فيقتلان صبرا وأما الواسع وسيحان فيموتان كمدا فكان كذلك\nأخبرني الحسين بن يحيى قال قال حماد قرأت على أبي أخبرك مروان بن أبي حفصة قال كان هدبة أشعر الناس منذ يوم دخل السجن إلى أن أقيد منه قال الخراز عن المدائني قال واسع بن خشرم يرثي هدبة لما قتل\n(يا هدب يا خير فتيان العشيرة من ... يفجع بمثلك في الدنيا فقد فجعا)\n(الله يعلم أني لو خشيتهم ... أو أوجس القلب من خوف لهم فزعا)\n(لم يقتلوه ولم أسلم أخي لهم ... حتى نعيش جميعا أو نموت معا)\nهذه الأبيات تمثل بها إبراهيم بن عبد الله بن حسن بن حسن بن علي ابن أبي طالب رضي عنهم لما بلغه قتل أخيه محمد\nأخبرني محمد بن العباس اليزيدي قال حدثنا أحمد بن أبي خيثمة قال حدثني مصعب الزبيري قال كنا بالمدينة أهل البيوتات إذا لم يكن عند أحدنا خبر هدبة وزيادة وأشعارهما ازدريناه وكنا نرفع من قدر أخبارهما وأشعارهما ونعجب بها","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":5,"spl":"زوجته تنكث بعهدها — هو أول من أقيد منه في الإسلام","tags":[],"loc":1894},
{"id":"b111-15","bab":"الجزء 10","sec":"كان جميل بن معمر راوية هدبة","page":"ج10 ص276","text":"أخبرني محمد بن العباس اليزيدي قال أخبرني محمد بن الحسن الأحول عن رواية من الكوفيين قالوا كان جميل بن معمر العذري راوية هدبة وكان هدبة راوية الحطيئة وكان الحطيئة راوية كعب بن زهير وأبيه\nحدثني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني أبو المغيرة محمد بن إسحاق قال حدثني أبو مصعب الزبيري قال حدثني المنكدر بن محمد بن المنكدر عن أبيه قال بعث هدبة بن خشرم إلى عائشة زوج النبي يقول لها استغفري لي فقالت إن قتلت استغفرت لك\n(ألم تر أني يوم جو سويقة ... بكيت فنادتني هنيدة ماليا)\n(فقلت لها إن البكاء لراحة ... به يشتفي من ظن أن لا تلاقيا)\n(قفي ودعينا يا هنيد فإنني ... أرى القوم قد شاموا العقيق اليمانيا)\nويروى أرى الركب قد شاموا\n(إذا اغرورقت عيناي أسبل منهما ... إلى أن تغيب الشعريان بكائيا)\nلشعر للفرزدق من قصيدة يهجو بها جريرا وهي فيما قيل أول قصيدة هجاه بها والغناء لابن سريج خفيف ثقيل عن الهشامي قال الهشامي وفيه لمالك ثقيل أول وابتداء اللحنين جميعا\n(ألم تر أني يوم جو سويقة ... )\nلعلوية فيه لحن من الرمل المطلق ابتداؤه\n(قفي ودعينا يا هنيد فإنني ... )","topic":"أخبار هدبة بن خشرم ونسبه وقصته في قوله هذا الشعر وخبر مقتله","topicNo":111,"sp":6,"spl":"كان جميل بن معمر راوية هدبة","tags":[],"song":1,"loc":1895,"partial":1},
{"id":"b112-1","bab":"الجزء 10","sec":"نسب الفرزدق وأخباره وذكر مناقضاته","page":"ج10 ص278","text":"الفرزدق لقب غلب عليه وتفسيره الرغيف الضخم الذي يجففه النساء للفتوت وقيل بل هو القطعة من العجين التي تبسط فيخبز منها الرغيف شبه وجهه بذلك لأنه كان غليظا جهما واسمه همام بن غالب بن صعصعة بن ناجية بن عقال بن محمد بن سفيان بن مجاشع بن دارم بن مالك ابن حنظلة بن زيد مناة بن تميم\nقال أبو عبيدة اسم دارم بحر واسم أبيه مالك عوف ويقال عرف وسمي دارم دارما لأن قوما أتوا أباه مالكا في حمالة فقال له قم يا بحر فأتني بالخريطة يعني خريطة كان له فيها مال فحملها يدرم عنها ثقلا والدرمان تقارب الخطو فقال لهم جاءكم يدرم بها فسمي دارما وسمي أبوه مالك عرفا لجوده وأم غالب ليلى بنت حابس بن عقال بن محمد بن سفيان بن مجاشع وكان للفرزدق أخ يقال له هميم ويلقب الأخطل ليست له نباهة فأعقب ابنا يقال له محمد فمات والفرزدق حي فرثاه وخبره يأتي بعد وكان للفرزدق من الولد خبطة ولبطة وسبطة هؤلاء المعروفون وكان له غيرهم فماتوا ولم يعرفوا وكان له بنات خمس أو ست\nوأم الفرزدق فيما ذكر أبو عبيدة لينة بنت قرظة الضبية","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":0,"spl":"نسب الفرزدق وأخباره وذكر مناقضاته","tags":["الفرزدق","الجواري والنساء","الموت"],"loc":1896},
{"id":"b112-2","bab":"الجزء 10","sec":"كان يقال لجده صعصعة محيي المؤودات","page":"ج10 ص279","text":"وكان يقال لصعصعة محيي الموءودات وذلك أنه كان مر برجل من قومه وهو يحفر بئرا وامرأته تبكي فقال لها صعصعة ما يبكيك قالت يريد أن يئد ابنتي هذه فقال له ما حملك على هذا\nقال الفقر قال فإني أشتريها منك بناقتين يتبعهما أولادهما تعيشون بألبانهما ولا تئد الصبية قال قد فعلت فأعطاه الناقتين وجملا كان تحته فحلا\nوقال في نفسه إن هذه لمكرمة ما سبقني إليها أحد من العرب فجعل على نفسه ألا يسمع بموءودة إلا فداها فجاء الإسلام وقد فدى ثلثمائة موءودة\nوقيل أربعمائة أخبرني بذلك هاشم بن محمد الخزاعي عن دماذ عن أبي عبيدة وأخبرني بهذا الخبر محمد بن العباس اليزيدي وعلي بن سليمان الأخفش قالا\nحدثنا أبو سعيد السكري عن محمد بن حبيب عن أبي عبيدة عن عقال بن شبة قال قال صعصعة خرجت باغيا ناقتين لي فارقتين والفارق التي تفرق إذا ضربها المخاض فتند على وجهها حتى تنتج فرفعت لي نار فسرت نحوها وهممت بالنزول فجعلت النار تضيء مرة وتخبو أخرى فلم تزل تفعل ذلك حتى قلت اللهم لك علي إن بلغتني هذه النار ألا أجد أهلها يوقدون لكربة يقدر أحد من الناس أن يفرجها إلا فرجتها عنهم قال فلم أسر إلا قليلا حتى أتيتها فإذا حي بن بني أنمار من الهجيم بن عمرو بن تميم وإذا\nأنا بشيخ حادر أشعر يوقدها في مقدم بيته والنساء قد اجتمعن إلى امرأة ماخض قد حبستهن ثلاث ليال فسلمت فقال الشيخ من أنت فقلت أنا صعصعة بن ناجية بن عقال\nقال مرحبا بسيدنا ففيم أنت يا بن أخي فقلت في بغاء ناقتين لي فارقتين عمي علي أثرهما فقال قد وجدتهما بعد أن أحيا الله بهما أهل بيت من قومك وقد نتجناهما وعطفت إحداهما على الأخرى وهما تانك في أدنى الإبل\nقال قلت ففيم توقد نارك منذ الليلة قال أوقدها لامرأة ماخض قد حبستنا منذ ثلاث ليال وتكلمت النساء فقلن قد جاء الولد فقال الشيخ إن كان غلاما فو الله ما ادري ما أصنع به وإن كانت جارية فلا أسمعن صوتها أي اقتلنها فقلت يا هذا ذرها فإنها ابنتك ورزقها على الله فقال اقتلنها فقلت أنشدك الله فقال إني أراك بها حفيا فاشترها مني فقلت إني أشتريها منك فقال ما تعطيني\nقلت أعطيك إحدى ناقتي قال لا قلت فأزيدك الأخرى فنظر إلى جملي الذي تحتي فقال لا إلا أن تزيدني جملك هذا فإني أراه حسن اللون شاب السن فقلت هو لك والناقتان على أن تبلغني أهلي عليه\nقال قد فعلت فابتعتها منه بلقوحين وجمل وأخذت عليه عهد الله وميثاقه ليحسنن برها وصلتها ما عاشت حتى تبين منه أو يدركها الموت فلما برزت من عنده حدثتني نفسي وقلت إن هذه لمكرمة ما سبقني إليها أحد من العرب فآليت ألا يئد أحد بنتا له إلا اشتريتها منه بلقوحين وجمل فبعث الله عز و جل محمدا عليه السلام وقد أحييت مائة موءودة إلا أربعا ولم يشاركني في ذلك أحد حتى أنزل الله تحريمه في القرآن وقد فخر بذلك الفرزدق في عدة قصائد من شعره ومنها قصيدته التي أولها\n(أبي أحد الغيثين صعصعة الذي ... متى تخلف الجوزاء والدلو يمطر)\n(أجار بنات الوائدين ومن يجر ... على الفقر يعلم أنه غير مخفر)\n(على حين لا تحيا البنات وإذ هم ... عكوف على الاصنام حول المدور)\nلمدور يعني الدوار الذي حول الصنم وهو طوافهم\n(أنا ابن الذي رد المنية فضله ... فما حسب دافعت عنه بمعور)\n(وفارق ليل من نساء أتت أبي ... تمارس ريحا ليلها غير مقمر)\n(فقالت أجر لي ما ولدت فإنني ... أتيتك من هزلى الحمولة مقتر)\n(هجف من العثو الرؤوس إذا بدت ... له ابنة عام يحطم العظم منكر)\n(رأى الأرض منها راحة فرمى بها ... إلى خدد منها إلى شر مخفر)\n(فقال لها فيئي فإني بذمتي ... لبنتك جار من أبيها القنور)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":1,"spl":"كان يقال لجده صعصعة محيي المؤودات","tags":["الفرزدق"],"loc":1897},
{"id":"b112-3","bab":"الجزء 10","sec":"إسلام أبيه على يد الرسول","page":"ج10 ص281","text":"ووفد غالب بن صعصعة إلى النبي فأسلم وقد كان وفده أبوه صعصعة إلى النبي فأخبره بفعله في الموءودات فاستحسنه وسأله هل له في ذلك من أجر قال نعم فأسلم وعمر غالب حتى لحق أمير المؤمنين\nعليا صلوات الله عليه بالبصرة وأدخل إليه الفرزدق وأظنه مات في إمارة زياد وملك معاوية أخبرني محمد بن الحسين الكندي وهاشم بن محمد الخزاعي وعبد العزيز بن أحمد عم أبي قالوا\nحدثنا الرياشي قال حدثنا العلاء بن الفضل ابن عبد الملك بن أبي سوية قال حدثني عقال بن كسيب أبو الخنساء العنبري قال حدثني الطفيف بن عمرو الربعي عن ربيعة بن مالك بن حنظلة عن صعصعة بن ناجية المجاشعي جد الفرزدق\nقال قدمت على النبي فعرض علي الإسلام فأسلمت وعلمني آيات من القرآن فقلت يا رسول الله إني عملت أعمالا في الجاهلية هل لي فيها من أجر فقال وما عملت فقلت إني أضللت ناقتين لي عشراوين فخرجت أبغيهما على جمل فرفع لي بيتان في فضاء من الأرض فقصدت قصدهما فوجدت في أحدهما شيخا كبيرا فقلت له هل أحسست من ناقتين عشراوين\nقال وما نارهما يعني السمة فقلت ميسم بني دارم فقال قد أصبت ناقتيك ونتجناهما وظأرتا على أولادهما ونعش الله بهما أهل بيت من قومك من العرب من مضر فبينا هو يخاطبني إذ نادته امرأة من البيت الآخر قد ولدت فقال وما ولدت إن كان غلاما فقد شركنا في قوتنا وإن كانت جارية فادفنوها فقالت هي جارية أفأئدها فقلت وما هذا المولود قالت بنت لي فقلت إني أشتريها منك فقال يا أخا بني نميم أتقول لي أتبيعني ابنتك وقد أخبرتك أني من العرب من مضر فقلت إني لا أشتري منك رقبتها إنما أشتري دمها لئلا تقتلها فقال وبم تشتريها فقلت بناقتي هاتين وولديهما قال لا حتى تزيدني هذا البعير\nالذي تركبه قلت نعم على أن ترسل معي رسولا فإذا بلغت أهلي رددت إليك البعير ففعل فلما بلغت أهلي رددت إليه البعير فلما كان في بعض الليل فكرت في نفسي فقلت إن هذه مكرمة ما سبقني إليها أحد من العرب فظهر الإسلام وقد أحييت ثلثمائة وستين موؤودة أشتري كل واحدة منهن بناقتين عشراوين وجمل فهل لي في ذلك من أجر يا رسول الله فقال عليه السلام هذا باب من البر ولك أجره إذ من الله عليك بالإسلام قال عباد ومصداق ذلك قول الفرزدق\n(وجدي الذي منع الوائدات ... وأحيا الوئيد فلم يوأد)\nخبرني محمد بن يحيى عن الغلابي عن العباس بن بكار عن أبي بكر الهذلي قال وفد صعصعة بن ناجية جد الفرزدق على رسول الله في وفد من تميم وكان صعصعة قد منع الوئيد في الجاهلية فلم يدع تميما تئد وهو يقدر على ذلك فجاء الإسلام وقد فدى أربعمائة جارية فقال للنبي أوصني فقال أوصيك بأمك وأبيك وأخيك وأختك وإمائك\nقال زدني قال احفظ ما بين لحييك وما بين رجليك ثم قال له عليه السلام ما شيء بلغني عنك فعلته قال يا رسول الله رأيت الناس يموجون على غير وجه ولم أدر أين الوجه غير أني علمت أنهم ليسوا عليه ورأيتهم يئدون بناتهم فعلمت أن ربهم لم يأمرهم بذلك فلم أتركهم يئدون وفديت من قدرت عليه وروى أبو عبيدة أنه قال للنبي إني حملت حمالات في الجاهلية\nوالإسلام وعلي منها ألف بعير فأديت من ذلك سبعمائة فقال له إن الإسلام أمر بالوفاء ونهى عن الغدر فقال حسبي حسبي ووفى بها وروي أنه إنما قال هذا القول لعمر بن الخطاب وقد وفد إليه في خلافته وكان صعصعة شاعرا وهو الذي يقول أنشدنيه محمد بن يحيى له\n(إذا المرء عادى من يودك صدره ... وكان لمن عاداك خدنا مصافيا)\n(فلا تسألن عما لديه فإنه ... هو الداء لا يخفى بذلك خافيا)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":2,"spl":"إسلام أبيه على يد الرسول","tags":["الفرزدق"],"loc":1898},
{"id":"b112-4","bab":"الجزء 10","sec":"أبوه هو أعطى تميم وبكر","page":"ج10 ص284","text":"أخبرني محمد بن يحيى عن محمد بن زكريا عن عبد الله بن الضحاك عن الهيثم بن عدي عن عوانة قال تراهن نفر من كلب ثلاثة على أن يختاروا من تميم وبكر نفرا ليسائلوهم فأيهم أعطى ولم يسألهم عن نسبهم من هم فهو أفضلهم فاختار كل رجل منهم رجلا والذين اختيروا عمير بن السليك بن قيس بن مسعود الشيباني وطلبة بن قيس بن عاصم المنقري وغالب بن صعصعة المجاشعي أبو الفرزدق فأتوا ابن السليك فسألوه مائة ناقة فقال من أنتم فانصرفوا عنه ثم أتوا طلبة بن قيس فقال لهم مثل قول الشيباني فأتوا غالبا فسألوه فأعطاهم مائة ناقة وراعيها ولم يسألهم من هم فساروا بها ليلة ثم ردوها وأخذ صاحب غالب الرهن وفي ذلك يقول الفرزدق\n(وإذا ناحبت كلب على الناس أيهم ... أحق بتاج الماجد المتكرم)\n(على نفر هم من نزار ذوي العلا ... وأهل الجراثيم التي لم تهدم)\n(فلم يجز عن أحسابهم غير غالب ... جرى بعنان كل أبيض خضرم)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":3,"spl":"أبوه هو أعطى تميم وبكر — مباراة في الكرم بين أبيه وسحيم بن وثيل — قيد نفسه حتى حفظ القرآن","tags":["الفرزدق"],"loc":1899},
{"id":"b112-6","bab":"الجزء 10","sec":"مباراة في الكرم بين أبيه وسحيم بن وثيل — قيد نفسه حتى حفظ القرآن","page":"ج10 ص285 – ج10 ص286","text":"أخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة عن جهم السليطي عن إياس بن شبة عن عقال بن صعصعة قال أجدبت بلاد تميم وأصابت بني حنظلة سنة في خلافة عثمان فبلغهم خصب عن بلاد كلب بن وبرة فانتجعتها بنو حنظلة فنزلوا أقصى الوادي وتسرع غالب بن صعصعة فيهم وحده دون بني مالك بن حنظلة ولم يكن مع بني يربوع من بني مالك غير غالب فنحر ناقته فأطعمهم إياها فلما وردت إبل سحيم بن وثيل الرياحي حبس منها ناقة فنحرها من غد فقيل لغالب إنما نحر سحيم مواءمة لك أي مساواة لك فضحك غالب\nوقال كلا ولكنه امرؤ كريم وسوف أنظر في ذلك فلما وردت إبل غالب حبس منها ناقتين فنحرهما فأطعمهما بني يربوع فعقر سحيم ناقتين فقال غالب الآن علمت انه يوائمني فعقر غالب عشرا فأطعمها بني يربوع فعقر سحيم عشرا فلما بلغ غالبا فعله ضحك وكانت إبله ترد لخمس فلما وردت عقرها كلها عن آخرها فالمكثر يقول كانت أربعمائة والمقل يقول كانت مائة فأمسك سحيم حينئذ ثم إنه عقر في خلافة علي بن أبي\nطالب صلوات الله عليه بكناسة الكوفة مائتي ناقة وبعير فخرج الناس بالزنابيل والأطباق والحبال لأخذ اللحم ورآهم علي عليه السلام فقال أيها الناس لا يحل لكم إنما أهل بها لغير الله عز و جل قال فحدثني من حضر ذلك قال كان الفرزدق يومئذ مع أبيه وهو غلام فجعل غالب يقول يا بني اردد علي والفرزدق يردها عليه ويقول له يا أبت اعقر قال جهم فلم يغن عن سحيم فعله ولم يجعل كغالب إذ لم يطق فعله\nحدثني محمد بن يحيى عن محمد بن القاسم يعني أبا العيناء عن أبي زيد النحوي عن أبي عمرو قال جاء غالب أبو الفرزدق إلى علي بن أبي طالب صلوات الله عليه بالفرزدق بعد الجمل بالبصرة فقال إن ابني هذا من شعراء مضر فاسمع منه\nقال علمه القرآن فكان ذلك في نفس الفرزدق فقيد نفسه في وقت وآلى لا يحل قيده حتى يحفظ القرآن قال محمد بن يحيى فقد صح لنا أن الفرزدق كان شاعرا موصوفا أربعا وسبعين سنة وندع ما قبل ذلك لأن مجيئه به بعد الجمل على الاستظهار كان في سنة ست وثلاثين وتوفي الفرزدق في سنة عشر ومائة في أول خلافة هشام هو وجرير والحسن البصري وابن سيرين في ستة أشهر وحكي ذلك\nعن جماعة منهم الغلابي عن ابن عائشة عن أبيه أخبرني محمد بن يحيى الصولي عن الغلابي عن ابن عائشة أيضا عن أبيه قال قال الفرزدق أيضا كنت أجيد الهجاء في أيام عثمان قال ومات غالب أبو الفرزدق في أول أيام معاوية ودفن بكاظمة فقال الفرزدق يرثيه\n(لقد ضمت الأكفان من آل دارم ... فتى فائض الكفين محض الضرائب)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":3,"spl":"أبوه هو أعطى تميم وبكر — مباراة في الكرم بين أبيه وسحيم بن وثيل — قيد نفسه حتى حفظ القرآن","tags":["الفرزدق","الحب والغزل","الهجاء"],"loc":1900},
{"id":"b112-7","bab":"الجزء 10","sec":"المفضل الضبي يفاضل بينه وبين جرير","page":"ج10 ص287","text":"أخبرني حبيب المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عمران الضبي قال حدثني جعفر بن محمد العنبري عن خالد ابن أم كلثوم قال قيل للمفضل الضبي الفرزدق أشعر أم جرير قال الفرزدق قال قلت ولم قال لأنه قال بيتا هجا فيه قبيلتين ومدح فيه قبيلتين وأحسن في ذلك فقال\n(عجبت لعجل إذ تهاجي عبيدها ... كما آل يربوع هجوا آل دارم)\nقيل له قد قال جرير\n(إن الفرزدق والبعيث وأمه ... وأبا البعيث لشر ما إستار)\nفقال وأي شيء أهون من أن يقول إنسان فلان وفلان وفلان والناس كلهم بنو الفاعلة أخبرني عبد الله بن مالك قال حدثنا محمد بن حبيب قال حدثني موسى بن طلحة\nقال قال أبو عبيدة معمر بن المثنى كان الشعراء في الجاهلية من قيس وليس في الإسلام مثل حظ تميم في الشعر وأشعر تميم جرير والفرزدق ومن بني تغلب الأخطل\nقال يونس بن حبيب ما ذكر جرير والفرزدق في مجلس شهدته قط فاتفق المجلس على أحدهما قال وكان يونس فرزدقيا أخبرني عمي عن محمد بن رستم الطبري عن أبي عثمان المازني قال مر الفرزدق ابن ميادة الرماح والناس حوله وهو ينشد\n(لو أن جميع الناس كانوا بربوة ... وجئت بجدي ظالم وابن ظالم)\n(لظلت رقاب الناس خاضعة لنا ... سجودا على أقدامنا بالجماجم)\nسمعه الفرزدق فقال أما والله يا بن الفارسية لتدعنه لي أو لأنبشن أمك من قبرها فقال له بان ميادة خذه لا بارك الله لك فيه فقال الفرزدق\n(لو أن جميع الناس كانوا بربوة ... وجئت بجدي دارم وابن دارم)\n(لظلت رقاب الناس خاضعة لنا ... سجودا على أقدامنا بالجماجم)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":4,"spl":"المفضل الضبي يفاضل بينه وبين جرير — هو وجرير يتشاكيان عند يزيد بن عبد الملك","tags":["الفرزدق","الهجاء"],"loc":1901},
{"id":"b112-8","bab":"الجزء 10","sec":"هو وجرير يتشاكيان عند يزيد بن عبد الملك","page":"ج10 ص288","text":"أخبرني عمي عن الكراني عن أبي فراس الهيثم بن فراس قال\nحدثني ورقة بن معروف عن حماد الراوية قال دخل جرير والفرزدق على يزيد بن عبد الملك وعنده بنية لها يشمها فقال جرير ما هذه يا أمير المؤمنين فيها عندك\nقال بنية لي قال بارك الله لأمير المؤمنين فيها فقال الفرزدق إن يكن دارم يضرب فيها فهي أكرم العرب ثم أقبل يزيد على جرير فقال مالك والفرزدق\nقال إنه يظلمني ويبغي علي فقال الفرزدق وجدت آبائي يظلمون آباءه فسرت فيه بسيرتهم قال جرير وأما والله لتردن الكبائر على أسافلها سائر اليوم فقال الفرزدق أما بك يا حمار بني كليب فلا ولكن إن شاء صاحب السرير فلا والله ما لي كفء غيره فجعل يزيد يضحك أخبرنا عبد الله بن مالك عن محمد بن حبيب عن ابن الأعرابي عن حماد الراوية\nقال أنشدني الفرزدق يوما شعرا له ثم قال لي أتيت الكلب يعني جريرا قلت نعم قال أفأنا أشعر أم هو قلت أنت في بعض وهو في بعض قال لم تناصحني\nقال قلت هو أشعر منك إذا أرخي من خناقه وأنت أشعر منه إذا خفت أو رجوت قال قضيت لي والله عليه وهل الشعر إلا في الخير والشر قال وروي عن أبي الزناد عن أبيه قال قال لي جرير يا أبا عبد الرحمن أنا أشعر أم هذا الخبيث يعني الفرزدق وناشدني لأخبرنه فقلت لا والله ما يشاركك ولا يتعلق بك في النسيب قال أوه قضيت والله له علي أنا والله أخبرك ما دهاني إلا أني\nهاجيت كذا وكذا شاعرا فسمى عددا كثيرا وأنه تفرد لي وحدي","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":4,"spl":"المفضل الضبي يفاضل بينه وبين جرير — هو وجرير يتشاكيان عند يزيد بن عبد الملك","tags":["الفرزدق","الحب والغزل"],"loc":1902},
{"id":"b112-9","bab":"الجزء 10","sec":"خبره مع النوار ابنة عمه","page":"ج10 ص290","text":"أخبرني عبد الله قال قال المازني قال أبو علي الحرمازي كان من خبر الفرزدق والنوار ابنة أعين بن صعصعة بن ناجية بن عقال المجاشعي وكانت ابنة عمه أنه خطبها رجل من بني عبد الله بن دارم فرضيته وكان الفرزدق وليها فأرسلت إليه أن زوجني من هذا الرجل فقال لا أفعل أو تشهديني أنك قد رضيت بمن زوجتك ففعلت فلما توثق منها\nقال أرسلي إلى القوم فليأتوا فجاءت بنو عبد الله بن دارم فشحنوا مسجد بني مجاشع وجاء الفرزدق فحمد الله وأثنى عليه ثم قال قد علمتم أن النوار قد ولتني أمرها وأشهدكم أني قد زوجتها نفسي على مائة ناقة حمراء سوداء الحدقة فنفرت من ذلك وأرادت الشخوص إلى ابن الزبير حين أعياها أهل البصرة ألا يطلقوها من الفرزدق حتى يشهد لها الشهود وأعياها الشهود أن يشهدوا لها اتقاء الفرزدق وابن الزبير يومئذ أمير الحجاز والعراق يدعى له بالخلافة فلم تجد من يحملها وأتت فتية من بني عدي بن عبد مناة بن أد يقال لهم بنو أم النسير فسألتهم برحم تجمعهم وإياها وكانت بينها وبينهم قرابة فأقسمت عليهم أمها ليحملنها فحملوها فبلغ ذلك الفرزدق فاستنهض عدة من أهل البصرة فأنهضوه وأوقروا له عدة من الإبل وأعين بنفقة فتبع النوار وقال\n(أطاعت بني أم النسير فأصبحت ... على شارف ورقاء صعب ذلولها)\n(وإن الذي أمسى يخبب زوجتي ... كماش إلى أسد الشرى يستبيلها)\nأدركها وقد قدمت مكة فاستجارت بخولة بنت منظور بن زبان بن سيار الفزاري وكانت عند عبد الله بن الزبير فلما قدم الفرزدق مكة اشرأب الناس إليه ونزل على بني عبد الله بن الزبير فاستنشدوه واستحدثوه ثم شفعوا له إلى أبيهم فجعل يشفعهم في الظاهر حتى إذا صار إلى خولة قلبته عن رأيه فمال إلى النوار فقال الفرزدق في ذلك\n(أما بنوه فلم تقبل شفاعتهم ... وشفعت بنت منظور بن زبانا)\n(ليس الشفيع الذي يأتيك مؤتزرا ... مثل الشفيع الذي يأتيك عريانا)\nعريب في هذا البيت خفيف رمل قال وسفر بينهما رجال من بني تميم كانوا بمكة فاصطلحا على أن يرجعا إلى البصرة ولا يجمعهما ظل ولا كن حتى يجمعا في أمرهما ذلك بني تميم ويصيرا على حكمهم ففعلا فلما صارا إلى البصرة رجعت إليه النوار بحكم عشيرتها قال وقال غير الحرمازي إن ابن الزبير قال للفرزدق جئني بصداقها\nوإلا فرقت بينكما فقال الفرزدق أنا في بلاد عربة فكيف أصنع قالوا له عليك بسلم بن زياد فإنه محبوس في السجن يطالبه ابن الزبير بمال فأتاه فقص عليه قصته قال كم صداقها قال أربعة آلاف درهم فأمر له بها وبألفين للنفقة فقال الفرزدق\n(دعي مغلقي الأبواب دون فعالهم ... ولكن تمشى بي هبلت إلى سلم)\n(إلى من يرى المعروف سهلا سبيله ... ويفعل أفعال الرجال التي تنمي)\nال فدفعها إليه ابن الزبير فقال الفرزدق\n(هلمي لابن عمك لا تكوني ... كمختار على الفرس الحمارا)\nقال فجاء بها إلى البصرة وقد أحبلها فقال جرير في ذلك\n(ألا تلكم عرس الفرزدق جامحا ... ولو رضيت رمح استه لاستقرت)\nأجابه الفرزدق وقال\n(وأمك لو لاقيتها بطمرة ... وجاءت بها جوف استها لاستقرت)\nقال الفرزدق وهو يخاصم النوار\n(تخاصمني وقد أولجت فيها ... كرأس الضب يلتمس الجرادا)\nال الحرماني ومكثت النوار عنده زمانا ترضى عنه أحيانا وتخاصمه أحيانا وكانت النوار امرأة صالحة فلم تزل تشمئز منه وتقول له ويحك\nأنت تعلم أنك إنما تزوجت بي ضغطة وعلى خدعة ثم لا تزال في كل ذلك حتى حلفت بيمين موثقة ثم حنثت وتجنبت فراشه فتزوج عليها امرأة يقال لها جهيمة من بني النمر بن قاسط حلفاء لبني الحارث بن عباد بن ضبيعة وأمها الخميصة من بني الحارث بن عباد فنافرته الخميصة واستعدت عليه فأنكرها الفرزدق وقال إنها مني بريء طالق وطلق ابنتها وقال\n(إن الخميصة كانت لي ولابنتها ... مثل الهراسة بين النعل والقدم)\n(إذا أتت أهلها مني مطلقة ... فلن أرد عليها زفرة الندم)\nعل يأتي النوار وبه ردع الخلوق وعليه الأثر فقالت له النوار هل تزوجتها إلا هدادية تعني حيا من أزد عمان فقال الفرزدق في ذلك\n(تريك نجوم الليل والشمس حية ... كرام بنات الحارث بن عباد)\n(أبوها الذي قاد النعامة بعد ما ... أبت وائل في الحرب غير تماد)\n(نساء أبوهن الأعز ولم تكن ... من الأزد في جاراتها وهداد)\n(ولم يك في الحي الغموض محلها ... ولا في العمانيين رهط زياد)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":5,"spl":"خبره مع النوار ابنة عمه","tags":["الفرزدق","المديح"],"song":1,"loc":1903},
{"id":"b112-10","bab":"الجزء 10","sec":"خبره مع النوار ابنة عمه","page":"ج10 ص290","text":"(عدلت بها ميل النوار فأصبحت ... وقد رضيت بالنصف بعد بعاد)\nقال فلم تزل النوار ترققه وتستعطفه حتى أجابها إلى طلاقها وأخذ عليها ألا تفارقه ولا تبرح من منزله ولا تتزوج رجلا بعده ولا تمنعه من مالها ما كانت تبذله له وأخذت عليه أن يشهد الحسن البصري على طلاقها ففعل ذلك\nقال المازني وحدثني محمد بن روح العدوي عن أبي شفقل راوية الفرزدق قال ما استصحب الفرزدق أحدا غيري وغير راوية آخر وقد صحب النوار رجال كثيرة إلا أنهم كانوا يلوذون بالسواري خوفا من أن يراهم الفرزدق فأتيا الحسن فقال له الفرزدق يا أبا سعيد\nقال له الحسن ما تشاء قال أشهد أن النوار طالق ثلاثا فقال الحسن قد شهدنا فلما انصرفنا قال يا أبا شفقل قد ندمت فقلت له والله إني لأظن أن دمك يترقرق أتدري من أشهدت والله لئن رجعت لترجمن بأحجارك فمضى وهو يقول\n(ندمت ندامة الكسعي لما ... غدت مني مطلقة نوار)\n(ولو أني ملكت يدي وقلبي ... لكان علي للقدر الخيار)\n(وكانت جنتي فخرجت منها ... كآدم حين أخرجه الضرار)\n(وكنت كفاقئ عينيه عمدا ... فأصبح ما يضيء له النهار)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":6,"spl":"خبره مع النوار ابنة عمه — يهجو بني قيس لأنهم ألجأوا النوار","tags":["الفرزدق","الرواية والكتابة"],"loc":1904},
{"id":"b112-11","bab":"الجزء 10","sec":"يهجو بني قيس لأنهم ألجأوا النوار","page":"ج10 ص294","text":"وأخبرني بخبره مع النوار أحمد بن عبد العزيز قال حدثنا عمر بن\nشبة قال حدثني محمد بن يحيى عن أبيه يحيى بن علي بن حميد أن النوار لما كرهت الفرزدق حين زوجها نفسه لجأت إلى بني قيس بن عاصم المنقري ليمنعوها فقال الفرزدق فيهم\n(بني عاصم لا تجنبوها فإنكم ... ملاجئ للسوءات دسم العمائم)\n(بني عاصم لو كان حيا أبوكم ... للام بنيه اليوم قيس بن عاصم)\nبلغهم ذلك الشعر فقالوا له والله لئن زدت على هذين البيتين لنقتلنك غيلة وخلوه والنوار وأرادت منافرته إلى ابن الزبير فلم يقدر أحد على أن يكريها خوفا منه ثم إن قوما من بني عدي يقال لهم بنو أم النسير أكروها فقال الفرزدق\n(ولولا أن يقول بنو عدي ... ألم تك أم حنظلة النوار)\n(أتتكم يا بني ملكان عني ... قواف لا تقسمها التجار)\nقال فيهم أيضا\n(لعمري لقد أردى النوار وساقها ... إلى البور أحلام خفاف عقولها)\n(أطاعت بني أم النسير فأصبحت ... على قتب يعلو الفلاة دليلها)\n(وقد سخطت مني النوار الذي ارتضى ... به قبلها الأزواج خاب رحيلها)\n(وإن امرأ أمسى يخبب زوجتي ... كساع إلى أسد الشرى يستبيلها)\n(ومن دون أبواب الأسود بسالة ... وبسطة أيد يمنع الضيم طولها)\n(وإن أمير المؤمنين لعالم ... بتأويل ما وصى العباد رسولها)\n(فدونكها يا بن الزبير فإنها ... مولعة يوهي الحجارة قيلها)\n(وما جادل الأقوام من ذي خصومة ... كورهاء مشنوء إليها حليلها)\nلما قدمت مكة نزلت على تماضر بنت منظور بن زبان زوجة عبد الله ابن الزبير ونزل الفرزدق بحمزة بن عبد الله بن الزبير ومدحه بقوله\n(أمسيت قد نزلت بحمزة حاجتي ... إن المنوه باسمه الموثوق)\n(بأبي عمارة خير من وطئ الحصا ... وجرت له في الصالحين عروق)\n(بين الحواري الأعز وهاشم ... ثم الخليفة بعد والصديق)\nنى في هذه الأبيات ابن سريج رملا بالبنصر قال فجعل أمر النوار يقوى وأمر الفرزدق يضعف فقال\n(أما بنوه فلم تقبل شفاعتهم ... وشفعت بنت منظور بن زبانا)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":6,"spl":"خبره مع النوار ابنة عمه — يهجو بني قيس لأنهم ألجأوا النوار","tags":["الفرزدق"],"loc":1905},
{"id":"b112-12","bab":"الجزء 10","sec":"ملاحاة بينه وبين ابن الزبير","page":"ج10 ص296","text":"وقال ابن الزبير للنوار إن شئت فرقت بينكما وقتلته فلا يهجونا أبدا وإن شئت سيرته إلى بلاد العدو فقالت ما أريد واحدة منهما فقال\nلها فإنه ابن عمك راغب فأزوجك أياه قالت نعم فزوجها منه فكان الفرزدق يقول خرجنا ونحن متحابين قال وكان الفرزدق قال لعبد الله بن الزبير وقد توجه الحكم عليه إنما تريد أن أفارقها فتثب عليها وكان ابن الزبير حديدا فقال له هل أنت وقومك إلا جالية العرب ثم أمر به فأقيم وأقبل على من حضر فقال إن بني تميم كانوا وثبوا على البيت قبل الإسلام بمائة وخمسين سنة فاستلبوه فاجتمعت العرب عليها لما انتهكت منه ما لم ينتهكه أحد قط فأجلتها من ارض تهامة قال فلقي الفرزدق بعض الناس فقال إيه يعيرنا ابن الزبير بالجلاء اسمع ثم قال\n(فإن تغضب قريش أو تغضب ... فإن الأرض توعبها تميم)\n(هم عدد النجوم وكل حي ... سواهم لا تعد له نجوم)\n(ولولا بيت مكة ما ثويتم ... بها صح المنابت والأروم)\n(بها كثر العديد وطاب منكم ... وغيركم أخيذ الريش هيم)\n(فمهلا عن تعلل من غدرتم ... بخونته وعذبه الحميم)\n(أعبد الله مهلا عن أداتي ... فإني لا الضعيف ولا السؤوم)\n(ولكني صفاة لم تدنس ... تزل الطير عنها والعصوم)\n(أنا ابن العاقر الخور الصفايا ... بضوى حين فتحت العكوم)\nال فبلغ هذا الشعر ابن الزبير وخرج للصلاة فرأى الفرزدق في طريقه فغمز عنقه فكاد يدقها ثم قال\n(لقد أصبحت عرس الفرزدق ناشزا ... ولو رضيت رمح استه لاستقرت)\nقال هذا الشعر لجعفر بن الزبير وقيل إن الذي كان تقرر عليه عشرة آلاف درهم وإن سلم بن زياد أمر له بعشرين ألف درهم مهرا ونفقة فقبضها فقالت له زوجته أم عثمان بنت عبد الله بن عمرو بن أبي العاص الثقفية أتعطي عشرين ألف درهم وأنت محبوس فقال\n(ألا بكرت عرسي تلوم سفاهة ... على ما مضى مني وتأمر بالبخل)\n(فقلت لها والجود مني سجية ... وهل يمنع المعروف سوا له مثلي)\n(ذريني فإني غير تارك شيمتي ... ولا مقصر طول الحياة عن البذل)\n(ولا طارد ضيفي إذا جاء طارقا ... وقد طرق الأضياف شيخي من قبلي)\n(أأبخل إن البحل ليس بمخلدي ... ولا الجود يدنيني إلى الموت والقتل)\n(أبيع بني حرب بآل خويلد ... وما ذاك عند الله في البيع بالعدل)\n(وليس ابن مروان الخليفة مشبها ... لفحل بني العوام قبح من فحل)\n(فإن تظهروا لي البخل آل خويلد ... فما دأبكم دأبي ولا شكلكم شكلي)\n(وإن تقهروني حين غابت عشيرتي ... فمن عجب الأيام أن تقهروا مثلي)\nفلما اصطلحا ورضيت به ساق إليها مهرها ودخل بها وأحبلها قبل أن يخرج من مكة ثم خرجا وهما عديلان في محمل وأخبرني أبو خليفة عن محمد بن سلام عن إبراهيم بن حبيب بن الشهيد بنحو من هذه القصة قال عمر بن شبة قال الفرزدق في خبره\n(يا حمز هل لك في ذي حاجة عرضت ... أنضاؤه بمكان غير ممطور)\n(فأنت أحرى قريش أن تكون لها ... وأنت بين أبي بكر ومنظور)\n(بين الحواري والصديق في شعب ... ثبتن في طنب الإسلام والخير)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":7,"spl":"ملاحاة بينه وبين ابن الزبير","tags":["الفرزدق"],"loc":1906},
{"id":"b112-13","bab":"الجزء 10","sec":"كانت القبائل تتقي هجاءه","page":"ج10 ص299","text":"أخبرنا أبو خليفة قال حدثنا محمد بن سلام قال حدثنا عبد القاهر بن السري السلمي قال كان فتى من بني حرام شويعر هجا الفرزدق قال فأخذناه فأتينا به الفرزدق وقلنا هذا بين يديك فإن شئت فاضرب وإن شئت فاحلق فلا عدوى عليك ولا قصاص قد برئنا إليك منه قال فخلى سبيله وقال\n(فمن يك خائفالأذاة شعري ... فقد أمن الهجاء بنو حرام)\n(هم قادوا سفيههم وخافوا ... قلائد مثل أطواق الحمام)\nقال ابن سلام وحدثني عبد القاهر قال مر الفرزدق بمجلسنا مجلس بني حرام ومعنا عنبسة مولى عثمان بن عفان فقال يا أبا فراس متى تذهب إلى الآخرة\nقال وما حاجتك إلى ذاك يا أخي قال أكتب معك إلى ابي قال أنا لا أذهب إلى حيث أبوك أبوك في النار اكتب إليه مع ريالويه واصطقانوس أخبرني الحسن بن يحيى عن حماد عن أبيه\nقال أخبرني مخبر عن خالد بن كلثوم الكلبي قال مررت بالفرزدق وقد كنت دونت شيئا من شعره وشعر جرير وبلغه ذلك فاستجلسني فجلست إليه وعذت بالله من شره وجعلت أحدثه حديث أبيه وأذكر له ما يعجبه ثم\nقلت له إني لأذكر يوم لقبك بالفرزدق قال وأي يوم قلت مررت به وأنت صبي فقال له بعض من كان يجالسه كأن ابنك هذا الفرزدق دهقان الحيرة في تيهه وأبهته فسماك بذلك فأعجبه هذا القول وجعل يستعيد ثم\nقال أنشدني بعض أشعار ابن المراغة في فجعلت أنشده حتى انتهيت ثم قال فأنشد نقائضها التي أجبته بها فقلت ما أحفظها فقال يا خالد أتحفظ ما قاله في ولا تحفظ تفائضه والله لأهجون كلبا هجاء يتصل عاره بأعقابها إلى يوم القيامة إن لم تقم حتى تكتب نقائضها أو تحفظها وتنشدنيها فقلت أفعل فلزمته شهرا حتى حفظت نقائضها وأنشدته إياها خوفا من شره","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":8,"spl":"كانت القبائل تتقي هجاءه","tags":["الفرزدق","الهجاء","الرواية والكتابة"],"loc":1907},
{"id":"b112-14","bab":"الجزء 10","sec":"زواجه من حدراء بنت زيق","page":"ج10 ص301","text":"أخبرني عبد الله بن مالك قال حدثنا محمد بن حبيب قال حدثني الأصمعي قال تزوج الفرزدق حدراء بنت زيق بن بسطام بن قيس الشيباني وخاصمته النوار وأخذت بلحيته فجاذبها وخرج عنها مغضبا وهو يقول\n(قامت نوار إلي تنتف لحيتي ... تنتاف جعدة لحية الخشخاش)\n(كلتاهما أسد إذا ما أغضبت ... وإذا رضين فهن خير معاش)\nال والخشخاش رجل من عنزة وجعدة امرأته فجاءت جعدة إلى النوار فقالت ما يريد مني الفرزدق أما وجد لامرأته أسوة غيري وقال الفرزدق يفضل عليها حدراء\n(لعمري لأعرابية في مظلة ... تظل بروقي بيتها الريح تخفق)\n(أحب إلينا من ضناك ضفنة ... إذا وضعت عنها المراويح تغرق)\n(كريم غزال أو كدرة غائص ... يكاد إذا مرت لها الأرض تشرق)\nلما سمعت النوار ذلك أرسلت إلى جرير وقالت للفرزدق والله لأخزينك يا فاسق فجاء جرير فقالت له أما ترى ما قال الفاسق وشكته إليه وأنشدته شعره فقال جرير أنا أكفيك وأنشأ يقول\n(ولست بمعطي الحكم عن شف منصب ... ولا عن بنات الحنظليين راغب)\n(وهن كماء المزن يشفى به الصدى ... وكانت ملاحا غيرهن المشارب)\n(لقد كنت أهلا أن يسوق دياتكم ... إلى آل رزيق أن يعيبك عائب)\n(وما عدلت ذات الصليب ظعينة ... عتيبة والردفان منها وحاجب)\n(أأهديت يا زيق بن بسطام ظبية ... إلى شر من تهدى إليه القرائب)\n(ألا ربما لم نعط زيقا بحكمه ... وأدى إلينا الحكم والغل لازب)\n(حوينا أبا زيق وزيقا وعمه ... وجدة زيق قد حوتها المقانب)\nفأجابه الفرزدق فقال\n(تقول كليب حين مثت سبالها ... وأعشب من مروتها كل جانب)\n(لسواق أغنام رعتهن أمه ... إلى أن علاها الشيب فوق الذوائب)\n(ألست إذا القعساء مرت براكب ... إلى آل بسطام بن قيس بخاطب)\n(وقالوا سمعنا أن حدراء زوجت ... على مائة شم الذرى والغوارب)\n(فلو كنت من أكفاء حدراء لم تلم ... على دارمي بين ليلى وغالب)\n(فنل مثلها من مثلهم ثم أمهم ... بملكك من مال مراح وعازب)\n(وإني لأخشى إن خطبت إليهم ... عليك الذي لاقى يسار الكواعب)\n(ولو تنكح الشمس النجوم بناتها ... نكحنا بنات الشمس قبل الكواكب)\nفي المناقضات التي دارت بين الفرزدق وجرير حول زواج بنت زيق قال جرير أبياته التي أولها\n(يا زيق أنكحت قينا في استه حمم ... يا زيق ويحك من أنكحت يا زيق)\n(أين الألى أنزلوا النعمان ضاحية ... أم أين أبناء شيبان الغرانيق)\n(يا رب قائلة بعد البناء بها ... لا الصهر راض ولا ابن القين معشوق)\n(غاب المثنى فلم يشهد نجيكما ... والحوفزان ولم يشهدك مفروق)\nالفرزدق يقول لجرير\n(إن كان أنفك قد أعياك تحمله ... فاركب أتانك ثم اخطب إلى زيق)\nخبرني الحسن بن يحيى عن حماد عن أبيه عن الهيثم بن عدي عن زكريا بن ثباة الثقفي قال أنشدني الفرزدق قصيدته التي رثى فيها ابنه فلما انتهى إلى قوله\n(بفي الشامتين الصخر إن كان مسني ... زرية شبل مخدر في الضراغم)\nقال يا أبا يحيى أرأيت ابني قلت لا قال والله ما كان يساوي عباءته","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":9,"spl":"زواجه من حدراء بنت زيق","tags":["الفرزدق"],"loc":1908},
{"id":"b112-15","bab":"الجزء 10","sec":"لبطة بن الفرزدق ينشد لأبيه","page":"ج10 ص304","text":"قال إسحاق حدثني أبو محمد العبدي عن اليربوعي عن أبي نصر قال قدم لبطة بن الفرزدق الحيرة فمر بقوم من بني تغلب فاستقراهم فقروه ثم قالوا له من أنت قال ابن شاعركم ومادحكم وأنا والله ابن الذي يقول فيكم\n(أضحى لتغلب من تميم شاعر ... يرمي الأعادي بالقريض الأثقل)\n(إن غاب كعب بني جعيل عنهم ... وتنمر الشعراء بعد الأخطل)\n(يتباشرون بموته ووراءهم ... مني لهم قطع العذاب المرسل)\nقالوا له فأنت ابن الفرزدق إذا قال أنا هو فتنادوا يا آل تغلب اقضوا حق شاعركم والذائد عنكم في ابنه فجعلوا له مائة ناقة وساقوها إليه فانصرف بها أخبرنا أبو خليفة عن محمد بن سلام قال أتى الفرزدق عبد الله بن مسلم الباهلي فسأله فثقل عليه الكثير وخشيه في القليل وعنده عمرو بن عفراء الضبي راوية الفرزدق وقد وكان هجاه جرير لروايته للفرزدق في قوله\n(ونبئت جوابا وسلما يسبني ... وعمرو بن عفري لا سلام على عمرو)\nقال ابن عفراء للباهلي لا يهولنك أمره أنا أرضيه عنك فأرضاه بدون\nما كان هم له به فأعطاه ثلثمائة درهم فقبلها الفرزدق ورضي عنه فبلغه بعد ذلك صنيع عمرو فقال\n(ستعلم يا عمرو بن عفرى من الذي ... يلام إذا ما الأمر غبت عواقبه)\n(نهيت ابن عفرى أن يعفر أمه ... كعفر السلا إذا جررته ثعالبه)\n(فلو كنت ضبيا صفحت ولو سرت ... على قدمي حياته وعقاربه)\n(ولكن ديافي أبوه وأمه ... بحوران يعصرن السليط أقاربه)\n(ولما رأى الدهنا رمته جبالها ... وقالت ديافي مع الشام جانبه)\n(فإن تغضب الدهنا عليك فما بها ... طريق لمرتاد تقاد ركائبه)\n( تضن بمال الباهلي كأنما ... تضن على المال الذي أنت كاسبه وإن امرأ يغتابني لم أطأ له ... حريما ولا ينهاه عني أقاربه كمحتطب يوما أساود هضبة ... أتاه بها في ظلمة الليل حاطبه أحين التقى ناباي وأبيض مسحلي ... وأطرق إطراق الكرى من يجانبه\nقال ابن عفراء وأتاه في نادي قومه اجهد جهدك هل هو إلا أن تسبني والله لا أدع لك مساءة إلا أتيتها ولا تأمرني بشيء إلا اجتنبته ولا\nتنهاني عن شيء إلا ركبته قال فاشهدوا أني أنهاه أن ينيك أمه فضحك القوم وخجل ابن عفرى أخبرنا أبو خليفة عن محمد بن سلام قال حدثنا شعيب بن صخر قال تزوج ذبيان بن أبي ذبيان العدوي من بلعدوية فدعا الناس في وليمته فدعا ابن أبي شيخ الفقيمي فألقى الفرزدق عنده فقال له يا أبا فراس انهض قال إنه لم يدعني قال إن ابن ذبيان يؤتى وإن لم يدع ثم لا تخرج من عنده إلا بجائزة فأتياه فقال الفرزدق حين دخل\n(كم قال لي ابن أبي شيخ وقلت له ... كيف السبيل إلى معروف ذبيان)\n(إن القلوص إذا ألقت جآجئها ... قدام بابك لم نرحل بحرمان)\nال أجل يا أبا فراس فدخل فتغدى عنده وأعطاه ثلثمائة درهم أخبرني أبو خليفة عن محمد بن سلام قال حدثني أبو بكر المدني قال دخل الفرزدق المدينة فوافق فيها موت طلحة بن عبد الرحمن بن عوف الزهري وكان سيدا سخيا شريفا فقال يا أهل المدينة أنتم أذل قوم الله قالوا وما ذاك يا أبا فراس قال غلبكم الموت على طلحة حتى أخذه منكم","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":10,"spl":"لبطة بن الفرزدق ينشد لأبيه","tags":["الفرزدق","الهجاء"],"loc":1909},
{"id":"b112-16","bab":"الجزء 10","sec":"يعطى عروضا بدل النقد","page":"ج10 ص306","text":"وأتى مكة فأتى عمرو بن عبد الله بن صفوان بن أمية بن خلف الجمحي وهو سيد أهل مكة يومئذ وليس عنده نقد حاضر وهو يتوقع\nأعطيته وأعطية ولده وأهله فقال والله يا أبا فراس ما وافقت عندنا نقدا ولكن عروضا إن شئت فعندنا رقيق فرهة فإن شئت أخذتهم قال نعم فأرسل له بوصفاء من بنيه وبني أخيه فقال هم لك عندنا حتى تشخص وجاءه العطاء فأخبره الخبر وفداهم فقال الفرزدق ونظر إلى عبد العزيز بن عبد الله بن خالد بن أسيد وكان يطوف بالبيت الحرام يتبختر\n(تمشي تبختر حول البيت منتخبا ... لو كنت عمرو بن عبد الله لم تزد)\nخبرنا أبو خليفة عن محمد بن سلام قال حدثنا عامر بن أبي عامر وهو صالح بن رستم الخراز قال أخبرني أبو بكر الهذلي قال إنا لجلوس عند الحسن إذ جاء الفرزدق يتخطى حتى جلس إلى جنبه فجاء رجل فقال يا أبا سعيد الرجل يقول لا والله وبلى والله في كلامه قال لا يريد اليمين فقال الفرزدق أو ما سمعت ما قلت في ذلك قال الحسن ما كل ما قلت سمعوا فما قلت قال قلت\n(ولست بمأخوذ بلغو تقوله ... إذا لم تعمد عاقدات العزائم)\nقال فلم ينشب أن جاء رجل آخر فقال يا أبا سعيد نكون في هذه المغازي فنصيب المرأة لها زوج أفيحل غشيانها وإن لم يطلقها زوجها فقال الفرزدق أو ما سمعت ما قلت في ذلك قال الحسن ما كل ما قلت سمعوا فما قلت قال قلت\n(وذات حليل أنكحتنا رماحنا ... حلالا لمن يبني بها لم تطلق)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":11,"spl":"يعطى عروضا بدل النقد — يهجو في شعره إبليس","tags":["الفرزدق","السفر والحج","الوصف والطبيعة"],"loc":1910},
{"id":"b112-17","bab":"الجزء 10","sec":"يهجو في شعره إبليس","page":"ج10 ص308","text":"قال أبو خليفة أخبرني محمد بن سلام وأخبرني محمد بن جعفر قالا أتى الفرزدق الحسن فقال إني هجوت إبليس فاسمع قال لا حاجة لنا بما تقول قال لتسمعن أو لأخرجن فأقول للناس إن الحسن ينهى عن هجاء إبليس قال اسكت فإنك بلسانه تنطق قال محمد بن سلام أخبرني سلام أبو المنذر عن علي بن زيد قال ما سمعت الحسن متمثلا شعرا قط إلا بيتا واحدا وهو قوله\n(الموت باب وكل الناس داخله ... فليت شعري بعد الباب ما الدار)\nال وقال لي يوما ما تقول في قول الشاعر\n(لولا جرير هلكت بجيله ... نعم الفتى وبئست القبيله)\nهجاه أم مدحه قلت مدحه وهجا قومه قال ما مدح من هجي قومه وقال جرير بن حازم ولم أسمعه ذكر شعرا قط إلا\n(ليس من مات فاستراح بميت ... إنما الميت ميت الأحياء)\nقال رجل لابن سيرين وهو قائم يستقبل القبلة يريد أن يكبر أيتوضأ من الشعر فانصرف بوجهه إليه فقال\n(ألا أصبحت عرس الفرزدق ناشزا ... ولو رضيت رمح استه لاستقرت)\nم كبر","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":11,"spl":"يعطى عروضا بدل النقد — يهجو في شعره إبليس","tags":["الفرزدق","الهجاء"],"loc":1911},
{"id":"b112-18","bab":"الجزء 10","sec":"متفرقات من أبياته الشائعة","page":"ج10 ص309","text":"قال ابن سلام وكان الفرزدق أكثرهم بيتا ومقلدا والمقلد المغني المشهور الذي يضرب به المثل من ذلك قوله\n(فيا عجبأ حتى كليب تسبني ... كأن أباها نهشل أو مجاشع)\nقوله\n(ليس الكرام بناحليك أباهم ... حتى يرد إلى عطية نهشل)\nقوله\n(وكنا إذا الجبار صعر خده ... ضربناه حتى تستقيم الأخادع)\nقوله\n(وكنت كذئب السوء لما رأى دما ... بصاحبه يوما أحال على الدم)\nقوله\n(وكنت ترجي ربيع أن تجيء صغارها ... بخير وقد أعيا ربيعا كبارها)\nقوله\n(أكلت دوابرها الإكام فمشيها ... مما وجئن كمشية الإعياء)\nقوله\n(قوارص تأتيني وتحتقرونها ... وقد يملأ القطر الإناء فيفعم)\nقوله\n(أحلامنا تزن الجبال رزانة ... وتخالنا جنا إذا ما نجهل)\nوقوله\n(وإنك إذ تسعى لتدرك دارما ... لأنت المعنى يا جرير المكلف)\nقوله ( فإن تنج مني تنج من ذي عظيمة ... وإلا فإني لا إخالك ناجيا\nقوله\n(ترى كل مظلوم إلينا فراره ... ويهرب منا جهده كل ظالم)\nقوله\n(ترى الناس ما سرنا يسيرون حولنا ... وإن نحن أومأنا إلى الناس وقفوا)\nقوله\n(فسيف بني عبس وقد ضربوا به ... نبا بيدي ورقاء عن رأس خالد)\n(كذاك سيوف الهند تنبو ظباتها ... ويقطعن أحيانا مناط القلائد)\nكان يداخل الكلام وكان ذلك يعجب أصحاب النحو من ذلك قوله يمدح هشام بن إسماعيل المخزومي خال هشام بن عبد الملك\n(وأصبح ما في الناس إلا مملكا ... أبو أمه حي أبوه يقاربه)\nقوله\n(تا الله قد سفهت أمية رأيها ... فاستجهلت سفهاؤها حلماءها)\nقوله\n(ألستم عائجين بنا لعنا ... نرى العرصات أو أثر الخيام)\nفقالوا\n(إن فعلت فأغن عنا ... دموعا غير راقئة السجام)\nقوله\n(فهل أنت إن ماتت أتانك راحل ... إلى آل بسطام بن قيس فخاطب)\nقوله\n(فنل مثلها من مثلهم ثم دلهم ... على دارمي بين ليلى وغالب)\nقوله\n(تعال فإن عاهدتني لا تخونني ... نكن مثل من يا ذئب يصطحبان)\nقوله\n(إنا وإياك إن بلغن أرحلنا ... كمن بواديه بعد المحل ممطور)\nقوله\n(بنى الفاروق أمك وابن أروى ... به عثمان مروان المصابا)\nقوله\n(إلى ملك ما أمه من محارب ... أبوه ولا كانت كليب تصاهره)\nوقوله\n(إليك أمير المؤمنين رمت بنا ... هموم المنا والهوجل المتعسف)\n(وعض زمان يا بن مروان لم يدع ... من المال إلا مسحتا أو مجلف)\nقوله\n(ولقد دنت لك بالتخلف إذ دنت ... منها بلا بخل ولا مبذول)\n(وكأن لون رضاب فيها إذ بدا ... برد بفرع بشامة مصقول)\nقوله فيها لمالك بن المنذر\n(إن ابن ضبارى ربيعة مالكا ... لله سيف صنيعة مسلول)\n(ما نال من آل المعلى قبله ... سيف لكل خليفة ورسول)\n(ما من يدي رجل أحق بما أتى ... من مكرمات عطاية الأخطار)\n(من راحتين يزيد يقدح زنده ... كفاهما ويشد عقد جوار)\nومن قوله\n(إذا جئته أعطاك عفوا ولم يكن ... على ماله حال الندى منك سائله)\n(لدى ملك لا تنصف النعل ساقه ... أجل لا وإن كانت طوالا حمائله)\nقوله ( والشيب ينهض في الشباب كأنه ... ليل يسير بجانبيه نهار","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":12,"spl":"متفرقات من أبياته الشائعة — كان صادقا في مدحه","tags":["الفرزدق","المديح"],"loc":1912},
{"id":"b112-19","bab":"الجزء 10","sec":"كان صادقا في مدحه","page":"ج10 ص311","text":"قال أبو خليفة أخبرنا محمد بن سلام قال حدثني شعيب بن صخر\nعن محمد بن زياد وأخبرني به الجوهري وجحظة عن ابن شبة عن محمد ابن سلام وكان محمد في زمام الحجاج زمانا قال انتهيت إلى الفرزدق بعد موت الحجاج بالردم وهو قائم والناس حوله ينشد مديح سليمان بن عبد الملك\n(وكم أطلقت كفاك من غل بائس ... ومن عقدة ما كان يرجى انحلالها)\n(كثيرا من الأيدي التي قد تكتفت ... فككت وأعناقا عليها غلالها)\nال قلت أنا والله أحدهم فأخذ بيدي وقال أيها الناس سلوه عما أقول والله ما كذبت قط أخبرني جحظة قال حدثني ابن شبة عن محمد بن سلام فذكر مثله وقال فيه والله ما كذبت قط ولا أكذب أبدا","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":12,"spl":"متفرقات من أبياته الشائعة — كان صادقا في مدحه","tags":["الفرزدق","المديح","السفر والحج"],"loc":1913},
{"id":"b112-20","bab":"الجزء 10","sec":"يأبى الحضور إلى يزيد بن المهلب قبل أن يدفع له","page":"ج10 ص312","text":"قال أبو خليفة قال ابن سلام وسمعت الحارث بن محمد بن زياد يقول\nكتب يزيد بن المهلب لما فتح جرحان إلى أخيه مدركة أو مروان احمل إلي الفرزدق فإذا شخص فأعط أهله كذا وكذا ذكر عشرة آلاف درهم فقال له الفرزدق ادفعها إلي قال اشخص وأدفعها إلى أهلك فأبى وخرج وهو يقول\n(دعاني إلى جرجان والري دونه ... لآتيه إني إذا لزءور)\n(لآتي من آل المهلب ثائرا ... بأعراضهم والدائرات تدور)\n(سآبى وتأبى لي تميم وربما ... أبيت فلم يقدر علي أمير)\nال أبو خليفة قال ابن سلام وسمعت سلمة بن عياش قال حبست في السجن فإذا فيه الفرزدق قد حبسه مالك بن المنذر بن الجارود فكان يريد أن يقول البيت فيقول صدره وأسبقه إلى القافية ويجيء إلى القافية فأسبقه إلى الصدر فقال لي ممن أنت\nقلت من قريش قال كل أير حمار من قريش من أيهم أنت قلت من بني عامر بن لؤي قال لئام والله أذلة جاورتهم فكانوا شر جيران قلت ألا أخبرك بأذل منهم وألأم\nقال من قلت بنو مجاشع قال ولم ويلك قلت أنت سيدهم وشاعرهم وابن سيدهم جاءك شرطي مالك حتى أدخلك السجن لم يمنعوك قال قاتلك الله قال أبو خليفة\nقال ابن سلام وكان مسلمة بن عبد الملك على العراق بعد قتل يزيد بن المهلب فلبث بها غير كثير ثم عزله يزيد بن عبد الملك واستعمل عمر بن هبيرة على العراق فأساء عزل مسلمة فقال الفرزدق وأنشدنيه يونس\n(ولت بمسلمة الركاب مودعا ... فارعي فزارة لا هناك المرتع)\n(فسد الزمان وبدلت أعلامه ... حتى أمية عن فزارة تنزع)\n(ولقد علمت إذا فزارة أمرت ... أن سوف تطمع في الإمارة أشجع)\n(وبحق ربك ما لهم ولمثلهم ... في مثل ما نالت فزارة مطمع)\n(عزل ابن بشر وابن عمرو قبله ... وأخو هراة لمثلها يتوقع)\nابن بشر عبد الملك بن بشر بن مروان كان على البصرة أمره عليها مسلمة وابن عمرو سعيد بن حذيفة بن عمرو بن الوليد بن عقبة بن أبي معيط وأخو هراة عبد العزيز بن الحكم بن أبي العاصي ويروى للفرزدق في ابن هبيرة\n(أمير المؤمنين وأنت عف ... كريم لست بالطبع الحريص)\n(أوليت العراق ورافديه ... فزاريا أحذ يد القميص)\n(ولم يك قبلها راعي مخاض ... لتأمنه على وركي قلوص)\n(تفنن بالعراق أبو المثنى ... وعلم أهله أكل الخبيص)\nأنشدني له يونس\n(جهز فإنك ممتار ومبتعث ... إلى فزارة عيرا تحمل الكمرا)\n(إن الفزاري لو يعمى فأطعمه ... أير الحمار طبيب أبرأ البصرا)\n(إن الفزاري لا يشفيه من قرم ... أطايب العير حتى ينهش الذكرا)\n(يقول لما رأى ما في إنائهم ... لله ضيف الفزاريين ما انتظرا)\nلما قدم خالد بن عبد الله القسري واليا على ابن هبيرة حبسه في\nالسجن فنقب له سرب فخرج منه فهرب إلى الشام فقال فيه الفرزدق يذكر خروجه\n(ولما رأيت الأرض قد سد ظهرها ... ولم تر إلا بطنها لك مخرجا)\n(دعوت الذي ناداه يونس بعد ما ... ثوى في ثلاث مظلمات ففرجا)\n(فأصبحت تحت الأرض قد سرت ليلة ... وما سار سار مثلها حين أدلجا)\n(خرجت ولم تمنن عليك شفاعة ... سوى ربذ التقريب من آل أعوجا)\n(أغر من الحو اللهاميم إذ جرى ... جرى بك محبوك القرى غير أفحجا)\n(جرى بك عريان الحماتين ليله ... به عنك أرخى الله ما كان أشرجا)\n(وما احتال محتال كحيلته التي ... بها نفسه تحت الصريمة أولجا)\n(وظلماء تحت الأرض قد خضت هولها ... وليل كلون الطيلساني أدعجا)\n(هما ظلمتا ليل وأرض تلاقتا ... على جامع من همه ما تعوجا)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":13,"spl":"يأبى الحضور إلى يزيد بن المهلب قبل أن يدفع له","tags":["الفرزدق"],"loc":1914},
{"id":"b112-21","bab":"الجزء 10","sec":"هجوه لخالد القسري","page":"ج10 ص315","text":"فحدثني جابر بن جندل قال فقيل لابن هبيرة من سيد العراق قال\nالفرزدق هجاني أميرا ومدحني سوقة وقال الفرزدق لخالد القسري حين قدم العراق أميرا لهشام\n(ألا قطع الرحمن ظهر مطية ... أتتنا تمطى من دمشق بخالد)\n(وكيف يؤم المسلمين وأمه ... تدين بأن الله ليس بواحد)\n(بنى بيعة فيها الصليب لأمه ... وهدم من كفر منار المساجد)\nقال أيضا\n(نزلت بجيلة واسطا فتمكنت ... ونفت فزارة عن قرار المنزل)\nوقال أيضا\n(لعمري لئن كانت بجيلة زانها ... جرير لقد أخزى بجيلة خالد)\nلما قدم العراق خالد أميرا أمر على شرطة البصرة مالك بن المنذر بن الجارود وكان عبد الأعلى بن عبد الله بن عامر يدعي على مالك قرية فأبطلها خالد وحفر النهر الذي سماه المبارك فاعترض عليه الفرزدق فقال\n(أهلكت مال الله في غير حقه ... على النهر المشؤوم غير المبارك)\n(وتضرب أقواما صحاحا ظهورهم ... وتترك حق الله في ظهر مالك)\n(أإنفاق مال الله في غير كنهه ... ومنعا لحق المرملات الضرائك)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":14,"spl":"هجوه لخالد القسري — دخل على الحجاج يستميحه مهر حدراء زوجته","tags":["الفرزدق","الهجاء","المديح"],"loc":1915},
{"id":"b112-22","bab":"الجزء 10","sec":"دخل على الحجاج يستميحه مهر حدراء زوجته","page":"ج10 ص317","text":"أخبرني عبد الله بن مالك قال حدثنا محمد بن حبيب عن الأصمعي قال قال أعين بن لبطة دخل الفرزدق على الحجاج لما تزوج حدراء يستميحه مهرها فقال له تزوجت أعرابية على مائة بعير فقال له عنبسة بن سعيد إنما هي فرائض قيمتها ألفا درهم الفريضة عشرون درهما فقال له الحجاج ليس غيرها يا كعب أعط الفرزدق ألفي درهم\nقال وقدم الفضيل العنزي بصدقات بكر بن وائل فاشترى الفرزدق مائة بعير بألفين وخمسمائة درهم على أن يثبتها له في الديوان قال الفرزدق فصليت مع الحجاج الظهر حتى إذا سلم خرجت فوقفت في الدار فرآني فقال مهيم فقلت إن الفضيل العنزي قدم بصدقات بكر بن وائل وقد اشتريت منه مائة بعير بألفين وخمسمائة درهم على أن تحتسب له في الديوان فإن رأى الأمير أن يأمر لي بإثباتها له فعل فأمر أبا كعب أن يثبت للفضيل ألفين وخمسمائة درهم ونسي ما كان أمر له به\nقال فلما جاء الفرزدق بالإبل قالت له النوار خسرت صفقتك أتتزوج أعرابية نصرانية سوداء مهزولة خمشاء الساقين على مائة من الإبل فقال يعرض بالنوار وكانت أمها وليدة\n(لجارية بين السليل عروقها ... وبين أبي الصهباء من آل خالد)\n(أحق بإغلاء المهور من التي ... ربت تتردى في حجور الولائد)\nفأبت النوار عليه أن يسوقها كلها فحبس بعضها وامتار عليه ما يحتاج إليه أهل البادية ومضى ومعه دليل يقال له أوفى بن خنزير قال أعين فلما كان في أدنى الحي رأوا كبشا مذبوحا فقال الفرزدق يا أوفى هلكت والله حدراء\nقال وما علمك بذلك قال ويقال إن أوفى قال للفرزدق يا أبا فراس لن ترى حدراء فمضوا حتى وقفوا على نادي زيق وهو جالس فرحب به وقال له انزل فإن حدراء قد ماتت وكان زيق نصرانيا فقال قد عرفنا أن نصيبك من ميراثها في دينكم النصف وهو لك عندنا فقال له الفرزدق والله لا أرزؤك منه قطميرا فقال زيق يا بني دارم ما صاهرنا أكرم منكم في الحياة ولا أكرم منكم شركة في الممات فقال الفرزدق\n(عجبت لحادينا المقحم سيره ... بنا موجعات من كلال وظلعا)\n(ليدنينا ممن إلينا لقاؤه ... حبيب ومن دار أردنا لتجمعا)\n(ولو نعلم الغيب الذي من أمامنا ... لكربنا الحادي المطي فأسرعا)\n(يقولون زر حدراء والترب دونها ... وكيف بشيء وصله قد تقطعا)\n(يقول ابن خنزير بكيت ولم تكن ... على امرأة عيني إدخال لتدمعا)\n(وأهون رزء لامرئ غير جازع ... رزئية مرتج الروادف أفرعا)\n(ولست وإن عزت علي بزائر ... ترابا على مرموسة قد تضعضعا)\nقيل إن النوار كانت استعانت بأم هاشم لا بتماضر وأم هاشم أخت تماضر لأن تماضر ماتت عند عبد الله بعد أن ولدت له خبيبا وثابتا ابني\nعبد الله بن الزبير وتزوج بعدها أختها أم هاشم فولدت له هاشما وحمزة وعبادا وفي أم هاشم يقول الفرزدق\n(تروحت الركبان يا أم هاشم ... وهن مناخات لهن حنين)\n(وحبسن حتى ليس فيهن نافق ... لبيع ولا مركوبهن سمين)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":14,"spl":"هجوه لخالد القسري — دخل على الحجاج يستميحه مهر حدراء زوجته","tags":["الفرزدق","الجواري والنساء","السفر والحج"],"loc":1916},
{"id":"b112-23","bab":"الجزء 10","sec":"طلق رهيمة زوجته لأنها نشزت به","page":"ج10 ص318","text":"أخبرنا عبد الله قال حدثنا محمد بن حبيب قال حدثني الأصمعي قال نشزت رهيمة بنت غني بن درهم النمرية بالفرزدق فطلقها وقال يهجوها بقوله\n(لا ينكحن بعدي فتى نمرية ... مرملة من بعلها لبعاد)\n(وبيضاء زعراء المفارق شختة ... مولعة في خضرة وسواد)\n(لها بشر شثن كأن مضمه ... إذا عانقت بعلا مضم قتاد)\n(قرنت بنفسي الشؤم في ورد حوضها ... فجرعته ملحا بماء رماد)\n(وما زلت حتى فرق الله بيننا ... له الحمد منها في أذى وجهاد)\n(تجدد لي ذكرى عذاب جهنم ... ثلاثا تمسيني بها وتغادي)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":15,"spl":"طلق رهيمة زوجته لأنها نشزت به — شعره في ابنته مكية وأمها الزنجية","tags":["الفرزدق","الجواري والنساء","الرواية والكتابة"],"loc":1917},
{"id":"b112-24","bab":"الجزء 10","sec":"يحظى بجارية بنسيئة فتحمل منه","page":"ج10 ص319","text":"أخبرني الحسن بن علي قال حدثني الحسين بن موسى قال قال\nالمدائني لقي الفرزدق جارية لبني نهشل فجعل ينظر إليها نظرا شديدا فقالت له مالك تنظر فو الله لو كان لي ألف حر ما طمعت في واحد منها قال ولم يالخناء قالت لأنك قبيح المنظر سيء المخبر فيما أرى فقال أما والله لو جربتني لعفى خبري على منظري قال ثم كشف لها عن مثل ذراع البكر فتضبعت له عن مثل سنام البكر فعالجها فقالت أنكاح بنسيئة هذا شر القضية قال ويحك ما معي إلا جبتي أفتسلبينني إياها ثم تسنمها فقال\n(أولجت فيها كذراع البكر ... مدملك الرأس شديد الأسر)\n(زاد على شبر ونصف شبر ... كأنني أولجته في جمر)\n(يطير عنه نفيان الشعر ... في شعور الناس يوم النحر)\nال فحملت منه ثم ماتت فبكاها وبكى ولده منها\n(وغمد سلاح قد رزئت فلم أنح ... عليه ولم أبعث عليه البواكيا)\n(وفي جوفه من دارم ذو حفيظة ... لو أن المنايا أنسأته لياليا)\n(ولكن ريب الدهر يعثر بالفتى ... فلم يستطع ردا لما كان جائيا)\n(وكم مثله في مثلها قد وضعته ... وما زلت وثابا أجر المخازيا)\nفقال جرير يعيره\n(وكم لك يا بن القين إن جاء سائل ... من ابن قصير الباع مثلك حامله)\n(وآخر لم تشعر به قد أضعته ... وأوردته رحما كثيرا غوائله)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":15,"spl":"طلق رهيمة زوجته لأنها نشزت به — شعره في ابنته مكية وأمها الزنجية","tags":["الفرزدق","الجواري والنساء"],"loc":1918},
{"id":"b112-25","bab":"الجزء 10","sec":"زواجه من ظبية ابنة حالم وعجزه عنها","page":"ج10 ص321","text":"أخبرني الحسن بن علي الخفاف قال حدثنا محمد بن موسى قال حدثني محمد بن سليمان الكوفي عن أبيه قال تزوج الفرزدق ظبية ابنة حالم من بني مجاشع بعد أن أسن فضعف وتركها عند أمها بالبادية سنة ولم يكن صداقها عنده فكتب إلى أبان بن الوليد البجلي وهو على فارس عامل لخالد بن عبد الله القسري فأعطاه ما سأل وأرضاه فقال يمدحه\n(فلو جمعوا من الخلان ألفا ... فقالوا أعطنا بهم أبانا)\n(لقلت لهم إذا لغبنتموني ... وكيف أبيع من شرط الزمانا)\n(خليل لا يرى المائة الصفايا ... ولا الخيل الجياد ولا القيانا)\n(عطاء دون أضعاف عليها ... ويطعم ضيفه العبط السمانا)\nلعبط الإبل التي لا وجع بها\n(فما أرجو لظبية غير ربي ... وغير أبي الوليد بما أعانا)\n(أعان بهجمة أرضت أباها ... وكانت عنده غلقا رهانا)\nقال أيضا في ذلك\n(لقد طال ما استودعت ظبية أمها ... وهذا زمان رد فيه الودائع)\nوقال حين أراد أن يبني بها\n(أبادر سؤالا بظبية أنني ... أتتني بها الأهوال من كل جانب)\n(بمالئة الحجلين لو أن ميتا ... ولو كان في الأموات تحت النصائب)\n(دعته لألقى الرب عند انتفاضه ... ولو كان تحت الراسيات الرواسب)\nلما ابتنى منها عجز عنها فقال\n(يا لهف نفسي على نعط فجعت به ... حين التقى الركب المحلوق والركب)\nقال جرير\n(وتقول ظبية إذ رأتك محوقلا ... حوق الحمار من الخبال الخابل)\n(إن البلية وهي كل بلية ... شيخ يعلل عرسه بالباطل)\n(لو قد علقت من المهاجر سلما ... لنجوت منه بالقضاء الفاصل)\nال فنشزت منه ونافرته إلى المهاجر وبلغه قول جرير فقال المهاجر لو أتتني بالملائكة معها لقضيت للفرزدق عليها","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":15,"spl":"طلق رهيمة زوجته لأنها نشزت به — شعره في ابنته مكية وأمها الزنجية","tags":["الفرزدق","المديح","الجواري والنساء"],"loc":1919},
{"id":"b112-26","bab":"الجزء 10","sec":"شعره في ابنته مكية وأمها الزنجية","page":"ج10 ص322","text":"قال وكان للفرزدق ابنة يقال لها مكية وكانت زنجية وكان إذا حمي الوطيس وبلغ منه الهجاء يكتني بها ويقول\n(ذا كم إذا ما كنت ذا محميه ... بدارمي أمه ضبيه)\n(صمحمح يكنى أبا مكية ... )\nقال في أمها\n(ويا رب خود من بنات الزنج ... تحمل تنورا شديد الوهج)\n(أقعب مثل القدح الخلنج ... يزداد طيبا عند طول الهرج)\n(مخجتها بالأير أي مخج ... )\nقالت له النوار ريحها مثل ريحك وقال في أم مكية يخاطب النوار\n(فإن يك خالها من آل كسرى ... فكسرى كان خيرا من عقال)\n(وأكثر جزية تهدى إليه ... وأصبر عند مختلف العوالي)\nال وكانت أم النوار خراسانية فقال لها في أم مكية\n(أغرك منها أدمة عربية ... علت لونها إن البجادي أحمر)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":15,"spl":"طلق رهيمة زوجته لأنها نشزت به — شعره في ابنته مكية وأمها الزنجية","tags":["الفرزدق","الهجاء"],"loc":1920,"partial":1},
{"id":"b112-27","bab":"الجزء 10","sec":"يمدح سعيد بن العاص فيحقد عليه مروان","page":"ج10 ص323","text":"حدثني محمد بن الحسن بن دريد قال حدثنا السكن بن سعيد عن محمد بن عباد عن ابن الكلبي قال دخل الفرزدق على سعيد بن العاص وهو والي المدينة لمعاوية فأنشده\n(ترى الغر الجحاجح من قريش ... إذا ما الخطب في الحدثان غالا)\n(وقوفا ينظرون إلى سعيد ... كأنهم يرون به هلالا)\nوعنده كعب بن جعيل فلما فرغ من إنشاده قال كعب هذه والله رؤياي البارحة رأيت كأن ابن مرة في نواحي المدينة وأنا أضم ذلاذلي\nخوفا منه فلما خرج الفرزدق خرج مروان في أثره فقال لم ترض أن نكون قعودا حتى جعلتنا قياما في قولك\n(قياما ينظرون إلى سعيد ... كأنهم يرون به هلالا)\nقال له يا أبا عبد الملك إنك من بينهم صافن فحقد عليه مروان ذلك ولم تطل الأيام حتى عزل سعيد وولي مروان فلم يجد على الفرزدق متقدما حتى قال قصيدته التي قال فيها\n(هما دلتاني من ثمانين قامة ... كما انقض باز أقتم الريش كاسره)\n(فلما استوت رجلاي في الأرض قالتا ... أخي يرجى أم قتيل نحاذره)\n(فقلت ارفعا الأمراس لا يشعروا بنا ... وأقبلت في أعقاب ليل أبادره)\n(أبارد بوابين لم يشعروا بنا ... وأحمر من ساج تلوح مسامره)\nقال له مروان أتقول هذا بين أزواج رسول الله اخرج عن المدينة فذلك قول جرير\n(تدليت تزني من ثمانين قامة ... وقصرت عن باع الندى والمكارم)\nخبرنا ابن دريد قال أخبرنا الرياشي عن محمد بن سلام قال","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":16,"spl":"يمدح سعيد بن العاص فيحقد عليه مروان — خبر آخر في مدحه سعيدا","tags":["الفرزدق","السفر والحج"],"loc":1921},
{"id":"b112-28","bab":"الجزء 10","sec":"خبر آخر في مدحه سعيدا","page":"ج10 ص324","text":"دخل الفرزدق المدينة هاربا من زياد وعليها سعيد بن العاص بن أمية\nابن عبد شمس أميرا من قبل معاوية فدخل على سعيد ومثل بين يديه وهو معتم وفي مجلس سعيد الحطيئة وكعب بن جعيل التغلبي وصاح الفرزدق أصلح الله الأمير أنا عائذ بالله وبك أنا رجل من تميم ثم أحد بني دارم أنا الفرزدق بن غالب قال فأطرق سعيد مليا فلم يجبه فقال الفرزدق رجل لم يصب دما حراما ولا مالا حراما فقال سعيد إن كنت كذلك فقد أمنت فأنشده\n(إليك فررت منك ومن زياد ... ولم أحسب دمي لكما حلالا)\n(ولكني هجوت وقد هجاني ... معاشر قد رضخت لهم سجالا)\n(فإن يكن الهجاء أحل قتلي ... فقد قلنا لشاعرهم وقالا)\n(أرقت فلم أنم ليلا طويلا ... أراقب هل أرى النسرين زالا)\n(عليك بني أمية فاستجرهم ... وخذ منهم لما تخشى حبالا)\n(فإن بني أمية في قريش ... بنوا لبيوتهم عمدا طوالا)\n(ترى الغر الجحاجح من قريش ... إذا ما الأمر في الحدثان غالا)\n(قياما ينظرون إلى سعيد ... كأنهم يرون به هلالا)\nقال فلما قال هذا البيت قال الحطيئة لسعيد هذا والله الشعر لا ما كنت تعلل به منذ اليوم فقال كعب بن جعيل فضلته على نفسك فلا تفضله على غيرك قال بلى والله إنه ليفضلني وغيره يا غلام أدركت من قبلك وسبقت من بعدك ولئن طال عمرك لتبرزن\nثم عبث الحطيئة بالفرزدق فقال يا غلام أنجدت أمك قال لا بل أبي أراد الحطيئة إن كانت أمك أنجدت فقد أصبتها فولدتك إذ شابهتني في الشعر فقال الفرزدق لا بل أبي فوجده لقنا أخبرني ابن دريد قال قال لنا أبو حاتم قال الأصمعي ومن عبثات الفرزدق انه لقي مخنثا فقال له من أين راحت عمتنا فقال له المخنث نفاها الأغر بن عبد العزيز يريد قول جرير\n(نفاك الأغر بن عبد العزيز ... وحقك تنفى من المسجد)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":16,"spl":"يمدح سعيد بن العاص فيحقد عليه مروان — خبر آخر في مدحه سعيدا","tags":["الفرزدق"],"loc":1922},
{"id":"b112-29","bab":"الجزء 10","sec":"جرير يقر له بالغلبة ويلقبه بالعزيز","page":"ج10 ص326","text":"أخبرنا ابن دريد عن الرياشي عن النضر بن شميل قال قال جرير ما قال لي ابن القين بيتا إلا وقد اكتفأته أي قلبته إلا قوله\n(ليس الكرام بناحليك أباهم ... حتى يرد إلى عطية تعتل)\nإني لا أدري كيف أقول فيها وأخبرني ابن دريد قال حدثنا السكن بن سعيد عن محمد بن عباد عن ابن الكلبي عن عوانة بن الحكم قال بينما جرير واقف في المربد وقد ركبه الناس وعمر بن لجأ مواقفه فأنشده عمر جواب قوله\n(يا تيم تيم عدي لا أبا لكم ... لا يقذفنكم في سوأة عمر)\n(أحين صرت سماما يا بني لجأ ... وخاطرت بي عن أحسابها مضر)\nقال عمر جواب هذا\n(لقد كذبت وشر القول أكذبه ... ما خاطرت بك عن أحسابها مضر)\n(ألست نزوة خوار على أمة ... لا يسبق الحلبات اللؤم والخور)\nقد كان الفرزدق رفده بهذين البيتين في هذه القصيدة فقال جرير لما سمعها قبحا لك يا بن لجأ أهذا شعرك كذبت والله ولو مت هذا شعر حنظلي هذا شعر العزيز يعني الفرزدق فأبلس عمر فما رد جوابا وخرج غنيم بن أبي الرقراق حتى أتى الفرزدق فضحك وقال إيه يا بن أبي الرقراق وإن عندك لخبرا قلت خزي أخوك ابن قتب فحدثته فضحك حتى فحص برجليه ثم قال في ساعته\n(وما أنت إن قرما تميم تساميا ... أخا التيم إلا كالوشيظة في العظم)\n(فلو كنت مولى الظلم أو في ثيابه ... ظلمت ولكن لا يدي لك بالظلم)\nما بلغ هذان البيتان جريرا قال ما أنصفني في شعر قط قبل هذا يعني قوله\n(إن قرما تميم تساميا ... )","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":17,"spl":"جرير يقر له بالغلبة ويلقبه بالعزيز — كان ابنه لبطة عاقا به","tags":["الفرزدق"],"loc":1923,"partial":1},
{"id":"b112-30","bab":"الجزء 10","sec":"يغتصب جيد الشعراء","page":"ج10 ص328","text":"أخبرنا ابن دريد قال أخبرنا الرياشي قال كان الفرزدق مهيبا تخافه الشعراء فمر يوما بالشمردل وهو ينشد قصيدته حتى بلغ إلى قوله\n(وما بين من لم يعط سمعا وطاعة ... وبين تميم غير حز الغلاصم)\nال والله لتتركن هذا البيت أو لتتركن عرضك قال خذه على كره مني فهو في قصيدة الفرزدق التي أولها قوله\n(تحن بزوراء المدينة ناقتي ... )\nال وكان الفرزدق يقول خير السرقة ما لا يجب فيه القطع يعني سرقة الشعر أخبرنا ابن دريد عن أبي حاتم عن أبي عبيدة عن الضحاك بن بهلول الفقيمي قال بينما أنا بكاظمة وذو الرمة ينشد قصيدته التي يقول فيها\n(أحين أعاذت بي تميم نساءها ... وجردت تجريد اليماني من الغمد)\nذا راكبان قد تدليا من نعف كاظمة متقنعان فوقفا فلما فرغ ذو الرمة حسر الفرزدق عن وجهه وقال يا عبيد اضممها إليك يعني راويته وهو عبيد أخو بني ربيعة بن حنظلة فقال ذو الرمة نشدتك الله يا أبا فراس إن\nفعلت قال دع ذا عنك فانتحلها في قصيدته وهي أربعة أبيات\n(أحين أعاذت بي تميم نساءها ... وجردت اليماني من الغمد)\n(ومدت بضبعي الرباب ومالك ... وعمرو وشالت من ورائي بنو سعد)\n(ومن آل يربوع زهاء كأنه ... دجى الليل محمود النكاية والورد)\n(وكنا إذا الجبار صعر خده ... ضربناه فوق الأنثيين على الكرد)\nخبرنا ابن دريد قال أخبرنا أبو حاتم عن أبي عبيدة قال اجتمع الفرزدق وجرير وكثير وابن الرقاع عند سليمان بن عبد الملك فقال أنشدونا من فخركم شيئا حسنا فبدرهم الفرزدق فقال\n(وما قوم إذا العلماء عدت ... عروق الأكرمين إلى التراب)\n(بمختلفين إن فضلتمونا ... عليهم في القديم ولا غضاب)\n(ولو رفع السحاب إليه قوما ... علونا في السماء إلى السحاب)\nقال سليمان لا تنطقوا فو الله ما ترك لكم مقالا أخبرنا عبد الله بن مالك قال حدثنا محمد بن عمران الضبي عن سليمان بن أبي سليمان الجوزجاني قال غاب الفرزدق فكتبت النوار تشكو إليه مكية وكتب إليه أهله يشكون سوء خلقها وتبذيها عليهم فكتب إليهم\n(كتبتم عليها أنها ظلمتكم ... كذبتم وبيت الله بل تظلمونها)\n(فإلا تعدوا أنها من نسائكم ... فإن ابن ليلى والد لا يشينها)\n(وإن لها أعمام صدق وإخوة ... وشيخا إذا شاءت تنمر دونها)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":17,"spl":"جرير يقر له بالغلبة ويلقبه بالعزيز — كان ابنه لبطة عاقا به","tags":["الفرزدق","السفر والحج"],"loc":1924,"partial":1},
{"id":"b112-31","bab":"الجزء 10","sec":"كان ابنه لبطة عاقا به","page":"ج10 ص329","text":"قال وكان للفرزدق ثلاثة أولاد يقال لواحد منهم لبطة والآخر حبطة والثالث سبطة وكان لبطة من العققة فقال له الفرزدق\n(أإن أرعشت كفا أبيك وأصبحت ... يداك يدي ليث فإنك جادبه)\n(إذا غالب ابن بالشباب أبا له ... كبيرا فإن الله لا بد غالبه)\n(رأيت تباشير العقوق هي التي ... من ابن امرئ ما إن يزال يعاتبه)\n(ولما رآني قد كبرت وأنني ... أخو الحي واستغنى عن المسح شاربه)\n(أصاخ لغربان النجي وإنه ... لأزور عن بعض المقالة جانبه)\nال أبو عبيدة في -","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":17,"spl":"جرير يقر له بالغلبة ويلقبه بالعزيز — كان ابنه لبطة عاقا به","tags":["الفرزدق"],"loc":1925},
{"id":"b112-33","bab":"الجزء 10","sec":"كتاب النقائض — جرير يهجوه وهو يجيب","page":"ج10 ص330 – ج10 ص331","text":"- قال رؤبة بن العجاج حج سليمان ابن عبد الملك وحجت معه الشعراء فمر بالمدينة منصرفا فأتي بأسرى من الروم نحو أربعمائة فقعد سليمان وعنده عبد الله بن حسن بن حسن عليهم السلام وعليه ثوبان ممصران وهو أقربهم منه مجلسا فأدنوا إليه بطريقهم وهو في جامعة فقال لعبد الله بن حسن قم فاضرب عنقه\nفقام فما أعطاه أحد سيفا حتى دفع إليه حرسي سيفا كليلا فضربه فأبان عنقه وذراعه وأطن ساعده وبعض الغل فقال له سليمان والله ما ضربته بسيفك ولكن بحسبك وجعل يدفع الأسرى إلى الوجوه فيقتلونهم حتى دفع إلى جرير رجلا منهم فدست إليه بنو عبس سيفا قاطعا في قراب أبيض فضربه فأبان رأسه ودفع إلى الفرزدق أسير فدست إليه القيسية سهما كليلا فضرب به الأسير ضربات فلم يصنع شيئا فضحك سليمان وضحك الناس معه\nوقيل إن سليمان لما دفع إليه الأسير دفع إليه سيفا وقال اقتله به فقال لا بل أقتله بسيف مجاشع واخترط سيفه فضربه فلم يغن شيئا فقال سليمان أما والله لقد بقي عليك عارها وشنارها فقال جرير قصيدته التي يهجوه فيها وأولها\n(ألا حي ربع المنزل المتقادم ... وما حل مذ حلت به أم سالم)\nمنها\n(ألم تشهد الجونين والشعب ذا الغضى ... وكرات قيس يوم دير الجماجم)\n(تحرض يا بن القين قيسا ليجعلوا ... لقومك يوما مثل يوم الأراقم)\n(بسيف أبي رغوان سيف مجاشع ... ضربت ولم تضرب بسيف ابن ظالم)\n(ضربت به عند الإمام فأرعشت ... يداك وقالوا محدث غير صارم)\nقال الفرزدق يجيب جريرا عن قوله\n(وهل ضربة الرومي جاعلة لكم ... أبا عن كليب أو أبا مثل دارم)\n(كذاك سيوف الهند تنبو ظباتها ... وتقطع أحيانا مناط التمائم)\n(ولا نقتل الأسرى ولكن نفكهم ... إذا أثقل الأعناق حمل المغارم)\nقال يعرض بسليمان ويعيره نبو سيف ورقاء بن زهير العبسي عن خالد بن جعفر وبنو عبس هم أخوال سليمان\n(فإن يك سيف خان أو قدر أبى ... بتعجيل نفس حتفها غير شاهد)\n(فسيف بني عبس وقد ضربوا به ... نبا بيدي ورقاء عن رأس خالد)\n(كذاك سيوف الهند تنبو ظباتها ... وتقطع أحيانا مناط القلائد)\nأولها\n(تباشر يربوع بنبوة ضربة ... ضربت بها بين الطلا والمحارد)\n(ولو شئت قد السيف ما بين عنقه ... إلى علق بين الحجابين جامد)\nقيل إن الفرزدق قال لسليمان يا أمير المؤمنين هب لي هذا الاسير فوهبه له فأعتقه وقال الأبيات التي منها\n(ولا نقتل الأسرى ولكن نفكهم ... إذا أثقل الأعناق حمل المغارم)\nم أقبل على راويته فقال كأني بابن المراغة وقد بلغه خبري فقال\n(بسيف أبي رغوان سيف مجاشع ... ضربت ولم تضرب بسيف ابن ظالم)\n(ضربت به عند الإمام فأرعشت ... يداك وقالوا محدث غير صارم)\nما لبثنا إلا أياما يسيرة حتى جاءتنا القصيدة وفيها البيتان فعجبنا من فطنة الفرزدق وقال أيضا في ذلك\n(أيعجب الناس أن أضحكت خيرهم ... خليفة الله يستسقى به المطر)\n(فما نبا السيف عن جبن وعن دهش ... عند الإمام ولكن أخر القدر)\n(ولو ضربت به عمدا مقلده ... لخر جثمانه ما فوقه شعر)\n(وما يقدم نفسا قبل ميتتها ... جمع اليدين ولا الصمصامة الذكر)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":18,"spl":"كتاب النقائض — جرير يهجوه وهو يجيب","tags":["الفرزدق"],"loc":1926},
{"id":"b112-34","bab":"الجزء 10","sec":"متفرقات من شعره","page":"ج10 ص333","text":"وأخبرني عبد الله بن مالك قال حدثنا محمد بن حبيب عن أبي عبيدة قال هجا الفرزدق خالدا القسري وذكر المبارك النهر الذي حفره بواسط فبلغه ذلك وكتب خالد إلى مالك بن المنذر أن احبس الفرزدق فإنه هجا نهر أمير المؤمنين بقوله\n(وأهلكت مال الله في غير حقه ... على نهرك المشؤوم غير المبارك)\nالأبيات فأرسل مالك إلى أيوب بن عيسى الضبي فقال ائتني بالفرزدق فلم يزل يعمل فيه حتى أخذه فطلب إليهم أن يمروا به على بني حنيفة فقال الفرزدق ما زلت أرجو أن أنجو حتى جاوزت بني حنيفة فلما قيل لمالك هذا الفرزدق انتفخ وريد مالك غضبا فلما أدخل عليه قال\n(أقول لنفسي حين غصت بريقها ... ألا ليت شعري مالها عند مالك)\n(لها عنده أن يرجع الله روحها ... إليها وتنجو من جميع المهالك)\n(وأنت ابن حباري ربيعة أدركت ... بك الشمس والخضراء ذات الحبائك)\nسكن مالك وأمر به إلى السجن فقال يهجو أيوب بن عيسى الضبي\n(فلو كنت قيسيا إذا ما حبستني ... ولكن زنجيا غليظا مشافره)\n(متت له بالرحم بيني وبينه ... فألفيته مني بعيدا أواصره)\n(وقلت امرؤ من آل ضبة فاعتزى ... لغيرهم لون استه ومحاجره)\n(فسوف يرى النوبي ما اجترحت له ... يداه إذا ما الشعر عيت نوافره)\n(ستلقي عليك الخنفساء إذا فست ... عليك من الشعر الذي أنت حاذره)\n(وتأتي ابن زب الخنفساء قصيدة ... تكون له مني عذابا يباشره)\n(تعذرت يا بن الخنفساء ولم تكن ... لتقبل لابن الخنفساء معاذره)\n(فإنكما يا بني يسار نزوتما ... على ثفرها ما حن للزيت عاصره)\n(لزنجية بظراء شقق بظرها ... زحير بأيوب شديد زوافره)\nثم مدح خالد بن عبد الله ومالك بن المنذر وهو محبوس مديحا كثيرا فأنشدني يونس في كلمة له طويلة\n(يا مال هل هو مهلكي ما لم أقل ... وليعلمن من القصائد قيلي)\n(يا مال هل لك في كبير قد أتت ... تسعون فوق يديه غير قليل)\n(فتجير ناصيتي وتفرج كربتي ... عني وتطلق لي يداك كبولي)\n(ولقد بنى لكم المعلى ذروة ... رفعت بناءك في أشم طويل)\n(والخيل تعلم في جذيمة أنها ... تردى بكل سميدع بهلول)\n(فاسقوا فقد ملأ المعلى حوضكم ... بذنوب ملتهم الرباب سجيل)\nقال يمدح مالكا وكانت أم مالك هذا بنت مالك بن مسمع\n(وقرم بين أولاد المعلى ... وأولاد المسامعة الكرام)\n(تخمط في ربيعة بين بكر ... وعبد القيس في الحسب اللهام)\nفلما لم تنفعه مديحة مالك قال يمدح هشام بن عبد الملك ويعتذر إليه\n(ألكني إلى راعي البرية والذي ... له العدل في الأرض العريضة نورا)\n(فإن تنكروا شعري إذا خرجت له ... بوادر لو يرمى بها لتفقرا)\n(ثبير ولو مست حراء لحركت ... به الراسيات الصم حتى تكورا)\n(إذا قال غاو من معد قصيدة ... بها حرب كانت وبالا مد مرا)\n(أينطقها غيري وأرمى بجرمها ... فكيف ألوم الدهر أن يتغيرا)\n(لئن صبرت نفسي لقد أمرت به ... وخير عباد الله من كان أصبرا)\n(وكنت ابن أحذار ولو كنت خائفا ... لكنت من العصماء في الطود أحذرا)\n(ولكن أتوني آمنا لا أخافهم ... نهارا وكان الله ما شاء قدرا)\nخبرني أبو خليفة عن محمد بن سلام قال حدثني أبو يحيى قال قال الفرزدق لابنه لبطة وهو محبوس اشخص إلى هشام وامدحه بقصيدة وقال استعن بالقيسية ولا يمنعك قولي فيهم فإنهم سيغضبون لك وقال\n(بكت عين محزون ففاض سجامها ... وطالت ليالي ساهر لا ينامها)\n(فإن تبك لا تبك المصيبات إذ أتى ... بها الدهر والأيام جم خصامها)\n(ولكنما تبكي تهتك خالد ... محارم منا لا يحلل حرامها)\n(فقل لبني مروان ما بال ذمة ... وحرمة)\n(أنقتل فيكم أن قتلنا عدوكم ... على دينكم والحرب باق قتامها)\n(أتاك بقتل ابن المهلب خالد ... وفينا بقيات الهدى وإمامها)\n(فغير أمير المؤمنين فإنها ... يمانية حمقاء وأنت هشامها)\n(أرى مضر المضرين قد ذل نصرها ... ولكن عسى أن لا يذل شآمها)\n(فمن مبلغ بالشام قيسا وخندفا ... أحاديث ما يشفى ببرء سقامها)\n(أحاديث منا نشتكيها إليهم ... ومظلمة يغشى الوجوه قتامها)\n(فإن من بها لم ينكر الضيم منهم ... فيغضب منها كهلها وغلامها)\n(نمت مثلها من مثلهم وتنكلوا ... فيعلم أهل الجور كيف انتقامها)\n(بغلباء من جمهورنا مضرية ... يزايل فيها أذرع القوم هامها)\n(وبيض على هام الرجال كأنها ... كواكب يحلوها لسار ظلامها)\n(غضبنا لكم يا آل مروان فاغضبوا ... عسى أن أرواحا يسوغ طعامها)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":19,"spl":"متفرقات من شعره","tags":["الفرزدق","الحب والغزل"],"loc":1927},
{"id":"b112-35","bab":"الجزء 10","sec":"متفرقات من شعره","page":"ج10 ص333","text":"(ولا تقطعوا الأرحام منا فإنها ... ذنوب من الأعمال يخشى أثامها)\n(ألم تك في الأرحام منا ومنكم ... حواجز أيام عزيز مرامها)\n(فترعى قريش من تميم قرابة ... ونجزي بأيام كريم مقامها)\n(لقد علمت أبناء خندف أننا ... ذراها وأنا عزها وسنامها)\n(وقد علم الأحياء من كل موطن ... إذا عدت الأحياء أنا كرامها)\n(وأنا إذا الحرب العوان تضرمت ... نليها إذا ما الحرب شب ضرامها)\n(قوام قوى الإسلام والأمر كله ... وهل طاعة إلا تميم قوامها)\n(تميم التي تخشى معد وغيرها ... إذا ما أبى أن يستقيم همامها)\n(إلى الله تشكو عزنا الأرض فوقها ... وتعلم أنا ثقلها وغرامها)\n(شكتنا إلى الله العزيز فأسمعت ... قريبا وأعيا من سواه كلامها)\n(نصول بحول الله في الأمر كله ... إذا خيف من مصدوعة ما التآمها)\nأعانته القيسية وقالوا كلما كان ناب من مضر أو شاعر أو سيد وثب عليه خالد وقال الفرزدق أبياتا كتب بها إلى سعيد بن الوليد الأبرش وكلم له هشاما\n(إلى الأبرش الكلبي أسندت حاجة ... تواكلها حيا تميم ووائل)\n(على حين أن زلت بي النعل زلة ... فأخلف ظني كل حاف وناعل)\n(فدونكها يا بن الوليد فإنها ... مفضلة أصحابها في المحافل)\n(ودونكها يا بن الوليد فقم بها ... قيام امرئ في قومه غير خامل)\nكلم هشاما وأمر بتخليته فقال يمدح الأبرش\n(لقد وثب الكلبي وثبة حازم ... إلى خير خلق الله نفسا وعنصرا)\n(إلى خير أبناء الخليفة لم يجد ... لحاجته من دونها متأخرا)\n(أبى حلف كلب في تميم وعقدها ... كما سنت الاباء أن يتغيرا)\nكان هذا الحلف حلفا قديما بين تميم وكلب في الجاهلية وذلك قول جرير بن الخطفى في الحلف\n(تميم إلى كلب وكلب إليهم ... أحق وأدنى من صداء وحميرا)\n(أشد حبال بين حيين مرة ... حبال أمرت من تميم ومن كلب)\n(وليس قضاعي لدينا بخائف ... ولو أصبحت تغلي القدور من الحرب)\nقال أيضا\n(ألم تر قيسا قيس عيلان شمرت ... لنصري وحاطتني هناك قرومها)\n(فقد حالفت قيس على النأي كلهم ... تميما فهم منها ومنها تميمها)\n(وعادت عدوي إن قيسا لأسرتي ... وقومي إذا ما الناس عد صميمها)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":20,"spl":"متفرقات من شعره — خبره مع الشرطيين","tags":["الفرزدق","المديح"],"loc":1928},
{"id":"b112-36","bab":"الجزء 10","sec":"خبره مع الشرطيين","page":"ج10 ص339","text":"أخبرني ابن دريد قال حدثني أبو حاتم عن أبي عبيدة قال بينما الفرزدق جالس بالبصرة أيام زياد في سكة ليس لها منفذ إذ مر به رجلان من قومه كانا في الشرطة وهما راكبان فقال أحدهما لصاحبه هل لك أن أفزعه وكان جبانا فحركا دابتيهما نحوه فأدبر موليا فعثر في طرف برده فشقه وانقطع شسع نعله وانصرفا عنه وعرف أنهما هزئا منه فقال\n(لقد خار إذ يجري علي حماره ... ضرار الخنا والعنبري بن أخوقا)\n(وما كنت لو خوفتماني كلاكما ... بأميكما عريانتين لأفرقا)\n(ولكنما خوفتماني بخادر ... شتيم إذا ما صادف القرن مزقا)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":20,"spl":"متفرقات من شعره — خبره مع الشرطيين","tags":["الفرزدق"],"loc":1929},
{"id":"b112-37","bab":"الجزء 10","sec":"نزل بدار ليلى الأخيلية والتقى توبة بن الحمير","page":"ج10 ص340","text":"أخبرني عبد الله بن مالك قال حدثنا محمد بن موسى قال حدثنا القحذمي عن بعض ولد قتيبة بن مسلم عن ابن زالان المازني قال حدثني الفرزدق قال لما طردني زياد أتيت المدينة وعليها مروان بن الحكم فبلغه أني خرجت من دار ابن صياد وهو رجل يزعم أهل المدينة أنه الدجال فليس يكلمه أحد ولا يجالسه أحد ولم أكن عرفت خبره فأرسل إلي مروان فقال أتدري ما مثلك حديث تحدث به العرب أن ضبعا مرت بحي قوم وقد رحلوا فوجدت مرآة فنظرت وجهها فيها فلما نظرت قبح وجهها ألقتها وقالت من شر ما أطرحك أهلك ولكن من شر ما أطرحك أميرك فلا تقيمن بالمدينة بعد ثلاثة أيام\nقال فخرجت أريد اليمن حتى إذا صرت بأعلى ذي قسي وهو طريق اليمن من البصرة فإذا رجل مقبل فقلت من أين أوضع الراكب قال من البصرة قلت فما الخبر وراءك قال أتانا أن زيادا مات بالكوفة قال فنزلت عن راحلتي فسجدت وقلت لو رجعت فمدحت عبيد الله بن زياد وهجوت مروان بن الحكم فقلت\n(وقفت بأعلى ذي قسي مطيتي ... أمثل في مروان وابن زياد)\n(فقلت عبيد الله خيرهما لنا ... وأدناهما من رأفة وسداد)\nمضيت لوجهي حتى وطئت بلاد بني عقيل فوردت ما بين مياههم فإذا بيت عظيم وإذا فيه امرأة سافرة لم أر كحسنها وهيئتها قط فدنوت فقالت أتأذنين في الظل قالت انزل فلك الظل والقرى فأنخت وجلست إلى قال فدعت جارية لها سوداء كالراعية فقلت ألطفيه شيئا واسعي إليها الراعي فردي علي شاة فاذبحيها له وأخرجت إلي تمرا وزبدا قال\nوحادثتها فو الله ما رأيت مثلها قط ما أنشدتها شعرا إلا أنشدتني أحسن منه قال فأعجبني المجلس والحديث إذ أقبل رجل بين بردين فلما رأته رمت ببرقعها على وجهها وجلس وأقبلت عليه بوجهها وحديثها فدخلني من ذلك غيظ فقلت للحين هل لك في الصراع فقال سوأة لك إن الرجل لا يصارع ضيفه\nقال فألححت عليه فقالت له ما عليك لو لاعبت ابن عمك فقام وقمت فلما رمى ببرده إذا خلق عجيب فقلت هلكت ورب الكعبة فقبض على يدي ثم اختلجني إليه فصرت في صدره ثم حملني\nقال فو الله ما اتقيت الأرض إلا بظهر كبدي وجلس على صدري فما ملكت نفسي أن ضرطت ضرطة منكرة قال وثرت إلى جملي فقال أنشدك الله فقالت المرأة عافاك الله الظل والقرى فقلت أخزى الله ظلكم وقراكم ومضيت فبينا أسير إذ لحقني الفتى على نجيب يجنب بختيا برحله وزمامه وكان رحله من أحسن الرحال فقال يا هذا والله ما سرني ما كان وقد أراك أبدعت أي كلت ركابك فخذ هذا النجيب وإياك أن تخدع عنه فقد والله أعطيت به مائتي دينار قلت نعم آخذه ولكن أخبرني من أنت ومن هذه المرأة قال أنا توبة بن الحمير وتلك ليلى الأخيلية","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":21,"spl":"نزل بدار ليلى الأخيلية والتقى توبة بن الحمير — خبر آخر عن لقائه بليلى وتوبة","tags":["الفرزدق","المديح","الجواري والنساء"],"loc":1930},
{"id":"b112-38","bab":"الجزء 10","sec":"خبر آخر عن لقائه بليلى وتوبة","page":"ج10 ص341","text":"وقد أخبرني بهذا الخبر عمي قال حدثني القاسم بن محمد الأنباري قال حدثني أحمد بن عبيد عن الأصمعي قال كانت امرأة من عقيل يقال لها ليلى يتحدث إليها الشباب فدخل الفرزدق إليها فجعل يحادثها وأقبل فتى من قومها كانت تألفه ودخل إليها فأقبلت عليه بحديثها وتركت الفرزدق فغاظه ذلك فقال للرجل أتصارعني\nقال ذلك إليك فقام إليه الرجل فلم يلبث أن أخذ الفرزدق مثل الكرة فصرعه وجلس على صدره فضرط الفرزدق فوثب عنه الرجل خجلا وقال له الرجل يا أبا فراس هذا مقام العائذ بك والله ما أردت بك ما جرى فقال ويحك ما بي أن صرعتني ولكن كأني بابن الأتأن جرير وقد بلغه خبري هذا فقال يهجوني\n(جلست إلى ليلى لتحظى بقربها ... فخانك دبر لا يزال يخون)\n(فلو كنت ذا حزم شددت وكاءها ... كما شد خرتا للدلاص قيون)\nالوا فو الله ما مضت أيام حتى بلغ جريرا الخبر فقال فيه هذين البيتين","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":21,"spl":"نزل بدار ليلى الأخيلية والتقى توبة بن الحمير — خبر آخر عن لقائه بليلى وتوبة","tags":["الفرزدق","الجواري والنساء"],"loc":1931},
{"id":"b112-39","bab":"الجزء 10","sec":"يومه كيوم امرئ القيس بدارة جلجل","page":"ج10 ص342","text":"أخبرنا عبد الله بن مالك قال حدثني محمد بن موسى قال حدثني القحذمي قال حدثني بعض أصحابنا عن عبد الله بن زالان التميمي راوية\nالفرزدق أن الفرزدق قال أصابنا بالبصرة مطر جود ليلا فإذا أنا بأثر دواب قد خرجت ناحية البرية فظننت قوما قد خرجوا لنزهة فقلت خليق أن تكون معهم سفرة وشراب فقصصت أثرهم حتى وقفت إلى بغال عليها رحائل موقوفة على غدير فأغذذت السير نحو الغدير فإذا نسوة مستنقعات في الماء فقلت لم أر كاليوم قط ولا يوم دارة جلجل وانصرفت مستحييا منهن فنادينني بالله يا صاحب البغلة ارجع نسألك عن شيء فانصرفت إليهن وهن في الماء إلى حلوقهن فقلن بالله إلا ما خبرتنا بحديث دارة جلجل فقلت إن امرأ القيس كان عاشقا لابنة عم له يقال لها عنيزة فطلبها زمانا فلم يصل إليها وكان في طلب غرة من أهلها ليزورها فلم يقض له حتى كان يوم الغدير وهو يوم دارة جلجل وذلك أن الحي احتملوا فتقدم الرجال وتخلف النساء والخدم والثقل فلما رأى ذلك امرؤ القيس تخلف بعد ما سار مع قومه غلوة فكمن في غيابة من الأرض حتى مر به النساء فإذا فتيات وفيهن عنيزة فلما وردن الغدير قلن لو نزلنا فذهب عنا بعض الكلال فنزلن إليه ونحين العبيد عنهن ثم تجردن فاغتمسن في الغدير كهيئتكن الساعة فأتاهن امرؤ القيس\nمحتالا كنحو ما أتيتكن وهن غوافل فأخذ ثيابهن فجمعها ورمى الفرزدق بنفسه عن بغلته فأخذ بعض أثوابهن فجمعها ووضعها على صدره وقال لهن كما أقول لكن والله لا أعطي جارية منكن ثوبها ولو أقامت في الغدير يومها حتى تخرج مجردة\nقال الفرزدق فقالت إحداهن وكانت أمجنهن ذلك كان عاشقا لابنة عمه أفعاشق أنت لبعضنا قال لا والله ما أعشق منكن واحدة ولكن أشتهيكن قال فنعرن وصفقن بأيديهن وقلن خذ في حديثك فلست منصرفا إلا بما تحب\nقال الفرزدق في حديث امرئ القيس فتأبين ذلك عليه حتى تعالى النهار ثم خشين أن يقصرن دون المنزل الذي أردنه فخرجت إحداهن فوضع لها ثوبها ناحية فأخذته فلبسته ثم تتابعن على ذلك حتى بقيت عنيزة فناشدته الله أن يطرح إليها ثوبها فقال دعينا منك فأنا حرام إن أخذت ثوبك إلا بيدك فخرجت فنظر إليها مقبلة ومدبرة فوضع لها ثوبها فأخذته وأقبلن عليه يلمنه ويعذلنه ويقلن عريتنا وحبستنا وجوعتنا\nقال فإن نحرت لكن مطيتي أتأكلن منها قلن نعم فاخترط سيفه فعقرها ونحرها وكشطها وصاح بالخدم فجمعوا له حطبا فأجج نارا عظيمة ثم جعل يقطع لهن من سنامها وأطايبها وكبدها فيلقيها على الجمر فيأكلن ويأكل معهن ويشرب من ركوة كانت معه ويغنيهن وينبذ إلى العبيد والخدم من الكباب حتى شبعن وطربن فلما أراد الرحيل قالت إحداهن أنا أحمل طنفسته وقالت الأخرى أنا أحمل رحله وقالت الأخرى أنا أحمل حشيته\nوأنساعه فتقسمن متاع راحلته بينهن وبقيت عنيزة لم يحملها شيئا فقال لها امرؤ القيس يا بنة الكرام لا بد لك أن تحمليني معك فإني لا أطيق المشي وليس من عادتي فحملته على غارب بعيرها فكان يدخل رأسه في خدرها فيقبلها فإذا امتنعت مال حدجها فتقول يا امرأ القيس عقرت بعيري فانزل فلذلك قوله\n(تقول وقد مال الغبيط بنا معا ... عقرت بعيري يا امرأ القيس فانزل)\nلما فرغ الفرزدق من الحديث قالت تلك الماجنة قاتلك الله ما أحسن حديثك يا فتى وأظرفك فمن أنت قال قلت من مضر قالت ومن أيها فقلت من تميم قالت ومن أيها\nقلت إلى ههنا انتهى الكلام قالت إخالك والله الفرزدق قلت الفرزدق شاعر وأنا راوية قالت دعنا من توريتك على نسبك أسألك بالله أنت هو قال أنا هو والله قالت فإن كنت أنت هو فلا أحسبك مفارقا ثيابنا إلا عن رضا\nقلت أجل قالت فاصرف وجهك عنا ساعة وهمست إلى صويحباتها بشيء لم أفهمه فغططن في الماء فتوارين وأبدين رؤوسهن وخرجن ومع كل واحدة منهن ملء كفيها طينا وجعلن يتعادين نحوي فضربن بذلك الطين والحمأة وجهي وملأن عيني وثيابي فوقعت على وجهي فصرت مشغولا بعيني وما فيها وشددن على ثيابهن فأخذنها وركبت الماجنة بغلتي وتركتني منبطحا بأسوأ حال وأخزاها وهي تقول زعم الفتى أنه لا بد أن ينيكنا فما زلت من ذلك المكان حتى غسلت وجهي وثيابي وجففتها وانصرفت عند مجيء الظلام إلى منزلي على قدمي وبغلتي قد وجهن بها إلى منزلي مع رسول لهن","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":22,"spl":"يومه كيوم امرئ القيس بدارة جلجل","tags":["الفرزدق","الجواري والنساء"],"loc":1932},
{"id":"b112-41","bab":"الجزء 10","sec":"يومه كيوم امرئ القيس بدارة جلجل — يهجو مسكينا الدارمي","page":"ج10 ص342 – ج10 ص345","text":"وقلن قل له تقول لك أخواتك طلبت منا ما لم يمكننا وقد وجهنا إليك بزوجتك فنكها سائر ليلتك وهذا كسر درهم لحمامك إذا أصبحت فكان إذا حدث بهذا الحديث يقول ما منيت بمثلهن\nأخبرني عبد الله بن مالك قال حدثنا أبو مسلم الحراني قال حدثني الأصمعي قال حدثنا العلاء بن أسلم قال لما مات زياد رثاه مسكين الدارمي فقال الفرزدق\n(أمسكين أبكى الله عينيك إنما ... جرى في ضلال دمعها إذ تحدرا)\n(بكيت امرأ من آل ميسان كافرا ... ككسرى على عدانه أو كقيصرا)\n(أقول له لما أتاني نعيه ... به لا بظبي بالصريمة أعفرا)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":23,"spl":"يومه كيوم امرئ القيس بدارة جلجل — يهجو مسكينا الدارمي — هجا ومدح آل المهلب","tags":["الفرزدق","الموت","الرواية والكتابة"],"loc":1933},
{"id":"b112-42","bab":"الجزء 10","sec":"هجا ومدح آل المهلب","page":"ج10 ص346","text":"أخبرنا عبد الله بن مالك عن أبي مسلم الحراني قال حدثنا الأصمعي قال حدثنا العلاء بن أسلم قال لما أراد المهلب الخروج إلى الأزارقة لقي الفرزدق جريرا فقال\nله يا أبا فراس هل لك أن تكلم المهلب حتى يضع عني البحث وأعطيك ألف درهم فكلم المهلب فأجابه فلامه جذيع رجل من عشيرته وشكا ذلك إلى خيرة امرأة المهلب وقال لها لا يزال الآن الرجل يجيء فيسأل في عشيرته وصديقه فلامته خيرة بنت ضمرة القشيرية فقال المهلب إنما اشتريت عرضي منه فبلغ ذلك الفرزدق فقال يهجو جذيعا\n(إن تبن دارك يا جذيع فما بنى ... لك يا جذيع أبوك من بنيان)\n(وابوك ملتزم السفينة عاقد ... خصييه فوق بنائق التبان)\n(ويظل يدفع باسته متقاعسا ... في البحر معتمدا على السكان)\n(لا تحسبن دراهما جمعتها ... تمحو مخازيك التي بعمان)\nقال يهجو خيرة\n(ألا قشر الإله بني قشير ... كقشر عصا المنقح من معال)\n(أرى رهطا لخيرة لم يؤوبوا ... بسهم في اليمين ولا الشمال)\n(إذا رهزت رأيت بني قشير ... من الخيلاء منتفشي السبال)\nغضب بنو المهلب لما هجا جذيعا وخيرة فنالوا منه فهجاهم فقال\n(وكائن للمهلب من نسيب ... يرى بلبانه أثر الزيار)\n(بخارك لم يقد فرسا ولكن ... يقود الساج بالمسد المغار)\n(عمي بالتنائف حين يضحى ... دليل الليل في اللجج الغمار)\n(وما لله يسجد إذ يصلي ... ولكن يسجدون لكل نار)\nلما ولي يزيد بن المهلب خراسان والعراق بعد أبيه ولاه سليمان بن عبد الملك خاف الفرزدق من بني المهلب فقال يمدحهم\n(فلأ مدحن بني المهلب مدحة ... غراء قاهرة على الأشعار)\n(مثل النجوم أمامها قمراؤها ... تجلو العمى وتضيء ليل الساري)\n(ورثوا الطعان عن المهلب والقرى ... وخلائقا كتدفق الأنهار)\n(كان المهلب للعراق وقاية ... وحيا الربيع ومعقل الفرار)\n(وإذا الرجال رأوا يزيد رأيتهم ... خضع الرقاب نواكس الأبصار)\n(مازال مذ شد الإزار بكفه ... ودنا فأدرك خمسة الأشبار)\n(أيزيد إنك للمهلب أدركت ... كفاك خير خلائق الأخيار)\nخبرنا عبد الله بن مالك قال حدثنا محمد بن حبيب قال حدثني الأصمعي قال لما قدم يزيد بن المهلب واسطا قال لأمية بن الجعد وكان صديق الفرزدق إني لأحب أن تأتيني بالفرزدق فقال للفرزدق ماذا فاتك من يزيد أعظم الناس عفوا وأسخى الناس كفا قال صدقت ولكن أخشى أن آتيه فأجد العمانية ببابه فيقوم إلي رجل منهم فيقول هذا الفرزدق الذي هجانا فيضرب عنقي فيبعث إليه يزيد فيضرب عنقه ويبعث إلى أهلي\nديتي فإذا يزيد قد صار أوفى العرب وإذا الفرزدق فيما بين ذلك قد ذهب قال لا والله لا أفعل فأخبر يزيد بما قال فقال أما إذ قد وقع هذا بنفسه فدعه لعنه الله","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":23,"spl":"يومه كيوم امرئ القيس بدارة جلجل — يهجو مسكينا الدارمي — هجا ومدح آل المهلب","tags":["الفرزدق","الهجاء","المديح"],"loc":1934},
{"id":"b112-43","bab":"الجزء 10","sec":"خبره مع الماجن الذي أراده","page":"ج10 ص349","text":"قال ابن حبيب وحدثنا يعقوب بن محمد الزهري عن أبيه عن جده قال دخل الفرزدق مع فتيان من آل المهلب في بركة يتبردون فيها ومعهم ابن أبي علقمة الماجن فجعل يتفلت إلى الفرزدق فيقول دعوني أنكحه حتى لا يهجونا أبدا وكان الفرزدق من أجبن الناس فجعل يستغيث ويقول ويلكم لا يمس جلده جلدي فيبلغ ذلك جريرا فيوجب علي أنه قد كان منه الذي يقول فلم يزل يناشدهم حتى كفوه عنه\nأخبرني عبيد الله قال حدثني محمد بن حبيب قال حدثني موسى بن طلحة قال لما ولي خالد بن عبد الله العراق فقدمها وكان من أشد خلق الله عصبية على نوار فقال لبطة بن الفرزدق فلبس أبي من صالح ثيابه وخرج يريد السلام عليه فقلت له يا أبت إن هذا الرجل يماني وفيه من العصبية ما قد علمت فلو دخلت إليه فأنشدته مدائحك أهل اليمن لعل الله أن يأتيك منه بخير فإنك قد كبرت على الرحلة فجعل لا يرد علي شيئا حتى دفعنا إلى البواب فأذن له فدخل وسلم فاستجلسه ثم قال إيه يا أبا فراس أنشدنا مما أحدثت فأنشدته\n(يختلف الناس ما لم نجتمع لهم ... ولا خلاف إذا ما أجمعت مضر)\n(فينا الكواهل والأعناق تقدمها ... فيها الرؤوس وفيها السمع والبصر)\n(ولا نحالف غير الله من أحد ... إلا السيوف إذا ما اغرورق النظر)\n(ومن يمل يمل المأثور قلته ... بحيث يلقى حفافي رأسه الشعر)\n(أما الملوك فإنا لا نلين لهم ... حتى يلين لضرس الماضغ الحجر)\nم قام فخرجنا قلت أهكذا أوصيتك قال اسكت لا أم لك فما كنت قط أملأ لقلبه مني الساعة","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":24,"spl":"خبره مع الماجن الذي أراده — فلما بلغ زيادا شخوصه أتبعه علي بن زهدم الفقيمي أحد بني مؤلة فل","tags":["الفرزدق","السفر والحج"],"loc":1935},
{"id":"b112-44","bab":"الجزء 10","sec":"يفحم المنذر بن الجارود","page":"ج10 ص350","text":"أخبرني عبد الله قال حدثني محمد بن حبيب عن موسى بن طلحة قال كان الفرزدق في حلقة في المسجد الجامع وفيها المنذر بن الجارود العبدي فقال المنذر من الذي يقول\n(وجدنا في كتاب بني تميم ... أحق الخيل بالركض المعار)\nقال الفرزدق يا أبا الحكم هو الذي يقول\n(أشارب قهوة وخدين زير ... وعبدي لفسوته بخار)\n(وجدنا الخيل في أبناء بكر ... وأفضل خيلهم خشب وقار)\nال فخجل المنذر حتى ما قدر على الكلام أخبرني عبد الله بن مالك قال حدثني محمد بن موسى قال حدثنا الأصمعي قال\nدخل الفرزدق على بعض خلفاء بني مروان ففاخره قوم من الشعراء فأنشأ يقول\n(ما حملت ناقة من معشر رجلا ... مثلي إذا الريح لفتني على الكور)\n(أعز قوما وأوفى عند مكرمة ... لمعظم من دماء القوم مهجور)\nقال له إيه فقال\n(إلا قريشا فإن الله فضلها ... على البرية بالإسلام والخير)\n(تلقى وجوه بني مروان تحسبها ... عند اللقاء مشوفات الدنانير)\nفضله عليهم ووصله","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":24,"spl":"خبره مع الماجن الذي أراده — فلما بلغ زيادا شخوصه أتبعه علي بن زهدم الفقيمي أحد بني مؤلة فل","tags":["الفرزدق","اللهو والمزاح"],"loc":1936},
{"id":"b112-45","bab":"الجزء 10","sec":"يمدح عيسى بن حصيلة لأنه أعانه على الفرار","page":"ج10 ص351","text":"قال ابن حبيب وكان الفرزدق يهاجي الأشهب بن رميلة النهشلي وبني فقيم فأرفث بهم فاستعدوا عليه زيادا فحدثني جابر بن جندل قال فأتى عيسى بن حصيلة بن مغيث بن نصر بن خالد السلمي ثم من بني بهز فقال يا أبا حصيلة إن هذا الرجل قد أخافني وقد لفظني جميع من كنت أرجو\nقال فمرحبا بك يا أبا فراس فكان عنده ليالي ثم قال إني أريد أن ألحق بالشام قال إن أقمت ففي الرحب والسعة وإن شخصت فهذه ناقة أرحبية أمتعك بها وألف درهم فركب الناقة وخرج من عنده ليلا\nفأرسل عيسى معه من أجازه من البيوت فأصبح وقد جاوز مسيرة ثلاث فقال يمدحه\n(كفاني بها البهزي حملان من أبى ... من الناس والجاني تخاف جرائمه)\n(فتى الجود عيسى والمكارم والعلا ... إذا المال لم ينفع بخيلا كرائمه)\n(ومن كان يا عيسى يؤنب ضيفه ... فضيفك يا عيسى هنيء مطاعمه)\n(وقال تعلم أنها أرحبية ... وأن لك الليل أنت جاشمه)\n(فأصبحت والملقى ورائي وحنبل ... وما صدرت حتى علا النجم عاتمه)\n(تزاور في آل الحقيق كأنها ... ظليم تباري جنح ليل نعائمه)\n(رأت دون عينيها ثوية فانجلى ... لها الصبح عن صعل أسيل مخاطمه)\nقال\n(تداركني أسباب عيسى من الردى ... ومن يك مولاه فليس بواحد)\n(نمته النواصي من سليم إلى العلا ... واعراق صدق بين نصر وخالد)\n(سأثني بما أوليتني وأربه ... إذا القوم عدوا فضلهم في المشاهد)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":24,"spl":"خبره مع الماجن الذي أراده — فلما بلغ زيادا شخوصه أتبعه علي بن زهدم الفقيمي أحد بني مؤلة فل","tags":["الفرزدق","المديح","الوصف والطبيعة"],"loc":1937},
{"id":"b112-46","bab":"الجزء 10","sec":"فلما بلغ زيادا شخوصه أتبعه علي بن زهدم الفقيمي أحد بني مؤلة فلم يلحقه","page":"ج10 ص352","text":"فقال الفرزدق\n(فإنك لو لاقيتني يا بن زهدم ... لأبت شعاعيا على غير تمثال)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":24,"spl":"خبره مع الماجن الذي أراده — فلما بلغ زيادا شخوصه أتبعه علي بن زهدم الفقيمي أحد بني مؤلة فل","tags":["الفرزدق","الحكمة والمواعظ"],"loc":1938},
{"id":"b112-47","bab":"الجزء 10","sec":"يلجأ إلى بكر بن وائل","page":"ج10 ص352","text":"فأتى بكر بن وائل فجاورهم فأمن فقال\n(وقد مثلت أين المسير فلم تجد ... لعوذتها كالحي بكر بن وائل)\n(وسارت إلى الأجفان خمسا فأصبحت ... مكان الثريا من يد المتناول)\n(وما ضرها إذ جاورت في بلادها ... بني الحصن ما كان اختلاف القبائل)\nالحصن بن ثعلبة بن عكابة بن صعب بن علي بن بكر بن وائل","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":25,"spl":"يلجأ إلى بكر بن وائل — ملاحاة بينه وبين مسكين الدارمي","tags":["الفرزدق"],"loc":1939},
{"id":"b112-48","bab":"الجزء 10","sec":"اطمأن عند سعيد بن العاصي بالمدينة","page":"ج10 ص353","text":"وهرب الفرزدق من زياد فأتى سعيد بن العاصي بن سعيد بن العاصي ابن أمية وهو على المدينة لمعاوية بن أبي سفيان فأمنه سعيد فبلغ الفرزدق أن زيادا قال لو أتاني أمنته وأعطيته فقال في كلمة له\n(دعاني زياد للعطاء ولم أكن ... لآتيه ما ساق ذو حسب وقرا)\n(وعند زياد لو أراد عطاءهم ... رجال كثير قد يرى بهم فقرا)\n(قعود لدى الأبواب طلاب حاجة ... عوان من الحاجات أو حاجة بكرا)\n(فلما خشيت أن يكون عطاؤه ... أداهم سودا أو محدرجة سمرا)\n(نميت إلى حرف أضر بنيها ... سرى الليل واستعراضها البلد القفرا)\nفلما اطمأن عند سعيد بن العاصي بالمدينة قال\n(ألا من مبلغ عني زيادا ... مغلغلة يخب بها البريد)\n(بأني قد فررت إلى سعيد ... ولا يسطاع ما يحمي سعيد)\n(فررت إليه من ليث هزبر ... تفادى عن فريسته الأسود)\n(فإن شئت انتميت إلى النصارى ... وناسبني وناسبت اليهود)\n(وإن شئت انتسبت إلى فقيم ... وناسبني وناسبت القرود)\n(وأبغضهم إلي بنو فقيم ... ولكن سوف آتي ما تريد)\nفأقام الفرزدق بالمدينة فكان يدخل بها على القيان فقال\n(إذا شئت غناني من العاج قاصف ... على معصم ريان لم يتخدد)\n(لبيضاء من أهل المدينة لم تعش ... ببؤس ولم تتبع حمولة مجحد)\n(وقامت تخشيني زيادا وأجفلت ... حوالي في بردي يمان ومجسد)\n(فقلت دعيني من زياد فإنني ... أرى الموت وقاعا على كل مرصد)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":25,"spl":"يلجأ إلى بكر بن وائل — ملاحاة بينه وبين مسكين الدارمي","tags":["الفرزدق","السفر والحج"],"loc":1940},
{"id":"b112-49","bab":"الجزء 10","sec":"ملاحاة بينه وبين مسكين الدارمي","page":"ج10 ص354","text":"فلما هلك زياد رثاه مسكين بن عامر بن شريح بن عمرو بن عدي بن عدس بن عبد الله بن دارم فقال\n(رأيت زيادة الإسلام ولت ... جهارا حين فارقها زياد)\nفبلغ ذلك الفرزدق فقال\n(أمسكين أبكى الله عينيك إنما ... جرى في ضلال دمعها فتحدرا)\n(أتبكي امرأ من آل ميسان كافرا ... ككسرى على عدانه أو كقيصرا)\n(أقول له لما أتاني نعيه ... به لا بظبي بالصريمة أعفرا)\nقال مسكين\n(ألا أيها المرء الذي لست قائما ... ولا قاعدا في القوم إلا انبرى ليا)\n(فجئني بعم مثل عمي أو أب ... كمثل أبي أو خال صدق كخاليا)\n(بعمرو بن عمرو أو زرارة ذي الندى ... سموت به حتى فرعت الروابيا)\nأمسك الفرزدق عنه وكان يقول نجوت من أن يهجوني مسكين فإن أجبته ذهبت بشطر فخري وإن أمسكت عنه كانت وصمة على مدى الدهر أخبرني أبو خليفة فقال أخبرنا ابن سلام\nقال حدثني الحكم بن محمد المازني قال كان تميم بن زيد القضاعي ثم أحد بني القين بن جسر غزا الهند في جيش فجمرهم وفي جيشه رجل يقال له حبيش فلما طالت غيبته على أمه إشتاقته فسألت عمن يكلم لها تميم بن زيد أن يقفل ابنها فقيل لها عليك بالفرزدق فاستجيري بقبر أبيه فأتت قبر غالب بكاظمة حتى علم الفرزدق مكانها ثم أتته وطلبت إليه حاجتها فكتب إلى تميم بن زيد هذه الأبيات\n(هب لي حبيشا واتخذ فيه منة ... لغصة أم ما يسوغ شرابها)\n(أتتني فعاذت يا تميم بغالب ... وبالحفرة السافي عليها ترابها)\n(تميم بن زيد لا تكونن حاجتي ... بظهر فلا يخفى علي جوابها)\nفلما أتاه كتابه لم يدر ما اسمه حبيش أو حنيش فأخرج ديوانه وأقفل كل حبيش وحنيش في جيشه وهم عدة وأنفذهم إلى الفرزدق","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":25,"spl":"يلجأ إلى بكر بن وائل — ملاحاة بينه وبين مسكين الدارمي","tags":["الفرزدق","الخمر"],"loc":1941},
{"id":"b112-50","bab":"الجزء 10","sec":"قبر أبيه معاذ الناس","page":"ج10 ص356","text":"قال أبو خليفة قال ابن سلام وحدثني أبو يحيى الضبي قال ضرب مكاتب لبني منقر بساطا على قبر غالب أبي الفرزدق فقدم الناس على الفرزدق فأخبروه بمكانه عند قبر أبيه ثم قدم عليه فقال\n(بقبر ابن ليلى غالب غذت بعدما ... خشيت الردى أو أن أرد على قسر)\n(فأخبرني قبر ابن ليلى فقال لي ... فكاكك أن تأتي الفرزدق بالمصر)\nقال الفرزدق صدق أبي أنخ ثم طاف له في الناس حتى جمع له مكاتبته وفضلا وكان نفيع ذو الأهدام أحد بني جعفر بن كلاب يتعصب لجرير بمدحه قيسا فهجاه الفرزدق فاستجارت أمه بقبر غالب وعاذت من هجاء الفرزدق فقال\n(ونبئت ذا الأهدام يعوي ودونه ... من الشام زراعاتها وقصورها)\n(على حين لم أترك على الأرض حية ... ولا نابحا إلا استقر عقورها)\n(كلاب نبحن الحي من كل جانب ... فعاد عواء بعد نبح هريرها)\n(عجوز تصلي الخمس عاذت بغالب ... فلا والذي عاذت به لا أضيرها)\n(لئن نافع لم يرع أرحام أمه ... وكانت كدلو لا يزال يعيرها)\n(لبئس دم المولود بل ثيابها ... عشية نادى بالغلام بشيرها)\n(وإني على إشفاقها من مخافتي ... وإن عقها بي نافع لمجيرها)\n(ولو أن أم الناس حواء جاورت ... تميم بن مر لم تجد من يجيرها)\nهذا البيت يروى لغيره في غير هذه القصيدة أخبرني عبد الله بن مالك قال حدثنا محمد بن حبيب قال حدثنا أحمد بن حاتم المعروف بابن نصر عن الأصمعي قال كان عبد الله بن عطية راوية الفرزدق وجرير قال فدعاني الفرزدق يوما فقال إني قلت بيت شعر والنوار طالق إن نقضه ابن المراغة قلت ما هو قال قلت\n(فإني أنا الموت الذي هو نازل ... بنفسك فانظر كيف أنت تحاوله)\nرحل إليه بالبيت قال فرحلت إلى اليمامة قال ولقيت جريرا بفناء بيته يعبث بالرمل فقلت إن الفرزدق قال بيتا وحلف بطلاق النوار أنك لا تنقضه قال هيه أظن والله ذلك ما هو ويلك فأنشدته إياه فجعل يتمرغ في الرمل ويحثوه على رأسه وصدره حتى كادت الشمس تغرب ثم قال أنا أبو حزرة طلقت امرأة الفاسق وقال\n(أنا الدهر يفنى الموت والدهر خالد ... فجئني بمثل الدهر شيئا يطاوله)\nرحل إلى الفاسق قال فقدمت على الفرزدق فأنشدته إياه وأعلمته بما قال فقال أقسمت عليك لما سترت هذا الحديث أخبرني عبد الله قال أخبرني محمد بن حبيب قال حدثنا الأصمعي وأبو عبيدة قال\nدخل الفرزدق على بلال بن أبي بردة وعنده ناس من اليمامة فضحكوا فقال يا أبا فراس أتدري مم ضحكوا قال لا قال من جفائك قال أصلح الله الأمير حججت فإذا أنا برجل منهم على عاتقه الأيمن صبي وعلى عاتقه الأيسر صبي وإذا امرأة آخذة بمئزره وهو يقول\n(أنت وهبت زائدا ومزيدا ... وكهلة أولج فيها الأجردا)\nالمرأة تقول من خلفه إذا شئت فسألت ممن هو فقيل من الأشعريين أفأنا أجفى أم ذلك فقال بلال لا حياك الله قد علمت أنهم لن يفتلوا منك أخبرني عبد الله بن مالك\nقال حدثني محمد بن حبيب قال حدثنا موسى بن طلحة عن أبي زيد الأنصاري قال ركب الفرزدق بغلته فمر بنسوة فلما حاذاهن لم تتمالك البغلة أن ضرطت فضحكن منه فالتفت إليهن فقال لا تضحكن فما حملتني أنثى إلا ضرطت فقالت له إحداهن ما حملتك أنثى أكثر من أمك فأراها قاست منك ضراطا كثيرا فحرك بغلته وهرب منهن وبهذا الإسناد\nقال أتى الفرزدق الحسن البصري فقال إني قد هجوت إبليس فقال كيف تهجوه وعن لسانه تنطق وبهذا الإسناد قال حمزة بن بيض للفرزدق يا أبا فراس أسألك عن مسألة قال سل عما أحببت قال أيما أحب إليك أتسبق الخير أم\nيسبقك قال إن سبقني فاتني وإن سبقته فته ولكن نكون معا لا يسبقني ولا أسبقه ولكن أسألك عن مسألة قال ابن بيض سل قال أيما أحب إليك أن تنصرف إلى منزلك فتجد امرأتك قابضة على أير رجل أم تراه قابضا على هنها قال فتحير وكان قد نهي عنه فلم يقبل","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":26,"spl":"قبر أبيه معاذ الناس","tags":["الفرزدق","الهجاء"],"loc":1942},
{"id":"b112-51","bab":"الجزء 10","sec":"هو وجرير لا يصطلحان أبدا","page":"ج10 ص359","text":"أخبرني عبد الله قال حدثني محمد بن عمران الضبي قال حدثني الأصمعي قال اجتمع الفرزدق وجرير عند بشر بن مروان فرجا أن يصلح بينهما حتى يتكافا فقال لهما ويحكما قد بلغتما من السن ما قد بلغتما وقربت آجالكما فلوا اصطلحتما ووهب كل واحد منكما لصاحبه ذنبه فقال جرير أصلح الله الأمير إنه يظلمني ويتعدى علي فقال الفرزدق أصلح الله الأمير إني وجدت آبائي يظلمون آباءه فسلكت طريقهم في ظلمه فقال بشر عليكما لعنة الله لا تصطلحان والله أبدا\nوأخبرني عبد الله بن مالك قال حدثنا محمد بن عمران الضبي قال حدثنا الأصمعي قال الفرزدق ما أعياني جواب أحد ما أعياني جواب دهقان مرة قال لي أنت الفرزدق الشاعر\nقلت نعم قال أفأموت إن هجوتني قلت لا قال أفتموت عيشونة ابنتي قلت لا قال فرجلي إلى عنقي في حر أمك قال قلت ويلك لم تركت رأسك قال حتى أنظر أي شيء تصنع أخبرني عبد الله قال حدثنا محمد بن حبيب عن الأصمعي قال\nمر الفرزدق بمأجل فيه ماء فأشرع بغلته فيه فقال له مجنون بالبصرة يقال له حربيش نح بغلتك جذ الله رجليك قال ولم ويلك قال لأنك كذوب الحنجرة زاني الكمرة فقال الفرزدق لبغلته عدس ومضى وكره أن يسمع قوله الناس","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":27,"spl":"هو وجرير لا يصطلحان أبدا — يؤثر القصائد القصار — بيتان لكثير يغيران لون وجهه","tags":["الفرزدق"],"loc":1943},
{"id":"b112-53","bab":"الجزء 10","sec":"يؤثر القصائد القصار — بيتان لكثير يغيران لون وجهه","page":"ج10 ص360 – ج10 ص361","text":"أخبرنا عبد الله بن مالك عن ابن حبيب عن سعدان بن المبارك قال قيل للفرزدق ما اختيارك في شعرك للقصار قال لأني رأيتها أثبت في الصدور وفي المحافل أجول\nقال وقيل للحطيئة ما بال قصارك أكثر من طوالك قال لأنها في الآذان أولج وفي أفواه الناس أعلق أخبرني عبد الله بن حبيب عن سعدان بن المبارك\nقال قيل لعقيل ابن علفة مالك تقصر في هجائك قال حسبك من القلادة ما أحاط بالرقبة أخبرني عبد الله عن محمد بن علي بن سعيد الترمذي عن أحمد بن حاتم أبي نصر\nقال قال الجهم بن سويد بن المنذر الجرمي للفرزدق أما وجدت أمك اسما لك إلا الفرزدق الذي تكسره النساء في سويقها قال والعرب تسمي خبز الفتوت الفرزدق فأقبل الفرزدق على قوم معه في المجلس فقال ما اسمه فلم يخبروه باسمه فقال والله لئن لم تخبروني لأهجونكم كلكم قال\nالجهم بن سويد بن المنذر فقال الفرزدق أحق الناس ألا يتكلم في هذا أنت لأن اسمك اسم متاع المرأة واسم أبيك اسم الحمار واسم جدك اسم الكلب\nأخبرنا عبد الله بن مالك عن الزبير عن عمه عن بعض القرويين قال قدم علينا الفرزدق فقلنا له قدم علينا جرير فأنشدنا قصيدة يمدح بها هؤلاء القوم ومضى يريدهم فقال أنشدونيها فأنشدناه قصيدة كثير التي يقول فيها\n(وما زالت رقاك تسل ضغني ... وتخرج من مكامنها ضبابي)\n(ويرقيني لك الحاوون حتى ... أجابك حية تحت الحجاب)\nال فجعل وجهه يتغير وعندنا كانون ونحن في الشتاء فلما رأينا ما به قلنا هون عليك يا أبا فراس فإنما هي لابن أبي جمعة فانثنى سريعا ليسجد فأصاب ناحية الكانون وجهه فأدماه\nأخبرني عبد الله بن مالك عن محمد بن موسى قال أخبرني القحذمي قال لقي الفرزدق الحسين بن علي عليهما السلام متوجها إلى الكوفة خارجا من مكة في اليوم السادس من ذي الحجة فقال له الحسين صلوات الله عليه وآله ما وراءك قال يا بن رسول الله أنفس الناس معك وأيديهم عليك قال ويحك معي وقر بعير من كتبهم يدعونني ويناشدونني الله\nقال فلما قتل الحسين صلوات الله عليه قال الفرزدق انظروا فإن غضبت العرب لابن سيدها وخيرها فاعلموا أنه سيدوم عزها وتبقى هيبتها وإن صبرت عليه ولم تتغير لم يزدها الله إلا ذلا إلى آخر الدهر وأنشد في ذلك\n(فإن أنتم لم تثأروا لابن خيركم ... فألقوا السلاح واغزلوا بالمغازل)\nخبرنا عبد الله بن مالك قال أخبرني أبو مسلم قال حدثني الأصمعي قال أنشد الراعي الفرزدق أربع قصائد فقال له الفرزدق أعيدها عليك لقد أتى علي زمان ولو سمعت ببيت شعر وأنا أهوي في بئر ما ذهب عني\nأخبرني عبد الله بن مالك قال حدثني أبو مسلم الحراني عن الأصمعي قال تغدى الفرزدق عند صديق له ثم انصرف فمر ببني أسد فحدثهم ساعة ثم استسقى ماء فقال فتى منهم أو لبنا فقال لبنا فقام إلى عس فصب فيه رطلا من خمر ثم حلب وناوله إياه فلما كرع فيه انتفخت أوادجه واحمر وجهه ثم رد العس وقال جزاك الله خيرا فإني ما علمتك تحب أن تحفي صديقك وتخفي معروفك ثم مضى","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":27,"spl":"هو وجرير لا يصطلحان أبدا — يؤثر القصائد القصار — بيتان لكثير يغيران لون وجهه","tags":["الفرزدق"],"loc":1944},
{"id":"b112-55","bab":"الجزء 10","sec":"قصته مع المرأة الشريفة وزوجته النوار — يهجو ابن سبرة لأنه منعه عن جارية","page":"ج10 ص362 – ج10 ص363","text":"وأخبرنا عبد الله بن مالك عن محمد بن موسى عن القحذمي قال\nكان الفرزدق أراد امرأة شريفة على نفسها فامتنعت عليه وتهددها بالهجاء والفضيحة فاستغاثت بالنوار امرأته وقصت عليها القصة فقالت لها واعديه ليلة ثم أعلميني ففعلت وجاءت النوار فدخلت الحجلة مع المرأة فلما دخل الفرزدق البيت أمرت الجارية فأطفأت السراج وغادرت المرأة الحجلة واتبعها الفرزدق فصار إلى الحجلة وقد انسلت المرأة خلف الحجلة وبقيت النوار فيها فوقع بالنوار وهو لا يشك أنها صاحبته فلما فرغ قالت له يا عدو الله يا فاسق فعرف نغمتها وأنه خدع فقال لها وأنت هي يا سبحان الله ما أطيبك حراما وأردأك حلالا\nأخبرني عبد الله بن مالك قال حدثني محمد بن موسى قال حدثني القحذمي قال استعمل الحجاج الخيار بن سبرة المجاشعي على عمان فكتب إليه الفرزدق يستهديه جارية فكتب إليه الخيار\n(كتبت إلي تستهدي الجواري ... لقد أنعظت من بلد بعيد)\nفأجابه الفرزدق\n(ألا قال الخيار وكان جهلا ... قد استهدى الفرزدق من بعيد)\n(فلولا أن أمك كان عمي ... أباها كنت أخرس بالنشيد)\n(وأن أبي لعم أبيك لحا ... وأنك حين أغضب من أسودي)\n(إذا لشددت شدة أعوجي ... يدق شكيم مجدول الحديد)\nخبرنا عبد الله بن مالك عن الأصمعي قال سمع الفرزدق رجلا يقرأ ( والسارق والسارقة فاقطعوا أيديهما جزاء بما كسبا نكالا من الله والله غفور رحيم\nفقال لا ينبغي أن يكون هذا هكذا قال فقيل له إنما هو ( عزيز حكيم\nقال هكذا ينبغي أن يكون","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":28,"spl":"قصته مع المرأة الشريفة وزوجته النوار — يهجو ابن سبرة لأنه منعه عن جارية — اغتلم فاحتال على","tags":["الفرزدق","الهجاء","الجواري والنساء"],"loc":1945},
{"id":"b112-56","bab":"الجزء 10","sec":"يمدح أسماء بن خارجة","page":"ج10 ص364","text":"أخبرنا عبد الله بن مالك قال حدثنا أبو مسلم قال حدثنا الأصمعي قال مر أسماء بن خارجة الفزاري على الفرزدق وهو يهنأ بعيرا له بنفسه فقال له أسماء يا فرزدق كسد شعرك واطرحتك الملوك فصرت إلى مهنة إبلك فقد أمرت لك بمائة بعير فقال الفرزدق فيه يمدحه\n(إن السماح الذي في الناس كلهم ... قد حازه الله للمفضال أسماء)\n(يعطي الجزيل بلا من يكدره ... عفوا ويتبع آلاء بنعماء)\n(ما ضر قوما إذا أمسى يجاورهم ... ألا يكونوا ذوي إبل ولا شاء)\nخبرني عبد الله بن مالك عن محمد بن موسى بن طلحة قال قال أبو عبيدة\nدخل الفرزدق على بلال بن أبي بردة فأنشده قصيدته المشهورة فيهم التي يقول فيها\n(فإن أبا موسى خليل محمد ... وكفاه يمنى للهدى وشمالها)\nقال ابن أبي بردة هلكت والله يا أبا فراس فارتاع الشيخ وقال كيف ذاك قال ذهب شعرك أين مثل شعرك في سعيد وفي العباس بن الوليد وسمى قوما فقال جئني بحسب مثل أحسابهم حتى أقول فيك كقولي فيهم فغضب بلال حتى درت أوداجه ودعي له بطست فيه ماء بارد فوضع يده فيها حتى سكن فكلمه فيه جلساؤه وقالوا قد كفاك الشيخ نفسه وقل ما يبقى حتى يموت فلم يحل عليه الحول حتى مات","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":28,"spl":"قصته مع المرأة الشريفة وزوجته النوار — يهجو ابن سبرة لأنه منعه عن جارية — اغتلم فاحتال على","tags":["الفرزدق","المديح","اللهو والمزاح"],"loc":1946},
{"id":"b112-57","bab":"الجزء 10","sec":"اغتلم فاحتال على قابلة","page":"ج10 ص365","text":"أخبرنا عبد الله بن مالك عن محمد بن موسى عن سعيد بن همام اليمامي قال شرب الفرزدق شرابا باليمامة وهو يريد العراق فقال لصاحب له إن الغلمة قد آذتني فأكسبني بغيا\nقال من أين أصيب لك ها هنا بغيا قال فلا بد لك من أن تحتال قال فمضى الرجل إلى القرية وترك الفرزدق ناحية فقال هل من امرأة تقبل فإن معي امرأتي وقد أخذها الطلق فبعثوا معه امرأة فأدخلها على الفرزدق وقد غطاه فلما دنت منه واثبها ثم ارتحل مبادرا وقال كأني بابن الخبيثة يعني جريرا لو قد بلغه الخبر قد قال\n(وكنت إذا حللت بدار قوم ... رحلت بخزية وتركت عارا)\nال فبلغ جريرا الخبر فهجاه بهذا الشعر وأخبرنا عبد الله بن مالك عن محمد بن موسى قال قال أبو نهشل حدثنا بعض أصحابنا قال وقف الفرزدق على الشمردل وهو ينشد قصيدة له فمر هذا البيت في بعض قوله\n(وما بين من لم يعط سمعا وطاعة ... وبين جرير غير حز الحلاقم)\nقال الفرزدق يا شمردل لتتركن هذا البيت لي أو لتتركن عرضك قال خذه لا بارك الله لك فيه فهو في قصيدته التي ذكر فيها قتيبة بن مسلم وهي التي أولها قوله\n(تحن إلى زورا اليمامة ناقتي ... حنين عجول تبتغي البو رائم)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":28,"spl":"قصته مع المرأة الشريفة وزوجته النوار — يهجو ابن سبرة لأنه منعه عن جارية — اغتلم فاحتال على","tags":["الفرزدق"],"loc":1947},
{"id":"b112-58","bab":"الجزء 10","sec":"امراة تستعيذ بقبر أبيه","page":"ج10 ص366","text":"أخبرنا عبد الله بن مالك قال حدثنا محمد بن حبيب عن الأصمعي قال جاءت امرأة إلى قبر غالب أبي الفرزدق فضربت عليه فسطاطا فأتاها فسألها عن أمرها فقالت إني عائذة بقبر غالب من أمر نزل بي قال لها وما هو قد ضمنت خلاصك منه قالت إن ابنا لي أغزي إلى السند\nمع تميم بن زيد وهو واحدي قال انصرفي فعلي انصرافه إليك إن شاء الله قال وكتب من وقته إلى تميم بقوله\n(تميم بن زيد لاتكونن حاجتي ... بظهر فلا يخفى علي جوابها)\n(وهب لي حبيشا واتخذ قيه منة ... لحرمة أم ما يسوغ شرابها)\n(أتتني فعاذت يا تميم بغالب ... ويالحفرة السافي عليها ترابها)\nال فعرض تميم جميع من معه من الجند فلم يدع أحدا اسمه حبيش ولا حنيش إلا وصله وأذن له في الانصراف إلى أهله أخبرنا عبد الله بن مالك قال أخبرنا محمد بن حبيب عن الأصمعي\nقال مر الفرزدق بصديق له فقال له ما تشتهي يا أبا فراس قال أشتهي شواء رشراشا ونبيذا سعيرا وغناء يفتق السمع الرشراش الرطب والسعير الكثير أخبرنا عبد الله بن مالك\nقال حدثنا محمد بن حبيب قال حدثني السعدي عن أبي مالك الزيدي قال أتينا الفرزدق لنسمع منه شيئا فجلسنا ببابه ننتظر إذ خرج علينا في ملحفة فقال لنا يا أعداء الله ما اجتماعكم ببابي والله لو أردت أن أزني ما قدرت\nأخبرني عبد الله بن مالك قال حدثنا أبو مسلم قال حدثنا الأصمعي عن هشام بن القاسم قال قال الفرزدق قد علم الناس أني فحل الشعراء وربما أتت علي\nالساعة لقلع ضرس من أضراسي أهون علي من قول بيت شعر حدثنا عبد الله بن مالك عن أبي مسلم عن الأصمعي قال كان الفرزدق وأبو شقفل راويته في المسجد فدخلت امرأة فسألت عن مسالة مسألة وتوسمت فرأت هيئة أبي شقفل فسألته عن مسألتها فقال الفرزدق\n(أبو شقفل شيخ عن الحق جائر ... بباب الهدى والرشد غير بصير)\nفقالت المرأة سبحان الله أتقول هذا لمثل هذا الشيخ فقال أبو شقفل دعيه فهو أعلم بي","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":29,"spl":"امراة تستعيذ بقبر أبيه — يطالب معاوية بتراث عمه","tags":["الفرزدق","الجواري والنساء"],"loc":1948},
{"id":"b112-59","bab":"الجزء 10","sec":"سكينة بنت الحسين تكذب ادعاءاته","page":"ج10 ص368","text":"أخبرنا عبد الله بن مالك قال حدثنا محمد بن موسى قال حدثنا المدائني قال خرج الفرزدق حاجا فمر بالمدينة فأتى سكينة بنت الحسين صلوات الله عليه وآله فقالت يا فرزدق من أشعر الناس قال أنا قالت كذبت أشعر منك الذي يقول\n(بنفسي من تجنبه عزيز ... علي ومن زيارته لمام)\n(ومن أمسي وأصبح لا أراه ... ويطرقني إذا هجع النيام)\nفقال والله لو أذنت لي لأسمعتك أحسن منه فقالت أقيموه فأخرج ثم عاد إليها في اليوم الثاني فقالت له يا فرزدق من أشعر الناس قال أنا قالت كذبت أشعر منك الذي يقول\n(لولا الحياء لهاجني استعبار ... ولزرت قبرك والحبيب يزار)\n(لا يلبث القرفاء أن يتفرقوا ... ليل بكر عليهم ونهار)\n(كانت إذا هجر الضجيع فراشها ... كتم الحديث وعفت الأسرار)\nال أفأسمعك أحسن منه قالت اخرج ثم عاد إليها في اليوم الثالث وعلى رأسها جارية كأنها ظبية فاشتد عجبه بها فقالت يا فرزدق من أشعر الناس قال أنا قالت كذبت أشعر منك الذي يقول\n(إن العيون التي في طرفها مرض ... قتلننا ثم لم يحيين قتلانا)\n(يصرعن ذا اللب حتى لا حراك له ... وهن أضعف خلق الله أركانا)\nم قالت قم فاخرج فقال لها يا بنت رسول الله إن لي عليك لحقا إذ كنت إنما جئت مسلما عليك فكان من تكذيبك إياي وصنيعك بي حين أردت أن أسمعك شيئا من شعري ما ضاق به صدري والمنايا تغدو وتروح ولا أدري لعلي لا أفارق المدينة حتى أموت فإن مت فمري من يدفنني في حر هذه الجارية التي على رأسك فضحكت سكينة حتى كادت تخرج من ثيابها وأمرت له بالجارية وقالت أحسن صحبتها فقد\nآثرتك بها على نفسي قال فخرج وهو آخذ بريطتها","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":29,"spl":"امراة تستعيذ بقبر أبيه — يطالب معاوية بتراث عمه","tags":["الفرزدق","الحب والغزل"],"loc":1949},
{"id":"b112-60","bab":"الجزء 10","sec":"يطالب معاوية بتراث عمه","page":"ج10 ص369","text":"أخبرنا عبد الله بن مالك قال حدثنا محمد بن موسى قال حدثنا المدائني قال وفد الحتات عم الفرزدق على معاوية فخرجت جوائزهم فانصرفوا ومرض الحتات فأقام عند معاوية حتى مات فأمر معاوية بماله فأدخل بيت المال فخرج الفرزدق إلى معاوية وهو غلام فلما أذن للناس دخل بين السماطين ومثل بين يدي معاوية فقال\n(أبوك وعمي يا معاوي ورثا ... تراثا فيحتاز التراث أقاربه)\n(فما بال ميراث الحتات أكلته ... وميراث حرب جامد لي ذائبه)\n(فلو كان هذا الأمر في جاهلية ... علمت من المولى القليل حلائبه)\n(ولو كان هذا الأمر في ملك غيركم ... لأداه لي أو غص بالماء شاربه)\nقال له معاوية من أنت قال أنا الفرزدق قال ادفعوا إليه ميراث عمه الحتات وكان ألف دينار فدفع إليه","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":29,"spl":"امراة تستعيذ بقبر أبيه — يطالب معاوية بتراث عمه","tags":["الفرزدق","الموت"],"loc":1950},
{"id":"b112-61","bab":"الجزء 10","sec":"امرأة ترجز به فيذكرها بشعر فاحش","page":"ج10 ص370","text":"أخبرنا عبد الله بن مالك عن أبي حمزة الأنصاري قال أخبرنا أبو زيد قال قال أبو عبيدة\nانصرف الفرزدق من عند بعض الأمراء في غداة بادرة وأمر بجزور فنحرت ثم قسمت فأغفل امرأة من بني فقيم نسيها فرجزت به فقالت\n(فيشلة هدلاء ذات شقشق ... مشرفة اليافوخ والمحوق)\n(مدمجة ذات حفاف أخلق ... نيطت بحقوي قطم عشنق)\n(أولجتها في سبة الفرزدق ... )\nال أبو عبيدة فبلغني أنه هرب منها فدخل في بيت حماد بن الهيثم ثم إن الفرزدق قال فيها بعد ذلك\n(قتلت قتيلا لم ير الناس مثله ... أقلبه ذا تومتين مسورا)\n(حملت عليه حملتين بطعنة ... فغادرته فوق الحشايا مكورا)\n(ترى جرحه من بعد ما قد طعنته ... يفوح كمثل المسك خالط عنبرا)\n(وما هو يوم الزحف بارز قرنه ... ولا هو ولى يوم لاقى فأدبرا)\n(بني دارم ما تأمرون بشاعر ... برود الثنايا ما يزال مزعفرا)\n(إذا ما هو استلقى رأيت جهازه ... كمقطع عنق الناب أسود أحمرا)\n(وكيف أهاجي شاعرا رمحه استه ... أعد ليوم الروع درعا ومجمرا)\nفقالت المرأة ألا لا أرى الرجال يذكرون مني هذا وعاهدت الله ألا تقول شعرا أخبرنا عبد الله بن مالك بن مسلم عن الأصمعي قال مر الفرزدق يوما في الأزد فوثب عليه ابن أبي علقمة لينكحه وأعانه على ذلك سفهاؤهم فجاءت مشايخ الأزد وأولو النهى منهم فصاحوا بابن أبي علقمة وبأولئك السفهاء فقال لهم ابن أبي علقمة ويلكم أطيعوني اليوم واعصوني الدهر هذا شاعر مضر ولسانها قد شتم أعراضكم وهجا ساداتكم والله لا تنالون من مضر مثلها أبدا فحالوا بينه وبينه فكان الفرزدق يقول بعد ذلك قاتله الله إي والله لقد كان أشار عليهم بالرأي","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":30,"spl":"امرأة ترجز به فيذكرها بشعر فاحش","tags":["الفرزدق","الهجاء"],"loc":1951,"partial":1}]);
window.__BOOK__['p05'].push([{"id":"b112-62","bab":"الجزء 10","sec":"رجل من الأنصار يتحداه بشاعرهم حسان بن ثابت","page":"ج10 ص372","text":"أخبرني عبد الله بن مالك قال حدثنا محمد بن حبيب قال قال الكلبي قال إبراهيم بن محمد بن سعد بن أبي وقاص وأخبرنا بهذا الخبر محمد بن العباس اليزيدي والأخفش جميعا عن السكري عن ابن حبيب عن أبي عبيدة والكلبي\nقال وأخبرنا به إبراهيم بن سعدان عن أبيه عن أبي عبيدة قالوا جميعا قدم الفرزدق المدينة في إمارة أبان بن عثمان فأتى الفرزدق وكثير عزة فبينا هما يتناشدان الأشعار إذ طلع عليهما غلام شخت رقيق الأدمة في ثوبين ممصرين فقصد نحونا فلم يسلم وقال أيكم الفرزدق فقلت مخافة أن يكون من قريش أهكذا تقول لسيد العرب وشاعرها فقال لو كان\nكذلك لم أقل هذا فقال له الفرزدق من أنت لا أم لك قال رجل من الأنصار ثم من بني النجار ثم أنا ابن أبي بكر بن حزم بلغني أنك تزعم أنك أشعر العرب وتزعمه مضر وقد قال شاعرنا حسان بن ثابت شعرا فأردت أن اعرضه عليك وأؤجلك سنة فإن قلت مثله فأنت أشعر العرب كما قيل وإلا فأنت منتحل كذاب ثم أنشده\n(ألم تسأل الربع الجديد التكلما ... )\nتى بلغ إلى قوله\n(وأبقى لنا مر الحروب ورزؤها ... سيوفا وأدراعا وجما عرمرما)\n(متى ما تردنا من معد عصابة ... وغسان نمنع حوضنا أن يهدما)\n(لنا حاضر فعم وباد كأنه ... شماريخ رضوى عزة وتكرما)\n(أبى فعلنا المعروف أن ننطق الخنا ... وقائلنا بالعرف إلا تكلما)\n(بكل فتى عاري الأشاجع لاحه ... قراع الكماة يرشح المسك والدما)\n(ولدنا بني العنقاء وابني محرق ... فأكرم بذا خالا وأكرم بذا ابنما)\n(يسود ذا المال القليل إذا بدت ... مروءته فينا وإن كان معدما)\n(وإنا لنقري الضيف إن جاء طارقا ... من الشحم ما أمسى صحيحا مسلما)\n(لنا الجفنات الغر يلمعن بالضحى ... وأسيافنا يقطرن من نجدة دما)\nأنشده القصيدة وهي نيف وثلاثون بيتا وقال له قد أجلتك في\nجوابها حولا فانصرف الفرزدق مغضبا يسحب رداءه وما يدري أية طرقه حتى خرج من المسجد فأقبل على كثير فقال له قاتل الله الأنصار ما أفصح لهجتهم وأوضح حجتهم وأجود شعرهم فلم نزل في حديث الأنصار والفرزدق بقية يومنا حتى إذا كان من الغد خرجت من منزلي إلى المسجد الذي كنت فيه بالأمس فأتى كثير فجلس معي وإنا لنتذاكر الفرزدق ونقول ليت شعري ما صنع إذ طلع علينا في حلة أفواف قد أرحى غديرته حتى جلس في مجلسه بالأمس ثم\nقال ما فعل الأنصاري فنلنا منه وشتمناه فقال قاتله الله ما منيت بمثله ولا سمعت بمثل شعره فارقته وأتيت منزلي فأقبلت أصعد وأصوب في كل فن من الشعر فكأني مفحم لم أقل شعرا قط حتى إذا نادى المنادي بالفجر رحلت ناقتي وأخذت بزمامها حتى أتيت ريانا وهو جبل بالمدينة ثم ناديت بأعلى صوتي أخاكم أخاكم يعني شيطانه فجاش صدري كما يجيش المرجل فعقلت ناقتي وتوسدت ذراعها فما عتمت حتى\nقلت مائة بيت من الشعر وثلاثة عشر بيتا فبينا هو ينشد إذ طلع الأنصاري حتى إذا انتهى إلينا سلم علينا ثم قال إني لم آتك لأعجلك عن الأجل الذي وقته لك ولكني أحببت ألا أراك إلا سألتك إيش صنعت فقال اجلس وأنشده قوله\n(عزفت بأعشاش وما كنت تعزف ... وأنكرت من حدراء ما كنت تعرف)\n(ولج بك الهجران حتى كأنما ... ترى الموت في البيت الذي كنت تألف)\nفي رواية ابن حبيب تيلف حتى بلغ إلى قوله\n(ترى الناس ما سرنا يسيرون خلفنا ... وإن نحن أومأنا إلى الناس وقفوا)\nأنشدها الفرزدق حتى بلغ إلى آخرها فقام الأنصاري كئيبا فلما توارى طلع أبوه أبو بكر بن حزم في مشيخة من الأنصار فسلموا عليه وقالوا يا أبا فراس قد عرفت حالنا ومكاننا من رسول الله وقد بلغنا أن سفيها من سفهائنا ربما تعرض لك فنسألك بحق الله وحق رسوله لما حفظت فينا وصية رسول الله ووهبتنا له ولم تفضحنا\nقال محمد بن إبراهيم فأقبلت عليه أكلمه فلما أكثرنا عليه قال اذهبوا فقد وهبتكم لهذا القرشي قال سليمان بن عبد الملك للفرزدق أنشدني أجود شعر عملته فأنشده\n(عزفت بأعشاش وما كدت تعزف ... )\nقال زدني فأنشده\n(ثلاث واثنتان فتلك خمس ... وواحدة تميل إلى الشمام)\n(فبتن بجانبي مصرعات ... وبت أفض أغلاق الختام)\nقال له سليمان ما أراك إلا قد أحللت نفسك للعقوبة أقررت بالزنى عندي وأنا إمام ولا تريد مني إقامة الحد عليك فقال إن أخذت في بقول الله عز و جل لم تفعل قال وما قال قال قال الله تبارك وتعالى ( والشعراء يتبعهم الغاوون ألم تر أنهم في كل واد يهيمون وأنهم يقولون","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":31,"spl":"رجل من الأنصار يتحداه بشاعرهم حسان بن ثابت","tags":["الفرزدق"],"loc":1952,"partialRef":{"sid":"b97-13","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b112-63","bab":"الجزء 10","sec":"رجل من الأنصار يتحداه بشاعرهم حسان بن ثابت","page":"ج10 ص372","text":"مالا يفعلون\nفضحك سليمان وقال تلافيتها ودرأت عنك الحد وخلع عليه وأجازه","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":32,"spl":"رجل من الأنصار يتحداه بشاعرهم حسان بن ثابت — يجتمع هو وجرير بالشام — فتى اسود يستخف به","tags":["الفرزدق","اللهو والمزاح"],"loc":1953},
{"id":"b112-65","bab":"الجزء 10","sec":"يجتمع هو وجرير بالشام — فتى اسود يستخف به","page":"ج10 ص376 – ج10 ص377","text":"أخبرنا عبد الله بن مالك قال حدثنا محمد بن حبيب عن الأصمعي قال قدم الفرزدق الشام وبها جرير بن الخطفي فقال له جرير ما ظننتك تقدم بلدا أنا فيه فقال له الفرزدق إني طالما أخلفت ظن العاجز أخبرنا عبد الله بن مالك\nقال حدثنا محمد بن موسى بن طلحة قال قال أبو مخنف كان الفرزدق لعنة أي يتلعن به كأنه لعنة على قوم وكان جرير شهابا من شهب النار أخبرنا عبد الله بن مالك\nقال حدثنا الأزدي قال حدثنا عمرو بن أبي عمرو عن أبيه قال قال أبو عمرو بن العلاء مر الفرزدق بمحمد بن وكيع بن أبي سود وهو على ناقة فقال له غدني\nقال ما يحضرني غداء قال فاسقني سويقا قال ما هو عندي قال فاسقني نبيذا قال أو صاحب نبيذ عهدتني قال فما يقعدك في الظل قال فما أصنع قال أطل وجهك بدبس ثم تحول إلى الشمس واقعد فيها حتى يشبه لونك لون أبيك الذي تزعمه قال أبو عمرو فما زال ولد محمد يسبون بذلك من قول الفرزدق انتهى أخبرنا عبد الله بن مالك عن ابن حبيب عن موسى بن طلحة عن\nأبي عبيدة عن أبي العلاء قال أخبرني هاشم بن القاسم العنزي انه قال جمعني والفرزدق مجلس فتجاهلت عليه فقلت له من أنت قال أما تعرفني قلت لا\nقال فأنا أبو فراس قلت ومن أبو فراس قال أنا الفرزدق قلت ومن الفرزدق قال أو ما تعرف الفرزدق قلت أعرف الفرزدق أنه شيء يتخذه النساء عندنا يتسمن به وهو الفتوت فضحك\nوقال الحمد الله الذي جعلني في بطون نسائكم أخبرني عبد الله بن مالك عن محمد بن حبيب عن النضر بن حديد قال مر الفرزدق بماء لبني كليب مجتازا فأخذوه وكان جبانا فقالوا والله لتلقين منا ما تكره أو لتنكحن هذه الأتان وأتوه بأتان فقال ويلكم اتقوا الله فإنه شيء ما فعلته قط فقالوا إنه لا ينجيك والله إلا الفعل قال أما إذا أبيتم فأتوني بالصخرة التي يقوم عليها عطية فضحكوا وقالوا اذهب لا صحبك الله\nأخبرنا عبد الله بن مالك عن محمد بن موسى عن العتبي قال دخل الفرزدق على قوم يشربون عند رجل بالبصرة وفي صدر مجلسهم فتى أسود وعلى رأسه إكليل فلم يحفل بالفرزدق ولم يحف به تهاونا فغضب الفرزدق من ذلك وقال\n(جلوسك في صدر الفراش مذلة ... ورأسك في الإكليل إحدى الكبائر)\n(وما نطفت كأس ولا لذ طعمها ... ضربت على حافاتها بالمشافر)\nأخبرني عبد الله بن مالك عن محمد بن موسى عن العتبي قال لما مات وكيع بن أبي سود أقبل الفرزدق حين أخرج وعليه قميص أسود وقد شقه إلى سرته وهو يقول\n(فمات ولم يوتر وما من قبيلة ... من الناس إلا قد أباءت على وتر)\n(وإن الذي لاقى وكيعا وناله ... تناول صديق النبي أبا بكر)\nال فعلق الناس الشعر فجعلوا ينشدونه حتى دفن وتركوا الاستغفار له","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":32,"spl":"رجل من الأنصار يتحداه بشاعرهم حسان بن ثابت — يجتمع هو وجرير بالشام — فتى اسود يستخف به","tags":["الفرزدق","اللهو والمزاح"],"loc":1954},
{"id":"b112-66","bab":"الجزء 10","sec":"ميميته المشهورة في مدح زين العابدين","page":"ج10 ص378","text":"أخبرنا عبد الله بن علي بن الحسن الهاشمي عن حيان بن علي العنزي عن مجالد عن الشعبي قال حج الفرزدق بعد ما كبر وقد أتت له سبعون سنة وكان هشام بن عبد الملك قد حج في ذلك العام فرأى علي بن الحسين في غمار الناس في الطواف فقال من هذا الشاب الذي تبرق أسرة وجهه كأنه مرآة صينية تتراءى فيها عذارى الحي وجوهها فقالوا هذا علي بن الحسين بن علي بن أبي طالب صلوات الله عليهم فقال الفرزدق\n(هذا الذي تعرف البطحاء وطأته ... والبيت يعرفه والحل والحرم)\n(هذا ابن خير عباد الله كلهم ... هذا التقي النقي الطاهر العلم)\n(هذا ابن فاطمة إن كنت جاهله ... بجده أنبياء الله قد ختموا)\n(وليس قولك من هذا بضائره ... العرب تعرف من أنكرت والعجم)\n(إذا رأته قريش قال قائلها ... إلى مكارم هذا ينتهي الكرم)\n(يغضي حياء ويغضى من مهابته ... فما يكلم إلا حين يبتسم)\n(بكفه خيزران ريحها عبق ... من كف أروع في عرنينه شمم)\n(يكاد يمسكه عرفان راحته ... ركن الحطيم إذا ما جاء يستلم)\n(الله شرفه قدما وعظمه ... جرى بذاك له في لوحه القلم)\n(أي الخلائق ليست في رقابهم ... لأولية هذا أوله نعم)\n(من يشكر الله يشكر أولية ذا ... فالدين من بيت هذا ناله الأمم)\n(ينمي إلى ذروة الدين التي قصرت ... عنها الأكف وعن إدراكها القدم)\n(من جده دان فضل الأنبياء له ... وفضل أمته دانت له الأمم)\n(مشتقة من رسول الله نبعته ... طابت مغارسه والخيم والشيم)\n(ينشق ثوب الدجى عن نور غرته ... كالشمس تنجاب عن إشراقها الظلم)\n(من معشر حبهم دين وبغضهم ... كفر وقربهم منجى ومعتصم)\n(مقدم بعد ذكر الله ذكرهم ... في كل بدء ومختوم به الكلم)\n(إن عد أهل التقى كانوا أئمتهم ... أو قيل من خير أهل الأرض قيل هم)\n(لا يستطيع جواد كنه جودهم ... ولا يدانيهم قوم وإن كرموا)\n(يستدفع الشر والبلوى بحبهم ... ويسترب به الإحسان والنعم)\nقد حدثني بهذا الخبر أحمد بن الجعد قال حدثنا أحمد بن القاسم البرتي قال حدثنا إسحاق بن محمد النخعي فذكر أن هشاما حج في حياة\nأبيه فرأى علي بن الحسين رضي الله تعالى عنهم يطوف بالبيت والناس يفرجون له فقال من هذا فقال الأبرش الكلبي ما أعرفه فقال الفرزدق ولكني أعرفه فقال من هو فقال\n(هذا الذي تعرف البطحاء وطأته ... )\nذكر الأبيات الخ قال فغضب هشام فحبسه بين مكة والمدينة فقال\n(أتحبسني بين المدينة والتي ... إليها قلوب الناس يهوى منيبها)\n(يقلب رأسا لم يكن رأس سيد ... وعينا له حولاء باد عيوبها)\nبلغ شعره هشاما فوجه فأطلقه","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":33,"spl":"ميميته المشهورة في مدح زين العابدين — يعجب بشعر لحائك","tags":["الفرزدق","السفر والحج"],"loc":1955,"partial":1},
{"id":"b112-67","bab":"الجزء 10","sec":"يعجب بشعر لحائك","page":"ج10 ص380","text":"أخبرنا عبد الله بن مالك عن محمد بن موسى عن الهيثم بن عدي قال اخبرنا أبو روح الراسبي قال لما ولي خالد بن عبد الله العراق ولى مالك بن المنذر شرطة البصرة فقال الفرزدق\n(يبغض فينا شرطة المصر أنني ... رأيت عليها مالكا عقب الكلب)\nال فقال مالك علي به فمضوا به إليه فقال\n(أقول لنفسي إذ تغص بريقها ... ألا ليت شعري ما لها عند مالك)\nقال فسمع قوله حائك يطلع من طرازه فقال\n(لها عنده أن يرجع الله ريقها ... إليها وتنجو من عظيم المهالك)\nقال الفرزدق هذا أشعر الناس وليعودن مجنونا يصيح الصبيان في أثره فقال فرأوه بعد ذلك مجنونا يصيح الصبيان في أثره أخبرنا عبد الله بن مالك قال حدثنا محمد بن علي بن سعيد قال حدثنا القحذمي قال فلما أتوا مالك بن المنذر بالفرزدق قال هيه عقب الكلب قال ليس هذا هكذا قلت وإنما قلت\n(ألم ترني ناديت بالصوت مالكا ... ليسمع لما غص من ريقه الفم)\n(أعوذ بقبر فيه أكفان منذر ... فهن لأيدي المستجيرين محرم)\nال قد عذت بمعاذ وخلى سبيله","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":33,"spl":"ميميته المشهورة في مدح زين العابدين — يعجب بشعر لحائك","tags":["الفرزدق","الرواية والكتابة"],"loc":1956},
{"id":"b112-68","bab":"الجزء 10","sec":"خالد القسري يأمر مالك بن المنذر بطلب الفرزدق","page":"ج10 ص381","text":"أخبرنا عبد الله قال حدثني محمد بن موسى قال كتب خالد القسري إلى مالك بن المنذر يأمره بطلب الفرزدق ويذكر أنه بلغه أنه هجاه وهجا نهره المبارك وهو النهر الذي بواسط الذي كان\nخالد حفره فاشتد مالك في طلبه حتى ظفر به في البراجم فأخذه وحبسه ومروا به على بني مجاشع فقال يا قوم اشهدوا أنه لا خاتم بيدي وذلك أنه أخذ عمر بن يزيد بن أسيد ثم أمر به فلويت عنقه ثم أخرجوه ليلا إلى السجن فجعل رأسه يتقلب والأعوان يقولون له قوم رأسك فلما أتوا به السجان\nقال لا أتسلمه منكم ميتا فأخذوا المفاتيح منه وأدخلوه الحبس وأصبح ميتا فسمعوا أنه مص خاتمه وكان فيه سم فمات وتكلم الناس في أمره فدخل لبطة بن الفرزدق على أبيه فقال يا بني هل كان من خبر قال نعم عمر بن يزيد مص خاتمه في الحبس وكان فيه سم فمات فقال الفرزدق والله يا بني لئن لم تلحق بواسط ليمص أبوك خاتمه وقال في ذلك\n(ألم يك قتل عبد الله ظلما ... أبا حفص من الحرم العظام)\n(قتيل عداوة لم يجن ذنبا ... يقطع وهو يهتف للإمام)\nال وكان عمر عارض خالدا وهو يصف لهشام طاعة أهل اليمن وحسن موالاتهم ونصيحتهم فصفق عمرو بن يزيد إحدى يديه على الأخرى حتى سمع له في الإيوان دوي ثم\nقال كذب والله يا أمير المؤمنين ما أطاعت اليمانية ولا نصحت أليس هم أعداؤك وأصحاب يزيد بن المهلب وابن الأشعث والله ما ينعق ناعق إلا أسرعوا الوثبة إليه فاحذرهم يا أمير المؤمنين\nقال فتبين ذلك في وجه هشام ووثب رجل من بني أمية فقال لعمرو بن يزيد وصل الله رحمك وأحسن جزاءك فلقد شددت من أنفس قومك وانتهزت الفرصة في وقتها ولكن أحسب هذا الرجل سيلي العراق وهو منكر حسود وليس يخار لك إن ولي فلم يرتدع عمر بقوله وظن أنه\nلا يقدم عليه فلما ولي لم تكن له همة غيره حتى قتله قال","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":34,"spl":"خالد القسري يأمر مالك بن المنذر بطلب الفرزدق — يهرب من زياد","tags":["الفرزدق","الحب والغزل"],"loc":1957},
{"id":"b112-69","bab":"الجزء 10","sec":"شفاعة جرير له","page":"ج10 ص382","text":"ثم إن مالكا وجه الفرزدق إلى خالد فلما قدم عليه وجده قد حج واستخلف أخاه أسد بن عبد الله على العراق فحبسه أسد ووافق عنده جريرا فوثب يشفع له وقال إن رأى الأمير أن يهبه لي فقال أسد أتشفع له يا جرير فقال إن ذلك أذل له أصلحك الله وكلم أسدا ابنه المنذر فخلى سبيله فقال الفرزدق في ذلك\n(لا فضل إلا فضل أم على ابنها ... كفضل أبي الأشبال عند الفرزدق)\n(تداركني من هوة دون قعرها ... ثمانون باعا للطوال العشنق)\nقال جرير يذكر شفاعته له\n(وهل لك في عان وليس بشاكر ... فتطلق عنه عض مس الحدائد)\n(يعود وكان الخبث منه سجية ... وإن قال إني منته غير عائد)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":34,"spl":"خالد القسري يأمر مالك بن المنذر بطلب الفرزدق — يهرب من زياد","tags":["الفرزدق"],"loc":1958},
{"id":"b112-70","bab":"الجزء 10","sec":"هجاؤه بني فقيم","page":"ج10 ص383","text":"أخبرني عبيد الله عن محمد بن موسى عن القحذمي قال كان سبب هرب الفرزدق من زياد وهو على العراق أنه كان هجا بني فقيم فقال فيهم أبياتا منها\n(وآب الوفد وفد بني فقيم ... بأخبث ما تؤوب به الوفود)\n(أتونا بالقرود معادليها ... فصار الجد للجد السعيد)\nقال يهجو زيد بن مسعود الفقيمي والأشهب بن رميلة بأبيات منها قوله\n(تمنى ابن مسعود لقائي سفاهة ... لقد قال مينا يوم ذاك ومنكرا)\n(غناء قليل عن فقيم ونهشل ... مقام هجين ساعة ثم أدبرا)\nعني الأشهب بن رميلة وكان الأشهب خطب إلى بني فقيم فردوه وقالوا له اهج الفرزدق حتى نزوجك فرجز به الأشهب فقال\n(يا عجبا هل يركب القين الفرس ... وعرق القين على الخيل نجس)\n(وإنما سلاحه إذا جلس ... الكلبتان والعلاة والقبس)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":34,"spl":"خالد القسري يأمر مالك بن المنذر بطلب الفرزدق — يهرب من زياد","tags":["الفرزدق","الهجاء"],"loc":1959},
{"id":"b112-71","bab":"الجزء 10","sec":"يهرب من زياد","page":"ج10 ص384","text":"فلما بلغ الفرزدق قوله هجاه فأرفث له وألح الفرزدق على النهشليين بالهجاء فشكوه إلى زياد وكان يزيد بن مسعود ذا منزلة عند زياد فطلبه زياد فهرب فأتى بكر بن وائل فأجاروه فقال الفرزدق يمدحهم بأبيات\n(إني وإن كانت تميم عمارتي ... وكنت إلى القرموس منها القماقم)\n(لمثن على أبناء بكر بن وائل ... ثناء يوافي ركبهم في المواسم)\n(همو يوم ذي قار أناخوا فجالدوا ... برأس به تدمى رؤوس الصلادم)\nهرب حتى أتى سعيد بن العاصي فأقام بالمدينة يشرب ويدخل إلى القيان وقال\n(إذا تشئت غناني من العاج قاصف ... على معصم ريان لم يتخدد)\n(لبيضاء من أهل المدينة لم تعش ... ببؤس ولم تتبع حمولة مجحد)\n(وقامت تخشيني زيادا وأجفلت ... حوالي في برد يمان ومجسد)\n(فقلت دعيني من زياد فإنني ... أرى الموت وقافا على كل مرصد)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":34,"spl":"خالد القسري يأمر مالك بن المنذر بطلب الفرزدق — يهرب من زياد","tags":["الفرزدق","الهجاء"],"loc":1960},
{"id":"b112-72","bab":"الجزء 10","sec":"مروان يتوعده ويؤجله ثلاثا","page":"ج10 ص385","text":"فبلغ شعره مروان فدعاه وتوعده وأجله ثلاثا وقال اخرج عني فأنشأ يقول الفرزدق\n(دعانا ثم أجلنا ثلاثا ... كما وعدت لمهلكها ثمود)\nال مروان قولوا له عني إني أجبته فقلت\n(قال للفرزدق والسفاهة كاسمها ... إن كنت تارك ما أمرتك فاجلس)\n(ودع المدينة إنها محظورة ... والحق بمكة أو ببيت المقدس)\nال وعزم على الشخوص إلى مكة فكتب له مروان إلى بعض عماله\nما بين مكة والمدينة بمائتي دينار فارتاب بكتاب مروان فجاء به إليه وقال\n(مروان إن مطيتي معقولة ... ترجو الحباء وربها لم ييأس)\n(آتيتني بصحيفة مختومة ... يخشى علي بها حباء النقرس)\n(ألق الصحيفة يا فرزدق لا تكن ... نكراء مثل صحيفة المتلمس)\nال ورمى بها إلى مروان فضحك وقال ويحك إنك أمي لا تقرأ فاذهب بها إلى من يقرؤها ثم ردها حتى أختمها فذهب بها فلما قرئت إذا فيها جائزة قال فردها إلى مروان فختمها وأمر له الحسين بن علي عليهما السلام بمائتي دينار قال ولما بلغ جريرا أنه أخرج عن المدينة قال\n(إذا حل المدينة فارجموه ... ولا تدنوه من جدث الرسول)\n(فما يحمى عليه شراب حد ... ولا ورهاء غائبة الحليل)\nأجابه الفرزدق فقال\n(نعت لنا من الورهاء نعتا ... قعدت به لأمك بالسبيل)\n(فلا تبغي إذا ما غاب عنها ... عطية غير نعتك من حليل)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":35,"spl":"مروان يتوعده ويؤجله ثلاثا — وصيته شعرا","tags":["الفرزدق","الحب والغزل","اللهو والمزاح"],"loc":1961},
{"id":"b112-73","bab":"الجزء 10","sec":"مرضه وموته","page":"ج10 ص386","text":"أخبرنا عبد الله بن مالك قال حدثني محمد بن موسى قال حدثنا أبو\nعكرمة الضبي عن أبي حاتم السجستاني عن محمد بن عبد الله الأنصاري قال أبو عكرمة وحكي لنا عن لبطة بن الفرزدق أن أباه أصابته ذات الجنب فكانت سبب وفاته قال ووصف له أن يشرب النفط الأبيض فجعلناه له في قدح وسقيناه إياه فقال يا بني عجلت لأبيك شراب أهل النار فقلت له يا أبت قل لا إله إلا الله فجعلت أكررها عليها مرارا فنظر الي وجعل يقول\n(فظلت تعالى باليفاع كأنها ... رماح نحاها وجهة الريح راكز)\nكان ذا هجيراه حتى مات أخبرني أبو خليفة عن محمد بن سلام قال حدثني شعيب بن صخر قال ودخل بلال بن أبي بردة على الفرزدق في مرضه الذي مات وفيه وهو يقول\n(أروني من يقوم لكم مقامي ... إذا ما الأمر جل عن الخطاب)\nلبيتين فقال بلال إلى الله إلى الله أخبرني الحسين بن يحيى عن حماد عن أبيه عن الأصمعي قال كان الفرزدق قد دبر عبيدا له وأوصى بعتقهم بعد موته ويدفع شيء من ماله إليهم فلما احتضر جمع سائر أهل بيته وأنشأ يقول\n(أروني من يقوم لكم مقامي ... إذا ما الأمر جل عن الخطاب)\n(إلى من تفزعون إذا حثوتم ... بأيديكم علي من التراب)\nقال له بعض عبيده الذين أمر بعتقهم إلى الله فأمر ببيعه قبل وفاته وأبطل وصيته فيه والله أعلم أخبرني الحسن بن علي عن بشر بن مروان عن الحميدي عن سفيان عن لبطة بن الفرزدق قال لما احتضر أبو فراس قال أي لبطة أبغني كتابا أكتب فيه وصيتي فأتيته بكتاب فكتب وصيته\n(اروني من يقوم لكم مقامي ... )\nلبيتين فقالت مولاة له قد كان أوصى لها بوصية إلى الله عز و جل فقال يا لبطة امحها من الوصية قال سفيان نعم ما قالت وبئس ما قال أبو فراس","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":35,"spl":"مروان يتوعده ويؤجله ثلاثا — وصيته شعرا","tags":["الفرزدق","الوصف والطبيعة","الخمر"],"loc":1962,"partial":1},
{"id":"b112-74","bab":"الجزء 10","sec":"وصيته شعرا","page":"ج10 ص388","text":"وقال عوانة قيل للفرزدق في مرضه الذي مات فيه أوص فقال\n(أوصي تميما إن قضاعة ساقها ... ندى الغيث عن دار بدومة أو جدب)\n(فإنكم الأكفاء والغيث دولة ... يكون بشرق من بلاد ومن غرب)\n(إذا انتجعت كلب عليكم فوسعوا ... لها الدار في سهل المقامة والرحب)\n(فأعظم من أحلام عاد حلومهم ... وأكثرهم عند العديد من الترب)\n(أشد حبال بعد حيين مرة ... حبال أمرت من تميم ومن كلب)\nقال وتوفي للفرزدق ابن صغير قبل وفاته بأيام وصلى عليه ثم التفت إلى الناس فقال\n(وما نحن إلا مثلهم غير أننا ... أقمنا قليلا بعدهم وتقدموا)\nال فلم يلبث إلا أياما حتى مات","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":35,"spl":"مروان يتوعده ويؤجله ثلاثا — وصيته شعرا","tags":["الفرزدق","الموت"],"loc":1963},
{"id":"b112-75","bab":"الجزء 10","sec":"شعره عند موته","page":"ج10 ص389","text":"وقال المدائني قال لبطة أغمي على أبي فبكينا ففتح عينيه وقال أعلي تبكون قلنا نعم أفعلى ابن المراغة نبكي فقال ويحكم أهذا موضع ذكره وقال\n(إذا ما دبت الانقاء فوقي ... وصاح صدى علي مع الظلام)\n(فقد شمتت أعاديكم وقالت ... أدانيكم من أين لنا المحامي)\nخبرني أبو خليفة الفضل بن الحباب إجازة قال حدثنا محمد بن سلام قال حدثنا أبو العراف قال نعي الفرزدق لجرير وهو عند المهاجر بن عبد الله باليمامة فقال\n(مات الفرزدق بعد ما جرعته ... ليت الفرزدق كان عاش قليلا)\nقال له المهاجر بئس ما قلت أتهجو ابن عمك بعد ما مات ولو رثيته كان أحسن بك فقال والله إني لأعلم أن بقائي بعده لقليل وأن نجمي لموافق لنجمه أفلا أرثيه قال أبعد ما قيل لك ألو كنت بكيته ما نسيتك العرب\nقال أبو خليفة قال ابن سلام فأنشدني معاوية بن عمرو قال أنشدني عمارة بن عقيل لجرير يرثي الفرزدق بأبيات منها\n(فلا ولدت بعد الفرزدق حامل ... ولا ذات بعل من نفاس تعلت)\n(هو الوافد المأمون والراتق الثأى ... إذا النعل يوما بالعشيرة زلت)\nأخبرني أحمد بن عبد العزيز عن ابن شبة بخبر جرير لما بلغه وفاة الفرزدق وهو عند المهاجر فذكر نحوا مما ذكره ابن سلام وزاد فيه قال ثم قام وبكى وندم وقال ما تقارب رجلان في أمر قط فمات أحدهما إلا أوشك صاحبه أن يتبعه","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":36,"spl":"شعره عند موته — الاختلاف في سنة وفاته — جرير يرثي نفسه ويرثيه","tags":["الفرزدق","الحب والغزل"],"loc":1964},
{"id":"b112-77","bab":"الجزء 10","sec":"الاختلاف في سنة وفاته — جرير يرثي نفسه ويرثيه","page":"ج10 ص390 – ج10 ص391","text":"قال أبو زيد مات الحسن وابن سيرين والفرزدق وجرير في سنة عشر ومائة فقبر الفرزدق بالبصرة وقبر جرير وأيوب السختياني ومالك بن دينار باليمامة في موضع واحد وهذا غلط من أبي زيد عمر بن شبة لأن الفرزدق مات بعد يوم كاظمة وكان ذلك في سنة اثنتي عشرة ومائة وقد\nقال فيه الفرزدق شعرا وذكره في مواضع من قصائده ويقوي ذلك ما أخبرنا به وكيع قال حدثنا عمر بن محمد بن عبد الملك الزيات قال حدثني ابن النطاح عن المدائني عن أبي اليقظان وأبي همام المجاشعي أن الفرزدق مات سنة أربع عشرة ومائة قال أبو عبيدة\nحدثني أبو أيوب بن كسيب من آل الخطفي وأمه ابنة جرير بن عطية قال بينا جرير في مجلس بفناء داره بحجر إذ راكب قد أقبل فقال له جرير من أين وضح الراكب قال من البصرة فسأل عن الخبر فأخبره بموت الفرزدق فقال\n(مات الفرزدق بعد ما جرعته ... ليت الفرزدق كان عاش قليلا)\nم سكت ساعة فظنناه يقول شعرا فدمعت عيناه فقال القوم سبحان الله أتبكي على الفرزدق فقال والله ما أبكي إلا على نفسي أما والله إن بقائي خلافه لقليل إنه قل ما كان مثلنا رجلان يجتمعان على خير أو شر إلا كان أمد ما بينهما قريبا ثم أنشأ يقول\n(فجعنا بحمال الديات ابن غالب ... وحامي تميم كلها والبراجم)\n(بكيناك حدثان الفراق وإنما ... بكيناك شجوا للأمور العظائم)\n(فلا حملت بعد ابن ليلى مهيرة ... ولا شد أنساع المطي الرواسم)\nقال البلاذري حدثنا أبو عدنان عن أبي اليقظان قال أسن الفرزدق حتى قارب المائة فأصابته الدبيلة وهو بالبادية فقدم إلى البصرة فأتي برجل من بني قيس متطبب فأشار بأن يكوى ويشرب النفط\nالأبيض فقال أتعجلون لي طعام أهل النار في الدنيا وجعل يقول\n(أروني من يقوم لكم مقامي ... إذا ما الأمر جل عن الخطاب)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":36,"spl":"شعره عند موته — الاختلاف في سنة وفاته — جرير يرثي نفسه ويرثيه","tags":["الفرزدق","الحب والغزل","الموت"],"loc":1965},
{"id":"b112-78","bab":"الجزء 10","sec":"أبو ليلى المجاشعي يرثيه","page":"ج10 ص392","text":"وقال أبو ليلى المجاشعي يرثي الفرزدق\n(لعمري لقد أشجى تميما وهدها ... على نكبات الدهر موت الفرزدق)\n(عشية قدنا للفرزدق نعشه ... إلى جدث في هوة الأرض معمق)\n(لقد غيبوا في اللحد من كان ينتمي ... إلى كل بدر في السماء محلق)\n(ثوى حامل الاثقال عن كل مثقل ... ودفاع سلطان الغشوم السملق)\n(لسان تميم كلها وعمادها ... وناطقها المعروف عند المخنق)\n(فمن لتميم بعد موت ابن غالب ... إذا حل يوم مظلم غير مشرق)\n(لتبك النساء المعولات ابن غالب ... لجان وعان في السلاسل موثق)\nقال ابن زكريا الغلابي عن ابن عائشة قال مات الفرزدق وجرير في سنة عشرة ومائة ومات جرير بعده بستة أشهر ومات في هذه السنة الحسن البصري وابن سيرين قال فقالت امرأة من أهل البصرة كيف يفلح بلد مات فقيهاه وشاعراه في سنة ونسبت جريرا إلى البصرة لكثرة قدومه إليها من اليمامة وقبر جرير باليمامة وبها مات وقبر الأعشى أيضا باليمامة أعشى بني قيس بن ثعلبة وقبر الفرزدق بالبصرة في مقابر بني تميم\nوقال جرير لما بلغه موت الفرزدق قلما تصاول فحلان فمات أحدهما إلا أسرع لحاق الآخر به ورثاهما جماعة فمنهم أبو ليلى الأبيض من بني الأبيض بن مجاشع فقال فيهما\n(لعمري لئن قرما تميم تتابعا ... مجيبين للداعي الذي قد دعاهما)\n(لرب عدو فرق الدهر بينه ... وبينهما لم تشوه ضغمتاهما)\nخبرني ابن عمار عن يعقوب بن إسرائيل عن قعنب بن المحرز الباهلي عن الأصمعي عن جرير يعني أبا حازم قال رئي الفرزدق وجرير في النوم فرئي الفرزدق بخير وجرير معلق\nقال قعنب وأخبرني الأصمعي عن روح الطائي قال رئي الفرزدق في النوم فذكر انه غفر له بتكبيره كبرها في المقبرة عند قبر غالب قال قعنب وأخبرني أبو عبيدة النحوي وكيسان بن المعروف النحوي عن لبطة بن الفرزدق قال رأيت أبي فيما يرى النائم فقلت له ما فعل الله بك قال نفعتني الكلمة التي نازعنيها الحسن على القبر","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":37,"spl":"أبو ليلى المجاشعي يرثيه — هو والحسن البصري في جنازة النوار","tags":["الفرزدق","الجواري والنساء","الموت"],"loc":1966},
{"id":"b112-79","bab":"الجزء 10","sec":"هو والحسن البصري في جنازة النوار","page":"ج10 ص393","text":"أخبرني وكيع عن محمد بن إسماعيل الحساني عن علي بن عاصم عن سفيان بن الحسن وأخبرني أبو خليفة عن محمد بن سلام والرواية قريب\nبعضها من بعض أن النوار لما حضرها الموت أوصت الفرزدق وهو ابن عمها أن يصلي عليها الحسن البصري فأخبره الفرزدق فقال إذا فرغتم منها فأعلمني وأخرجت وجاءها الحسن وسبقهما الناس فانتظروهما فأقبلا والناس ينتظرون فقال الحسن ما للناس فقال ينتظرون خير الناس وشر الناس فقال إني لست بخيرههم ولست بشرهم\nوقال له الحسن على قبرها ما أعددت لهذا المضجع فقال شهادة أن لا إله إلا الله منذ سبعين سنة هذا لفظ محمد بن سلام وقال وكيع في خبره فتشاغل الفرزدق بدفنها وجلس الحسن يعظ الناس فما فرغ الفرزدق وقف على حلقة الحسن وقال\n(لقد خاب من أولاد آدم من مشى ... إلى النار مغلول القلادة أزرقا)\n(أخاف وراء القبر إن لم يعافني ... أشد من القبر التهابا وأضيقا)\n(إذا جاءني يوم القيامة قائد ... عنيف وسواق يقود الفرزدقا)\nخبرنا أحمد قال حدثنا عمر بن شبة قال حدثنا حيان بن هلال قال حدثنا خالد بن الحر قال رأيت الحسن في جنازة أبي رجاء العطاردي فقال للفرزدق ما أعددت لهذا اليوم فقال شهادة أن لا إله إلا الله منذ بضع وتسعين سنة قال إذا تنجو إن صدقت قال وقال الفرزدق في هذه الجنازة خير الناس وشر الناس فقال الحسن لست بخير الناس ولست بشرهم","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":37,"spl":"أبو ليلى المجاشعي يرثيه — هو والحسن البصري في جنازة النوار","tags":["الفرزدق","الموت","الرواية والكتابة"],"loc":1967},
{"id":"b112-81","bab":"الجزء 10","sec":"يذكر ذنوبه ويبكي — موازنة بينه وبين جرير والأخطل","page":"ج10 ص395 – ج10 ص396","text":"أخبرنا ابن عمار عن أحمد بن إسرائيل عن عبيد الله بن محمد القرشي بطوس قال حدثني يزيد بن هاشم العبدي قال حدثنا أبي قال حدثنا فضيل الرقاشي\nقال خرجت في ليلة باردة فدخلت المسجد فسمعت نشيجا وبكاء كثيرا فلم أعلم من صاحب ذلك إلى أن أسفر الصبح فإذا الفرزدق فقلت يا أبا فراس تركت النوار وهي لينة الدثار دفئة الشعار\nقال إني والله ذكرت ذنوبي فأقلقني ففزعت إلى الله عز و جل أخبرني وكيع عن أبي العباس مسعود بن عمرو بن مسعود الجحدري قال حدثني هلال بن يحيى الرازي\nقال حدثني شيخ كان ينزل سكة قريش قال رأيت الفرزدق في النوم فقلت يا أبا فراس ما فعل الله بك قال غفر لي بإخلاصي يوم الحسن وقال لولا شيبتك لعذبنك بالنار\nأخبرني هاشم الخزاعي عن دماذ عن أبي عبيدة عن لبطة بن الفرزدق عن أبيه قال لقيت الحسين بن علي صلوات الله عليهما وأصحابه بالصفاح وقد ركبوا الإبل وجنبوا الخيل متقلدين السيوف متنكبين القسي عليهم يلامق من الديباج فسلمت عليه وقلت أين تريد قال العراق فكيف\nتركت الناس قال تركت الناس قلوبهم معك وسيوفهم عليك والدنيا مطلوبة وهي في أيدي بني أمية والأمر إلى الله عز و جل والقضاء ينزل من السماء بما شاء\nأخبرني حبيب بن نصر المهلبي وأحمد بن عبد العزيز عن ابن شبة قال حدثني هارون بن عمر عن ضمرة بن شوذب قال قيل لأبي هريرة هذا الفرزدق قال هذا الذي يقذف المحصنات ثم\nقال له إني أرى عظمك رقيقا وعرقك دقيقا ولا طاقة لك بالنار فتب فإن التوبة مقبولة من ابن آدم حتى يطير غرابه أخبرني هاشم بن محمد عن الرياشي عن المنهال بن بحر بن أبي سلمة عن صالح المري عن حبيب بن أبي محمد قال رأيت الفرزدق بالشام فقال لي أبو هريرة إنه سيأتيك قوم يوئسونك من رحمة الله فلا تيأس\nقال أبو الفرج والفرزدق مقدم على الشعراء الإسلاميين هو وجرير والأخطل ومحله في الشعر أكبر من أن ينبه عليه بقول أو يدل على مكانه بوصف لأن الخاص والعام يعرفانه بالاسم ويعلمان تقدمه بالخبر الشائع علما يستغنى به عن الإطالة في الوصف وقد تكلم الناس في هذا قديما وحديثا وتعصبوا واحتجوا بما لا مزيد فيه واختلفوا بعد اجتماعهم على\nتقديم هذه الطبقة في أيهم أحق بالتقدم على سائرها فأما قدماء أهل العلم والرواة فلم يسووا بينهما وبين الأخطل لأنه لم يلحق شأوهما في الشعر ولا له مثل ما لهما من فنونه ولا تصرف كتصرفهما في سائره وزعموا أن ربيعة أفرطت فيه حتى ألحقته بهما وهم في ذلك طبقتان أما من كان يميل إلى جزالة الشعر وفخامته وشدة أسره فيقدم الفرزدق وأما من كان يميل إلى أشعار المطبوعين والى الكلام السمح السهل الغزل فيقدم جريرا أخبرنا أبو خليفة\nقال حدثنا محمد بن سلام قال سمعت يونس ين حبيب يقول ما شهدت مشهدا قط ذكر فيه الفرزدق وجرير فاجتمع أهل ذلك المجلس على أحدهما قال ابن سلام وكان يونس يقدم الفرزدق تقدمة بغير إفراط وكان المفضل يقدمه تقدمة شديدة\nقال ابن سلام وقال ابن دأب وسئل عنهما فقال الفرزدق أشعر خاصة وجرير أشعر عامة أخبرني الجوهري وحبيب المهلبي عن ابن شبة عن العلاء بن الفضل قال قال لي أبو البيداء يا أبا الهذيل أيهما أشعر أجرير أم الفرزدق قال قلت ذاك إليك ثم قال ألم تسمعه يقول\n(ما حملت ناقة من معشر رجلا ... مثلي إذا الريح لفتني على الكور)\n(إلا قريشا فإن الله فضلها ... مع النبوة بالإسلام والخير)\nيقول جرير\n(لا تحسبن مراس الحرب إذ لقحت ... شرب الكسيس وأكل الخبز بالصير)\nسلح والله أبو حرزة أخبرني هاشم الخزاعي عن أبي حاتم السجستاني عن أبي عبيدة قال سمعت يونس يقول لولا شعر الفرزدق لذهب ثلث لغة العرب أخبرني هاشم الخزاعي عن أبي غسان عن أبي عبيدة قال قال يونس أبو البيداء قال الفرزدق كنت أهاجي شعراء قومي وأنا غلام في خلافة عثمان بن عفان فكان قومي يخشون معرة لساني منذ يومئذ ووفد بي أبي إلى علي بن أبي طالب صلوات الله عليه عام الجمل فقال له إن ابني هذا يقول الشعر فقال علمه القرآن فهو خير له","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":38,"spl":"يذكر ذنوبه ويبكي — موازنة بينه وبين جرير والأخطل","tags":["الفرزدق"],"loc":1968},
{"id":"b112-82","bab":"الجزء 10","sec":"يمضي خمسا وسبعين سنة يباري الشعراء ويهجو الأشراف","page":"ج10 ص398","text":"قال أبو عبيدة ومات الفرزدق في سنة عشر ومائة وقد نيف على التسعين سنة كان منها خمسة وسبعين سنة يباري الشعراء ويهجو الأشراف فيغضهم ما ثبت له أحد منهم قط إلا جريرا\nأخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني محمد بن معاوية الأسدي قال حدثنا ابن الرازي عن خالد بن كلثوم قال\nقيل للفرزدق مالك وللشعر فو الله ما كان أبوك غالب شاعرا ولا كان صعصعة شاعرا فمن أين لك هذا قال من قبل خالي قيل أي أخوالك قال خالي العلاء بن قرظة الذي يقول\n(إذا ما الدهر جر على أناس ... بكلكله أناخ بآخرينا)\n(فقل للشامتين بنا أفيقوا ... سيلقى الشامتون كما لقينا)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":39,"spl":"يمضي خمسا وسبعين سنة يباري الشعراء ويهجو الأشراف — بنو حرام يخشون معرة لسانه","tags":["الفرزدق"],"loc":1969},
{"id":"b112-83","bab":"الجزء 10","sec":"يرد على قوم من بني ضبة","page":"ج10 ص399","text":"أخبرني عمي قال حدثنا الكراني عن العمري عن الهيثم بن عدي عن حماد الراوية وأخبرني هاشم الخزاعي قال حدثنا دماذ عن أبي عبيدة قال دخل قوم من بني ضبة على الفرزدق فقالوا له قبحك الله من ابن أخت قد عرضتنا لهذا الكلب السفيه يعنون جريرا حتى يشتم أعراضنا ويذكر نساءنا فغضب الفرزدق وقال بل قبحكم الله من أخوال فو الله لقد شرفكم من فخري أكثر مما غضكم من هجاء جرير أفأنا ويلكم عرضتكم لسويد بن أبي كاهل حيث يقول\n(لقد زرقت عيناك يا بن مكعبر ... كما كل ضبي من اللؤم أزرق)\n(ترى اللؤم فيهم لائحا في وجوههم ... كما لاح في خيل الحلائب أبلق)\nو أنا عرضتكم للأغلب العجلي حيث يقول\n(لن تجد الضبي إلا فلا ... عبدا إذانا ولقوم ذلا)\n(مثل قفا المدية أو أكلا ... حتى يكون الألأم الأقلا)\nو أنا عرضتكم له حيث يقول\n(إذا رأيت رجلا من ضبه ... فنكه عمدا في سواء السبه)\n(إن اليماني عقاص الزبه ... )\nو أنا عرضتكم لمالك بن نويرة حيث يقول\n(ولو يذبح الضبي بالسيف لم تجد ... من اللؤم للضبي لحما ولا دما)\nالله لما ذكرت من شرفكم وأظهرت من أيامكم أكثر ألست القائل\n(وأنا ابن حنظلة الأغر وإنني ... في آل ضبة للمعم المخول)\n(فرعان قد بلغ السماء ذراهما ... وإليهما من كل خوف يعقل)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":39,"spl":"يمضي خمسا وسبعين سنة يباري الشعراء ويهجو الأشراف — بنو حرام يخشون معرة لسانه","tags":["الفرزدق","الهجاء","الرواية والكتابة"],"loc":1970,"partial":1},
{"id":"b112-84","bab":"الجزء 10","sec":"بنو حرام يخشون معرة لسانه","page":"ج10 ص400","text":"أخبرنا أبو خليفة عن ابن سلام عن أبي بكر محمد بن واسع وعبد القاهر قالا كان فتى في بني حرام بن سماك شويعر قد هجا الفرزدق فأخذناه فأتينا به الفرزدق وقلنا هو بين يديك فإن شئت فاضرب وإن شئت فاحلق لا عدوى عليك ولا قصاص فخلى عنه وقال\n(فمن يك خائفا لأذاة قولي ... فقد أمن الهجاء بنو حرام)\n(هم قادوا سفيههم وخافوا ... قلائد مثل أطواق الحمام)\nخبرنا أبو خليفة عن محمد بن سلام قال حدثني الحكم بن محمد قال كان رجل من قضاعة ثم من بني القين على السند وفي حبسه رجل يقال له حبيش أو خنيس وطالت غيبته عن أهله فأتت أمه قبر غالب بكاظمة فأقامت عليه حتى علم الفرزدق بمكانها ثم إنها أتت فطلبت إليه في أمر ابنها فكتب إلى تميم القضاعي\n(هب لي خنيسا واتخذ فيه منة ... لغصة أم ما يسوغ شرابها)\n(أتتني فعاذت يا تميم بغالب ... وبالحفرة السافي عليه ترابها)\n(تميم بن زيد لا تكونن حاجتي ... بظهر فلا يخفى علي جوابها)\nفلما أتاه الكتاب لم يدر أخنيس أم حبيش فأطلقهما جميعا أخبرني أبو خليفة قال حدثنا محمد بن سلام قال حدثني أبو يحيى الضبي قال ضرب مكاتب لبني منقر خيما على قبر غالب فقدم الناس على الفرزدق فأخبروه أنهم رأوا بناء على قبر غالب أبيه ثم قدم عليه وهو بالمربد فقال\n(بقبر ابن ليلى غالب عذت بعدما ... خشيت الردى أو أن أرد على قسر)\n(فخاطبني قبر ابن ليلى وقال لي ... فكاكك أن تلقى الفرزدق بالمصر)\nقال له الفرزدق صدق أبي أنخ أنخ ثم طاف في الناس حتى جمع كتابته وفضلا","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":39,"spl":"يمضي خمسا وسبعين سنة يباري الشعراء ويهجو الأشراف — بنو حرام يخشون معرة لسانه","tags":["الفرزدق","الهجاء","الخمر"],"loc":1971},
{"id":"b112-85","bab":"الجزء 10","sec":"يناقض نفسه في شعره","page":"ج10 ص402","text":"أخبرني ابن خلف وكيع عن هارون بن الزيات عن أحمد بن حماد ابن الجميل قال حدثنا القحذمي عن ابن عياش قال لقيت الفرزدق فقلت له يا فراس أنت الذي تقول\n(فليت الأكف الدافنات ابن يوسف ... يقطعن إذ غيبن تحت السقائف)\nقال نعم أنا فقلت له ثم قلت بعد ذلك له\n(لئن نفر الحجاح آل معتب ... لقوا دولة كان العدو يدالها)\n(لقد أصبح الأحياء منهم أذلة ... وفي الناس موتاهم كلوحا سبالها)\nال فقال الفرزدق نعم نكون مع الواحد منهم ما كان الله معه فإذا تخلى منه انقلبنا عليه أخبرنا هاشم بن محمد عن عبد الرحمن ابن أخي الأصمعي عن عمه عن بعض أشياخه\nقال شهد الفرزدق عند إياس بن معاوية فقال أجزنا شهادة الفرزدق أبي فراس وزيدونا شهودا فقام الفرزدق فرحا فقيل له أما والله ما أجاز شهادتك\nقال بلى قد سمعته يقول قد قبلنا شهادة أبي فراس قالوا أفما سمعته يستزيد شاهدا آخر فقال وما يمنعه ألا يقبل شهادتي وقد قذفت ألف محصنة أخبرنا ابن دريد عن أبي حاتم عن أبي عبيدة عن يونس قال كان عطية بن جعال الغذاني صديقا ونديما للفرزدق فبلغ الفرزدق أن\nرجلا من بني غدانة هجاه وعاون جريرا عليه وأنه أراد أن يهجو بني غدانة فأتاه عطية بن جعال فسأله أن يصفح له عن قومه ويهب له أعراضهم ففعل ثم قال\n(أبني غدانة إنني حررتكم ... فوهبتكم لعطية بن جعال)\n(لولا عطية لاجتدعت أنوفكم ... من بين ألأم أعين وسبال)\nبلغ ذلك عطية فقال ما أسرع ما ارتجع أخي هبته قبحها الله من هبة ممنوعة مرتجعة","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":40,"spl":"يناقض نفسه في شعره","tags":["الفرزدق","الهجاء"],"loc":1972},
{"id":"b112-87","bab":"الجزء 10","sec":"خبر آخر عن المجنون الذي أراده — عمر بن عبد العزيز يجيزه ثم ينفيه","page":"ج10 ص403 – ج10 ص404","text":"أخبرني وكيع عن هارون بن محمد قال حدثني قبيصة بن معاوية المهلبي عن المدائني عن محمد بن النضر أن الفرزدق مر بباب المفضل بن المهلب فأرسل إليه غلمة فاحتملوه حتى أدخل إليه بواسط وقد خرج من تيار ماء كان فيه فأمر به فألقي فيه بثيابه وعنده ابن أبي علقمة اليحمدي المجنون فسعى إلى الفرزدق فقال له المفضل ما تريد\nقال أريد أن أنيكه وأفضحه فو الله لا يهجو بعدها أحدا من الأزد فصاح الفرزدق الله الله أيها الأمير في أنا جوارك وذمتك فمنع عنه ابن أبي علقمة فلما خرج\nقال قاتل الله مجنونهم والله لو مس ثوبه لقام بها جرير وقعد وفضحني في العرب فلم يبق لي فيهم باقية وأخبرني بنحو هذا الخبر حبيب المهلبي عن ابن شبة عن محمد بن يحيى عن عبد الحميد عن أبيه عن جده قال أبو زيد وأخبرني أبو\nحذف 404\nعاصم عن الحسن بن دينار قال قال لي الفرزدق ما مر بي يوم قط أشد علي من يوم دخلت فيه على أبي عيينة بن المهلب وكان يوما شديد الحر فما منا أحد إلا جلس في أبزن فقلنا له إن أردت أن تنفعنا فابعث إلى ابن أبي علقمة فقال لا تريدوه فإنه يكدر علينا مجلسنا فقلنا لا بد منه فأرسل إليه فلما دخل فرآني\nقال الفرزدق والله ووثب إلي وقد أنعظ أيره وجعل يصيح والله لأنيكنه فقلت لأبي عيينة الله الله في أنا في جوارك فو الله لئن دنا إلي لا تبقى لي باقية مع جرير فلم يتكلم أبو عيينة ولم تكن لي همة إلا أن عدوت حتى صعدت إلى السطح فاقتحمت الحائط فقيل له ولا يوم زياد كان مثل يومئذ فقال ولا مثل يوم زياد\nأخبرني عمي عن ابن أبي سعد عن أحمد بن عمر عن إسحاق بن مروان مولى جهينة وكان يقال له كوزا الراوية قال احمد بن عمر وأخبرني عثمان بن خالد العثماني أن الفرزدق قدم المدينة في سنة مجدبة حصاء فمشى أهل المدينة إلى عمر بن عبد العزيز فقالوا له أيها الأمير إن الفرزدق قدم مدينتنا هذه في هذه السنة الجدبة التي أهلكت عامة الأموال التي لأهل المدينة وليس عند أحد منهم ما يعطيه شاعرا فلو أن الأمير بعث إليه فأرضاه وتقدم إليه ألا يعرض لأحد بمدح ولا هجاء فبعث إليه عمر إنك يا فرزدق قدمت مدينتنا هذه في هذه السنة الجدبة وليس عند أحد ما يعطيه شاعرا وقد\nأمرت لك بأربعة آلاف درهم فخذها ولا تعرض لأحد بمدح ولا هجاء فأخذها الفرزدق ومر بعبد الله بن عمرو بن عثمان وهو جالس في سقيفة داره وعليه مطرفا خز أحمر وجبة خز أحمر فوقف عليه وقال\n(أعبد الله أنت أحق ماش ... وساع بالجماهير الكبار)\n(نما الفاروق أمك وابن أروى ... أبوك فأنت منصدع النهار)\n(هما قمرا السماء وأنت نجم ... به في الليل يدلج كل سار)\nخلع عليه الجبة والعمامة والمطرف وأمر له بعشرة آلاف درهم فخرج رجل كان حضر عبد الله والفرزدق عنده ورأى ما أعطاه إياه وسمع ما أمره عمر به من ألا يعرض لأحد فدخل إلى عمر بن عبد العزيز فأخبره فبعث إليه عمر ألم أتقدم إليك يا فرزدق ألا تعرض لأحد بمدح ولا هجاء أخرج فقد أجلتك ثلاثا فإن وجدتك بعد ثلاث نكلت بك فخرج وهو يقول\n(فأجلني وواعدني ثلاثا ... كما وعدت لمهلكها ثمود)\nال وقال جرير فيه\n(نفاك الأغر ابن عبد العزيز ... ومثلك ينفى من المسجد)\n(وشبهت نفسك أشقى ثمود ... فقالوا ضللت ولم تهتد)","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":41,"spl":"خبر آخر عن المجنون الذي أراده — عمر بن عبد العزيز يجيزه ثم ينفيه","tags":["الفرزدق","الهجاء","المديح"],"loc":1973},
{"id":"b112-88","bab":"الجزء 10","sec":"يهجو ابن عفراء لأنه استكثر عليه الجائزة","page":"ج10 ص405","text":"أخبرني حبيب المهلبي عن ابن أبي سعد عن صباح عن النوفلي بن خاقان عن يونس النحوي قال\nمدح الفرزدق عمر بن مسلم الباهلي فأمر له بثلثمائة درهم وكان عمرو بن عفراء الضبي صديقا لعمر فلامه وقال أتعطي الفرزدق ثلثمائة درهم وإنما كان يكفيه عشرون درهما فبلغه ذلك فقال\n(نهيت ابن عفرى أن يعفر أمه ... كعفر السلا إذ جررته ثعالبه)\n(وإن امرأ يغتابني لم أطأ له ... حريما فلا ينهاه عني أقاربه)\n(كمحتطب يوما أساود هضبة ... أتاه بها في ظلمة الليل حاطبه)\n(ألما استوى ناباي وأبيض مسحلي ... وأطرق إطراق الكرى من أحاربه)\n(فلو كان ضبيا صفحت ولو سرت ... على قدمي حياته وعقاربه)\n(ولكن ديافي أبوه وأمه ... بحوران يعصرن السليط قرائبه)\n\n(ومقالها بالنعف نعف محسر ... لفتاتها هل تعرفين المعرضا)\n(ذاك الذي أعطى مواثق عهده ... ألا يخون وخلت أن لن ينقضا)\n(فلئن ظفرت بمثلها من مثله ... يوما ليعترفن ما قد أقرضا)\nلشعر لخالد القسري والناس ينسبونه إلى عمر بن أبي ربيعة والغناء للغريض ثقيل أول بالوسطى عن الهشامي وابن المكي وحبش وقبل أن أذكر أخباره ونسبه فإني أذكر الرواية في أن هذا الشعر له أخبرنا محمد بن خلف وكيع قال أخبرني عبد الواحد بن سعيد قال حدثني أبو بشر محمد بن خالد البجلي قال حدثني أبو الخطاب بن يزيد بن عبد الرحمن قال سمعت أبي يحدث قال حدثني مسمع بن مالك بن جحوش البجلي قال\nركب خالد بن عبد الله وهو أمير العراق وهو يومئذ بالكوفة إلى ضيعته التي يقال لها المكرخة وهي من الكوفة على أربعة فراسخ وركبت معه في زورق فقال لي نشدتك الله يا بن جحوش هل سمعت غريض مكة يتغنى\n(ومقالها بالنعف نعف محسر ... لفتاتها هل تعرفين المعرضا)\nال قلت نعم قال الشعر والله لي والغناء لغريض مكة وما وجدت هذا الشعر في شيء من دواوين عمر بن أبي ربيعة التي رواها المدنيون والمكيون وإنما يوجد في الكتب المحدثة والإسنادات المنقطعة ثم نرجع الآن إلى ذكره","topic":"نسب الفرزدق وأخباره وذكر مناقضاته","topicNo":112,"sp":42,"spl":"يهجو ابن عفراء لأنه استكثر عليه الجائزة","tags":["الفرزدق"],"song":1,"loc":1974}]);